export function escapeRegExp(value) {
  // TODO [engine:node@>=24]: Replace with built in RegExp.escape()
  return value
    .replaceAll(/[|\\{}()[\]^$+*?.]/g, "\\$&")
    .replaceAll("-", "\\x2d");
}

