}

function escapeXml(value) {
  return escape(
    stripInvalidXmlCharacters(String(value).replace(ANSI_ESCAPE_SEQUENCE, "")),
  );
}

function stripInvalidXmlCharacters(value) {
  var result = "";

  for (var i = 0; i < value.length; i += 1) {
    var charCode = value.charCodeAt(i);
