      charCode === 0x09 ||
      charCode === 0x0a ||
      charCode === 0x0d ||
      charCode >= 0x20
    ) {
      result += value[i];
    }
  }

  return result;
}

function testFilePath(filepath, options) {
  if (
    options &&
    options.reporterOptions &&
    options.reporterOptions.showRelativePaths
  ) {
    return path.relative(process.cwd(), filepath);
  }

