import path from 'node:path';

const toPath = urlOrPath => urlOrPath instanceof URL ? fileURLToPath(urlOrPath) : urlOrPath;

export async function findUp(name, {
	cwd = process.cwd(),
	type = 'file',
	stopAt,
} = {}) {
	let directory = path.resolve(toPath(cwd) ?? '');
	const {root} = path.parse(directory);
	stopAt = path.resolve(directory, toPath(stopAt ?? root));
	const isAbsoluteName = path.isAbsolute(name);

	while (directory) {
		const filePath = isAbsoluteName ? name : path.join(directory, name);
		try {
			const stats = await fsPromises.stat(filePath); // eslint-disable-line no-await-in-loop
			if ((type === 'file' && stats.isFile()) || (type === 'directory' && stats.isDirectory())) {
				return filePath;
			}
		} catch {}

		if (directory === stopAt || directory === root) {
			break;
		}

		directory = path.dirname(directory);
	}
}

export function findUpSync(name, {
	cwd = process.cwd(),
	type = 'file',
	stopAt,
} = {}) {
	let directory = path.resolve(toPath(cwd) ?? '');
	const {root} = path.parse(directory);
	stopAt = path.resolve(directory, toPath(stopAt) ?? root);
	const isAbsoluteName = path.isAbsolute(name);

	while (directory) {
		const filePath = isAbsoluteName ? name : path.join(directory, name);

		try {
			const stats = fs.statSync(filePath, {throwIfNoEntry: false});
			if ((type === 'file' && stats?.isFile()) || (type === 'directory' && stats?.isDirectory())) {
				return filePath;
			}
		} catch {}

		if (directory === stopAt || directory === root) {
			break;
		}

		directory = path.dirname(directory);
	}
}

"use strict";
import fs from "node:fs";
import path from "node:path";

import referee from "@sinonjs/referee";
import bag from "bagofcli";
import sinon from "sinon";

import cli from "../lib/cli.js";
import { LOG_LEVELS, Logs } from "../lib/logging/logger.js";
import { readLogRecords } from "./helpers/log-records.js";
import { ROOT, SDK_726, SPEC, tmpDir } from "./helpers/paths.js";

const { assert, refute } = referee;

describe("cli - exec", function () {
  afterEach(function () {
    sinon.restore();
  });

  it("should contain only the serve command with an action", function (done) {
    sinon.stub(bag, "command").value(function (
      base: string,
      actions: { commands: Record<string, { action: unknown }> },
    ) {
      assert.isString(base);
      assert.equals(Object.keys(actions.commands), ["serve"]);
      assert.isFunction(actions.commands.serve.action);
      done();
    });
    cli.exec();
  });

  it("should define every command in conf/commands.json", function () {
    const commands = JSON.parse(
      fs.readFileSync(path.join(ROOT, "conf", "commands.json"), "utf8"),
    );
    assert.equals(Object.keys(commands.commands), ["serve"]);
    const serveOpts = commands.commands.serve.options.map(
      (o: { arg: string }) => o.arg.split(" ")[0],
    );
    assert.isUndefined(commands.commands.serve.args);
    for (const flag of ["--spec", "--sdk"]) {
      const opt = commands.commands.serve.options.find((o: { arg: string }) =>
        o.arg.startsWith(`${flag} `),
      );
      assert.equals(opt.rules, ["required"], flag);
    }
    for (const flag of [
      "--spec",
      "--sdk",
      "--sdk-layout",
      "--transport",
      "--port",
      "--config",
    ]) {
      assert.contains(serveOpts, flag);
    }
    for (const ex of commands.commands.serve.examples) {
      assert.match(ex, /^oag-mcp serve --spec \S+ --sdk \S+/);
    }
  });

  it("should declare argument validation for bagofcli in conf/commands.json", function () {
    const commands = JSON.parse(
      fs.readFileSync(path.join(ROOT, "conf", "commands.json"), "utf8"),
    );
    type Opt = { arg: string; [k: string]: unknown };
    const find = (opts: Opt[], flag: string) =>
      opts.find((o) => o.arg.startsWith(`${flag} `))!;
    const serve = commands.commands.serve;
    assert.isFalse(serve.allowExcessArguments);
    assert.equals(find(serve.options, "--sdk-layout").choices, [
      "auto",
      "source",
      "compiled",
    ]);
    assert.equals(find(serve.options, "--transport").choices, [
      "stdio",
      "streamable-http",
    ]);
    const port = find(serve.options, "--port");
    assert.equals([port.integer, port.min, port.max], [true, 0, 65535]);
    // The allowed log levels must stay in step with the logger.
    assert.equals(find(commands.options, "--log-level").choices, [
      ...LOG_LEVELS,
    ]);
    assert.equals(find(commands.options, "--log-format").choices, [
      "json",
      "pretty",
    ]);
  });
});

describe("cli - documentation", function () {
  it("should document only serve invocations that pass --spec and --sdk", function () {
    const files = [
      "README.md",
      ...fs
        .readdirSync(path.join(ROOT, "docs"), { recursive: true })
        .map(String)
        .filter((f) => f.endsWith(".md"))
        .map((f) => `docs/${f}`),
      ...fs
        .readdirSync(path.join(ROOT, "examples"))
        .map((f) => `examples/${f}`),
    ];
    let invocations = 0;
    for (const rel of files) {
      const text = fs
        .readFileSync(path.join(ROOT, rel), "utf8")
        .replace(/\\\n\s*/g, " ");
      // Every documented invocation with options must name both inputs.
      for (const m of text.matchAll(/oag-mcp serve (?!--help)--[^\n`|]*/g)) {
        assert.match(m[0], /--spec\b/, `${rel}: ${m[0]}`);
        assert.match(m[0], /--sdk\b/, `${rel}: ${m[0]}`);
        invocations++;
      }
    }
    assert(invocations >= 10, `only ${invocations} invocations found`);
    const readme = fs.readFileSync(path.join(ROOT, "README.md"), "utf8");
    assert.contains(
      readme,
      "oag-mcp serve --spec ./openapi.yaml --sdk ./generated-sdk --transport stdio",
    );
  });
});

/**
 * The serve action, run against the process as faked here: process.exit
 * is recorded, signal and stdin handlers are captured, stderr is captured.
 */
function harness() {
  const exits: number[] = [];
  const stderr: string[] = [];
  const signals: Record<string, () => void> = {};
  let stdinEnd: (() => void) | undefined;
  let action: ((args: Record<string, unknown>) => void) | undefined;
  sinon.stub(bag, "command").value(function (
    _base: string,
    actions: { commands: { serve: { action: typeof action } } },
  ) {
    action = actions.commands.serve.action;
  });
  cli.exec();
  sinon.stub(process, "exit").callsFake(((code: number) => {
    exits.push(code);
  }) as never);
  const on = process.on.bind(process);
  sinon.stub(process, "on").callsFake(((event: string, fn: () => void) => {
    if (event === "SIGINT" || event === "SIGTERM") {
      signals[event] = fn;
      return process;
    }
    return on(event, fn);
  }) as never);
  sinon.stub(process.stdin, "once").callsFake(((
    event: string,
    fn: () => void,
  ) => {
    if (event === "end") {
      stdinEnd = fn;
    }
    return process.stdin;
  }) as never);
  sinon.stub(process.stderr, "write").callsFake(((chunk: string) => {
    stderr.push(String(chunk));
    return true;
  }) as never);
  const dir = tmpDir();
  const config = path.join(dir, "oag-mcp.yaml");
  fs.writeFileSync(
    config,
    [
      "upstream:",
      "  baseUrl: http://127.0.0.1:9/v1",
      "execution:",
      "  typecheck: false",
      "logging:",
      `  file: ${path.join(dir, "config.log")}`,
      "  level: debug",
    ].join("\n"),
  );
  const logFile = path.join(dir, "cli.log");
  return {
    exits,
    stderr,
    signals,
    stdinEnd: () => stdinEnd,
    records: () => readLogRecords(logFile),
    run(args: Record<string, unknown> = {}) {
      action!({
        spec: SPEC,
        sdk: SDK_726,
        config,
        logFile,
        auditLogFile: logFile,
        ...args,
      });
    },
  };
}

async function until(cond: () => unknown, ms = 30000): Promise<void> {
  const end = Date.now() + ms;
  while (!cond()) {
    if (Date.now() > end) {
      throw new Error("timed out waiting");
    }
    await new Promise((r) => setTimeout(r, 20));
  }
}

describe("cli - serve", function () {
  this.timeout(60000);

  afterEach(function () {
    sinon.restore();
  });

  it("should serve over HTTP with flag overrides, then stop cleanly on a signal", async function () {
    const h = harness();
    h.run({
      transport: "streamable-http",
      host: "127.0.0.1",
      port: "0",
      path: "/mcp-test",
      logLevel: "info",
      logFormat: "json",
    });
    await until(() => h.stderr.join("").includes("listening on"));
    const url = /listening on (\S+)/.exec(h.stderr.join(""))![1];
    assert.match(url, /^http:\/\/127\.0\.0\.1:\d+\/mcp-test$/);
    const health = await fetch(new URL("/healthz", url));
    assert.equals(health.status, 200);
    h.signals.SIGTERM();
    await until(() => h.exits.length > 0);
    assert.equals(h.exits, [0]);
    // A second signal while stopping is ignored.
    h.signals.SIGINT();
    assert.equals(h.exits, [0]);
    const events = h.records().map((r) => r.event);
    assert.contains(events, "cli.command.started");
    assert.contains(events, "server.shutdown_requested");
    assert.contains(events, "cli.command.completed");
    refute.contains(
      events,
      "prepare.stage.started",
      "debug from the config is overridden",
    );
  });

  it("should stop when the MCP client closes stdin", async function () {
    const h = harness();
    h.run({ transport: "stdio" });
    await until(() => h.stdinEnd());
    h.stdinEnd()!();
    await until(() => h.exits.length > 0);
    assert.equals(h.exits, [0]);
    assert.equals(
      h
        .records()
        .find((r) => r.event === "server.shutdown_requested")!
        .get("signal"),
      "stdin_closed",
    );
  });

  it("should cancel start-up on a signal, and exit at once on a second", async function () {
    const h = harness();
    h.run({ transport: "streamable-http", port: "0" });
    h.signals.SIGINT();
    h.signals.SIGINT();
    assert.equals(h.exits, [1], "second signal exits immediately");
    await until(() => h.exits.length > 1);
    assert.equals(h.exits, [1, 1]);
    assert.match(h.stderr.join(""), /Error \[STARTUP_ABORTED\]/);
    const failed = h.records().find((r) => r.event === "cli.command.failed")!;
    assert.equals(failed.get("errorCode"), "STARTUP_ABORTED");
  });

  it("should close a server whose start-up was cancelled while its transport started", async function () {
    const h = harness();
    const op = Logs.prototype.op;
    sinon.stub(Logs.prototype, "op").callsFake(function (
      this: Logs,
      ...args: Parameters<Logs["op"]>
    ) {
      op.apply(this, args);
      if (args[1] === "transport.initialized") {
        h.signals.SIGTERM();
      }
    });
    h.run({ transport: "streamable-http", port: "0" });
    await until(() => h.exits.length > 0);
    // Exits 1 after closing the server (the fake exit returns, so any
    // output after it here is not what a real exit would print).
    assert.equals(h.exits[0], 1);
    assert.contains(
      h.records().map((r) => r.event),
      "server.stopped",
    );
  });

  it("should report a configuration that cannot be read, before logging starts", async function () {
    const h = harness();
    h.run({ config: path.join(tmpDir(), "missing.yaml") });
    await until(() => h.exits.length > 0);
    assert.equals(h.exits, [1]);
    assert.match(h.stderr.join(""), /^Error \[CONFIG_NOT_FOUND\]/);
  });
});

// Note: since nyc uses this module to output coverage, any lines
// that are in the direct sync flow of nyc's outputCoverage are
// ignored, since we can never get coverage for them.
// grab a reference to node's real process object right away
import { signals } from './signals.js'
export { signals }

// just a loosened process type so we can do some evil things
type ProcessRE = NodeJS.Process & {
  reallyExit: (code?: number | undefined | null) => any
  emit: (ev: string, ...a: any[]) => any
}

const processOk = (process: any): process is ProcessRE =>
  !!process &&
  typeof process === 'object' &&
  typeof process.removeListener === 'function' &&
  typeof process.emit === 'function' &&
  typeof process.reallyExit === 'function' &&
  typeof process.listeners === 'function' &&
  typeof process.kill === 'function' &&
  typeof process.pid === 'number' &&
  typeof process.on === 'function'

const kExitEmitter = Symbol.for('signal-exit emitter')
const global: typeof globalThis & { [kExitEmitter]?: Emitter } = globalThis
const ObjectDefineProperty = Object.defineProperty.bind(Object)

/**
 * A function that takes an exit code and signal as arguments
 *
 * In the case of signal exits *only*, a return value of true
 * will indicate that the signal is being handled, and we should
 * not synthetically exit with the signal we received. Regardless
 * of the handler return value, the handler is unloaded when an
 * otherwise fatal signal is received, so you get exactly 1 shot
 * at it, unless you add another onExit handler at that point.
 *
 * In the case of numeric code exits, we may already have committed
 * to exiting the process, for example via a fatal exception or
 * unhandled promise rejection, so it is impossible to stop safely.
 */
export type Handler = (
  code: number | null | undefined,
  signal: NodeJS.Signals | null
) => true | void
type ExitEvent = 'afterExit' | 'exit'
type Emitted = { [k in ExitEvent]: boolean }
type Listeners = { [k in ExitEvent]: Handler[] }

// teeny special purpose ee
class Emitter {
  emitted: Emitted = {
    afterExit: false,
    exit: false,
  }

  listeners: Listeners = {
    afterExit: [],
    exit: [],
  }

  count: number = 0
  id: number = Math.random()

  constructor() {
    if (global[kExitEmitter]) {
      return global[kExitEmitter]
    }
    ObjectDefineProperty(global, kExitEmitter, {
      value: this,
      writable: false,
      enumerable: false,
      configurable: false,
    })
  }

  on(ev: ExitEvent, fn: Handler) {
    this.listeners[ev].push(fn)
  }

  removeListener(ev: ExitEvent, fn: Handler) {
    const list = this.listeners[ev]
    const i = list.indexOf(fn)
    /* c8 ignore start */
    if (i === -1) {
      return
    }
    /* c8 ignore stop */
    if (i === 0 && list.length === 1) {
      list.length = 0
    } else {
      list.splice(i, 1)
    }
  }

  emit(
    ev: ExitEvent,
    code: number | null | undefined,
    signal: NodeJS.Signals | null
  ): boolean {
    if (this.emitted[ev]) {
      return false
    }
    this.emitted[ev] = true
    let ret: boolean = false
    for (const fn of this.listeners[ev]) {
      ret = fn(code, signal) === true || ret
    }
    if (ev === 'exit') {
      ret = this.emit('afterExit', code, signal) || ret
    }
    return ret
  }
}

abstract class SignalExitBase {
  abstract onExit(cb: Handler, opts?: { alwaysLast?: boolean }): () => void
  abstract load(): void
  abstract unload(): void
}

const signalExitWrap = <T extends SignalExitBase>(handler: T) => {
  return {
    onExit(cb: Handler, opts?: { alwaysLast?: boolean }) {
      return handler.onExit(cb, opts)
    },
    load() {
      return handler.load()
    },
    unload() {
      return handler.unload()
    },
  }
}

class SignalExitFallback extends SignalExitBase {
  onExit() {
    return () => {}
  }
  load() {}
  unload() {}
}

class SignalExit extends SignalExitBase {
  // "SIGHUP" throws an `ENOSYS` error on Windows,
  // so use a supported signal instead
  /* c8 ignore start */
  #hupSig = process.platform === 'win32' ? 'SIGINT' : 'SIGHUP'
  /* c8 ignore stop */
  #emitter = new Emitter()
  #process: ProcessRE
  #originalProcessEmit: ProcessRE['emit']
  #originalProcessReallyExit: ProcessRE['reallyExit']

  #sigListeners: { [k in NodeJS.Signals]?: () => void } = {}
  #loaded: boolean = false

  constructor(process: ProcessRE) {
    super()
    this.#process = process
    // { <signal>: <listener fn>, ... }
    this.#sigListeners = {}
    for (const sig of signals) {
      this.#sigListeners[sig] = () => {
        // If there are no other listeners, an exit is coming!
        // Simplest way: remove us and then re-send the signal.
        // We know that this will kill the process, so we can
        // safely emit now.
        const listeners = this.#process.listeners(sig)
        let { count } = this.#emitter
        // This is a workaround for the fact that signal-exit v3 and signal
        // exit v4 are not aware of each other, and each will attempt to let
        // the other handle it, so neither of them do. To correct this, we
        // detect if we're the only handler *except* for previous versions
        // of signal-exit, and increment by the count of listeners it has
        // created.
        /* c8 ignore start */
        const p = process as unknown as {
          __signal_exit_emitter__?: { count: number }
        }
        if (
          typeof p.__signal_exit_emitter__ === 'object' &&
          typeof p.__signal_exit_emitter__.count === 'number'
        ) {
          count += p.__signal_exit_emitter__.count
        }
        /* c8 ignore stop */
        if (listeners.length === count) {
          this.unload()
          const ret = this.#emitter.emit('exit', null, sig)
          /* c8 ignore start */
          const s = sig === 'SIGHUP' ? this.#hupSig : sig
          if (!ret) process.kill(process.pid, s)
          /* c8 ignore stop */
        }
      }
    }

    this.#originalProcessReallyExit = process.reallyExit
    this.#originalProcessEmit = process.emit
  }

  onExit(cb: Handler, opts?: { alwaysLast?: boolean }) {
    /* c8 ignore start */
    if (!processOk(this.#process)) {
      return () => {}
    }
    /* c8 ignore stop */

    if (this.#loaded === false) {
      this.load()
    }

    const ev = opts?.alwaysLast ? 'afterExit' : 'exit'
    this.#emitter.on(ev, cb)
    return () => {
      this.#emitter.removeListener(ev, cb)
      if (
        this.#emitter.listeners['exit'].length === 0 &&
        this.#emitter.listeners['afterExit'].length === 0
      ) {
        this.unload()
      }
    }
  }

  load() {
    if (this.#loaded) {
      return
    }
    this.#loaded = true

    // This is the number of onSignalExit's that are in play.
    // It's important so that we can count the correct number of
    // listeners on signals, and don't wait for the other one to
    // handle it instead of us.
    this.#emitter.count += 1

    for (const sig of signals) {
      try {
        const fn = this.#sigListeners[sig]
        if (fn) this.#process.on(sig, fn)
      } catch (_) {}
    }

    this.#process.emit = (ev: string, ...a: any[]) => {
      return this.#processEmit(ev, ...a)
    }
    this.#process.reallyExit = (code?: number | null | undefined) => {
      return this.#processReallyExit(code)
    }
  }

  unload() {
    if (!this.#loaded) {
      return
    }
    this.#loaded = false

    signals.forEach(sig => {
      const listener = this.#sigListeners[sig]
      /* c8 ignore start */
      if (!listener) {
        throw new Error('Listener not defined for signal: ' + sig)
      }
      /* c8 ignore stop */
      try {
        this.#process.removeListener(sig, listener)
        /* c8 ignore start */
      } catch (_) {}
      /* c8 ignore stop */
    })
    this.#process.emit = this.#originalProcessEmit
    this.#process.reallyExit = this.#originalProcessReallyExit
    this.#emitter.count -= 1
  }

  #processReallyExit(code?: number | null | undefined) {
    /* c8 ignore start */
    if (!processOk(this.#process)) {
      return 0
    }
    this.#process.exitCode = code || 0
    /* c8 ignore stop */

    this.#emitter.emit('exit', this.#process.exitCode, null)
    return this.#originalProcessReallyExit.call(
      this.#process,
      this.#process.exitCode
    )
  }

  #processEmit(ev: string, ...args: any[]): any {
    const og = this.#originalProcessEmit
    if (ev === 'exit' && processOk(this.#process)) {
      if (typeof args[0] === 'number') {
        this.#process.exitCode = args[0]
        /* c8 ignore start */
      }
      /* c8 ignore start */
      const ret = og.call(this.#process, ev, ...args)
      /* c8 ignore start */
      this.#emitter.emit('exit', this.#process.exitCode, null)
      /* c8 ignore stop */
      return ret
    } else {
      return og.call(this.#process, ev, ...args)
    }
  }
}

const process = globalThis.process
// wrap so that we call the method on the actual handler, without
// exporting it directly.
export const {
  /**
   * Called when the process is exiting, whether via signal, explicit
   * exit, or running out of stuff to do.
   *
   * If the global process object is not suitable for instrumentation,
   * then this will be a no-op.
   *
   * Returns a function that may be used to unload signal-exit.
   */
  onExit,

  /**
   * Load the listeners.  Likely you never need to call this, unless
   * doing a rather deep integration with signal-exit functionality.
   * Mostly exposed for the benefit of testing.
   *
   * @internal
   */
  load,

  /**
   * Unload the listeners.  Likely you never need to call this, unless
   * doing a rather deep integration with signal-exit functionality.
   * Mostly exposed for the benefit of testing.
   *
   * @internal
   */
  unload,
} = signalExitWrap(
  processOk(process) ? new SignalExit(process) : new SignalExitFallback()
)

"use strict";
/**
 * oag-mcp command-line interface.
 *
 * @module cli
 */
import path from "node:path";
import { fileURLToPath } from "node:url";

import bag, { type CommandArg } from "bagofcli";

import { loadConfig } from "./config.js";
import { OagMcpError, formatCliError } from "./errors.js";
import { type LogLevel, Logs, type LoggingOptions } from "./logging/logger.js";
import { type RunningServer, serve } from "./server/serve.js";

const DIRNAME = path.dirname(fileURLToPath(import.meta.url));

/**
 * Build logging options from CLI flags and an optional config section.
 * Values are already validated: flags by bagofcli (`choices` in
 * conf/commands.json), the config section by its zod schema.
 *
 * @private
 */
function _loggingOptions(
  args: CommandArg,
  fromConfig: LoggingOptions = {},
): LoggingOptions {
  return {
    level: (args.logLevel as LogLevel | undefined) ?? fromConfig.level,
    format:
      (args.logFormat as "json" | "pretty" | undefined) ?? fromConfig.format,
    file: (args.logFile as string | undefined) ?? fromConfig.file,
    auditFile:
      (args.auditLogFile as string | undefined) ?? fromConfig.auditFile,
    auditFailClosed:
      Boolean(args.auditFailClosed) || Boolean(fromConfig.auditFailClosed),
  };
}

/**
 * Report a command failure and exit.
 *
 * @private
 */
function _fail(logs: Logs | undefined, command: string, err: unknown): never {
  logs?.op("error", "cli.command.failed", {
    command,
    errorCode: err instanceof OagMcpError ? err.code : "UNEXPECTED",
    outcome: "failure",
  });
  logs?.flush();
  process.stderr.write(`${formatCliError(err)}\n`);
  process.exit(1);
}

/**
 * `serve` action. bagofcli has already validated every flag against
 * conf/commands.json (required inputs, allowed values, the port range, no
 * positional arguments) before calling it.
 *
 * @private
 */
async function _serve(args: CommandArg): Promise<void> {
  let logs: Logs | undefined;
  try {
    const transport =
      (args.transport as "stdio" | "streamable-http" | undefined) ?? "stdio";
    const { config, baseDir } = loadConfig(args.config as string | undefined);
    if (args.port !== undefined) {
      config.http.port = Number(args.port);
    }
    if (args.host) {
      config.http.host = String(args.host);
    }
    if (args.path) {
      config.http.path = String(args.path);
    }
    logs = new Logs(_loggingOptions(args, config.logging));
    logs.op("info", "cli.command.started", { command: "serve", transport });
    // Signal handlers are installed before preparation starts. A signal
    // during start-up cancels preparation at the next stage boundary; the
    // normal failure path then removes the workspace. A second signal exits
    // immediately (the exit hook still removes the workspace, best effort).
    const state: { running?: RunningServer } = {};
    const startup = new AbortController();
    let closing = false;
    const shutdown = async (signal: string) => {
      if (closing) {
        if (!state.running) {
          process.exit(1);
        }
        return;
      }
      closing = true;
      logs?.op("info", "server.shutdown_requested", {
        signal,
        phase: state.running ? "serving" : "starting",
      });
      if (!state.running) {
        startup.abort();
        return;
      }
      try {
        await state.running.close();
      } finally {
        logs?.op("info", "cli.command.completed", {
          command: "serve",
          outcome: "success",
        });
        logs?.flush();
        process.exit(0);
      }
    };
    process.on("SIGINT", () => void shutdown("SIGINT"));
    process.on("SIGTERM", () => void shutdown("SIGTERM"));
    const running = await serve({
      spec: String(args.spec),
      sdk: String(args.sdk),
      sdkLayout: args.sdkLayout as "auto" | "source" | "compiled" | undefined,
      sdkOagVersion: args.sdkOagVersion as string | undefined,
      allowUntestedOagVersion: Boolean(args.allowUntestedOagVersion),
      transport,
      config,
      configBaseDir: baseDir,
      signal: startup.signal,
      logs,
    });
    state.running = running;
    if (closing) {
      // The signal arrived while the transport was starting.
      await running.close();
      logs.flush();
      process.exit(1);
    }
    if (running.url) {
      process.stderr.write(`oag-mcp listening on ${running.url}\n`);
    }
    if (transport === "stdio") {
      // The MCP client closed our stdin: shut down and remove the workspace.
      process.stdin.once("end", () => void shutdown("stdin_closed"));
    }
  } catch (err) {
    _fail(logs, "serve", err);
  }
}

/**
 * Execute the oag-mcp CLI.
 */
function exec(): void {
  const actions = {
    commands: {
      serve: { action: (args: CommandArg) => void _serve(args) },
    },
  };
  bag.command(DIRNAME, actions);
}

const exports = {
  exec,
};

