export type Config = z.infer<typeof ConfigSchema>;

/**
 * Parse and validate a configuration object.
 *
 * @param {Object} raw - configuration object
 * @param {String} [source] - file name for messages
 * @return {Object} validated configuration
 */
export function parseConfig(raw: unknown, source = "config"): Config {
  const res = ConfigSchema.safeParse(raw ?? {});
  if (!res.success) {
    const issues = res.error.issues
      .slice(0, 8)
      .map((i) => `${i.path.join(".") || "(root)"}: ${i.message}`)
      .join("; ");
    throw new OagMcpError(
      "CONFIG_INVALID",
      `Invalid configuration in ${source}: ${issues}`,
      {
        hint: "See docs/configuration.md. Secret values must be referenced with { env: NAME } or { secret: key }, never written inline.",
      },
    );
  }
  return res.data;
}

/**
 * Load a configuration file (YAML or JSON).
 *
 * @param {String} [file] - path; undefined yields defaults
 * @return {Object} { config, baseDir }
 */
export function loadConfig(file?: string): {
  config: Config;
  baseDir: string;
} {
  if (!file) {
    return { config: parseConfig({}), baseDir: process.cwd() };
  }
  let text: string;
  try {
    text = fs.readFileSync(file, "utf8");
  } catch (err) {
    throw new OagMcpError(
      "CONFIG_NOT_FOUND",
      `Cannot read configuration file ${file}`,
      { cause: err },
    );
  }
  let raw: unknown;
  try {
    raw = YAML.parse(text);
  } catch (err) {
    throw new OagMcpError(
      "CONFIG_INVALID",
      `Configuration file ${file} is not valid YAML/JSON: ${(err as Error).message}`,
    );
  }
  return {
    config: parseConfig(raw, file),
    baseDir: path.dirname(path.resolve(file)),
  };
}

"use strict";
/**
 * Error types shared across oag-mcp components.
 *
 * @module errors
 */

/**
 * An error carrying a stable machine-readable code and an actionable hint
 * for the person running the CLI.
 */
export class OagMcpError extends Error {
  readonly code: string;
  readonly hint?: string;
  readonly details?: Record<string, unknown>;

  /**
   * @param {String} code - stable error code, e.g. "SDK_LAYOUT_UNSUPPORTED"
   * @param {String} message - human-readable description
   * @param {Object} [opts] - optional settings
   * @param {String} [opts.hint] - actionable next step
   * @param {Object} [opts.details] - structured, non-sensitive context
   * @param {Error} [opts.cause] - underlying error
   */
  constructor(
    code: string,
    message: string,
    opts: {
      hint?: string;
      details?: Record<string, unknown>;
      cause?: unknown;
    } = {},
  ) {
    super(message, opts.cause ? { cause: opts.cause } : undefined);
    this.name = "OagMcpError";
    this.code = code;
    this.hint = opts.hint;
    this.details = opts.details;
  }
}

/**
 * Format an error for terminal output (stderr), including its hint.
 *
 * @param {Error} err - error to format
 * @return {String} formatted message
 */
export function formatCliError(err: unknown): string {
  if (err instanceof OagMcpError) {
    const lines = [`Error [${err.code}]: ${err.message}`];
    if (err.hint) {
      lines.push(`Hint: ${err.hint}`);
    }
    return lines.join("\n");
  }
  if (err instanceof Error) {
    return `Error: ${err.message}`;
  }
  return `Error: ${String(err)}`;
}

"use strict";
/**
 * Structured logging with Pino, in two standard formats.
 *
 * Two event categories are produced, each in the standard suited to it:
 *
 * - `operational`: lifecycle, builds, transports, performance, failures.
 *   OpenTelemetry log records (see {@link module:otel}), filtered by the
 *   configurable operational log level.
 * - `security_audit`: authentication, authorisation, credential handling and
 *   policy enforcement. OCSF events (see {@link module:ocsf}), always
 *   recorded independent of the operational level, and never sampled.
 *
 * Every record carries a stable event name: `EventName` in operational
 * records, `metadata.event_code` in audit records. Destinations are
 * synchronous sonic-boom destinations over file descriptors, so a failing
 * audit destination is detected immediately; with fail-closed enabled,
 * callers must refuse execution while auditing is unavailable.
 *
 * @module logging/logger
 */
import crypto from "node:crypto";
import fs from "node:fs";
import tty from "node:tty";

import pino, { type Logger as PinoLogger } from "pino";
import pinoPretty, { prettyFactory } from "pino-pretty";
import sonicBoomModule, { type SonicBoomOpts } from "sonic-boom";

import {
  type AuditEvent,
  type AuditLevel,
  type AuditOutcome,
  type OcsfProduct,
  toOcsfEvent,
} from "./ocsf.js";
import {
  type OtelSource,
  SEVERITY_NUMBER,
  otelRecord,
  otelTimestamp,
  toOtelAttributes,
} from "./otel.js";
import { boundValue } from "../util/redact.js";
import { oagMcpAuthor, oagMcpName, oagMcpVersion } from "../util/version.js";

/** An operational log level: one of pino's levels, or `silent`. */
export type LogLevel = pino.LevelWithSilent;

/**
 * Operational log levels accepted by the CLI and configuration, taken from
 * pino: its levels from most to least severe, then `silent`.
 */
export const LOG_LEVELS: readonly LogLevel[] = [
  ...Object.entries(pino.levels.values)
    .sort(([, a], [, b]) => b - a)
    .map(([label]) => label as pino.Level),
  "silent",
];

/** Log event categories. */
export type LogCategory = "operational" | "security_audit";

/** Logging configuration. */
export interface LoggingOptions {
  /** Operational level; audit records ignore it. */
  level?: LogLevel;
  /** Output format for stderr destinations. Files are always JSON. */
  format?: "json" | "pretty";
  /** Operational destination: a path, `stderr` or `fd:N`. Default stderr. */
  file?: string;
  /** Audit destination: a path, `stderr` or `fd:N`. Default stderr. */
  auditFile?: string;
  /** Refuse execute calls while audit records cannot be written. */
  auditFailClosed?: boolean;
  /** Server instance identifier included in every record (default: random). */
  instanceId?: string;
}

/** Context fields that may be attached to any record. */
export interface LogContext {
  requestId?: string;
  executionId?: string;
  transport?: string;
  principalId?: string;
  /** Address and port of a Streamable HTTP client. */
  clientAddress?: string;
  clientPort?: number;
  /** MCP session and JSON-RPC request of a tool call. */
  mcpSessionId?: string;
  jsonrpcRequestId?: string | number;
  /** MCP tool being called. */
  toolName?: string;
  [key: string]: unknown;
}

/**
 * How many times in a row a write to a full, non-blocking destination
 * (typically a stderr pipe whose reader is falling behind) is retried before
 * it counts as failed. sonic-boom waits 100 ms between attempts, so this is
 * about two seconds. The count resets only when a write makes progress, so
 * once it is exhausted further writes fail fast until the reader catches up.
 */
export const MAX_WRITE_RETRIES = 20;

// sonic-boom is CommonJS (`module.exports = SonicBoom`), but its type
// definitions declare an ES default export, so TypeScript places the class one
// level deeper than it is at runtime.
const SonicBoom = sonicBoomModule as unknown as typeof sonicBoomModule.default;
type SonicBoom = InstanceType<typeof SonicBoom>;

/** Upper bound on log data held in memory while a destination is failing. */
const MAX_BUFFERED_BYTES = 1024 * 1024;

/** Depth to which logged fields are kept; deeper values are cut. */
const MAX_FIELD_DEPTH = 5;

/**
 * OpenTelemetry resource and scope of operational records.
 *
 * @param {String} [instanceId] - server instance identifier
 * @return {Object} source
 * @private
 */
function _otelSource(instanceId?: string): OtelSource {
  return {
    resource: {
      "service.name": oagMcpName(),
      "service.version": oagMcpVersion(),
      ...(instanceId ? { "service.instance.id": instanceId } : {}),
    },
    scope: { Name: `${oagMcpName()}.operational`, Version: oagMcpVersion() },
  };
}

/**
 * Write one operational record to stderr directly, never through the
 * logger, e.g. to report that a destination failed.
 *
 * @private
 */
function _reportToStderr(
  event: string,
  fields: Record<string, unknown>,
  instanceId?: string,
): void {
  try {
    fs.writeSync(
      2,
      `${JSON.stringify(otelRecord("error", event, { ...fields, outcome: "failure" }, _otelSource(instanceId)))}\n`,
    );
  } catch {
    // stderr itself is unavailable; nothing more can be done.
  }
}

/** A synchronous destination together with its failure count. */
interface TrackedDestination {
  fd: number;
  stream: SonicBoom;
  health: { failures: number };
}

/**
 * Create a synchronous sonic-boom destination over a file descriptor.
 * Failed writes are counted instead of thrown, and the first few are
 * reported to stderr directly, never through the logger.
 *
 * - Writes are synchronous, so a failing audit destination is detected during
 *   the logging call (needed for fail-closed auditing).
 * - Partial writes are completed, and a record whose write failed stays
 *   buffered (up to `MAX_BUFFERED_BYTES`) and is written, in order, once the
 *   destination recovers.
 * - A full non-blocking pipe (`EAGAIN`) is retried up to `MAX_WRITE_RETRIES`
 *   times, so a reader that never drains stderr cannot stall the server.
 *
 * sonic-boom 5 is used directly rather than through `pino.destination()`,
 * whose bundled sonic-boom 4 retries a persistent write error forever in
 * `flushSync()`; pino calls `flushSync()` after every `fatal` record.
 *
 * @param {Number} fd - file descriptor
 * @param {String} label - destination label used in failure reports
 * @return {Object} { fd, stream, health }
 * @private
 */
function _trackedDestination(fd: number, label: string): TrackedDestination {
  const health = { failures: 0 };
  let reported = 0;
  const stream = new SonicBoom({
    fd,
    sync: true,
    maxLength: MAX_BUFFERED_BYTES,
    // Supported since sonic-boom 5.0.0, not yet in its type definitions.
    maxWriteRetries: MAX_WRITE_RETRIES,
  } as SonicBoomOpts);
  const fail = (errorCode: string) => {
    health.failures++;
    if (reported < 3) {
      reported++;
      _reportToStderr("logging.destination_failed", {
        destination: label,
        errorCode,
      });
    }
  };
  stream.on("error", (err: NodeJS.ErrnoException) =>
    fail(err.code ?? "UNKNOWN"),
  );
  stream.on("drop", () => fail("BUFFER_FULL"));
  return { fd, stream, health };
}

/**
 * Open a destination specifier.
 *
 * @param {String} spec - `stderr`, `fd:N` or a file path
 * @return {Object} { fd, label, isStderr }
 * @private
 */
function _openDestination(spec: string | undefined): {
  fd: number;
  label: string;
  isStderr: boolean;
  openError?: string;
} {
  if (!spec || spec === "stderr") {
    return { fd: 2, label: "stderr", isStderr: true };
  }
  if (spec === "stdout") {
    throw new Error(
      "Logging to stdout is not allowed; stdout is reserved for MCP protocol traffic",
    );
  }
  const fdMatch = /^fd:(\d+)$/.exec(spec);
  if (fdMatch) {
    const fd = parseInt(fdMatch[1], 10);
    if (fd === 1) {
      throw new Error(
        "Logging to fd:1 (stdout) is not allowed; stdout is reserved for MCP protocol traffic",
      );
    }
    return { fd, label: spec, isStderr: fd === 2 };
  }
  try {
    const fd = fs.openSync(spec, "a", 0o600);
    return { fd, label: "file", isStderr: false };
  } catch (err) {
    return {
      fd: -1,
      label: "file",
      isStderr: false,
      openError: (err as NodeJS.ErrnoException).code ?? "OPEN_FAILED",
    };
  }
}

/**
 * Local wall-clock time of a timestamp, for pretty output.
 *
 * @param {Number} ms - milliseconds since the epoch
 * @return {String} HH:MM:ss.mmm
 * @private
 */
function _localTime(ms: number): string {
  const d = new Date(ms);
  const pad = (n: number, w = 2) => String(n).padStart(w, "0");
  return `${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}.${pad(d.getMilliseconds(), 3)}`;
}

/**
 * Build the pino logger for operational records: OpenTelemetry log records
 * with the data model's field names.
 *
 * @private
 */
function _buildOperationalPino(
  level: string,
  dest: { fd: number; isStderr: boolean },
  tracked: TrackedDestination,
  format: "json" | "pretty",
  source: OtelSource,
): PinoLogger {
  const opts: pino.LoggerOptions = {
    level,
    base: { Resource: source.resource, InstrumentationScope: source.scope },
    messageKey: "Body",
    timestamp: () => `,"Timestamp":"${otelTimestamp()}"`,
    formatters: {
      level: (label) => ({
        SeverityText: label.toUpperCase(),
        SeverityNumber: SEVERITY_NUMBER[label as pino.Level],
      }),
    },
  };
  if (format === "pretty" && dest.isStderr) {
    // Pretty output goes through the same tracked destination, so its write
    // failures are counted too.
    const stream = pinoPretty({
      destination: tracked.stream,
      colorize: tty.isatty(dest.fd),
      levelKey: "SeverityText",
      timestampKey: "Timestamp",
      translateTime: false,
      ignore: "Resource,InstrumentationScope,EventName,SeverityNumber,Body",
      messageFormat: (log) => {
        const attributes = (log.Attributes ?? {}) as Record<string, unknown>;
        const outcome = attributes["oag_mcp.outcome"];
        return `[operational] ${String(log.EventName)}${outcome ? ` ${String(outcome)}` : ""}`;
      },
      customPrettifiers: {
        // `Timestamp` is in nanoseconds, which pino-pretty cannot translate.
        time: (ts) => `[${_localTime(Number(BigInt(String(ts)) / 1000000n))}]`,
      },
    });
    return pino(opts, stream);
  }
  return pino(opts, tracked.stream);
}

/**
 * Build the writer for security audit records. Each OCSF event is written
 * exactly as built, one JSON object per line; pino is not used, since it
 * would add its own level and time fields.
 *
 * @private
 */
function _buildAuditWriter(
  dest: { fd: number; isStderr: boolean },
  tracked: TrackedDestination,
  format: "json" | "pretty",
): (event: Record<string, unknown>) => void {
  if (format === "pretty" && dest.isStderr) {
    const pretty = prettyFactory({
      colorize: tty.isatty(dest.fd),
      timestampKey: "time",
      translateTime: false,
      customPrettifiers: {
        time: (ts) => `[${_localTime(Number(ts))}]`,
        // OCSF severity, e.g. "Informational", rather than a pino level.
        level: (severity) => String(severity).toUpperCase(),
      },
      levelKey: "severity",
      hideObject: true,
      messageFormat: (log) => {
        const metadata = (log.metadata ?? {}) as Record<string, unknown>;
        const detail = log.status_detail
          ? ` (${String(log.status_detail)})`
          : "";
        return `[security_audit] ${String(metadata.event_code)} ${String(log.class_name)}: ${String(log.activity_name)} ${String(log.action ?? log.status)}${detail}`;
      },
    });
    return (event) => {
      tracked.stream.write(pretty(event));
    };
  }
  return (event) => {
    tracked.stream.write(`${JSON.stringify(event)}\n`);
  };
}

/**
 * oag-mcp logger facade: a pino logger for operational records and an
 * OCSF writer for security audit records.
 */
export class Logs {
  private readonly opLogger: PinoLogger;
  private readonly writeAudit: (event: Record<string, unknown>) => void;
  private readonly opDest: TrackedDestination;
  private readonly auditDest: TrackedDestination;
  private readonly context: LogContext;
  private readonly state: { auditOpenFailed: boolean };
  private readonly product: OcsfProduct;
  readonly failClosed: boolean;

  /**
   * @param {Object} [opts] - logging options
   * @param {Object} [shared] - internal: shared state for child loggers
   */
  constructor(
    opts: LoggingOptions = {},
    shared?: {
      opLogger: PinoLogger;
      writeAudit: (event: Record<string, unknown>) => void;
      opDest: TrackedDestination;
      auditDest: TrackedDestination;
      context: LogContext;
      state: { auditOpenFailed: boolean };
      product: OcsfProduct;
      failClosed: boolean;
    },
  ) {
    if (shared) {
      this.opLogger = shared.opLogger;
      this.writeAudit = shared.writeAudit;
      this.opDest = shared.opDest;
      this.auditDest = shared.auditDest;
      this.context = shared.context;
      this.state = shared.state;
      this.product = shared.product;
      this.failClosed = shared.failClosed;
      return;
    }
    const format = opts.format ?? "json";
    const instanceId = opts.instanceId ?? `inst_${crypto.randomUUID()}`;
    this.product = {
      name: oagMcpName(),
      version: oagMcpVersion(),
      vendorName: oagMcpAuthor(),
      instanceId,
    };
    const opDest = _openDestination(opts.file);
    const auditDest = _openDestination(opts.auditFile);
    this.opDest = _trackedDestination(opDest.fd, `operational:${opDest.label}`);
    this.auditDest = _trackedDestination(
      auditDest.fd,
      `security_audit:${auditDest.label}`,
    );
    this.state = { auditOpenFailed: Boolean(auditDest.openError) };
    this.failClosed = Boolean(opts.auditFailClosed);
    this.context = {};
    this.opLogger = _buildOperationalPino(
      opts.level ?? "info",
      opDest,
      this.opDest,
      format,
      _otelSource(instanceId),
    );
    // Audit records are never filtered by the operational level.
    this.writeAudit = _buildAuditWriter(auditDest, this.auditDest, format);
    if (opDest.openError) {
      _reportToStderr(
        "logging.destination_open_failed",
        { destination: "operational", errorCode: opDest.openError },
        instanceId,
      );
    }
    if (auditDest.openError) {
      this.auditDest.health.failures++;
      _reportToStderr(
        "logging.destination_open_failed",
        {
          destination: "security_audit",
          errorCode: auditDest.openError,
          failClosed: this.failClosed,
        },
        instanceId,
      );
    }
  }

  /**
   * Create a child logger with additional context fields.
   *
   * @param {Object} ctx - context fields such as requestId
   * @return {Logs} child logger sharing destinations
   */
  child(ctx: LogContext): Logs {
    return new Logs(
      {},
      {
        opLogger: this.opLogger,
        writeAudit: this.writeAudit,
        opDest: this.opDest,
        auditDest: this.auditDest,
        context: { ...this.context, ...ctx },
        state: this.state,
        product: this.product,
        failClosed: this.failClosed,
      },
    );
  }

  /** Context fields attached to this logger. */
  get ctx(): LogContext {
    return { ...this.context };
  }

  /**
   * Record an operational event as an OpenTelemetry log record.
   *
   * Fields are redacted and bounded, then named by the OpenTelemetry
   * semantic conventions (see {@link toOtelAttributes}).
   *
   * @param {String} level - pino level
   * @param {String} event - stable event name, e.g. "server.ready"
   * @param {Object} [fields] - structured context (never secrets or bodies)
   * @param {String} [message] - optional human message (default: the event)
   */
  op(
    level: pino.Level,
    event: string,
    fields: Record<string, unknown> = {},
    message?: string,
  ): void {
    if (!this.opLogger.isLevelEnabled(level)) {
      return;
    }
    const bounded = boundValue(
      { ...this.context, ...fields },
      { maxDepth: MAX_FIELD_DEPTH },
    ) as Record<string, unknown>;
    this.opLogger[level](
      { EventName: event, Attributes: toOtelAttributes(bounded) },
      message ?? event,
    );
  }

  /**
   * Record a security audit event as an OCSF event. Audit records bypass
   * the operational level filter and are never sampled.
   *
   * @param {String} event - stable event name, e.g. "authorization.denied"
   * @param {String} outcome - "success", "failure", "allowed", "denied", ...
   * @param {Object} [fields] - identifiers, policy ids and reason codes only
   * @param {String} [level] - "info" (default), "warn" or "error"
   * @return {Boolean} whether the record was written successfully
   */
  audit(
    event: AuditEvent,
    outcome: AuditOutcome,
    fields: Record<string, unknown> = {},
    level: AuditLevel = "info",
  ): boolean {
    const before = this.auditDest.health.failures;
    const bounded = boundValue(
      { ...this.context, ...fields },
      { maxDepth: MAX_FIELD_DEPTH },
    ) as Record<string, unknown>;
    this.writeAudit({
      ...toOcsfEvent(event, outcome, level, bounded, this.product),
      message: event,
    });
    return (
      this.auditDest.health.failures === before && !this.state.auditOpenFailed
    );
  }

  /**
   * Whether the audit destination has failed at least once.
   *
   * @return {Boolean} true when healthy
   */
  get auditHealthy(): boolean {
    return this.auditDest.health.failures === 0 && !this.state.auditOpenFailed;
  }

  /**
   * Whether execution must be refused because auditing is required
   * (fail-closed) but unavailable.
   *
   * @return {Boolean} true when execution must be refused
   */
  auditBlocksExecution(): boolean {
    return this.failClosed && !this.auditHealthy;
  }

  /** Flush destinations, e.g. on graceful shutdown. */
  flush(): void {
    for (const { fd, stream } of [this.opDest, this.auditDest]) {
      try {
        // Retry anything still buffered after an earlier failed write.
        stream.flushSync();
      } catch {
        // The destination is still failing; it has already been counted.
      }
      try {
        fs.fsyncSync(fd);
      } catch {
        // fsync is unsupported on pipes and ttys.
      }
    }
  }
}

"use strict";
/**
 * OCSF representation of security audit records.
 *
 * Every security audit record is an Open Cybersecurity Schema Framework
 * ({@link OCSF_VERSION}) event: one JSON object per line, in one of six
 * classes chosen by the oag-mcp event name (kept in `metadata.event_code`):
 *
 * | Class | Used for |
 * | --- | --- |
 * | Authentication (3002) | MCP caller authentication, upstream OAuth tokens |
 * | API Activity (6003) | the `execute` tool call and each SDK operation's authorisation |
 * | HTTP Activity (4002) | denied upstream destinations and redirects, rejected HTTP requests |
 * | Process Activity (1007) | the Deno sandbox process: limits, denied capabilities, termination |
 * | Application Lifecycle (6002) | security configuration applied, or start-up refused |
 * | Detection Finding (2004) | forged bridge messages from agent code |
 *
 * Profiles used: Date/Time (`time_dt`), Security Control (allow and deny
 * decisions), Host (`actor` where the class does not define it) and AI
 * Operation (`message_context`: the MCP tool call and session).
 *
 * Call sites log camelCase fields; {@link toOcsfEvent} places the ones OCSF
 * defines in their OCSF attribute and keeps the rest under `unmapped`.
 *
 * @module logging/ocsf
 */
import crypto from "node:crypto";
import net from "node:net";
import os from "node:os";

/** OCSF schema version followed. */
export const OCSF_VERSION = "1.9.0";

/** OCSF event classes used by oag-mcp, with the activities they use. */
const CLASSES = {
  authentication: {
    uid: 3002,
    name: "Authentication",
    category_uid: 3,
    category_name: "Identity & Access Management",
    activities: { 1: "Logon" },
  },
  api_activity: {
    uid: 6003,
    name: "API Activity",
    category_uid: 6,
    category_name: "Application Activity",
    activities: { 1: "Create", 2: "Read", 3: "Update", 4: "Delete" },
  },
  http_activity: {
    uid: 4002,
    name: "HTTP Activity",
    category_uid: 4,
    category_name: "Network Activity",
    activities: {
      1: "Connect",
      2: "Delete",
      3: "Get",
      4: "Head",
      5: "Options",
      6: "Post",
      7: "Put",
      8: "Trace",
      9: "Patch",
    },
  },
  process_activity: {
    uid: 1007,
    name: "Process Activity",
    category_uid: 1,
    category_name: "System Activity",
    activities: { 2: "Terminate" },
  },
  application_lifecycle: {
    uid: 6002,
    name: "Application Lifecycle",
    category_uid: 6,
    category_name: "Application Activity",
    activities: { 3: "Start" },
  },
  detection_finding: {
    uid: 2004,
    name: "Detection Finding",
    category_uid: 2,
    category_name: "Findings",
    activities: { 1: "Create" },
  },
} satisfies Record<
  string,
  {
    uid: number;
    name: string;
    category_uid: number;
    category_name: string;
    activities: Record<number, string>;
  }
>;

type OcsfClass = keyof typeof CLASSES;

/** OCSF `activity_id` 99 (Other): the activity is named by `activity_name`. */
const OTHER = 99;

/** API Activity's activity for each HTTP method. */
const API_ACTIVITY: Readonly<Record<string, number>> = {
  POST: 1,
  GET: 2,
  HEAD: 2,
  OPTIONS: 2,
  PUT: 3,
  PATCH: 3,
  DELETE: 4,
};

/** HTTP Activity's activity for each HTTP method. */
const HTTP_ACTIVITY: Readonly<Record<string, number>> = {
  CONNECT: 1,
  DELETE: 2,
  GET: 3,
  HEAD: 4,
  OPTIONS: 5,
  POST: 6,
  PUT: 7,
  TRACE: 8,
  PATCH: 9,
};

/** How an oag-mcp event maps to an OCSF class and activity. */
interface EventSpec {
  cls: OcsfClass;
  /** Activity id, or a source-specific name for activity 99 (Other). */
  activity: number | string;
  /** `status_id` regardless of the logged outcome. */
  statusId?: 1 | 2;
  /** `severity_id` regardless of the logged level. */
  severityId?: number;
}

type Fields = Record<string, unknown>;

/**
 * API Activity, with the activity of the SDK operation's HTTP method.
 *
 * @private
 */
function _api(f: Fields): EventSpec {
  const method = String(f.httpMethod ?? "").toUpperCase();
  return { cls: "api_activity", activity: API_ACTIVITY[method] ?? "Call" };
}

/**
 * HTTP Activity, with the activity of the request's HTTP method.
 *
 * @private
 */
function _http(f: Fields): EventSpec {
  const method = String(f.httpMethod ?? "").toUpperCase();
  return {
    cls: "http_activity",
    activity: HTTP_ACTIVITY[method] ?? (method || "Request"),
  };
}

const CONFIGURE: EventSpec = {
  cls: "application_lifecycle",
  activity: "Configure",
};
const START: EventSpec = { cls: "application_lifecycle", activity: 3 };
const LOGON: EventSpec = { cls: "authentication", activity: 1 };
const EXECUTE: EventSpec = { cls: "api_activity", activity: "Execute" };
const TERMINATE: EventSpec = {
  cls: "process_activity",
  activity: 2,
  statusId: 1,
};

/**
 * Every security audit event oag-mcp records, and its OCSF class and
 * activity. Logging an event name not listed here is a compile-time error.
 */
const EVENTS = {
  "authentication.mode_configured": () => CONFIGURE,
  "authentication.succeeded": () => LOGON,
  "authentication.failed": () => LOGON,
  "authentication.token_in_url_rejected": () => LOGON,
  "upstream.token.issue": () => ({
    cls: "authentication",
    activity: "Token Issue",
  }),
  "upstream.token.issue_failed": () => ({
    cls: "authentication",
    activity: "Token Issue",
  }),
  "upstream.token.refresh": () => ({
    cls: "authentication",
    activity: "Token Refresh",
  }),
  "upstream.token.refresh_failed": () => ({
    cls: "authentication",
    activity: "Token Refresh",
  }),
  "upstream.token.invalidated": () => ({
    cls: "authentication",
    activity: "Token Invalidate",
  }),
  "authorization.policy_loaded": () => CONFIGURE,
  "authorization.allowed": _api,
  "authorization.denied": _api,
  "credential.provider.configured": () => CONFIGURE,
  "credential.config_invalid": () => START,
  "credential.lookup_failed": _api,
  "execution.policy.applied": () => CONFIGURE,
  "execution.requested": () => EXECUTE,
  "execution.import_denied": () => EXECUTE,
  "execution.resource_limit": (f) =>
    f.operation !== undefined
      ? _api(f)
      : f.pid !== undefined
        ? { cls: "process_activity", activity: "Limit" }
        : EXECUTE,
  "execution.capability_denied": () => ({
    cls: "process_activity",
    activity: "Capability Request",
  }),
  "execution.timeout": () => TERMINATE,
  "executor.terminated": () => TERMINATE,
  "execution.boundary_violation": () => ({
    cls: "detection_finding",
    activity: 1,
    statusId: 1, // New
    severityId: 3,
  }),
  "network.destination_denied": _http,
  "network.redirect_denied": _http,
  "transport.host_rejected": _http,
  "transport.origin_rejected": _http,
  "security.config_invalid": () => START,
  "security.unauthenticated_nonloopback_refused": () => START,
} satisfies Record<string, (f: Fields) => EventSpec>;

/** A security audit event name. */
export type AuditEvent = keyof typeof EVENTS;

/** Every security audit event name, in catalogue order. */
export const AUDIT_EVENTS = Object.keys(EVENTS) as AuditEvent[];

/** Outcome of a security audit event, as logged by call sites. */
export type AuditOutcome =
  "success" | "failure" | "allowed" | "denied" | "accepted" | "terminated";

/** Severity of a security audit event, as logged by call sites. */
export type AuditLevel = "info" | "warn" | "error";

/** `severity_id` for each logged level. */
const SEVERITY_ID: Readonly<Record<AuditLevel, number>> = {
  info: 1,
  warn: 2,
  error: 4,
};

const SEVERITY_NAMES: Readonly<Record<number, string>> = {
  1: "Informational",
  2: "Low",
  3: "Medium",
  4: "High",
};

const STATUS_NAMES: Readonly<Record<number, string>> = {
  1: "Success",
  2: "Failure",
};

/** `auth_protocol_id` and `auth_protocol` for an MCP authentication mode. */
const AUTH_PROTOCOL: Readonly<Record<string, [number, string]>> = {
  oauth: [6, "OAUTH 2.0"],
  "static-bearer": [99, "Bearer Token"],
  "stdio-process-boundary": [99, "Process Boundary"],
  none: [99, "None"],
};

/** Identity of the oag-mcp process recording the events. */
export interface OcsfProduct {
  /** Package name. */
  name: string;
  /** Package version. */
  version: string;
  /** Vendor (package author). */
  vendorName?: string;
  /** Server instance identifier. */
  instanceId: string;
}

/**
 * Reads event fields, remembering which were placed in an OCSF attribute so
 * that the rest can be kept under `unmapped`.
 *
 * @private
 */
class FieldReader {
  private readonly used = new Set<string>();

  constructor(private readonly fields: Fields) {}

  /** A field's value, marking it as placed. */
  take(key: string): unknown {
    this.used.add(key);
    return this.fields[key];
  }

  /** A string field, marking it as placed. */
  str(key: string): string | undefined {
    const v = this.take(key);
    return typeof v === "string" ? v : undefined;
  }

  /** A number field, marking it as placed. */
  num(key: string): number | undefined {
    const v = this.take(key);
    return typeof v === "number" ? v : undefined;
  }

  /** Whether a field is present, without placing it. */
  has(key: string): boolean {
    return this.fields[key] !== undefined;
  }

  /** The fields not placed in any OCSF attribute. */
  rest(): Fields {
    const out: Fields = {};
    for (const [k, v] of Object.entries(this.fields)) {
      if (v !== undefined && !this.used.has(k)) {
        out[k] = v;
      }
    }
    return out;
  }
}

/**
 * An endpoint for a URL origin, by IP address or hostname.
 *
 * @private
 */
function _origin(origin: string): Fields {
  try {
    const url = new URL(origin);
    const host = url.hostname.replace(/^\[|\]$/g, "");
    const port = url.port
      ? Number(url.port)
      : url.protocol === "https:"
        ? 443
        : 80;
    return net.isIP(host) ? { ip: host, port } : { hostname: host, port };
  } catch {
    return { name: origin };
  }
}

/**
 * The MCP client's endpoint: its address for Streamable HTTP, otherwise the
 * transport name.
 *
 * @private
 */
function _client(r: FieldReader): Fields {
  const ip = r.str("clientAddress");
  const port = r.num("clientPort");
  const transport = r.str("transport");
  if (ip) {
    return { ip, ...(port !== undefined ? { port } : {}) };
  }
  return { name: transport ?? "unknown" };
}

/**
 * The URL of an upstream request: origin and path template, never a query.
 *
 * @private
 */
function _url(origin: string | undefined, path: string | undefined): Fields {
  const url: Fields = { path };
  if (origin) {
    try {
      const u = new URL(origin);
      url.scheme = u.protocol.replace(/:$/, "");
      url.hostname = u.hostname;
      url.port = u.port ? Number(u.port) : undefined;
    } catch {
      // Not a URL; it is still reported as the destination endpoint.
    }
  }
  return _compact(url);
}

/**
 * The upstream request: method and URL.
 *
 * @private
 */
function _httpRequest(r: FieldReader, origin?: string): Fields | undefined {
  const method = r.str("httpMethod");
  const url = _url(origin, r.str("pathTemplate"));
  const hasUrl = Object.keys(url).length > 0;
  if (!method && !hasUrl) {
    return undefined;
  }
  return _compact({ http_method: method, url: hasUrl ? url : undefined });
}

/**
 * The actor: the authenticated caller, or oag-mcp itself.
 *
 * @private
 */
function _actor(r: FieldReader, product: OcsfProduct): Fields {
  const principal = r.str("principalId");
  return principal
    ? { user: { uid: principal } }
    : {
        app_name: product.name,
        process: { pid: process.pid, name: product.name },
      };
}

/**
 * A copy of an object without its undefined values.
 *
 * @private
 */
function _compact(obj: Fields): Fields {
  return Object.fromEntries(
    Object.entries(obj).filter(([, v]) => v !== undefined),
  );
}

/**
 * Authentication: an MCP caller, or oag-mcp's own service identity obtaining
 * an upstream OAuth token.
 *
 * @private
 */
function _authentication(r: FieldReader, product: OcsfProduct): Fields {
  if (r.has("scheme")) {
    const status = r.num("status");
    return _compact({
      user: {
        uid: r.str("provider") ?? "upstream",
        type_id: 4,
        type: "Service",
      },
      service: { name: r.str("scheme") },
      auth_protocol_id: 6,
      auth_protocol: "OAUTH 2.0",
      status_code: status === undefined ? undefined : String(status),
    });
  }
  const principal = r.str("principalId");
  const [protocolId, protocol] = AUTH_PROTOCOL[r.str("mode") ?? ""] ?? [
    0,
    "Unknown",
  ];
  return {
    user: principal
      ? { uid: principal }
      : { name: "unknown", type_id: 0, type: "Unknown" },
    service: { name: product.name, version: product.version },
    auth_protocol_id: protocolId,
    auth_protocol: protocol,
    src_endpoint: _client(r),
  };
}

/**
 * API Activity: the `execute` tool call, or one SDK operation.
 *
 * @private
 */
function _apiActivity(r: FieldReader, product: OcsfProduct): Fields {
  const operationId = r.str("operationId");
  const executionId = r.str("executionId");
  return _compact({
    actor: _actor(r, product),
    api: _compact({
      operation: r.str("operation") ?? "execute",
      request: executionId ? { uid: executionId } : undefined,
      service: { name: product.name, version: product.version },
    }),
    src_endpoint: _client(r),
    resources: operationId
      ? [{ uid: operationId, type: "OpenAPI operation" }]
      : undefined,
    http_request: _httpRequest(r),
  });
}

/**
 * HTTP Activity: an outbound call names the upstream, an inbound request
 * the client.
 *
 * @private
 */
function _httpActivity(r: FieldReader, product: OcsfProduct): Fields {
  const origin = r.str("destinationOrigin");
  const endpoints = origin
    ? { dst_endpoint: _origin(origin) }
    : { src_endpoint: _client(r), dst_endpoint: { svc_name: product.name } };
  return _compact({
    actor: _actor(r, product),
    ...endpoints,
    http_request: _httpRequest(r, origin),
  });
}

/**
 * Process Activity: the Deno sandbox process.
 *
 * @private
 */
function _processActivity(r: FieldReader, product: OcsfProduct): Fields {
  return {
    actor: _actor(r, product),
    device: { type_id: 1, type: "Server", hostname: os.hostname() },
    process: _compact({
      name: "deno",
      pid: r.num("pid"),
      uid: r.str("executionId"),
    }),
  };
}

/**
 * Application Lifecycle: oag-mcp itself.
 *
 * @private
 */
function _applicationLifecycle(_r: FieldReader, product: OcsfProduct): Fields {
  return {
    app: _compact({
      name: product.name,
      version: product.version,
      vendor_name: product.vendorName,
    }),
  };
}

/**
 * Detection Finding: a forged bridge message from agent code.
 *
 * @private
 */
function _detectionFinding(r: FieldReader, product: OcsfProduct): Fields {
  return {
    actor: _actor(r, product),
    finding_info: {
      uid: crypto.randomUUID(),
      title: "Agent code sent a forged bridge message",
      types: ["Sandbox Boundary Violation"],
    },
  };
}

/** Class-specific attributes of each class. */
const CLASS_ATTRIBUTES: Readonly<
  Record<OcsfClass, (r: FieldReader, product: OcsfProduct) => Fields>
> = {
  authentication: _authentication,
  api_activity: _apiActivity,
  http_activity: _httpActivity,
  process_activity: _processActivity,
  application_lifecycle: _applicationLifecycle,
  detection_finding: _detectionFinding,
};

/**
 * The security control attributes of an allow or deny decision.
 *
 * @private
 */
function _control(outcome: AuditOutcome, r: FieldReader): Fields {
  if (outcome !== "allowed" && outcome !== "denied") {
    return {};
  }
  const stripped = r.take("strippedCredentials");
  const policy = r.str("policyId");
  const decision =
    outcome === "denied"
      ? {
          action_id: 2,
          action: "Denied",
          disposition_id: 2,
          disposition: "Blocked",
        }
      : Array.isArray(stripped) && stripped.length > 0
        ? {
            // Credentials supplied by agent code were removed.
            action_id: 4,
            action: "Modified",
            disposition_id: 11,
            disposition: "Corrected",
          }
        : {
            action_id: 1,
            action: "Allowed",
            disposition_id: 1,
            disposition: "Allowed",
          };
  return {
    ...decision,
    ...(policy ? { policy: { uid: policy } } : {}),
    ...(Array.isArray(stripped) ? { strippedCredentials: stripped } : {}),
  };
}

/**
 * The MCP tool call an event belongs to, as an AI Operation profile message
 * context: oag-mcp acts as a tool (`ai_role_id` 3) in the client's session.
 *
 * @private
 */
function _messageContext(
  cls: OcsfClass,
  r: FieldReader,
  product: OcsfProduct,
): Fields | undefined {
  if (cls === "detection_finding" || !r.has("toolName")) {
    return undefined;
  }
  const session = r.str("mcpSessionId");
  const tool = r.str("toolName");
  return {
    ...(session ? { uid: session } : {}),
    name: `tools/call ${tool}`,
    ai_role_id: 3,
    ai_role: "Tool",
    service: { name: product.name, version: product.version },
  };
}

/** Classes whose `actor` comes from the host profile rather than the class. */
const HOST_PROFILE: ReadonlySet<OcsfClass> = new Set([
  "http_activity",
  "detection_finding",
]);

/**
 * The classification attributes: category, class, activity and type.
 *
 * @private
 */
function _classification(spec: EventSpec): Fields {
  const cls = CLASSES[spec.cls];
  const activities: Record<number, string> = cls.activities;
  const numbered = typeof spec.activity === "number";
  const activityId = numbered ? (spec.activity as number) : OTHER;
  const activityName = numbered
    ? activities[activityId]
    : (spec.activity as string);
  return {
    category_uid: cls.category_uid,
    category_name: cls.category_name,
    class_uid: cls.uid,
    class_name: cls.name,
    activity_id: activityId,
    activity_name: activityName,
    type_uid: cls.uid * 100 + activityId,
    type_name: `${cls.name}: ${activityName}`,
  };
}

/**
 * The severity and status attributes.
 *
 * @private
 */
function _outcome(
  spec: EventSpec,
  outcome: AuditOutcome,
  level: AuditLevel,
  r: FieldReader,
): Fields {
  const severityId = spec.severityId ?? SEVERITY_ID[level];
  const failed = outcome === "failure" || outcome === "denied";
  const statusId = spec.statusId ?? (failed ? 2 : 1);
  const duration = r.num("durationMs");
  return _compact({
    severity_id: severityId,
    severity: SEVERITY_NAMES[severityId],
    status_id: statusId,
    // A finding's status is its lifecycle state: a new finding.
    status: spec.cls === "detection_finding" ? "New" : STATUS_NAMES[statusId],
    status_detail: r.str("reason"),
    status_code: r.str("errorCode"),
    duration,
  });
}

/**
 * The event metadata.
 *
 * @private
 */
function _metadata(
  event: AuditEvent,
  profiles: string[],
  r: FieldReader,
  product: OcsfProduct,
): Fields {
  return _compact({
    version: OCSF_VERSION,
    uid: crypto.randomUUID(),
    event_code: event,
    profiles,
    product: _compact({
      name: product.name,
      version: product.version,
      vendor_name: product.vendorName,
    }),
    reporter: {
      name: product.name,
      uid: product.instanceId,
      hostname: os.hostname(),
    },
    correlation_uid: r.str("requestId"),
  });
}

/**
 * The profiles an event uses beyond the class's own attributes.
 *
 * @private
 */
function _profiles(
  cls: OcsfClass,
  control: Fields,
  messageContext: Fields | undefined,
): string[] {
  return [
    "datetime",
    ...(HOST_PROFILE.has(cls) ? ["host"] : []),
    ...(control.action_id !== undefined ? ["security_control"] : []),
    ...(messageContext ? ["ai_operation"] : []),
  ];
}

/**
 * Convert a security audit event to an OCSF event.
 *
 * @param {String} event - oag-mcp event name
 * @param {String} outcome - logged outcome
 * @param {String} level - logged level
 * @param {Object} fields - context and event fields, already redacted and
 *   bounded
 * @param {Object} product - the recording oag-mcp instance
 * @param {Number} [time] - event time in milliseconds (default: now)
 * @return {Object} OCSF event (without `message`, which the logger adds)
 */
export function toOcsfEvent(
  event: AuditEvent,
  outcome: AuditOutcome,
  level: AuditLevel,
  fields: Fields,
  product: OcsfProduct,
  time: number = Date.now(),
): Fields {
  const spec = (EVENTS[event] as (f: Fields) => EventSpec)(fields);
  const r = new FieldReader(fields);
  const classification = _classification(spec);
  const outcomes = _outcome(spec, outcome, level, r);
  const attributes = CLASS_ATTRIBUTES[spec.cls](r, product);
  const messageContext = _messageContext(spec.cls, r, product);
  const { strippedCredentials, ...control } = _control(outcome, r);
  const metadata = _metadata(
    event,
    _profiles(spec.cls, control, messageContext),
    r,
    product,
  );
  const unmapped = _compact({ ...r.rest(), strippedCredentials });
  return _compact({
    time,
    time_dt: new Date(time).toISOString(),
    timezone_offset: 0,
    ...classification,
    ...outcomes,
    metadata,
    ...attributes,
    message_context: messageContext,
    ...control,
    unmapped: Object.keys(unmapped).length > 0 ? unmapped : undefined,
  });
}

"use strict";
/**
 * OpenTelemetry representation of operational log records.
 *
 * Operational records follow the OpenTelemetry Logs Data Model: one JSON
 * object per line with the data model's field names (`Timestamp`,
 * `SeverityText`, `SeverityNumber`, `EventName`, `Body`, `Resource`,
 * `InstrumentationScope`, `Attributes`).
 *
 * Attribute names follow the OpenTelemetry semantic conventions
 * ({@link OTEL_SEMCONV_VERSION}), including the Model Context Protocol
 * conventions. Attributes the conventions do not define are prefixed with
 * the `oag_mcp.` namespace, as the conventions recommend.
 *
 * Call sites log camelCase fields; {@link toOtelAttributes} maps them.
 *
 * @module logging/otel
 */
import type pino from "pino";

/** Version of the OpenTelemetry semantic conventions followed. */
export const OTEL_SEMCONV_VERSION = "1.44.0";

/** Namespace for attributes that the semantic conventions do not define. */
export const OAG_MCP_NAMESPACE = "oag_mcp";

/** `SeverityNumber` of each pino level (OpenTelemetry Logs Data Model). */
export const SEVERITY_NUMBER: Readonly<Record<pino.Level, number>> = {
  trace: 1,
  debug: 5,
  info: 9,
  warn: 13,
  error: 17,
  fatal: 21,
};

/**
 * Fields whose OpenTelemetry semantic convention attribute differs from the
 * default `oag_mcp.<snake_case>` name.
 */
const ATTRIBUTES: Readonly<Record<string, string>> = {
  // Correlation identifiers specific to oag-mcp.
  requestId: "oag_mcp.request.id",
  executionId: "oag_mcp.execution.id",
  prepareId: "oag_mcp.prepare.id",
  // The authenticated caller.
  principalId: "enduser.id",
  clientAddress: "client.address",
  clientPort: "client.port",
  // Model Context Protocol.
  mcpSessionId: "mcp.session.id",
  jsonrpcRequestId: "jsonrpc.request.id",
  toolName: "gen_ai.tool.name",
  // HTTP calls to the upstream API.
  httpMethod: "http.request.method",
  status: "http.response.status_code",
  pathTemplate: "url.template",
  responseBytes: "http.response.body.size",
  // The address the HTTP transport listens on.
  host: "server.address",
  port: "server.port",
  // Error classification.
  error: "error.type",
  errorCode: "error.type",
  errorType: "error.type",
};

/**
 * Convert a camelCase field name to snake_case.
 *
 * @param {String} name - field name, e.g. "startupDurationMs"
 * @return {String} snake_case name, e.g. "startup_duration_ms"
 * @private
 */
function _snake(name: string): string {
  return name
    .replace(/([a-z0-9])([A-Z])/g, "$1_$2")
    .replace(/([A-Z])([A-Z][a-z])/g, "$1_$2")
    .toLowerCase();
}

/**
 * The attribute name for a field: its semantic convention attribute, or
 * `oag_mcp.<snake_case>`.
 *
 * @param {String} field - camelCase field name
 * @return {String} attribute name
 */
export function otelAttributeName(field: string): string {
  return ATTRIBUTES[field] ?? `${OAG_MCP_NAMESPACE}.${_snake(field)}`;
}

/**
 * Map logged fields to OpenTelemetry attributes.
 *
 * - `transport` becomes `network.transport` (`pipe` for stdio, `tcp` for
 *   Streamable HTTP, with `network.protocol.name: http`), as the MCP
 *   conventions describe.
 * - `toolName` also sets `mcp.method.name: tools/call` and
 *   `gen_ai.operation.name: execute_tool`.
 * - Undefined values are dropped.
 *
 * @param {Object} fields - camelCase fields, already redacted and bounded
 * @return {Object} attributes keyed by attribute name
 */
export function toOtelAttributes(
  fields: Record<string, unknown>,
): Record<string, unknown> {
  const out: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(fields)) {
    if (value === undefined) {
      continue;
    }
    if (key === "transport") {
      if (value === "stdio") {
        out["network.transport"] = "pipe";
      } else if (value === "streamable-http") {
        out["network.transport"] = "tcp";
        out["network.protocol.name"] = "http";
      } else {
        out[otelAttributeName(key)] = value;
      }
      continue;
    }
    if (key === "toolName") {
      out["mcp.method.name"] = "tools/call";
      out["gen_ai.operation.name"] = "execute_tool";
    }
    out[otelAttributeName(key)] = value;
  }
  return out;
}

/**
 * `Timestamp` of a record: nanoseconds since the Unix epoch, as a string.
 *
 * @param {Number} [ms] - milliseconds since the epoch (default: now)
 * @return {String} nanoseconds since the epoch
 */
export function otelTimestamp(ms: number = Date.now()): string {
  return `${ms}000000`;
}

/** The `Resource` and `InstrumentationScope` of every operational record. */
export interface OtelSource {
  /** Resource attributes, e.g. `service.name`. */
  resource: Record<string, unknown>;
  /** Instrumentation scope name and version. */
  scope: { Name: string; Version?: string };
}

/**
 * Build a complete operational record outside the logger, for the few
 * reports written to stderr directly when a destination fails.
 *
 * @param {String} level - pino level
 * @param {String} event - event name
 * @param {Object} fields - camelCase fields (no secrets)
 * @param {Object} source - resource and scope
 * @return {Object} record
 */
export function otelRecord(
  level: pino.Level,
  event: string,
  fields: Record<string, unknown>,
  source: OtelSource,
): Record<string, unknown> {
  return {
    Timestamp: otelTimestamp(),
    SeverityText: level.toUpperCase(),
    SeverityNumber: SEVERITY_NUMBER[level],
    Resource: source.resource,
    InstrumentationScope: source.scope,
    EventName: event,
    Attributes: toOtelAttributes(fields),
    Body: event,
  };
}

"use strict";
/**
 * Redaction and sanitisation of values before they reach logs, errors,
 * search results or tool output.
 *
 * @module util/redact
 */

/** Placeholder written in place of a sensitive value. */
export const REDACTED = "[REDACTED]";

/** Key names whose values are always censored, matched case-insensitively. */
const SENSITIVE_KEY =
  /^(authorization|proxy-authorization|cookie|set-cookie|password|passwd|secret|client_?secret|api_?key|apikey|x-api-key|token|access_?token|refresh_?token|id_?token|bearer|credentials?|private_?key)$/i;

/** Patterns that look like credentials inside free text. */
const TEXT_PATTERNS: Array<[RegExp, string]> = [
  [/\b(Bearer|Basic|Digest)\s+[A-Za-z0-9._~+/=-]{4,}/gi, `$1 ${REDACTED}`],
  [/\beyJ[A-Za-z0-9_-]{4,}\.[A-Za-z0-9_-]{4,}\.[A-Za-z0-9_-]*/g, REDACTED],
  [
    /([?&;](?:api[_-]?key|apikey|access_token|token|key|secret|password|client_secret|code|sig|signature)=)[^&#\s"']+/gi,
    `$1${REDACTED}`,
  ],
  [/(\/\/)[^/@\s:]+:[^/@\s]+@/g, `$1${REDACTED}@`],
];

/**
 * Registry of secret values known to the process (upstream credentials,
 * issued upstream tokens, MCP bearer tokens). Every outbound string is
 * scrubbed against it.
 */
export class SecretRegistry {
  private readonly values = new Set<string>();

  /**
   * Register a secret value. Values shorter than 4 characters are ignored
   * because scrubbing them would corrupt ordinary text.
   *
   * @param {String} value - secret value
   */
  add(value: string | undefined | null): void {
    if (typeof value === "string" && value.length >= 4) {
      this.values.add(value);
      // Also catch the base64 forms used by HTTP Basic credentials.
      this.values.add(Buffer.from(value).toString("base64"));
    }
  }

  /**
   * Forget a secret value (e.g. an expired token).
   *
   * @param {String} value - secret value
   */
  remove(value: string | undefined): void {
    if (value) {
      this.values.delete(value);
      this.values.delete(Buffer.from(value).toString("base64"));
    }
  }

  /**
   * Number of registered values.
   *
   * @return {Number} count
   */
  get size(): number {
    return this.values.size;
  }

  /**
   * Replace only registered secret values (no heuristics), for data such as
   * API results where pattern-based scrubbing could corrupt content.
   *
   * @param {String} text - text to scrub
   * @return {String} scrubbed text
   */
  scrubKnown(text: string): string {
    let out = text;
    const sorted = [...this.values].sort((a, b) => b.length - a.length);
    for (const v of sorted) {
      if (out.includes(v)) {
        out = out.split(v).join(REDACTED);
      }
    }
    return out;
  }

  /**
   * Replace registered secret values and credential-looking patterns.
   *
   * @param {String} text - text to scrub
   * @return {String} scrubbed text
   */
  scrub(text: string): string {
    let out = text;
    // Longest first so a secret containing another secret is fully hidden.
    const sorted = [...this.values].sort((a, b) => b.length - a.length);
    for (const v of sorted) {
      if (out.includes(v)) {
        out = out.split(v).join(REDACTED);
      }
    }
    for (const [re, replacement] of TEXT_PATTERNS) {
      out = out.replace(re, replacement);
    }
    return out;
  }
}

/** Process-wide registry used by the logger and error sanitisers. */
export const secrets = new SecretRegistry();

/**
 * Whether a key name denotes a sensitive value.
 *
 * @param {String} key - property name
 * @return {Boolean} true when sensitive
 */
export function isSensitiveKey(key: string): boolean {
  return SENSITIVE_KEY.test(key);
}

/** Limits applied by {@link boundValue}. */
export interface BoundOptions {
  maxString?: number;
  maxDepth?: number;
  maxKeys?: number;
  maxArray?: number;
  registry?: SecretRegistry;
}

/** Limits and state of one {@link boundValue} walk. */
interface Walk {
  maxString: number;
  maxDepth: number;
  maxKeys: number;
  maxArray: number;
  registry: SecretRegistry;
  seen: WeakSet<object>;
}

/** Marks a value that is not a scalar, so it is walked as an object. */
const NOT_SCALAR = Symbol("not scalar");

/**
 * Produce a bounded, scrubbed, JSON-safe copy of a value for logging.
 * Sensitive keys are censored, long strings truncated, deep structures cut.
 *
 * @param {*} value - value to bound
 * @param {Object} [opts] - limits
 * @return {*} bounded copy
 */
export function boundValue(value: unknown, opts: BoundOptions = {}): unknown {
  return _walk(value, 0, {
    maxString: opts.maxString ?? 512,
    maxDepth: opts.maxDepth ?? 6,
    maxKeys: opts.maxKeys ?? 50,
    maxArray: opts.maxArray ?? 50,
    registry: opts.registry ?? secrets,
    seen: new WeakSet<object>(),
  });
}

/**
 * Bound one value at a depth.
 *
 * @private
 */
function _walk(v: unknown, depth: number, w: Walk): unknown {
  const scalar = _scalar(v, w);
  if (scalar !== NOT_SCALAR) {
    return scalar;
  }
  const obj = v as object;
  if (w.seen.has(obj)) {
    return "[circular]";
  }
  if (depth >= w.maxDepth) {
    return "[max-depth]";
  }
  w.seen.add(obj);
  return Array.isArray(obj)
    ? _walkArray(obj, depth, w)
    : _walkObject(obj as Record<string, unknown>, depth, w);
}

/**
 * Bound a value that is not walked into: strings (scrubbed and truncated),
 * other primitives, errors and dates.
 *
 * @private
 */
function _scalar(v: unknown, w: Walk): unknown {
  if (v === null || v === undefined) {
    return v;
  }
  switch (typeof v) {
    case "string": {
      const s = w.registry.scrub(v);
      return s.length > w.maxString
        ? `${s.slice(0, w.maxString)}…[truncated ${s.length - w.maxString}]`
        : s;
    }
    case "number":
    case "boolean":
      return v;
    case "bigint":
      return v.toString();
    case "object":
      return _scalarObject(v, w);
    default:
      return `[${typeof v}]`;
  }
}

/**
 * Bound errors (sanitised) and dates (ISO 8601); other objects are walked.
 *
 * @private
 */
function _scalarObject(v: object, w: Walk): unknown {
  if (v instanceof Error) {
    return sanitizeError(v, w.registry);
  }
  if (v instanceof Date) {
    return v.toISOString();
  }
  return NOT_SCALAR;
}

/**
 * Bound an array: its first items, then a count of the rest.
 *
 * @private
 */
function _walkArray(v: unknown[], depth: number, w: Walk): unknown[] {
  const arr = v.slice(0, w.maxArray).map((x) => _walk(x, depth + 1, w));
  if (v.length > w.maxArray) {
    arr.push(`[+${v.length - w.maxArray} more]`);
  }
  return arr;
}

/**
 * Bound an object: its first keys, with sensitive keys censored.
 *
 * @private
 */
function _walkObject(
  v: Record<string, unknown>,
  depth: number,
  w: Walk,
): Record<string, unknown> {
  const out: Record<string, unknown> = {};
  let count = 0;
  for (const [k, val] of Object.entries(v)) {
    if (count++ >= w.maxKeys) {
      out["…"] = "[more keys truncated]";
      break;
    }
    out[k] = isSensitiveKey(k) ? REDACTED : _walk(val, depth + 1, w);
  }
  return out;
}

/**
 * Sanitise an error into a small structured object without stack traces.
 *
 * @param {Error} err - error to sanitise
 * @param {SecretRegistry} [registry] - registry used to scrub messages
 * @return {Object} { name, code, message }
 */
export function sanitizeError(
  err: unknown,
  registry: SecretRegistry = secrets,
): { name: string; code?: string; message: string } {
  if (err instanceof Error) {
    const code = (err as { code?: unknown }).code;
    const message = registry.scrub(err.message || "");
    return {
      name: err.name,
      ...(typeof code === "string" ? { code } : {}),
      message: message.length > 1000 ? `${message.slice(0, 1000)}…` : message,
    };
  }
  return { name: "Error", message: registry.scrub(String(err)).slice(0, 1000) };
}

"use strict";
/**
 * Version information for oag-mcp and the tools it pins.
 *
 * @module util/version
 */
import fs from "node:fs";
import { createRequire } from "node:module";
import path from "node:path";
import { fileURLToPath } from "node:url";

const require = createRequire(import.meta.url);

/**
 * Exact OpenAPI Generator versions that oag-mcp is tested against. SDKs
 * generated by any other version are rejected unless
 * --allow-untested-oag-version is given. Add versions here (with a fixture
 * and tests) to support more than one.
 */
export const SUPPORTED_OAG_VERSIONS = ["7.26.0"] as const;

/** The only OpenAPI Generator target supported by this release. */
export const SUPPORTED_GENERATOR = "typescript-fetch";

/** Deno versions accepted by the executor, as a semver range. */
export const DENO_VERSION_RANGE = ">=2.5.0 <3.0.0";

let cachedPackage:
  { name: string; version: string; author?: string } | undefined;

/**
 * Locate the oag-mcp package root by walking up from this module.
 *
 * @return {String} absolute directory containing oag-mcp's package.json
 */
export function packageRoot(): string {
  let dir = path.dirname(fileURLToPath(import.meta.url));
  for (let i = 0; i < 5; i++) {
    const candidate = path.join(dir, "package.json");
    if (fs.existsSync(candidate)) {
      const pkg = JSON.parse(fs.readFileSync(candidate, "utf8"));
      if (pkg.name === "oag-mcp") {
        return dir;
      }
    }
    dir = path.dirname(dir);
  }
  throw new Error("Unable to locate the oag-mcp package root");
}

/**
 * The name in a package.json person field: npm's "Name <email> (url)" form,
 * or an object with a name.
 *
 * @param {String|Object} [author] - the field's value
 * @return {String} the name, or undefined when there is none
 */
export function authorName(author: unknown): string | undefined {
  const name =
    typeof author === "string"
      ? author.replace(/\s*[<(].*$/, "").trim()
      : (author as { name?: unknown } | undefined)?.name;
  return typeof name === "string" && name ? name : undefined;
}

/**
 * Read (once) oag-mcp's own package.json.
 *
 * @private
 */
function _package(): { name: string; version: string; author?: string } {
  if (!cachedPackage) {
    const pkg = JSON.parse(
      fs.readFileSync(path.join(packageRoot(), "package.json"), "utf8"),
    );
    cachedPackage = {
      name: pkg.name as string,
      version: pkg.version as string,
      author: authorName(pkg.author),
    };
  }
  return cachedPackage;
}

/**
 * Read the oag-mcp package name from package.json.
 *
 * @return {String} package name
 */
export function oagMcpName(): string {
  return _package().name;
}

/**
 * Read the oag-mcp version from package.json.
 *
 * @return {String} version string
 */
export function oagMcpVersion(): string {
  return _package().version;
}

/**
 * Read the oag-mcp author's name from package.json.
 *
 * @return {String} author name, or undefined when not set
 */
export function oagMcpAuthor(): string | undefined {
  return _package().author;
}

/**
 * Read the installed version of a dependency.
 *
 * @param {String} name - package name
 * @return {String} version, or "unknown"
 */
export function dependencyVersion(name: string): string {
  try {
    const pkgPath = require.resolve(`${name}/package.json`);
    return JSON.parse(fs.readFileSync(pkgPath, "utf8")).version;
  } catch {
    return "unknown";
  }
}

"use strict";
/**
 * `oag-mcp serve`: prepare an OpenAPI document and an existing
 * typescript-fetch SDK once, then serve them over stdio or Streamable HTTP.
 *
 * Start-up order: inputs → compatibility → SDK bundle/declarations → index
 * (prepare/prepare) → bridge and executor (server/service) → tool
 * registration → transport. No request is accepted until every stage has
 * succeeded; on any failure the private workspace is removed and the error
 * is returned (no partially functional server).
 *
 * stdio uses the local process/OS boundary for access control: the parent
 * process that spawned the server is the caller. stdout carries only MCP
 * protocol traffic; logs go to stderr or configured files.
 *
 * Streamable HTTP binds to loopback by default and authenticates every
 * protected request (see server/authentication). This is the 2025-03-26+ Streamable
 * HTTP transport, not the legacy HTTP+SSE transport.
 *
 * @module server/serve
 */
import crypto from "node:crypto";
import http from "node:http";
import type { AddressInfo } from "node:net";
import type { Readable, Writable } from "node:stream";

import {
  hostHeaderValidation,
  localhostOriginValidation,
  originValidation,
  toNodeHandler,
} from "@modelcontextprotocol/node";
import {
  createMcpHandler,
  localhostAllowedHostnames,
} from "@modelcontextprotocol/server";
import {
  StdioServerTransport,
  serveStdio,
} from "@modelcontextprotocol/server/stdio";

import {
  type HttpAuthenticator,
  createHttpAuthenticator,
  isLoopbackHost,
} from "./authentication.js";
import { type Config, browserOrigin } from "../config.js";
import type { Executor } from "../executor/types.js";
import { SecretResolver } from "../util/secrets.js";
import { OagMcpError } from "../errors.js";
import type { Logs } from "../logging/logger.js";
import { secrets } from "../util/redact.js";
import {
  type PrepareOptions,
  type PreparedSdk,
  prepareSdk,
  runStage,
} from "../prepare/prepare.js";
import type { Principal } from "../types.js";
import { TOOL_NAMES, createMcpServer } from "./tools.js";
import { type ClientEndpoint, OagMcpService } from "./service.js";

/** A running server. */
export interface RunningServer {
  transport: "stdio" | "streamable-http";
  /** Bound URL for HTTP. */
  url?: string;
  close(): Promise<void>;
}

/** Options for {@link serve}. */
export interface ServeOptions extends Omit<PrepareOptions, "logs"> {
  transport: "stdio" | "streamable-http";
  config: Config;
  configBaseDir: string;
  logs: Logs;
  fetchImpl?: typeof fetch;
  /** Executor for agent code; default: a verified Deno subprocess executor. */
  executor?: Executor;
  /** Streams for the stdio transport; default: this process's. */
  stdio?: { stdin: Readable; stdout: Writable };
}

/** Node.js request handling for Streamable HTTP. */
type NodeHandler = ReturnType<typeof toNodeHandler>;

/** Validates one request, writing the refusal itself; false when refused. */
type RequestValidator = (
  req: http.IncomingMessage,
  res: http.ServerResponse,
) => boolean;

/** Everything a Streamable HTTP request is routed with. */
interface HttpContext {
  h: Config["http"];
  logs: Logs;
  authenticator: HttpAuthenticator;
  nodeHandler: NodeHandler;
  validateHost: RequestValidator | undefined;
  validateOrigin: RequestValidator;
  resourceUrl: URL;
}

/** What identifies one HTTP request in records and in the MCP server. */
interface HttpRequestScope {
  requestId: string;
  client: ClientEndpoint;
  reqLogs: Logs;
}

/**
 * Prepare the SDK and start serving it.
 *
 * @param {Object} opts - serve options
 * @return {Promise} running server
 */
export async function serve(opts: ServeOptions): Promise<RunningServer> {
  const started = Date.now();
  return servePrepared(await prepareSdk(opts), opts, started);
}

/**
 * Serve an already prepared SDK. The prepared workspace is removed when
 * start-up fails or the server is closed.
 *
 * @param {Object} prepared - prepared SDK
 * @param {Object} opts - serve options
 * @param {Number} [started] - start-up start time, default: now
 * @return {Promise} running server
 */
export async function servePrepared(
  prepared: PreparedSdk,
  opts: ServeOptions,
  started: number = Date.now(),
): Promise<RunningServer> {
  const { config, logs } = opts;
  let running: RunningServer;
  try {
    const service = await runStage(
      logs,
      "executor",
      () =>
        OagMcpService.create({
          prepared,
          config,
          configBaseDir: opts.configBaseDir,
          logs,
          executor: opts.executor,
          fetchImpl: opts.fetchImpl,
        }),
      opts.signal,
    );
    logs.op("info", "tools.registered", {
      tools: TOOL_NAMES,
      methods: prepared.records.length,
    });
    if (opts.signal?.aborted) {
      throw new OagMcpError(
        "STARTUP_ABORTED",
        "Start-up was cancelled before the transport started",
        { hint: "The server received a shutdown signal while preparing." },
      );
    }
    service.warmUp();
    running =
      opts.transport === "stdio"
        ? _serveStdio(service, opts)
        : await _serveHttp(service, opts);
  } catch (err) {
    prepared.cleanup();
    throw err;
  }
  logs.op("info", "server.ready", {
    transport: running.transport,
    prepareId: prepared.info.prepareId,
    methods: prepared.records.length,
    startupDurationMs: Date.now() - started,
  });
  const close = running.close;
  let closed: Promise<void> | undefined;
  running.close = () => {
    closed ??= (async () => {
      try {
        await close();
      } finally {
        if (prepared.cleanup()) {
          logs.op("info", "prepare.workspace.cleaned", { outcome: "success" });
        }
        logs.op("info", "server.stopped", { transport: running.transport });
        logs.flush();
      }
    })();
    return closed;
  };
  return running;
}

/**
 * Serve over stdio.
 *
 * @private
 */
function _serveStdio(
  service: OagMcpService,
  opts: ServeOptions,
): RunningServer {
  const { logs, config } = opts;
  const principal: Principal = {
    id: `local:${config.mcpAuth.stdio.principal}`,
    kind: "local",
    name: config.mcpAuth.stdio.principal,
    scopes: config.mcpAuth.stdio.scopes,
  };
  logs.audit("authentication.succeeded", "success", {
    mode: "stdio-process-boundary",
    principalId: principal.id,
    transport: "stdio",
  });
  const handle = serveStdio(
    () => createMcpServer(service, principal, "stdio"),
    {
      transport: new StdioServerTransport(
        opts.stdio?.stdin,
        opts.stdio?.stdout,
      ),
      onerror: (err) =>
        logs.op("error", "transport.error", {
          transport: "stdio",
          error: err.name,
        }),
    },
  );
  logs.op("info", "transport.initialized", {
    transport: "stdio",
    outcome: "success",
  });
  return {
    transport: "stdio",
    close: async () => {
      await handle.close();
    },
  };
}

/**
 * Refuse unauthenticated non-loopback binds; warn about remote exposure.
 *
 * @private
 */
function _checkExposure(config: Config, logs: Logs, loopback: boolean): void {
  const host = config.http.host;
  if (config.mcpAuth.mode === "none" && !loopback) {
    logs.audit(
      "security.unauthenticated_nonloopback_refused",
      "denied",
      { host, mode: "none" },
      "error",
    );
    throw new OagMcpError(
      "MCP_AUTH_REQUIRED",
      `Refusing to serve unauthenticated MCP on non-loopback address ${host}`,
      {
        hint: "Bind to 127.0.0.1, or configure mcpAuth.mode static-bearer or oauth. Terminate TLS in front of the server for remote access.",
      },
    );
  }
  if (!loopback) {
    logs.op("warn", "transport.remote_exposure", {
      host,
      note: "terminate HTTPS in a reverse proxy; oag-mcp serves plain HTTP",
    });
  }
}

/**
 * Start listening.
 *
 * @private
 */
function _listen(h: Config["http"]): Promise<http.Server> {
  return new Promise((resolve, reject) => {
    const server = http.createServer();
    server.once("error", reject);
    server.listen(h.port, h.host, () => resolve(server));
  });
}

/**
 * The URL a listening server serves the MCP endpoint at.
 *
 * @private
 */
function _localUrl(server: http.Server, h: Config["http"]): string {
  const listen = server.address() as AddressInfo;
  const host =
    listen.family === "IPv6" ? `[${listen.address}]` : listen.address;
  return `http://${host}:${listen.port}${h.path}`;
}

/**
 * Create the authenticator, auditing an invalid configuration.
 *
 * @private
 */
async function _authenticator(
  service: OagMcpService,
  opts: ServeOptions,
  resourceUrl: URL,
): Promise<HttpAuthenticator> {
  const { config, logs } = opts;
  try {
    return await createHttpAuthenticator({
      config,
      resolver: new SecretResolver({
        secretsFile: config.upstreamAuth.secretsFile,
        baseDir: opts.configBaseDir,
      }),
      registry: secrets,
      logs,
      resourceUrl,
      resourceName: `${service.info.api.title} (oag-mcp)`,
    });
  } catch (err) {
    logs.audit(
      "security.config_invalid",
      "failure",
      {
        area: "mcpAuth",
        errorCode: err instanceof OagMcpError ? err.code : "UNEXPECTED",
      },
      "error",
    );
    throw err;
  }
}

/**
 * The Streamable HTTP MCP request handler: creates an MCP server for each
 * authenticated request's principal, and refuses a request that arrives
 * without one (routing authenticates first; this is a second line).
 *
 * @param {Object} service - the service the tools call
 * @param {Object} logs - logs
 * @return {Object} MCP handler
 */
export function mcpRequestHandler(
  service: OagMcpService,
  logs: Logs,
): ReturnType<typeof createMcpHandler> {
  return createMcpHandler(
    ({ authInfo }) => {
      const extra = (authInfo?.extra ?? {}) as {
        principal?: Principal;
        requestId?: string;
        client?: ClientEndpoint;
      };
      if (!extra.principal) {
        throw new Error("unauthenticated request reached the MCP handler");
      }
      return createMcpServer(
        service,
        extra.principal,
        "streamable-http",
        extra.requestId,
        extra.client,
      );
    },
    {
      onerror: (err) =>
        logs.op("warn", "transport.request_failed", {
          transport: "streamable-http",
          error: err.name,
        }),
    },
  );
}

/**
 * Host header validation: the localhost names plus the configured hosts on
 * loopback binds; elsewhere the configured hosts, if any.
 *
 * @private
 */
function _hostValidator(
  h: Config["http"],
  loopback: boolean,
): RequestValidator | undefined {
  if (loopback) {
    return hostHeaderValidation([
      ...localhostAllowedHostnames(),
      ...h.allowedHosts,
    ]);
  }
  return h.allowedHosts.length > 0
    ? hostHeaderValidation(h.allowedHosts)
    : undefined;
}

/**
 * Origin validation: exactly the configured origins, otherwise loopback
 * origins on loopback binds and none elsewhere. Requests without an Origin
 * header (non-browser clients) pass.
 *
 * @private
 */
function _originValidator(
  h: Config["http"],
  loopback: boolean,
): RequestValidator {
  if (h.allowedOrigins.length > 0) {
    return _exactOriginValidation(h.allowedOrigins);
  }
  return loopback ? localhostOriginValidation() : originValidation([]);
}

/**
 * Admit only these origins, compared by scheme, host and port. The MCP SDK's
 * own guard compares hostnames only.
 *
 * @private
 */
function _exactOriginValidation(origins: string[]): RequestValidator {
  const allowed = new Set(origins.map(browserOrigin));
  return (req, res) => {
    const origin = req.headers.origin;
    if (!origin) {
      return true;
    }
    const normalised = browserOrigin(origin);
    if (normalised !== undefined && allowed.has(normalised)) {
      return true;
    }
    res.writeHead(403, { "content-type": "application/json" });
    res.end(
      JSON.stringify({
        jsonrpc: "2.0",
        error: { code: -32000, message: "Origin not allowed" },
        id: null,
      }),
    );
    return false;
  };
}

/**
 * Serve over Streamable HTTP.
 *
 * @private
 */
async function _serveHttp(
  service: OagMcpService,
  opts: ServeOptions,
): Promise<RunningServer> {
  const { logs, config } = opts;
  const h = config.http;
  const loopback = isLoopbackHost(h.host);
  _checkExposure(config, logs, loopback);
  const server = await _listen(h);
  const localUrl = _localUrl(server, h);
  const resourceUrl = new URL(h.publicUrl ?? localUrl);
  let authenticator: HttpAuthenticator;
  try {
    authenticator = await _authenticator(service, opts, resourceUrl);
  } catch (err) {
    server.close();
    throw err;
  }
  const handler = mcpRequestHandler(service, logs);
  const ctx: HttpContext = {
    h,
    logs,
    authenticator,
    nodeHandler: toNodeHandler(handler, {
      maxRequestBodySize: h.maxBodyBytes,
      onerror: (err) =>
        logs.op("error", "transport.error", {
          transport: "streamable-http",
          error: err.name,
        }),
    }),
    validateHost: _hostValidator(h, loopback),
    validateOrigin: _originValidator(h, loopback),
    resourceUrl,
  };
  server.on("request", (req, res) => _handleRequest(ctx, req, res));
  server.on("clientError", (err, socket) => {
    logs.op("warn", "transport.connection_failed", {
      transport: "streamable-http",
      error: err.name,
    });
    socket.destroy();
  });
  logs.op("info", "transport.initialized", {
    transport: "streamable-http",
    host: h.host,
    port: (server.address() as AddressInfo).port,
    path: h.path,
    mcpAuthMode: authenticator.mode,
    outcome: "success",
  });
  return {
    transport: "streamable-http",
    url: localUrl,
    close: async () => {
      await handler.close();
      const closed = new Promise<void>((resolve) =>
        server.close(() => resolve()),
      );
      server.closeAllConnections();
      await closed;
    },
  };
}

/**
 * Handle one HTTP request, answering a server error when routing fails.
 *
 * @private
 */
async function _handleRequest(
  ctx: HttpContext,
  req: http.IncomingMessage,
  res: http.ServerResponse,
): Promise<void> {
  const requestId = `req_${crypto.randomUUID()}`;
  const client = {
    clientAddress: req.socket.remoteAddress,
    clientPort: req.socket.remotePort,
  };
  const reqLogs = ctx.logs.child({
    requestId,
    transport: "streamable-http",
    ...client,
  });
  try {
    await _route(ctx, req, res, { requestId, client, reqLogs });
  } catch (err) {
    reqLogs.op("error", "transport.request_failed", {
      error: (err as Error).name,
    });
    if (!res.headersSent) {
      _respond(res, 500, '{"error":"server_error"}');
    }
  }
}

/**
 * Route one HTTP request: transport checks, health, discovery metadata,
 * authentication, then the MCP handler.
 *
 * @private
 */
async function _route(
  ctx: HttpContext,
  req: http.IncomingMessage,
  res: http.ServerResponse,
  scope: HttpRequestScope,
): Promise<void> {
  if (!_admitted(ctx, req, res, scope.reqLogs)) {
    return;
  }
  const url = new URL(req.url ?? "/", "http://localhost");
  if (url.searchParams.has("access_token") || url.searchParams.has("token")) {
    scope.reqLogs.audit(
      "authentication.token_in_url_rejected",
      "denied",
      {},
      "warn",
    );
    _respond(
      res,
      400,
      JSON.stringify({
        error: "invalid_request",
        error_description:
          "Access tokens must be sent in the Authorization header",
      }),
    );
    return;
  }
  if (url.pathname === "/healthz") {
    _respond(res, 200, '{"status":"ok"}');
    return;
  }
  const webReq = new Request(
    new URL(url.pathname + url.search, ctx.resourceUrl.origin),
    { method: req.method, headers: _headerPairs(req.headers) },
  );
  const meta = ctx.authenticator.metadata(webReq);
  if (meta) {
    await _relay(res, meta);
    return;
  }
  if (url.pathname !== ctx.h.path) {
    _respond(res, 404, '{"error":"not_found"}');
    return;
  }
  await _authenticateAndHandle(ctx, req, res, scope, webReq);
}

/**
 * Apply the Host and Origin checks, auditing a refusal.
 *
 * @private
 */
function _admitted(
  ctx: HttpContext,
  req: http.IncomingMessage,
  res: http.ServerResponse,
  reqLogs: Logs,
): boolean {
  if (ctx.validateHost && !ctx.validateHost(req, res)) {
    reqLogs.audit(
      "transport.host_rejected",
      "denied",
      { httpMethod: req.method, reason: "host_not_allowed" },
      "warn",
    );
    return false;
  }
  if (!ctx.validateOrigin(req, res)) {
    reqLogs.audit(
      "transport.origin_rejected",
      "denied",
      { httpMethod: req.method, reason: "origin_not_allowed" },
      "warn",
    );
    return false;
  }
  return true;
}

/**
 * Authenticate a request to the MCP endpoint and hand it to the MCP
 * handler with its principal.
 *
 * @private
 */
async function _authenticateAndHandle(
  ctx: HttpContext,
  req: http.IncomingMessage,
  res: http.ServerResponse,
  scope: HttpRequestScope,
  webReq: Request,
): Promise<void> {
  const auth = await ctx.authenticator.authenticate(
    webReq,
    scope.reqLogs.child({}),
  );
  if (!auth.ok) {
    await _relay(res, auth.response);
    return;
  }
  (req as http.IncomingMessage & { auth?: unknown }).auth = {
    ...auth.authInfo,
    extra: {
      ...(auth.authInfo.extra ?? {}),
      principal: auth.principal,
      requestId: scope.requestId,
      client: scope.client,
    },
  };
  await ctx.nodeHandler(req as never, res as never);
}

/**
 * Request headers as name/value pairs, one per value.
 *
 * @private
 */
function _headerPairs(
  headers: http.IncomingHttpHeaders,
): Array<[string, string]> {
  return Object.entries(headers).flatMap(([k, v]) =>
    (Array.isArray(v) ? v : [v])
      .filter((x): x is string => x !== undefined)
      .map((x): [string, string] => [k, x]),
  );
}

/**
 * Answer with a JSON body.
 *
 * @private
 */
function _respond(res: http.ServerResponse, status: number, body: string) {
  res.writeHead(status, { "content-type": "application/json" });
  res.end(body);
}

/**
 * Answer with a web Response.
 *
 * @private
 */
async function _relay(res: http.ServerResponse, response: Response) {
  res.writeHead(response.status, Object.fromEntries(response.headers));
  res.end(Buffer.from(await response.arrayBuffer()));
}

import type { IncomingMessage, ServerResponse } from 'node:http';

import { localhostAllowedHostnames, validateHostHeader } from '@modelcontextprotocol/server';

/**
 * Node.js request guard for DNS rebinding protection.
 * Validates the `Host` header hostname (port-agnostic) against an allowed list.
 *
 * Unlike the framework adapters, plain `node:http` has no middleware chain, so
 * the guard returns whether the request may proceed: when it returns `false`
 * it has already answered the request with a `403` JSON-RPC error and the
 * caller must not handle it further.
 *
 * @param allowedHostnames - List of allowed hostnames (without ports).
 *   For IPv6, provide the address with brackets (e.g., `[::1]`).
 *
 * @example
 * ```ts
 * const validateHost = hostHeaderValidation(['localhost', '127.0.0.1', '[::1]']);
 * http.createServer((req, res) => {
 *     if (!validateHost(req, res)) return;
 *     void transport.handleRequest(req, res);
 * });
 * ```
 */
export function hostHeaderValidation(allowedHostnames: string[]): (req: IncomingMessage, res: ServerResponse) => boolean {
    return (req, res) => {
        const result = validateHostHeader(req.headers.host, allowedHostnames);
        if (result.ok) {
            return true;
        }
        res.writeHead(403, { 'Content-Type': 'application/json' });
        res.end(
            JSON.stringify({
                jsonrpc: '2.0',
                error: {
                    code: -32_000,
                    message: result.message
                },
                id: null
            })
        );
        return false;
    };
}

/**
 * Convenience guard for localhost DNS rebinding protection.
 * Allows only `localhost`, `127.0.0.1`, and `[::1]` (IPv6 localhost) hostnames.
 */
export function localhostHostValidation(): (req: IncomingMessage, res: ServerResponse) => boolean {
    return hostHeaderValidation(localhostAllowedHostnames());
}
import type { IncomingMessage, ServerResponse } from 'node:http';

import { localhostAllowedOrigins, validateOriginHeader } from '@modelcontextprotocol/server';

/**
 * Node.js request guard for Origin header validation.
 * Validates the `Origin` header hostname (port-agnostic) against an allowed list.
 *
 * Requests without an `Origin` header pass (non-browser MCP clients do not send
 * one); a present value that is not allowed, or that cannot be parsed, is
 * rejected with `403`. The guard returns whether the request may proceed: when
 * it returns `false` it has already answered the request and the caller must
 * not handle it further.
 *
 * @param allowedOriginHostnames - List of allowed origin hostnames (without scheme or port), or `<scheme>://*` entries.
 *   For IPv6, provide the address with brackets (e.g., `[::1]`).
 *
 * @example
 * ```ts
 * const validateOrigin = originValidation(['localhost', '127.0.0.1', '[::1]']);
 * http.createServer((req, res) => {
 *     if (!validateOrigin(req, res)) return;
 *     void transport.handleRequest(req, res);
 * });
 * ```
 */
export function originValidation(allowedOriginHostnames: string[]): (req: IncomingMessage, res: ServerResponse) => boolean {
    return (req, res) => {
        const result = validateOriginHeader(req.headers.origin, allowedOriginHostnames);
        if (result.ok) {
            return true;
        }
        res.writeHead(403, { 'Content-Type': 'application/json' });
        res.end(
            JSON.stringify({
                jsonrpc: '2.0',
                error: {
                    code: -32_000,
                    message: result.message
                },
                id: null
            })
        );
        return false;
    };
}

/**
 * Convenience guard for localhost Origin validation.
 * Allows only origins whose hostname is `localhost`, `127.0.0.1`, or `[::1]` (IPv6 localhost).
 */
export function localhostOriginValidation(): (req: IncomingMessage, res: ServerResponse) => boolean {
    return originValidation(localhostAllowedOrigins());
}
/**
 * Node.js Streamable HTTP Server Transport
 *
 * This is a thin wrapper around {@linkcode WebStandardStreamableHTTPServerTransport} that provides
 * compatibility with Node.js HTTP server (`IncomingMessage`/`ServerResponse`).
 *
 * For web-standard environments (Cloudflare Workers, Deno, Bun), use {@linkcode WebStandardStreamableHTTPServerTransport} directly.
 */

import type { IncomingMessage, ServerResponse } from 'node:http';

import { getRequestListener } from '@hono/node-server';
import type {
    AuthInfo,
    JSONRPCMessage,
    MessageExtraInfo,
    RequestId,
    ScopeChallengeHandler,
    Transport,
    WebStandardStreamableHTTPServerTransportOptions
} from '@modelcontextprotocol/server';
import { WebStandardStreamableHTTPServerTransport } from '@modelcontextprotocol/server';

/**
 * Configuration options for {@linkcode NodeStreamableHTTPServerTransport}
 *
 * This is an alias for {@linkcode WebStandardStreamableHTTPServerTransportOptions} for backward compatibility.
 */
export type StreamableHTTPServerTransportOptions = WebStandardStreamableHTTPServerTransportOptions;

/**
 * Server transport for Streamable HTTP: this implements the MCP Streamable HTTP transport specification.
 * It supports both SSE streaming and direct HTTP responses.
 *
 * This is a wrapper around {@linkcode WebStandardStreamableHTTPServerTransport} that provides Node.js HTTP compatibility.
 * It uses the `@hono/node-server` library to convert between Node.js HTTP and Web Standard APIs.
 *
 * In stateful mode:
 * - Session ID is generated and included in response headers
 * - Session ID is always included in initialization responses
 * - Requests with invalid session IDs are rejected with `404 Not Found`
 * - Non-initialization requests without a session ID are rejected with `400 Bad Request`
 * - State is maintained in-memory (connections, message history)
 *
 * In stateless mode:
 * - No Session ID is included in any responses
 * - No session validation is performed
 *
 * @example Stateful setup
 * ```ts source="./streamableHttp.examples.ts#NodeStreamableHTTPServerTransport_stateful"
 * const server = new McpServer({ name: 'my-server', version: '1.0.0' });
 *
 * const transport = new NodeStreamableHTTPServerTransport({
 *     sessionIdGenerator: () => randomUUID()
 * });
 *
 * await server.connect(transport);
 * ```
 *
 * @example Stateless setup
 * ```ts source="./streamableHttp.examples.ts#NodeStreamableHTTPServerTransport_stateless"
 * const transport = new NodeStreamableHTTPServerTransport({
 *     sessionIdGenerator: undefined
 * });
 * ```
 *
 * @example Using with a pre-parsed request body (e.g. Express)
 * ```ts source="./streamableHttp.examples.ts#NodeStreamableHTTPServerTransport_express"
 * app.post('/mcp', async (req, res) => {
 *     // Stateless example: create a server and a transport per request.
 *     const server = new McpServer({ name: 'my-server', version: '1.0.0' });
 *     const transport = new NodeStreamableHTTPServerTransport({ sessionIdGenerator: undefined });
 *     await server.connect(transport);
 *     await transport.handleRequest(req, res, req.body);
 * });
 * ```
 */
export class NodeStreamableHTTPServerTransport implements Transport {
    private _webStandardTransport: WebStandardStreamableHTTPServerTransport;
    private _requestListener: ReturnType<typeof getRequestListener>;
    // Store auth and parsedBody per request for passing through to handleRequest
    private _requestContext: WeakMap<Request, { authInfo?: AuthInfo; parsedBody?: unknown }> = new WeakMap();

    constructor(options: StreamableHTTPServerTransportOptions = {}) {
        this._webStandardTransport = new WebStandardStreamableHTTPServerTransport(options);

        // Create a request listener that wraps the web standard transport
        // getRequestListener converts Node.js HTTP to Web Standard and properly handles SSE streaming
        // overrideGlobalObjects: false prevents Hono from overwriting global Response, which would
        // break frameworks like Next.js whose response classes extend the native Response
        this._requestListener = getRequestListener(
            async (webRequest: Request) => {
                // Get context if available (set during handleRequest)
                const context = this._requestContext.get(webRequest);
                return this._webStandardTransport.handleRequest(webRequest, {
                    authInfo: context?.authInfo,
                    parsedBody: context?.parsedBody
                });
            },
            { overrideGlobalObjects: false }
        );
    }

    /**
     * Gets the session ID for this transport instance.
     */
    get sessionId(): string | undefined {
        return this._webStandardTransport.sessionId;
    }

    /**
     * Sets callback for when the transport is closed.
     */
    set onclose(handler: (() => void) | undefined) {
        this._webStandardTransport.onclose = handler;
    }

    get onclose(): (() => void) | undefined {
        return this._webStandardTransport.onclose;
    }

    /**
     * Sets callback for transport errors.
     */
    set onerror(handler: ((error: Error) => void) | undefined) {
        this._webStandardTransport.onerror = handler;
    }

    get onerror(): ((error: Error) => void) | undefined {
        return this._webStandardTransport.onerror;
    }

    /**
     * Sets callback for incoming messages.
     */
    set onmessage(handler: ((message: JSONRPCMessage, extra?: MessageExtraInfo) => void) | undefined) {
        this._webStandardTransport.onmessage = handler;
    }

    get onmessage(): ((message: JSONRPCMessage, extra?: MessageExtraInfo) => void) | undefined {
        return this._webStandardTransport.onmessage;
    }

    /**
     * Starts the transport. This is required by the {@linkcode Transport} interface but is a no-op
     * for the Streamable HTTP transport as connections are managed per-request.
     */
    async start(): Promise<void> {
        return this._webStandardTransport.start();
    }

    /**
     * Closes the transport and all active connections.
     */
    async close(): Promise<void> {
        return this._webStandardTransport.close();
    }

    /**
     * Sends a JSON-RPC message through the transport.
     */
    async send(message: JSONRPCMessage, options?: { relatedRequestId?: RequestId }): Promise<void> {
        return this._webStandardTransport.send(message, options);
    }

    /**
     * Forwards the supported protocol versions to the wrapped Web Standard
     * transport for `MCP-Protocol-Version` header validation. Called by the
     * protocol layer during connect; without this delegation a server's
     * `supportedProtocolVersions` option never reached the Node adapter's
     * header validation.
     */
    setSupportedProtocolVersions(versions: string[]): void {
        this._webStandardTransport.setSupportedProtocolVersions(versions);
    }

    /** Sets the scope challenge resolver used by the wrapped Web Standard transport. */
    setScopeChallengeResolver(resolver: ScopeChallengeHandler): void {
        this._webStandardTransport.setScopeChallengeResolver(resolver);
    }

    /**
     * Handles an incoming HTTP request, whether `GET` or `POST`.
     *
     * This method converts Node.js HTTP objects to Web Standard Request/Response
     * and delegates to the underlying {@linkcode WebStandardStreamableHTTPServerTransport}.
     *
     * @param req - Node.js `IncomingMessage`, optionally with `auth` property from middleware
     * @param res - Node.js `ServerResponse`
     * @param parsedBody - Optional pre-parsed body from body-parser middleware
     */
    async handleRequest(req: IncomingMessage & { auth?: AuthInfo }, res: ServerResponse, parsedBody?: unknown): Promise<void> {
        // Store context for this request to pass through auth and parsedBody
        // We need to intercept the request creation to attach this context
        const authInfo = req.auth;

        // Create a custom handler that includes our context
        // overrideGlobalObjects: false prevents Hono from overwriting global Response, which would
        // break frameworks like Next.js whose response classes extend the native Response
        const handler = getRequestListener(
            async (webRequest: Request) => {
                return this._webStandardTransport.handleRequest(webRequest, {
                    authInfo,
                    parsedBody
                });
            },
            { overrideGlobalObjects: false }
        );

        // Delegate to the request listener which handles all the Node.js <-> Web Standard conversion
        // including proper SSE streaming support
        await handler(req, res);
    }

    /**
     * Close an SSE stream for a specific request, triggering client reconnection.
     * Use this to implement polling behavior during long-running operations -
     * client will reconnect after the retry interval specified in the priming event.
     */
    closeSSEStream(requestId: RequestId): void {
        this._webStandardTransport.closeSSEStream(requestId);
    }

    /**
     * Close the standalone GET SSE stream, triggering client reconnection.
     * Use this to implement polling behavior for server-initiated notifications.
     */
    closeStandaloneSSEStream(): void {
        this._webStandardTransport.closeStandaloneSSEStream();
    }
}
/**
 * `toNodeHandler` — adapt the web-standard {@linkcode McpHttpHandler} returned
 * by `createMcpHandler` to a Node.js `(req, res, parsedBody?)` request handler.
 *
 * The handler itself is web-standards-only (`{ fetch, close, notify, bus }` — the
 * shape Workers/Bun/Deno expect from `export default`). Node frameworks
 * (Express, Fastify, plain `node:http`) wrap it once with this helper:
 *
 * ```ts
 * import { createMcpHandler } from '@modelcontextprotocol/server';
 * import { toNodeHandler } from '@modelcontextprotocol/node';
 *
 * const handler = createMcpHandler(factory);
 * app.all('/mcp', toNodeHandler(handler));
 * // or, when a body parser already consumed the stream:
 * const node = toNodeHandler(handler);
 * app.all('/mcp', (req, res) => void node(req, res, req.body));
 * ```
 *
 * The Node→web `Request` conversion the adapter performs is also exported on
 * its own as {@linkcode toWebRequest}, for hand-wired compositions (for
 * example, routing on `isLegacyRequest`).
 *
 * The Node request/response shapes are duck-typed (kept structural so this
 * module stays free of `node:` imports); the conversion reads `req.auth`
 * (validated authentication info attached by upstream middleware) and forwards
 * it as the handler's pass-through `authInfo`.
 */
import type { AuthInfo, McpHandlerRequestOptions } from '@modelcontextprotocol/server';
import { DEFAULT_MAX_REQUEST_BODY_SIZE } from '@modelcontextprotocol/server';

/**
 * The rejection {@linkcode toWebRequest} produces for a body over the size
 * limit, recognisable by `name` and `status` without matching message text.
 */
class RequestBodyTooLargeError extends Error {
    readonly status = 413;
    constructor(maxBytes: number) {
        super(`Payload Too Large: Request body must not exceed ${maxBytes} bytes`);
        this.name = 'RequestBodyTooLargeError';
    }
}

function resolveMaxRequestBodySize(value: number | undefined): number {
    if (value === undefined) {
        return DEFAULT_MAX_REQUEST_BODY_SIZE;
    }
    if (typeof value !== 'number' || !Number.isFinite(value) || value <= 0) {
        throw new RangeError(`maxRequestBodySize must be a positive number of bytes, got ${String(value)}`);
    }
    return value;
}

/**
 * Minimal duck-typed shape of a Node.js `IncomingMessage` accepted by
 * {@linkcode toNodeHandler}. Kept structural so the adapter stays free of
 * `node:` imports.
 */
export interface NodeIncomingMessageLike extends AsyncIterable<unknown> {
    method?: string;
    url?: string;
    headers: Record<string, string | string[] | undefined>;
    /** Validated authentication info attached by upstream middleware (pass-through). */
    auth?: AuthInfo;
}

/** Minimal duck-typed shape of a Node.js `ServerResponse` accepted by {@linkcode toNodeHandler}. */
export interface NodeServerResponseLike {
    writeHead(statusCode: number, headers?: Record<string, string>): unknown;
    write(chunk: string | Uint8Array): unknown;
    end(chunk?: string | Uint8Array): unknown;
    on(event: string, listener: (...args: unknown[]) => void): unknown;
    destroyed?: boolean;
}

/**
 * The web-standard fetch face of an `McpHttpHandler` (or any
 * fetch-shaped MCP handler) — the only surface {@linkcode toNodeHandler}
 * touches. Accepting the face structurally keeps the adapter usable with
 * hand-wired compositions that route over `isLegacyRequest` and produce a
 * `Response` directly.
 */
export interface FetchLikeMcpHandler {
    fetch: (request: Request, options?: McpHandlerRequestOptions) => Promise<Response>;
}

/**
 * A Node.js `(req, res, parsedBody?)` request handler produced by
 * {@linkcode toNodeHandler}. The third argument is an optional pre-parsed body
 * (`req.body` from `express.json()`); a function third argument (Express's
 * `next` when the handler is mounted as middleware) is ignored.
 */
export type NodeMcpRequestHandler = (req: NodeIncomingMessageLike, res: NodeServerResponseLike, parsedBody?: unknown) => Promise<void>;

/** Options for {@linkcode toNodeHandler}. */
export interface ToNodeHandlerOptions {
    /**
     * Called when the adapter answers `500` because request conversion or
     * `handler.fetch` itself threw (e.g. a closed handler). Restores the
     * observability the removed `.node` face had via the entry's own
     * `onerror` — entry-internal failures are still reported through
     * `handler.fetch` and surface via the entry's `onerror` option as before.
     */
    onerror?: (error: Error) => void;
    /**
     * Upper bound, in bytes, on a request body the adapter buffers from the
     * Node stream (when no `parsedBody` is supplied). A larger body is answered
     * `413` without calling `handler.fetch`. Raise it together with the
     * handler's own `maxRequestBodySize`; the adapter's bound applies first.
     * Must be a positive number.
     * @default 4194304 (4 MiB)
     */
    maxRequestBodySize?: number;
}

/**
 * Adapts a web-standard MCP handler (`handler.fetch`) to a Node.js
 * `(req, res, parsedBody?)` request handler. The returned function converts the
 * Node request to a web-standard `Request`, calls `handler.fetch`, then writes
 * the `Response` back to `res` (honoring write backpressure for streamed SSE
 * responses).
 *
 * `req.auth` is forwarded as the handler's pass-through `authInfo`. A function
 * third argument (Express's `next`) is ignored, never treated as a body.
 *
 * Pass `{ onerror }` to observe the adapter-level error fallback (request
 * conversion / `handler.fetch` throw) before the `500` response is written.
 */
export function toNodeHandler(handler: FetchLikeMcpHandler, opts?: ToNodeHandlerOptions): NodeMcpRequestHandler {
    const maxRequestBodySize = resolveMaxRequestBodySize(opts?.maxRequestBodySize);
    return async (req, res, parsedBody) => {
        // Express passes (req, res, next) when the handler is mounted as a
        // middleware function; a function third argument is `next`, not a body.
        if (typeof parsedBody === 'function') {
            parsedBody = undefined;
        }

        let finished = false;
        const abort = new AbortController();
        res.on('close', () => {
            if (!finished) {
                abort.abort();
            }
        });
        if (res.destroyed === true) {
            abort.abort();
        }

        let response: Response;
        try {
            const request = await toWebRequest(req, parsedBody, { signal: abort.signal, maxRequestBodySize });
            response = await handler.fetch(request, {
                ...(req.auth !== undefined && { authInfo: req.auth }),
                ...(parsedBody !== undefined && { parsedBody })
            });
        } catch (error) {
            if (error instanceof RequestBodyTooLargeError) {
                // A normal answer, not an adapter failure. `connection: close` has
                // an HTTP/1.1 server end the socket after answering instead of
                // idling a connection whose request stream was left partly unread.
                response = Response.json(
                    { jsonrpc: '2.0', error: { code: -32_000, message: error.message }, id: null },
                    { status: 413, headers: { connection: 'close' } }
                );
            } else {
                try {
                    opts?.onerror?.(error instanceof Error ? error : new Error(String(error)));
                } catch {
                    // Reporting must never alter the response.
                }
                response = internalServerErrorResponse(echoableRequestId(parsedBody));
            }
        }

        const headers: Record<string, string> = {};
        for (const [name, value] of response.headers) {
            headers[name] = value;
        }
        res.writeHead(response.status, headers);
        if (response.body === null) {
            finished = true;
            res.end();
            return;
        }
        // Honor write backpressure: when write() reports a full buffer (Node's
        // `false` return), wait for the response to drain before pulling the
        // next chunk. The abort signal (wired to 'close' above, and seeded
        // from `res.destroyed` at entry to cover the pre-registration window
        // when 'close' already fired during async middleware) is the single
        // termination source — racing it against the drain wait means a
        // vanished client cannot park the loop, and breaking out of the async
        // iterator calls return() to cancel the upstream stream.
        let drainResolve: (() => void) | undefined;
        const releaseDrainWait = () => {
            drainResolve?.();
            drainResolve = undefined;
        };
        res.on('drain', releaseDrainWait);
        const closed = new Promise<void>(resolve => {
            abort.signal.addEventListener('abort', () => resolve(), { once: true });
        });
        try {
            for await (const chunk of response.body) {
                if (abort.signal.aborted) {
                    break;
                }
                if (res.write(chunk) === false) {
                    await Promise.race([
                        new Promise<void>(resolve => {
                            drainResolve = resolve;
                        }),
                        closed
                    ]);
                }
            }
        } catch {
            // Stream aborted upstream; the abort signal already cancelled the exchange.
        }
        finished = true;
        res.end();
    };
}

/* ------------------------------------------------------------------------ *
 * Node request conversion — `toWebRequest` (duck-typed; no node: imports)
 * ------------------------------------------------------------------------ */

function singleHeaderValue(value: string | string[] | undefined): string | undefined {
    return Array.isArray(value) ? value[0] : value;
}

/** Options for {@linkcode toWebRequest}. */
export interface ToWebRequestOptions {
    /** An `AbortSignal` to attach to the constructed `Request` (`request.signal`). */
    signal?: AbortSignal;
    /**
     * Upper bound, in bytes, on the body read from the Node stream (when no
     * `parsedBody` is supplied); the returned promise rejects past it with an
     * `Error` whose `name` is `'RequestBodyTooLargeError'` and `status` is `413`.
     * Must be a positive number.
     * @default 4194304 (4 MiB)
     */
    maxRequestBodySize?: number;
}

/**
 * Convert a Node.js `IncomingMessage` (duck-typed — an Express `req` works) to
 * the web-standard `Request` that `handler.fetch()` and `isLegacyRequest()`
 * take. This is the conversion {@linkcode toNodeHandler} performs internally,
 * exported for hand-wired compositions:
 *
 * ```ts
 * const probe = await toWebRequest(req, req.body);
 * await ((await isLegacyRequest(probe)) ? legacy(req, res) : modern(req, res, req.body));
 * ```
 *
 * With no `parsedBody` the Node stream is read to completion (up to
 * `maxRequestBodySize`, 4 MiB by default — a longer body rejects with an error
 * carrying `name: 'RequestBodyTooLargeError'` and `status: 413`) — read the
 * body from the returned `Request` afterwards, not from `req`. When a body
 * parser already consumed the stream (`express.json()`), pass the parsed value
 * as `parsedBody` and nothing is read from `req`.
 */
export async function toWebRequest(req: NodeIncomingMessageLike, parsedBody?: unknown, options?: ToWebRequestOptions): Promise<Request> {
    const maxRequestBodySize = resolveMaxRequestBodySize(options?.maxRequestBodySize);
    const method = (req.method ?? 'GET').toUpperCase();
    // HTTP/2 requests carry their authority as the `:authority` pseudo-header,
    // usually with no `host` entry at all (mirrors Node's `request.authority`).
    const host = singleHeaderValue(req.headers['host']) ?? singleHeaderValue(req.headers[':authority']) ?? 'localhost';
    const url = `http://${host}${req.url ?? '/'}`;

    const headers = new Headers();
    for (const [name, value] of Object.entries(req.headers)) {
        // HTTP/2 pseudo-headers (`:method`, `:path`, `:authority`, …) are
        // connection metadata, not header fields — `Headers` rejects their
        // names, so they are skipped rather than copied.
        if (value === undefined || name.startsWith(':')) {
            continue;
        }
        if (Array.isArray(value)) {
            for (const item of value) {
                headers.append(name, item);
            }
        } else {
            headers.set(name, value);
        }
    }

    // The body is carried as text: MCP request bodies are JSON, and a string
    // body keeps the constructed Request portable across runtime lib versions.
    let body: string | undefined;
    if (method !== 'GET' && method !== 'HEAD') {
        if (parsedBody === undefined) {
            if (Number(singleHeaderValue(req.headers['content-length'])) > maxRequestBodySize) {
                throw new RequestBodyTooLargeError(maxRequestBodySize);
            }
            const decoder = new TextDecoder();
            let collected = '';
            let received = 0;
            for await (const chunk of req) {
                received += typeof chunk === 'string' ? new TextEncoder().encode(chunk).byteLength : (chunk as Uint8Array).byteLength;
                if (received > maxRequestBodySize) {
                    throw new RequestBodyTooLargeError(maxRequestBodySize);
                }
                collected += typeof chunk === 'string' ? chunk : decoder.decode(chunk as Uint8Array, { stream: true });
            }
            collected += decoder.decode();
            if (collected.length > 0) {
                body = collected;
            }
        } else {
            // The caller already consumed and parsed the Node stream (the
            // documented `(req, res, req.body)` mounting behind
            // `express.json()`), so the bytes cannot be re-read. Re-serialize
            // the parsed value so consumers of the forwarded Request — anything
            // on the legacy leg reading `request.json()`/`text()` instead of
            // the pass-through parsedBody — still receive the body, and replace
            // the entity headers that described the original raw bytes.
            const serialized: string | undefined = JSON.stringify(parsedBody);
            headers.delete('content-encoding');
            headers.delete('transfer-encoding');
            if (serialized === undefined) {
                headers.delete('content-length');
            } else {
                body = serialized;
                headers.set('content-length', String(new TextEncoder().encode(serialized).byteLength));
            }
        }
    }

    return new Request(url, {
        method,
        headers,
        ...(options?.signal !== undefined && { signal: options.signal }),
        ...(body !== undefined && { body })
    });
}

/* ------------------------------------------------------------------------ *
 * Adapter-level error fallback (request conversion failure / closed handler)
 * ------------------------------------------------------------------------ */

/**
 * The JSON-RPC id to echo on an adapter-built error response: the body's `id`
 * when the body is a single JSON-RPC request whose id is a string or number,
 * `null` otherwise.
 */
function echoableRequestId(body: unknown): string | number | null {
    if (body === null || typeof body !== 'object' || Array.isArray(body)) {
        return null;
    }
    const { method, id } = body as { method?: unknown; id?: unknown };
    if (typeof method !== 'string') {
        return null;
    }
    return typeof id === 'string' || typeof id === 'number' ? id : null;
}

function internalServerErrorResponse(id: string | number | null): Response {
    return Response.json({ jsonrpc: '2.0', error: { code: -32_603, message: 'Internal server error' }, id }, { status: 500 });
}

/**
 * A single-exchange, per-request HTTP server transport for modern-era
 * (protocol revision 2026-07-28) serving.
 *
 * One transport instance serves exactly one already-classified inbound
 * JSON-RPC message and produces exactly one HTTP `Response`:
 *
 * - a `202` with no body for notifications,
 * - a single JSON body for requests whose handler produces no streamed
 *   output, or
 * - a lazily-opened SSE stream when the handler emits related messages
 *   (notifications or server-to-client requests) before its result — the
 *   stream carries those messages and finally the terminal result, then
 *   closes.
 *
 * The transport is constructed already-classified: the entry parses and
 * classifies the request body exactly once and hands the classification in via
 * the constructor; the transport attaches it (together with the original
 * request and any caller-provided auth info) to every message it delivers, and
 * the protocol layer validates it against the serving instance's negotiated
 * era. `authInfo` is strictly pass-through — it is never derived from the
 * inbound request's headers here.
 *
 * Deliberately NOT carried over from the session-oriented streamable HTTP
 * transport: session ids and session headers, resumability (event ids,
 * priming events, `Last-Event-ID` replay, retry hints), the standalone GET
 * stream, and request-header validation (which belongs to middleware). The
 * exchange is single-use; serving another request requires a new transport
 * (and, in the per-request serving model, a fresh server instance).
 *
 * Consumers wiring this transport into a custom entry (instead of
 * `createMcpHandler`) inherit the spec's per-error HTTP mandate with it: a
 * terminal `MissingRequiredClientCapabilityError` (-32021) MUST answer 400,
 * which this transport applies whenever the response is still uncommitted.
 * A custom entry must also reject POSTs whose Content-Type media type is not
 * `application/json` (415) before parsing the body — use `isJsonContentType`
 * from the package root; this transport never sees the HTTP headers, so it
 * cannot perform that validation itself.
 */
import type {
    AuthInfo,
    JSONRPCMessage,
    JSONRPCNotification,
    JSONRPCRequest,
    MessageClassification,
    MessageExtraInfo,
    RequestId,
    Transport,
    TransportSendOptions
} from '@modelcontextprotocol/core-internal';
import {
    isJSONRPCErrorResponse,
    isJSONRPCRequest,
    isJSONRPCResultResponse,
    LADDER_ERROR_HTTP_STATUS,
    ProtocolErrorCode,
    SdkError,
    SdkErrorCode
} from '@modelcontextprotocol/core-internal';

import { armSseKeepAlive, DEFAULT_SSE_KEEP_ALIVE_MS } from './sseKeepAlive';

/**
 * How the transport shapes its HTTP response for a request:
 *
 * - `auto` (default): answer with a single JSON body unless the handler emits
 *   a related message before its result, in which case the response upgrades
 *   to an SSE stream.
 * - `sse`: always answer handler output over an SSE stream. The stream opens
 *   once the request has passed the pre-dispatch validation gates, so ladder
 *   rejections keep their mapped HTTP status instead of being framed onto a
 *   200 stream.
 * - `json`: never stream; related messages other than the terminal response
 *   are dropped.
 */
export type PerRequestResponseMode = 'auto' | 'sse' | 'json';

/** Constructor options for {@linkcode PerRequestHTTPServerTransport}. */
export interface PerRequestHTTPServerTransportOptions {
    /** The edge classification of the message this transport will serve. */
    classification: MessageClassification;
    /** Response shaping for the exchange; defaults to `auto`. */
    responseMode?: PerRequestResponseMode;
    /** SSE keep-alive interval in milliseconds; defaults to `15000`, `0` disables. */
    keepAliveMs?: number;
}

/** Per-exchange context handed to {@linkcode PerRequestHTTPServerTransport.handleMessage}. */
export interface PerRequestMessageExtra {
    /**
     * The original HTTP request. Used for handler context and, when the
     * runtime provides an abort signal on it, to cancel the exchange when the
     * client disconnects.
     */
    request?: globalThis.Request;
    /**
     * Validated authentication information supplied by the caller. Strictly
     * pass-through: the transport never populates this from request headers.
     */
    authInfo?: AuthInfo;
}

interface DeferredResponse {
    promise: Promise<Response>;
    resolve: (response: Response) => void;
    reject: (error: Error) => void;
    settled: boolean;
}

interface SseSink {
    controller: ReadableStreamDefaultController<Uint8Array>;
    encoder: InstanceType<typeof TextEncoder>;
    closed: boolean;
    keepAliveTimer?: ReturnType<typeof setInterval>;
}

/**
 * The per-request micro-transport: a real, connected `Transport` whose whole
 * lifetime is one HTTP exchange. See the module documentation for the
 * response shapes it produces.
 */
export class PerRequestHTTPServerTransport implements Transport {
    onclose?: () => void;
    onerror?: (error: Error) => void;
    onmessage?: <T extends JSONRPCMessage>(message: T, extra?: MessageExtraInfo) => void;

    private readonly _classification: MessageClassification;
    private readonly _responseMode: PerRequestResponseMode;

    private _started = false;
    private _used = false;
    private _closed = false;
    private _terminalDelivered = false;
    /**
     * `true` only while the inbound message is being delivered synchronously
     * to the connected protocol layer. The pre-handler gates (the era
     * registry gate, the edge→instance handoff check, the missing-handler
     * rejection) answer inside this window; request handlers always run
     * after it (the protocol layer defers them to a microtask). An error
     * sent inside the window is therefore ladder-originated, and an error
     * sent after it is handler-produced.
     */
    private _dispatchWindowOpen = false;
    private _requestId?: RequestId;
    private _deferredResponse?: DeferredResponse;
    private _sse?: SseSink;
    private _abortCleanup?: () => void;
    private readonly _keepAliveMs: number;

    constructor(options: PerRequestHTTPServerTransportOptions) {
        this._classification = options.classification;
        this._responseMode = options.responseMode ?? 'auto';
        this._keepAliveMs = options.keepAliveMs ?? DEFAULT_SSE_KEEP_ALIVE_MS;
    }

    async start(): Promise<void> {
        if (this._started) {
            throw new Error('PerRequestHTTPServerTransport is already started');
        }
        this._started = true;
    }

    /**
     * Serves the single exchange: delivers the classified message to the
     * connected server instance and resolves with the HTTP response.
     *
     * Throws when called a second time (the transport is strictly
     * single-use), or before a server has been connected to the transport.
     * The returned promise rejects with a connection-closed error when the
     * transport is closed before a response was produced (for example because
     * the client disconnected).
     */
    async handleMessage(message: JSONRPCRequest | JSONRPCNotification, extra?: PerRequestMessageExtra): Promise<Response> {
        if (this._used) {
            throw new Error('PerRequestHTTPServerTransport serves exactly one exchange; construct a new transport per request');
        }
        if (!this._started || this.onmessage === undefined) {
            throw new Error('PerRequestHTTPServerTransport is not connected: connect a server to this transport before handling a message');
        }
        if (this._closed) {
            throw new Error('PerRequestHTTPServerTransport is closed');
        }
        this._used = true;

        const signal = extra?.request?.signal;
        if (signal?.aborted) {
            await this.close();
            throw new SdkError(SdkErrorCode.ConnectionClosed, 'The request was aborted before it could be handled');
        }

        // authInfo is strictly pass-through from the caller; it is never
        // derived from the inbound request's headers.
        const messageExtra: MessageExtraInfo = {
            classification: this._classification,
            ...(extra?.request !== undefined && { request: extra.request }),
            ...(extra?.authInfo !== undefined && { authInfo: extra.authInfo })
        };

        if (isJSONRPCRequest(message)) {
            this._requestId = message.id;

            let resolve!: (response: Response) => void;
            let reject!: (error: Error) => void;
            const promise = new Promise<Response>((promiseResolve, promiseReject) => {
                resolve = promiseResolve;
                reject = promiseReject;
            });
            this._deferredResponse = { promise, resolve, reject, settled: false };

            if (signal !== undefined) {
                const onAbort = () => void this.close();
                signal.addEventListener('abort', onAbort, { once: true });
                this._abortCleanup = () => signal.removeEventListener('abort', onAbort);
            }

            this._dispatchWindowOpen = true;
            try {
                this.onmessage(message, messageExtra);
            } finally {
                this._dispatchWindowOpen = false;
            }

            if (this._responseMode === 'sse' && !this._closed && !this._deferredResponse.settled) {
                // Forced-SSE exchanges open their stream as soon as the
                // request has passed the pre-dispatch gates: a ladder
                // rejection settles inside the dispatch window with its
                // mapped HTTP status, while handler output — including
                // comment frames written before the first message — streams
                // as before.
                this.upgradeToSse();
            }
            return promise;
        }

        // Notifications never get a JSON-RPC response: deliver the message and
        // acknowledge the POST with 202 and no body.
        this.onmessage(message, messageExtra);
        return new Response(null, { status: 202 });
    }

    async send(message: JSONRPCMessage, options?: TransportSendOptions): Promise<void> {
        if (this._closed) {
            // The exchange is over; late writes are dropped.
            return;
        }

        const isResponse = isJSONRPCResultResponse(message) || isJSONRPCErrorResponse(message);
        const relatedId = isResponse ? (message as { id: RequestId }).id : options?.relatedRequestId;

        if (this._requestId === undefined || relatedId === undefined || relatedId !== this._requestId) {
            if (isResponse) {
                this.onerror?.(new Error(`Received a response for an unknown request id: ${String((message as { id?: unknown }).id)}`));
            }
            // Messages unrelated to the single in-flight request have nowhere
            // to go on a per-request exchange (there is no session-wide
            // stream); they are dropped.
            return;
        }

        if (isResponse) {
            if (this._terminalDelivered) {
                return;
            }
            this._terminalDelivered = true;

            // The HTTP status is keyed on the error's origin, not on its bare
            // code: only errors produced inside the dispatch window — the
            // validation ladder, the era registry gate and handoff check, a
            // missing handler — are answered with the mapped HTTP status from
            // the ladder table. Handler-produced errors, whatever their code,
            // stay in-band on HTTP 200 — except
            // MissingRequiredClientCapability (-32021), whose 400 the spec
            // mandates per-error with no origin condition and whose only
            // SDK-produced post-window source (the input_required capability
            // gate) cannot fire any earlier — a handler-minted -32021 gets
            // the same 400; a handler RELAYING a downstream peer's
            // -32020/-32022 is not that peer's spec error and stays in-band.
            // Must agree with httpStatusForErrorCode (core-internal), which
            // is deliberately NOT called here: its `?? 400` ladder fallback
            // would wrongly map window codes outside the table.
            // The mapping applies only while no response has been committed:
            // once the stream is open — the handler streamed first, or the
            // exchange is forced-`sse` (which settles its 200 at dispatch
            // end) — the status is on the wire and the error rides the
            // stream. Pre-dispatch ladder rejections always precede the
            // forced-`sse` upgrade, so they keep their mapped status in every
            // response mode.
            const errorCode = isJSONRPCErrorResponse(message) ? message.error.code : undefined;
            const ladderStatus =
                errorCode !== undefined && (this._dispatchWindowOpen || errorCode === ProtocolErrorCode.MissingRequiredClientCapability)
                    ? LADDER_ERROR_HTTP_STATUS[errorCode]
                    : undefined;
            if (ladderStatus !== undefined && this._sse === undefined) {
                this.settleResponse(Response.json(message, { status: ladderStatus, headers: { 'Content-Type': 'application/json' } }));
                queueMicrotask(() => void this.close());
                return;
            }

            if (this._sse !== undefined || this._responseMode === 'sse') {
                // Finalize the stream: serialize the terminal result onto it
                // after everything already enqueued, then close.
                if (this._sse === undefined) {
                    this.upgradeToSse();
                }
                this.writeMessageFrame(message);
                this.finalizeStream();
                return;
            }

            // Single JSON body.
            this.settleResponse(Response.json(message, { status: 200, headers: { 'Content-Type': 'application/json' } }));
            queueMicrotask(() => void this.close());
            return;
        }

        // A message related to the in-flight request that is not its terminal
        // response: a mid-call notification or a server-to-client request
        // emitted by the handler.
        if (this._responseMode === 'json') {
            // JSON responses cannot carry mid-call messages; they are dropped.
            return;
        }
        if (this._sse === undefined) {
            this.upgradeToSse();
        }
        this.writeMessageFrame(message);
    }

    /**
     * Writes an SSE comment frame (a keep-alive heartbeat). Dropped when the
     * exchange is not currently streaming.
     */
    writeCommentFrame(comment: string): void {
        if (this._closed || this._sse === undefined || this._sse.closed) {
            return;
        }
        const frame = comment
            .split('\n')
            .map(line => `: ${line}`)
            .join('\n');
        this.writeFrame(`${frame}\n\n`);
    }

    async close(): Promise<void> {
        if (this._closed) {
            return;
        }
        this._closed = true;

        this._abortCleanup?.();
        this._abortCleanup = undefined;

        if (this._sse?.keepAliveTimer !== undefined) {
            clearInterval(this._sse.keepAliveTimer);
        }
        if (this._sse !== undefined && !this._sse.closed) {
            this._sse.closed = true;
            try {
                this._sse.controller.close();
            } catch {
                // The stream was already closed or cancelled by the consumer.
            }
        }

        if (this._deferredResponse !== undefined && !this._deferredResponse.settled) {
            this._deferredResponse.settled = true;
            this._deferredResponse.reject(new SdkError(SdkErrorCode.ConnectionClosed, 'Connection closed before a response was produced'));
        }

        this.onclose?.();
    }

    private settleResponse(response: Response): void {
        if (this._deferredResponse === undefined || this._deferredResponse.settled) {
            return;
        }
        this._deferredResponse.settled = true;
        this._deferredResponse.resolve(response);
    }

    private upgradeToSse(): void {
        let controller!: ReadableStreamDefaultController<Uint8Array>;
        const readable = new ReadableStream<Uint8Array>({
            start: streamController => {
                controller = streamController;
            },
            cancel: () => {
                // The client went away mid-stream: tear the exchange down,
                // which aborts the in-flight handler through the connected
                // server's close chain.
                void this.close();
            }
        });
        this._sse = { controller, encoder: new TextEncoder(), closed: false };
        this._sse.keepAliveTimer = armSseKeepAlive(this._keepAliveMs, () => this.writeCommentFrame('keepalive'));

        this.settleResponse(
            new Response(readable, {
                status: 200,
                headers: {
                    'Content-Type': 'text/event-stream',
                    'Cache-Control': 'no-cache, no-transform',
                    Connection: 'keep-alive',
                    // Disable proxy buffering so streamed messages are
                    // delivered as they are written.
                    'X-Accel-Buffering': 'no'
                }
            })
        );
    }

    private finalizeStream(): void {
        if (this._sse?.keepAliveTimer !== undefined) {
            clearInterval(this._sse.keepAliveTimer);
        }
        if (this._sse !== undefined && !this._sse.closed) {
            this._sse.closed = true;
            try {
                this._sse.controller.close();
            } catch {
                // The stream was already cancelled by the consumer.
            }
        }
        queueMicrotask(() => void this.close());
    }

    private writeMessageFrame(message: JSONRPCMessage): void {
        this.writeFrame(`event: message\ndata: ${JSON.stringify(message)}\n\n`);
    }

    private writeFrame(frame: string): void {
        if (this._sse === undefined || this._sse.closed) {
            return;
        }
        try {
            this._sse.controller.enqueue(this._sse.encoder.encode(frame));
        } catch (error) {
            this.onerror?.(new Error(`Failed to write to the response stream: ${error}`));
        }
    }
}
