import type { StandardSchemaV1 } from '@modelcontextprotocol/core-internal';

export const COMPLETABLE_SYMBOL: unique symbol = Symbol.for('mcp.completable');

export type CompleteCallback<T extends StandardSchemaV1 = StandardSchemaV1> = (
    value: StandardSchemaV1.InferInput<T>,
    context?: {
        arguments?: Record<string, string>;
    }
) => StandardSchemaV1.InferInput<T>[] | Promise<StandardSchemaV1.InferInput<T>[]>;

export type CompletableMeta<T extends StandardSchemaV1 = StandardSchemaV1> = {
    complete: CompleteCallback<T>;
};

export type CompletableSchema<T extends StandardSchemaV1> = T & {
    [COMPLETABLE_SYMBOL]: CompletableMeta<T>;
};

/**
 * Wraps a schema to provide autocompletion capabilities. Useful for, e.g., prompt arguments in MCP.
 *
 * @example
 * ```ts source="./completable.examples.ts#completable_basicUsage"
 * server.registerPrompt(
 *     'review-code',
 *     {
 *         title: 'Code Review',
 *         argsSchema: z.object({
 *             language: completable(z.string().describe('Programming language'), value =>
 *                 ['typescript', 'javascript', 'python', 'rust', 'go'].filter(lang => lang.startsWith(value))
 *             )
 *         })
 *     },
 *     ({ language }) => ({
 *         messages: [
 *             {
 *                 role: 'user' as const,
 *                 content: {
 *                     type: 'text' as const,
 *                     text: `Review this ${language} code.`
 *                 }
 *             }
 *         ]
 *     })
 * );
 * ```
 *
 * @see {@linkcode server/mcp.McpServer.registerPrompt | McpServer.registerPrompt} for using completable schemas in prompt argument definitions
 */
export function completable<T extends StandardSchemaV1>(schema: T, complete: CompleteCallback<T>): CompletableSchema<T> {
    Object.defineProperty(schema as object, COMPLETABLE_SYMBOL, {
        value: { complete } as CompletableMeta<T>,
        enumerable: false,
        writable: false,
        configurable: false
    });
    return schema as CompletableSchema<T>;
}

/**
 * Checks if a schema is completable (has completion metadata).
 */
export function isCompletable(schema: unknown): schema is CompletableSchema<StandardSchemaV1> {
    return !!schema && typeof schema === 'object' && COMPLETABLE_SYMBOL in (schema as object);
}

/**
 * Gets the completer callback from a completable schema, if it exists.
 */
export function getCompleter<T extends StandardSchemaV1>(schema: T): CompleteCallback<T> | undefined {
    const meta = (schema as unknown as { [COMPLETABLE_SYMBOL]?: CompletableMeta<T> })[COMPLETABLE_SYMBOL];
    return meta?.complete as CompleteCallback<T> | undefined;
}
/** Default interval between SSE keep-alive comment frames. */
export const DEFAULT_SSE_KEEP_ALIVE_MS = 15_000;

const MAX_TIMER_DELAY_MS = 2 ** 31 - 1;

/** Arms an unref'd timer, or disables keep-alive for invalid delays. */
export function armSseKeepAlive(intervalMs: number, onTick: () => void): ReturnType<typeof setInterval> | undefined {
    if (!Number.isFinite(intervalMs) || intervalMs < 1) {
        return undefined;
    }

    const timer = setInterval(onTick, Math.min(intervalMs, MAX_TIMER_DELAY_MS));
    (timer as { unref?: () => void }).unref?.();
    return timer;
}
import type { ServerCapabilities, SubscriptionFilter } from '@modelcontextprotocol/core-internal';

/**
 * A change event a server publishes for delivery on open `subscriptions/listen`
 * streams. Each variant maps onto exactly one notification method:
 *
 * - `tools_list_changed` → `notifications/tools/list_changed`
 * - `prompts_list_changed` → `notifications/prompts/list_changed`
 * - `resources_list_changed` → `notifications/resources/list_changed`
 * - `resource_updated` → `notifications/resources/updated` (carries the URI)
 *
 * The bus carries the EVENT, not the wire shape — the entry's listen router
 * owns subscription-id stamping and per-stream filtering.
 */
export type ServerEvent =
    | { kind: 'tools_list_changed' }
    | { kind: 'prompts_list_changed' }
    | { kind: 'resources_list_changed' }
    | { kind: 'resource_updated'; uri: string };

/**
 * The server-side change-event seam for `subscriptions/listen`.
 *
 * The serving entry (`createMcpHandler`) owns the per-stream listen router:
 * each open `subscriptions/listen` stream registers a listener via
 * `subscribe()`, and consumer code (typically via `handler.notify.*` sugar)
 * publishes change events via `publish()`. In-process servers can use the
 * default {@linkcode InMemoryServerEventBus}; multi-process deployments
 * implement this interface over their own pub/sub.
 *
 * The SDK owns wire semantics (ack-first, filtering, subscription-id
 * stamping, teardown); a `ServerEventBus` only sources the events. It MUST
 * NOT echo back to the listener that published an event when called from
 * inside that listener (no surprise here — the default delivers
 * synchronously and listeners never publish).
 */
export interface ServerEventBus {
    /**
     * Publish a change event to every registered listener.
     */
    publish(event: ServerEvent): void;
    /**
     * Register a listener; returns an idempotent unsubscribe function.
     */
    subscribe(listener: (event: ServerEvent) => void): () => void;
}

/**
 * A `ServerEventBus` backed by an in-process listener set.
 *
 * `publish()` delivers synchronously to the live listener set (a listener
 * unsubscribing itself mid-dispatch is safe; the entry's listen-router
 * listeners never unsubscribe peers). A throwing listener does not stop
 * delivery to the others.
 */
export class InMemoryServerEventBus implements ServerEventBus {
    private readonly _listeners = new Set<(event: ServerEvent) => void>();

    /**
     * @param onerror - Optional callback for errors thrown by listeners
     *   during dispatch.
     */
    constructor(private readonly onerror?: (error: Error) => void) {}

    publish(event: ServerEvent): void {
        for (const listener of this._listeners) {
            try {
                listener(event);
            } catch (error) {
                this.onerror?.(error instanceof Error ? error : new Error(String(error)));
            }
        }
    }

    subscribe(listener: (event: ServerEvent) => void): () => void {
        this._listeners.add(listener);
        let live = true;
        return () => {
            if (!live) return;
            live = false;
            this._listeners.delete(listener);
        };
    }

    /** The number of currently registered listeners (test/introspection only — the routers track capacity via their own open-subscription set). */
    get listenerCount(): number {
        return this._listeners.size;
    }
}

/**
 * Typed publish-side facade over `bus.publish` returned by `createMcpHandler`:
 * each method publishes the corresponding {@linkcode ServerEvent}. Prefer this
 * over calling `bus.publish` directly — the names match the wire methods.
 */
export interface ServerNotifier {
    /** Publish `notifications/tools/list_changed` to every open subscription that opted in. */
    toolsChanged(): void;
    /** Publish `notifications/prompts/list_changed` to every open subscription that opted in. */
    promptsChanged(): void;
    /** Publish `notifications/resources/list_changed` to every open subscription that opted in. */
    resourcesChanged(): void;
    /** Publish `notifications/resources/updated` for `uri` to every open subscription that opted in to that URI. */
    resourceUpdated(uri: string): void;
}

/** Build a {@linkcode ServerNotifier} over a bus. */
export function createServerNotifier(bus: ServerEventBus): ServerNotifier {
    return {
        toolsChanged: () => bus.publish({ kind: 'tools_list_changed' }),
        promptsChanged: () => bus.publish({ kind: 'prompts_list_changed' }),
        resourcesChanged: () => bus.publish({ kind: 'resources_list_changed' }),
        resourceUpdated: (uri: string) => bus.publish({ kind: 'resource_updated', uri })
    };
}

/**
 * Whether a `subscriptions/listen` filter accepts a given change event.
 *
 * Pure: no I/O, no mutation. The filter governs ONLY the four
 * subscription-gated change types — non-gated notifications never reach the
 * bus and are not modeled here.
 *
 * `resource_updated` matches only when `resourceSubscriptions` is present and
 * contains the event's URI exactly (per the spec: "for these resource URIs").
 */
export function listenFilterAccepts(filter: SubscriptionFilter, event: ServerEvent): boolean {
    switch (event.kind) {
        case 'tools_list_changed': {
            return filter.toolsListChanged === true;
        }
        case 'prompts_list_changed': {
            return filter.promptsListChanged === true;
        }
        case 'resources_list_changed': {
            return filter.resourcesListChanged === true;
        }
        case 'resource_updated': {
            return filter.resourceSubscriptions !== undefined && filter.resourceSubscriptions.includes(event.uri);
        }
    }
}

/**
 * The honored subset of a requested filter: keeps only the fields the client
 * explicitly opted in to (drops `false` and absent fields), narrowed against
 * the server's declared capabilities when supplied. The serving entry sends
 * this back in `notifications/subscriptions/acknowledged` so the ack reflects
 * what the server can actually deliver.
 *
 * - `toolsListChanged` is honored only when `capabilities.tools.listChanged`
 *   is advertised; likewise `promptsListChanged` / `resourcesListChanged`.
 * - `resourceSubscriptions` is honored only when
 *   `capabilities.resources.subscribe` is advertised.
 *
 * `capabilities` is optional on this pure helper for test convenience only —
 * both wired routers REQUIRE capabilities at the call site (the HTTP router's
 * `serve()` takes a required parameter; `StdioListenRouter.serve()` throws
 * before `setServerCapabilities()` was called), so the fail-open
 * `undefined → honor everything` branch is never reachable on a wired entry.
 */
export function honoredSubset(requested: SubscriptionFilter, capabilities?: ServerCapabilities): SubscriptionFilter {
    const honored: SubscriptionFilter = {};
    const allow = (bit: unknown): boolean => capabilities === undefined || bit === true;
    if (requested.toolsListChanged === true && allow(capabilities?.tools?.listChanged)) honored.toolsListChanged = true;
    if (requested.promptsListChanged === true && allow(capabilities?.prompts?.listChanged)) honored.promptsListChanged = true;
    if (requested.resourcesListChanged === true && allow(capabilities?.resources?.listChanged)) honored.resourcesListChanged = true;
    if (
        requested.resourceSubscriptions !== undefined &&
        requested.resourceSubscriptions.length > 0 &&
        allow(capabilities?.resources?.subscribe)
    ) {
        honored.resourceSubscriptions = [...requested.resourceSubscriptions];
    }
    return honored;
}

/** Map a {@linkcode ServerEvent} onto its wire notification `{method, params}`. */
export function serverEventToNotification(event: ServerEvent): { method: string; params?: { uri: string } } {
    switch (event.kind) {
        case 'tools_list_changed': {
            return { method: 'notifications/tools/list_changed' };
        }
        case 'prompts_list_changed': {
            return { method: 'notifications/prompts/list_changed' };
        }
        case 'resources_list_changed': {
            return { method: 'notifications/resources/list_changed' };
        }
        case 'resource_updated': {
            return { method: 'notifications/resources/updated', params: { uri: event.uri } };
        }
    }
}
/**
 * The entry-handled `subscriptions/listen` router for the HTTP serving entry.
 *
 * `createMcpHandler` recognizes a modern-classified `subscriptions/listen`
 * request and routes it here: the entry owns ack-first, per-stream filtering,
 * subscription-id stamping, keepalive, capacity guarding, and teardown. The
 * consumer's factory IS constructed for listen, to read the instance's
 * declared `ServerCapabilities` only — the probe instance is never connected
 * and is closed immediately after the capabilities read. Token verification
 * and any per-request authorization still belong at the middleware layer
 * mounted in front of `createMcpHandler` (the entry's documented authz
 * posture).
 *
 * Per the spec at protocol revision 2026-07-28:
 * - The acknowledged notification is the FIRST message on the stream and
 *   carries the honored subset of the requested filter.
 * - Every notification on the stream (including the ack) carries the listen
 *   request's JSON-RPC id under `_meta['io.modelcontextprotocol/subscriptionId']`.
 * - The server MUST NOT deliver a notification type the client did not request.
 * - Server-side graceful close (`closeAll()`) emits the empty
 *   `subscriptions/listen` JSON-RPC result (the `SubscriptionsListenResult` —
 *   `_meta` carries the subscription id) before closing the stream; an abrupt
 *   transport close carries no response and the client treats it as a
 *   disconnect.
 */
import type {
    Implementation,
    JSONRPCRequest,
    RequestId,
    ServerCapabilities,
    SubscriptionFilter
} from '@modelcontextprotocol/core-internal';
import { codecForVersion, MODERN_WIRE_REVISION, SERVER_INFO_META_KEY, SUBSCRIPTION_ID_META_KEY } from '@modelcontextprotocol/core-internal';

import type { ServerEventBus } from './serverEventBus';
import { honoredSubset, listenFilterAccepts, serverEventToNotification } from './serverEventBus';
import { armSseKeepAlive, DEFAULT_SSE_KEEP_ALIVE_MS } from './sseKeepAlive';

/** Default capacity guard: refuse a new subscription when this many are already open. */
export const DEFAULT_MAX_SUBSCRIPTIONS = 1024;

/** Options for {@linkcode createListenRouter}. */
export interface ListenRouterOptions {
    /** The event bus listen streams subscribe to. */
    bus: ServerEventBus;
    /** Reject a new listen with `-32603` when this many subscriptions are already open (default 1024). */
    maxSubscriptions?: number;
    /** SSE comment-frame keepalive interval; `0` disables keepalive (default 15000). */
    keepAliveMs?: number;
    /** Out-of-band error reporting (never alters the response). */
    onerror?: (error: Error) => void;
}

/**
 * A wire-shape notification body (method + loose params).
 * @internal
 */
export interface NotificationBody {
    method: string;
    params: { _meta?: Record<string, unknown>; [key: string]: unknown };
}

function jsonRpcError(id: RequestId | null, code: number, message: string): Response {
    return Response.json({ jsonrpc: '2.0', error: { code, message }, id }, { status: 200 });
}

/** Stamp the subscription id onto a notification's `_meta`. Non-mutating. */
function stampSubscriptionId(
    notification: { method: string; params?: { _meta?: Record<string, unknown>; [key: string]: unknown } },
    subscriptionId: RequestId
): NotificationBody {
    return {
        method: notification.method,
        params: {
            ...notification.params,
            _meta: { ...notification.params?._meta, [SUBSCRIPTION_ID_META_KEY]: subscriptionId }
        }
    };
}

/**
 * Read the requested filter off a `subscriptions/listen` request body.
 * Returns the validated filter, or `undefined` when `params.notifications`
 * is absent or fails the schema (the caller answers `-32602` — the spec
 * marks `notifications` REQUIRED on the listen request).
 */
export function parseListenFilter(message: JSONRPCRequest): SubscriptionFilter | undefined {
    // `subscriptions/listen` is 2026-only vocabulary; route through the era
    // codec's request validator (the wire layer owns the filter schema).
    const outcome = codecForVersion(MODERN_WIRE_REVISION).validateRequest('subscriptions/listen', message);
    return outcome.ok ? outcome.value.params?.notifications : undefined;
}

/**
 * The HTTP listen router: holds the set of open subscriptions and serves
 * each listen request as an SSE response.
 */
export interface ListenRouter {
    /**
     * Serve one `subscriptions/listen` request and return the SSE `Response`
     * (or, on capacity / params rejection, the in-band JSON-RPC error
     * `Response`). The ack notification is the first SSE frame.
     *
     * `capabilities` is required: the acknowledged filter is always narrowed
     * against what the serving instance advertises (honoring a filter without
     * capabilities would fail open and deliver unadvertised types).
     * `serverInfo` is the serving instance's identity, stamped onto the
     * graceful-close result's `_meta` (the spec's `SubscriptionsListenResultMetaObject`
     * extends `ResultMetaObject`, so the serverInfo SHOULD applies there too).
     */
    serve(message: JSONRPCRequest, signal: AbortSignal | undefined, capabilities: ServerCapabilities, serverInfo: Implementation): Response;
    /**
     * Gracefully close every open subscription stream: emits the empty
     * `subscriptions/listen` JSON-RPC result (the spec's graceful-close
     * signal) as the final SSE frame, then closes the stream.
     */
    closeAll(): void;
    /** The number of currently open subscription streams (for tests / introspection). */
    readonly openCount: number;
}

export function createListenRouter(options: ListenRouterOptions): ListenRouter {
    const { bus, onerror } = options;
    const maxSubscriptions = options.maxSubscriptions ?? DEFAULT_MAX_SUBSCRIPTIONS;
    const keepAliveMs = options.keepAliveMs ?? DEFAULT_SSE_KEEP_ALIVE_MS;

    const open = new Set<(graceful: boolean) => void>();

    function serve(
        message: JSONRPCRequest,
        signal: AbortSignal | undefined,
        capabilities: ServerCapabilities,
        serverInfo: Implementation
    ): Response {
        // Capacity guard, pre-ack: in-band -32603 on HTTP 200.
        if (open.size >= maxSubscriptions) {
            onerror?.(new Error(`subscriptions/listen refused: subscription limit reached (${maxSubscriptions})`));
            return jsonRpcError(message.id, -32_603, 'Subscription limit reached');
        }
        const filter = parseListenFilter(message);
        if (filter === undefined) {
            return jsonRpcError(message.id, -32_602, "Invalid params: 'notifications' is required and must be a valid SubscriptionFilter");
        }
        const honored = honoredSubset(filter, capabilities);
        // The spec carries the listen request's JSON-RPC id verbatim as the
        // subscription id; demux is per-connection (each HTTP listen has its
        // own SSE stream) so client-chosen ids cannot route across requests.
        const subscriptionId = message.id;

        const encoder = new TextEncoder();
        let controller!: ReadableStreamDefaultController<Uint8Array>;
        let closed = false;
        let unsubscribe: (() => void) | undefined;
        let keepAliveTimer: ReturnType<typeof setInterval> | undefined;
        let abortCleanup: (() => void) | undefined;

        const writeFrame = (frame: string) => {
            if (closed) return;
            try {
                controller.enqueue(encoder.encode(frame));
            } catch (error) {
                onerror?.(error instanceof Error ? error : new Error(String(error)));
            }
        };
        const writeNotification = (method: string, params: { _meta?: Record<string, unknown>; [key: string]: unknown }) => {
            writeFrame(`event: message\ndata: ${JSON.stringify({ jsonrpc: '2.0', method, params })}\n\n`);
        };

        const teardown = (graceful: boolean) => {
            if (closed) return;
            if (graceful) {
                // Server-side graceful close: emit the empty
                // `subscriptions/listen` JSON-RPC result before closing the
                // stream so the client distinguishes graceful end from a
                // transport drop. Written before `closed = true` so writeFrame
                // still enqueues.
                writeFrame(
                    `event: message\ndata: ${JSON.stringify({
                        jsonrpc: '2.0',
                        id: subscriptionId,
                        result: {
                            resultType: 'complete',
                            _meta: { [SUBSCRIPTION_ID_META_KEY]: subscriptionId, [SERVER_INFO_META_KEY]: serverInfo }
                        }
                    })}\n\n`
                );
            }
            closed = true;
            try {
                unsubscribe?.();
            } catch (error) {
                onerror?.(error instanceof Error ? error : new Error(String(error)));
            }
            if (keepAliveTimer !== undefined) clearInterval(keepAliveTimer);
            abortCleanup?.();
            open.delete(teardown);
            try {
                controller.close();
            } catch {
                // Already closed/cancelled by the consumer.
            }
        };

        const readable = new ReadableStream<Uint8Array>({
            start(streamController) {
                controller = streamController;

                // Ack-first MUST: the acknowledged notification is the first
                // frame on the stream, stamped with the subscription id.
                const ack = stampSubscriptionId(
                    { method: 'notifications/subscriptions/acknowledged', params: { notifications: honored } },
                    subscriptionId
                );
                writeNotification(ack.method, ack.params);

                // Nothing honored means nothing can ever be delivered: complete the subscription instead of holding the stream.
                if (Object.keys(honored).length === 0) {
                    teardown(true);
                    return;
                }

                // Only after the ack frame is enqueued does delivery activate.
                unsubscribe = bus.subscribe(event => {
                    if (closed || !listenFilterAccepts(honored, event)) return;
                    const note = stampSubscriptionId(serverEventToNotification(event), subscriptionId);
                    writeNotification(note.method, note.params);
                });

                keepAliveTimer = armSseKeepAlive(keepAliveMs, () => writeFrame(': keepalive\n\n'));

                open.add(teardown);
            },
            cancel() {
                // The client closed the SSE stream — the spec's HTTP cancel
                // signal. Not a server-side graceful close, so no listen
                // result is written (and the consumer is gone anyway).
                teardown(false);
            }
        });

        if (signal !== undefined) {
            if (signal.aborted) {
                teardown(false);
            } else {
                const onAbort = () => teardown(false);
                signal.addEventListener('abort', onAbort, { once: true });
                abortCleanup = () => signal.removeEventListener('abort', onAbort);
            }
        }

        return new Response(readable, {
            status: 200,
            headers: {
                'Content-Type': 'text/event-stream',
                'Cache-Control': 'no-cache, no-transform',
                Connection: 'keep-alive',
                'X-Accel-Buffering': 'no'
            }
        });
    }

    return {
        serve,
        closeAll() {
            for (const teardown of open) teardown(true);
        },
        get openCount() {
            return open.size;
        }
    };
}

/* ------------------------------------------------------------------------ *
 * Stdio listen router
 * ------------------------------------------------------------------------ */

/** A graceful-close `subscriptions/listen` result frame emitted by {@linkcode StdioListenRouter.teardownAll}. */
export interface ListenCloseFrame {
    jsonrpc: '2.0';
    id: RequestId;
    result: {
        resultType: 'complete';
        _meta: { [SUBSCRIPTION_ID_META_KEY]: RequestId; [SERVER_INFO_META_KEY]?: Implementation };
    };
}

const CHANGE_NOTIFICATION_METHODS: ReadonlySet<string> = new Set([
    'notifications/tools/list_changed',
    'notifications/prompts/list_changed',
    'notifications/resources/list_changed',
    'notifications/resources/updated'
]);

/**
 * Per-connection listen state for the stdio entry. One instance is held by
 * `serveStdio` for the connection lifetime; it routes inbound
 * `subscriptions/listen` / `notifications/cancelled` and rewrites outbound
 * change notifications onto the active subscriptions. No bus — the long-lived
 * pinned instance's existing `send*ListChanged()` calls feed straight into
 * `routeOutbound()`.
 */
export class StdioListenRouter {
    /** Active subscriptions, keyed by the listen request's JSON-RPC id verbatim. */
    private readonly _subs = new Map<RequestId, SubscriptionFilter>();
    /**
     * The serving instance's declared capabilities. Filled in by the entry
     * once the modern instance is constructed (the router is created before
     * the instance exists), so the acknowledged filter is narrowed against
     * what the server can actually deliver.
     */
    private _serverCapabilities: ServerCapabilities | undefined;
    /**
     * The serving instance's identity, stamped onto the graceful-close
     * results' `_meta` (the spec's `SubscriptionsListenResultMetaObject` extends
     * `ResultMetaObject`). Handed over together with the capabilities.
     */
    private _serverInfo: Implementation | undefined;

    constructor(
        private readonly _maxSubscriptions: number = DEFAULT_MAX_SUBSCRIPTIONS,
        serverCapabilities?: ServerCapabilities,
        serverInfo?: Implementation
    ) {
        this._serverCapabilities = serverCapabilities;
        this._serverInfo = serverInfo;
    }

    /**
     * Record the serving instance's declared capabilities and identity once
     * it has been constructed. Called by `serveStdio`'s connect path;
     * subsequent `serve()` calls narrow the honored filter against the
     * capabilities, and `teardownAll()` stamps the identity.
     */
    setServerCapabilities(capabilities: ServerCapabilities, serverInfo?: Implementation): void {
        this._serverCapabilities = capabilities;
        if (serverInfo !== undefined) this._serverInfo = serverInfo;
    }

    /** Whether `id` is an active listen subscription on this connection. */
    has(id: RequestId): boolean {
        return this._subs.has(id);
    }

    /**
     * Serve one inbound `subscriptions/listen` request: registers the
     * subscription and returns the stamped acknowledged notification (or, on
     * capacity / params rejection, the in-band JSON-RPC error response).
     *
     * @throws when called before {@linkcode setServerCapabilities} (or the
     * constructor) has supplied the serving instance's capabilities. Honoring a
     * filter without knowing the server's advertised capabilities would fail
     * open (deliver unadvertised types); the entry guarantees capabilities are
     * set before any listen request is routed here.
     */
    serve(message: JSONRPCRequest): NotificationBody | { jsonrpc: '2.0'; id: RequestId; error: { code: number; message: string } } {
        if (this._serverCapabilities === undefined) {
            throw new Error(
                'StdioListenRouter.serve() called before setServerCapabilities(); refusing to honor a filter without capabilities'
            );
        }
        if (this._subs.size >= this._maxSubscriptions) {
            return { jsonrpc: '2.0', id: message.id, error: { code: -32_603, message: 'Subscription limit reached' } };
        }
        const filter = parseListenFilter(message);
        if (filter === undefined) {
            return {
                jsonrpc: '2.0',
                id: message.id,
                error: { code: -32_602, message: "Invalid params: 'notifications' is required and must be a valid SubscriptionFilter" }
            };
        }
        const honored = honoredSubset(filter, this._serverCapabilities);
        this._subs.set(message.id, honored);
        return stampSubscriptionId({ method: 'notifications/subscriptions/acknowledged', params: { notifications: honored } }, message.id);
    }

    /**
     * Tear down one subscription (inbound `notifications/cancelled`). Returns
     * `true` when a subscription was removed. After this call NOTHING further
     * is delivered for that subscription id (the post-cancel hardening).
     */
    cancel(id: RequestId): boolean {
        return this._subs.delete(id);
    }

    /**
     * Route an outbound notification through the active subscriptions.
     *
     * - For a subscription-gated change notification, returns one stamped copy
     *   per subscription that opted in to it (an empty array means it is
     *   dropped — the modern era never delivers an un-requested change type).
     * - For any other outbound message, returns `'passthrough'` (the entry
     *   forwards it as-is).
     */
    routeOutbound(message: { method: string; params?: { [key: string]: unknown } }): NotificationBody[] | 'passthrough' {
        if (!CHANGE_NOTIFICATION_METHODS.has(message.method)) {
            return 'passthrough';
        }
        const uriParam: unknown = message.params?.['uri'];
        const uri = typeof uriParam === 'string' ? uriParam : undefined;
        const event = notificationToServerEvent(message.method, uri);
        const out: NotificationBody[] = [];
        for (const [subscriptionId, filter] of this._subs) {
            if (listenFilterAccepts(filter, event)) {
                out.push(stampSubscriptionId({ method: message.method, params: message.params ?? {} }, subscriptionId));
            }
        }
        return out;
    }

    /**
     * Server-side graceful teardown of every active subscription: returns the
     * empty `subscriptions/listen` JSON-RPC result for each subscription id —
     * the spec's graceful-close signal, `_meta` carrying the subscription id
     * and the serving instance's identity — for the entry to emit before
     * closing the wire. Clears the set so nothing further is delivered.
     */
    teardownAll(): ListenCloseFrame[] {
        const out: ListenCloseFrame[] = [];
        for (const id of this._subs.keys()) {
            out.push({
                jsonrpc: '2.0',
                id,
                result: {
                    resultType: 'complete',
                    _meta: {
                        [SUBSCRIPTION_ID_META_KEY]: id,
                        ...(this._serverInfo !== undefined && { [SERVER_INFO_META_KEY]: this._serverInfo })
                    }
                }
            });
        }
        this._subs.clear();
        return out;
    }
}

function notificationToServerEvent(method: string, uri: string | undefined): import('./serverEventBus').ServerEvent {
    switch (method) {
        case 'notifications/tools/list_changed': {
            return { kind: 'tools_list_changed' };
        }
        case 'notifications/prompts/list_changed': {
            return { kind: 'prompts_list_changed' };
        }
        case 'notifications/resources/list_changed': {
            return { kind: 'resources_list_changed' };
        }
        default: {
            return { kind: 'resource_updated', uri: uri ?? '' };
        }
    }
}
import type { AuthInfo } from '@modelcontextprotocol/core-internal';
import { OAuthError, OAuthErrorCode } from '@modelcontextprotocol/core-internal';

/**
 * Minimal token-verifier interface for MCP servers acting as an OAuth 2.0
 * Resource Server. Implementations introspect or locally validate an access
 * token and return the resulting {@link AuthInfo}, which the serving entry
 * surfaces to MCP request handlers via `ctx.http.authInfo`.
 *
 * This is intentionally narrower than a full OAuth Authorization Server
 * provider — it only covers the verification step a Resource Server needs.
 */
export interface OAuthTokenVerifier {
    /**
     * Verifies an access token and returns information about it.
     *
     * Implementations should throw an {@link OAuthError} with
     * `OAuthErrorCode.InvalidToken` when the token is unknown, revoked, or
     * otherwise invalid; the bearer-auth helpers map that to a `401` with a
     * `WWW-Authenticate` challenge.
     *
     * Note: bearer-auth verification rejects tokens whose
     * `AuthInfo.expiresAt` is unset (matches v1 behavior). Ensure your
     * verifier populates it (e.g. from RFC 7662 introspection `exp` or the
     * JWT `exp` claim).
     */
    verifyAccessToken(token: string): Promise<AuthInfo>;
}

/**
 * Options for {@link verifyBearerToken}, {@link requireBearerAuth}, and
 * {@link bearerAuthChallengeResponse}.
 */
export interface BearerAuthOptions {
    /**
     * A verifier used to validate access tokens.
     */
    verifier: OAuthTokenVerifier;

    /**
     * Optional scopes that the token must have. When any are missing the
     * request is refused with `403 insufficient_scope`.
     */
    requiredScopes?: string[];

    /**
     * Optional Protected Resource Metadata URL to advertise in the
     * `WWW-Authenticate` header on 401/403 responses, per
     * {@link https://datatracker.ietf.org/doc/html/rfc9728 | RFC 9728}.
     *
     * Typically built with `getOAuthProtectedResourceMetadataUrl`, exported
     * from this package.
     *
     * When verification succeeds the value is also stamped onto the returned
     * {@link AuthInfo} (`authInfo.resourceMetadataUrl`, unless the verifier
     * already set one), so challenges built after authentication — such as
     * per-operation `insufficient_scope` scope challenges — advertise the
     * same document without being configured separately.
     */
    resourceMetadataUrl?: string;
}

/**
 * Options for {@link verifyBearerToken} and {@link requireBearerAuth}:
 * {@link BearerAuthOptions} plus `expectedResource`.
 */
export interface VerifyBearerTokenOptions extends BearerAuthOptions {
    /**
     * Accept only tokens issued for this resource (the token's audience):
     * the value your authorization server puts into tokens meant for this
     * server, usually the server's URL (its
     * {@link https://datatracker.ietf.org/doc/html/rfc8707 | RFC 8707}
     * resource identifier).
     *
     * When set, a token is accepted only if the verifier reports that value
     * in `AuthInfo.resource`. The two are compared as strings, ignoring a
     * fragment and one trailing slash. A token reported for another value, or
     * for none, is refused with `401 invalid_token`, so the verifier has to
     * fill `AuthInfo.resource`, for example from the token's `aud` claim.
     * When unset, `AuthInfo.resource` is not compared with anything.
     */
    expectedResource?: URL;
}

// The serialized value without its fragment and without one trailing slash.
function comparableResource(value: URL): string {
    const text = String(value);
    const hash = text.indexOf('#');
    return (hash === -1 ? text : text.slice(0, hash)).replace(/\/$/, '');
}

// A reported resource matches when it serializes to the same string as the expected one, fragment and one trailing slash aside.
function sameResource(reported: URL | undefined, expected: URL): boolean {
    if (!reported) return false;
    return comparableResource(reported) === comparableResource(expected);
}

function headerQuotedValue(value: string): string {
    // HTTP quoted-string per RFC 7235: escape backslash and double quote, and
    // replace characters a header cannot carry (controls, anything beyond
    // printable ASCII) so a verifier-authored message can never make the
    // challenge Response constructor throw.
    return value.replaceAll(/[\\"]/g, String.raw`\$&`).replaceAll(/[^\u0020-\u007E]/g, ' ');
}

/**
 * Build a `WWW-Authenticate: Bearer …` challenge header value (RFC 6750).
 *
 * The single formatter behind every challenge this package emits — the
 * bearer-auth 401/403 answers and the per-operation scope-challenge 403 — so
 * all challenges from one server agree on parameter order and quoting. Every
 * parameter value is emitted as an HTTP quoted-string with `\` and `"`
 * escaped and non-printable characters replaced.
 */
export function buildWwwAuthenticateHeader(
    errorCode: string,
    description: string,
    requiredScopes: readonly string[],
    resourceMetadataUrl: string | undefined
): string {
    let header = `Bearer error="${headerQuotedValue(errorCode)}", error_description="${headerQuotedValue(description)}"`;
    if (requiredScopes.length > 0) {
        header += `, scope="${headerQuotedValue(requiredScopes.join(' '))}"`;
    }
    if (resourceMetadataUrl) {
        header += `, resource_metadata="${headerQuotedValue(resourceMetadataUrl)}"`;
    }
    return header;
}

/**
 * Validate a raw `Authorization` header value as a Bearer token and return
 * the verified {@link AuthInfo}.
 *
 * The runtime-neutral core of Bearer authentication: it parses the header,
 * runs the verifier, compares the token's resource with `expectedResource`,
 * enforces `requiredScopes`, and rejects tokens without an
 * expiration or past it. On any failure it throws an {@link OAuthError} —
 * pass that to {@link bearerAuthChallengeResponse} for the matching HTTP
 * answer, or use {@link requireBearerAuth} to get both steps as one call.
 *
 * Framework adapters build on this: `requireBearerAuth` from
 * `@modelcontextprotocol/express` feeds it `req.headers.authorization`.
 */
export async function verifyBearerToken(
    authorizationHeader: string | null | undefined,
    options: VerifyBearerTokenOptions
): Promise<AuthInfo> {
    const { verifier, requiredScopes = [], expectedResource } = options;

    if (!authorizationHeader) {
        throw new OAuthError(OAuthErrorCode.InvalidToken, 'Missing Authorization header');
    }

    const [type, token] = authorizationHeader.split(' ');
    if (type?.toLowerCase() !== 'bearer' || !token) {
        throw new OAuthError(OAuthErrorCode.InvalidToken, "Invalid Authorization header format, expected 'Bearer TOKEN'");
    }

    const authInfo = await verifier.verifyAccessToken(token);

    // Check if the token was issued for this server (if configured)
    if (expectedResource !== undefined && !sameResource(authInfo.resource, expectedResource)) {
        throw new OAuthError(OAuthErrorCode.InvalidToken, 'Token was not issued for this resource');
    }

    // Check if token has the required scopes (if any)
    if (requiredScopes.length > 0) {
        const hasAllScopes = requiredScopes.every(scope => authInfo.scopes.includes(scope));
        if (!hasAllScopes) {
            throw new OAuthError(OAuthErrorCode.InsufficientScope, 'Insufficient scope');
        }
    }

    // Check if the token is set to expire or if it is expired
    if (typeof authInfo.expiresAt !== 'number' || Number.isNaN(authInfo.expiresAt)) {
        throw new OAuthError(OAuthErrorCode.InvalidToken, 'Token has no expiration time');
    } else if (authInfo.expiresAt < Date.now() / 1000) {
        throw new OAuthError(OAuthErrorCode.InvalidToken, 'Token has expired');
    }

    // Hand the gate's discovery configuration inward with the verified token,
    // so challenges built after authentication (per-operation scope
    // challenges) advertise the same metadata document. A verifier-set value
    // wins over the gate's configuration.
    if (options.resourceMetadataUrl !== undefined && authInfo.resourceMetadataUrl === undefined) {
        return { ...authInfo, resourceMetadataUrl: options.resourceMetadataUrl };
    }

    return authInfo;
}

/**
 * Build the HTTP answer for a Bearer authentication failure.
 *
 * Maps an {@link OAuthError} to its status — `401` for `invalid_token` and
 * `403` for `insufficient_scope` (both carrying the `WWW-Authenticate: Bearer …`
 * challenge, with `resource_metadata` when configured so clients can discover
 * the Authorization Server), `500` for `server_error`, `400` for anything
 * else. A non-`OAuthError` value answers `500 server_error`. The body is the
 * OAuth error JSON.
 */
export function bearerAuthChallengeResponse(
    error: unknown,
    options?: Pick<BearerAuthOptions, 'requiredScopes' | 'resourceMetadataUrl'>
): Response {
    const { requiredScopes = [], resourceMetadataUrl } = options ?? {};

    if (!(error instanceof OAuthError)) {
        const serverError = new OAuthError(OAuthErrorCode.ServerError, 'Internal Server Error');
        return Response.json(serverError.toResponseObject(), { status: 500 });
    }

    switch (error.code) {
        case OAuthErrorCode.InvalidToken: {
            const challenge = buildWwwAuthenticateHeader(error.code, error.message, requiredScopes, resourceMetadataUrl);
            return Response.json(error.toResponseObject(), { status: 401, headers: { 'WWW-Authenticate': challenge } });
        }
        case OAuthErrorCode.InsufficientScope: {
            const challenge = buildWwwAuthenticateHeader(error.code, error.message, requiredScopes, resourceMetadataUrl);
            return Response.json(error.toResponseObject(), { status: 403, headers: { 'WWW-Authenticate': challenge } });
        }
        case OAuthErrorCode.ServerError: {
            return Response.json(error.toResponseObject(), { status: 500 });
        }
        default: {
            return Response.json(error.toResponseObject(), { status: 400 });
        }
    }
}

/**
 * Require a valid Bearer token on web-standard requests.
 *
 * The framework-free counterpart of `requireBearerAuth` from
 * `@modelcontextprotocol/express`, for hosts whose HTTP surface is a
 * `fetch(request)` handler — Cloudflare Workers, Deno, Bun, Hono. The
 * returned gate resolves to the verified {@link AuthInfo}, or to the
 * ready-to-return challenge `Response` when the request must be refused.
 *
 * @example
 * ```ts source="./bearerAuth.examples.ts#requireBearerAuth_fetchGate"
 * const gate = requireBearerAuth({ verifier, requiredScopes: ['mcp'] });
 *
 * async function fetchHandler(request: Request): Promise<Response> {
 *     const auth: AuthInfo | Response = await gate(request);
 *     if (auth instanceof Response) return auth;
 *     return handler.fetch(request, { authInfo: auth });
 * }
 * ```
 */
export function requireBearerAuth(options: VerifyBearerTokenOptions): (request: Request) => Promise<AuthInfo | Response> {
    // Destructure at creation so a plain-JS caller passing undefined or
    // malformed options crashes at startup, not on the first request.
    const { verifier, requiredScopes = [], resourceMetadataUrl, expectedResource } = options;
    const resolved = { verifier, requiredScopes, resourceMetadataUrl, expectedResource };
    return async request => {
        // Outside the try: a wrong-framework misuse (no web-standard Request)
        // should throw loudly, not surface as a 500 challenge. Fetch's
        // Headers.get comma-joins repeated headers where Node keeps the
        // first; take the first segment so both adapters agree (the token68
        // alphabet has no comma, so this is lossless).
        const [authorizationHeader] = (request.headers.get('authorization') ?? '').split(',');
        try {
            return await verifyBearerToken(authorizationHeader || undefined, resolved);
        } catch (error) {
            return bearerAuthChallengeResponse(error, resolved);
        }
    };
}
import type { OAuthMetadata, OAuthProtectedResourceMetadata } from '@modelcontextprotocol/core-internal';
import { OAuthError, OAuthErrorCode } from '@modelcontextprotocol/core-internal';

/**
 * Options for {@link oauthMetadataResponse} and
 * {@link buildOAuthProtectedResourceMetadata}.
 */
export interface AuthMetadataOptions {
    /**
     * Authorization Server metadata (RFC 8414) for the AS this MCP server
     * relies on. Served at `/.well-known/oauth-authorization-server` so
     * legacy clients that probe the resource origin still discover the AS.
     */
    oauthMetadata: OAuthMetadata;

    /**
     * The public URL of this MCP server, used as the `resource` value in the
     * Protected Resource Metadata document. Any path component is reflected
     * in the well-known route per RFC 9728.
     */
    resourceServerUrl: URL;

    /**
     * Optional documentation URL advertised as `resource_documentation`.
     */
    serviceDocumentationUrl?: URL;

    /**
     * Optional list of scopes this MCP server understands, advertised as
     * `scopes_supported`.
     */
    scopesSupported?: string[];

    /**
     * Optional human-readable name advertised as `resource_name`.
     */
    resourceName?: string;

    /**
     * Allow a non-HTTPS issuer URL. Local testing only — never enable in
     * production. The Express adapter maps its
     * `MCP_DANGEROUSLY_ALLOW_INSECURE_ISSUER_URL` environment variable here.
     */
    dangerouslyAllowInsecureIssuerUrl?: boolean;
}

function checkIssuerUrl(issuer: URL, allowInsecure: boolean | undefined): void {
    // RFC 8414 technically does not permit a localhost HTTPS exemption, but it is necessary for local testing.
    if (issuer.protocol !== 'https:' && issuer.hostname !== 'localhost' && issuer.hostname !== '127.0.0.1' && !allowInsecure) {
        throw new Error('Issuer URL must be HTTPS');
    }
    if (issuer.hash) {
        throw new Error(`Issuer URL must not have a fragment: ${issuer}`);
    }
    if (issuer.search) {
        throw new Error(`Issuer URL must not have a query string: ${issuer}`);
    }
}

/**
 * Derive the RFC 9728 Protected Resource Metadata document from
 * {@link AuthMetadataOptions}, validating the Authorization Server issuer URL
 * (HTTPS required outside localhost) in the process.
 *
 * `oauthMetadataResponse` and the Express `mcpAuthMetadataRouter` both build
 * on this; use it directly when serving the document through your own
 * routing — or call it once at startup to fail fast on a misconfigured
 * issuer before any request arrives.
 */
export function buildOAuthProtectedResourceMetadata(options: AuthMetadataOptions): OAuthProtectedResourceMetadata {
    checkIssuerUrl(new URL(options.oauthMetadata.issuer), options.dangerouslyAllowInsecureIssuerUrl);
    return {
        resource: options.resourceServerUrl.href,
        authorization_servers: [options.oauthMetadata.issuer],
        scopes_supported: options.scopesSupported,
        resource_name: options.resourceName,
        resource_documentation: options.serviceDocumentationUrl?.href
    };
}

/**
 * Builds the RFC 9728 Protected Resource Metadata URL for a given MCP server
 * URL by inserting `/.well-known/oauth-protected-resource` ahead of the path.
 *
 * @example
 * ```ts
 * getOAuthProtectedResourceMetadataUrl(new URL('https://api.example.com/mcp'))
 * // → 'https://api.example.com/.well-known/oauth-protected-resource/mcp'
 * ```
 */
export function getOAuthProtectedResourceMetadataUrl(serverUrl: URL): string {
    const metadataUrl = new URL(serverUrl);
    metadataUrl.pathname = protectedResourceMetadataPath(serverUrl);
    metadataUrl.hash = '';
    return metadataUrl.href;
}

/** The RFC 9728 path-aware well-known path for a resource URL. */
function protectedResourceMetadataPath(resourceServerUrl: URL): string {
    // Normalized like the request path in `oauthMetadataResponse`: a resource
    // URL with a trailing slash must not make its own PRM route unreachable.
    const rsPath = stripTrailingSlash(resourceServerUrl.pathname);
    return `/.well-known/oauth-protected-resource${rsPath === '/' ? '' : rsPath}`;
}

function stripTrailingSlash(path: string): string {
    return path.length > 1 && path.endsWith('/') ? path.slice(0, -1) : path;
}

const ALLOWED_METHODS = 'GET, HEAD, OPTIONS';

function metadataDocumentResponse(request: Request, metadata: OAuthMetadata | OAuthProtectedResourceMetadata): Response {
    // Metadata documents must be fetchable from web-based MCP clients on any
    // origin, so every response carries permissive CORS headers.
    if (request.method === 'OPTIONS') {
        const requestedHeaders = request.headers.get('access-control-request-headers');
        return new Response(null, {
            status: 204,
            headers: {
                'Access-Control-Allow-Origin': '*',
                'Access-Control-Allow-Methods': ALLOWED_METHODS,
                // The reflected allow-list makes the response vary by request:
                // without this a shared cache would replay one preflight's
                // allow-list against another's headers.
                ...(requestedHeaders === null
                    ? {}
                    : { 'Access-Control-Allow-Headers': requestedHeaders, Vary: 'Access-Control-Request-Headers' })
            }
        });
    }
    if (request.method !== 'GET' && request.method !== 'HEAD') {
        const error = new OAuthError(OAuthErrorCode.MethodNotAllowed, `The method ${request.method} is not allowed for this endpoint`);
        return Response.json(error.toResponseObject(), {
            status: 405,
            headers: { Allow: ALLOWED_METHODS, 'Access-Control-Allow-Origin': '*' }
        });
    }
    const response = Response.json(metadata, { headers: { 'Access-Control-Allow-Origin': '*' } });
    // RFC 9110: HEAD is GET without the body, same headers.
    return request.method === 'HEAD' ? new Response(null, { status: response.status, headers: response.headers }) : response;
}

/**
 * Serve the two OAuth discovery documents an MCP server acting as a Resource
 * Server exposes, from a web-standard `fetch(request)` handler:
 *
 *  - `/.well-known/oauth-protected-resource[/<path>]` — RFC 9728 Protected
 *    Resource Metadata, derived from the supplied options (path-aware: the
 *    resource URL's path is reflected in the route).
 *  - `/.well-known/oauth-authorization-server` — RFC 8414 Authorization
 *    Server Metadata, passed through verbatim.
 *
 * Returns the matched document `Response` (JSON with permissive CORS, `405`
 * with an `Allow` header for non-GET methods, `204` for CORS preflight), or
 * `undefined` when the request path is neither well-known route — fall
 * through to your own routing. The framework-free counterpart of
 * `mcpAuthMetadataRouter` from `@modelcontextprotocol/express`; pair it with
 * `requireBearerAuth` and `getOAuthProtectedResourceMetadataUrl` so
 * unauthenticated clients can discover the AS from the `401` challenge.
 *
 * @example
 * ```ts source="./oauthMetadata.examples.ts#oauthMetadataResponse_fetchHandler"
 * async function fetchHandler(request: Request): Promise<Response> {
 *     return oauthMetadataResponse(request, options) ?? serveMcp(request);
 * }
 * ```
 */
export function oauthMetadataResponse(request: Request, options: AuthMetadataOptions): Response | undefined {
    // Match before building: unmatched traffic must fall through untouched,
    // even when the options are misconfigured — a bad issuer surfaces on the
    // discovery routes (or at startup via buildOAuthProtectedResourceMetadata),
    // never on the host's own traffic.
    // Tolerate a single trailing slash, as path-mounted routers do.
    const requestPath = stripTrailingSlash(new URL(request.url).pathname);
    if (requestPath === protectedResourceMetadataPath(options.resourceServerUrl)) {
        return metadataDocumentResponse(request, buildOAuthProtectedResourceMetadata(options));
    }
    if (requestPath === '/.well-known/oauth-authorization-server') {
        buildOAuthProtectedResourceMetadata(options); // issuer validation
        return metadataDocumentResponse(request, options.oauthMetadata);
    }
    return undefined;
}
import type { AuthInfo, JSONRPCRequest } from '@modelcontextprotocol/core-internal';
import { OAuthError, OAuthErrorCode } from '@modelcontextprotocol/core-internal';

import { bearerAuthChallengeResponse } from './middleware/bearerAuth';
import { getOAuthProtectedResourceMetadataUrl } from './middleware/oauthMetadata';

/** OAuth scopes to request before handling an MCP request. */
export interface ScopeChallenge {
    /** The exact, complete scope set to include in the challenge. Each scope must satisfy the OAuth `scope-token` grammar. */
    scopes: readonly [string, ...string[]];
    /** Optional human-readable detail satisfying the RFC 6750 `error-description` grammar. */
    errorDescription?: string;
}

/** Determines whether an MCP request needs an OAuth scope challenge. */
export type ScopeChallengeHandler = (context: {
    request: JSONRPCRequest;
    authInfo?: AuthInfo;
}) => ScopeChallenge | undefined | Promise<ScopeChallenge | undefined>;

/** @internal */
export function supportsScopeChallengeResolver(
    transport: unknown
): transport is { setScopeChallengeResolver(resolver: ScopeChallengeHandler): void } {
    return (
        typeof transport === 'object' &&
        transport !== null &&
        'setScopeChallengeResolver' in transport &&
        typeof (transport as { setScopeChallengeResolver: unknown }).setScopeChallengeResolver === 'function'
    );
}

function assertScope(scope: unknown, location: string): asserts scope is string {
    if (typeof scope !== 'string' || !/^[\u0021\u0023-\u005B\u005D-\u007E]+$/.test(scope)) {
        throw new TypeError(`${location} must satisfy the OAuth scope-token grammar`);
    }
}

function validateScopeChallenge(challenge: ScopeChallenge): ScopeChallenge {
    if (challenge === null || typeof challenge !== 'object' || !Array.isArray(challenge.scopes) || challenge.scopes.length === 0) {
        throw new TypeError('scope challenge must contain at least one scope');
    }
    for (const [index, scope] of challenge.scopes.entries()) {
        assertScope(scope, `scope challenge scopes[${index}]`);
    }
    if (challenge.errorDescription !== undefined && typeof challenge.errorDescription !== 'string') {
        throw new TypeError('scope challenge errorDescription must be a string');
    }
    if (challenge.errorDescription !== undefined && !/^[\u0020-\u0021\u0023-\u005B\u005D-\u007E]+$/.test(challenge.errorDescription)) {
        throw new TypeError('scope challenge errorDescription must satisfy the RFC 6750 error-description grammar');
    }
    return challenge;
}

/**
 * Creates a handler that requires every supplied scope exactly.
 *
 * Requests without authentication are left to the server's authentication gate.
 */
export function requireScopes(...scopes: readonly [string, ...string[]]): ScopeChallengeHandler {
    if (scopes.length === 0) {
        throw new TypeError('requireScopes must contain at least one scope');
    }
    for (const [index, scope] of scopes.entries()) {
        assertScope(scope, `requireScopes scope[${index}]`);
    }
    const requiredScopes = [...scopes] as [string, ...string[]];
    return ({ authInfo }) => {
        if (authInfo === undefined) return;
        const activeScopes = new Set(authInfo.scopes);
        if (requiredScopes.every(scope => activeScopes.has(scope))) return;
        return { scopes: requiredScopes };
    };
}

/** @internal */
export async function findScopeChallenge(
    requests: readonly JSONRPCRequest[],
    authInfo: AuthInfo | undefined,
    resolve: ScopeChallengeHandler
): Promise<ScopeChallenge | undefined> {
    for (const request of requests) {
        const challenge = await resolve({ request, ...(authInfo !== undefined && { authInfo }) });
        if (challenge !== undefined) {
            return validateScopeChallenge(challenge);
        }
    }
    return undefined;
}

/**
 * The RFC 9728 Protected Resource Metadata URL to advertise on a scope
 * challenge, derived from the verified {@link AuthInfo}: the URL the
 * authentication gate stamped (`authInfo.resourceMetadataUrl`, set by the
 * bearer-auth helpers from their `resourceMetadataUrl` option), falling back
 * to the well-known location for an HTTP(S) RFC 8707 `resource` identifier, or
 * `undefined` when neither is available (the `resource_metadata` parameter is
 * then omitted, matching the bearer-auth challenges).
 *
 * @internal
 */
export function scopeChallengeResourceMetadataUrl(authInfo: AuthInfo | undefined): string | undefined {
    if (authInfo?.resourceMetadataUrl !== undefined) {
        return authInfo.resourceMetadataUrl;
    }
    if (authInfo?.resource?.protocol === 'https:' || authInfo?.resource?.protocol === 'http:') {
        return getOAuthProtectedResourceMetadataUrl(authInfo.resource);
    }
    return undefined;
}

/** @internal */
export function createScopeChallengeResponse(challenge: ScopeChallenge, resourceMetadataUrl: string | undefined): Response {
    return bearerAuthChallengeResponse(
        new OAuthError(OAuthErrorCode.InsufficientScope, challenge.errorDescription ?? 'Insufficient scope'),
        {
            requiredScopes: [...challenge.scopes],
            resourceMetadataUrl
        }
    );
}
