    /**
     * Enforces server-side validation for `tools/call` results regardless of how the
     * handler was registered, attaches the configured per-operation cache hint
     * (when one exists) so the 2026-07-28 encode seam can fill `ttlMs`/`cacheScope`
     * for results that do not provide their own, and owns the multi-round-trip
     * seam: on the methods whose 2026-07-28 result vocabulary includes
     * `input_required` (`tools/call`, `prompts/get`, `resources/read`) an
     * input-required return skips result-schema validation and is checked
     * against the served era, the at-least-one rule, and the request's own
     * declared client capabilities; on every other method an input-required
     * return is a server bug and fails loudly. The hint rides a symbol-keyed
     * property that is never serialized, so 2025-era responses are unaffected.
     */
    protected override _wrapHandler(
        method: string,
        handler: (request: JSONRPCRequest, ctx: ServerContext) => Promise<Result>
    ): (request: JSONRPCRequest, ctx: ServerContext) => Promise<Result> {
        if (method !== 'tools/call') {
            const cacheHint = (this._cacheHints as Record<string, CacheHint | undefined> | undefined)?.[method];
            const isInputRequiredCapable = INPUT_REQUIRED_CAPABLE_METHODS.has(method);
            if (cacheHint === undefined && !isInputRequiredCapable) {
                // Server-bug guard: an input-required return from a method
                // whose result vocabulary does not include it is never
                // mis-typed onto the wire.
                return async (request, ctx) => {
                    const result = await handler(request, ctx);
                    if (isInputRequiredResult(result)) {
                        throw new ProtocolError(
                            ProtocolErrorCode.InternalError,
                            `Handler for ${method} returned an input-required result, but only tools/call, prompts/get and ` +
                                `resources/read support input_required (protocol revision 2026-07-28)`
                        );
                    }
                    return result;
                };
            }
            return async (request, ctx) => {
                const result = isInputRequiredCapable
                    ? await this._invokeInputRequiredCapableHandler(method, handler, request, ctx)
                    : await handler(request, ctx);
                if (isInputRequiredResult(result)) {
                    if (!isInputRequiredCapable) {
                        throw new ProtocolError(
                            ProtocolErrorCode.InternalError,
                            `Handler for ${method} returned an input-required result, but only tools/call, prompts/get and ` +
                                `resources/read support input_required (protocol revision 2026-07-28)`
                        );
                    }
                    // Never cache-stamped (the encode contract skips
                    // non-complete results); the hint is not attached.
                    return result;
                }
                return cacheHint === undefined ? result : attachCacheHintFallback(result, cacheHint);
            };
        }
        return async (request, ctx) => {
            // Era-exact validation via the function-only WireCodec contract:
            // resolved from the instance era at dispatch time (the era gate
            // guarantees tools/call exists on the serving era, so the
            // `not-in-era` arm is an internal error). The era registry entry
            // IS the plain CallToolResult schema (the result map is aligned
            // to the typed map — no widened unions), so no narrower surface
            // is needed.
            const codec = codecForVersion(this._negotiatedProtocolVersion);
            const validatedRequest = codec.validateRequest('tools/call', request);
            if (!validatedRequest.ok) {
                throw new ProtocolError(
                    validatedRequest.reason === 'not-in-era' ? ProtocolErrorCode.InternalError : ProtocolErrorCode.InvalidParams,
                    validatedRequest.reason === 'not-in-era'
                        ? 'No wire schema for tools/call in the resolved era'
                        : `Invalid tools/call request: ${validatedRequest.message}`
                );
            }

            const result = await this._invokeInputRequiredCapableHandler('tools/call', handler, request, ctx);
            if (isInputRequiredResult(result)) {
                // Already checked by the seam; the CallToolResult schema does
                // not apply to it (no widening — InputRequiredResult travels
                // alongside).
                return result;
            }

            // v1-parity authoring affordance, era-independent: a content-less
            // handler result normalizes to content: [] before era validation.
            // Other result families' bodies stay un-normalized and fail loudly.
            const normalizedResult = normalizeContentlessToolResult(result);

            const validationResult = codec.validateResult('tools/call', normalizedResult);
            if (!validationResult.ok) {
                throw new ProtocolError(
                    validationResult.reason === 'not-in-era' ? ProtocolErrorCode.InternalError : ProtocolErrorCode.InvalidParams,
                    validationResult.reason === 'not-in-era'
                        ? 'No wire schema for tools/call in the resolved era'
                        : `Invalid tools/call result: ${validationResult.message}`
                );
            }

            return validationResult.value;
        };
    }

    /**
     * Whether this instance is bound to a 2026-07-28-or-later protocol
     * revision. Era is instance state — a serving entry (`createMcpHandler`,
     * `serveStdio`) marks the instance modern at construction; a 2025-era
     * `initialize` handshake binds it legacy. The multi-round-trip seam reads
     * this directly: there is no per-request era consult.
     */
    private _servedModernEra(): boolean {
        return this._negotiatedProtocolVersion !== undefined && isModernProtocolVersion(this._negotiatedProtocolVersion);
    }

    /**
     * Invokes a handler for one of the multi-round-trip methods and applies
     * the input-required seam:
     *
     * - a `UrlElicitationRequiredError` (or any 2025-style server→client
     *   request idiom) escaping the handler on a request served on the
     *   2026-07-28 era fails LOUDLY with a clear steer to
     *   `inputRequired.elicitUrl(...)` — the `-32042` error never reaches the
     *   2026-07-28 wire and the throw is not silently converted. Requests
     *   served on the 2025 era keep today's `-32042` behavior byte-exact (the
     *   error is rethrown unchanged).
     * - an input-required RETURN toward a 2026-07-28 request must satisfy
     *   the at-least-one rule, and every embedded request must be covered by
     *   the capabilities declared on the request's envelope (violations
     *   answer the typed `-32021` error). Toward a 2025-era request the
     *   return is fulfilled by the default-on legacy shim, whose own gate
     *   consults the initialize-declared capabilities and surfaces
     *   violations per family; `inputRequired.legacyShim: false` restores
     *   the pre-shim loud failure.
     */
    private async _invokeInputRequiredCapableHandler(
        method: string,
        handler: (request: JSONRPCRequest, ctx: ServerContext) => Promise<Result>,
        request: JSONRPCRequest,
        ctx: ServerContext
    ): Promise<Result> {
        const servedModern = this._servedModernEra();

        // The configured requestState.verify hook runs above the handler (and
        // therefore above the McpServer tools/call funnel), so a rejection
        // reaches the wire as a real JSON-RPC error rather than an `isError`
        // tool result. The wire message is FROZEN — the thrown reason is
        // surfaced via `onerror` only. A non-string `requestState` value (the
        // wire field is `string | undefined`) is treated as invalid regardless
        // of whether a hook is configured, so a malformed value cannot bypass
        // verification.
        const rawRequestState: unknown = ctx.mcpReq.requestState();
        if (rawRequestState !== undefined && typeof rawRequestState !== 'string') {
            throw new ProtocolError(ProtocolErrorCode.InvalidParams, 'Invalid or expired requestState', {
                reason: 'invalid_request_state'
            });
        }
        let ctxForHandler = ctx;
        if (typeof rawRequestState === 'string') {
            const decoded = await this._verifyRequestState(rawRequestState, ctx, method);
            if (decoded !== undefined) {
                ctxForHandler = withRequestStateValue(ctx, decoded);
            }
        }

        let result: Result;
        try {
            result = await handler(request, ctxForHandler);
        } catch (error) {
            if (error instanceof ProtocolError && error.code === ProtocolErrorCode.UrlElicitationRequired) {
                if (!servedModern) {
                    // 2025-era behavior is frozen: the error reaches the wire
                    // exactly as it does today.
                    throw error;
                }
                // 2026-era requests do not carry the -32042 surface. A
                // 2025-style throw fails loudly with a clear steer rather than
                // being converted: the handler should return
                // inputRequired.elicitUrl(...) instead.
                throw new ProtocolError(
                    ProtocolErrorCode.InternalError,
                    `URL elicitation cannot be signalled by throwing UrlElicitationRequiredError on protocol revision ` +
                        `${this._negotiatedProtocolVersion}: return inputRequired({ inputRequests: { …: inputRequired.elicitUrl(...) } }) ` +
                        `from the handler instead. The urlElicitationRequired error (-32042) of earlier revisions is not ` +
                        `available on this revision.`
                );
            }
            throw error;
        }

        if (!isInputRequiredResult(result)) {
            return result;
        }

        if (!servedModern) {
            if (!this._inputRequiredServing.legacyShim) {
                // The escape hatch (`inputRequired.legacyShim: false`)
                // restores the pre-shim posture: the 2025-era wire has no
                // input_required vocabulary, so fail loudly rather than
                // putting a mis-typed result on the wire.
                throw new ProtocolError(
                    ProtocolErrorCode.InternalError,
                    `Handler for ${method} returned an input-required result, but this request is served on protocol revision ` +
                        `${this._negotiatedProtocolVersion ?? LATEST_PROTOCOL_VERSION}, which has no input_required vocabulary`
                );
            }
            // Write-once handlers served to deployed 2025 clients.
            return await this._legacyInputRequiredShim().fulfill(method, handler, request, ctxForHandler, result);
        }

        // F7 at-least-one re-check (hand-built results are legal; the rule is
        // re-checked at the seam).
        const inputRequests = result.inputRequests as Record<string, unknown> | null | undefined;
        const hasInputRequests = inputRequests != null && Object.keys(inputRequests).length > 0;
        const hasRequestState = typeof result.requestState === 'string';
        if (!hasInputRequests && !hasRequestState) {
            throw new ProtocolError(
                ProtocolErrorCode.InternalError,
                `Handler for ${method} returned an input-required result with neither inputRequests nor requestState ` +
                    `(every InputRequiredResult must include at least one of the two)`
            );
        }

        // Per-embedded-request capability check against the request's own
        // envelope declaration (-32021 on violation).
        if (hasInputRequests) {
            const declared = this._inputRequestCapabilityView(ctx);
            for (const [key, entry] of Object.entries(inputRequests)) {
                const { embedded, required } = coerceEmbeddedInputRequest(method, key, entry);
                const missing = missingClientCapabilities(required, declared);
                if (missing !== undefined) {
                    throw new MissingRequiredClientCapabilityError(
                        { requiredCapabilities: missing },
                        `Cannot request input '${key}' (${embedded.method}): the request's client capabilities do not declare ` +
                            `the required capability`
                    );
                }
            }
        }

        return result;
    }

    /**
     * Runs the configured `requestState.verify` hook and returns its
     * resolved value (`undefined` when unconfigured or the hook returns
     * nothing). Deny-on-error: any hook failure answers the frozen `-32602`;
     * the reason goes to `onerror` only.
     */
    private async _verifyRequestState(state: string, ctx: ServerContext, method: string): Promise<unknown> {
        if (this._requestStateVerify === undefined) {
            return undefined;
        }
        try {
            return await this._requestStateVerify(state, ctx);
        } catch (error) {
            this.onerror?.(
                new Error(`requestState verification rejected ${method}: ${error instanceof Error ? error.message : String(error)}`)
            );
            throw new ProtocolError(ProtocolErrorCode.InvalidParams, 'Invalid or expired requestState', {
                reason: 'invalid_request_state'
            });
        }
    }

    /**
     * The per-request resolved client-capabilities view: the request's own
     * `_meta` envelope on the 2026 era; the `initialize`-declared state on a
     * 2025-era connection. Per-request instances that never saw an
     * initialize (stateless legacy) hold nothing, so gates refuse there.
     */
    private _inputRequestCapabilityView(ctx: ServerContext): ClientCapabilities | undefined {
        return this._servedModernEra()
            ? (ctx.mcpReq.envelope?.[CLIENT_CAPABILITIES_META_KEY] as ClientCapabilities | undefined)
            : this._clientCapabilities;
    }

    /**
     * Guard for the push-style server→client request APIs ({@linkcode createMessage},
     * {@linkcode elicitInput}, {@linkcode listRoots}, {@linkcode ping}) on a
     * modern-era instance: the 2026-07-28 revision has no server→client request
     * channel, so the call fails before any wire traffic with a typed error
     * whose message steers to `inputRequired(...)`. The base era gate would
     * also reject it; this guard runs first to carry the steer.
     */
    private _assertPushApiInServedEra(method: string): void {
        if (this._servedModernEra()) {
            throw new SdkError(
                SdkErrorCode.MethodNotSupportedByProtocolVersion,
                `Server-to-client requests are not available on protocol revision ${this._negotiatedProtocolVersion}: ` +
                    `'${method}' cannot be sent while serving a request on that revision. ` +
                    `Return inputRequired({ ... }) from the handler instead — the client fulfils the embedded ` +
                    `requests and retries the original request (multi round-trip requests).`,
                { method, era: '2026-07-28' }
            );
        }
    }

    protected assertCapabilityForMethod(method: RequestMethod | string): void {
        switch (method) {
            case 'sampling/createMessage': {
                if (!this._clientCapabilities?.sampling) {
                    throw new SdkError(SdkErrorCode.CapabilityNotSupported, `Client does not support sampling (required for ${method})`);
                }
                break;
            }

            case 'elicitation/create': {
                if (!this._clientCapabilities?.elicitation) {
                    throw new SdkError(SdkErrorCode.CapabilityNotSupported, `Client does not support elicitation (required for ${method})`);
                }
                break;
            }

            case 'roots/list': {
                if (!this._clientCapabilities?.roots) {
                    throw new SdkError(
                        SdkErrorCode.CapabilityNotSupported,
                        `Client does not support listing roots (required for ${method})`
                    );
                }
                break;
            }

            case 'ping': {
                // No specific capability required for ping
                break;
            }
        }
    }

    protected assertNotificationCapability(method: NotificationMethod | string): void {
        switch (method) {
            case 'notifications/message': {
                if (!this._capabilities.logging) {
                    throw new SdkError(SdkErrorCode.CapabilityNotSupported, `Server does not support logging (required for ${method})`);
                }
                break;
            }

            case 'notifications/resources/updated':
            case 'notifications/resources/list_changed': {
                if (!this._capabilities.resources) {
                    throw new SdkError(
                        SdkErrorCode.CapabilityNotSupported,
                        `Server does not support notifying about resources (required for ${method})`
                    );
                }
                break;
            }

            case 'notifications/tools/list_changed': {
                if (!this._capabilities.tools) {
                    throw new SdkError(
                        SdkErrorCode.CapabilityNotSupported,
                        `Server does not support notifying of tool list changes (required for ${method})`
                    );
                }
                break;
            }

            case 'notifications/prompts/list_changed': {
                if (!this._capabilities.prompts) {
                    throw new SdkError(
                        SdkErrorCode.CapabilityNotSupported,
                        `Server does not support notifying of prompt list changes (required for ${method})`
                    );
                }
                break;
            }

            case 'notifications/elicitation/complete': {
                if (!this._clientCapabilities?.elicitation?.url) {
                    throw new SdkError(
                        SdkErrorCode.CapabilityNotSupported,
                        `Client does not support URL elicitation (required for ${method})`
                    );
                }
                break;
            }

            case 'notifications/cancelled': {
                // Cancellation notifications are always allowed
                break;
            }

            case 'notifications/progress': {
                // Progress notifications are always allowed
                break;
            }
        }
    }

    protected assertRequestHandlerCapability(method: string): void {
        switch (method) {
            case 'completion/complete': {
                if (!this._capabilities.completions) {
                    throw new SdkError(SdkErrorCode.CapabilityNotSupported, `Server does not support completions (required for ${method})`);
                }
                break;
            }

            case 'logging/setLevel': {
                if (!this._capabilities.logging) {
                    throw new SdkError(SdkErrorCode.CapabilityNotSupported, `Server does not support logging (required for ${method})`);
                }
                break;
            }

            case 'prompts/get':
            case 'prompts/list': {
                if (!this._capabilities.prompts) {
                    throw new SdkError(SdkErrorCode.CapabilityNotSupported, `Server does not support prompts (required for ${method})`);
                }
                break;
            }

            case 'resources/list':
            case 'resources/templates/list':
            case 'resources/read': {
                if (!this._capabilities.resources) {
                    throw new SdkError(SdkErrorCode.CapabilityNotSupported, `Server does not support resources (required for ${method})`);
                }
                break;
            }

            case 'tools/call':
            case 'tools/list': {
                if (!this._capabilities.tools) {
                    throw new SdkError(SdkErrorCode.CapabilityNotSupported, `Server does not support tools (required for ${method})`);
                }
                break;
            }

            case 'ping':
            case 'initialize': {
                // No specific capability required for these methods
                break;
            }
        }
    }

    private async _oninitialize(request: InitializeRequest): Promise<InitializeResult> {
        const requestedVersion = request.params.protocolVersion;

        this._clientCapabilities = request.params.capabilities;
        this._clientVersion = request.params.clientInfo;

        // A 2026-07-28-or-later revision is NEVER negotiated via the legacy
        // `initialize` handshake — only ever selected through `server/discover` —
        // so the accept check and counter-offer consult only the legacy subset.
        const legacyVersions = legacyProtocolVersions(this._supportedProtocolVersions);
        const protocolVersion = legacyVersions.includes(requestedVersion)
            ? requestedVersion
            : (legacyVersions[0] ?? LATEST_PROTOCOL_VERSION);

        // The negotiated version is the instance's connection state — it IS
        // the wire-era selection for everything this instance sends and
        // receives from here on (legacy handshake ⇒ a legacy-era version).
        this._negotiatedProtocolVersion = protocolVersion;
        this.transport?.setProtocolVersion?.(protocolVersion);

        return {
            protocolVersion,
            capabilities: this.getCapabilities(),
            serverInfo: this._serverInfo,
            ...(this._instructions && { instructions: this._instructions })
        };
    }

    /**
     * Answers `server/discover` (protocol revision 2026-07-28). `supportedVersions`
     * lists only modern revisions (2025-era versions are negotiated via `initialize`);
     * the capabilities are advertised as-is, listChanged/subscribe bits included
     * (see {@linkcode discoverAdvertisedCapabilities}).
     */
    private _ondiscover(): DiscoverResult {
        // Server identity is not a body field: the encode seam stamps it into
        // the result `_meta` via `_outboundServerInfo` (spec PR #3002).
        return {
            supportedVersions: modernProtocolVersions(this._supportedProtocolVersions),
            capabilities: discoverAdvertisedCapabilities(this.getCapabilities()),
            ...(this._instructions && { instructions: this._instructions })
        };
    }

    /**
     * The identity the 2026-era encode seam stamps into every outbound
     * result's `_meta` under `io.modelcontextprotocol/serverInfo` (spec PR
     * #3002: servers SHOULD identify themselves on every response).
     */
    protected override _outboundServerInfo(): Implementation | undefined {
        return this._serverInfo;
    }

    /**
     * After initialization has completed, this will be populated with the client's reported capabilities.
     *
     * @deprecated Read client identity from the per-request handler context instead: on
     * 2026-07-28 (per-request envelope) requests `ctx.mcpReq.envelope` carries the client's
     * declared capabilities, while on 2025-era connections this accessor keeps returning the
     * `initialize`-scoped value. The accessor remains functional — instances serving the
     * 2026-07-28 era are backfilled per request from the validated envelope.
     */
    getClientCapabilities(): ClientCapabilities | undefined {
        return this._clientCapabilities;
    }

    /**
     * After initialization has completed, this will be populated with information about the client's name and version.
     *
     * @deprecated Read client identity from the per-request handler context instead: on
     * 2026-07-28 (per-request envelope) requests `ctx.mcpReq.envelope` carries the client's
     * name and version, while on 2025-era connections this accessor keeps returning the
     * `initialize`-scoped value. The accessor remains functional — instances serving the
     * 2026-07-28 era are backfilled per request from the validated envelope.
     */
    getClientVersion(): Implementation | undefined {
        return this._clientVersion;
    }

    /**
     * After initialization has completed, this will be populated with the protocol version negotiated
     * with the client (the version the server responded with during the initialize handshake), or
     * `undefined` before initialization.
     *
     * @deprecated Read the protocol revision from the per-request handler context instead: on
     * 2026-07-28 (per-request envelope) requests `ctx.mcpReq.envelope` names the revision the
     * request was sent for, while on 2025-era connections this accessor keeps returning the
     * `initialize`-negotiated version. The accessor remains functional — instances serving the
     * 2026-07-28 era report that revision.
     */
    getNegotiatedProtocolVersion(): string | undefined {
        return this._negotiatedProtocolVersion;
    }

    /**
     * Project a `tools/call` result through this instance's negotiated wire
     * codec — the era-agnostic SEP-2106 §4.3 TextContent auto-append, plus on
     * the 2025 era the `{result:…}` wrap when `structuredContent` is a
     * non-object value or the advertised `outputSchema` had a non-object root.
     * Identity for object-shaped `structuredContent` on the 2026 era.
     *
     * `McpServer`'s built-in `tools/call` handler routes through this method.
     * Low-level `setRequestHandler('tools/call', …)` authors call it
     * themselves so the projection lives in one place (the codec) and the
     * server-side handler stays era-blind.
     *
     * This is the only codec function exposed on `Server` — the full
     * `WireCodec` is intentionally not part of the public surface.
     */
    public projectCallToolResult(
        result: CallToolResult,
        advertisedOutputSchema: Readonly<Record<string, unknown>> | undefined
    ): CallToolResult {
        return this._wireCodec().projectCallToolResult(result, advertisedOutputSchema);
    }

    /**
     * Returns the current server capabilities.
     */
    public getCapabilities(): ServerCapabilities {
        return this._capabilities;
    }

    /**
     * Sends a `ping` request to the connected client.
     *
     * @deprecated The 2026-07-28 protocol removed ping; it throws on a 2026-07-28-era instance.
     * If your factory serves both eras, this only works on the legacy path.
     */
    async ping(): Promise<EmptyResult> {
        this._assertPushApiInServedEra('ping');
        return this.request({ method: 'ping' });
    }

    /**
     * Request LLM sampling from the client (without tools).
     * Returns single content block for backwards compatibility.
     *
     * @deprecated Deprecated as of protocol version 2026-07-28 (SEP-2577).
     * Throws on a 2026-07-28-era request — use {@link index.inputRequired | inputRequired} (multi-round-trip) instead,
     * or migrate to calling LLM provider APIs directly. The 2025 push-style server-to-client
     * request model is replaced by input_required results in the 2026-07-28 protocol. If your
     * factory serves both eras, this only works on the legacy path.
     */
    async createMessage(params: CreateMessageRequestParamsBase, options?: RequestOptions): Promise<CreateMessageResult>;

    /**
     * Request LLM sampling from the client with tool support.
     * Returns content that may be a single block or array (for parallel tool calls).
     *
     * @deprecated Deprecated as of protocol version 2026-07-28 (SEP-2577).
     * Throws on a 2026-07-28-era request — use {@link index.inputRequired | inputRequired} (multi-round-trip) instead,
     * or migrate to calling LLM provider APIs directly. The 2025 push-style server-to-client
     * request model is replaced by input_required results in the 2026-07-28 protocol. If your
     * factory serves both eras, this only works on the legacy path.
     */
    async createMessage(params: CreateMessageRequestParamsWithTools, options?: RequestOptions): Promise<CreateMessageResultWithTools>;

    /**
     * Request LLM sampling from the client.
     * When tools may or may not be present, returns the union type.
     *
     * @deprecated Deprecated as of protocol version 2026-07-28 (SEP-2577).
     * Throws on a 2026-07-28-era request — use {@link index.inputRequired | inputRequired} (multi-round-trip) instead,
     * or migrate to calling LLM provider APIs directly. The 2025 push-style server-to-client
     * request model is replaced by input_required results in the 2026-07-28 protocol. If your
     * factory serves both eras, this only works on the legacy path.
     */
    async createMessage(
        params: CreateMessageRequest['params'],
        options?: RequestOptions
    ): Promise<CreateMessageResult | CreateMessageResultWithTools>;

    // Implementation
    async createMessage(
        params: CreateMessageRequest['params'],
        options?: RequestOptions
    ): Promise<CreateMessageResult | CreateMessageResultWithTools> {
        this._assertPushApiInServedEra('sampling/createMessage');
        // Capability check - only required when tools/toolChoice are provided
        if ((params.tools || params.toolChoice) && !this._clientCapabilities?.sampling?.tools) {
            throw new SdkError(SdkErrorCode.CapabilityNotSupported, 'Client does not support sampling tools capability.');
        }

        // Message structure validation - always validate tool_use/tool_result pairs.
        // These may appear even without tools/toolChoice in the current request when
        // a previous sampling request returned tool_use and this is a follow-up with results.
        if (params.messages.length > 0) {
            const lastMessage = params.messages.at(-1)!;
            const lastContent = Array.isArray(lastMessage.content) ? lastMessage.content : [lastMessage.content];
            const hasToolResults = lastContent.some(c => c.type === 'tool_result');

            const previousMessage = params.messages.length > 1 ? params.messages.at(-2) : undefined;
            const previousContent = previousMessage
                ? Array.isArray(previousMessage.content)
                    ? previousMessage.content
                    : [previousMessage.content]
                : [];
            const hasPreviousToolUse = previousContent.some(c => c.type === 'tool_use');

            if (hasToolResults) {
                if (lastContent.some(c => c.type !== 'tool_result')) {
                    throw new ProtocolError(
                        ProtocolErrorCode.InvalidParams,
                        'The last message must contain only tool_result content if any is present'
                    );
                }
                if (!hasPreviousToolUse) {
                    throw new ProtocolError(
                        ProtocolErrorCode.InvalidParams,
                        'tool_result blocks are not matching any tool_use from the previous message'
                    );
                }
            }
            if (hasPreviousToolUse) {
                const toolUseIds = new Set(previousContent.filter(c => c.type === 'tool_use').map(c => (c as ToolUseContent).id));
                const toolResultIds = new Set(
                    lastContent.filter(c => c.type === 'tool_result').map(c => (c as ToolResultContent).toolUseId)
                );
                if (toolUseIds.size !== toolResultIds.size || ![...toolUseIds].every(id => toolResultIds.has(id))) {
                    throw new ProtocolError(
                        ProtocolErrorCode.InvalidParams,
                        'ids of tool_result blocks and tool_use blocks from previous message do not match'
                    );
                }
            }
        }

        // The result schema depends on the REQUEST params (tools vs no tools),
        // which a method-keyed registry entry cannot express — the era codec's
        // `samplingResultVariant` owns the with-tools/plain pair. The funnel's
        // registry-result path runs first (era-gated: sampling/createMessage
        // is not a wire request on the 2026 era, so a modern-era instance
        // fails with the typed era error before anything reaches the
        // transport), then the variant validator narrows the wide result.
        const hasTools = Boolean(params.tools || params.toolChoice);
        const wide = await this.request({ method: 'sampling/createMessage', params }, options);
        const outcome = this._wireCodec().samplingResultVariant(hasTools, wide);
        if (!outcome.ok) {
            // `not-in-era` is unreachable on the path that gets here (the era
            // gate above filters out 2026 instances); `invalid` is a peer bug.
            throw new SdkError(
                SdkErrorCode.InvalidResult,
                `Invalid sampling/createMessage result: ${outcome.reason === 'invalid' ? outcome.message : outcome.reason}`
            );
        }
        return outcome.value;
    }

    /**
     * Creates an elicitation request for the given parameters.
     * For backwards compatibility, `mode` may be omitted for form requests and will default to `"form"`.
     * @param params The parameters for the elicitation request.
     * @param options Optional request options.
     * @returns The result of the elicitation request.
     *
     * @deprecated Throws on a 2026-07-28-era request — use {@link index.inputRequired | inputRequired} (multi-round-trip)
     * instead. The 2025 push-style server-to-client request model is replaced by input_required
     * results in the 2026-07-28 protocol. If your factory serves both eras, this only works on the
     * legacy path.
     */
    async elicitInput(params: ElicitRequestFormParams | ElicitRequestURLParams, options?: RequestOptions): Promise<ElicitResult> {
        this._assertPushApiInServedEra('elicitation/create');
        const mode = (params.mode ?? 'form') as 'form' | 'url';

        switch (mode) {
            case 'url': {
                if (!this._clientCapabilities?.elicitation?.url) {
                    throw new SdkError(SdkErrorCode.CapabilityNotSupported, 'Client does not support url elicitation.');
                }
                break;
            }
            case 'form': {
                if (!this._clientCapabilities?.elicitation?.form) {
                    throw new SdkError(SdkErrorCode.CapabilityNotSupported, 'Client does not support form elicitation.');
                }
                break;
            }
        }

        return this._sendElicitationLeg(params, options);
    }

    /**
     * The capability-check-free core of {@linkcode elicitInput}. The shim
     * uses it because its gate differs from the public checks: a bare
     * `elicitation: {}` counts as form support (the pre-mode rule), and
     * accepted content passes through unvalidated for parity with the
     * modern client driver (handlers validate via the schema-aware
     * `acceptedContent` overload and can re-ask).
     */
    private async _sendElicitationLeg(
        params: ElicitRequestFormParams | ElicitRequestURLParams,
        options?: RequestOptions,
        behavior?: { validateAcceptedContent: boolean }
    ): Promise<ElicitResult> {
        const mode = (params.mode ?? 'form') as 'form' | 'url';
        const validateAcceptedContent = behavior?.validateAcceptedContent ?? true;

        switch (mode) {
            case 'url': {
                const urlParams = params as ElicitRequestURLParams;
                // Method-keyed request(): the era registry's plain
                // ElicitResult schema is exactly the narrow surface.
                return this.request({ method: 'elicitation/create', params: urlParams }, options);
            }
            case 'form': {
                const formParams: ElicitRequestFormParams =
                    params.mode === 'form' ? (params as ElicitRequestFormParams) : { ...(params as ElicitRequestFormParams), mode: 'form' };

                const result = await this.request({ method: 'elicitation/create', params: formParams }, options);

                if (validateAcceptedContent && result.action === 'accept' && result.content && formParams.requestedSchema) {
                    try {
                        const validator = this._jsonSchemaValidator.getValidator(formParams.requestedSchema as JsonSchemaType);
                        const validationResult = validator(result.content);

                        if (!validationResult.valid) {
                            throw new ProtocolError(
                                ProtocolErrorCode.InvalidParams,
                                `Elicitation response content does not match requested schema: ${validationResult.errorMessage}`
                            );
                        }
                    } catch (error) {
                        if (error instanceof ProtocolError) {
                            throw error;
                        }
                        throw new ProtocolError(
                            ProtocolErrorCode.InternalError,
                            `Error validating elicitation response: ${error instanceof Error ? error.message : String(error)}`
                        );
                    }
                }
                return result;
            }
        }
    }

    /**
     * Creates a reusable callback that, when invoked, will send a `notifications/elicitation/complete`
     * notification for the specified elicitation ID.
     *
     * The notification (and the `elicitationId` it references) exists only on protocol revision
     * 2025-11-25 — the 2026-07-28 revision removed both. On a connection negotiated at 2026-07-28 the
     * returned callback rejects with a typed local error before anything reaches the transport
     * (the method is not part of that revision's wire registry).
     *
     * @param elicitationId The ID of the elicitation to mark as complete.
     * @param options Optional notification options. Useful when the completion notification should be related to a prior request.
     * @returns A function that emits the completion notification when awaited.
     */
    createElicitationCompletionNotifier(elicitationId: string, options?: NotificationOptions): () => Promise<void> {
        if (!this._clientCapabilities?.elicitation?.url) {
            throw new SdkError(
                SdkErrorCode.CapabilityNotSupported,
                'Client does not support URL elicitation (required for notifications/elicitation/complete)'
            );
        }

        return () =>
            this.notification(
                {
                    method: 'notifications/elicitation/complete',
                    params: {
                        elicitationId
                    }
                },
                options
            );
    }

    /**
     * Requests the list of roots from the client.
     *
     * @deprecated Deprecated as of protocol version 2026-07-28 (SEP-2577).
     * Throws on a 2026-07-28-era request — use {@link index.inputRequired | inputRequired} (multi-round-trip) instead,
     * or migrate to passing paths via tool parameters, resource URIs, or configuration. The 2025
     * push-style server-to-client request model is replaced by input_required results in the
     * 2026-07-28 protocol. If your factory serves both eras, this only works on the legacy path.
     */
    async listRoots(params?: ListRootsRequest['params'], options?: RequestOptions): Promise<ListRootsResult> {
        this._assertPushApiInServedEra('roots/list');
        return this.request({ method: 'roots/list', params }, options);
    }

    /**
     * Sends a logging message to the client, if connected.
     * Note: You only need to send the parameters object, not the entire JSON-RPC message.
     * @see {@linkcode LoggingMessageNotification}
     * @param params
     * @param sessionId Optional for stateless transports and backward compatibility.
     *
     * @deprecated Deprecated as of protocol version 2026-07-28 (SEP-2577).
     * Remains functional during the deprecation window (at least twelve months).
     * Migrate to stderr logging (STDIO servers) or OpenTelemetry.
     */
    async sendLoggingMessage(params: LoggingMessageNotification['params'], sessionId?: string) {
        if (this._capabilities.logging && !this.isMessageIgnored(params.level, sessionId)) {
            return this.notification({ method: 'notifications/message', params });
        }
    }

    async sendResourceUpdated(params: ResourceUpdatedNotification['params']) {
        return this.notification({
            method: 'notifications/resources/updated',
            params
        });
    }

    async sendResourceListChanged() {
        return this.notification({
            method: 'notifications/resources/list_changed'
        });
    }

    async sendToolListChanged() {
        return this.notification({ method: 'notifications/tools/list_changed' });
    }

    async sendPromptListChanged() {
        return this.notification({ method: 'notifications/prompts/list_changed' });
    }
}

/**
 * The capability set a server advertises on `server/discover`. Pure — never
 * mutates the input; the legacy `initialize` advertisement is untouched.
 *
 * The serving entries serve `subscriptions/listen` themselves, so the
 * `listChanged` and `resources.subscribe` capability bits are advertised
 * as-is: a modern-era client uses them to decide which notification types to
 * request on its listen filter.
 */
export function discoverAdvertisedCapabilities(capabilities: ServerCapabilities): ServerCapabilities {
    return { ...capabilities };
}
import type {
    BaseMetadata,
    CacheHint,
    CallToolResult,
    CompleteRequestPrompt,
    CompleteRequestResourceTemplate,
    CompleteResult,
    GetPromptResult,
    Icon,
    Implementation,
    InputRequiredResult,
    ListPromptsResult,
    ListResourcesResult,
    ListToolsResult,
    LoggingMessageNotification,
    Prompt,
    PromptReference,
    ReadResourceResult,
    Resource,
    ResourceTemplateReference,
    Result,
    ServerContext,
    StandardSchemaWithJSON,
    Tool,
    ToolAnnotations,
    ToolExecution,
    Transport,
    Variables
} from '@modelcontextprotocol/core-internal';
import {
    assertCompleteRequestPrompt,
    assertCompleteRequestResourceTemplate,
    assertValidCacheHint,
    attachCacheHintFallback,
    isInputRequiredResult,
    normalizeRawShapeSchema,
    promptArgumentsFromStandardSchema,
    ProtocolError,
    ProtocolErrorCode,
    ResourceNotFoundError,
    scanXMcpHeaderDeclarations,
    standardSchemaToJsonSchema,
    UriTemplate,
    validateAndWarnToolName,
    validateStandardSchema
} from '@modelcontextprotocol/core-internal';
import type * as z from 'zod/v4';

import { getCompleter, isCompletable } from './completable';
import type { ScopeChallengeHandler } from './scopeChallenge';
import { supportsScopeChallengeResolver } from './scopeChallenge';
import type { ServerOptions } from './server';
import { Server } from './server';

// Counts array elements and object members in `value`, stopping once the running total passes `max`.
function toolInputElementCount(value: unknown, max: number): number {
    let count = 0;
    const stack: unknown[] = [value];
    while (stack.length > 0) {
        const node = stack.pop();
        if (node === null || typeof node !== 'object') continue;
        if (Array.isArray(node)) {
            for (const child of node) {
                if (++count > max) return count;
                if (child !== null && typeof child === 'object') stack.push(child);
            }
        } else {
            for (const key in node) {
                if (!Object.prototype.hasOwnProperty.call(node, key)) continue;
                if (++count > max) return count;
                const child = (node as Record<string, unknown>)[key];
                if (child !== null && typeof child === 'object') stack.push(child);
            }
        }
    }
    return count;
}

// Resolves the configured element ceiling: no limit when unset or Infinity, else a number of at least 1.
function resolveMaxToolInputElements(value: number | undefined): number | undefined {
    if (value === undefined || value === Infinity) return undefined;
    if (typeof value !== 'number' || Number.isNaN(value) || value < 1) {
        throw new RangeError(`maxToolInputElements must be a number of at least 1, or Infinity, got ${String(value)}`);
    }
    return value;
}

/**
 * Options for {@linkcode McpServer}: everything {@linkcode ServerOptions} accepts, plus `maxToolInputElements`.
 */
export type McpServerOptions = ServerOptions & {
    /**
     * Largest combined number of array elements and object members a single `tools/call` `arguments` payload may contain.
     * A number of at least 1; unset or `Infinity` means no limit.
     */
    maxToolInputElements?: number;
};

/**
 * High-level MCP server that provides a simpler API for working with resources, tools, and prompts.
 * For advanced usage (like sending notifications or setting custom request handlers), use the underlying
 * {@linkcode Server} instance available via the {@linkcode McpServer.server | server} property.
 *
 * @example
 * ```ts source="./mcp.examples.ts#McpServer_basicUsage"
 * const server = new McpServer({
 *     name: 'my-server',
 *     version: '1.0.0'
 * });
 * ```
 */
export class McpServer {
    /**
     * The underlying {@linkcode Server} instance, useful for advanced operations like sending notifications.
     */
    public readonly server: Server;

    private readonly _maxToolInputElements: number | undefined;

    private _registeredResources: { [uri: string]: RegisteredResource } = {};
    private _registeredResourceTemplates: {
        [name: string]: RegisteredResourceTemplate;
    } = {};
    private _registeredTools: { [name: string]: RegisteredTool } = {};
    private _registeredPrompts: { [name: string]: RegisteredPrompt } = {};
    /** Per-tool JSON-converted `inputSchema`, filled on first use by `toolInputSchemaJson()`. */
    private _toolInputSchemaJson: { [name: string]: Record<string, unknown> } = {};

    /**
     * The JSON-serialized `inputSchema` of a registered tool, or `undefined`
     * when no such tool is registered. Used by the HTTP entry's pre-dispatch
     * SEP-2243 `Mcp-Param-*` validation step (which needs the same JSON Schema
     * `tools/list` would emit, before dispatch reaches the handler).
     *
     * @internal
     */
    toolInputSchemaJson(name: string): Record<string, unknown> | undefined {
        const tool = this._registeredTools[name];
        if (tool === undefined || !tool.enabled) return undefined;
        if (Object.hasOwn(this._toolInputSchemaJson, name)) return this._toolInputSchemaJson[name];
        if (tool.inputSchema === undefined) return EMPTY_OBJECT_JSON_SCHEMA;
        // A conversion failure returns `undefined` so it surfaces where it always has (`tools/list`).
        try {
            const json = standardSchemaToJsonSchema(tool.inputSchema, 'input');
            this._toolInputSchemaJson[name] = json;
            return json;
        } catch {
            return undefined;
        }
    }

    constructor(serverInfo: Implementation, options?: McpServerOptions) {
        this.server = new Server(serverInfo, options);
        this._maxToolInputElements = resolveMaxToolInputElements(options?.maxToolInputElements);

        // Per the MCP spec, a server that declares a primitive capability MUST respond to its
        // list method (potentially with an empty result) rather than "Method not found" — even
        // if nothing has been registered yet. Handlers are normally installed lazily on first
        // registration, so eagerly install them here for any capability declared up front.
        // (Users of the low-level `Server` class remain responsible for their own handlers.)
        if (options?.capabilities?.tools) {
            this.setToolRequestHandlers();
        }
        if (options?.capabilities?.resources) {
            this.setResourceRequestHandlers();
        }
        if (options?.capabilities?.prompts) {
            this.setPromptRequestHandlers();
        }
    }

    /**
     * Attaches to the given transport, starts it, and starts listening for messages.
     *
     * The `server` object assumes ownership of the {@linkcode Transport}, replacing any callbacks that have already been set, and expects that it is the only user of the {@linkcode Transport} instance going forward.
     *
     * @example
     * ```ts source="./mcp.examples.ts#McpServer_connect_stdio"
     * const server = new McpServer({ name: 'my-server', version: '1.0.0' });
     * const transport = new StdioServerTransport();
     * await server.connect(transport);
     * ```
     */
    async connect(transport: Transport): Promise<void> {
        if (supportsScopeChallengeResolver(transport)) {
            transport.setScopeChallengeResolver(context => this.resolveScopeChallenge(context));
        }
        return await this.server.connect(transport);
    }

    /**
     * Closes the connection.
     */
    async close(): Promise<void> {
        await this.server.close();
    }

    /** @internal */
    resolveScopeChallenge: ScopeChallengeHandler = context => {
        switch (context.request.method) {
            case 'tools/call': {
                const toolName = (context.request.params as { name?: unknown } | undefined)?.name;
                if (typeof toolName !== 'string') return;
                const tool = this._registeredTools[toolName];
                if (tool === undefined || !tool.enabled) return;
                return tool.scopeChallenge?.(context);
            }
            case 'resources/read': {
                const resourceUri = (context.request.params as { uri?: unknown } | undefined)?.uri;
                if (typeof resourceUri !== 'string') return;

                let uri: URL;
                try {
                    uri = new URL(resourceUri);
                } catch {
                    return;
                }

                const resource = this._registeredResources[uri.toString()];
                if (resource !== undefined) {
                    return resource.enabled ? resource.scopeChallenge?.(context) : undefined;
                }

                for (const template of Object.values(this._registeredResourceTemplates)) {
                    const variables = template.resourceTemplate.uriTemplate.match(uri.toString());
                    if (variables) {
                        return template.enabled ? template.scopeChallenge?.(context) : undefined;
                    }
                }
                return;
            }
            case 'prompts/get': {
                const promptName = (context.request.params as { name?: unknown } | undefined)?.name;
                if (typeof promptName !== 'string') return;
                const prompt = this._registeredPrompts[promptName];
                if (prompt === undefined || !prompt.enabled) return;
                return prompt.scopeChallenge?.(context);
            }
            default: {
                return;
            }
        }
    };

    private _toolHandlersInitialized = false;

    private setToolRequestHandlers() {
        if (this._toolHandlersInitialized) {
            return;
        }

        this.server.assertCanSetRequestHandler('tools/list');
        this.server.assertCanSetRequestHandler('tools/call');

        this.server.registerCapabilities({
            tools: {
                listChanged: this.server.getCapabilities().tools?.listChanged ?? true
            }
        });

        // Note: tools are listed in registration (insertion) order, which keeps the ordering
        // deterministic across requests when the underlying tool set has not changed, as
        // recommended by the spec.
        this.server.setRequestHandler(
            'tools/list',
            (): ListToolsResult => ({
                tools: Object.entries(this._registeredTools)
                    .filter(([, tool]) => tool.enabled)
                    .map(([name, tool]): Tool => {
                        const toolDefinition: Tool = {
                            name,
                            title: tool.title,
                            description: tool.description,
                            inputSchema: tool.inputSchema
                                ? (convertListedInputSchema(name, tool.inputSchema) as Tool['inputSchema'])
                                : EMPTY_OBJECT_JSON_SCHEMA,
                            annotations: tool.annotations,
                            icons: tool.icons,
                            execution: tool.execution,
                            _meta: tool._meta
                        };

                        if (tool.outputSchema) {
                            // SEP-2106 legacy interop (non-object outputSchema roots wrapped in
                            // `{type:'object',properties:{result:<natural>},required:['result']}` toward
                            // 2025-era clients) lives in the 2025 wire codec's `encodeResult('tools/list', …)`
                            // — this handler is era-blind and emits the natural converted schema.
                            toolDefinition.outputSchema = standardSchemaToJsonSchema(tool.outputSchema, 'output') as Tool['outputSchema'];
                        }

                        return toolDefinition;
                    })
            })
        );

        this.server.setRequestHandler('tools/call', async (request, ctx): Promise<CallToolResult | InputRequiredResult> => {
            const tool = this._registeredTools[request.params.name];
            if (!tool) {
                throw new ProtocolError(ProtocolErrorCode.InvalidParams, `Tool ${request.params.name} not found`);
            }
            if (!tool.enabled) {
                throw new ProtocolError(ProtocolErrorCode.InvalidParams, `Tool ${request.params.name} disabled`);
            }

            try {
                const args = await this.validateToolInput(tool, request.params.arguments, request.params.name);
                const result = await this.executeToolHandler(tool, args, ctx);
                await this.validateToolOutput(tool, result, request.params.name);
                if (isInputRequiredResult(result)) return result;
                // SEP-2106 result-side projection (the era-agnostic TextContent auto-append; the
                // `{result:…}` wrap on the 2025 era) lives behind the wire codec's
                // `projectCallToolResult`. The codec receives the SAME advertised JSON Schema
                // `tools/list` emits (and that the codec's `encodeResult('tools/list', …)` may have
                // wrapped) so the listing and the call cannot diverge.
                return this.server.projectCallToolResult(result, tool.outputSchemaJson);
            } catch (error) {
                if (error instanceof ProtocolError && error.code === ProtocolErrorCode.UrlElicitationRequired) {
                    throw error; // Return the error to the caller without wrapping in CallToolResult
                }
                return this.createToolError(error instanceof Error ? error.message : String(error));
            }
        });

        this._toolHandlersInitialized = true;
    }

    /**
     * Creates a tool error result.
     *
     * @param errorMessage - The error message.
     * @returns The tool error result.
     */
    private createToolError(errorMessage: string): CallToolResult {
        return {
            content: [
                {
                    type: 'text',
                    text: errorMessage
                }
            ],
            isError: true
        };
    }

    /**
     * Validates tool input arguments against the tool's input schema.
     */
    private async validateToolInput<
        ToolType extends RegisteredTool,
        Args extends ToolType['inputSchema'] extends infer InputSchema
            ? InputSchema extends StandardSchemaWithJSON
                ? StandardSchemaWithJSON.InferOutput<InputSchema>
                : undefined
            : undefined
    >(tool: ToolType, args: Args, toolName: string): Promise<Args> {
        if (
            this._maxToolInputElements !== undefined &&
            toolInputElementCount(args, this._maxToolInputElements) > this._maxToolInputElements
        ) {
            throw new ProtocolError(
                ProtocolErrorCode.InvalidParams,
                `Invalid arguments for tool ${toolName}: arguments contain more than the maximum of ${this._maxToolInputElements} elements`
            );
        }

        if (!tool.inputSchema) {
            return undefined as Args;
        }

        const parseResult = await validateStandardSchema(tool.inputSchema, args ?? {});
        if (!parseResult.success) {
            throw new ProtocolError(
                ProtocolErrorCode.InvalidParams,
                `Input validation error: Invalid arguments for tool ${toolName}: ${parseResult.error}`
            );
        }

        return parseResult.data as unknown as Args;
    }

    /**
     * Validates tool output against the tool's output schema.
     */
    private async validateToolOutput(tool: RegisteredTool, result: CallToolResult | InputRequiredResult, toolName: string): Promise<void> {
        if (!tool.outputSchema) {
            return;
        }

        // An input-required result is not the tool's final output: structured
        // content is only required (and validated) on the completing result.
        if (isInputRequiredResult(result)) {
            return;
        }

        if (result.isError) {
            return;
        }

        // SEP-2106: `structuredContent` may legally be any JSON value including `null`, `0`,
        // `false`, `""`. The presence check is therefore `=== undefined` (not falsy); when present,
        // the value is ALWAYS validated against the output schema — a falsy value against an
        // object-typed schema fails validation, so this is not a guard weakening.
        if (result.structuredContent === undefined) {
            throw new ProtocolError(
                ProtocolErrorCode.InvalidParams,
                `Output validation error: Tool ${toolName} has an output schema but no structured content was provided`
            );
        }

        // if the tool has an output schema, validate structured content
        const parseResult = await validateStandardSchema(tool.outputSchema, result.structuredContent);
        if (!parseResult.success) {
            throw new ProtocolError(
                ProtocolErrorCode.InvalidParams,
                `Output validation error: Invalid structured content for tool ${toolName}: ${parseResult.error}`
            );
        }
    }

    /**
     * Executes a tool handler.
     */
    private async executeToolHandler(
        tool: RegisteredTool,
        args: unknown,
        ctx: ServerContext
    ): Promise<CallToolResult | InputRequiredResult> {
        // Executor encapsulates handler invocation with proper types
        return tool.executor(args, ctx);
    }

    private _completionHandlerInitialized = false;

    private setCompletionRequestHandler() {
        if (this._completionHandlerInitialized) {
            return;
        }

        this.server.assertCanSetRequestHandler('completion/complete');

        this.server.registerCapabilities({
            completions: {}
        });

        this.server.setRequestHandler('completion/complete', async (request): Promise<CompleteResult> => {
            switch (request.params.ref.type) {
                case 'ref/prompt': {
                    assertCompleteRequestPrompt(request);
                    return this.handlePromptCompletion(request, request.params.ref);
                }

                case 'ref/resource': {
                    assertCompleteRequestResourceTemplate(request);
                    return this.handleResourceCompletion(request, request.params.ref);
                }

                default: {
                    throw new ProtocolError(ProtocolErrorCode.InvalidParams, `Invalid completion reference: ${request.params.ref}`);
                }
            }
        });

        this._completionHandlerInitialized = true;
    }

    private async handlePromptCompletion(request: CompleteRequestPrompt, ref: PromptReference): Promise<CompleteResult> {
        const prompt = this._registeredPrompts[ref.name];
        if (!prompt) {
            throw new ProtocolError(ProtocolErrorCode.InvalidParams, `Prompt ${ref.name} not found`);
        }

        if (!prompt.enabled) {
            throw new ProtocolError(ProtocolErrorCode.InvalidParams, `Prompt ${ref.name} disabled`);
        }

        if (!prompt.argsSchema) {
            return EMPTY_COMPLETION_RESULT;
        }

        const promptShape = getSchemaShape(prompt.argsSchema);
        const field = unwrapOptionalSchema(promptShape?.[request.params.argument.name]);
        if (!isCompletable(field)) {
            return EMPTY_COMPLETION_RESULT;
        }

        const completer = getCompleter(field);
        if (!completer) {
            return EMPTY_COMPLETION_RESULT;
        }

        const suggestions = await completer(request.params.argument.value, request.params.context);
        return createCompletionResult(suggestions);
    }

    private async handleResourceCompletion(
        request: CompleteRequestResourceTemplate,
        ref: ResourceTemplateReference
    ): Promise<CompleteResult> {
        const template = Object.values(this._registeredResourceTemplates).find(t => t.resourceTemplate.uriTemplate.toString() === ref.uri);

        if (!template) {
            if (this._registeredResources[ref.uri]) {
                // Attempting to autocomplete a fixed resource URI is not an error in the spec (but probably should be).
                return EMPTY_COMPLETION_RESULT;
            }

            throw new ProtocolError(ProtocolErrorCode.InvalidParams, `Resource template ${request.params.ref.uri} not found`);
        }

        const completer = template.resourceTemplate.completeCallback(request.params.argument.name);
        if (!completer) {
            return EMPTY_COMPLETION_RESULT;
        }

        const suggestions = await completer(request.params.argument.value, request.params.context);
        return createCompletionResult(suggestions);
    }

    private _resourceHandlersInitialized = false;

    private setResourceRequestHandlers() {
        if (this._resourceHandlersInitialized) {
            return;
        }

        this.server.assertCanSetRequestHandler('resources/list');
        this.server.assertCanSetRequestHandler('resources/templates/list');
        this.server.assertCanSetRequestHandler('resources/read');

        this.server.registerCapabilities({
            resources: {
                listChanged: this.server.getCapabilities().resources?.listChanged ?? true
            }
        });

        this.server.setRequestHandler('resources/list', async (_request, ctx) => {
            const resources = Object.entries(this._registeredResources)
                .filter(([_, resource]) => resource.enabled)
                .map(([uri, resource]) => ({
                    uri,
                    name: resource.name,
                    ...resource.metadata
                }));

            const templateResources: Resource[] = [];
            for (const template of Object.values(this._registeredResourceTemplates)) {
                if (!template.resourceTemplate.listCallback) {
                    continue;
                }

                const result = await template.resourceTemplate.listCallback(ctx);
                for (const resource of result.resources) {
                    templateResources.push({
                        ...template.metadata,
                        // the defined resource metadata should override the template metadata if present
                        ...resource
                    });
                }
            }

            return { resources: [...resources, ...templateResources] };
        });

        this.server.setRequestHandler('resources/templates/list', async () => {
            const resourceTemplates = Object.entries(this._registeredResourceTemplates).map(([name, template]) => ({
                name,
                uriTemplate: template.resourceTemplate.uriTemplate.toString(),
                ...template.metadata
            }));

            return { resourceTemplates };
        });

        this.server.setRequestHandler('resources/read', async (request, ctx) => {
            let uri: URL;
            try {
                uri = new URL(request.params.uri);
            } catch {
                throw new ProtocolError(ProtocolErrorCode.InvalidParams, `Resource URI ${request.params.uri} is invalid`, {
                    uri: request.params.uri,
                    reason: 'invalid_uri'
                });
            }

            // First check for exact resource match
            const resource = this._registeredResources[uri.toString()];
            if (resource) {
                if (!resource.enabled) {
                    throw new ProtocolError(ProtocolErrorCode.InvalidParams, `Resource ${uri} disabled`);
                }
                // A per-resource cache hint is the most specific configured
                // author for this result's 2026-07-28 cache fields; it rides a
                // never-serialized carrier and is resolved at the encode seam.
                return attachCacheHintFallback(await resource.readCallback(uri, ctx), resource.cacheHint);
            }

            // Then check templates
            for (const template of Object.values(this._registeredResourceTemplates)) {
                const variables = template.resourceTemplate.uriTemplate.match(uri.toString());
                if (variables) {
                    if (!template.enabled) {
                        throw new ProtocolError(
                            ProtocolErrorCode.InvalidParams,
                            `Resource template ${template.resourceTemplate.uriTemplate} disabled`
                        );
                    }
                    return attachCacheHintFallback(await template.readCallback(uri, variables, ctx), template.cacheHint);
                }
            }

            // Domain layer throws one neutral resource-not-found error; the
            // era-aware encode seam (WireCodec.encodeErrorCode) selects the
            // wire code (−32602 on every era).
            throw new ResourceNotFoundError(request.params.uri);
        });

        this._resourceHandlersInitialized = true;
    }

    private _promptHandlersInitialized = false;

    private setPromptRequestHandlers() {
        if (this._promptHandlersInitialized) {
            return;
        }

        this.server.assertCanSetRequestHandler('prompts/list');
        this.server.assertCanSetRequestHandler('prompts/get');

        this.server.registerCapabilities({
            prompts: {
                listChanged: this.server.getCapabilities().prompts?.listChanged ?? true
            }
        });

        this.server.setRequestHandler(
            'prompts/list',
            (): ListPromptsResult => ({
                prompts: Object.entries(this._registeredPrompts)
                    .filter(([, prompt]) => prompt.enabled)
                    .map(([name, prompt]): Prompt => {
                        return {
                            name,
                            title: prompt.title,
                            description: prompt.description,
                            arguments: prompt.argsSchema ? promptArgumentsFromStandardSchema(prompt.argsSchema) : undefined,
                            icons: prompt.icons,
                            _meta: prompt._meta
                        };
                    })
            })
        );

        this.server.setRequestHandler('prompts/get', async (request, ctx): Promise<GetPromptResult | InputRequiredResult> => {
            const prompt = this._registeredPrompts[request.params.name];
            if (!prompt) {
                throw new ProtocolError(ProtocolErrorCode.InvalidParams, `Prompt ${request.params.name} not found`);
            }

            if (!prompt.enabled) {
                throw new ProtocolError(ProtocolErrorCode.InvalidParams, `Prompt ${request.params.name} disabled`);
            }

            // Handler encapsulates parsing and callback invocation with proper types
            return prompt.handler(request.params.arguments, ctx);
        });

        this._promptHandlersInitialized = true;
    }

    /**
     * Registers a resource with a config object and callback.
     * For static resources, use a URI string. For dynamic resources, use a {@linkcode ResourceTemplate}.
     *
     * @example
     * ```ts source="./mcp.examples.ts#McpServer_registerResource_static"
     * server.registerResource(
     *     'config',
     *     'config://app',
     *     {
     *         title: 'Application Config',
     *         mimeType: 'text/plain'
     *     },
     *     async uri => ({
     *         contents: [{ uri: uri.href, text: 'App configuration here' }]
     *     })
     * );
     * ```
     */
    registerResource(
        name: string,
        uriOrTemplate: string,
        config: ResourceMetadata & { cacheHint?: CacheHint; scopeChallenge?: ScopeChallengeHandler },
        readCallback: ReadResourceCallback
    ): RegisteredResource;
    registerResource(
        name: string,
        uriOrTemplate: ResourceTemplate,
        config: ResourceMetadata & { cacheHint?: CacheHint; scopeChallenge?: ScopeChallengeHandler },
        readCallback: ReadResourceTemplateCallback
    ): RegisteredResourceTemplate;
    registerResource(
        name: string,
        uriOrTemplate: string | ResourceTemplate,
        config: ResourceMetadata & { cacheHint?: CacheHint; scopeChallenge?: ScopeChallengeHandler },
        readCallback: ReadResourceCallback | ReadResourceTemplateCallback
    ): RegisteredResource | RegisteredResourceTemplate {
        // These options configure request handling and are not advertised as
        // resource metadata by `resources/list`.
        const { cacheHint, scopeChallenge, ...resourceMetadata } = config;
        const metadata: ResourceMetadata = resourceMetadata;
        if (cacheHint !== undefined) {
            assertValidCacheHint(cacheHint, `resource ${name}`);
        }

        if (typeof uriOrTemplate === 'string') {
            if (this._registeredResources[uriOrTemplate]) {
                throw new Error(`Resource ${uriOrTemplate} is already registered`);
            }

            const registeredResource = this._createRegisteredResource(
                name,
                (config as BaseMetadata).title,
                uriOrTemplate,
                metadata,
                scopeChallenge,
                readCallback as ReadResourceCallback
            );
            if (cacheHint !== undefined) {
                registeredResource.cacheHint = cacheHint;
            }

            this.setResourceRequestHandlers();
            this.sendResourceListChanged();
            return registeredResource;
        } else {
            if (this._registeredResourceTemplates[name]) {
                throw new Error(`Resource template ${name} is already registered`);
            }

            const registeredResourceTemplate = this._createRegisteredResourceTemplate(
                name,
                (config as BaseMetadata).title,
                uriOrTemplate,
                metadata,
                scopeChallenge,
                readCallback as ReadResourceTemplateCallback
            );
            if (cacheHint !== undefined) {
                registeredResourceTemplate.cacheHint = cacheHint;
            }

            this.setResourceRequestHandlers();
            this.sendResourceListChanged();
            return registeredResourceTemplate;
        }
    }

    private _createRegisteredResource(
        name: string,
        title: string | undefined,
        uri: string,
        metadata: ResourceMetadata | undefined,
        scopeChallenge: ScopeChallengeHandler | undefined,
        readCallback: ReadResourceCallback
    ): RegisteredResource {
        const registeredResource: RegisteredResource = {
            name,
            title,
            metadata,
            readCallback,
            scopeChallenge,
            enabled: true,
            disable: () => registeredResource.update({ enabled: false }),
            enable: () => registeredResource.update({ enabled: true }),
            remove: () => registeredResource.update({ uri: null }),
            update: updates => {
                if (updates.uri !== undefined && updates.uri !== uri) {
                    delete this._registeredResources[uri];
                    if (updates.uri) this._registeredResources[updates.uri] = registeredResource;
                }
                if (updates.name !== undefined) registeredResource.name = updates.name;
                if (updates.title !== undefined) registeredResource.title = updates.title;
                if (updates.metadata !== undefined) registeredResource.metadata = updates.metadata;
                if (updates.callback !== undefined) registeredResource.readCallback = updates.callback;
                if (updates.scopeChallenge !== undefined) {
                    registeredResource.scopeChallenge = updates.scopeChallenge === null ? undefined : updates.scopeChallenge;
                }
                if (updates.enabled !== undefined) registeredResource.enabled = updates.enabled;
                this.sendResourceListChanged();
            }
        };
        this._registeredResources[uri] = registeredResource;
        return registeredResource;
    }

    private _createRegisteredResourceTemplate(
        name: string,
        title: string | undefined,
        template: ResourceTemplate,
        metadata: ResourceMetadata | undefined,
        scopeChallenge: ScopeChallengeHandler | undefined,
        readCallback: ReadResourceTemplateCallback
    ): RegisteredResourceTemplate {
        const registeredResourceTemplate: RegisteredResourceTemplate = {
            resourceTemplate: template,
            title,
            metadata,
            readCallback,
            scopeChallenge,
            enabled: true,
            disable: () => registeredResourceTemplate.update({ enabled: false }),
            enable: () => registeredResourceTemplate.update({ enabled: true }),
            remove: () => registeredResourceTemplate.update({ name: null }),
            update: updates => {
                if (updates.name !== undefined && updates.name !== name) {
                    delete this._registeredResourceTemplates[name];
                    if (updates.name) this._registeredResourceTemplates[updates.name] = registeredResourceTemplate;
                }
                if (updates.title !== undefined) registeredResourceTemplate.title = updates.title;
                if (updates.template !== undefined) registeredResourceTemplate.resourceTemplate = updates.template;
                if (updates.metadata !== undefined) registeredResourceTemplate.metadata = updates.metadata;
                if (updates.callback !== undefined) registeredResourceTemplate.readCallback = updates.callback;
                if (updates.scopeChallenge !== undefined) {
                    registeredResourceTemplate.scopeChallenge = updates.scopeChallenge === null ? undefined : updates.scopeChallenge;
                }
                if (updates.enabled !== undefined) registeredResourceTemplate.enabled = updates.enabled;
                this.sendResourceListChanged();
            }
        };
        this._registeredResourceTemplates[name] = registeredResourceTemplate;

        // If the resource template has any completion callbacks, enable completions capability
        const variableNames = template.uriTemplate.variableNames;
        const hasCompleter = Array.isArray(variableNames) && variableNames.some(v => !!template.completeCallback(v));
        if (hasCompleter) {
            this.setCompletionRequestHandler();
        }

        return registeredResourceTemplate;
    }

    private _createRegisteredPrompt(
        name: string,
        title: string | undefined,
        description: string | undefined,
        argsSchema: StandardSchemaWithJSON | undefined,
        callback: PromptCallback<StandardSchemaWithJSON | undefined>,
        icons: Icon[] | undefined,
        scopeChallenge: ScopeChallengeHandler | undefined,
        _meta: Record<string, unknown> | undefined
    ): RegisteredPrompt {
        // Track current schema and callback for handler regeneration
        let currentArgsSchema = argsSchema;
        let currentCallback = callback;

        const registeredPrompt: RegisteredPrompt = {
            title,
            description,
            argsSchema,
            icons,
            scopeChallenge,
            _meta,
            handler: createPromptHandler(name, argsSchema, callback),
            enabled: true,
            disable: () => registeredPrompt.update({ enabled: false }),
            enable: () => registeredPrompt.update({ enabled: true }),
            remove: () => registeredPrompt.update({ name: null }),
            update: updates => {
                if (updates.name !== undefined && updates.name !== name) {
                    delete this._registeredPrompts[name];
                    if (updates.name) this._registeredPrompts[updates.name] = registeredPrompt;
                }
                if (updates.title !== undefined) registeredPrompt.title = updates.title;
                if (updates.description !== undefined) registeredPrompt.description = updates.description;
                if (updates.icons !== undefined) registeredPrompt.icons = updates.icons;
                if (updates.scopeChallenge !== undefined) {
                    registeredPrompt.scopeChallenge = updates.scopeChallenge === null ? undefined : updates.scopeChallenge;
                }
                if (updates._meta !== undefined) registeredPrompt._meta = updates._meta;

                // Track if we need to regenerate the handler
                let needsHandlerRegen = false;
                if (updates.argsSchema !== undefined) {
                    registeredPrompt.argsSchema = updates.argsSchema;
                    currentArgsSchema = updates.argsSchema;
                    needsHandlerRegen = true;
                }
                if (updates.callback !== undefined) {
                    currentCallback = updates.callback as PromptCallback<StandardSchemaWithJSON | undefined>;
                    needsHandlerRegen = true;
                }
                if (needsHandlerRegen) {
                    registeredPrompt.handler = createPromptHandler(name, currentArgsSchema, currentCallback);
                }

                if (updates.enabled !== undefined) registeredPrompt.enabled = updates.enabled;
                this.sendPromptListChanged();
            }
        };
        this._registeredPrompts[name] = registeredPrompt;

        // If any argument uses a Completable schema, enable completions capability
        if (argsSchema) {
            const shape = getSchemaShape(argsSchema);
            if (shape) {
                const hasCompletable = Object.values(shape).some(field => {
                    const inner = unwrapOptionalSchema(field);
                    return isCompletable(inner);
                });
                if (hasCompletable) {
                    this.setCompletionRequestHandler();
                }
            }
        }

        return registeredPrompt;
    }

    private _createRegisteredTool(
        name: string,
        title: string | undefined,
        description: string | undefined,
        inputSchema: StandardSchemaWithJSON | undefined,
        outputSchema: StandardSchemaWithJSON | undefined,
        annotations: ToolAnnotations | undefined,
        icons: Icon[] | undefined,
        execution: ToolExecution | undefined,
        scopeChallenge: ScopeChallengeHandler | undefined,
        _meta: Record<string, unknown> | undefined,
        handler: AnyToolHandler<StandardSchemaWithJSON | undefined>
    ): RegisteredTool {
        // Validate tool name according to SEP specification
        validateAndWarnToolName(name);

        // Track current handler for executor regeneration
        let currentHandler = handler;

        let outputSchemaJson: Record<string, unknown> | undefined;
        const registeredTool: RegisteredTool = {
            title,
            description,
            inputSchema,
            outputSchema,
            get outputSchemaJson() {
                return (outputSchemaJson ??= convertOutputSchemaJson(registeredTool.outputSchema));
            },
            set outputSchemaJson(value) {
                outputSchemaJson = value;
            },
            annotations,
            icons,
            execution,
            scopeChallenge,
            _meta,
            handler: handler,
            executor: createToolExecutor(inputSchema, handler),
            enabled: true,
            disable: () => registeredTool.update({ enabled: false }),
            enable: () => registeredTool.update({ enabled: true }),
            remove: () => registeredTool.update({ name: null }),
            update: updates => {
                // The closure's `name` tracks the CURRENT registry key, not
                // the original registration name — renaming reassigns it so
                // subsequent paramsSchema/rename invalidations evict the live
                // `_toolInputSchemaJson` slot rather than the original.
                if (updates.name !== undefined && updates.name !== name) {
                    if (typeof updates.name === 'string') {
                        validateAndWarnToolName(updates.name);
                    }
                    delete this._registeredTools[name];
                    delete this._toolInputSchemaJson[name];
                    if (updates.name) {
                        // The TARGET key may already be occupied by another
                        // tool (rename has no duplicate-name guard) — drop
                        // its memo too, otherwise `toolInputSchemaJson()`
                        // returns the displaced tool's converted schema and
                        // the SEP-2243 pre-dispatch validation runs against
                        // the wrong schema for this name.
                        delete this._toolInputSchemaJson[updates.name];
                        this._registeredTools[updates.name] = registeredTool;
                        name = updates.name;
                    }
                }
                if (updates.title !== undefined) registeredTool.title = updates.title;
                if (updates.description !== undefined) registeredTool.description = updates.description;

                // Track if we need to regenerate the executor
                let needsExecutorRegen = false;
                if (updates.paramsSchema !== undefined) {
                    registeredTool.inputSchema = updates.paramsSchema;
                    delete this._toolInputSchemaJson[name];
                    needsExecutorRegen = true;
                }
                if (updates.callback !== undefined) {
                    registeredTool.handler = updates.callback;
                    currentHandler = updates.callback as AnyToolHandler<StandardSchemaWithJSON | undefined>;
                    needsExecutorRegen = true;
                }
                if (needsExecutorRegen) {
                    registeredTool.executor = createToolExecutor(registeredTool.inputSchema, currentHandler);
                }

                if (updates.outputSchema !== undefined) {
                    registeredTool.outputSchema = updates.outputSchema;
                    registeredTool.outputSchemaJson = convertOutputSchemaJson(updates.outputSchema);
                }
                if (updates.annotations !== undefined) registeredTool.annotations = updates.annotations;
                if (updates.icons !== undefined) registeredTool.icons = updates.icons;
                if (updates.scopeChallenge !== undefined) {
                    registeredTool.scopeChallenge = updates.scopeChallenge === null ? undefined : updates.scopeChallenge;
                }
                if (updates._meta !== undefined) registeredTool._meta = updates._meta;
                if (updates.enabled !== undefined) registeredTool.enabled = updates.enabled;
                this.sendToolListChanged();
            }
        };
        this._registeredTools[name] = registeredTool;

        this.setToolRequestHandlers();
        this.sendToolListChanged();

        return registeredTool;
    }

    /**
     * Registers a tool with a config object and callback.
     *
     * @example
     * ```ts source="./mcp.examples.ts#McpServer_registerTool_basic"
     * server.registerTool(
     *     'calculate-bmi',
     *     {
     *         title: 'BMI Calculator',
     *         description: 'Calculate Body Mass Index',
     *         inputSchema: z.object({
     *             weightKg: z.number(),
     *             heightM: z.number()
     *         }),
     *         outputSchema: z.object({ bmi: z.number() })
     *     },
     *     async ({ weightKg, heightM }) => {
     *         const output = { bmi: weightKg / (heightM * heightM) };
     *         return {
     *             content: [{ type: 'text', text: JSON.stringify(output) }],
     *             structuredContent: output
     *         };
     *     }
     * );
     * ```
     */
    registerTool<OutputArgs extends StandardSchemaWithJSON, InputArgs extends StandardSchemaWithJSON | undefined = undefined>(
        name: string,
        config: {
            title?: string;
            description?: string;
            inputSchema?: InputArgs;
            outputSchema?: OutputArgs;
            annotations?: ToolAnnotations;
            icons?: Icon[];
            /** Determines whether this tool call needs an OAuth scope challenge. */
            scopeChallenge?: ScopeChallengeHandler;
            _meta?: Record<string, unknown>;
        },
        cb: ToolCallback<InputArgs>
    ): RegisteredTool;
    /** @deprecated Wrap with `z.object({...})` instead. Raw-shape form: `inputSchema`/`outputSchema` may be a plain `{ field: z.string() }` record; it is auto-wrapped with `z.object()`. */
    registerTool<InputArgs extends ZodRawShape, OutputArgs extends ZodRawShape | StandardSchemaWithJSON | undefined = undefined>(
        name: string,
        config: {
            title?: string;
            description?: string;
            inputSchema?: InputArgs;
            outputSchema?: OutputArgs;
            annotations?: ToolAnnotations;
            icons?: Icon[];
            scopeChallenge?: ScopeChallengeHandler;
            _meta?: Record<string, unknown>;
        },
        cb: LegacyToolCallback<InputArgs>
    ): RegisteredTool;
    registerTool(
        name: string,
        config: {
            title?: string;
            description?: string;
            inputSchema?: StandardSchemaWithJSON | ZodRawShape;
            outputSchema?: StandardSchemaWithJSON | ZodRawShape;
            annotations?: ToolAnnotations;
            icons?: Icon[];
            scopeChallenge?: ScopeChallengeHandler;
            _meta?: Record<string, unknown>;
        },
        cb: ToolCallback<StandardSchemaWithJSON | undefined> | LegacyToolCallback<ZodRawShape>
    ): RegisteredTool {
        if (this._registeredTools[name]) {
            throw new Error(`Tool ${name} is already registered`);
        }

        const { title, description, inputSchema, outputSchema, annotations, icons, scopeChallenge, _meta } = config;
        return this._createRegisteredTool(
            name,
            title,
            description,
            normalizeRawShapeSchema(inputSchema),
            normalizeRawShapeSchema(outputSchema),
            annotations,
            icons,
            undefined,
            scopeChallenge,
            _meta,
            cb as ToolCallback<StandardSchemaWithJSON | undefined>
        );
    }

    /**
     * Registers a prompt with a config object and callback.
     *
     * @example
     * ```ts source="./mcp.examples.ts#McpServer_registerPrompt_basic"
     * server.registerPrompt(
     *     'review-code',
     *     {
     *         title: 'Code Review',
     *         description: 'Review code for best practices',
     *         argsSchema: z.object({ code: z.string() })
     *     },
     *     ({ code }) => ({
     *         messages: [
     *             {
     *                 role: 'user' as const,
     *                 content: {
     *                     type: 'text' as const,
     *                     text: `Please review this code:\n\n${code}`
     *                 }
     *             }
     *         ]
     *     })
     * );
     * ```
     */
    registerPrompt(
        name: string,
        config: {
            title?: string;
            description?: string;
            argsSchema?: undefined;
            icons?: Icon[];
            /** Determines whether this prompt retrieval needs an OAuth scope challenge. */
            scopeChallenge?: ScopeChallengeHandler;
            _meta?: Record<string, unknown>;
        },
        cb: PromptCallback
    ): RegisteredPrompt;
    registerPrompt<Args extends StandardSchemaWithJSON>(
        name: string,
        config: {
            title?: string;
            description?: string;
            argsSchema?: Args;
            icons?: Icon[];
            /** Determines whether this prompt retrieval needs an OAuth scope challenge. */
            scopeChallenge?: ScopeChallengeHandler;
            _meta?: Record<string, unknown>;
        },
        cb: PromptCallback<Args>
    ): RegisteredPrompt;
    /** @deprecated Wrap with `z.object({...})` instead. Raw-shape form: `argsSchema` may be a plain `{ field: z.string() }` record; it is auto-wrapped with `z.object()`. */
    registerPrompt<Args extends ZodRawShape>(
        name: string,
        config: {
            title?: string;
            description?: string;
            argsSchema?: Args;
            icons?: Icon[];
            scopeChallenge?: ScopeChallengeHandler;
            _meta?: Record<string, unknown>;
        },
        cb: LegacyPromptCallback<Args>
    ): RegisteredPrompt;
    registerPrompt(
        name: string,
        config: {
            title?: string;
            description?: string;
            argsSchema?: StandardSchemaWithJSON | ZodRawShape;
            icons?: Icon[];
            scopeChallenge?: ScopeChallengeHandler;
            _meta?: Record<string, unknown>;
        },
        cb: PromptCallback | PromptCallback<StandardSchemaWithJSON> | LegacyPromptCallback<ZodRawShape>
    ): RegisteredPrompt {
        if (this._registeredPrompts[name]) {
            throw new Error(`Prompt ${name} is already registered`);
        }

        const { title, description, argsSchema, icons, scopeChallenge, _meta } = config;

        const registeredPrompt = this._createRegisteredPrompt(
            name,
            title,
            description,
            normalizeRawShapeSchema(argsSchema),
            cb as PromptCallback<StandardSchemaWithJSON | undefined>,
            icons,
            scopeChallenge,
            _meta
        );

        this.setPromptRequestHandlers();
        this.sendPromptListChanged();

        return registeredPrompt;
    }

    /**
     * Checks if the server is connected to a transport.
     * @returns `true` if the server is connected
     */
    isConnected() {
        return this.server.transport !== undefined;
    }

    /**
     * Sends a logging message to the client, if connected.
     * Note: You only need to send the parameters object, not the entire JSON-RPC message.
     * @see {@linkcode LoggingMessageNotification}
     * @param params
     * @param sessionId Optional for stateless transports and backward compatibility.
     *
     * @example
     * ```ts source="./mcp.examples.ts#McpServer_sendLoggingMessage_basic"
     * await server.sendLoggingMessage({
     *     level: 'info',
     *     data: 'Processing complete'
     * });
     * ```
     *
     * @deprecated Deprecated as of protocol version 2026-07-28 (SEP-2577).
     * Remains functional during the deprecation window (at least twelve months).
     * Migrate to stderr logging (STDIO servers) or OpenTelemetry.
     */
    async sendLoggingMessage(params: LoggingMessageNotification['params'], sessionId?: string) {
        return this.server.sendLoggingMessage(params, sessionId);
    }
    /**
     * Sends a resource list changed event to the client, if connected.
     */
    sendResourceListChanged() {
        if (this.isConnected()) {
            this.server.sendResourceListChanged();
        }
    }

    /**
     * Sends a tool list changed event to the client, if connected.
     */
    sendToolListChanged() {
        if (this.isConnected()) {
            this.server.sendToolListChanged();
        }
    }

    /**
     * Sends a prompt list changed event to the client, if connected.
     */
    sendPromptListChanged() {
        if (this.isConnected()) {
            this.server.sendPromptListChanged();
        }
    }
}

/**
 * A callback to complete one variable within a resource template's URI template.
 */
export type CompleteResourceTemplateCallback = (
    value: string,
    context?: {
        arguments?: Record<string, string>;
    }
) => string[] | Promise<string[]>;

/**
 * A resource template combines a URI pattern with optional functionality to enumerate
 * all resources matching that pattern.
 */
export class ResourceTemplate {
    private _uriTemplate: UriTemplate;

    constructor(
        uriTemplate: string | UriTemplate,
        private _callbacks: {
            /**
             * A callback to list all resources matching this template. This is required to be specified, even if `undefined`, to avoid accidentally forgetting resource listing.
             */
            list: ListResourcesCallback | undefined;

            /**
             * An optional callback to autocomplete variables within the URI template. Useful for clients and users to discover possible values.
             */
            complete?: {
                [variable: string]: CompleteResourceTemplateCallback;
            };
        }
    ) {
        this._uriTemplate = typeof uriTemplate === 'string' ? new UriTemplate(uriTemplate) : uriTemplate;
    }

    /**
     * Gets the URI template pattern.
     */
    get uriTemplate(): UriTemplate {
        return this._uriTemplate;
    }

    /**
     * Gets the list callback, if one was provided.
     */
    get listCallback(): ListResourcesCallback | undefined {
        return this._callbacks.list;
    }

    /**
     * Gets the callback for completing a specific URI template variable, if one was provided.
     */
    completeCallback(variable: string): CompleteResourceTemplateCallback | undefined {
        return this._callbacks.complete?.[variable];
    }
}

/**
 * A plain record of Zod field schemas, e.g. `{ name: z.string() }`. Accepted by
 * `registerTool`/`registerPrompt` as a shorthand; auto-wrapped with `z.object()`.
 * Zod schemas only — `z.object()` cannot wrap other Standard Schema libraries.
 */
export type ZodRawShape = Record<string, z.ZodType>;

/** Infers the parsed-output type of a {@linkcode ZodRawShape}. */
export type InferRawShape<S extends ZodRawShape> = z.infer<z.ZodObject<S>>;

/** {@linkcode ToolCallback} variant used when `inputSchema` is a {@linkcode ZodRawShape}. */
export type LegacyToolCallback<Args extends ZodRawShape | undefined> = Args extends ZodRawShape
    ? (
          args: InferRawShape<Args>,
          ctx: ServerContext
      ) => CallToolResult | InputRequiredResult | Promise<CallToolResult | InputRequiredResult>
    : (ctx: ServerContext) => CallToolResult | InputRequiredResult | Promise<CallToolResult | InputRequiredResult>;

/** {@linkcode PromptCallback} variant used when `argsSchema` is a {@linkcode ZodRawShape}. */
export type LegacyPromptCallback<Args extends ZodRawShape | undefined> = Args extends ZodRawShape
    ? (
          args: InferRawShape<Args>,
          ctx: ServerContext
      ) => GetPromptResult | InputRequiredResult | Promise<GetPromptResult | InputRequiredResult>
    : (ctx: ServerContext) => GetPromptResult | InputRequiredResult | Promise<GetPromptResult | InputRequiredResult>;

export type BaseToolCallback<
    SendResultT extends Result,
    Ctx extends ServerContext,
    Args extends StandardSchemaWithJSON | undefined
> = Args extends StandardSchemaWithJSON
    ? (args: StandardSchemaWithJSON.InferOutput<Args>, ctx: Ctx) => SendResultT | Promise<SendResultT>
    : (ctx: Ctx) => SendResultT | Promise<SendResultT>;

/**
 * Callback for a tool handler registered with {@linkcode McpServer.registerTool}.
 */
export type ToolCallback<Args extends StandardSchemaWithJSON | undefined = undefined> = BaseToolCallback<
    CallToolResult | InputRequiredResult,
    ServerContext,
    Args
>;

/**
 * Tool handler callback type.
 */
export type AnyToolHandler<Args extends StandardSchemaWithJSON | undefined = undefined> = ToolCallback<Args>;

/**
 * Internal executor type that encapsulates handler invocation with proper types.
 */
type ToolExecutor = (args: unknown, ctx: ServerContext) => Promise<CallToolResult | InputRequiredResult>;

export type RegisteredTool = {
    title?: string;
    description?: string;
    inputSchema?: StandardSchemaWithJSON;
    outputSchema?: StandardSchemaWithJSON;
    /**
     * @hidden
     * The converted JSON Schema of `outputSchema`, memoised on first use (and on
     * `update({outputSchema})`) so the `tools/call` handler passes the SAME advertised schema
     * `tools/list` emits to the wire codec's `projectCallToolResult` — the SEP-2106 `{result:…}`
     * wrap predicate follows the schema's root, never the runtime value shape. `undefined` when
     * no `outputSchema` is registered or its conversion threw (see {@link convertOutputSchemaJson}).
     */
    outputSchemaJson?: Record<string, unknown>;
    annotations?: ToolAnnotations;
    icons?: Icon[];
    execution?: ToolExecution;
    scopeChallenge?: ScopeChallengeHandler;
    _meta?: Record<string, unknown>;
    handler: AnyToolHandler<StandardSchemaWithJSON | undefined>;
    /** @hidden */
    executor: ToolExecutor;
    enabled: boolean;
    enable(): void;
    disable(): void;
    update(updates: {
        name?: string | null;
        title?: string;
        description?: string;
        paramsSchema?: StandardSchemaWithJSON;
        outputSchema?: StandardSchemaWithJSON;
        annotations?: ToolAnnotations;
        icons?: Icon[];
        scopeChallenge?: ScopeChallengeHandler | null;
        _meta?: Record<string, unknown>;
        callback?: ToolCallback<StandardSchemaWithJSON>;
        enabled?: boolean;
    }): void;
    remove(): void;
};

/**
 * Creates an executor that invokes the handler with the appropriate arguments.
 * When `inputSchema` is defined, the handler is called with `(args, ctx)`.
 * When `inputSchema` is undefined, the handler is called with just `(ctx)`.
 */
function createToolExecutor(
    inputSchema: StandardSchemaWithJSON | undefined,
    handler: AnyToolHandler<StandardSchemaWithJSON | undefined>
): ToolExecutor {
    if (inputSchema) {
        const callback = handler as ToolCallbackInternal;
        return async (args, ctx) => callback(args, ctx);
    }

    // When no inputSchema, call with just ctx (the handler expects (ctx) signature)
    const callback = handler as (
        ctx: ServerContext
    ) => CallToolResult | InputRequiredResult | Promise<CallToolResult | InputRequiredResult>;
    return async (_args, ctx) => callback(ctx);
}

const EMPTY_OBJECT_JSON_SCHEMA = {
    type: 'object' as const,
    properties: {}
};

/** Converts a tool's `inputSchema` for `tools/list` and warns on an invalid SEP-2243 `x-mcp-header` declaration. */
function convertListedInputSchema(name: string, inputSchema: StandardSchemaWithJSON): Record<string, unknown> {
    const json = standardSchemaToJsonSchema(inputSchema, 'input');
    const scan = scanXMcpHeaderDeclarations(json);
    if (!scan.valid) {
        console.warn(
            `[mcp-sdk] tool '${name}' carries an invalid x-mcp-header declaration and will be excluded by ` +
                `conforming Streamable HTTP clients: ${scan.reason}`
        );
    }
    return json;
}

/**
 * Convert a registered `outputSchema` to JSON Schema, memoised on {@link RegisteredTool.outputSchemaJson}
 * so `tools/call` passes the SAME advertised schema to the wire codec's `projectCallToolResult` that
 * `tools/list` emits (and that the 2025 codec's `encodeResult('tools/list', …)` may wrap). A conversion
 * failure yields `undefined` so the failure surfaces where it always has (`tools/list`).
 */
function convertOutputSchemaJson(outputSchema: StandardSchemaWithJSON | undefined): Record<string, unknown> | undefined {
    if (outputSchema === undefined) return undefined;
    try {
        return standardSchemaToJsonSchema(outputSchema, 'output');
    } catch {
        return undefined;
    }
}

/**
 * Additional, optional information for annotating a resource.
 */
export type ResourceMetadata = Omit<Resource, 'uri' | 'name'>;

/**
 * Callback to list all resources matching a given template.
