                if (key in value) {
                    ctx.addIssue({
                        code: 'custom',
                        message: `content is required when the body carries '${key}' — another result family cannot default into an empty tools/call success`
                    });
                    return;
                }
            }
        })
        .transform(normalizeContentlessToolResult)
        .pipe(CallToolResultSchema);

    return {
