    /* ------------------------------------------------------------------------ *
     * Response envelopes (wire-true; parity/corpus artifacts).
     * ------------------------------------------------------------------------ */
    const wireResultResponse = <T extends z.ZodType>(result: T) =>
        z
            .object({
                jsonrpc: z.literal('2.0'),
