    if (!isPlainObject(entry) || typeof entry['method'] !== 'string') {
        throw new SdkError(
            SdkErrorCode.InvalidResult,
            `Invalid input request '${key}': each inputRequests entry must be an embedded request object with a method`,
            { key }
