        config,
        method: request.method,
        originalParams: request.params,
        firstPayload,
        flowStartedAt,
        signal: options?.signal,
        requestOptions: {
            ...(options?.timeout !== undefined && { timeout: options.timeout }),
            ...(options?.maxTotalTimeout !== undefined && { maxTotalTimeout: options.maxTotalTimeout }),
