    // and (since 3.24) `~standard.vendor === 'zod'`, but never `_zod`. We require
    // v4 because the wrap path below uses v4's `z.object()`, which cannot consume
    // v3 field schemas.
    return typeof v === 'object' && v !== null && '_zod' in v;
