 * // from '@modelcontextprotocol/server' or '@modelcontextprotocol/client' —
 * // each package bundles its own schema copy, so warm the one(s) you import.
 * preloadSchemas(); // module scope — runs during isolate warm-up
 * ```
 *
 * On Node CLIs and other process-per-invocation runtimes, prefer the lazy
 * default — there, module-scope construction is pure added boot latency.
 */
export function preloadSchemas(): void {
    // The era schema factories — the bulk of the construction cost.
    buildSchemas2025();
    buildSchemas2026();
    // The memoized lookup layers above the factories. (The 2026 registry has
    // no map memo of its own — it reads the dispatch maps straight off the
    // built schema set.)
    warmRegistryMaps2025();
    warmInputSchemaMaps2026();
    warmWireResultSchemas2026();
}
import type { StandardSchemaV1, StandardSchemaWithJSON } from '../util/standardSchema';
import type { JsonSchemaType, jsonSchemaValidator } from './types';

/**
 * Wrap a raw JSON Schema object as a {@linkcode StandardSchemaWithJSON} so it can be
 * passed to `registerTool` / `registerPrompt`. Use this when you already have JSON
 * Schema (e.g. from TypeBox, or hand-written) and want to register it without going
 * through a Standard Schema library.
 *
 * The callback arguments will be typed `unknown` (raw JSON Schema has no TypeScript
 * types attached). Cast at the call site, or use the generic `fromJsonSchema<MyType>(...)`.
 *
 * @param schema - A JSON Schema object describing the expected shape
 * @param validator - A validator provider. When importing `fromJsonSchema` from
 *   `@modelcontextprotocol/server` or `@modelcontextprotocol/client`, a runtime-appropriate
 *   default is provided automatically (AJV on Node.js, CfWorker on edge runtimes).
 *
 * @example
 * ```ts source="./fromJsonSchema.examples.ts#fromJsonSchema_basicUsage"
 * const inputSchema = fromJsonSchema<{ name: string }>(
 *     { type: 'object', properties: { name: { type: 'string' } }, required: ['name'] },
 *     validator
 * );
 * // Use with server.registerTool('greet', { inputSchema }, handler)
 * ```
 */
export function fromJsonSchema<T = unknown>(schema: JsonSchemaType, validator: jsonSchemaValidator): StandardSchemaWithJSON<T, T> {
    const check = validator.getValidator<T>(schema);
    return {
        '~standard': {
            version: 1,
            vendor: 'mcp',
            jsonSchema: {
                input: () => schema as Record<string, unknown>,
                output: () => schema as Record<string, unknown>
            },
            validate: (data: unknown): StandardSchemaV1.Result<T> => {
                const result = check(data);
                return result.valid ? { value: result.data } : { issues: [{ message: result.errorMessage }] };
            }
        }
    };
}

/**
 * Declared-dialect classification shared by the default validator providers.
 */

import type { JsonSchemaType } from './types';

/**
 * Canonical `$schema` URIs per supported dialect (http + https variants, trailing-`#` stripped).
 */
const DRAFT_2020_12_URIS: ReadonlySet<string> = new Set([
    'https://json-schema.org/draft/2020-12/schema',
    'http://json-schema.org/draft/2020-12/schema'
]);
const DRAFT_2019_09_URIS: ReadonlySet<string> = new Set([
    'https://json-schema.org/draft/2019-09/schema',
    'http://json-schema.org/draft/2019-09/schema'
]);
const DRAFT_07_URIS: ReadonlySet<string> = new Set(['https://json-schema.org/draft-07/schema', 'http://json-schema.org/draft-07/schema']);
const DRAFT_06_URIS: ReadonlySet<string> = new Set(['https://json-schema.org/draft-06/schema', 'http://json-schema.org/draft-06/schema']);

/**
 * Dialects the default providers dispatch on. draft-06 maps to `'draft-7'`: draft-07 only adds
 * keywords over draft-06 (`if`/`then`/`else`), and enforcing them on a draft-06 schema is the
 * accepted downlevel.
 */
export type DeclaredDialect = '2020-12' | '2019-09' | 'draft-7';

/**
 * Whether a `$schema` value declares the 2019-09 dialect — the only supported dialect with
 * `$recursiveRef`/`$recursiveAnchor`. Non-throwing (unlike {@linkcode declaredDialect}) so
 * wire-layer callers can consult it for documents whose dialect may be unsupported.
 */
export function declares2019Dialect($schema: unknown): boolean {
    return typeof $schema === 'string' && DRAFT_2019_09_URIS.has($schema.replace(/#$/, ''));
}

/**
 * Classify a schema's declared `$schema` dialect. No `$schema` (or a non-string one) means
 * 2020-12. Any other dialect throws a plain `Error` with a clear message rather than letting the
 * engine crash on an opaque internal error or silently mis-validate; `remedy` names the calling
 * provider's escape hatch in that message.
 */
export function declaredDialect(schema: JsonSchemaType, remedy: string): DeclaredDialect {
    if (!('$schema' in schema) || typeof schema.$schema !== 'string') {
        return '2020-12';
    }
    const declared = schema.$schema.replace(/#$/, '');
    if (DRAFT_2020_12_URIS.has(declared)) {
        return '2020-12';
    }
    if (DRAFT_2019_09_URIS.has(declared)) {
        return '2019-09';
    }
    if (DRAFT_07_URIS.has(declared) || DRAFT_06_URIS.has(declared)) {
        return 'draft-7';
    }
    throw new Error(
        `JSON Schema declares an unsupported dialect ("$schema": "${schema.$schema.slice(0, 200)}"). ` +
            `The default validator supports JSON Schema 2020-12, 2019-09, draft-07, and draft-06; ${remedy}`
    );
}

