 *   entry's modern path).
 * - A `server/discover` probe is answered by an optimistically built modern
 *   instance but does NOT pin the connection yet: the spec's stdio
 *   backward-compatibility flow lets a client probe first and then either
 *   continue with modern requests (which pins the connection modern) or fall
 *   back to the `initialize` handshake when no mutually supported modern
 *   revision exists — in which case the probe instance is discarded and a
 *   fresh legacy instance serves the handshake.
 * - Once the modern era is pinned, a later claim-less `initialize` is
 *   rejected with the unsupported-protocol-version error naming the supported
 *   revisions (the spec recommends naming them in any error returned to
 *   `initialize`, and forbids falling back once the modern era is confirmed).
 *
 * Every instance the factory produces serves exactly one era; the ambiguity
 * of the opening exchange lives entirely in this entry. In the probe-fallback
 * case the factory is called twice (once for the discarded probe instance,
 * once for the legacy instance), so factories should be cheap and
 * side-effect-free to construct — the same expectation `createMcpHandler`
 * already sets for per-request construction.
 *
 * Hand-constructed servers connected directly to a `StdioServerTransport`
 * are unaffected by this entry: they keep serving the 2025-era protocol they
 * were written for.
 */
import type {
    CancelledNotificationParams,
    JSONRPCMessage,
    JSONRPCNotification,
    JSONRPCRequest,
    MessageClassification,
    MessageExtraInfo,
    RequestId,
    Transport,
    TransportSendOptions
} from '@modelcontextprotocol/core-internal';
import {
    carriesValidModernEnvelopeClaim,
    envelopeClaimVersion,
    hasEnvelopeClaim,
    isJSONRPCErrorResponse,
    isJSONRPCNotification,
    isJSONRPCRequest,
    isJSONRPCResultResponse,
    modernOnlyStrictRejection,
    ProtocolErrorCode,
    requestMetaOf,
    setNegotiatedProtocolVersion,
    SUPPORTED_MODERN_PROTOCOL_VERSIONS,
    UnsupportedProtocolVersionError,
    validateEnvelopeMeta
} from '@modelcontextprotocol/core-internal';

import type { McpServerFactory } from './createMcpHandler';
import { DEFAULT_MAX_SUBSCRIPTIONS, StdioListenRouter } from './listenRouter';
import { McpServer } from './mcp';
import type { Server } from './server';
import { installModernOnlyHandlers, serverIdentityOf } from './server';
import { StdioServerTransport } from './stdio';

/** Options for {@linkcode serveStdio}. */
export interface ServeStdioOptions {
    /**
     * How a 2025-era opening (an `initialize` request, or any claim-less
     * message) is handled:
     *
     * - `'serve'` (default) — the connection is pinned to a 2025-era instance
     *   from the same factory and served exactly as a hand-wired stdio server
     *   serves it today.
     * - `'reject'` — the opening request is answered with the
     *   unsupported-protocol-version error naming the supported modern
     *   revisions (claim-less notifications are dropped); the connection
     *   stays open for a modern opening.
     */
    legacy?: 'serve' | 'reject';
    /**
     * Bring your own transport (for example a `StdioServerTransport`
     * constructed over a Unix domain socket or TCP stream, per the stdio
     * binding's custom-transport guidance). Defaults to a
     * {@linkcode StdioServerTransport} over the current process's stdio. The
     * entry owns the transport: it starts it, receives every inbound message,
     * and closes it when the connection ends.
     */
    transport?: Transport;
    /** Callback for out-of-band errors (reporting only; it never alters what is written to the wire). */
    onerror?: (error: Error) => void;
    /**
     * Reject a new `subscriptions/listen` with `-32603` 'Subscription limit
     * reached' (in-band, before the ack) when this many subscriptions are
     * already open on this connection.
     * @default 1024
     */
    maxSubscriptions?: number;
}

/** The handle returned by {@linkcode serveStdio}. */
export interface StdioServerHandle {
    /** Tears the connection down: closes the pinned instance (if any) and the underlying transport. */
    close(): Promise<void>;
}

/* ------------------------------------------------------------------------ *
 * Per-instance channel
 * ------------------------------------------------------------------------ */

/**
 * How long the probe-discard path waits for the probe instance to answer the
 * requests it was delivered before closing it. The wait normally settles as
 * soon as the DiscoverResult is handed to the wire (or immediately, when a
 * delivered cancellation already settled the probe); the bound is a backstop
 * so no edge can ever hold the connection's inbound pump indefinitely behind
 * the discard.
 */
const DISCARD_ANSWER_TIMEOUT_MS = 3000;

/**
 * The transport a pinned instance is connected to: a thin channel that writes
 * through to the entry-owned wire transport and receives the messages the
 * entry forwards. The wire transport itself is never handed to an instance —
 * that is what lets the entry discard an optimistic probe instance (close the
 * channel) without tearing down the connection.
 */
class StdioConnectionChannel implements Transport {
    onclose?: () => void;
    onerror?: (error: Error) => void;
    onmessage?: <T extends JSONRPCMessage>(message: T, extra?: MessageExtraInfo) => void;

    private _closed = false;
    /** Request ids the entry delivered to the instance that the instance has not yet answered. */
    private readonly _pendingRequests = new Set<RequestId>();
    private _drainWaiters: Array<() => void> = [];

    constructor(
        private readonly _wire: Transport,
        private readonly _onInstanceClose: () => void,
        /**
         * Optional first-look on outbound messages. When set and returning
         * `'handled'`, the channel does not write the message to the wire
         * (the entry already wrote whatever was appropriate). Used by the
         * modern-era listen router to fan a change notification out onto the
         * active subscriptions instead of broadcasting it unsolicited.
         */
        private readonly _outboundIntercept?: (message: JSONRPCMessage) => 'handled' | undefined
    ) {}

    async start(): Promise<void> {
        // The entry already started the wire transport; connecting an
        // instance to its channel must not start anything again.
    }

    async send(message: JSONRPCMessage, options?: TransportSendOptions): Promise<void> {
        if (isJSONRPCResultResponse(message) || isJSONRPCErrorResponse(message)) {
            // The instance answered a delivered request: settle it whether or
            // not the wire write below succeeds (write failures surface
            // through the wire's own error reporting).
            const { id } = message;
            if (id !== undefined) {
                this._settle(id);
            }
        }
        if (this._closed) {
            // A discarded or torn-down instance has nowhere to write; late
            // sends are dropped.
            return;
        }
        if (this._outboundIntercept?.(message) === 'handled') {
            return;
        }
        return this._wire.send(message, options);
    }

    setProtocolVersion = (version: string): void => {
        this._wire.setProtocolVersion?.(version);
    };

    /** Forwards one inbound message to the connected instance. */
    deliver(message: JSONRPCMessage, extra?: MessageExtraInfo): void {
        if (this._closed) {
            return;
        }
        if (isJSONRPCRequest(message)) {
            this._pendingRequests.add(message.id);
        } else if (isJSONRPCNotification(message) && message.method === 'notifications/cancelled') {
            // By protocol contract a cancelled request may legitimately go
            // unanswered (the instance aborts the in-flight handler and writes
            // nothing for it), so a delivered cancellation settles the request
            // it names: nothing should keep waiting for an answer that may
            // never come. Non-cancelled requests still settle only when their
            // answer is handed to the wire.
            const cancelledId = (message.params as CancelledNotificationParams | undefined)?.requestId;
            if (cancelledId !== undefined) {
                this._settle(cancelledId);
            }
        }
        this.onmessage?.(message, extra);
    }

    /**
     * Resolves once every request delivered to the instance has been answered
     * through {@linkcode send}, settled by a delivered cancellation, or the
     * channel has been closed and nothing further can be answered. The wait is
     * bounded by `timeoutMs` as a backstop so no edge can hold the caller
     * indefinitely; resolves `false` only when the bound elapsed with requests
     * still unanswered. Used by the probe-discard path so a probe request the
     * entry accepted is never silently dropped.
     */
    async whenRequestsAnswered(timeoutMs: number): Promise<boolean> {
        if (this._closed || this._pendingRequests.size === 0) {
            return true;
        }
        return await new Promise<boolean>(resolve => {
            const waiter = (): void => {
                clearTimeout(timer);
                resolve(true);
            };
            const timer = setTimeout(() => {
                this._drainWaiters = this._drainWaiters.filter(pending => pending !== waiter);
                resolve(false);
            }, timeoutMs);
            this._drainWaiters.push(waiter);
        });
    }

    async close(): Promise<void> {
        if (this._closed) {
            return;
        }
        this._closed = true;
        // Nothing further can be answered through a closed channel; release
        // anyone waiting on in-flight answers.
        this._pendingRequests.clear();
        this._releaseDrainWaiters();
        try {
            this._onInstanceClose();
        } finally {
            this.onclose?.();
        }
    }

    private _settle(id: RequestId): void {
        this._pendingRequests.delete(id);
        if (this._pendingRequests.size === 0) {
            this._releaseDrainWaiters();
        }
    }

    private _releaseDrainWaiters(): void {
        const waiters = this._drainWaiters;
        this._drainWaiters = [];
        for (const waiter of waiters) {
            waiter();
        }
    }
}

/* ------------------------------------------------------------------------ *
 * Opening-exchange classification
 * ------------------------------------------------------------------------ */

interface EnvelopeIssue {
    key: string;
    problem: string;
}

type OpeningClassification =
    /** A 2025-era opening: `initialize`, or any message without an envelope claim. */
    | { kind: 'legacy'; reason: 'initialize' | 'no-claim'; requestedVersion?: string }
    /** A valid envelope claim naming a modern revision this entry serves. */
    | { kind: 'modern'; revision: string; classification: MessageClassification }
    /** A present envelope claim whose envelope is malformed. */
    | { kind: 'invalid-envelope'; issue: EnvelopeIssue }
    /** A valid envelope claim naming a revision this entry does not serve (unknown future or 2025-era). */
    | { kind: 'unsupported-revision'; requested: string };

/**
 * Classifies one message of the opening exchange with the same body-primary
 * rules the HTTP entry applies per request: `initialize` is the legacy
 * handshake unless it carries a valid modern envelope claim; a present claim
 * is validated (never silently ignored); a claim-less message is 2025-era
 * traffic. There is no header layer on stdio, so the body is the only signal.
 */
function classifyOpeningMessage(message: JSONRPCRequest | JSONRPCNotification): OpeningClassification {
    const params = message.params;

    if (message.method === 'initialize' && !carriesValidModernEnvelopeClaim(params)) {
        const requestedVersion =
            params !== null && typeof params === 'object' && typeof (params as { protocolVersion?: unknown }).protocolVersion === 'string'
                ? ((params as { protocolVersion: string }).protocolVersion as string)
                : undefined;
        return { kind: 'legacy', reason: 'initialize', ...(requestedVersion !== undefined && { requestedVersion }) };
    }

    if (!hasEnvelopeClaim(params)) {
        return { kind: 'legacy', reason: 'no-claim' };
    }

    // A present claim is validated, never silently ignored — a malformed
    // envelope behind the claim is an invalid-params answer, not a fall back
    // to legacy serving (mirrors the HTTP entry's envelope rung).
    const meta = requestMetaOf(params);
    const issues = meta === undefined ? [] : validateEnvelopeMeta(meta);
    const firstIssue = issues[0];
    if (firstIssue !== undefined) {
        return { kind: 'invalid-envelope', issue: firstIssue };
    }

    const claimedVersion = envelopeClaimVersion(params);
    if (claimedVersion === undefined || !SUPPORTED_MODERN_PROTOCOL_VERSIONS.includes(claimedVersion)) {
        // The claim names a revision this entry does not serve (an unknown
        // future revision, or a 2025-era revision delivered via the envelope
        // mechanism) — answered like the HTTP entry's modern path.
        return { kind: 'unsupported-revision', requested: claimedVersion ?? 'unknown' };
    }

    return { kind: 'modern', revision: claimedVersion, classification: { era: 'modern', revision: claimedVersion } };
}

/* ------------------------------------------------------------------------ *
 * The entry
 * ------------------------------------------------------------------------ */

interface ConnectedInstance {
    product: McpServer | Server;
    channel: StdioConnectionChannel;
}

type EntryState =
    /** Waiting for the connection's opening message. */
    | { phase: 'opening' }
    /** A `server/discover` probe was answered; the era is not pinned yet. */
    | { phase: 'probe'; instance: ConnectedInstance }
    /** The connection is pinned to one instance serving one era. */
    | { phase: 'pinned'; era: 'legacy' | 'modern'; instance: ConnectedInstance }
    | { phase: 'closed' };

/**
 * Serves MCP over stdio from a server factory, owning the era decision for
 * the connection: the opening exchange selects the era, ONE instance from the
 * factory is pinned for the connection lifetime, and everything after passes
 * straight through to it. See the module documentation for the opening rules.
 *
 * ```ts
 * import { serveStdio } from '@modelcontextprotocol/server/stdio';
 *
 * serveStdio(() => {
 *     const server = new McpServer({ name: 'my-server', version: '1.0.0' }, { capabilities: { tools: {} } });
 *     // register tools/resources/prompts once — the same factory serves both eras
 *     return server;
 * });
 * ```
 */
export function serveStdio(factory: McpServerFactory, options: ServeStdioOptions = {}): StdioServerHandle {
    const legacyMode = options.legacy ?? 'serve';
    const wire = options.transport ?? new StdioServerTransport();

    let state: EntryState = { phase: 'opening' };
    /** Channel currently being discarded (its close must not tear the connection down). */
    let discarding: StdioConnectionChannel | undefined;
    let closing = false;

    /**
     * Whether the connection has been torn down (`handle.close()` or the wire
     * closing). The opening arms re-check this after every await: a close can
     * race factory construction, and the continuation must neither resurrect
     * the connection state nor keep a late-resolved instance around.
     */
    const isTornDown = (): boolean => closing || state.phase === 'closed';

    const reportError = (error: Error) => {
        try {
            options.onerror?.(error);
        } catch {
            // Reporting must never affect the wire.
        }
    };

    const writeErrorResponse = (id: RequestId, code: number, message: string, data?: unknown): Promise<void> =>
        wire
            .send({ jsonrpc: '2.0', id, error: { code, message, ...(data !== undefined && { data }) } })
            .catch(error => reportError(toError(error)));

    /**
     * Entry-handled `subscriptions/listen` for this connection: holds the
     * active subscriptions, serves inbound listen / cancelled-of-listen
     * before the pinned instance is consulted, and rewrites the instance's
     * outbound change notifications onto the active subscriptions. Only
     * consulted on a modern-pinned connection — on a legacy connection
     * change notifications pass straight through (the 2025 unsolicited
     * delivery model is unchanged).
     */
    const listenRouter = new StdioListenRouter(options.maxSubscriptions ?? DEFAULT_MAX_SUBSCRIPTIONS);

    /** Outbound intercept installed on a modern instance's channel. */
    const modernOutboundIntercept = (message: JSONRPCMessage): 'handled' | undefined => {
        if (!isJSONRPCNotification(message)) return undefined;
        const routed = listenRouter.routeOutbound(message);
        if (routed === 'passthrough') return undefined;
        // A subscription-gated change notification on the modern era: one
        // stamped copy per subscription that opted in (an empty array means
        // it is dropped — the modern era never delivers an un-requested
        // change type unsolicited). Nothing else from the instance is
        // affected.
        for (const stamped of routed) {
            void wire.send({ jsonrpc: '2.0', ...stamped }).catch(error => reportError(toError(error)));
        }
        return 'handled';
    };

    /**
     * Entry-handled inbound listen routing for a modern-pinned connection.
     * Returns `true` when the message was served at the entry and must NOT
     * be delivered to the pinned instance.
     */
    const tryServeListen = async (message: JSONRPCMessage): Promise<boolean> => {
        if (isJSONRPCRequest(message) && message.method === 'subscriptions/listen') {
            // Entry-handled listen is its own request-handling subsystem; it
            // applies the same per-request envelope rung the instance's
            // `_onrequest` would (method-existence is N/A here — the entry
            // recognized the method — so envelope validation is the first
            // applicable rung) and the same supported-revision check the
            // opening classifier and the HTTP entry apply per request. Reuses
            // the same validators the opening classifier uses.
            const meta = requestMetaOf(message.params);
            const issue = hasEnvelopeClaim(message.params)
                ? (meta === undefined ? [] : validateEnvelopeMeta(meta))[0]
                : { key: '_meta', problem: 'the per-request envelope is required on protocol revision 2026-07-28' };
            const claimedVersion = envelopeClaimVersion(message.params);
            let reply;
            if (issue !== undefined) {
                reply = {
                    jsonrpc: '2.0' as const,
                    id: message.id,
                    error: { code: -32_602, message: `Invalid _meta envelope: ${issue.key}: ${issue.problem}` }
                };
            } else if (claimedVersion === undefined || !SUPPORTED_MODERN_PROTOCOL_VERSIONS.includes(claimedVersion)) {
                const error = new UnsupportedProtocolVersionError({
                    supported: [...SUPPORTED_MODERN_PROTOCOL_VERSIONS],
                    requested: claimedVersion ?? 'unknown'
                });
                reply = { jsonrpc: '2.0' as const, id: message.id, error: { code: error.code, message: error.message, data: error.data } };
            } else {
                reply = listenRouter.serve(message);
            }
            await wire
                .send('error' in reply ? reply : { jsonrpc: '2.0', method: reply.method, params: reply.params })
                .catch(error => reportError(toError(error)));
            return true;
        }
        if (isJSONRPCNotification(message) && message.method === 'notifications/cancelled') {
            const cancelledId = (message.params as CancelledNotificationParams | undefined)?.requestId;
            // Inbound cancel of a parked listen: tear the subscription down
            // and DO NOT deliver to the instance (it never saw the listen
            // request). After this point nothing further is delivered for
            // that subscription id (post-cancel hardening).
            if (cancelledId !== undefined && listenRouter.cancel(cancelledId)) {
                return true;
            }
        }
        return false;
    };

    /** Answers a 2025-era request the entry will not serve (the modern-only rejection cells). */
    const answerLegacyRejection = (
        request: JSONRPCRequest,
        reason: 'initialize' | 'no-claim',
        requestedVersion?: string
    ): Promise<void> => {
        const rejection = modernOnlyStrictRejection(
            { kind: 'legacy', reason, ...(requestedVersion !== undefined && { requestedVersion }) },
            SUPPORTED_MODERN_PROTOCOL_VERSIONS
        );
        if (rejection === undefined) {
            return Promise.resolve();
        }
        reportError(new Error(`Rejected 2025-era request on a modern-only stdio connection (${rejection.cell}): ${rejection.message}`));
        return writeErrorResponse(request.id, rejection.code, rejection.message, rejection.data);
    };

    const onInstanceClosed = (channel: StdioConnectionChannel) => {
        if (closing || channel === discarding) {
            return;
        }
        // The pinned (or probe) instance was closed from the instance side:
        // the connection is over.
        void closeAll();
    };

    const connectInstance = async (era: 'legacy' | 'modern', revision?: string): Promise<ConnectedInstance> => {
        const product = await factory({ era });
        const server = product instanceof McpServer ? product.server : product;
        if (era === 'modern') {
            // Era-write at instance binding, then modern-only handler
            // installation — the same helpers the HTTP entry's modern path
            // uses, before the instance is connected.
            setNegotiatedProtocolVersion(server, revision);
            installModernOnlyHandlers(server, SUPPORTED_MODERN_PROTOCOL_VERSIONS);
            // The listen router was created before this instance existed; now
            // that capabilities are known, hand them over (with the identity
            // stamped onto graceful-close results) so the acknowledged filter
            // is narrowed against what the server actually advertises.
            listenRouter.setServerCapabilities(server.getCapabilities(), serverIdentityOf(server));
        }
        const channel: StdioConnectionChannel = new StdioConnectionChannel(
            wire,
            () => onInstanceClosed(channel),
            era === 'modern' ? modernOutboundIntercept : undefined
        );
        await product.connect(channel);
        return { product, channel };
    };

    /** Closes an instance whose factory resolved only after the connection was torn down. */
    const disposeLateInstance = (instance: ConnectedInstance): Promise<void> =>
        instance.product.close().catch(error => reportError(toError(error)));

    const discardProbeInstance = async (instance: ConnectedInstance): Promise<void> => {
        // The probe instance served only the discover exchange; closing its
        // channel must not tear down the connection the fallback is about to
        // continue on.
        discarding = instance.channel;
        try {
            // A probe request the entry accepted must never go silently
            // unanswered: a client may pipeline its fallback `initialize`
            // straight behind `server/discover` without waiting, and closing
            // the instance aborts whatever it still has in flight. Let the
            // in-flight DiscoverResult reach the wire before the instance is
            // closed; the probe instance only ever receives `server/discover`,
            // whose entry-installed handler always answers promptly. A probe
            // the client cancelled is already settled by the delivered
            // cancellation (a cancelled request may go unanswered), and the
            // wait is bounded as a backstop so nothing can wedge the
            // connection's pump behind the discard.
            const answered = await instance.channel.whenRequestsAnswered(DISCARD_ANSWER_TIMEOUT_MS);
            if (!answered) {
                reportError(
                    new Error(
                        `Discarded the probe instance with requests still unanswered after ${DISCARD_ANSWER_TIMEOUT_MS}ms; continuing with the fallback`
                    )
                );
            }
            await instance.product.close();
        } catch (error) {
            reportError(toError(error));
        } finally {
            discarding = undefined;
        }
    };

    const processMessage = async (message: JSONRPCMessage): Promise<void> => {
        if (state.phase === 'closed') {
            return;
        }

        if (state.phase === 'pinned') {
            if (
                state.era === 'modern' &&
                isJSONRPCRequest(message) &&
                message.method === 'initialize' &&
                !carriesValidModernEnvelopeClaim(message.params)
            ) {
                // The modern era is confirmed for this connection; a late
                // legacy handshake is answered with the version error naming
                // the supported revisions (the specification recommends
                // naming them in any error returned to `initialize`, and
                // rules out falling back once the modern era is confirmed).
                const requestedVersion =
                    message.params !== null &&
                    typeof message.params === 'object' &&
                    typeof (message.params as { protocolVersion?: unknown }).protocolVersion === 'string'
                        ? ((message.params as { protocolVersion: string }).protocolVersion as string)
                        : undefined;
                await answerLegacyRejection(message, 'initialize', requestedVersion);
                return;
            }
            if (state.era === 'modern' && (await tryServeListen(message))) {
                return;
            }
            if (isTornDown()) {
                // Closed while entry listen routing was being checked (a
                // buffered final message can race stdin EOF): stay closed.
                return;
            }
            state.instance.channel.deliver(message);
            return;
        }

        // Negotiation window ('opening' | 'probe').
        if (!isJSONRPCRequest(message) && !isJSONRPCNotification(message)) {
            // A JSON-RPC response before any era is pinned: nothing has been
            // asked of the client yet, so there is nothing it can answer.
            reportError(new Error('Discarded a JSON-RPC response received before the connection negotiated an era'));
            return;
        }

        const opening = classifyOpeningMessage(message);
        switch (opening.kind) {
            case 'invalid-envelope': {
                const detail = `Invalid _meta envelope for protocol revision 2026-07-28: ${opening.issue.key}: ${opening.issue.problem}`;
                if (isJSONRPCRequest(message)) {
                    await writeErrorResponse(message.id, ProtocolErrorCode.InvalidParams, detail, { envelope: opening.issue });
                } else {
                    reportError(new Error(`Discarded a notification with a malformed envelope: ${detail}`));
                }
                return;
            }
            case 'unsupported-revision': {
                if (isJSONRPCRequest(message)) {
                    const error = new UnsupportedProtocolVersionError({
                        supported: [...SUPPORTED_MODERN_PROTOCOL_VERSIONS],
                        requested: opening.requested
                    });
                    reportError(error);
                    await writeErrorResponse(message.id, error.code, error.message, error.data);
                } else {
                    reportError(new Error(`Discarded a notification claiming unsupported protocol revision ${opening.requested}`));
                }
                return;
            }
            case 'modern': {
                if (isJSONRPCRequest(message) && message.method === 'server/discover') {
                    if (state.phase === 'probe') {
                        // A repeated probe is answered by the same optimistic
                        // instance and the negotiation window stays open: only
                        // a non-discover enveloped request commits the
                        // connection to the modern era, so a later fallback
                        // `initialize` is still served by a fresh legacy
                        // instance.
                        state.instance.channel.deliver(message, { classification: opening.classification });
                        return;
                    }
                    // Probe: answer from an optimistically built modern
                    // instance so the advertisement reflects the real server
                    // definition, but do not pin the connection yet — the
                    // client may still fall back to `initialize` when it
                    // shares no modern revision with the advertisement.
                    const instance = await connectInstance('modern', opening.revision);
                    if (isTornDown()) {
                        // The connection was torn down while the factory was
                        // building the probe instance: dispose of it and stay
                        // closed instead of resurrecting the negotiation
                        // window; nothing is delivered or answered.
                        await disposeLateInstance(instance);
                        return;
                    }
                    state = { phase: 'probe', instance };
                    instance.channel.deliver(message, { classification: opening.classification });
                    return;
                }
                if (state.phase === 'probe') {
                    if (isJSONRPCNotification(message)) {
                        // An enveloped notification during the negotiation
                        // window (for example a notifications/cancelled for
                        // the probe itself) is delivered to the probe instance
                        // without committing the era: only a non-discover
                        // enveloped request pins the connection, so a later
                        // fallback `initialize` is still served by a fresh
                        // legacy instance.
                        state.instance.channel.deliver(message, { classification: opening.classification });
                        return;
                    }
                    // The probe was followed by a modern request: the client
                    // committed to the modern era — pin the probe instance.
                    state = { phase: 'pinned', era: 'modern', instance: state.instance };
                } else {
                    const instance = await connectInstance('modern', opening.revision);
                    if (isTornDown()) {
                        // Closed while the factory was building the modern
                        // instance: dispose of it and stay closed.
                        await disposeLateInstance(instance);
                        return;
                    }
                    state = { phase: 'pinned', era: 'modern', instance };
                }
                if (await tryServeListen(message)) {
                    return;
                }
                if (isTornDown()) {
                    // Closed while entry listen routing was being checked (a
                    // buffered final message can race stdin EOF): stay closed.
                    return;
                }
                state.instance.channel.deliver(message, { classification: opening.classification });
                return;
            }
            case 'legacy': {
                if (legacyMode === 'reject') {
                    if (isJSONRPCRequest(message)) {
                        await answerLegacyRejection(message, opening.reason, opening.requestedVersion);
                    }
                    // Claim-less notifications are accepted and dropped (the
                    // stdio analog of the HTTP entry's 202-and-drop); the
                    // connection stays open for a modern opening.
                    return;
                }
                if (state.phase === 'probe') {
                    // Probe-then-fallback: the client probed, found no
                    // mutually supported modern revision, and fell back to
                    // the 2025 handshake on the same connection. The probe
                    // instance is discarded; a fresh legacy instance serves
                    // the handshake.
                    await discardProbeInstance(state.instance);
                    if (isTornDown()) {
                        // Closed while the probe was being discarded: stay closed.
                        return;
                    }
                    state = { phase: 'opening' };
                }
                const instance = await connectInstance('legacy');
                if (isTornDown()) {
                    // Closed while the factory was building the legacy
                    // instance: dispose of it and stay closed.
                    await disposeLateInstance(instance);
                    return;
                }
                state = { phase: 'pinned', era: 'legacy', instance };
                state.instance.channel.deliver(message);
                return;
            }
        }
    };

    // Inbound messages are processed strictly in arrival order: the queue
    // absorbs anything that arrives while the opening exchange is still being
    // decided (factory construction and instance connection are async).
    const queue: JSONRPCMessage[] = [];
    let pumping = false;
    const pump = async (): Promise<void> => {
        if (pumping) {
            return;
        }
        pumping = true;
        try {
            while (queue.length > 0) {
                const message = queue.shift()!;
                try {
                    await processMessage(message);
                } catch (error) {
                    // Every arm of processMessage that answers a request does
                    // so through writeErrorResponse (which never throws — wire
                    // failures are routed to onerror) and returns right after,
                    // so an error escaping to here means the request was never
                    // answered. Answer it now: a throwing factory or a failed
                    // connect during the opening exchange must not leave the
                    // client's request hanging (the stdio analog of the HTTP
                    // entry's internal-server-error response). Notifications
                    // carry no id to answer and are only reported.
                    if (isJSONRPCRequest(message)) {
                        await writeErrorResponse(message.id, ProtocolErrorCode.InternalError, 'Internal server error');
                    }
                    reportError(toError(error));
                }
            }
        } finally {
            pumping = false;
        }
    };

    const closeAll = async (): Promise<void> => {
        if (closing || state.phase === 'closed') {
            return;
        }
        closing = true;
        const current = state;
        state = { phase: 'closed' };
        // Stdio server-side graceful teardown: emit the empty
        // `subscriptions/listen` JSON-RPC result for every active subscription
        // (the spec's graceful-close signal — `SubscriptionsListenResult`)
        // before the wire is closed, so the client distinguishes graceful end
        // from a transport drop.
        for (const result of listenRouter.teardownAll()) {
            await wire.send(result).catch(error => reportError(toError(error)));
        }
        if (current.phase === 'probe' || current.phase === 'pinned') {
            await current.instance.product.close().catch(error => reportError(toError(error)));
        }
        await wire.close().catch(error => reportError(toError(error)));
    };

    wire.onmessage = (message: JSONRPCMessage) => {
        queue.push(message);
        void pump();
    };
    wire.onerror = error => {
        reportError(error);
        if (state.phase === 'probe' || state.phase === 'pinned') {
            state.instance.channel.onerror?.(error);
        }
    };
    wire.onclose = () => {
        if (closing || state.phase === 'closed') {
            return;
        }
        closing = true;
        const current = state;
        state = { phase: 'closed' };
        if (current.phase === 'probe' || current.phase === 'pinned') {
            void current.instance.product.close().catch(error => reportError(toError(error)));
        }
    };

    const started = wire.start().catch(error => {
        reportError(toError(error));
        throw error;
    });
    // Surface a failed start through onerror (above); close() still resolves.
    started.catch(() => {});

    return {
        close: async () => {
            await started.catch(() => {});
            await closeAll();
        }
    };
}

function toError(value: unknown): Error {
    return value instanceof Error ? value : new Error(String(value));
}

"use strict";
/**
 * Authentication of callers of the MCP server over Streamable HTTP.
 *
 * Modes:
 * - `none`: local development only; the server refuses to bind a
 *   non-loopback address in this mode.
 * - `static-bearer`: pre-shared bearer tokens mapped to named principals.
 *   This does NOT implement MCP OAuth discovery/authorization; it suits
 *   clients that let you configure an Authorization header.
 * - `oauth`: OAuth 2.0 resource server per the MCP authorization
 *   specification: RFC 9728 protected resource metadata, Bearer challenges,
 *   and token validation (issuer, audience/resource, expiry, scopes) via a
 *   configured JWKS or RFC 7662 introspection at an external authorization
 *   server.
 *
 * Every protected request is authenticated; session identifiers are never
 * treated as credentials, and tokens are only accepted in the Authorization
 * header.
 *
 * @module server/authentication
 */
import crypto from "node:crypto";

import {
  type AuthInfo,
  OAuthError,
  OAuthErrorCode,
  type OAuthTokenVerifier,
  bearerAuthChallengeResponse,
  getOAuthProtectedResourceMetadataUrl,
  verifyBearerToken,
} from "@modelcontextprotocol/server";
import * as jose from "jose";

import type { Config } from "../config.js";
import type { SecretResolver } from "../util/secrets.js";
import { OagMcpError } from "../errors.js";
import type { Logs } from "../logging/logger.js";
import type { SecretRegistry } from "../util/redact.js";
import type { Principal } from "../types.js";
import { opaquePrincipalId } from "./authorization.js";

/** Result of authenticating a request. */
export type AuthResult =
  | { ok: true; principal: Principal; authInfo: AuthInfo }
  | { ok: false; response: Response };

/** Authenticator for HTTP requests. */
export interface HttpAuthenticator {
  readonly mode: "none" | "static-bearer" | "oauth";
  /** Authenticate one request. */
  authenticate(req: Request, logs: Logs): Promise<AuthResult>;
  /** Serve discovery metadata, or undefined when the path is not metadata. */
  metadata(req: Request): Response | undefined;
}

/** Error carrying a machine-readable token validation reason. */
class TokenRejected extends OAuthError {
  constructor(
    readonly reason: string,
    message: string,
  ) {
    super(OAuthErrorCode.InvalidToken, message);
  }
}

/**
 * Parse scopes from token claims (`scope` string or `scp` array/string).
 *
 * @param {Object} claims - token claims
 * @return {Array} scopes
 */
export function scopesFromClaims(claims: Record<string, unknown>): string[] {
  const raw = claims.scope ?? claims.scp;
  if (Array.isArray(raw)) {
    return raw.map(String);
  }
  if (typeof raw === "string") {
    return raw.split(/\s+/).filter(Boolean);
  }
  return [];
}

/** Reasons for jose errors, by error class; the first match wins. */
const JOSE_REASONS: ReadonlyArray<
  [abstract new (...args: never[]) => Error, string]
> = [
  [jose.errors.JWTExpired, "expired"],
  [jose.errors.JWSSignatureVerificationFailed, "invalid_signature"],
  [jose.errors.JWKSNoMatchingKey, "unknown_signing_key"],
  [jose.errors.JOSEAlgNotAllowed, "algorithm_not_allowed"],
  [jose.errors.JWSInvalid, "malformed_token"],
  [jose.errors.JWTInvalid, "malformed_token"],
];

/** Reasons for failed JWT claim checks, by claim. */
const CLAIM_REASONS: Readonly<Record<string, string>> = {
  aud: "audience_mismatch",
  iss: "issuer_mismatch",
  nbf: "not_yet_valid",
};

/**
 * Map jose errors to stable reasons.
 *
 * @private
 */
function _joseReason(err: unknown): string {
  if (
    err instanceof jose.errors.JWTClaimValidationFailed &&
    !(err instanceof jose.errors.JWTExpired)
  ) {
    return Object.hasOwn(CLAIM_REASONS, err.claim)
      ? CLAIM_REASONS[err.claim]
      : `claim_${err.claim}_invalid`;
  }
  return (
    JOSE_REASONS.find(([cls]) => err instanceof cls)?.[1] ?? "invalid_token"
  );
}

/**
 * Whether a host binds only to loopback.
 *
 * @param {String} host - bind host
 * @return {Boolean} true for loopback
 */
export function isLoopbackHost(host: string): boolean {
  return (
    ["127.0.0.1", "localhost", "::1", "[::1]"].includes(host) ||
    host.startsWith("127.")
  );
}

/**
 * Discover the JWKS URI from authorization server metadata.
 *
 * @private
 */
async function _discoverJwks(issuer: string): Promise<string> {
  const u = new URL(issuer);
  const pathPart = u.pathname.replace(/\/+$/, "");
  const candidates = [
    `${u.origin}/.well-known/oauth-authorization-server${pathPart}`,
    `${issuer.replace(/\/+$/, "")}/.well-known/openid-configuration`,
  ];
  for (const url of candidates) {
    try {
      const res = await fetch(url, { redirect: "error" });
      if (!res.ok) {
        continue;
      }
      const meta = (await res.json()) as Record<string, unknown>;
      if (meta.issuer !== issuer) {
        throw new OagMcpError(
          "MCP_AUTH_ISSUER_MISMATCH",
          `Authorization server metadata at ${url} reports issuer ${String(meta.issuer)}, expected ${issuer}`,
        );
      }
      if (typeof meta.jwks_uri === "string") {
        return meta.jwks_uri;
      }
    } catch (err) {
      if (err instanceof OagMcpError) {
        throw err;
      }
    }
  }
  throw new OagMcpError(
    "MCP_AUTH_JWKS_UNKNOWN",
    `Could not discover jwks_uri for issuer ${issuer}`,
    {
      hint: "Set mcpAuth.oauth.jwksUri explicitly, or configure introspection.",
    },
  );
}

/**
 * JWT access token verifier using a remote JWKS.
 */
class JwtVerifier implements OAuthTokenVerifier {
  private readonly jwks: ReturnType<typeof jose.createRemoteJWKSet>;

  constructor(
    jwksUri: string,
    private readonly o: {
      issuer: string;
      audiences: string[];
      algorithms: string[];
      clockToleranceSec: number;
      resource: URL;
    },
  ) {
    this.jwks = jose.createRemoteJWKSet(new URL(jwksUri), {
      timeoutDuration: 5000,
      cooldownDuration: 30000,
    });
  }

  async verifyAccessToken(token: string): Promise<AuthInfo> {
    let payload: jose.JWTPayload;
    try {
      ({ payload } = await jose.jwtVerify(token, this.jwks, {
        issuer: this.o.issuer,
        audience: this.o.audiences,
        algorithms: this.o.algorithms,
        clockTolerance: this.o.clockToleranceSec,
        requiredClaims: ["exp"],
      }));
    } catch (err) {
      throw new TokenRejected(_joseReason(err), "The access token is invalid");
    }
    const claims = payload as Record<string, unknown>;
    return {
      token,
      clientId: String(
        claims.client_id ?? claims.azp ?? claims.sub ?? "unknown",
      ),
      scopes: scopesFromClaims(claims),
      expiresAt: payload.exp,
      resource: this.o.resource,
      extra: { sub: payload.sub, iss: payload.iss },
    };
  }
}

/** An introspection response that passed the checks. */
type ActiveToken = Record<string, unknown> & { exp: number };

/**
 * The audiences of an introspection response's `aud`.
 *
 * @private
 */
function _audiences(aud: unknown): string[] {
  if (Array.isArray(aud)) {
    return aud.map(String);
  }
  return aud ? [String(aud)] : [];
}

/**
 * RFC 7662 token introspection verifier for opaque tokens.
 */
class IntrospectionVerifier implements OAuthTokenVerifier {
  constructor(
    private readonly o: {
      endpoint: string;
      clientId: string;
      clientSecret: string;
      issuer: string;
      audiences: string[];
      resource: URL;
    },
  ) {}

  async verifyAccessToken(token: string): Promise<AuthInfo> {
    const data = await this._introspect(token);
    this._check(data);
    return {
      token,
      clientId: String(data.client_id ?? data.sub ?? "unknown"),
      scopes: scopesFromClaims(data),
      expiresAt: data.exp,
      resource: this.o.resource,
      extra: { sub: data.sub, iss: data.iss ?? this.o.issuer },
    };
  }

  /**
   * Ask the introspection endpoint about a token.
   *
   * @private
   */
  private async _introspect(token: string): Promise<Record<string, unknown>> {
    let res: Response;
    try {
      res = await fetch(this.o.endpoint, {
        method: "POST",
        redirect: "error",
        headers: {
          "content-type": "application/x-www-form-urlencoded",
          accept: "application/json",
          authorization: `Basic ${Buffer.from(`${encodeURIComponent(this.o.clientId)}:${encodeURIComponent(this.o.clientSecret)}`).toString("base64")}`,
        },
        body: new URLSearchParams({ token, token_type_hint: "access_token" }),
        signal: AbortSignal.timeout(5000),
      });
    } catch {
      throw new OAuthError(
        OAuthErrorCode.ServerError,
        "Token introspection is unavailable",
      );
    }
    if (!res.ok) {
      throw new OAuthError(
        OAuthErrorCode.ServerError,
        "Token introspection failed",
      );
    }
    return (await res.json()) as Record<string, unknown>;
  }

  /**
   * Check that a token is active, ours and unexpired.
   *
   * @private
   */
  private _check(data: Record<string, unknown>): asserts data is ActiveToken {
    if (data.active !== true) {
      throw new TokenRejected("inactive", "The access token is not active");
    }
    if (data.iss !== undefined && data.iss !== this.o.issuer) {
      throw new TokenRejected(
        "issuer_mismatch",
        "The access token was issued by another issuer",
      );
    }
    if (!_audiences(data.aud).some((a) => this.o.audiences.includes(a))) {
      throw new TokenRejected(
        "audience_mismatch",
        "The access token is not intended for this server",
      );
    }
    if (typeof data.exp !== "number" || data.exp * 1000 < Date.now()) {
      throw new TokenRejected("expired", "The access token has expired");
    }
  }
}

/**
 * Timing-safe comparison of two strings via their digests.
 *
 * @private
 */
function _safeEqual(a: string, b: string): boolean {
  const da = crypto.createHash("sha256").update(a).digest();
  const db = crypto.createHash("sha256").update(b).digest();
  return crypto.timingSafeEqual(da, db);
}

/**
 * Bearer token from an Authorization header.
 *
 * @private
 */
function _bearer(req: Request): string | undefined {
  const h = req.headers.get("authorization");
  const m = h ? /^Bearer\s+([^\s]+)\s*$/i.exec(h) : null;
  return m ? m[1] : undefined;
}

/**
 * JSON error response with a WWW-Authenticate challenge.
 *
 * @private
 */
function _challenge(
  status: number,
  error: string | undefined,
  description: string,
): Response {
  const params = [`realm="oag-mcp"`];
  if (error) {
    params.push(`error="${error}"`, `error_description="${description}"`);
  }
  return new Response(
    JSON.stringify({
      error: error ?? "unauthorized",
      error_description: description,
    }),
    {
      status,
      headers: {
        "content-type": "application/json",
        "www-authenticate": `Bearer ${params.join(", ")}`,
      },
    },
  );
}

/** Options for {@link createHttpAuthenticator}. */
export interface AuthenticatorOptions {
  config: Config;
  resolver: SecretResolver;
  registry: SecretRegistry;
  logs: Logs;
  /** Public URL of the MCP endpoint (the protected resource). */
  resourceUrl: URL;
  resourceName: string;
}

/** A configured static bearer token with its resolved value. */
type StaticEntry = NonNullable<
  Config["mcpAuth"]["staticBearer"]
>["tokens"][number] & { value: string };

/** OAuth resource server settings. */
type OAuthConfig = NonNullable<Config["mcpAuth"]["oauth"]>;

/** What an OAuth authenticator checks tokens against. */
interface OAuthContext {
  o: OAuthConfig;
  verifier: OAuthTokenVerifier;
  validation: "jwt" | "introspection";
  resource: URL;
  resourceMetadataUrl: string;
  registry: SecretRegistry;
}

/**
 * Create the HTTP authenticator for the configured mode.
 *
 * @param {Object} opts - options
 * @return {Promise} authenticator
 */
export async function createHttpAuthenticator(
  opts: AuthenticatorOptions,
): Promise<HttpAuthenticator> {
  const mode = opts.config.mcpAuth.mode;
  if (mode === "none") {
    return _noneAuthenticator(opts.logs);
  }
  if (mode === "static-bearer") {
    return _staticBearerAuthenticator(opts);
  }
  return _oauthAuthenticator(opts);
}

/**
 * Local development: every caller is anonymous.
 *
 * @private
 */
function _noneAuthenticator(logs: Logs): HttpAuthenticator {
  const mode = "none";
  logs.audit(
    "authentication.mode_configured",
    "success",
    {
      mode,
      warning: "unauthenticated; loopback only",
    },
    "warn",
  );
  return {
    mode,
    metadata: () => undefined,
    authenticate: async (_req, l) => {
      const principal: Principal = {
        id: "anonymous",
        kind: "anonymous",
        scopes: [],
      };
      l.audit("authentication.succeeded", "success", {
        mode,
        principalId: principal.id,
      });
      return {
        ok: true,
        principal,
        authInfo: {
          token: "",
          clientId: "anonymous",
          scopes: [],
          extra: { principal },
        },
      };
    },
  };
}

/**
 * Pre-shared bearer tokens mapped to named principals.
 *
 * @private
 */
function _staticBearerAuthenticator(
  opts: AuthenticatorOptions,
): HttpAuthenticator {
  const mode = "static-bearer";
  const entries = _staticEntries(opts);
  opts.logs.audit("authentication.mode_configured", "success", {
    mode,
    principals: entries.map((e) => e.principal),
    note: "static bearer does not implement MCP OAuth discovery",
  });
  return {
    mode,
    metadata: () => undefined,
    authenticate: async (req, l) => _authenticateStatic(req, l, entries),
  };
}

/**
 * Resolve the configured static bearer tokens, refusing weak ones.
 *
 * @private
 */
function _staticEntries(opts: AuthenticatorOptions): StaticEntry[] {
  const tokens = opts.config.mcpAuth.staticBearer?.tokens;
  if (!tokens || tokens.length === 0) {
    throw new OagMcpError(
      "MCP_AUTH_CONFIG_INVALID",
      "mcpAuth.mode is static-bearer but mcpAuth.staticBearer.tokens is empty",
    );
  }
  return tokens.map((t) => {
    const value = opts.resolver.resolve(
      t.token,
      `mcpAuth token for ${t.principal}`,
    );
    if (value.length < 16) {
      throw new OagMcpError(
        "MCP_AUTH_TOKEN_WEAK",
        `Static bearer token for ${t.principal} is shorter than 16 characters`,
        { hint: "Generate one with: openssl rand -hex 32" },
      );
    }
    opts.registry.add(value);
    return { ...t, value };
  });
}

/**
 * The entry a token belongs to, comparing against every entry to keep
 * timing independent of position.
 *
 * @private
 */
function _matchStatic(
  token: string,
  entries: StaticEntry[],
): StaticEntry | undefined {
  let match: StaticEntry | undefined;
  for (const e of entries) {
    if (_safeEqual(token, e.value) && !match) {
      match = e;
    }
  }
  return match;
}

/**
 * Audit a refused static bearer request and challenge the caller.
 *
 * @private
 */
function _refuseStatic(
  l: Logs,
  reason: string,
  response: Response,
): AuthResult {
  l.audit(
    "authentication.failed",
    "failure",
    { mode: "static-bearer", reason },
    "warn",
  );
  return { ok: false, response };
}

/**
 * Authenticate a request with a static bearer token.
 *
 * @private
 */
function _authenticateStatic(
  req: Request,
  l: Logs,
  entries: StaticEntry[],
): AuthResult {
  const token = _bearer(req);
  if (!token) {
    return _refuseStatic(
      l,
      "missing_token",
      _challenge(401, undefined, "Bearer token required"),
    );
  }
  const match = _matchStatic(token, entries);
  if (!match) {
    return _refuseStatic(
      l,
      "invalid_token",
      _challenge(401, "invalid_token", "The bearer token is invalid"),
    );
  }
  const principal: Principal = {
    id: `static:${match.principal}`,
    kind: "static",
    name: match.principal,
    scopes: match.scopes,
  };
  l.audit("authentication.succeeded", "success", {
    mode: "static-bearer",
    principalId: principal.id,
  });
  return {
    ok: true,
    principal,
    authInfo: {
      token: "[static-bearer]",
      clientId: match.principal,
      scopes: match.scopes,
      extra: { principal },
    },
  };
}

/**
 * The OAuth settings, refusing a missing section or an insecure issuer.
 *
 * @private
 */
function _oauthConfig(config: Config): OAuthConfig {
  const o = config.mcpAuth.oauth;
  if (!o) {
    throw new OagMcpError(
      "MCP_AUTH_CONFIG_INVALID",
      "mcpAuth.mode is oauth but mcpAuth.oauth is not configured",
    );
  }
  const issuerUrl = new URL(o.issuer);
  if (
    issuerUrl.protocol !== "https:" &&
    !o.allowInsecureIssuer &&
    !isLoopbackHost(issuerUrl.hostname)
  ) {
    throw new OagMcpError(
      "MCP_AUTH_ISSUER_INSECURE",
      `OAuth issuer ${o.issuer} must use HTTPS`,
      {
        hint: "Use an HTTPS issuer; allowInsecureIssuer is for local testing only.",
      },
    );
  }
  return o;
}

/**
 * The token verifier: introspection when configured, otherwise JWTs signed
 * by the issuer's JWKS.
 *
 * @private
 */
async function _oauthVerifier(
  o: OAuthConfig,
  opts: AuthenticatorOptions,
  audiences: string[],
  resource: URL,
): Promise<Pick<OAuthContext, "verifier" | "validation">> {
  if (o.introspection) {
    const clientId = opts.resolver.resolve(
      o.introspection.clientId,
      "introspection client id",
    );
    const clientSecret = opts.resolver.resolve(
      o.introspection.clientSecret,
      "introspection client secret",
    );
    opts.registry.add(clientSecret);
    return {
      verifier: new IntrospectionVerifier({
        endpoint: o.introspection.endpoint,
        clientId,
        clientSecret,
        issuer: o.issuer,
        audiences,
        resource,
      }),
      validation: "introspection",
    };
  }
  const jwksUri = o.jwksUri ?? (await _discoverJwks(o.issuer));
  return {
    verifier: new JwtVerifier(jwksUri, {
      issuer: o.issuer,
      audiences,
      algorithms: o.algorithms,
      clockToleranceSec: o.clockToleranceSec,
      resource,
    }),
    validation: "jwt",
  };
}

/**
 * Serve RFC 9728 protected resource metadata at its well-known paths.
 *
 * @private
 */
function _metadataHandler(
  prm: Record<string, unknown>,
  paths: Set<string>,
): HttpAuthenticator["metadata"] {
  return (req) => {
    if (!paths.has(new URL(req.url).pathname)) {
      return undefined;
    }
    if (req.method !== "GET" && req.method !== "HEAD") {
      return new Response(null, {
        status: 405,
        headers: { allow: "GET, HEAD" },
      });
    }
    return new Response(JSON.stringify(prm), {
      status: 200,
      headers: {
        "content-type": "application/json",
        "cache-control": "max-age=300",
      },
    });
  };
}

/**
 * OAuth 2.0 resource server.
 *
 * @private
 */
async function _oauthAuthenticator(
  opts: AuthenticatorOptions,
): Promise<HttpAuthenticator> {
  const mode = "oauth";
  const o = _oauthConfig(opts.config);
  const resource = new URL(o.resource ?? opts.resourceUrl.toString());
  const audiences =
    o.audience && o.audience.length > 0 ? o.audience : [resource.toString()];
  const resourceMetadataUrl = getOAuthProtectedResourceMetadataUrl(resource);
  const { verifier, validation } = await _oauthVerifier(
    o,
    opts,
    audiences,
    resource,
  );
  const metadata = _metadataHandler(
    {
      resource: resource.toString(),
      authorization_servers: [o.issuer],
      scopes_supported: o.scopesSupported ?? o.requiredScopes,
      bearer_methods_supported: ["header"],
      resource_name: opts.resourceName,
    },
    new Set([
      "/.well-known/oauth-protected-resource",
      new URL(resourceMetadataUrl).pathname,
    ]),
  );
  opts.logs.audit("authentication.mode_configured", "success", {
    mode,
    validation,
    issuer: o.issuer,
    requiredScopes: o.requiredScopes,
  });
  const ctx: OAuthContext = {
    o,
    verifier,
    validation,
    resource,
    resourceMetadataUrl,
    registry: opts.registry,
  };
  return {
    mode,
    metadata,
    authenticate: (req, l) => _authenticateOAuth(req, l, ctx),
  };
}

/**
 * Authenticate a request with an OAuth access token.
 *
 * @private
 */
async function _authenticateOAuth(
  req: Request,
  l: Logs,
  ctx: OAuthContext,
): Promise<AuthResult> {
  const { o, validation, resourceMetadataUrl } = ctx;
  try {
    const authInfo = await verifyBearerToken(req.headers.get("authorization"), {
      verifier: ctx.verifier,
      requiredScopes: o.requiredScopes,
      resourceMetadataUrl,
      expectedResource: ctx.resource,
    });
    const extra = (authInfo.extra ?? {}) as { sub?: string; iss?: string };
    const principal: Principal = {
      id: opaquePrincipalId("oauth", [
        String(extra.iss ?? o.issuer),
        String(extra.sub ?? authInfo.clientId),
      ]),
      kind: "oauth",
      clientId: authInfo.clientId,
      scopes: authInfo.scopes,
      expiresAt: authInfo.expiresAt,
    };
    ctx.registry.add(authInfo.token);
    l.audit("authentication.succeeded", "success", {
      mode: "oauth",
      validation,
      principalId: principal.id,
      scopeCount: principal.scopes.length,
    });
    return {
      ok: true,
      principal,
      authInfo: { ...authInfo, extra: { ...authInfo.extra, principal } },
    };
  } catch (err) {
    l.audit(
      "authentication.failed",
      "failure",
      { mode: "oauth", validation, reason: _oauthFailureReason(err, req) },
      "warn",
    );
    return {
      ok: false,
      response: bearerAuthChallengeResponse(err, {
        requiredScopes: o.requiredScopes,
        resourceMetadataUrl,
      }),
    };
  }
}

/**
 * A stable reason for a refused OAuth request.
 *
 * @private
 */
function _oauthFailureReason(err: unknown, req: Request): string {
  if (err instanceof TokenRejected) {
    return err.reason;
  }
  if (!req.headers.get("authorization")) {
    return "missing_token";
  }
  const code = err instanceof OAuthError ? err.code : "server_error";
  if (code === OAuthErrorCode.InsufficientScope) {
    return "insufficient_scope";
  }
  const message = String((err as Error).message);
  if (/expired/i.test(message)) {
    return "expired";
  }
  return /resource/i.test(message) ? "resource_mismatch" : String(code);
}

"use strict";
/**
 * Request-scoped principals and the operation authorisation policy.
 *
 * Authorisation is enforced twice: search results are filtered to what the
 * caller may use, and every SDK call made during an execution is checked by
 * the host broker before it reaches the upstream API. Hiding a method from
 * search is not the control; the broker check is.
 *
 * @module server/authorization
 */
import crypto from "node:crypto";

import type { AuthorizationRule } from "../config.js";
import type { OperationBinding, Principal } from "../types.js";

/**
 * Derive an opaque, stable principal id from identifying values.
 *
 * @param {String} kind - principal kind
 * @param {Array} parts - identifying values (e.g. issuer and subject)
 * @return {String} opaque id
 */
export function opaquePrincipalId(kind: string, parts: string[]): string {
  const h = crypto
    .createHash("sha256")
    .update(parts.join("\u0000"))
    .digest("hex")
    .slice(0, 16);
  return `${kind}:${h}`;
}

/** Authorisation decision. */
export interface Decision {
  allowed: boolean;
  policyId: string;
  reason: string;
}

/**
 * Convert a glob with `*` wildcards to a regular expression.
 *
 * @private
 */
function _glob(pattern: string): RegExp {
  const escaped = pattern
    .split("*")
    .map((p) => p.replace(/[.+?^${}()|[\]\\]/g, "\\$&"))
    .join(".*");
  return new RegExp(`^${escaped}$`);
}

/**
 * Whether an operation pattern matches a binding. Patterns are globs over
 * binding ids ("PetsApi.list*"), `tag:<name>`, `method:<HTTP>` or
 * `operationId:<glob>`.
 *
 * @param {String} pattern - pattern
 * @param {Object} op - operation binding
 * @return {Boolean} match
 */
export function matchesOperation(
  pattern: string,
  op: OperationBinding,
): boolean {
  if (pattern.startsWith("tag:")) {
    return op.tags.includes(pattern.slice(4));
  }
  if (pattern.startsWith("method:")) {
    return op.httpMethod === pattern.slice(7).toUpperCase();
  }
  if (pattern.startsWith("operationId:")) {
    return (
      Boolean(op.operationId) && _glob(pattern.slice(12)).test(op.operationId!)
    );
  }
  return _glob(pattern).test(op.id);
}

/**
 * Operation authorisation policy.
 */
export class AuthorizationPolicy {
  private readonly rules: AuthorizationRule[];
  private readonly defaultAllow: boolean;
  readonly implicit: boolean;

  /**
   * @param {Object} [config] - `authorization` configuration; undefined allows
   *   every operation for every authenticated principal ("implicit-allow-all")
   */
  constructor(config?: {
    default: "allow" | "deny";
    rules: AuthorizationRule[];
  }) {
    this.implicit = !config;
    this.rules = config?.rules ?? [];
    this.defaultAllow = config ? config.default === "allow" : true;
  }

  /**
   * Rules applying to a principal.
   *
   * @private
   */
  private _rulesFor(p: Principal): AuthorizationRule[] {
    return this.rules.filter((r) => {
      if (
        r.principals &&
        !r.principals.some(
          (g) =>
            _glob(g).test(p.id) ||
            (p.name !== undefined && _glob(g).test(p.name)),
        )
      ) {
        return false;
      }
      if (r.clientIds && !(p.clientId && r.clientIds.includes(p.clientId))) {
        return false;
      }
      if (r.scopes && !r.scopes.every((s) => p.scopes.includes(s))) {
        return false;
      }
      return true;
    });
  }

  /**
   * Decide whether a principal may invoke an operation.
   *
   * @param {Object} p - principal
   * @param {Object} op - operation binding
   * @return {Object} decision
   */
  decide(p: Principal, op: OperationBinding): Decision {
    if (this.implicit) {
      return {
        allowed: true,
        policyId: "implicit-allow-all",
        reason: "no_policy_configured",
      };
    }
    const rules = this._rulesFor(p);
    for (const r of rules) {
      if (r.deny.some((pat) => matchesOperation(pat, op))) {
        return { allowed: false, policyId: r.id, reason: "rule_deny" };
      }
    }
    for (const r of rules) {
      if (r.allow.some((pat) => matchesOperation(pat, op))) {
        return { allowed: true, policyId: r.id, reason: "rule_allow" };
      }
    }
    return {
      allowed: this.defaultAllow,
      policyId: "default",
      reason: this.defaultAllow ? "default_allow" : "default_deny",
    };
  }
}

"use strict";
/**
 * Resolution of secret references (`{ env: NAME }` or `{ secret: key }`)
 * used in the configuration file. Values are read at start-up from the
 * environment or from a protected local secrets file, never from the
 * configuration file itself.
 *
 * @module util/secrets
 */
import fs from "node:fs";
import path from "node:path";

import YAML from "yaml";

import type { SecretRef } from "../config.js";
import { OagMcpError } from "../errors.js";

/**
 * Resolves secret references from the environment and a secrets file.
 */
export class SecretResolver {
  private fileSecrets?: Record<string, string>;

  /**
   * @param {Object} opts - options
   * @param {String} [opts.secretsFile] - path to the secrets file
   * @param {String} opts.baseDir - base for relative paths
   * @param {Object} [opts.env] - environment (defaults to process.env)
   */
  constructor(
    private readonly opts: {
      secretsFile?: string;
      baseDir: string;
      env?: NodeJS.ProcessEnv;
    },
  ) {}

  /**
   * Load the secrets file once.
   *
   * @private
   */
  private _load(): Record<string, string> {
    if (!this.fileSecrets) {
      if (!this.opts.secretsFile) {
        throw new OagMcpError(
          "SECRETS_FILE_MISSING",
          "A { secret: ... } reference was used but upstreamAuth.secretsFile is not configured",
        );
      }
      this.fileSecrets = _readSecretsFile(
        path.resolve(this.opts.baseDir, this.opts.secretsFile),
      );
    }
    return this.fileSecrets;
  }

  /**
   * Resolve a reference to its value.
   *
   * @param {Object} ref - secret reference
   * @param {String} label - what the value is for (for messages, never the value)
   * @return {String} secret value
   */
  resolve(ref: SecretRef, label: string): string {
    if ("env" in ref) {
      const v = (this.opts.env ?? process.env)[ref.env];
      if (v === undefined || v === "") {
        throw new OagMcpError(
          "SECRET_NOT_FOUND",
          `Environment variable ${ref.env} (for ${label}) is not set`,
          {
            hint: `Export ${ref.env} in the environment of the oag-mcp server.`,
          },
        );
      }
      return v;
    }
    const v = this._load()[ref.secret];
    if (v === undefined || v === "") {
      throw new OagMcpError(
        "SECRET_NOT_FOUND",
        `Secret "${ref.secret}" (for ${label}) is not in the secrets file`,
      );
    }
    return v;
  }
}

/**
 * Read a secrets file: a YAML mapping of key to string value, readable by
 * its owner only on POSIX. Values that are not strings are ignored.
 *
 * @private
 */
function _readSecretsFile(file: string): Record<string, string> {
  let stat: fs.Stats;
  try {
    stat = fs.statSync(file);
  } catch (err) {
    throw new OagMcpError(
      "SECRETS_FILE_MISSING",
      `Secrets file ${file} cannot be read`,
      { cause: err },
    );
  }
  if (process.platform !== "win32" && (stat.mode & 0o077) !== 0) {
    throw new OagMcpError(
      "SECRETS_FILE_PERMISSIONS",
      `Secrets file ${file} is readable by group or others (mode ${(stat.mode & 0o777).toString(8)})`,
      { hint: `Restrict it with: chmod 600 ${file}` },
    );
  }
  const parsed = YAML.parse(fs.readFileSync(file, "utf8")) ?? {};
  if (typeof parsed !== "object" || Array.isArray(parsed)) {
    throw new OagMcpError(
      "SECRETS_FILE_INVALID",
      `Secrets file ${file} must be a mapping of key to string value`,
    );
  }
  return Object.fromEntries(
    Object.entries(parsed).filter(([, v]) => typeof v === "string"),
  ) as Record<string, string>;
}

"use strict";
/**
 * Start-up preparation: turn an OpenAPI document and an existing
 * typescript-fetch SDK into everything the server needs, once per process.
 *
 * Stages (each logged as `prepare.stage.completed`):
 *
 * 1. `inputs`: validate and load the OpenAPI document; resolve the SDK
 *    directory in place or extract an archive into the workspace.
 * 2. `compatibility`: check generator target, version, options and layout,
 *    and that runtime dependencies are already installed (never installs).
 * 3. `sdk`: declarations (emitted for source SDKs, copied for compiled ones)
 *    and one ES-module execution bundle, written to the workspace.
 * 4. `index`: SDK methods (from declarations and implementation) mapped to
 *    OpenAPI operations, the in-memory search index and the `sdk` binding
 *    declaration.
 *
 * The bridge and executor (stage 5) are assembled by the runtime service.
 * Nothing is written to the supplied SDK; no package manager, lifecycle
 * script or SDK build script is run.
 *
 * @module prepare/prepare
 */
import crypto from "node:crypto";
import fs from "node:fs";
import path from "node:path";

import { OagMcpError } from "../errors.js";
import type { Logs } from "../logging/logger.js";
import { MethodSearchIndex } from "../search/search-index.js";
import type {
  MethodRecord,
  OperationBinding,
  PreparedSdkInfo,
  SpecSummary,
} from "../types.js";
import { sha256File } from "../util/hash.js";
import {
  dependencyVersion,
  oagMcpVersion,
  packageRoot,
} from "../util/version.js";
import { SdkAnalyzer, scanImplementation } from "./analyze.js";
import {
  bundleSdk,
  copyDeclarations,
  copyTsLibs,
  emitDeclarations,
} from "./bundle.js";
import { type SdkInspection, inspectSdk } from "./compat.js";
import { buildRecords, hintsForOperation } from "./method-records.js";
import {
  type StagedSdk,
  missingDependencies,
  stageSdkInput,
} from "./sdk-input.js";
import { loadSpec } from "./spec.js";
import {
  WORKSPACE_PATHS,
  type Workspace,
  bindingDeclaration,
  createWorkspace,
} from "./workspace.js";

/** Start-up preparation stages, in order. */
export const PREPARE_STAGES = [
  "inputs",
  "compatibility",
  "sdk",
  "index",
  "executor",
] as const;

/** A preparation stage name. */
export type PrepareStage = (typeof PREPARE_STAGES)[number];

/** Options for {@link prepareSdk}. */
export interface PrepareOptions {
  /** OpenAPI 3.0/3.1 document. */
  spec: string;
  /** typescript-fetch SDK directory or npm package archive (.tgz). */
  sdk: string;
  sdkLayout?: "auto" | "source" | "compiled";
  /** Generator version for SDKs lacking .openapi-generator/VERSION. */
  sdkOagVersion?: string;
  allowUntestedOagVersion?: boolean;
  /** Parent of the private workspace, default: OS temporary directory. */
  workspaceRoot?: string;
  /** Cancels preparation between stages (e.g. on SIGTERM during start-up). */
  signal?: AbortSignal;
  logs: Logs;
}

/** A prepared SDK held by one server process. */
export interface PreparedSdk {
  info: PreparedSdkInfo;
  /** Private workspace with sdk/ and executor/ (removed by cleanup). */
  workspaceDir: string;
  records: MethodRecord[];
  bindings: OperationBinding[];
  index: MethodSearchIndex;
  warnings: string[];
  /** Remove the workspace. Never throws; returns whether it succeeded. */
  cleanup(): boolean;
}

/**
 * Run one preparation stage with logging.
 *
 * @param {Object} logs - logs
 * @param {String} stage - stage name
 * @param {Function} fn - stage body
 * @return {Promise} stage result
 */
export async function runStage<T>(
  logs: Logs,
  stage: PrepareStage,
  fn: () => T | Promise<T>,
  signal?: AbortSignal,
): Promise<T> {
  if (signal?.aborted) {
    logs.op("info", "prepare.aborted", { stage });
    throw new OagMcpError(
      "STARTUP_ABORTED",
      `Start-up was cancelled before the ${stage} stage`,
      { hint: "The server received a shutdown signal while preparing." },
    );
  }
  const started = Date.now();
  logs.op("debug", "prepare.stage.started", { stage });
  try {
    const out = await fn();
    logs.op("info", "prepare.stage.completed", {
      stage,
      durationMs: Date.now() - started,
      outcome: "success",
    });
    return out;
  } catch (err) {
    const code = err instanceof OagMcpError ? err.code : "UNEXPECTED";
    if (stage === "compatibility") {
      logs.op("error", "prepare.compat.failed", {
        errorCode: code,
        outcome: "failure",
      });
    }
    logs.op("error", "prepare.stage.failed", {
      stage,
      errorCode: code,
      durationMs: Date.now() - started,
      outcome: "failure",
    });
    throw err;
  }
}

/**
 * Stage 1: inputs.
 *
 * @private
 */
async function _inputs(
  opts: PrepareOptions,
  ws: Workspace,
): Promise<{ specPath: string; spec: SpecSummary; staged: StagedSdk }> {
  if (!opts.spec) {
    throw new OagMcpError("CLI_ARGS_INVALID", "--spec is required", {
      hint: "Usage: oag-mcp serve --spec ./openapi.yaml --sdk ./generated-sdk",
    });
  }
  if (!opts.sdk) {
    throw new OagMcpError("CLI_ARGS_INVALID", "--sdk is required", {
      hint: "Pass an existing OpenAPI Generator typescript-fetch SDK directory or .tgz package. oag-mcp does not generate SDKs.",
    });
  }
  const specPath = path.resolve(opts.spec);
  if (!fs.existsSync(specPath) || !fs.statSync(specPath).isFile()) {
    throw new OagMcpError(
      "SPEC_NOT_FOUND",
      `OpenAPI document ${opts.spec} does not exist`,
      { hint: "Pass --spec <file> with an OpenAPI 3.0/3.1 YAML or JSON file." },
    );
  }
  const spec = await loadSpec(specPath);
  opts.logs.op("info", "prepare.spec.loaded", {
    openapiVersion: spec.openapiVersion,
    operations: spec.operations.length,
    securitySchemes: Object.keys(spec.securitySchemes).length,
  });
  const staged = await stageSdkInput(
    opts.sdk,
    path.join(ws.dir, WORKSPACE_PATHS.input),
  );
  opts.logs.op("info", "prepare.sdk.resolved", { sdkKind: staged.kind });
  return { specPath, spec, staged };
}

/**
 * Stage 2: compatibility.
 *
 * @private
 */
function _compatibility(
  opts: PrepareOptions,
  staged: StagedSdk,
): SdkInspection {
  const insp = inspectSdk(staged.root, {
    layout: opts.sdkLayout,
    declaredOagVersion: opts.sdkOagVersion,
    allowUntestedOagVersion: opts.allowUntestedOagVersion,
  });
  const missing = missingDependencies(staged.root, insp.pkg?.dependencies);
  if (missing.length > 0) {
    const how =
      staged.kind === "archive"
        ? "Extract the archive (e.g. `tar -xzf <file>.tgz`), run `npm install --omit=dev --ignore-scripts` in the extracted `package/` directory, and pass that directory to --sdk."
        : `Run \`npm install --omit=dev --ignore-scripts\` in ${opts.sdk}, then restart oag-mcp.`;
    throw new OagMcpError(
      "SDK_DEPENDENCIES_MISSING",
      `SDK runtime dependencies are not installed: ${missing.join(", ")}`,
      {
        hint: `oag-mcp never installs packages or runs package scripts. ${how}`,
        details: { missing },
      },
    );
  }
  opts.logs.op("info", "prepare.compat.checked", {
    layout: insp.layout,
    oagVersion: insp.oagVersion,
    oagVersionTested: insp.oagVersionTested,
    apiFiles: insp.apiFiles.length,
    outcome: "success",
  });
  return insp;
}

/**
 * Stage 3: declarations, execution bundle, TypeScript libs and the runner.
 *
 * @private
 */
async function _sdk(
  insp: SdkInspection,
  staged: StagedSdk,
  ws: Workspace,
  logs: Logs,
): Promise<{ typesDir: string; warnings: string[] }> {
  const warnings: string[] = [];
  const typesDir = path.join(ws.dir, WORKSPACE_PATHS.types);
  if (insp.layout === "source") {
    const diags = emitDeclarations(insp.entry, typesDir);
    if (diags.length > 0) {
      warnings.push(
        `SDK declarations emitted with ${diags.length} TypeScript diagnostic(s): ${diags[0]}`,
      );
    }
  } else {
    copyDeclarations(insp.typesDir!, typesDir);
  }
  const classNames = [...scanImplementation(insp.apiFiles).keys()];
  const bundle = await bundleSdk({
    entry: insp.entry,
    root: staged.root,
    outFile: path.join(ws.dir, WORKSPACE_PATHS.bundle),
    shimDir: path.join(ws.dir, WORKSPACE_PATHS.shim),
    classNames,
  });
  logs.op("info", "prepare.sdk.bundled", {
    bytes: bundle.bytes,
    exports: bundle.exports.length,
  });
  copyTsLibs(path.join(ws.dir, WORKSPACE_PATHS.tsLib));
  fs.mkdirSync(path.dirname(path.join(ws.dir, WORKSPACE_PATHS.runner)), {
    recursive: true,
  });
  fs.copyFileSync(
    path.join(packageRoot(), "assets", "deno-runner.js"),
    path.join(ws.dir, WORKSPACE_PATHS.runner),
  );
  return { typesDir, warnings };
}

/**
 * Stage 4: method index and the `sdk` binding declaration.
 *
 * @private
 */
function _index(
  spec: SpecSummary,
  insp: SdkInspection,
  typesDir: string,
  ws: Workspace,
  logs: Logs,
): {
  records: MethodRecord[];
  bindings: OperationBinding[];
  unmapped: Array<{ key: string; operationId?: string }>;
  index: MethodSearchIndex;
  warnings: string[];
} {
  const impl = scanImplementation(insp.apiFiles);
  const analyzer = new SdkAnalyzer(path.join(typesDir, "index.d.ts"));
  const byKey = new Map(spec.operations.map((o) => [o.key, o]));
  const methods = analyzer.analyze(impl, (m, p) =>
    hintsForOperation(byKey.get(`${m} ${p}`)),
  );
  const { records, bindings, unmapped } = buildRecords(spec, methods);
  const warnings = unmapped.map(
    (u) =>
      `Operation ${u.key}${u.operationId ? ` (${u.operationId})` : ""} has no SDK method and is not available`,
  );
  fs.writeFileSync(
    path.join(ws.dir, WORKSPACE_PATHS.binding),
    bindingDeclaration(records),
  );
  const index = new MethodSearchIndex(records);
  logs.op("info", "prepare.index.created", {
    methods: records.length,
    apiClasses: new Set(records.map((r) => r.className)).size,
    unmappedOperations: unmapped.length,
  });
  return { records, bindings, unmapped, index, warnings };
}

/**
 * Prepare the SDK for serving: stages 1–4. On failure the workspace is
 * removed before the error is rethrown.
 *
 * @param {Object} opts - preparation options
 * @return {Promise} prepared SDK
 */
export async function prepareSdk(opts: PrepareOptions): Promise<PreparedSdk> {
  const { logs } = opts;
  const started = Date.now();
  const prepareId = crypto.randomUUID();
  logs.op("info", "prepare.started", { prepareId });
  const ws = createWorkspace({ root: opts.workspaceRoot, logs });
  try {
    const { specPath, spec, staged } = await runStage(logs, "inputs", () =>
      _inputs(opts, ws),
    );
    const insp = await runStage(logs, "compatibility", () =>
      _compatibility(opts, staged),
    );
    const sdk = await runStage(logs, "sdk", () => _sdk(insp, staged, ws, logs));
    const idx = await runStage(logs, "index", () =>
      _index(spec, insp, sdk.typesDir, ws, logs),
    );
    const warnings = [...insp.warnings, ...sdk.warnings, ...idx.warnings];
    for (const w of warnings) {
      logs.op("warn", "prepare.warning", { warning: w });
    }
    const info: PreparedSdkInfo = {
      prepareId,
      preparedAt: new Date().toISOString(),
      oagMcpVersion: oagMcpVersion(),
      target: {
        generator: "typescript-fetch",
        oagVersion: insp.oagVersion,
        oagVersionTested: insp.oagVersionTested,
        options: insp.detectedOptions,
        sdkLayout: insp.layout,
        sdkPackage: insp.pkg
          ? { name: insp.pkg.name, version: insp.pkg.version }
          : undefined,
      },
      tools: {
        typescript: dependencyVersion("typescript"),
        esbuild: dependencyVersion("esbuild"),
      },
      inputs: {
        spec: {
          fileName: path.basename(specPath),
          sha256: sha256File(specPath),
        },
        sdk: { kind: staged.kind, sha256: staged.sha256 },
      },
      api: {
        title: spec.title,
        version: spec.apiVersion,
        description: spec.description,
        servers: spec.servers,
        tags: spec.tags,
      },
      securitySchemes: spec.securitySchemes,
      operations: idx.bindings,
      unmappedOperations: idx.unmapped,
    };
    logs.op("info", "prepare.sdk.prepared", {
      prepareId,
      methods: idx.records.length,
      oagVersion: insp.oagVersion,
      sdkLayout: insp.layout,
      sdkKind: staged.kind,
      specSha256: info.inputs.spec.sha256,
      sdkSha256: staged.sha256,
      durationMs: Date.now() - started,
    });
    return {
      info,
      workspaceDir: ws.dir,
      records: idx.records,
      bindings: idx.bindings,
      index: idx.index,
      warnings,
      cleanup: ws.cleanup,
    };
  } catch (err) {
    logs.op("error", "prepare.failed", {
      prepareId,
      errorCode: err instanceof OagMcpError ? err.code : "UNEXPECTED",
      durationMs: Date.now() - started,
      outcome: "failure",
    });
    ws.cleanup();
    throw err;
  }
}

"use strict";
/**
 * Local lexical search over SDK method records using MiniSearch (BM25-style
 * full-text ranking, prefix and fuzzy matching), with English stop words
 * from the stopword package and Porter stemming from the stemmer package.
 * No embeddings or external services are involved.
 *
 * @module search/search-index
 */
import MiniSearch from "minisearch";
import { stemmer } from "stemmer";
import { eng } from "stopword";

import type { MethodRecord } from "../types.js";

/** Fields indexed for full-text search. */
const FIELDS = [
  "methodName",
  "methodWords",
  "className",
  "operationId",
  "summary",
  "description",
  "tags",
  "path",
  "params",
  "types",
];

const SEARCH_OPTIONS = {
  boost: {
    methodName: 3,
    methodWords: 3,
    operationId: 2,
    summary: 2.5,
    tags: 1.5,
    path: 1.5,
    className: 1.2,
    types: 0.5,
  },
  prefix: true,
  fuzzy: 0.2,
  combineWith: "OR" as const,
};

/**
 * Words in the stopword package's English list that carry meaning in API
 * search: "get" is a method-name verb (getPetById), and the others are
 * common query-parameter names (since, before, after, between, from).
 */
const API_TERMS = new Set([
  "get",
  "since",
  "before",
  "after",
  "between",
  "from",
]);

/** English stop words (the stopword package's list) minus API terms. */
const STOP_WORDS = new Set(eng.filter((w) => !API_TERMS.has(w)));

/**
 * Normalise a search term, at indexing and at query time alike: lower-case,
 * drop English stop words, and reduce the word to its Porter stem, so
 * "cats" matches "cat" and "vaccinated" matches "vaccination".
 *
 * @param {String} term - raw term
 * @return {String|null} processed term, or null to drop it
 */
export function processTerm(term: string): string | null {
  const t = term.toLowerCase().replace(/'s$/, "");
  if (STOP_WORDS.has(t)) {
    return null;
  }
  return stemmer(t);
}

/**
 * Split identifiers into words: "listPetVisits" -> "list pet visits".
 *
 * @param {String} s - identifier
 * @return {String} words
 */
export function splitWords(s: string | undefined): string {
  return (s ?? "")
    .replace(/([a-z0-9])([A-Z])/g, "$1 $2")
    .replace(/[_\-/{}.]+/g, " ")
    .toLowerCase();
}

/**
 * Convert a record to an indexable document.
 *
 * @private
 */
function _doc(r: MethodRecord): Record<string, string> {
  return {
    id: r.id,
    methodName: r.methodName,
    methodWords: splitWords(r.methodName),
    className: `${r.className} ${splitWords(r.className.replace(/Api$/, ""))}`,
    operationId: `${r.operationId ?? ""} ${splitWords(r.operationId)}`,
    summary: r.summary ?? "",
    description: r.description ?? "",
    tags: r.tags.join(" "),
    path: `${r.httpMethod} ${splitWords(r.path)}`,
    params: [
      ...r.apiParameters.map(
        // The schema type carries enum values, e.g. "dog" | "cat".
        (p) =>
          `${p.name} ${splitWords(p.name)} ${p.description ?? ""} ${p.schemaType ?? ""}`,
      ),
      ...r.parameters.map((p) => p.name),
    ].join(" "),
    types: [
      r.returnType,
      ...r.referencedTypes.map(
        (t) =>
          `${t.name} ${t.declaration.replace(/[{}();:|"'<>[\],=?]/g, " ")}`,
      ),
    ].join(" "),
  };
}

/** A compact search hit. */
export interface SearchHit {
  id: string;
  sdkPath: string;
  signature: string;
  summary?: string;
  httpMethod: string;
  path: string;
  requiredArguments: string[];
  auth: string;
  score: number;
}

/**
 * Summarise auth requirements in one line.
 *
 * @param {Object} r - method record
 * @return {String} summary
 */
export function authLine(r: MethodRecord): string {
  if (r.auth.alternatives.length === 0) {
    return "none";
  }
  const alts = r.auth.alternatives
    .map((a) => a.schemes.map((s) => `${s.name}(${s.type})`).join(" + "))
    .join(" OR ");
  return `${alts}${r.auth.optional ? " OR none" : ""}${
    r.auth.unsupportedSchemes.length
      ? ` [unsupported: ${r.auth.unsupportedSchemes.join(", ")}]`
      : ""
  }`;
}

/**
 * Search index over method records.
 */
export class MethodSearchIndex {
  private readonly mini: MiniSearch;
  private readonly byId: Map<string, MethodRecord>;

  /**
   * @param {Array} records - method records
   * @param {String} [serialised] - previously serialised MiniSearch JSON
   */
  constructor(
    readonly records: MethodRecord[],
    serialised?: string,
  ) {
    this.byId = new Map(records.map((r) => [r.id, r]));
    const options = {
      fields: FIELDS,
      storeFields: ["id"],
      processTerm,
      searchOptions: SEARCH_OPTIONS,
    };
    if (serialised) {
      this.mini = MiniSearch.loadJSON(serialised, options);
    } else {
      this.mini = new MiniSearch(options);
      this.mini.addAll(records.map(_doc));
    }
  }

  /**
   * Serialise the full-text index.
   *
   * @return {String} JSON
   */
  serialise(): string {
    return JSON.stringify(this.mini);
  }

  /**
   * Look up a record by id.
   *
   * @param {String} id - "<Class>.<method>"
   * @return {Object|undefined} record
   */
  get(id: string): MethodRecord | undefined {
    return this.byId.get(id);
  }

  /**
   * Ranked search restricted to visible records.
   *
   * @param {String} query - free text
   * @param {Object} opts - options
   * @param {Function} opts.visible - filter for records the caller may use
   * @param {Number} opts.limit - maximum results
   * @param {String} [opts.tag] - restrict to a tag or API class
   * @return {Object} { hits, total }
   */
  search(
    query: string,
    opts: {
      visible: (r: MethodRecord) => boolean;
      limit: number;
      tag?: string;
    },
  ): { hits: SearchHit[]; total: number } {
    const results = this.mini.search(query);
    const hits: SearchHit[] = [];
    let total = 0;
    for (const res of results) {
      const r = this.byId.get(String(res.id));
      if (!r || !opts.visible(r)) {
        continue;
      }
      if (opts.tag && !r.tags.includes(opts.tag) && r.className !== opts.tag) {
        continue;
      }
      total++;
      if (hits.length < opts.limit) {
        hits.push({
          id: r.id,
          sdkPath: r.sdkPath,
          signature: r.signature,
          summary: r.summary ?? r.description?.split("\n")[0],
          httpMethod: r.httpMethod,
          path: r.path,
          requiredArguments: r.requiredArguments,
          auth: authLine(r),
          score: Math.round(res.score * 100) / 100,
        });
      }
    }
    return { hits, total };
  }

  /**
   * Overview of capabilities grouped by API class, for agents that do not
   * yet know the API's vocabulary.
   *
   * @param {Object} opts - options
   * @param {Function} opts.visible - filter for records the caller may use
   * @param {Number} opts.perClass - method names listed per class
   * @param {String} [opts.tag] - restrict to a tag or API class (lists all)
   * @return {Array} groups
   */
  browse(opts: {
    visible: (r: MethodRecord) => boolean;
    perClass: number;
    tag?: string;
  }): Array<{
    api: string;
    tags: string[];
    methodCount: number;
    methods: Array<{ id: string; summary?: string }>;
    more: number;
  }> {
    const groups = new Map<string, MethodRecord[]>();
    for (const r of this.records) {
      if (!opts.visible(r)) {
        continue;
      }
      if (opts.tag && !r.tags.includes(opts.tag) && r.className !== opts.tag) {
        continue;
      }
      groups.set(r.className, [...(groups.get(r.className) ?? []), r]);
    }
    const limit = opts.tag ? 100 : opts.perClass;
    return [...groups.entries()]
      .sort(([a], [b]) => a.localeCompare(b))
      .map(([api, rs]) => ({
        api,
        tags: [...new Set(rs.flatMap((r) => r.tags))],
        methodCount: rs.length,
        methods: rs
          .slice(0, limit)
          .map((r) => ({ id: r.id, summary: r.summary })),
        more: Math.max(0, rs.length - limit),
      }));
  }
}

"use strict";
/**
 * Hashing helpers used to identify preparation inputs.
 *
 * @module util/hash
 */
import crypto from "node:crypto";
import fs from "node:fs";
import path from "node:path";

/**
 * SHA-256 of a buffer or string, hex encoded.
 *
 * @param {Buffer|String} data - data to hash
 * @return {String} hex digest
 */
export function sha256(data: string | Buffer): string {
  return crypto.createHash("sha256").update(data).digest("hex");
}

/**
 * SHA-256 of a file's content.
 *
 * @param {String} file - file path
 * @return {String} hex digest
 */
export function sha256File(file: string): string {
  return sha256(fs.readFileSync(file));
}

/**
 * List files under a directory recursively, sorted, as relative POSIX paths.
 * Symbolic links are not followed.
 *
 * @param {String} dir - directory
 * @param {Function} [filter] - returns false to skip a relative path
 * @return {Array} relative file paths
 */
export function listFiles(
  dir: string,
  filter: (rel: string) => boolean = () => true,
): string[] {
  const out: string[] = [];
  const walk = (current: string) => {
    for (const entry of fs.readdirSync(current, { withFileTypes: true })) {
      const abs = path.join(current, entry.name);
      const rel = path.relative(dir, abs).split(path.sep).join("/");
      if (!filter(rel)) {
        continue;
      }
      if (entry.isDirectory()) {
        walk(abs);
      } else if (entry.isFile()) {
        out.push(rel);
      }
    }
  };
  walk(dir);
  return out.sort();
}

/**
 * Deterministic hash of a directory tree (relative paths and contents).
 *
 * @param {String} dir - directory
 * @param {Function} [filter] - returns false to skip a relative path
 * @return {String} hex digest
 */
export function sha256Tree(
  dir: string,
  filter?: (rel: string) => boolean,
): string {
  const h = crypto.createHash("sha256");
  for (const rel of listFiles(dir, filter)) {
    h.update(rel);
    h.update("\0");
    h.update(sha256File(path.join(dir, rel)));
    h.update("\n");
  }
  return h.digest("hex");
}

"use strict";
/**
 * Static analysis of a typescript-fetch SDK.
 *
 * Two independent sources are combined:
 *
 * 1. Implementation files (TypeScript sources or compiled JavaScript) are
 *    parsed to find, for every public API method, the HTTP method and path
 *    template it sends. typescript-fetch 7.x builds these in
 *    `<method>RequestOpts`; older output builds them in `<method>Raw`. This
 *    gives a reliable binding without assuming operationId equals the
 *    generated method name.
 * 2. Declarations (`.d.ts`) are type-checked to extract exact signatures,
 *    documentation and the declarations of referenced types.
 *
 * @module prepare/analyze
 */
import fs from "node:fs";
import path from "node:path";

import ts from "typescript";

import { OagMcpError } from "../errors.js";
import type { TypeDeclaration } from "../types.js";
import { sdkCompilerOptions } from "./bundle.js";

/** HTTP binding found in an implementation method. */
export interface ImplBinding {
  httpMethod: string;
  path: string;
  source: "RequestOpts" | "Raw";
}

/** A public API method of the SDK with its binding and types. */
export interface AnalyzedMethod {
  className: string;
  methodName: string;
  httpMethod: string;
  path: string;
  signature: string;
  parameters: Array<{ name: string; type: string; optional: boolean }>;
  requestStyle: "object" | "positional" | "none";
  inputType?: TypeDeclaration;
  returnType: string;
  referencedTypes: TypeDeclaration[];
  requiredArguments: string[];
  documentation: string;
  deprecated: boolean;
  example: string;
}

/** Example hints keyed by normalised parameter/property name. */
export type ExampleHints = Record<string, unknown>;

const MAX_REFERENCED_TYPES = 15;
const MAX_TYPE_DEPTH = 3;
const MAX_MEMBERS = 40;

/**
 * Normalise a name for loose matching between OpenAPI and SDK naming.
 *
 * @param {String} name - name
 * @return {String} normalised name
 */
export function normaliseName(name: string): string {
  return name.toLowerCase().replace(/[^a-z0-9]/g, "");
}

/** Class name -> method name -> binding. */
type Bindings = Map<string, Map<string, ImplBinding>>;

/** What a method body scan has found so far. */
interface BindingScan {
  httpMethod?: string;
  pathInit?: ts.Expression;
  variables: Map<string, ts.Expression>;
}

/** A property assignment with a plain or quoted name. */
type NamedAssignment = ts.PropertyAssignment & {
  name: ts.Identifier | ts.StringLiteral;
};

/** A class method with a plain name. */
type NamedMethod = ts.MethodDeclaration & { name: ts.Identifier };

/** The SDK declaration kinds that are rendered for agents. */
type SdkDeclaration =
  ts.InterfaceDeclaration | ts.TypeAliasDeclaration | ts.EnumDeclaration;

/** A method parameter as written in the declarations. */
interface Param {
  name: string;
  type: string;
  optional: boolean;
  node: ts.ParameterDeclaration;
}

/** How a method takes its arguments, and an example call's arguments. */
interface RequestArgs {
  requestStyle: AnalyzedMethod["requestStyle"];
  inputType: TypeDeclaration | undefined;
  requiredArguments: string[];
  exampleArgs: string;
}

/** State shared while analysing the classes of every declaration file. */
interface AnalyzeRun {
  impl: Bindings;
  hintsFor: (httpMethod: string, p: string) => ExampleHints;
  found: Set<string>;
  problems: string[];
  methods: AnalyzedMethod[];
}

/** Implementation method suffixes, most authoritative first. */
const BINDING_SOURCES: ReadonlyArray<ImplBinding["source"]> = [
  "RequestOpts",
  "Raw",
];

const HIDDEN_MODIFIERS =
  ts.ModifierFlags.Private |
  ts.ModifierFlags.Protected |
  ts.ModifierFlags.Static;

/** Example renderers for scalar types, by type flag. */
const SCALAR_EXAMPLES: ReadonlyArray<{
  flags: ts.TypeFlags;
  render: (hint: unknown) => string;
}> = [
  {
    flags: ts.TypeFlags.StringLike,
    render: (hint) =>
      JSON.stringify(typeof hint === "string" ? hint : "example"),
  },
  {
    flags: ts.TypeFlags.NumberLike,
    render: (hint) => (typeof hint === "number" ? String(hint) : "1"),
  },
  {
    flags: ts.TypeFlags.BooleanLike,
    render: (hint) => (typeof hint === "boolean" ? String(hint) : "true"),
  },
];

/**
 * Reconstruct a string from a literal-ish expression.
 *
 * @private
 */
function _literalText(node: ts.Expression | undefined): string | undefined {
  if (!node) {
    return undefined;
  }
  if (ts.isStringLiteral(node) || ts.isNoSubstitutionTemplateLiteral(node)) {
    return node.text;
  }
  if (ts.isTemplateExpression(node)) {
    return _templateText(node);
  }
  if (
    ts.isCallExpression(node) &&
    ts.isPropertyAccessExpression(node.expression)
  ) {
    // `/pets/{petId}`.replace(...) in older generator output
    return _literalText(node.expression.expression);
  }
  if (ts.isParenthesizedExpression(node)) {
    return _literalText(node.expression);
  }
  return undefined;
}

/**
 * Reconstruct a template whose substitutions are all literal-ish.
 *
 * @private
 */
function _templateText(node: ts.TemplateExpression): string | undefined {
  let out = node.head.text;
  for (const span of node.templateSpans) {
    const inner = _literalText(span.expression);
    if (inner === undefined) {
      return undefined;
    }
    out += inner + span.literal.text;
  }
  return out;
}

/**
 * Whether a node is a property assignment with a plain or quoted name.
 *
 * @private
 */
function _isNamedAssignment(n: ts.Node): n is NamedAssignment {
  return (
    ts.isPropertyAssignment(n) &&
    (ts.isIdentifier(n.name) || ts.isStringLiteral(n.name))
  );
}

/**
 * Remember the first initialiser of each local variable.
 *
 * @private
 */
function _noteVariable(n: ts.Node, scan: BindingScan): void {
  if (
    ts.isVariableDeclaration(n) &&
    ts.isIdentifier(n.name) &&
    n.initializer &&
    !scan.variables.has(n.name.text)
  ) {
    scan.variables.set(n.name.text, n.initializer);
  }
}

/**
 * Take the first `method:` and `path:` properties.
 *
 * @private
 */
function _noteProperty(n: ts.Node, scan: BindingScan): void {
  if (!_isNamedAssignment(n)) {
    return;
  }
  if (n.name.text === "method" && scan.httpMethod === undefined) {
    const text = _literalText(n.initializer);
    if (text) {
      scan.httpMethod = text.toUpperCase();
    }
  }
  if (n.name.text === "path" && scan.pathInit === undefined) {
    scan.pathInit = n.initializer;
  }
}

/**
 * Take a shorthand `path` property as the path.
 *
 * @private
 */
function _noteShorthand(n: ts.Node, scan: BindingScan): void {
  if (
    ts.isShorthandPropertyAssignment(n) &&
    n.name.text === "path" &&
    scan.pathInit === undefined
  ) {
    scan.pathInit = n.name;
  }
}

/**
 * The path text, following a variable the path property names.
 *
 * @private
 */
function _pathText(scan: BindingScan): string | undefined {
  const init = scan.pathInit;
  if (!init) {
    return undefined;
  }
  return ts.isIdentifier(init)
    ? _literalText(scan.variables.get(init.text))
    : _literalText(init);
}

/**
 * Find the HTTP method and path built inside a method body.
 *
 * @private
 */
function _extractBinding(body: ts.Node): {
  httpMethod?: string;
  path?: string;
} {
  const scan: BindingScan = { variables: new Map() };
  const visit = (n: ts.Node) => {
    _noteVariable(n, scan);
    _noteProperty(n, scan);
    _noteShorthand(n, scan);
    ts.forEachChild(n, visit);
  };
  visit(body);
  return { httpMethod: scan.httpMethod, path: _pathText(scan) };
}

/**
 * The public method an implementation method builds the request for.
 *
 * @private
 */
function _bindingTarget(
  name: string,
): { base: string; source: ImplBinding["source"] } | undefined {
  const source = BINDING_SOURCES.find((s) => name.endsWith(s));
  const base = source ? name.slice(0, -source.length) : "";
  return source && base ? { base, source } : undefined;
}

/**
 * Record the binding an implementation method builds, if it builds one.
 *
 * @private
 */
function _recordBinding(
  out: Bindings,
  cls: string,
  name: string,
  body: ts.Node | undefined,
): void {
  const target = _bindingTarget(name);
  if (!body || !target) {
    return;
  }
  const { httpMethod, path: p } = _extractBinding(body);
  if (!httpMethod || !p) {
    return;
  }
  const methods = out.get(cls) ?? new Map<string, ImplBinding>();
  const existing = methods.get(target.base);
  // RequestOpts is authoritative when both are present.
  if (!existing || existing.source === "Raw") {
    methods.set(target.base, { httpMethod, path: p, source: target.source });
  }
  out.set(cls, methods);
}

/**
 * Whether a class extends the generated runtime's BaseAPI.
 *
 * @private
 */
function _extendsBaseApi(n: ts.ClassDeclaration, sf: ts.SourceFile): boolean {
  return (n.heritageClauses ?? []).some((h) =>
    h.types.some((t) => /BaseAPI$/.test(t.expression.getText(sf))),
  );
}

/**
 * Record the bindings of an API class declaration's methods.
 *
 * @private
 */
function _scanClass(n: ts.Node, sf: ts.SourceFile, out: Bindings): void {
  if (!ts.isClassDeclaration(n) || !n.name || !_extendsBaseApi(n, sf)) {
    return;
  }
  const cls = n.name.text;
  out.set(cls, out.get(cls) ?? new Map());
  for (const m of n.members) {
    if (ts.isMethodDeclaration(m) && ts.isIdentifier(m.name)) {
      _recordBinding(out, cls, m.name.text, m.body);
    }
  }
}

/**
 * The class and method an ES5 `Foo.prototype.bar` target names.
 *
 * @private
 */
function _prototypeMember(
  left: ts.Expression,
): { cls: string; name: string } | undefined {
  if (
    ts.isPropertyAccessExpression(left) &&
    ts.isPropertyAccessExpression(left.expression) &&
    left.expression.name.text === "prototype" &&
    ts.isIdentifier(left.expression.expression)
  ) {
    return { cls: left.expression.expression.text, name: left.name.text };
  }
  return undefined;
}

/**
 * Record the binding of an ES5 method assignment:
 * `Foo.prototype.barRequestOpts = function () { ... }`.
 *
 * @private
 */
function _scanPrototypeAssignment(n: ts.Node, out: Bindings): void {
  if (
    !ts.isBinaryExpression(n) ||
    n.operatorToken.kind !== ts.SyntaxKind.EqualsToken ||
    !(ts.isFunctionExpression(n.right) || ts.isArrowFunction(n.right))
  ) {
    return;
  }
  const member = _prototypeMember(n.left);
  if (member) {
    _recordBinding(out, member.cls, member.name, n.right.body);
  }
}

/**
 * Scan implementation files for API classes and method bindings.
 *
 * @param {Array} files - implementation files under apis/
 * @return {Map} className -> methodName -> binding
 */
export function scanImplementation(files: string[]): Bindings {
  const out: Bindings = new Map();
  for (const file of files) {
    const text = fs.readFileSync(file, "utf8");
    const sf = ts.createSourceFile(
      file,
      text,
      ts.ScriptTarget.ES2022,
      true,
      file.endsWith(".js") ? ts.ScriptKind.JS : ts.ScriptKind.TS,
    );
    const visit = (n: ts.Node) => {
      _scanClass(n, sf, out);
      _scanPrototypeAssignment(n, out);
      ts.forEachChild(n, visit);
    };
    visit(sf);
  }
  return out;
}

/**
 * Collapse whitespace in a declaration snippet.
 *
 * @private
 */
function _compact(text: string): string {
  return text.replace(/\s+/g, " ").trim();
}

/**
 * Whether a declaration is of a kind rendered for agents.
 *
 * @private
 */
function _isRenderable(d: ts.Declaration): d is SdkDeclaration {
  return (
    ts.isInterfaceDeclaration(d) ||
    ts.isTypeAliasDeclaration(d) ||
    ts.isEnumDeclaration(d)
  );
}

/**
 * Whether a class member is a public, non-implementation API method.
 *
 * @private
 */
function _isApiMethod(m: ts.ClassElement): m is NamedMethod {
  if (!ts.isMethodDeclaration(m) || !ts.isIdentifier(m.name)) {
    return false;
  }
  const name = m.name.text;
  return (
    !(ts.getCombinedModifierFlags(m) & HIDDEN_MODIFIERS) &&
    !BINDING_SOURCES.some((s) => name.endsWith(s))
  );
}

/**
 * Describe a method parameter.
 *
 * @private
 */
function _param(p: ts.ParameterDeclaration, sf: ts.SourceFile): Param {
  return {
    name: p.name.getText(sf),
    type: p.type ? _compact(p.type.getText(sf)) : "any",
    optional: Boolean(p.questionToken || p.initializer),
    node: p,
  };
}

/**
 * Example hints keyed by normalised property name.
 *
 * @private
 */
function _hintsByName(hint: unknown): Map<string, unknown> {
  const h =
    hint && typeof hint === "object" ? (hint as Record<string, unknown>) : {};
  return new Map(Object.entries(h).map(([k, v]) => [normaliseName(k), v]));
}

/**
 * The names of a type's required properties.
 *
 * @private
 */
function _requiredProperties(type: ts.Type): string[] {
  return type
    .getProperties()
    .filter((s) => !(s.flags & ts.SymbolFlags.Optional))
    .map((s) => s.name);
}

/**
 * The type nodes whose SDK declarations a method's documentation shows.
 *
 * @private
 */
function _typeRoots(apiParams: Param[], m: ts.MethodDeclaration): ts.Node[] {
  return [...apiParams.map((p) => p.node.type), m.type].filter(
    (t): t is ts.TypeNode => t !== undefined,
  );
}

/**
 * The example body that calls a method and returns its result.
 *
 * @private
 */
function _exampleBody(call: string, returnType: string): string {
  return /Promise<void>/.test(returnType)
    ? `await ${call};\nreturn { done: true };`
    : `const result = await ${call};\nreturn result;`;
}

/**
 * Analyse SDK declarations together with implementation bindings.
 */
export class SdkAnalyzer {
  private readonly program: ts.Program;
  private readonly checker: ts.TypeChecker;
  private readonly typesDir: string;
  private readonly printer = ts.createPrinter({ removeComments: true });

  /**
   * @param {String} typesIndex - path to the SDK declarations index.d.ts
   */
  constructor(typesIndex: string) {
    this.typesDir = path.dirname(path.resolve(typesIndex));
    this.program = ts.createProgram([typesIndex], {
      ...sdkCompilerOptions(),
      noEmit: true,
    });
    this.checker = this.program.getTypeChecker();
  }

  /**
   * Whether a file is one of the SDK's declaration files.
   *
   * @private
   */
  private _isSdkFile(fileName: string): boolean {
    return path.resolve(fileName).startsWith(this.typesDir + path.sep);
  }

  /**
   * Whether a declaration belongs to the SDK (not lib, not the runtime
   * module).
   *
   * @private
   */
  private _isSdkDecl(decl: ts.Declaration): boolean {
    const file = decl.getSourceFile().fileName;
    return this._isSdkFile(file) && !/[\\/]runtime\.d\.ts$/.test(file);
  }

  /**
   * Resolve a type reference to SDK declarations.
   *
   * @private
   */
  private _resolveRef(node: ts.TypeReferenceNode): SdkDeclaration[] {
    let sym = this.checker.getSymbolAtLocation(node.typeName);
    if (sym && sym.flags & ts.SymbolFlags.Alias) {
      sym = this.checker.getAliasedSymbol(sym);
    }
    return (sym?.declarations ?? []).filter(
      (d): d is SdkDeclaration => _isRenderable(d) && this._isSdkDecl(d),
    );
  }

  /**
   * The documentation comment of the symbol a name refers to.
   *
   * @private
   */
  private _docOf(name: ts.Node | undefined): string {
    const sym = name ? this.checker.getSymbolAtLocation(name) : undefined;
    return ts.displayPartsToString(sym?.getDocumentationComment(this.checker));
  }

  /**
   * The type of a property symbol, when it has a declaration to read it from.
   *
   * @private
   */
  private _propertyType(p: ts.Symbol): ts.Type | undefined {
    const decl = p.valueDeclaration ?? p.declarations?.[0];
    return decl ? this.checker.getTypeOfSymbolAtLocation(p, decl) : undefined;
  }

  /**
   * Whether a type is an object type other than an array.
   *
   * @private
   */
  private _isPlainObject(t: ts.Type | undefined): boolean {
    return (
      t !== undefined &&
      Boolean(t.flags & ts.TypeFlags.Object) &&
      !this.checker.isArrayType(t)
    );
  }

  /**
   * Render an SDK declaration compactly with member documentation.
   *
   * @private
   */
  private _render(decl: SdkDeclaration): TypeDeclaration {
    if (ts.isInterfaceDeclaration(decl)) {
      return this._renderInterface(decl);
    }
    if (ts.isTypeAliasDeclaration(decl)) {
      return this._renderAlias(decl);
    }
    return {
      name: decl.name.text,
      declaration: this.printer
        .printNode(ts.EmitHint.Unspecified, decl, decl.getSourceFile())
        .trim(),
    };
  }

  /**
   * Render an interface, one documented member per line.
   *
   * @private
   */
  private _renderInterface(decl: ts.InterfaceDeclaration): TypeDeclaration {
    const sf = decl.getSourceFile();
    const heritage = decl.heritageClauses
      ? ` ${decl.heritageClauses.map((h) => h.getText(sf)).join(" ")}`
      : "";
    const hidden = decl.members.length - MAX_MEMBERS;
    const lines = [
      `interface ${decl.name.text}${heritage} {`,
      ...decl.members
        .slice(0, MAX_MEMBERS)
        .map((m) => `  ${this._renderMember(m, sf)}`),
      ...(hidden > 0 ? [`  // … ${hidden} more members`] : []),
      "}",
    ];
    return { name: decl.name.text, declaration: lines.join("\n") };
  }

  /**
   * Render an interface member with its documentation as a comment.
   *
   * @private
   */
  private _renderMember(m: ts.TypeElement, sf: ts.SourceFile): string {
    const doc = _compact(this._docOf(m.name));
    const text = _compact(
      this.printer.printNode(ts.EmitHint.Unspecified, m, sf),
    );
    return `${text}${doc ? ` // ${doc.slice(0, 160)}` : ""}`;
  }

  /**
   * Render a type alias, spelling out a union of literals.
   *
   * @private
   */
  private _renderAlias(decl: ts.TypeAliasDeclaration): TypeDeclaration {
    const type = this.checker.getTypeAtLocation(decl.name);
    const body =
      type.isUnion() && type.types.every((t) => t.isLiteral())
        ? type.types.map((t) => this.checker.typeToString(t)).join(" | ")
        : _compact(decl.type.getText(decl.getSourceFile()));
    return {
      name: decl.name.text,
      declaration: `type ${decl.name.text} = ${body};`,
    };
  }

  /**
   * Collect SDK declarations referenced from type nodes, breadth first.
   *
   * @private
   */
  private _collectTypes(roots: ts.Node[]): TypeDeclaration[] {
    const out: TypeDeclaration[] = [];
    const seen = new Set<string>();
    let frontier: ts.Node[] = roots;
    for (
      let depth = 0;
      depth < MAX_TYPE_DEPTH && frontier.length > 0;
      depth++
    ) {
      const next: ts.Node[] = [];
      const visit = (n: ts.Node) => {
        if (ts.isTypeReferenceNode(n)) {
          for (const decl of this._resolveRef(n)) {
            const name = decl.name.text;
            if (!seen.has(name) && out.length < MAX_REFERENCED_TYPES) {
              seen.add(name);
              out.push(this._render(decl));
              next.push(decl);
            }
          }
        }
        ts.forEachChild(n, visit);
      };
      frontier.forEach(visit);
      frontier = next;
    }
    return out;
  }

  /**
   * Produce an example expression for a type.
   *
   * @private
   */
  private _example(type: ts.Type, hint: unknown, depth: number): string {
    const fromUnion = type.isUnion()
      ? this._unionExample(type, hint, depth)
      : undefined;
    return (
      fromUnion ??
      SCALAR_EXAMPLES.find((s) => type.flags & s.flags)?.render(hint) ??
      this._structuredExample(type, hint, depth)
    );
  }

  /**
   * Example for a union: the hinted literal, the first literal, or an
   * example of the first non-null member.
   *
   * @private
   */
  private _unionExample(
    type: ts.UnionType,
    hint: unknown,
    depth: number,
  ): string | undefined {
    const nonNull = type.types.filter(
      (t) => !(t.flags & (ts.TypeFlags.Undefined | ts.TypeFlags.Null)),
    );
    const literals = nonNull.filter((t) => t.isLiteral());
    if (
      hint !== undefined &&
      literals.some((t) => (t as ts.LiteralType).value === hint)
    ) {
      return JSON.stringify(hint);
    }
    if (literals.length > 0) {
      return this.checker.typeToString(literals[0]);
    }
    // Under the SDK program's non-strict checking a union has no null or
    // undefined members; the filter guards a stricter configuration.
    const [first] = nonNull;
    return first && this._example(first, hint, depth);
  }

  /**
   * Example for a date, array or object type.
   *
   * @private
   */
  private _structuredExample(
    type: ts.Type,
    hint: unknown,
    depth: number,
  ): string {
    if (this.checker.typeToString(type) === "Date") {
      return `new Date(${JSON.stringify(typeof hint === "string" ? hint : "2026-01-31")})`;
    }
    if (this.checker.isArrayType(type)) {
      const [elem] = this.checker.getTypeArguments(type as ts.TypeReference);
      const h = Array.isArray(hint) ? hint[0] : undefined;
      return elem ? `[${this._example(elem, h, depth + 1)}]` : "[]";
    }
    if (type.flags & ts.TypeFlags.Object && depth < 3) {
      return this._objectExample(type, hint, depth);
    }
    return "undefined";
  }

  /**
   * Example object literal with the type's required properties.
   *
   * @private
   */
  private _objectExample(type: ts.Type, hint: unknown, depth: number): string {
    const props = type
      .getProperties()
      .filter((p) => !(p.flags & ts.SymbolFlags.Optional));
    if (props.length === 0) {
      return "{}";
    }
    const hintByName = _hintsByName(hint);
    const parts = props.slice(0, 12).map((p) => {
      const pt = this._propertyType(p) ?? this.checker.getAnyType();
      return `${p.name}: ${this._example(pt, hintByName.get(normaliseName(p.name)), depth + 1)}`;
    });
    return `{ ${parts.join(", ")} }`;
  }

  /**
   * Analyse every public method of every API class.
   *
   * @param {Map} impl - implementation bindings from {@link scanImplementation}
   * @param {Function} hintsFor - returns example hints for (method, path)
   * @return {Array} analysed methods
   */
  analyze(
    impl: Bindings,
    hintsFor: (httpMethod: string, p: string) => ExampleHints,
  ): AnalyzedMethod[] {
    const run: AnalyzeRun = {
      impl,
      hintsFor,
      found: new Set(),
      problems: [],
      methods: [],
    };
    for (const sf of this.program.getSourceFiles()) {
      if (this._isSdkFile(sf.fileName)) {
        ts.forEachChild(sf, (node) => this._analyzeClass(sf, node, run));
      }
    }
    for (const cls of impl.keys()) {
      if (!run.found.has(cls)) {
        run.problems.push(
          `${cls}: implementation found but no matching class in declarations`,
        );
      }
    }
    if (run.problems.length > 0) {
      throw new OagMcpError(
        "SDK_BINDING_AMBIGUOUS",
        `Could not reliably map SDK methods to HTTP operations: ${run.problems.slice(0, 5).join("; ")}`,
        {
          hint: "The SDK may have been modified after generation, or generated by an unsupported version. Regenerate it with a supported OpenAPI Generator version.",
          details: { problems: run.problems },
        },
      );
    }
    return run.methods.sort((a, b) =>
      `${a.className}.${a.methodName}`.localeCompare(
        `${b.className}.${b.methodName}`,
      ),
    );
  }

  /**
   * Analyse the public methods of a declared class that has bindings.
   *
   * @private
   */
  private _analyzeClass(sf: ts.SourceFile, node: ts.Node, run: AnalyzeRun) {
    if (!ts.isClassDeclaration(node) || !node.name) {
      return;
    }
    const cls = node.name.text;
    const bindings = run.impl.get(cls);
    if (!bindings) {
      return;
    }
    run.found.add(cls);
    for (const m of node.members.filter(_isApiMethod)) {
      const binding = bindings.get(m.name.text);
      if (binding) {
        run.methods.push(
          this._method(
            sf,
            cls,
            m,
            binding,
            run.hintsFor(binding.httpMethod, binding.path),
          ),
        );
      } else {
        run.problems.push(
          `${cls}.${m.name.text}: no HTTP method/path found in its RequestOpts/Raw implementation`,
        );
      }
    }
  }

  /**
   * Analyse a single method declaration.
   *
   * @private
   */
  private _method(
    sf: ts.SourceFile,
    cls: string,
    m: NamedMethod,
    binding: ImplBinding,
    hints: ExampleHints,
  ): AnalyzedMethod {
    const name = m.name.text;
    const params = m.parameters.map((p) => _param(p, sf));
    const apiParams = params.filter((p) => p.name !== "initOverrides");
    const returnType = m.type
      ? _compact(m.type.getText(sf))
      : "Promise<unknown>";
    const args = this._requestArgs(apiParams, hints);
    const referencedTypes = this._collectTypes(_typeRoots(apiParams, m));
    return {
      className: cls,
      methodName: name,
      httpMethod: binding.httpMethod,
      path: binding.path,
      signature: _compact(
        this.printer.printNode(ts.EmitHint.Unspecified, m, sf),
      ).replace(/;$/, ""),
      parameters: params.map(({ name: n, type, optional }) => ({
        name: n,
        type,
        optional,
      })),
      requestStyle: args.requestStyle,
      inputType: args.inputType,
      returnType,
      referencedTypes: referencedTypes.filter(
        (t) => t.name !== args.inputType?.name,
      ),
      requiredArguments: args.requiredArguments,
      documentation: this._docOf(m.name).trim(),
      deprecated: ts
        .getJSDocTags(m)
        .some((t) => t.tagName.text === "deprecated"),
      example: _exampleBody(
        `sdk.${cls}.${name}(${args.exampleArgs})`,
        returnType,
      ),
    };
  }

  /**
   * How a method takes its arguments: one request object, positional
   * arguments, or none.
   *
   * @private
   */
  private _requestArgs(apiParams: Param[], hints: ExampleHints): RequestArgs {
    if (apiParams.length === 1 && apiParams[0].name === "requestParameters") {
      return this._objectArgs(apiParams[0], hints);
    }
    if (apiParams.length > 0) {
      return this._positionalArgs(apiParams, hints);
    }
    return {
      requestStyle: "none",
      inputType: undefined,
      requiredArguments: [],
      exampleArgs: "",
    };
  }

  /**
   * Arguments of a method taking a single request object.
   *
   * @private
   */
  private _objectArgs(p: Param, hints: ExampleHints): RequestArgs {
    const type = this.checker.getNonNullableType(
      this.checker.getTypeAtLocation(p.node),
    );
    const ref =
      p.node.type && ts.isTypeReferenceNode(p.node.type)
        ? this._resolveRef(p.node.type)[0]
        : undefined;
    return {
      requestStyle: "object",
      inputType: ref ? this._render(ref) : undefined,
      requiredArguments: _requiredProperties(type),
      exampleArgs: this._example(type, this._hintObject(type, hints), 0),
    };
  }

  /**
   * Arguments of a method taking positional parameters.
   *
   * @private
   */
  private _positionalArgs(
    apiParams: Param[],
    hints: ExampleHints,
  ): RequestArgs {
    const required = apiParams.filter((p) => !p.optional);
    return {
      requestStyle: "positional",
      inputType: undefined,
      requiredArguments: required.map((p) => p.name),
      exampleArgs: required
        .map((p) => {
          const t = this.checker.getTypeAtLocation(p.node);
          const hint =
            hints[normaliseName(p.name)] ??
            (this._isPlainObject(t) ? hints.__body : undefined);
          return this._example(t, hint, 0);
        })
        .join(", "),
    };
  }

  /**
   * Map example hints onto the properties of a request type.
   *
   * @private
   */
  private _hintObject(
    type: ts.Type,
    hints: ExampleHints,
  ): Record<string, unknown> {
    const out: Record<string, unknown> = {};
    for (const p of type.getProperties()) {
      const h = hints[normaliseName(p.name)];
      if (h !== undefined) {
        out[p.name] = h;
      } else if (
        hints.__body !== undefined &&
        // The body parameter is usually the only object-typed property.
        this._isPlainObject(this._propertyType(p))
      ) {
        out[p.name] = hints.__body;
      }
    }
    return out;
  }
}

"use strict";
/**
 * Prepare the SDK once at server start-up: bundle it into a single ES module
 * for the Deno executor, and produce TypeScript declarations used to
 * type-check agent code. All output goes to the oag-mcp workspace; the SDK
 * is only read.
 *
 * @module prepare/bundle
 */
import fs from "node:fs";
import { createRequire } from "node:module";
import path from "node:path";

import * as esbuild from "esbuild";
import ts from "typescript";

import { OagMcpError } from "../errors.js";
import { listFiles } from "../util/hash.js";

const require = createRequire(import.meta.url);

/** Exports the runner requires from every SDK bundle. */
export const REQUIRED_RUNTIME_EXPORTS = ["Configuration", "BaseAPI"];

/** TypeScript libs made available to agent code. */
export const AGENT_TS_LIBS = [
  "lib.es2022.d.ts",
  "lib.dom.d.ts",
  "lib.dom.iterable.d.ts",
  "lib.dom.asynciterable.d.ts",
];

/** Compiler options used for SDK declarations and agent type checks. */
export function sdkCompilerOptions(): ts.CompilerOptions {
  return {
    target: ts.ScriptTarget.ES2022,
    module: ts.ModuleKind.ESNext,
    moduleResolution: ts.ModuleResolutionKind.Bundler,
    lib: AGENT_TS_LIBS,
    types: [],
    strict: false,
    skipLibCheck: true,
    allowJs: false,
    noEmitOnError: false,
    esModuleInterop: true,
  };
}

/**
 * Whether a JavaScript entry is CommonJS.
 *
 * @private
 */
function _isCommonJs(entry: string): boolean {
  if (entry.endsWith(".ts")) {
    return false;
  }
  const text = fs.readFileSync(entry, "utf8");
  return !/^\s*export\s/m.test(text) && /\b(exports\.|require\()/.test(text);
}

/**
 * Bundle the SDK into a single ESM file with all runtime dependencies.
 *
 * @param {Object} opts - options
 * @param {String} opts.entry - SDK entry module
 * @param {String} opts.root - SDK package root (for resolution; read-only)
 * @param {String} opts.outFile - bundle output path (in the workspace)
 * @param {String} opts.shimDir - workspace directory for a CommonJS entry shim
 * @param {Array} opts.classNames - API classes that must be exported
 * @return {Promise} { exports, bytes }
 */
export async function bundleSdk(opts: {
  entry: string;
  root: string;
  outFile: string;
  shimDir: string;
  classNames: string[];
}): Promise<{ exports: string[]; bytes: number }> {
  fs.mkdirSync(path.dirname(opts.outFile), { recursive: true });
  let entry = opts.entry;
  if (_isCommonJs(entry)) {
    // CommonJS entries lose named exports when bundled to ESM; re-export the
    // names the runner needs from a generated ESM shim.
    fs.mkdirSync(opts.shimDir, { recursive: true });
    const shim = path.join(opts.shimDir, "__oag_mcp_entry.mjs");
    const names = [
      ...new Set([
        ...REQUIRED_RUNTIME_EXPORTS,
        "ResponseError",
        "FetchError",
        "RequiredError",
        ...opts.classNames,
      ]),
    ];
    fs.writeFileSync(
      shim,
      `import __sdk from ${JSON.stringify(entry.split(path.sep).join("/"))};\n` +
        names.map((n) => `export const ${n} = __sdk.${n};`).join("\n") +
        "\n",
    );
    entry = shim;
  }
  let result: esbuild.BuildResult<{ metafile: true }>;
  try {
    result = await esbuild.build({
      entryPoints: [entry],
      absWorkingDir: opts.root,
      bundle: true,
      format: "esm",
      platform: "neutral",
      target: "es2022",
      mainFields: ["module", "main"],
      conditions: ["import", "default"],
      outfile: opts.outFile,
      metafile: true,
      write: true,
      logLevel: "silent",
      legalComments: "inline",
      banner: {
        js: "// oag-mcp SDK execution bundle. Generated from the user's OpenAPI Generator typescript-fetch SDK; do not edit.",
      },
    });
  } catch (err) {
    const errors = (err as esbuild.BuildFailure).errors ?? [];
    throw new OagMcpError(
      "SDK_BUNDLE_FAILED",
      `Bundling the SDK failed: ${errors
        .slice(0, 5)
        .map((e) => e.text)
        .join("; ")}`,
      {
        hint: "If the SDK has runtime dependencies, install them in the SDK directory yourself (e.g. `npm install --omit=dev --ignore-scripts`); oag-mcp never installs packages. Node.js built-in modules cannot be used by the sandboxed SDK.",
        cause: err,
      },
    );
  }
  const out = Object.values(result.metafile.outputs)[0];
  const exports = out?.exports ?? [];
  const missing = [...REQUIRED_RUNTIME_EXPORTS, ...opts.classNames].filter(
    (n) => !exports.includes(n),
  );
  if (missing.length > 0) {
    throw new OagMcpError(
      "SDK_BUNDLE_EXPORTS",
      `The SDK bundle does not export: ${missing.join(", ")}`,
      {
        hint: "The SDK index module must re-export runtime and apis (typescript-fetch does this by default). Check for a modified index.ts.",
      },
    );
  }
  return { exports, bytes: fs.statSync(opts.outFile).size };
}

/**
 * Emit TypeScript declarations for an SDK in source layout.
 *
 * @param {String} entry - SDK index.ts
 * @param {String} outDir - declarations output directory
 * @return {Array} non-fatal diagnostics
 */
export function emitDeclarations(entry: string, outDir: string): string[] {
  const options: ts.CompilerOptions = {
    ...sdkCompilerOptions(),
    declaration: true,
    emitDeclarationOnly: true,
    rootDir: path.dirname(entry),
    outDir,
  };
  const program = ts.createProgram([entry], options);
  const emit = program.emit();
  const diags = [...ts.getPreEmitDiagnostics(program), ...emit.diagnostics];
  const messages = diags
    .filter((d) => d.category === ts.DiagnosticCategory.Error)
    .map((d) => ts.flattenDiagnosticMessageText(d.messageText, "\n"));
  if (emit.emitSkipped || !fs.existsSync(path.join(outDir, "index.d.ts"))) {
    throw new OagMcpError(
      "SDK_DECLARATIONS_FAILED",
      `Emitting SDK declarations failed: ${messages.slice(0, 5).join("; ")}`,
    );
  }
  return messages;
}

/**
 * Copy compiled declarations into the workspace.
 *
 * @param {String} typesDir - SDK declarations directory (e.g. dist)
 * @param {String} outDir - workspace types directory
 */
export function copyDeclarations(typesDir: string, outDir: string): void {
  for (const rel of listFiles(typesDir, (r) => !r.startsWith("esm/"))) {
    if (rel.endsWith(".d.ts")) {
      const dest = path.join(outDir, rel);
      fs.mkdirSync(path.dirname(dest), { recursive: true });
      fs.copyFileSync(path.join(typesDir, rel), dest);
    }
  }
}

/**
 * Copy the transitive closure of TypeScript lib files needed for agent
 * type checks, so type checking works without the TypeScript package's lib
 * directory at runtime.
 *
 * @param {String} outDir - destination directory
 * @return {Array} copied file names
 */
export function copyTsLibs(outDir: string): string[] {
  const libDir = path.dirname(require.resolve("typescript/lib/lib.d.ts"));
  const seen = new Set<string>();
  const queue = [...AGENT_TS_LIBS];
  while (queue.length > 0) {
    const name = queue.shift()!;
    if (seen.has(name)) {
      continue;
    }
    seen.add(name);
    const text = fs.readFileSync(path.join(libDir, name), "utf8");
    for (const m of text.matchAll(/\/\/\/\s*<reference\s+lib="([^"]+)"/g)) {
      queue.push(`lib.${m[1].toLowerCase()}.d.ts`);
    }
  }
  fs.mkdirSync(outDir, { recursive: true });
  for (const name of seen) {
    fs.copyFileSync(path.join(libDir, name), path.join(outDir, name));
  }
  return [...seen].sort();
}

"use strict";
/**
 * Compatibility checks for OpenAPI Generator typescript-fetch SDKs.
 *
 * oag-mcp only supports typescript-fetch output from a tested set of
 * generator versions and options. This module detects the SDK layout
 * (TypeScript sources or compiled JavaScript with declarations), the
 * generator version and the options that shape the generated code, and
 * rejects anything it cannot support with an actionable error.
 *
 * @module prepare/compat
 */
import fs from "node:fs";
import path from "node:path";

import { OagMcpError } from "../errors.js";
import {
  SUPPORTED_GENERATOR,
  SUPPORTED_OAG_VERSIONS,
} from "../util/version.js";

/** Options known to produce unsupported output. */
export const UNSUPPORTED_GENERATOR_OPTIONS: Record<string, string> = {
  sagasAndRecords:
    "generates redux-saga/immutablejs code that cannot run in the sandbox",
  dateLibrary:
    "only the default 'date' library is supported (Temporal is experimental)",
  withNodeImports: "not applicable to typescript-fetch",
  stringEnums:
    "TypeScript enums cannot be referenced from agent code (no imports); use the default union types",
};

/** Detected SDK layout. */
export interface SdkInspection {
  root: string;
  layout: "source" | "compiled";
  /** Directory containing runtime and apis/ implementation files. */
  implDir: string;
  /** Module bundled into the execution bundle. */
  entry: string;
  /** Directory containing compiled declarations (compiled layout only). */
  typesDir?: string;
  oagVersion: string;
  oagVersionTested: boolean;
  detectedOptions: Record<string, string | boolean>;
  pkg?: {
    name?: string;
    version?: string;
    dependencies?: Record<string, string>;
  };
  apiFiles: string[];
  warnings: string[];
}

/** Options for {@link inspectSdk}. */
export interface InspectOptions {
  layout?: "auto" | "source" | "compiled";
  declaredOagVersion?: string;
  allowUntestedOagVersion?: boolean;
}

const OTHER_GENERATOR_MARKERS: Array<[RegExp, string]> = [
  [/from ['"]axios['"]|globalAxios/, "typescript-axios"],
  [/@angular\/core/, "typescript-angular"],
  [/from ['"]rxjs['"]/, "typescript-rxjs"],
  [/localVarRequest|from ['"]request['"]/, "typescript-node"],
  [/from ['"]jquery['"]/, "typescript-jquery"],
  [/ObservableAPI|PromiseAPI/, "typescript"],
];

/**
 * Read a file if it exists.
 *
 * @private
 */
function _read(file: string): string | undefined {
  try {
    return fs.readFileSync(file, "utf8");
  } catch {
    return undefined;
  }
}

/**
 * List API implementation files in `<implDir>/apis`.
 *
 * @private
 */
function _apiFiles(implDir: string, ext: "ts" | "js"): string[] {
  const dir = path.join(implDir, "apis");
  if (!fs.existsSync(dir)) {
    return [];
  }
  return fs
    .readdirSync(dir)
    .filter(
      (f) =>
        f.endsWith(`.${ext}`) &&
        !f.endsWith(".d.ts") &&
        !/^index\.(ts|js)$/.test(f) &&
        !/Sagas\.(ts|js)$/.test(f) &&
        f !== "SagaApiManager.ts" &&
        f !== "allSagas.ts",
    )
    .sort()
    .map((f) => path.join(dir, f));
}

/**
 * Verify the runtime module is typescript-fetch output.
 *
 * @private
 */
function _checkRuntime(runtimeFile: string, root: string): void {
  const text = _read(runtimeFile);
  if (text === undefined) {
    throw new OagMcpError(
      "SDK_LAYOUT_UNSUPPORTED",
      `typescript-fetch runtime module not found in ${root}`,
      {
        hint: "Expected src/runtime.ts (sources) or dist/runtime.js with dist/runtime.d.ts (compiled). Only OpenAPI Generator typescript-fetch SDKs are supported.",
      },
    );
  }
  for (const [re, gen] of OTHER_GENERATOR_MARKERS) {
    if (re.test(text)) {
      throw new OagMcpError(
        "SDK_GENERATOR_UNSUPPORTED",
        `The SDK in ${root} looks like OpenAPI Generator "${gen}" output`,
        {
          hint: `Only the ${SUPPORTED_GENERATOR} generator is supported. Regenerate the SDK with OpenAPI Generator -g ${SUPPORTED_GENERATOR}.`,
        },
      );
    }
  }
  const markers = ["BaseAPI", "Configuration", "fetchApi", "ResponseError"];
  const missing = markers.filter((m) => !text.includes(m));
  if (missing.length > 0) {
    throw new OagMcpError(
      "SDK_GENERATOR_UNSUPPORTED",
      `The SDK runtime in ${root} is missing typescript-fetch markers: ${missing.join(", ")}`,
      {
        hint: `Only OpenAPI Generator ${SUPPORTED_GENERATOR} SDKs are supported.`,
      },
    );
  }
}

/**
 * Detect generator options from the generated code.
 *
 * @private
 */
function _detectOptions(
  implDir: string,
  apiFiles: string[],
  declarationText: string,
): Record<string, string | boolean> {
  const opts: Record<string, string | boolean> = {};
  const apiText = apiFiles.map((f) => _read(f) ?? "").join("\n");
  opts.withInterfaces = /ApiInterface\b/.test(apiText + declarationText);
  const modelDir = path.join(implDir, "models");
  const modelText = fs.existsSync(modelDir)
    ? fs
        .readdirSync(modelDir)
        .map((f) => _read(path.join(modelDir, f)) ?? "")
        .join("\n")
    : "";
  opts.withoutRuntimeChecks = !/FromJSON/.test(apiText + modelText);
  opts.importFileExtension = /from ['"]\.\.?\/[^'"]+\.js['"]/.test(apiText)
    ? ".js"
    : "";
  const base = apiFiles.map((f) => path.basename(f));
  opts.fileNaming = base.some((b) => b.includes("-"))
    ? "kebab-case"
    : base.some((b) => /^[a-z]/.test(b))
      ? "camelCase"
      : "PascalCase";
  return opts;
}

/**
 * Determine the generator version recorded in `.openapi-generator/VERSION`.
 *
 * @private
 */
function _oagVersion(
  root: string,
  opts: InspectOptions,
): { version: string; tested: boolean } {
  const recorded = _read(path.join(root, ".openapi-generator", "VERSION"));
  const version = (recorded ?? opts.declaredOagVersion ?? "").trim();
  if (!version) {
    throw new OagMcpError(
      "SDK_OAG_VERSION_UNKNOWN",
      `Cannot determine the OpenAPI Generator version of the SDK in ${root}`,
      {
        hint: "The generator writes .openapi-generator/VERSION. If it was removed, pass --sdk-oag-version <version> to declare it.",
      },
    );
  }
  if (
    recorded &&
    opts.declaredOagVersion &&
    recorded.trim() !== opts.declaredOagVersion
  ) {
    throw new OagMcpError(
      "SDK_OAG_VERSION_CONFLICT",
      `--sdk-oag-version ${opts.declaredOagVersion} conflicts with .openapi-generator/VERSION ${recorded.trim()}`,
    );
  }
  const tested = (SUPPORTED_OAG_VERSIONS as readonly string[]).includes(
    version,
  );
  if (!tested && !opts.allowUntestedOagVersion) {
    throw new OagMcpError(
      "SDK_OAG_VERSION_UNSUPPORTED",
      `OpenAPI Generator ${version} is not in the tested set (${SUPPORTED_OAG_VERSIONS.join(", ")})`,
      {
        hint: `Regenerate the SDK with a tested OpenAPI Generator version (${SUPPORTED_OAG_VERSIONS.join(", ")}), or pass --allow-untested-oag-version to proceed at your own risk.`,
      },
    );
  }
  return { version, tested };
}

/** A compiled SDK package's entry point and declarations. */
interface CompiledLayout {
  implDir: string;
  entry: string;
  typesDir: string;
}

/** The SDK layout chosen for preparation. */
interface ResolvedLayout {
  layout: "source" | "compiled";
  /** Directory with runtime, apis/ and models/. */
  implDir: string;
  /** Extension of the implementation files. */
  ext: "ts" | "js";
  entry: string;
  /** Declarations directory of a compiled package. */
  typesDir?: string;
}

/** The parsed package.json of an SDK. */
type SdkPackage = Record<string, unknown>;

/**
 * Read the SDK's package.json, if it has one.
 *
 * @private
 */
function _readPackage(
  root: string,
  warnings: string[],
): SdkPackage | undefined {
  const pkgText = _read(path.join(root, "package.json"));
  if (!pkgText) {
    warnings.push(
      "SDK has no package.json (generated without npmName); it can still be imported by path.",
    );
    return undefined;
  }
  try {
    return JSON.parse(pkgText) as SdkPackage;
  } catch {
    throw new OagMcpError(
      "SDK_PACKAGE_INVALID",
      `package.json in ${root} is not valid JSON`,
    );
  }
}

/**
 * Reject an SDK generated with an unsupported option.
 *
 * @private
 */
function _unsupported(option: string, setting: string): never {
  throw new OagMcpError(
    "SDK_OPTION_UNSUPPORTED",
    `The SDK was generated with ${setting}, which is not supported`,
    { hint: UNSUPPORTED_GENERATOR_OPTIONS[option] },
  );
}

/**
 * The directory with typescript-fetch sources (`index.ts` and
 * `runtime.ts`): `src/` or the root.
 *
 * @private
 */
function _sourceDir(root: string): string | undefined {
  return [path.join(root, "src"), root].find(
    (d) =>
      fs.existsSync(path.join(d, "runtime.ts")) &&
      fs.existsSync(path.join(d, "index.ts")),
  );
}

/**
 * The compiled package layout: the first of `module`, `main` and
 * `dist/index.js` with a runtime beside it and declarations.
 *
 * @private
 */
function _compiledLayout(
  root: string,
  pkg: SdkPackage | undefined,
): CompiledLayout | undefined {
  const p = (pkg ?? {}) as Record<string, string>;
  const typesFile = p.types ?? p.typings ?? "dist/index.d.ts";
  const typesDir = path.dirname(path.join(root, typesFile));
  for (const entryRel of [p.module, p.main, "dist/index.js"].filter(Boolean)) {
    const entry = path.join(root, entryRel);
    const implDir = path.dirname(entry);
    if (
      fs.existsSync(entry) &&
      fs.existsSync(path.join(implDir, "runtime.js")) &&
      fs.existsSync(path.join(typesDir, "index.d.ts"))
    ) {
      return { implDir, entry, typesDir };
    }
  }
  return undefined;
}

/**
 * Choose the layout: sources when requested or found (`auto`), otherwise
 * the compiled package.
 *
 * @private
 */
function _resolveLayout(
  root: string,
  pkg: SdkPackage | undefined,
  wanted: InspectOptions["layout"] = "auto",
): ResolvedLayout {
  const sourceDir = _sourceDir(root);
  if (wanted === "source" || (wanted === "auto" && sourceDir)) {
    if (!sourceDir) {
      throw new OagMcpError(
        "SDK_LAYOUT_UNSUPPORTED",
        `No typescript-fetch sources (src/index.ts, src/runtime.ts) found in ${root}`,
        {
          hint: "Use --sdk-layout compiled for packages that ship only dist/.",
        },
      );
    }
    return {
      layout: "source",
      implDir: sourceDir,
      ext: "ts",
      entry: path.join(sourceDir, "index.ts"),
    };
  }
  const compiled = _compiledLayout(root, pkg);
  if (!compiled) {
    throw new OagMcpError(
      "SDK_LAYOUT_UNSUPPORTED",
      `Unrecognised SDK layout in ${root}`,
      {
        hint: "Expected typescript-fetch sources (src/index.ts, src/runtime.ts, src/apis/) or a compiled package (dist/index.js, dist/runtime.js, dist/index.d.ts). See docs/sdk-compatibility.md.",
      },
    );
  }
  return { layout: "compiled", ext: "js", ...compiled };
}

/**
 * Whether any model is generated as a TypeScript enum (stringEnums=true).
 * Sources declare `export enum`; compiled SDKs are checked through their
 * declarations (`export declare enum`), which are the same whatever module
 * format the JavaScript was compiled to, and which a compiled SDK always
 * has even when its JavaScript directory holds none.
 *
 * @private
 */
function _hasEnumDeclarations(dirs: string[]): boolean {
  return dirs.some((dir) => {
    const modelsDir = path.join(dir, "models");
    return (
      fs.existsSync(modelsDir) &&
      fs
        .readdirSync(modelsDir)
        .some((f) =>
          /export (declare )?enum /.test(_read(path.join(modelsDir, f)) ?? ""),
        )
    );
  });
}

/**
 * Reject generator options oag-mcp does not support: sagasAndRecords,
 * stringEnums and the Temporal date library.
 *
 * @private
 */
function _checkGeneratorOptions(resolved: ResolvedLayout): void {
  const { implDir, ext } = resolved;
  if (
    fs.existsSync(path.join(implDir, "ApiEntitiesRecord.ts")) ||
    fs.existsSync(path.join(implDir, "apis", "allSagas.ts"))
  ) {
    _unsupported("sagasAndRecords", "sagasAndRecords");
  }
  if (_hasEnumDeclarations([implDir, resolved.typesDir ?? implDir])) {
    _unsupported("stringEnums", "stringEnums=true");
  }
  const runtimeText = _read(path.join(implDir, `runtime.${ext}`)) ?? "";
  if (/Temporal\./.test(runtimeText)) {
    _unsupported("dateLibrary", "dateLibrary=temporal");
  }
}

/**
 * The SDK's generated API class files, of which there must be at least one.
 *
 * @private
 */
function _requireApiFiles(resolved: ResolvedLayout): string[] {
  const apiFiles = _apiFiles(resolved.implDir, resolved.ext);
  if (apiFiles.length === 0) {
    throw new OagMcpError(
      "SDK_LAYOUT_UNSUPPORTED",
      `No API classes found in ${path.join(resolved.implDir, "apis")}`,
      {
        hint: "The SDK must contain generated API classes (apis/*Api). Check that the spec has operations and that generation succeeded.",
      },
    );
  }
  return apiFiles;
}

/**
 * The API declarations of a compiled package, for option detection.
 *
 * @private
 */
function _apiDeclarations(resolved: ResolvedLayout): string {
  if (resolved.layout !== "compiled") {
    return "";
  }
  const apisDir = path.join(resolved.typesDir!, "apis");
  return fs
    .readdirSync(apisDir)
    .filter((f) => f.endsWith(".d.ts"))
    .map((f) => _read(path.join(apisDir, f)) ?? "")
    .join("\n");
}

/**
 * The package fields reported in the inspection.
 *
 * @private
 */
function _packageInfo(pkg: SdkPackage | undefined): SdkInspection["pkg"] {
  if (!pkg) {
    return undefined;
  }
  return {
    name: pkg.name as string,
    version: pkg.version as string,
    dependencies: pkg.dependencies as Record<string, string> | undefined,
  };
}

/**
 * Inspect an SDK working copy and verify it is supported.
 *
 * @param {String} root - SDK working copy root
 * @param {Object} [opts] - inspection options
 * @return {Object} inspection result
 */
export function inspectSdk(
  root: string,
  opts: InspectOptions = {},
): SdkInspection {
  const warnings: string[] = [];
  const pkg = _readPackage(root, warnings);
  if (/redux-saga|immutable/.test(JSON.stringify(pkg?.dependencies ?? {}))) {
    _unsupported("sagasAndRecords", "sagasAndRecords");
  }
  const resolved = _resolveLayout(root, pkg, opts.layout);
  _checkRuntime(path.join(resolved.implDir, `runtime.${resolved.ext}`), root);
  _checkGeneratorOptions(resolved);
  const apiFiles = _requireApiFiles(resolved);
  const { version, tested } = _oagVersion(root, opts);
  if (!tested) {
    warnings.push(
      `OpenAPI Generator ${version} is untested; proceeding because --allow-untested-oag-version was given.`,
    );
  }
  return {
    root,
    layout: resolved.layout,
    implDir: resolved.implDir,
    entry: resolved.entry,
    typesDir: resolved.typesDir,
    oagVersion: version,
    oagVersionTested: tested,
    detectedOptions: _detectOptions(
      resolved.implDir,
      apiFiles,
      _apiDeclarations(resolved),
    ),
    pkg: _packageInfo(pkg),
    apiFiles,
    warnings,
  };
}

"use strict";
/**
 * Merge SDK analysis with OpenAPI operations into method records.
 *
 * Bindings are matched on HTTP method plus path template. Methods that
 * match no operation, or more than one, are reported as errors rather than
 * guessed.
 *
 * @module prepare/method-records
 */
import { OagMcpError } from "../errors.js";
import type {
  AuthSummary,
  MethodRecord,
  OperationBinding,
  SecurityRequirement,
  SecuritySchemeInfo,
  SpecOperation,
  SpecSummary,
} from "../types.js";
import {
  type AnalyzedMethod,
  type ExampleHints,
  normaliseName,
} from "./analyze.js";

/**
 * Normalise a path template so parameter names do not matter.
 *
 * @param {String} p - path template
 * @return {String} normalised template
 */
export function normalisePathTemplate(p: string): string {
  return p.replace(/\{[^}]+\}/g, "{}").replace(/\/+$/, "") || "/";
}

/**
 * Build example hints for an operation from its OpenAPI parameters and body.
 *
 * @param {Object} op - spec operation
 * @return {Object} hints keyed by normalised name
 */
export function hintsForOperation(op: SpecOperation | undefined): ExampleHints {
  const hints: ExampleHints = {};
  if (!op) {
    return hints;
  }
  for (const p of op.parameters) {
    if (p.example !== undefined) {
      hints[normaliseName(p.name)] = p.example;
    }
  }
  if (op.requestBody?.example !== undefined) {
    hints.__body = op.requestBody.example;
  }
  return hints;
}

/**
 * How a scheme is shown to agents, e.g. "http-bearer" or "apiKey-header".
 *
 * @private
 */
function _schemeType(s: SecuritySchemeInfo | undefined): string {
  if (!s) {
    return "undefined-scheme";
  }
  switch (s.type) {
    case "http":
      return `http-${s.scheme}`;
    case "apiKey":
      return `apiKey-${s.in}`;
    case "oauth2":
      return "oauth2-client-credentials";
    default:
      return s.type;
  }
}

/**
 * Summarise authentication requirements for agents.
 *
 * @param {Array} security - effective requirement alternatives
 * @param {Object} schemes - security schemes
 * @return {Object} auth summary
 */
export function summariseAuth(
  security: SecurityRequirement[],
  schemes: Record<string, SecuritySchemeInfo>,
): AuthSummary {
  const unsupported = new Set<string>();
  const alternatives = security
    .filter((req) => Object.keys(req).length > 0)
    .map((req) => ({
      schemes: Object.entries(req).map(([name, scopes]) => {
        const s = schemes[name];
        if (!s || !s.supported) {
          unsupported.add(name);
        }
        const type = _schemeType(s);
        return { name, type, scopes };
      }),
    }));
  return {
    alternatives,
    optional:
      security.length === 0 ||
      security.some((r) => Object.keys(r).length === 0),
    unsupportedSchemes: [...unsupported].sort(),
  };
}

/** Spec operations by key, and by method and normalised path. */
interface OperationIndex {
  byKey: Map<string, SpecOperation>;
  byNormalised: Map<string, SpecOperation[]>;
}

/**
 * Index the spec's operations for matching.
 *
 * @private
 */
function _operationIndex(spec: SpecSummary): OperationIndex {
  const byKey = new Map<string, SpecOperation>();
  const byNormalised = new Map<string, SpecOperation[]>();
  for (const op of spec.operations) {
    byKey.set(op.key, op);
    const nk = `${op.method} ${normalisePathTemplate(op.path)}`;
    byNormalised.set(nk, [...(byNormalised.get(nk) ?? []), op]);
  }
  return { byKey, byNormalised };
}

/**
 * The operation an SDK method calls: the one with its exact method and
 * path, or the only one matching once path parameter names are ignored.
 * Otherwise the problem is recorded and undefined returned.
 *
 * @private
 */
function _matchOperation(
  m: AnalyzedMethod,
  index: OperationIndex,
  problems: string[],
): SpecOperation | undefined {
  const exact = index.byKey.get(`${m.httpMethod} ${m.path}`);
  if (exact) {
    return exact;
  }
  const candidates =
    index.byNormalised.get(
      `${m.httpMethod} ${normalisePathTemplate(m.path)}`,
    ) ?? [];
  if (candidates.length === 1) {
    return candidates[0];
  }
  const method = `${m.className}.${m.methodName} (${m.httpMethod} ${m.path})`;
  problems.push(
    candidates.length > 1
      ? `${method} matches several operations: ${candidates.map((c) => c.key).join(", ")}`
      : `${method} has no matching operation in the spec`,
  );
  return undefined;
}

/**
 * The method record of an SDK method bound to its operation.
 *
 * @private
 */
function _record(
  m: AnalyzedMethod,
  op: SpecOperation,
  spec: SpecSummary,
): MethodRecord {
  const id = `${m.className}.${m.methodName}`;
  return {
    id,
    className: m.className,
    methodName: m.methodName,
    sdkPath: `sdk.${id}`,
    operationId: op.operationId,
    httpMethod: op.method,
    path: op.path,
    tags: op.tags,
    summary: op.summary,
    description: op.description ?? (m.documentation || undefined),
    deprecated: op.deprecated || m.deprecated,
    signature: m.signature,
    parameters: m.parameters,
    inputType: m.inputType,
    returnType: m.returnType,
    referencedTypes: m.referencedTypes,
    requiredArguments: m.requiredArguments,
    apiParameters: op.parameters,
    requestBody: op.requestBody,
    responses: op.responses,
    auth: summariseAuth(op.security, spec.securitySchemes),
    security: op.security,
    example: m.example,
  };
}

/**
 * Build method records and operation bindings.
 *
 * @param {Object} spec - spec summary
 * @param {Array} methods - analysed SDK methods
 * @return {Object} { records, bindings, unmapped }
 */
export function buildRecords(
  spec: SpecSummary,
  methods: AnalyzedMethod[],
): {
  records: MethodRecord[];
  bindings: OperationBinding[];
  unmapped: Array<{ key: string; operationId?: string }>;
} {
  const index = _operationIndex(spec);
  const problems: string[] = [];
  const records: MethodRecord[] = [];
  const bound = new Set<string>();
  for (const m of methods) {
    const op = _matchOperation(m, index, problems);
    if (op) {
      bound.add(op.key);
      records.push(_record(m, op, spec));
    }
  }
  if (problems.length > 0) {
    throw new OagMcpError(
      "SDK_SPEC_MISMATCH",
      `The SDK does not match the OpenAPI document: ${problems.slice(0, 5).join("; ")}`,
      {
        hint: "Make sure --spec is the document the SDK was generated from (or regenerate the SDK from this document), then restart oag-mcp.",
        details: { problems },
      },
    );
  }
  if (records.length === 0) {
    throw new OagMcpError(
      "SDK_NO_METHODS",
      "No SDK methods could be bound to OpenAPI operations",
    );
  }
  const unmapped = spec.operations
    .filter((op) => !bound.has(op.key))
    .map((op) => ({ key: op.key, operationId: op.operationId }));
  const bindings: OperationBinding[] = records.map((r) => ({
    id: r.id,
    className: r.className,
    methodName: r.methodName,
    httpMethod: r.httpMethod,
    path: r.path,
    operationId: r.operationId,
    tags: r.tags,
    security: r.security,
  }));
  return { records, bindings, unmapped };
}

"use strict";
/**
 * Resolve an existing SDK input (package directory or npm package archive).
 *
 * Directories are read in place and never written to: declarations and the
 * execution bundle are produced in the oag-mcp workspace, and dependencies
 * resolve from the SDK's own `node_modules` (or a parent's). Archives are
 * extracted safely into the workspace. The supplied SDK is never modified.
 *
 * @module prepare/sdk-input
 */
import fs from "node:fs";
import path from "node:path";

import * as tar from "tar";

import { OagMcpError } from "../errors.js";
import { sha256File, sha256Tree } from "../util/hash.js";

/** Limits applied when extracting archives. */
export const ARCHIVE_LIMITS = {
  maxEntries: 20000,
  maxTotalBytes: 256 * 1024 * 1024,
};

/** Entry types allowed in SDK archives. */
const ALLOWED_ENTRY_TYPES = new Set([
  "File",
  "OldFile",
  "ContiguousFile",
  "Directory",
]);

/** Result of resolving an SDK input. */
export interface StagedSdk {
  /**
   * Package root (directory containing package.json/src): the supplied
   * directory itself (read-only use) or the extracted archive.
   */
  root: string;
  kind: "directory" | "archive";
  /** Hash of the original input (archive bytes or directory tree). */
  sha256: string;
}

const IGNORED_TREE_ENTRIES = new Set([".git", "node_modules"]);

/**
 * Validate an archive entry path, returning a reason when unsafe.
 *
 * @param {String} entryPath - path recorded in the archive
 * @return {String|undefined} rejection reason
 */
export function unsafeArchivePath(entryPath: string): string | undefined {
  if (!entryPath || entryPath.includes("\0")) {
    return "empty or NUL-containing path";
  }
  if (
    entryPath.startsWith("/") ||
    entryPath.startsWith("\\") ||
    /^[a-zA-Z]:/.test(entryPath)
  ) {
    return "absolute path";
  }
  const segments = entryPath.split(/[\\/]+/);
  if (segments.includes("..")) {
    return "parent directory traversal";
  }
  return undefined;
}

/**
 * Extract an npm package archive safely into `dest`.
 *
 * Entries are validated before extraction: absolute paths, `..` traversal,
 * links, devices and FIFOs are rejected, and entry count and total size are
 * bounded. After extraction every path is checked to resolve inside `dest`.
 *
 * @param {String} archive - path to the .tgz archive
 * @param {String} dest - empty destination directory
 * @return {Promise} absolute path of the package root inside `dest`
 */
export async function extractArchive(
  archive: string,
  dest: string,
): Promise<string> {
  const problems: string[] = [];
  let count = 0;
  let total = 0;
  const topLevel = new Set<string>();
  try {
    await tar.t({
      file: archive,
      strict: true,
      onReadEntry: (entry) => {
        count++;
        total += entry.size ?? 0;
        const reason = unsafeArchivePath(entry.path);
        if (reason) {
          problems.push(`${entry.path}: ${reason}`);
        }
        if (!ALLOWED_ENTRY_TYPES.has(String(entry.type))) {
          problems.push(`${entry.path}: entry type ${entry.type} not allowed`);
        }
        topLevel.add(entry.path.split(/[\\/]+/)[0]);
      },
    });
  } catch (err) {
    throw new OagMcpError(
      "SDK_ARCHIVE_INVALID",
      `SDK archive ${archive} could not be read: ${(err as Error).message}`,
      {
        hint: "Provide a gzip-compressed npm package archive, e.g. created with `npm pack`.",
        cause: err,
      },
    );
  }
  if (count > ARCHIVE_LIMITS.maxEntries) {
    problems.push(`too many entries (${count} > ${ARCHIVE_LIMITS.maxEntries})`);
  }
  if (total > ARCHIVE_LIMITS.maxTotalBytes) {
    problems.push(
      `uncompressed size too large (${total} > ${ARCHIVE_LIMITS.maxTotalBytes} bytes)`,
    );
  }
  if (problems.length > 0) {
    throw new OagMcpError(
      "SDK_ARCHIVE_UNSAFE",
      `SDK archive ${archive} contains unsafe entries: ${problems.slice(0, 5).join("; ")}`,
      {
        hint: "Repack the SDK with `npm pack`; archives must not contain links, absolute paths or '..' segments.",
        details: { problems: problems.slice(0, 20) },
      },
    );
  }
  if (topLevel.size !== 1) {
    throw new OagMcpError(
      "SDK_ARCHIVE_LAYOUT",
      `SDK archive must contain a single top-level directory (found: ${[...topLevel].join(", ")})`,
      { hint: "npm pack archives contain a single `package/` directory." },
    );
  }
  fs.mkdirSync(dest, { recursive: true });
  await tar.x({
    file: archive,
    cwd: dest,
    strict: true,
    preservePaths: false,
    noChmod: true,
    filter: (_p, entry) =>
      ALLOWED_ENTRY_TYPES.has(String((entry as tar.ReadEntry).type)),
  });
  const realDest = fs.realpathSync(dest);
  const root = path.join(realDest, [...topLevel][0]);
  const check = (dir: string) => {
    for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
      const abs = path.join(dir, e.name);
      if (e.isSymbolicLink()) {
        throw new OagMcpError(
          "SDK_ARCHIVE_UNSAFE",
          `Extracted archive contains a link: ${path.relative(realDest, abs)}`,
        );
      }
      const real = fs.realpathSync(abs);
      if (!real.startsWith(realDest + path.sep)) {
        throw new OagMcpError(
          "SDK_ARCHIVE_UNSAFE",
          `Extracted path escapes destination: ${path.relative(realDest, abs)}`,
        );
      }
      if (e.isDirectory()) {
        check(abs);
      }
    }
  };
  check(realDest);
  return root;
}

/**
 * Resolve an SDK input. Archives are extracted into `workDir`; directories
 * are used in place, read-only.
 *
 * @param {String} input - SDK directory or .tgz archive path
 * @param {String} workDir - private workspace directory for extraction
 * @return {Promise} staged SDK
 */
export async function stageSdkInput(
  input: string,
  workDir: string,
): Promise<StagedSdk> {
  const abs = path.resolve(input);
  if (!fs.existsSync(abs)) {
    throw new OagMcpError("SDK_NOT_FOUND", `SDK path ${input} does not exist`, {
      hint: "Pass --sdk <directory|package.tgz> pointing at an existing OpenAPI Generator typescript-fetch SDK.",
    });
  }
  const stat = fs.statSync(abs);
  if (stat.isDirectory()) {
    return {
      root: fs.realpathSync(abs),
      kind: "directory",
      sha256: sha256Tree(
        abs,
        (rel) => !rel.split("/").some((s) => IGNORED_TREE_ENTRIES.has(s)),
      ),
    };
  }
  if (/\.(tgz|tar\.gz)$/i.test(abs)) {
    const root = await extractArchive(abs, workDir);
    return { root, kind: "archive", sha256: sha256File(abs) };
  }
  throw new OagMcpError(
    "SDK_INPUT_UNSUPPORTED",
    `SDK input ${input} is neither a directory nor a .tgz package archive`,
    {
      hint: "Use a generated typescript-fetch SDK directory or an archive produced by `npm pack`.",
    },
  );
}

/**
 * Find the runtime dependencies of an SDK that cannot be resolved from its
 * root, using Node.js lookup rules (`node_modules` in the root or any
 * parent directory). Nothing is installed.
 *
 * @param {String} root - SDK package root
 * @param {Object} [deps] - package.json dependencies
 * @return {Array} names of missing dependencies
 */
export function missingDependencies(
  root: string,
  deps: Record<string, string> | undefined,
): string[] {
  return Object.keys(deps ?? {}).filter((name) => {
    for (let dir = root; ; dir = path.dirname(dir)) {
      if (fs.existsSync(path.join(dir, "node_modules", name, "package.json"))) {
        return false;
      }
      if (path.dirname(dir) === dir) {
        return true;
      }
    }
  });
}

import EE from 'events'
import fs from 'fs'
import { Minipass } from 'minipass'

const writev = fs.writev

const _autoClose = Symbol('_autoClose')
const _close = Symbol('_close')
const _ended = Symbol('_ended')
const _fd = Symbol('_fd')
const _finished = Symbol('_finished')
const _flags = Symbol('_flags')
const _flush = Symbol('_flush')
const _handleChunk = Symbol('_handleChunk')
const _makeBuf = Symbol('_makeBuf')
const _mode = Symbol('_mode')
const _needDrain = Symbol('_needDrain')
const _onerror = Symbol('_onerror')
const _onopen = Symbol('_onopen')
const _onread = Symbol('_onread')
const _onwrite = Symbol('_onwrite')
const _open = Symbol('_open')
const _path = Symbol('_path')
const _pos = Symbol('_pos')
const _queue = Symbol('_queue')
const _read = Symbol('_read')
const _readSize = Symbol('_readSize')
const _reading = Symbol('_reading')
const _remain = Symbol('_remain')
const _size = Symbol('_size')
const _write = Symbol('_write')
const _writing = Symbol('_writing')
const _defaultFlag = Symbol('_defaultFlag')
const _errored = Symbol('_errored')

export type ReadStreamOptions =
  Minipass.Options<Minipass.ContiguousData> & {
    fd?: number
    readSize?: number
    size?: number
    autoClose?: boolean
  }

export type ReadStreamEvents = Minipass.Events<Minipass.ContiguousData> & {
  open: [fd: number]
}

export class ReadStream extends Minipass<
  Minipass.ContiguousData,
  Buffer,
  ReadStreamEvents
> {
  [_errored]: boolean = false;
  [_fd]?: number;
  [_path]: string;
  [_readSize]: number;
  [_reading]: boolean = false;
  [_size]: number;
  [_remain]: number;
  [_autoClose]: boolean

  constructor(path: string, opt: ReadStreamOptions) {
    opt = opt || {}
    super(opt)

    this.readable = true
    this.writable = false

    if (typeof path !== 'string') {
      throw new TypeError('path must be a string')
    }

    this[_errored] = false
    this[_fd] = typeof opt.fd === 'number' ? opt.fd : undefined
    this[_path] = path
    this[_readSize] = opt.readSize || 16 * 1024 * 1024
    this[_reading] = false
    this[_size] = typeof opt.size === 'number' ? opt.size : Infinity
    this[_remain] = this[_size]
    this[_autoClose] =
      typeof opt.autoClose === 'boolean' ? opt.autoClose : true

    if (typeof this[_fd] === 'number') {
      this[_read]()
    } else {
      this[_open]()
    }
  }

  get fd() {
    return this[_fd]
  }

  get path() {
    return this[_path]
  }

  //@ts-ignore
  write() {
    throw new TypeError('this is a readable stream')
  }

  //@ts-ignore
  end() {
    throw new TypeError('this is a readable stream')
  }

  [_open]() {
    fs.open(this[_path], 'r', (er, fd) => this[_onopen](er, fd))
  }

  [_onopen](er?: NodeJS.ErrnoException | null, fd?: number) {
    if (er) {
      this[_onerror](er)
    } else {
      this[_fd] = fd
      this.emit('open', fd as number)
      this[_read]()
    }
  }

  [_makeBuf]() {
    return Buffer.allocUnsafe(Math.min(this[_readSize], this[_remain]))
  }

  [_read]() {
    if (!this[_reading]) {
      this[_reading] = true
      const buf = this[_makeBuf]()
      /* c8 ignore start */
      if (buf.length === 0) {
        return process.nextTick(() => this[_onread](null, 0, buf))
      }
      /* c8 ignore stop */
      fs.read(this[_fd] as number, buf, 0, buf.length, null, (er, br, b) =>
        this[_onread](er, br, b),
      )
    }
  }

  [_onread](er?: NodeJS.ErrnoException | null, br?: number, buf?: Buffer) {
    this[_reading] = false
    if (er) {
      this[_onerror](er)
    } else if (this[_handleChunk](br as number, buf as Buffer)) {
      this[_read]()
    }
  }

  [_close]() {
    if (this[_autoClose] && typeof this[_fd] === 'number') {
      const fd = this[_fd]
      this[_fd] = undefined
      fs.close(fd, er =>
        er ? this.emit('error', er) : this.emit('close'),
      )
    }
  }

  [_onerror](er: NodeJS.ErrnoException) {
    this[_reading] = true
    this[_close]()
    this.emit('error', er)
  }

  [_handleChunk](br: number, buf: Buffer) {
    let ret = false
    // no effect if infinite
    this[_remain] -= br
    if (br > 0) {
      ret = super.write(br < buf.length ? buf.subarray(0, br) : buf)
    }

    if (br === 0 || this[_remain] <= 0) {
      ret = false
      this[_close]()
      super.end()
    }

    return ret
  }

  emit<Event extends keyof ReadStreamEvents>(
    ev: Event,
    ...args: ReadStreamEvents[Event]
  ): boolean {
    switch (ev) {
      case 'prefinish':
      case 'finish':
        return false

      case 'drain':
        if (typeof this[_fd] === 'number') {
          this[_read]()
        }
        return false

      case 'error':
        if (this[_errored]) {
          return false
        }
        this[_errored] = true
        return super.emit(ev, ...args)

      default:
        return super.emit(ev, ...args)
    }
  }
}

export class ReadStreamSync extends ReadStream {
  [_open]() {
    let threw = true
    try {
      this[_onopen](null, fs.openSync(this[_path], 'r'))
      threw = false
    } finally {
      if (threw) {
        this[_close]()
      }
    }
  }

  [_read]() {
    let threw = true
    try {
      if (!this[_reading]) {
        this[_reading] = true
        do {
          const buf = this[_makeBuf]()
          /* c8 ignore start */
          const br =
            buf.length === 0
              ? 0
              : fs.readSync(this[_fd] as number, buf, 0, buf.length, null)
          /* c8 ignore stop */
          if (!this[_handleChunk](br, buf)) {
            break
          }
        } while (true)
        this[_reading] = false
      }
      threw = false
    } finally {
      if (threw) {
        this[_close]()
      }
    }
  }

  [_close]() {
    if (this[_autoClose] && typeof this[_fd] === 'number') {
      const fd = this[_fd]
      this[_fd] = undefined
      fs.closeSync(fd)
      this.emit('close')
    }
  }
}

export type WriteStreamOptions = {
  fd?: number
  autoClose?: boolean
  mode?: number
  captureRejections?: boolean
  start?: number
  flags?: string
}

export class WriteStream extends EE {
  readable: false = false
  writable: boolean = true;
  [_errored]: boolean = false;
  [_writing]: boolean = false;
  [_ended]: boolean = false;
  [_queue]: Buffer[] = [];
  [_needDrain]: boolean = false;
  [_path]: string;
  [_mode]: number;
  [_autoClose]: boolean;
  [_fd]?: number;
  [_defaultFlag]: boolean;
  [_flags]: string;
  [_finished]: boolean = false;
  [_pos]?: number

  constructor(path: string, opt: WriteStreamOptions) {
    opt = opt || {}
    super(opt)
    this[_path] = path
    this[_fd] = typeof opt.fd === 'number' ? opt.fd : undefined
    this[_mode] = opt.mode === undefined ? 0o666 : opt.mode
    this[_pos] = typeof opt.start === 'number' ? opt.start : undefined
    this[_autoClose] =
      typeof opt.autoClose === 'boolean' ? opt.autoClose : true

    // truncating makes no sense when writing into the middle
    const defaultFlag = this[_pos] !== undefined ? 'r+' : 'w'
    this[_defaultFlag] = opt.flags === undefined
    this[_flags] = opt.flags === undefined ? defaultFlag : opt.flags

    if (this[_fd] === undefined) {
      this[_open]()
    }
  }

  emit(ev: string, ...args: any[]) {
    if (ev === 'error') {
      if (this[_errored]) {
        return false
      }
      this[_errored] = true
    }
    return super.emit(ev, ...args)
  }

  get fd() {
    return this[_fd]
  }

  get path() {
    return this[_path]
  }

  [_onerror](er: NodeJS.ErrnoException) {
    this[_close]()
    this[_writing] = true
    this.emit('error', er)
  }

  [_open]() {
    fs.open(this[_path], this[_flags], this[_mode], (er, fd) =>
      this[_onopen](er, fd),
    )
  }

  [_onopen](er?: null | NodeJS.ErrnoException, fd?: number) {
    if (
      this[_defaultFlag] &&
      this[_flags] === 'r+' &&
      er &&
      er.code === 'ENOENT'
    ) {
      this[_flags] = 'w'
      this[_open]()
    } else if (er) {
      this[_onerror](er)
    } else {
      this[_fd] = fd
      this.emit('open', fd)
      if (!this[_writing]) {
        this[_flush]()
      }
    }
  }

  end(buf: string, enc?: BufferEncoding): this
  end(buf?: Buffer, enc?: undefined): this
  end(buf?: Buffer | string, enc?: BufferEncoding): this {
    if (buf) {
      //@ts-ignore
      this.write(buf, enc)
    }

    this[_ended] = true

    // synthetic after-write logic, where drain/finish live
    if (
      !this[_writing] &&
      !this[_queue].length &&
      typeof this[_fd] === 'number'
    ) {
      this[_onwrite](null, 0)
    }
    return this
  }

  write(buf: string, enc?: BufferEncoding): boolean
  write(buf: Buffer, enc?: undefined): boolean
  write(buf: Buffer | string, enc?: BufferEncoding): boolean {
    if (typeof buf === 'string') {
      buf = Buffer.from(buf, enc)
    }

    if (this[_ended]) {
      this.emit('error', new Error('write() after end()'))
      return false
    }

    if (this[_fd] === undefined || this[_writing] || this[_queue].length) {
      this[_queue].push(buf)
      this[_needDrain] = true
      return false
    }

    this[_writing] = true
    this[_write](buf)
    return true
  }

  [_write](buf: Buffer) {
    fs.write(
      this[_fd] as number,
      buf,
      0,
      buf.length,
      this[_pos],
      (er, bw) => this[_onwrite](er, bw),
    )
  }

  [_onwrite](er?: null | NodeJS.ErrnoException, bw?: number) {
    if (er) {
      this[_onerror](er)
    } else {
      if (this[_pos] !== undefined && typeof bw === 'number') {
        this[_pos] += bw
      }
      if (this[_queue].length) {
        this[_flush]()
      } else {
        this[_writing] = false

        if (this[_ended] && !this[_finished]) {
          this[_finished] = true
          this[_close]()
          this.emit('finish')
        } else if (this[_needDrain]) {
          this[_needDrain] = false
          this.emit('drain')
        }
      }
    }
  }

  [_flush]() {
    if (this[_queue].length === 0) {
      if (this[_ended]) {
        this[_onwrite](null, 0)
      }
    } else if (this[_queue].length === 1) {
      this[_write](this[_queue].pop() as Buffer)
    } else {
      const iovec = this[_queue]
      this[_queue] = []
      writev(this[_fd] as number, iovec, this[_pos] as number, (er, bw) =>
        this[_onwrite](er, bw),
      )
    }
  }

  [_close]() {
    if (this[_autoClose] && typeof this[_fd] === 'number') {
      const fd = this[_fd]
      this[_fd] = undefined
      fs.close(fd, er =>
        er ? this.emit('error', er) : this.emit('close'),
      )
    }
  }
}

export class WriteStreamSync extends WriteStream {
  [_open](): void {
    let fd
    // only wrap in a try{} block if we know we'll retry, to avoid
    // the rethrow obscuring the error's source frame in most cases.
    if (this[_defaultFlag] && this[_flags] === 'r+') {
      try {
        fd = fs.openSync(this[_path], this[_flags], this[_mode])
      } catch (er) {
        if ((er as NodeJS.ErrnoException)?.code === 'ENOENT') {
          this[_flags] = 'w'
          return this[_open]()
        } else {
          throw er
        }
      }
    } else {
      fd = fs.openSync(this[_path], this[_flags], this[_mode])
    }

    this[_onopen](null, fd)
  }

  [_close]() {
    if (this[_autoClose] && typeof this[_fd] === 'number') {
      const fd = this[_fd]
      this[_fd] = undefined
      fs.closeSync(fd)
      this.emit('close')
    }
  }

  [_write](buf: Buffer) {
    // throw the original, but try to close if it fails
    let threw = true
    try {
      this[_onwrite](
        null,
        fs.writeSync(this[_fd] as number, buf, 0, buf.length, this[_pos]),
      )
      threw = false
    } finally {
      if (threw) {
        try {
          this[_close]()
        } catch {
          // ok error
        }
      }
    }
  }
}
const proc =
  typeof process === 'object' && process
