  | (TarOptionsWithAliases & { f: string })
export type TarOptionsWithAliasesSyncFile = TarOptionsWithAliasesSync &
  TarOptionsWithAliasesFile
export type TarOptionsWithAliasesAsyncFile = TarOptionsWithAliasesAsync &
  TarOptionsWithAliasesFile

