const getType = (stat: Stats): EntryTypeName | 'Unsupported' =>
  stat.isFile() ? 'File'
  : stat.isDirectory() ? 'Directory'
  : stat.isSymbolicLink() ? 'SymbolicLink'
  : 'Unsupported'
export const modeFix = (
  mode: number,
  isDir: boolean,
  portable: boolean,
) => {
  mode &= 0o7777

  // in portable mode, use the minimum reasonable umask
  // if this system creates files with 0o664 by default
  // (as some linux distros do), then we'll write the
  // archive with 0o644 instead.  Also, don't ever create
  // a file that is not readable/writable by the owner.
  if (portable) {
    mode = (mode | 0o600) & ~0o22
  }

  // if dirs are readable, then they should be listable
  if (isDir) {
    if (mode & 0o400) {
      mode |= 0o100
    }
    if (mode & 0o40) {
      mode |= 0o10
    }
    if (mode & 0o4) {
      mode |= 0o1
    }
  }
  return mode
}
// unix absolute paths are also absolute on win32, so we use this for both
import { win32 } from 'node:path'
const { isAbsolute, parse } = win32

// returns [root, stripped]
// Note that windows will think that //x/y/z/a has a "root" of //x/y, and in
// those cases, we want to sanitize it to x/y/z/a, not z/a, so we strip /
// explicitly if it's the first character.
// drive-specific relative paths on Windows get their root stripped off even
// though they are not absolute, so `c:../foo` becomes ['c:', '../foo']
export const stripAbsolutePath = (path: string): [string, string] => {
  let r = ''

  let parsed = parse(path)
  while (isAbsolute(path) || parsed.root) {
    // windows will think that //x/y/z has a "root" of //x/y/
    // but strip the //?/C:/ off of //?/C:/path
    const root =
      path.charAt(0) === '/' && path.slice(0, 4) !== '//?/' ?
        '/'
      : parsed.root
    path = path.slice(root.length)
    r += root
    parsed = parse(path)
  }
  return [r, path]
}
// When writing files on Windows, translate the characters to their
// 0xf000 higher-encoded versions.

const raw = ['|', '<', '>', '?', ':']

const win = raw.map(char =>
  String.fromCodePoint(0xf000 + Number(char.codePointAt(0))),
)

const toWin = new Map(raw.map((char, i) => [char, win[i]]))
const toRaw = new Map(win.map((char, i) => [char, raw[i]]))

export const encode = (s: string) =>
  raw.reduce((s, c) => s.split(c).join(toWin.get(c)), s)
export const decode = (s: string) =>
  win.reduce((s, c) => s.split(c).join(toRaw.get(c)), s)
export class Yallist<T = unknown> {
  tail?: Node<T>
  head?: Node<T>
  length: number = 0

  static create<T = unknown>(list: Iterable<T> = []) {
    return new Yallist(list)
  }

  constructor(list: Iterable<T> = []) {
    for (const item of list) {
      this.push(item)
    }
  }

  *[Symbol.iterator]() {
    for (let walker = this.head; walker; walker = walker.next) {
      yield walker.value
    }
  }

  removeNode(node: Node<T>) {
    if (node.list !== this) {
      throw new Error(
        'removing node which does not belong to this list',
      )
    }

    const next = node.next
    const prev = node.prev

    if (next) {
      next.prev = prev
    }

    if (prev) {
      prev.next = next
    }

    if (node === this.head) {
      this.head = next
    }
    if (node === this.tail) {
      this.tail = prev
    }

    this.length--
    node.next = undefined
    node.prev = undefined
    node.list = undefined

    return next
  }

  unshiftNode(node: Node<T>) {
    if (node === this.head) {
      return
    }

    if (node.list) {
      node.list.removeNode(node)
    }

    const head = this.head
    node.list = this
    node.next = head
    if (head) {
      head.prev = node
    }

    this.head = node
    if (!this.tail) {
      this.tail = node
    }
    this.length++
  }

  pushNode(node: Node<T>) {
    if (node === this.tail) {
      return
    }

    if (node.list) {
      node.list.removeNode(node)
    }

    const tail = this.tail
    node.list = this
    node.prev = tail
    if (tail) {
      tail.next = node
    }

    this.tail = node
    if (!this.head) {
      this.head = node
    }
    this.length++
  }

  push(...args: T[]) {
    for (let i = 0, l = args.length; i < l; i++) {
      push(this, args[i])
    }
    return this.length
  }

  unshift(...args: T[]) {
    for (var i = 0, l = args.length; i < l; i++) {
      unshift(this, args[i])
    }
    return this.length
  }

  pop() {
    if (!this.tail) {
      return undefined
    }

    const res = this.tail.value
    const t = this.tail
    this.tail = this.tail.prev
    if (this.tail) {
      this.tail.next = undefined
    } else {
      this.head = undefined
    }
    t.list = undefined
    this.length--
    return res
  }

  shift() {
    if (!this.head) {
      return undefined
    }

    const res = this.head.value
    const h = this.head
    this.head = this.head.next
    if (this.head) {
      this.head.prev = undefined
    } else {
      this.tail = undefined
    }
    h.list = undefined
    this.length--
    return res
  }

  forEach(
    fn: (value: T, i: number, list: Yallist<T>) => any,
    thisp?: any,
  ) {
    thisp = thisp || this
    for (let walker = this.head, i = 0; !!walker; i++) {
      fn.call(thisp, walker.value, i, this)
      walker = walker.next
    }
  }

  forEachReverse(
    fn: (value: T, i: number, list: Yallist<T>) => any,
    thisp?: any,
  ) {
    thisp = thisp || this
    for (let walker = this.tail, i = this.length - 1; !!walker; i--) {
      fn.call(thisp, walker.value, i, this)
      walker = walker.prev
    }
  }

  get(n: number) {
    let i = 0
    let walker = this.head
    for (; !!walker && i < n; i++) {
      walker = walker.next
    }
    if (i === n && !!walker) {
      return walker.value
    }
  }

  getReverse(n: number) {
    let i = 0
    let walker = this.tail
    for (; !!walker && i < n; i++) {
      // abort out of the list early if we hit a cycle
      walker = walker.prev
    }
    if (i === n && !!walker) {
      return walker.value
    }
  }

  map<R = any>(
    fn: (value: T, list: Yallist<T>) => R,
    thisp?: any,
  ): Yallist<R> {
    thisp = thisp || this
    const res = new Yallist<R>()
    for (let walker = this.head; !!walker; ) {
      res.push(fn.call(thisp, walker.value, this))
      walker = walker.next
