  mapReverse<R = any>(
    fn: (value: T, list: Yallist<T>) => R,
    thisp?: any,
  ): Yallist<R> {
    thisp = thisp || this
    var res = new Yallist<R>()
    for (let walker = this.tail; !!walker; ) {
      res.push(fn.call(thisp, walker.value, this))
      walker = walker.prev
    }
    return res
