  reduce(fn: (left: T, right: T, i: number) => T): T
  reduce<R = any>(
    fn: (acc: R, next: T, i: number) => R,
    initial: R,
  ): R
  reduce<R = any>(
    fn: (acc: R, next: T, i: number) => R,
    initial?: R,
  ): R {
    let acc: R | T
    let walker = this.head
