    }

    for (var i = 0; !!walker; i++) {
      acc = fn(acc as R, walker.value, i)
      walker = walker.next
    }

    return acc as R
  }

  reduceReverse(fn: (left: T, right: T, i: number) => T): T
  reduceReverse<R = any>(
    fn: (acc: R, next: T, i: number) => R,
    initial: R,
  ): R
  reduceReverse<R = any>(
    fn: (acc: R, next: T, i: number) => R,
    initial?: R,
  ): R {
    let acc: R | T
    let walker = this.tail
    if (arguments.length > 1) {
      acc = initial as R
    } else if (this.tail) {
      walker = this.tail.prev
      acc = this.tail.value
    } else {
      throw new TypeError(
        'Reduce of empty list with no initial value',
      )
    }

    for (let i = this.length - 1; !!walker; i--) {
      acc = fn(acc as R, walker.value, i)
      walker = walker.prev
    }

    return acc as R
  }

  toArray() {
    const arr = new Array(this.length)
    for (let i = 0, walker = this.head; !!walker; i++) {
      arr[i] = walker.value
      walker = walker.next
    }
    return arr
  }

  toArrayReverse() {
    const arr = new Array(this.length)
    for (let i = 0, walker = this.tail; !!walker; i++) {
      arr[i] = walker.value
      walker = walker.prev
    }
    return arr
  }

  slice(from: number = 0, to: number = this.length) {
    if (to < 0) {
      to += this.length
    }
    if (from < 0) {
      from += this.length
    }
    const ret = new Yallist()
    if (to < from || to < 0) {
      return ret
    }
    if (from < 0) {
      from = 0
    }
    if (to > this.length) {
      to = this.length
    }
    let walker = this.head
    let i = 0
    for (i = 0; !!walker && i < from; i++) {
      walker = walker.next
    }
    for (; !!walker && i < to; i++, walker = walker.next) {
      ret.push(walker.value)
    }
    return ret
  }

  sliceReverse(from: number = 0, to: number = this.length) {
    if (to < 0) {
      to += this.length
    }
    if (from < 0) {
      from += this.length
    }
    const ret = new Yallist()
    if (to < from || to < 0) {
      return ret
    }
    if (from < 0) {
      from = 0
    }
    if (to > this.length) {
      to = this.length
    }
    let i = this.length
    let walker = this.tail
    for (; !!walker && i > to; i--) {
      walker = walker.prev
    }
    for (; !!walker && i > from; i--, walker = walker.prev) {
      ret.push(walker.value)
    }
    return ret
  }

  splice(start: number, deleteCount: number = 0, ...nodes: T[]) {
    if (start > this.length) {
      start = this.length - 1
    }
    if (start < 0) {
      start = this.length + start
    }

    let walker = this.head

    for (let i = 0; !!walker && i < start; i++) {
      walker = walker.next
    }

    const ret: T[] = []
    for (let i = 0; !!walker && i < deleteCount; i++) {
      ret.push(walker.value)
      walker = this.removeNode(walker)
    }
    if (!walker) {
      walker = this.tail
    } else if (walker !== this.tail) {
      walker = walker.prev
