  reverse() {
    const head = this.head
    const tail = this.tail
    for (let walker = head; !!walker; walker = walker.prev) {
      const p = walker.prev
      walker.prev = walker.next
      walker.next = p
    }
    this.head = tail
    this.tail = head
    return this
