import { makeCommand } from './make-command.js'
import { type TarOptionsWithAliases } from './options.js'

import { replace as r } from './replace.js'

// just call tar.r with the filter and mtimeCache
export const update = makeCommand(
  r.syncFile,
  r.asyncFile,
  r.syncNoFile,
  r.asyncNoFile,
  (opt, entries = []) => {
    r.validate?.(opt, entries)
    mtimeFilter(opt)
  },
)

const mtimeFilter = (opt: TarOptionsWithAliases) => {
  const filter = opt.filter

  if (!opt.mtimeCache) {
    opt.mtimeCache = new Map()
  }

  opt.filter =
    filter ?
      (path, stat) =>
        filter(path, stat) &&
        !(
          /* c8 ignore start */
          (
            (opt.mtimeCache?.get(path) ?? stat.mtime ?? 0) >
            (stat.mtime ?? 0)
          )
          /* c8 ignore stop */
        )
    : (path, stat) =>
        !(
          /* c8 ignore start */
          (
            (opt.mtimeCache?.get(path) ?? stat.mtime ?? 0) >
            (stat.mtime ?? 0)
          )
          /* c8 ignore stop */
        )
}

"use strict";
/**
 * Load an OpenAPI 3.x document and extract the operations, security schemes
 * and documentation used for indexing and for the runtime request broker.
 *
 * External `$ref`s are resolved from the local filesystem only: HTTP
 * resolution is disabled so builds never contact remote hosts.
 *
 * @module prepare/spec
 */
import SwaggerParser from "@apidevtools/swagger-parser";
import { sample } from "openapi-sampler";

import { OagMcpError } from "../errors.js";
import type {
  ParameterInfo,
  SecurityRequirement,
  SecuritySchemeInfo,
  SpecOperation,
  SpecSummary,
} from "../types.js";

export const HTTP_METHODS = [
  "get",
  "put",
  "post",
  "delete",
  "options",
  "head",
  "patch",
  "trace",
] as const;

type Json = Record<string, unknown>;

/** Composite schema keywords and how their parts are joined. */
const COMPOSITES: ReadonlyArray<[string, string]> = [
  ["oneOf", " | "],
  ["anyOf", " | "],
  ["allOf", " & "],
];

/**
 * Convert a schema to a compact human description, e.g. "integer(int64)".
 *
 * @param {Object} schema - OpenAPI schema
 * @param {Number} [depth] - recursion depth
 * @return {String} description
 */
export function describeSchema(schema: unknown, depth = 0): string {
  if (!schema || typeof schema !== "object") {
    return "any";
  }
  const s = schema as Json;
  if (depth > 2) {
    return String(s.type ?? "object");
  }
  if (Array.isArray(s.enum)) {
    return s.enum.map((v) => JSON.stringify(v)).join(" | ");
  }
  return _describeTyped(s, depth) ?? _describeComposite(s, depth);
}

/**
 * Describe a schema by its `type` (and `format`), or undefined if it has none.
 *
 * @private
 */
function _describeTyped(s: Json, depth: number): string | undefined {
  const type = Array.isArray(s.type) ? s.type.join("|") : s.type;
  if (type === "array") {
    return `${describeSchema(s.items, depth + 1)}[]`;
  }
  if (!type) {
    return undefined;
  }
  return s.format ? `${type}(${s.format})` : String(type);
}

/**
 * Describe a schema without a `type`: its `oneOf`, `anyOf` or `allOf`
 * parts, or "object" when it has properties.
 *
 * @private
 */
function _describeComposite(s: Json, depth: number): string {
  for (const [keyword, joiner] of COMPOSITES) {
    if (Array.isArray(s[keyword])) {
      return (s[keyword] as unknown[])
        .map((x) => describeSchema(x, depth + 1))
        .join(joiner);
    }
  }
  return s.properties ? "object" : "any";
}

/**
 * Pick an example value for a schema, using openapi-sampler: the schema's
 * own `example`, `examples`, `default` or first `enum` value where present,
 * otherwise a value generated from its type and format (`oneOf`/`anyOf`,
 * `allOf` and recursive schemas included). Only required properties are
 * included, and `readOnly` properties are left out because the examples are
 * for requests.
 *
 * @param {Object} schema - dereferenced OpenAPI schema
 * @return {*} example value, or undefined when none can be produced
 */
export function exampleForSchema(schema: unknown): unknown {
  if (!schema || typeof schema !== "object") {
    return undefined;
  }
  try {
    return sample(schema as Parameters<typeof sample>[0], {
      skipReadOnly: true,
      skipNonRequired: true,
      quiet: true,
    });
  } catch {
    // An example is a convenience; never fail preparation over one.
    return undefined;
  }
}

/** Describes the parts of one security scheme type and whether it is supported. */
type SchemeDescriber = (info: SecuritySchemeInfo, scheme: Json) => void;

/** Security scheme types oag-mcp cannot satisfy, and why. */
const UNSUPPORTED_SCHEME_TYPES: Readonly<Record<string, string>> = {
  openIdConnect:
    "openIdConnect is not supported for upstream calls (interactive login is out of scope)",
  mutualTLS: "mutualTLS is not supported for upstream calls",
};

/** The describer of each supported security scheme type. */
const SCHEME_DESCRIBERS: Readonly<Record<string, SchemeDescriber>> = {
  apiKey: (info, scheme) => {
    info.in = scheme.in as SecuritySchemeInfo["in"];
    info.paramName = String(scheme.name ?? "");
    if (info.in === "header" || info.in === "query") {
      info.supported = true;
    } else {
      info.unsupportedReason = `apiKey in "${String(scheme.in)}" is not supported (header and query are)`;
    }
  },
  http: (info, scheme) => {
    info.scheme = String(scheme.scheme ?? "").toLowerCase();
    info.bearerFormat =
      typeof scheme.bearerFormat === "string" ? scheme.bearerFormat : undefined;
    if (info.scheme === "basic" || info.scheme === "bearer") {
      info.supported = true;
    } else {
      info.unsupportedReason = `HTTP "${info.scheme}" authentication is not supported (basic and bearer are)`;
    }
  },
  oauth2: (info, scheme) => {
    const flows = (scheme.flows ?? {}) as Json;
    const cc = flows.clientCredentials as Json | undefined;
    info.flows = Object.keys(flows);
    if (cc && typeof cc.tokenUrl === "string") {
      info.supported = true;
      info.tokenUrl = cc.tokenUrl;
      info.scopes = Object.keys((cc.scopes ?? {}) as Json);
    } else {
      info.unsupportedReason = `OAuth2 flows [${info.flows.join(", ")}] are not supported; only clientCredentials is (interactive login is out of scope)`;
    }
  },
};

/**
 * Describe a security scheme and whether oag-mcp supports it for upstream
 * calls.
 *
 * @param {String} name - scheme name
 * @param {Object} scheme - OpenAPI security scheme
 * @return {Object} scheme info
 */
export function describeSecurityScheme(
  name: string,
  scheme: Json,
): SecuritySchemeInfo {
  const type = String(scheme.type ?? "");
  const info: SecuritySchemeInfo = {
    name,
    type: type as SecuritySchemeInfo["type"],
    supported: false,
    description:
      typeof scheme.description === "string" ? scheme.description : undefined,
  };
  const describe = Object.hasOwn(SCHEME_DESCRIBERS, type)
    ? SCHEME_DESCRIBERS[type]
    : undefined;
  if (describe) {
    describe(info, scheme);
  } else {
    info.unsupportedReason = Object.hasOwn(UNSUPPORTED_SCHEME_TYPES, type)
      ? UNSUPPORTED_SCHEME_TYPES[type]
      : `Unknown security scheme type "${type}"`;
  }
  return info;
}

/**
 * Resolve the first server URL, substituting variable defaults.
 *
 * @param {Array} servers - OpenAPI servers
 * @return {String|undefined} URL
 * @private
 */
function _serverUrls(servers: unknown): string[] {
  if (!Array.isArray(servers)) {
    return [];
  }
  return servers
    .filter((s) => s && typeof s.url === "string")
    .map((s) => {
      let url = s.url as string;
      const vars = (s.variables ?? {}) as Record<string, { default?: string }>;
      for (const [k, v] of Object.entries(vars)) {
        url = url.split(`{${k}}`).join(String(v.default ?? ""));
      }
      return url.replace(/\/+$/, "");
    });
}

/**
 * Normalise a security requirement list.
 *
 * @param {Array} security - OpenAPI security requirement objects
 * @return {Array} requirements
 * @private
 */
function _security(security: unknown): SecurityRequirement[] | undefined {
  if (!Array.isArray(security)) {
    return undefined;
  }
  return security.map((req) => {
    const out: SecurityRequirement = {};
    for (const [k, v] of Object.entries((req ?? {}) as Json)) {
      out[k] = Array.isArray(v) ? v.map(String) : [];
    }
    return out;
  });
}

/**
 * A value if it is a string, otherwise undefined.
 *
 * @private
 */
function _str(v: unknown): string | undefined {
  return typeof v === "string" ? v : undefined;
}

/**
 * Parse and validate the document, resolving `$ref`s from local files only.
 *
 * @private
 */
async function _parse(specPath: string): Promise<Json> {
  try {
    return (await SwaggerParser.validate(specPath, {
      resolve: { http: false },
    })) as unknown as Json;
  } catch (err) {
    throw new OagMcpError(
      "SPEC_INVALID",
      `OpenAPI document ${specPath} could not be loaded: ${(err as Error).message}`,
      {
        hint: "Check the document is valid OpenAPI 3.0/3.1. Remote $ref URLs are not fetched; vendor them as local files.",
        cause: err,
      },
    );
  }
}

/**
 * The document's OpenAPI version, which must be 3.0.x or 3.1.x.
 *
 * @private
 */
function _version(api: Json): string {
  const version = String(api.openapi ?? api.swagger ?? "");
  if (!/^3\.[01]\./.test(version)) {
    throw new OagMcpError(
      "SPEC_VERSION_UNSUPPORTED",
      `OpenAPI version "${version}" is not supported`,
      {
        hint: "oag-mcp supports OpenAPI 3.0.x and 3.1.x documents. Convert Swagger 2.0 documents first (e.g. with swagger2openapi).",
      },
    );
  }
  return version;
}

/**
 * The document's security schemes, described.
 *
 * @private
 */
function _securitySchemes(api: Json): Record<string, SecuritySchemeInfo> {
  const components = (api.components ?? {}) as Json;
  const schemes: Record<string, SecuritySchemeInfo> = {};
  for (const [name, scheme] of Object.entries(
    (components.securitySchemes ?? {}) as Json,
  )) {
    schemes[name] = describeSecurityScheme(name, scheme as Json);
  }
  return schemes;
}

/**
 * An operation's parameters: the path item's, overridden by the
 * operation's own with the same location and name.
 *
 * @private
 */
function _parameters(shared: Json[], op: Json): ParameterInfo[] {
  const params = new Map<string, Json>();
  for (const prm of [...shared, ...((op.parameters as Json[]) ?? [])]) {
    params.set(`${prm.in}:${prm.name}`, prm);
  }
  return [...params.values()].map((prm) => {
    const schema = (prm.schema ?? {}) as Json;
    return {
      name: String(prm.name),
      in: String(prm.in) as ParameterInfo["in"],
      required: Boolean(prm.required),
      description: _str(prm.description),
      schemaType: describeSchema(schema),
      example:
        prm.example !== undefined ? prm.example : exampleForSchema(schema),
    };
  });
}

/**
 * An operation's request body, described by its first media type.
 *
 * @private
 */
function _requestBody(op: Json): SpecOperation["requestBody"] {
  if (!op.requestBody || typeof op.requestBody !== "object") {
    return undefined;
  }
  const rb = op.requestBody as Json;
  const content = (rb.content ?? {}) as Json;
  const contentTypes = Object.keys(content);
  const firstType = contentTypes[0];
  const media = (firstType ? content[firstType] : {}) as Json;
  return {
    required: Boolean(rb.required),
    contentTypes,
    description: _str(rb.description),
    schemaType: describeSchema(media.schema),
    example:
      media.example !== undefined
        ? media.example
        : exampleForSchema(media.schema),
  };
}

/**
 * An operation's response descriptions by status code.
 *
 * @private
 */
function _responses(op: Json): Record<string, string> {
  const responses: Record<string, string> = {};
  for (const [code, r] of Object.entries((op.responses ?? {}) as Json)) {
    responses[code] = _str((r as Json)?.description) ?? "";
  }
  return responses;
}

/**
 * Summarise one operation.
 *
 * @private
 */
function _operation(
  method: string,
  path: string,
  op: Json,
  shared: Json[],
  globalSecurity: SecurityRequirement[],
): SpecOperation {
  const explicit = _security(op.security);
  return {
    key: `${method.toUpperCase()} ${path}`,
    method: method.toUpperCase(),
    path,
    operationId: _str(op.operationId),
    tags: Array.isArray(op.tags) ? op.tags.map(String) : [],
    summary: _str(op.summary),
    description: _str(op.description),
    deprecated: Boolean(op.deprecated),
    parameters: _parameters(shared, op),
    requestBody: _requestBody(op),
    responses: _responses(op),
    security: explicit ?? globalSecurity,
    securityIsOverride: explicit !== undefined,
  };
}

/**
 * Every operation of every path, in document order.
 *
 * @private
 */
function _operations(
  api: Json,
  globalSecurity: SecurityRequirement[],
): SpecOperation[] {
  const operations: SpecOperation[] = [];
  for (const [path, item] of Object.entries((api.paths ?? {}) as Json)) {
    const pathItem = (item ?? {}) as Json;
    const shared = Array.isArray(pathItem.parameters)
      ? (pathItem.parameters as Json[])
      : [];
    for (const method of HTTP_METHODS) {
      const op = pathItem[method] as Json | undefined;
      if (op) {
        operations.push(_operation(method, path, op, shared, globalSecurity));
      }
    }
  }
  return operations;
}

/**
 * The document's tags.
 *
 * @private
 */
function _tags(api: Json): SpecSummary["tags"] {
  if (!Array.isArray(api.tags)) {
    return [];
  }
  return (api.tags as Json[]).map((t) => ({
    name: String(t.name),
    description: _str(t.description),
  }));
}

/**
 * Load, validate and summarise an OpenAPI document.
 *
 * @param {String} specPath - path to the OpenAPI YAML/JSON document
 * @return {Promise} spec summary
 */
export async function loadSpec(specPath: string): Promise<SpecSummary> {
  const api = await _parse(specPath);
  const version = _version(api);
  const info = (api.info ?? {}) as Json;
  const globalSecurity = _security(api.security) ?? [];
  return {
    openapiVersion: version,
    title: String(info.title ?? "API"),
    apiVersion: String(info.version ?? ""),
    description: _str(info.description),
    servers: _serverUrls(api.servers),
    tags: _tags(api),
    securitySchemes: _securitySchemes(api),
    globalSecurity,
    operations: _operations(api, globalSecurity),
  };
}

"use strict";
/**
 * The private preparation workspace: a temporary directory owned by one
 * oag-mcp process that holds the prepared SDK bundle, declarations and the
 * sandbox runner for the lifetime of the server. Users never manage it: it
 * is removed on shutdown and on start-up failure, and stale workspaces of
 * processes that have died are swept on start-up.
 *
 * @module prepare/workspace
 */
import fs from "node:fs";
import os from "node:os";
import path from "node:path";

import type { Logs } from "../logging/logger.js";
import type { MethodRecord } from "../types.js";

/** Prefix of workspace directory names under the temporary directory. */
export const WORKSPACE_PREFIX = "oag-mcp-ws-";

/** Owner marker written into every workspace. */
const OWNER_FILE = ".oag-mcp-owner.json";

/** Relative paths inside a workspace. */
export const WORKSPACE_PATHS = {
  bundle: "sdk/sdk.bundle.js",
  types: "sdk/types",
  binding: "sdk/sdk-binding.d.ts",
  tsLib: "sdk/ts-lib",
  runner: "executor/runner.js",
  /** Extracted SDK archives. */
  input: "input",
  /** Generated entry shims for CommonJS SDKs. */
  shim: "shim",
} as const;

/** Workspaces of this process not yet removed (for the exit safety net). */
const LIVE = new Set<string>();
let exitHookInstalled = false;

/**
 * Last-resort synchronous removal when the process exits without a graceful
 * shutdown; anything left is swept by the next start-up.
 *
 * @private
 */
function _onExit(): void {
  for (const dir of LIVE) {
    try {
      fs.rmSync(dir, { recursive: true, force: true });
    } catch {
      // Swept by the next start-up.
    }
  }
  LIVE.clear();
}

/** A private workspace directory. */
export interface Workspace {
  dir: string;
  /** Remove the workspace; never throws. Returns whether it succeeded. */
  cleanup(): boolean;
}

/**
 * Whether a process exists.
 *
 * @private
 */
function _alive(pid: number): boolean {
  try {
    process.kill(pid, 0);
    return true;
  } catch (err) {
    return (err as NodeJS.ErrnoException).code === "EPERM";
  }
}

/**
 * Remove workspaces left behind by oag-mcp processes on this host that no
 * longer exist (e.g. killed with SIGKILL). Only directories carrying an
 * owner marker for a dead process are removed.
 *
 * @param {String} root - parent directory of workspaces
 * @param {Object} logs - logs
 * @return {Number} number of workspaces removed
 */
export function sweepStaleWorkspaces(root: string, logs: Logs): number {
  let removed = 0;
  let entries: string[];
  try {
    entries = fs.readdirSync(root);
  } catch {
    return 0;
  }
  for (const name of entries) {
    if (!name.startsWith(WORKSPACE_PREFIX)) {
      continue;
    }
    const dir = path.join(root, name);
    try {
      const owner = JSON.parse(
        fs.readFileSync(path.join(dir, OWNER_FILE), "utf8"),
      ) as { pid?: number; hostname?: string };
      if (
        typeof owner.pid !== "number" ||
        owner.hostname !== os.hostname() ||
        _alive(owner.pid)
      ) {
        continue;
      }
      fs.rmSync(dir, { recursive: true, force: true });
      removed++;
    } catch {
      // Not ours, unreadable or concurrently removed: leave it alone.
    }
  }
  if (removed > 0) {
    logs.op("info", "prepare.workspace.stale_removed", { count: removed });
  }
  return removed;
}

/**
 * Create a private workspace (mode 0700) under `root`.
 *
 * @param {Object} opts - options
 * @param {String} [opts.root] - parent directory, default: OS temp directory
 * @param {Object} opts.logs - logs
 * @return {Object} workspace
 */
export function createWorkspace(opts: {
  root?: string;
  logs: Logs;
}): Workspace {
  const root = path.resolve(opts.root ?? os.tmpdir());
  fs.mkdirSync(root, { recursive: true });
  sweepStaleWorkspaces(root, opts.logs);
  const dir = fs.mkdtempSync(path.join(root, WORKSPACE_PREFIX));
  fs.chmodSync(dir, 0o700);
  fs.writeFileSync(
    path.join(dir, OWNER_FILE),
    JSON.stringify({ pid: process.pid, hostname: os.hostname() }),
  );
  LIVE.add(dir);
  if (!exitHookInstalled) {
    process.once("exit", _onExit);
    exitHookInstalled = true;
  }
  let removed = false;
  const cleanup = (): boolean => {
    if (removed) {
      return true;
    }
    try {
      fs.rmSync(dir, { recursive: true, force: true, maxRetries: 3 });
      removed = true;
      LIVE.delete(dir);
      opts.logs.op("debug", "prepare.workspace.removed", {
        outcome: "success",
      });
      return true;
    } catch (err) {
      opts.logs.op("warn", "prepare.workspace.cleanup_failed", {
        error: (err as NodeJS.ErrnoException).code ?? (err as Error).name,
        outcome: "failure",
      });
      return false;
    }
  };
  return { dir, cleanup };
}

/**
 * Generate the TypeScript declaration of the `sdk` binding.
 *
 * @param {Array} records - method records
 * @return {String} declaration source
 */
export function bindingDeclaration(records: MethodRecord[]): string {
  const byClass = new Map<string, string[]>();
  for (const r of records) {
    byClass.set(r.className, [
      ...(byClass.get(r.className) ?? []),
      r.methodName,
    ]);
  }
  const lines = [
    "// Generated by oag-mcp. Declares the `sdk` binding available to execute code.",
    'import type * as __sdk from "./types/index";',
    "",
    "declare global {",
    "  /**",
    "   * SDK binding provided by oag-mcp: `sdk.<ApiClass>.<method>(...)` calls the",
    "   * generated typescript-fetch SDK. Base URL and credentials are configured",
    "   * by the server; do not pass them.",
    "   */",
    "  const sdk: {",
  ];
  for (const [cls, methods] of [...byClass.entries()].sort(([a], [b]) =>
    a.localeCompare(b),
  )) {
    const names = methods
      .sort()
      .map((m) => JSON.stringify(m))
      .join(" | ");
    lines.push(`    readonly ${cls}: Pick<__sdk.${cls}, ${names}>;`);
  }
  lines.push("  };", "}", "", "export {};", "");
  return lines.join("\n");
}

"use strict";
/**
 * MCP server definition: exactly two tools, `search` and `execute`, with the
 * same behaviour on every transport.
 *
 * @module server/tools
 */
import crypto from "node:crypto";

import { McpServer } from "@modelcontextprotocol/server";
import * as z from "zod";

import type { Principal } from "../types.js";
import { oagMcpVersion } from "../util/version.js";
import type { ClientEndpoint, OagMcpService } from "./service.js";

/** The only tools oag-mcp exposes. */
export const TOOL_NAMES = ["search", "execute"] as const;

/** Tool descriptions computed once per service (process). */
const DESCRIPTIONS = new WeakMap<
  OagMcpService,
  { search: string; execute: string }
>();

/**
 * Tool descriptions for a service, computed once.
 *
 * @private
 */
function _descriptions(service: OagMcpService): {
  search: string;
  execute: string;
} {
  let d = DESCRIPTIONS.get(service);
  if (!d) {
    d = {
      search: searchDescription(service),
      execute: executeDescription(service),
    };
    DESCRIPTIONS.set(service, d);
  }
  return d;
}

/**
 * Build the description of the execute tool.
 *
 * @param {Object} service - service
 * @return {String} description
 */
export function executeDescription(service: OagMcpService): string {
  const apis = service.apiClasses().join(", ");
  return [
    `Run JavaScript or TypeScript that calls the ${service.info.api.title} API through its generated SDK.`,
    "Write the BODY of an async function: use `await`, combine several calls, loop, filter and aggregate, then `return` a JSON-serialisable result (keep it small).",
    `A global \`sdk\` binding exposes the SDK API classes: ${apis}. Call methods as \`sdk.<ApiClass>.<method>(...)\` exactly as shown by the search tool; the base URL and credentials are configured by the server.`,
    "No imports, network, filesystem, environment or subprocess access. `console.log` output is captured (bounded). TypeScript is type-checked against the SDK before running.",
    "Example:\n```ts\nconst items = await sdk.PetsApi.listPets({ limit: 50 });\nreturn items.filter((p) => p.vaccinated).map((p) => p.name);\n```",
    "Errors are structured: syntax_error, type_error (with diagnostics), api_error (HTTP status and body), permission_denied, timeout, output_limit, resource_limit.",
  ].join("\n\n");
}

/**
 * Build the description of the search tool.
 *
 * @param {Object} service - service
 * @return {String} description
 */
export function searchDescription(service: OagMcpService): string {
  return [
    `Discover methods of the ${service.info.api.title} SDK available to the execute tool.`,
    '- `{ query }`: ranked full-text search (e.g. "list pets by species"); returns ids, signatures and summaries.',
    "- `{ id }`: full details for one method: signature, input/return types, referenced type declarations, auth and an example.",
    "- `{}` or `{ tag }`: browse API classes and their methods when you do not know the vocabulary yet.",
  ].join("\n");
}

/**
 * Format a tool result with text and structured content.
 *
 * @private
 */
function _result(payload: Record<string, unknown>, isError = false) {
  return {
    content: [
      { type: "text" as const, text: JSON.stringify(payload, null, 2) },
    ],
    structuredContent: payload,
    isError,
  };
}

/**
 * Create an MCP server instance bound to one principal.
 *
 * @param {Object} service - service
 * @param {Object} principal - authenticated principal
 * @param {String} transport - transport name
 * @param {String} [httpRequestId] - correlation id of the HTTP request
 * @param {Object} [client] - address and port of the HTTP client
 * @return {McpServer} server
 */
export function createMcpServer(
  service: OagMcpService,
  principal: Principal,
  transport: "stdio" | "streamable-http",
  httpRequestId?: string,
  client: ClientEndpoint = {},
): McpServer {
  const server = new McpServer(
    {
      name: "oag-mcp",
      version: oagMcpVersion(),
      title: `${service.info.api.title} (oag-mcp)`,
    },
    {
      capabilities: { tools: {} },
      instructions:
        "Use `search` to find SDK methods (start with no arguments to browse), then `execute` TypeScript that calls them via the `sdk` binding. Return only the data you need.",
    },
  );
  const requestId = () => httpRequestId ?? `req_${crypto.randomUUID()}`;
  server.registerTool(
    "search",
    {
      title: "Search SDK methods",
      description: _descriptions(service).search,
      inputSchema: z.object({
        query: z
          .string()
          .max(500)
          .optional()
          .describe("Keywords describing what you want to do"),
        id: z
          .string()
          .max(200)
          .optional()
          .describe(
            "Exact method id from a previous result, e.g. 'PetsApi.listPets'",
          ),
        tag: z
          .string()
          .max(200)
          .optional()
          .describe("Restrict to an API class or OpenAPI tag"),
        limit: z
          .number()
          .int()
          .min(1)
          .max(20)
          .optional()
          .describe("Maximum results (default 5)"),
      }),
      annotations: {
        readOnlyHint: true,
        idempotentHint: true,
        openWorldHint: false,
      },
    },
    async (args, extra) => {
      const out = service.search(args, {
        principal,
        requestId: requestId(),
        transport,
        ...client,
        mcpSessionId: extra.sessionId,
        jsonrpcRequestId: extra.mcpReq.id,
      });
      return _result(out, Boolean(out.error));
    },
  );
  server.registerTool(
    "execute",
    {
      title: "Execute SDK code",
      description: _descriptions(service).execute,
      inputSchema: z.object({
        code: z
          .string()
          .min(1)
          .max(200000)
          .describe("Body of an async function using the `sdk` binding"),
        language: z
          .enum(["typescript", "javascript"])
          .optional()
          .describe("Default: typescript (type-checked)"),
        timeoutMs: z
          .number()
          .int()
          .min(100)
          .max(600000)
          .optional()
          .describe("Wall-clock limit for this execution"),
      }),
      annotations: {
        readOnlyHint: false,
        destructiveHint: true,
        openWorldHint: true,
      },
    },
    async (args, extra) => {
      const out = await service.execute(args, {
        principal,
        requestId: requestId(),
        transport,
        ...client,
        mcpSessionId: extra.sessionId,
        jsonrpcRequestId: extra.mcpReq.id,
      });
      return _result(out as unknown as Record<string, unknown>, !out.ok);
    },
  );
  return server;
}

"use strict";
/**
 * The oag-mcp service: assembles the trusted bridge (credentials, policy,
 * request broker) and the isolated executor around an SDK prepared at
 * start-up, and implements the behaviour of the two MCP tools independent
 * of transport.
 *
 * @module server/service
 */
import crypto from "node:crypto";
import path from "node:path";

import { AuthorizationPolicy } from "./authorization.js";
import type { Config } from "../config.js";
import { SecretResolver } from "../util/secrets.js";
import { OagMcpError } from "../errors.js";
import { prepareCode } from "../executor/code-policy.js";
import { DenoExecutor, resolveDeno } from "../executor/deno-executor.js";
import { AgentTypeChecker } from "../executor/typecheck.js";
import type {
  ExecutionError,
  ExecutionOutcome,
  Executor,
  LogEntry,
} from "../executor/types.js";
import type { Logs } from "../logging/logger.js";
import { boundValue, secrets } from "../util/redact.js";
import type { PreparedSdk } from "../prepare/prepare.js";
import { WORKSPACE_PATHS } from "../prepare/workspace.js";
import { type MethodSearchIndex, authLine } from "../search/search-index.js";
import type {
  MethodRecord,
  OperationBinding,
  PreparedSdkInfo,
  Principal,
} from "../types.js";
import { RequestBroker } from "../upstream/broker.js";
import { ServiceIdentityCredentialProvider } from "../upstream/credentials.js";
import { Semaphore } from "../util/semaphore.js";

/** Context of one tool invocation. */
export interface CallContext extends ClientEndpoint {
  principal: Principal;
  requestId: string;
  transport: "stdio" | "streamable-http";
  /** MCP session of a Streamable HTTP call. */
  mcpSessionId?: string;
  /** JSON-RPC id of the tool call request. */
  jsonrpcRequestId?: string | number;
}

/** Address and port of a Streamable HTTP client. */
export interface ClientEndpoint {
  clientAddress?: string;
  clientPort?: number;
}

/**
 * Context fields for the records of one tool call.
 *
 * @private
 */
function _callContext(
  ctx: CallContext,
  toolName: "search" | "execute",
): Record<string, unknown> {
  return {
    requestId: ctx.requestId,
    transport: ctx.transport,
    principalId: ctx.principal.id,
    clientAddress: ctx.clientAddress,
    clientPort: ctx.clientPort,
    mcpSessionId: ctx.mcpSessionId,
    jsonrpcRequestId: ctx.jsonrpcRequestId,
    toolName,
  };
}

/** Input of the search tool. */
export interface SearchInput {
  query?: string;
  id?: string;
  tag?: string;
  limit?: number;
}

/** Input of the execute tool. */
export interface ExecuteInput {
  code: string;
  language?: "typescript" | "javascript";
  timeoutMs?: number;
}

/** Output of the execute tool. */
export interface ExecuteOutput {
  ok: boolean;
  executionId: string;
  result?: unknown;
  logs: LogEntry[];
  logsTruncated: boolean;
  error?: ExecutionError;
  hint?: string;
  stats: { durationMs: number; sdkCalls: number };
}

const MAX_SEARCH_OUTPUT = 24000;

/** One execute call as it moves through its stages. */
interface Run {
  started: number;
  executionId: string;
  language: "typescript" | "javascript";
  ctx: CallContext;
  /** Logs carrying the call's context. */
  logs: Logs;
}

/** A call refused before the code runs. */
interface Refused {
  error: ExecutionError;
  hint?: string;
}

/** Code that passed the checks, as the module the sandbox runs. */
interface Checked {
  moduleBase64: string;
}

/**
 * Whether a stage refused the call.
 *
 * @private
 */
function _refused<T extends object>(value: T | Refused): value is Refused {
  return !("ok" in value) && !("moduleBase64" in value);
}

/**
 * Trim long text.
 *
 * @private
 */
function _clip(s: string | undefined, n: number): string | undefined {
  if (!s) {
    return s;
  }
  return s.length > n ? `${s.slice(0, n)}…` : s;
}

/**
 * The upstream API's base URL: configured, or the spec's first server. It
 * must be absolute http(s).
 *
 * @private
 */
function _upstreamBase(config: Config, info: PreparedSdkInfo): URL {
  const baseUrl = config.upstream.baseUrl ?? info.api.servers[0];
  try {
    const base = new URL(baseUrl ?? "");
    if (base.protocol === "http:" || base.protocol === "https:") {
      return base;
    }
  } catch {
    // Not a URL; reported below.
  }
  throw new OagMcpError(
    "CONFIG_BASE_URL_REQUIRED",
    `No absolute upstream base URL is available (spec servers: ${info.api.servers.join(", ") || "none"})`,
    { hint: "Set upstream.baseUrl in the configuration file." },
  );
}

/**
 * Audit the authorization policy in force.
 *
 * @private
 */
function _auditPolicy(
  logs: Logs,
  config: Config,
  policy: AuthorizationPolicy,
): void {
  logs.audit("authorization.policy_loaded", "success", {
    policyMode: policy.implicit ? "implicit-allow-all" : "configured",
    rules: config.authorization?.rules.length ?? 0,
    default: config.authorization?.default ?? "allow",
  });
}

/**
 * Audit the network and sandbox limits in force.
 *
 * @private
 */
function _auditExecutionPolicy(logs: Logs, config: Config, base: URL): void {
  logs.audit("execution.policy.applied", "success", {
    upstreamOrigin: base.origin,
    extraRedirectOrigins: config.upstream.allowedOrigins.length,
    followRedirects: config.upstream.followRedirects,
    timeoutMs: config.execution.timeoutMs,
    memoryMb: config.execution.memoryMb,
    maxConcurrent: config.execution.maxConcurrent,
    sandbox: "deno-no-permissions",
  });
}

/**
 * A Deno executor, verified by loading the SDK bundle with every binding.
 *
 * @private
 */
async function _verifiedDenoExecutor(
  workspaceDir: string,
  info: PreparedSdkInfo,
  broker: RequestBroker,
  config: Config,
  logs: Logs,
): Promise<DenoExecutor> {
  const deno = resolveDeno(config.execution.denoPath);
  logs.op("info", "executor.runtime.resolved", {
    executor: "deno-subprocess",
    denoVersion: deno.version,
    source: deno.source,
  });
  const executor = new DenoExecutor({ workspaceDir, deno, logs });
  await executor.verify(info.operations, broker.sdkBasePath);
  logs.op("info", "executor.verified", {
    executor: "deno-subprocess",
    bindings: info.operations.length,
    outcome: "success",
  });
  return executor;
}

/**
 * Keep search output within its size limit: drop detail from a large method
 * description first, then replace anything still too large with a preview.
 *
 * @private
 */
function _boundSearchOutput(
  out: Record<string, unknown>,
): Record<string, unknown> {
  let text = JSON.stringify(out);
  if (text.length > MAX_SEARCH_OUTPUT && out.method) {
    const m = out.method as Record<string, unknown>;
    m.referencedTypes = (m.referencedTypes as string[]).slice(0, 3);
    m.apiParameters = undefined;
    text = JSON.stringify(out);
  }
  if (text.length <= MAX_SEARCH_OUTPUT) {
    return out;
  }
  return {
    truncated: true,
    note: "Result too large; narrow the query.",
    preview: text.slice(0, MAX_SEARCH_OUTPUT - 200),
  };
}

/**
 * Prepared SDK plus runtime components, shared by every session of one
 * server process.
 */
/**
 * A hint for the agent about an execution's outcome, when there is one.
 *
 * @private
 */
function _outcomeHint(outcome: ExecutionOutcome): string | undefined {
  if (outcome.ok && outcome.resultUndefined) {
    return "The code returned no value; use `return` to send results back.";
  }
  if (outcome.error?.thrownIn) {
    return `The error was thrown inside the SDK (${outcome.error.thrownIn}), not in your code. The API's response may not match the OpenAPI document the SDK was generated from.`;
  }
  return undefined;
}

export class OagMcpService {
  readonly info: PreparedSdkInfo;
  readonly index: MethodSearchIndex;
  readonly policy: AuthorizationPolicy;
  readonly broker: RequestBroker;
  readonly executor: Executor;
  private readonly bindings: Map<string, OperationBinding>;
  private readonly checker?: AgentTypeChecker;
  private readonly semaphore: Semaphore;

  /**
   * @param {Object} parts - assembled components (use {@link OagMcpService.create})
   */
  private constructor(
    readonly workspaceDir: string,
    readonly config: Config,
    readonly logs: Logs,
    parts: {
      info: PreparedSdkInfo;
      index: MethodSearchIndex;
      policy: AuthorizationPolicy;
      broker: RequestBroker;
      executor: Executor;
      checker?: AgentTypeChecker;
    },
  ) {
    this.info = parts.info;
    this.index = parts.index;
    this.policy = parts.policy;
    this.broker = parts.broker;
    this.executor = parts.executor;
    this.checker = parts.checker;
    this.bindings = new Map(parts.info.operations.map((o) => [o.id, o]));
    this.semaphore = new Semaphore(
      config.execution.maxConcurrent,
      config.execution.maxQueue,
    );
  }

  /**
   * Assemble the runtime around a prepared SDK: credential provider,
   * authorization policy, request broker, Deno executor (verified by
   * loading the bundle with every binding) and the type checker.
   *
   * @param {Object} opts - options
   * @return {Promise} service
   */
  static async create(opts: {
    prepared: PreparedSdk;
    config: Config;
    configBaseDir: string;
    logs: Logs;
    executor?: Executor;
    fetchImpl?: typeof fetch;
  }): Promise<OagMcpService> {
    const { config, logs, prepared } = opts;
    const dir = prepared.workspaceDir;
    const info = prepared.info;
    const base = _upstreamBase(config, info);
    const provider = new ServiceIdentityCredentialProvider({
      schemes: config.upstreamAuth.schemes,
      schemeInfo: info.securitySchemes,
      resolver: new SecretResolver({
        secretsFile: config.upstreamAuth.secretsFile,
        baseDir: opts.configBaseDir,
      }),
      registry: secrets,
      logs,
      allowInsecureTokenUrl: config.upstreamAuth.allowInsecureTokenUrl,
      baseUrl: base.toString(),
      fetchImpl: opts.fetchImpl,
    });
    const policy = new AuthorizationPolicy(config.authorization);
    _auditPolicy(logs, config, policy);
    const broker = new RequestBroker({
      operations: info.operations,
      schemes: info.securitySchemes,
      provider,
      policy,
      network: { baseUrl: base.toString(), ...config.upstream },
      fetchImpl: opts.fetchImpl,
    });
    _auditExecutionPolicy(logs, config, base);
    const executor =
      opts.executor ??
      (await _verifiedDenoExecutor(dir, info, broker, config, logs));
    const checker = config.execution.typecheck
      ? new AgentTypeChecker(
          path.join(dir, "sdk"),
          path.join(dir, WORKSPACE_PATHS.tsLib),
        )
      : undefined;
    return new OagMcpService(dir, config, logs, {
      info,
      index: prepared.index,
      policy,
      broker,
      executor,
      checker,
    });
  }

  /** Warm caches (type checker) in the background. */
  warmUp(): void {
    setImmediate(() => {
      const started = Date.now();
      try {
        this.checker?.warmUp();
        this.logs.op("debug", "typecheck.warmed", {
          durationMs: Date.now() - started,
        });
      } catch (err) {
        this.logs.op("warn", "typecheck.warm_failed", {
          error: (err as Error).name,
        });
      }
    });
  }

  /**
   * Whether a record is visible to a principal.
   *
   * @private
   */
  private _visible(p: Principal): (r: MethodRecord) => boolean {
    return (r) => {
      const b = this.bindings.get(r.id);
      return Boolean(b) && this.policy.decide(p, b!).allowed;
    };
  }

  /**
   * Names of API classes visible to a principal (for tool descriptions).
   *
   * @return {Array} class names
   */
  apiClasses(): string[] {
    return [...new Set(this.info.operations.map((o) => o.className))].sort();
  }

  /**
   * Full description of one method record.
   *
   * @private
   */
  private _detail(r: MethodRecord): Record<string, unknown> {
    return {
      id: r.id,
      sdkPath: r.sdkPath,
      operationId: r.operationId,
      httpMethod: r.httpMethod,
      path: r.path,
      tags: r.tags,
      summary: r.summary,
      description: _clip(r.description, 1500),
      deprecated: r.deprecated || undefined,
      signature: r.signature,
      requiredArguments: r.requiredArguments,
      parameters: r.parameters,
      inputType: r.inputType?.declaration,
      returnType: r.returnType,
      referencedTypes: r.referencedTypes.map((t) => t.declaration),
      apiParameters: r.apiParameters.map((p) => ({
        name: p.name,
        in: p.in,
        required: p.required,
        type: p.schemaType,
        description: _clip(p.description, 300),
      })),
      requestBody: r.requestBody
        ? {
            required: r.requestBody.required,
            contentTypes: r.requestBody.contentTypes,
            type: r.requestBody.schemaType,
          }
        : undefined,
      responses: r.responses,
      auth: authLine(r),
      example: r.example,
    };
  }

  /**
   * Run the search tool: describe one method by id, search by query, or
   * browse the APIs, showing only methods the caller may call.
   *
   * @param {Object} input - search input
   * @param {Object} ctx - call context
   * @return {Object} search output
   */
  search(input: SearchInput, ctx: CallContext): Record<string, unknown> {
    const started = Date.now();
    const logs = this.logs.child(_callContext(ctx, "search"));
    const visible = this._visible(ctx.principal);
    const [mode, found] = input.id
      ? ["detail", this._searchDetail(input.id, visible)]
      : input.query?.trim()
        ? ["query", this._searchQuery(input, visible)]
        : ["browse", this._browse(input, visible)];
    const out = _boundSearchOutput(found);
    logs.op("info", "search.completed", {
      mode,
      results: Array.isArray(out.results) ? out.results.length : undefined,
      durationMs: Date.now() - started,
      outcome: "success",
    });
    return out;
  }

  /**
   * One method in full, if the caller may see it.
   *
   * @private
   */
  private _searchDetail(
    id: string,
    visible: (r: MethodRecord) => boolean,
  ): Record<string, unknown> {
    const r = this.index.get(id);
    return r && visible(r)
      ? { method: this._detail(r) }
      : {
          error: `No method with id "${id}" is available. Use search with a query to find ids.`,
        };
  }

  /**
   * The methods matching a query.
   *
   * @private
   */
  private _searchQuery(
    input: SearchInput,
    visible: (r: MethodRecord) => boolean,
  ): Record<string, unknown> {
    const { hits, total } = this.index.search(input.query!.slice(0, 500), {
      visible,
      limit: Math.min(Math.max(input.limit ?? 5, 1), 20),
      tag: input.tag,
    });
    return {
      results: hits,
      total,
      hint:
        hits.length === 0
          ? "No matches. Call search without a query to browse available APIs."
          : "Call search with { id } for full types and an example, then use execute.",
    };
  }

  /**
   * An overview of the APIs and their methods.
   *
   * @private
   */
  private _browse(
    input: SearchInput,
    visible: (r: MethodRecord) => boolean,
  ): Record<string, unknown> {
    return {
      api: { title: this.info.api.title, version: this.info.api.version },
      apis: this.index.browse({ visible, perClass: 8, tag: input.tag }),
      hint: "Use search with a query or { tag: <ApiClass or tag> } to list methods; { id } for details.",
    };
  }

  /**
   * Run the execute tool: admit the call, check the code, run it in the
   * sandbox, then audit and report the outcome.
   *
   * @param {Object} input - execute input
   * @param {Object} ctx - call context
   * @return {Promise} execute output
   */
  async execute(input: ExecuteInput, ctx: CallContext): Promise<ExecuteOutput> {
    const executionId = `exec_${crypto.randomUUID()}`;
    const run: Run = {
      started: Date.now(),
      executionId,
      language: input.language ?? "typescript",
      ctx,
      logs: this.logs.child({ ..._callContext(ctx, "execute"), executionId }),
    };
    const checked = this._admit(input, run) ?? this._check(input, run);
    if (_refused(checked)) {
      return this._fail(run, checked.error, checked.hint);
    }
    const outcome = await this._run(input, run, checked.moduleBase64);
    if (_refused(outcome)) {
      return this._fail(run, outcome.error);
    }
    this._auditOutcome(run, outcome);
    return this._output(run, outcome);
  }

  /**
   * Refuse the call while required auditing is unavailable; otherwise
   * record the execution request.
   *
   * @private
   */
  private _admit(input: ExecuteInput, run: Run): Refused | undefined {
    const unavailable: Refused = {
      error: {
        type: "audit_unavailable",
        message:
          "Execution is disabled because required security auditing is unavailable",
      },
    };
    if (this.logs.auditBlocksExecution()) {
      return unavailable;
    }
    const recorded = run.logs.audit("execution.requested", "accepted", {
      language: run.language,
      codeBytes: Buffer.byteLength(input.code ?? ""),
    });
    if (!recorded && this.logs.failClosed) {
      return unavailable;
    }
    run.logs.op("info", "execution.started", { language: run.language });
    return undefined;
  }

  /**
   * Check the code against the code policy and, for TypeScript, the type
   * checker.
   *
   * @private
   */
  private _check(input: ExecuteInput, run: Run): Refused | Checked {
    const maxCodeBytes = this.config.execution.maxCodeBytes;
    const prepared = prepareCode(input.code ?? "", run.language, maxCodeBytes);
    if (!prepared.ok) {
      this._auditCodePolicy(run, prepared);
      return { error: prepared.error };
    }
    const diagnostics =
      run.language === "typescript"
        ? (this.checker?.check(input.code) ?? [])
        : [];
    if (diagnostics.length > 0) {
      return {
        error: {
          type: "type_error",
          message: `Code has ${diagnostics.length} type error(s): ${diagnostics[0].message} (line ${diagnostics[0].line})`,
          diagnostics,
        },
        hint: "Check method names, argument shapes and return types with search { id }.",
      };
    }
    return { moduleBase64: prepared.moduleBase64 };
  }

  /**
   * Audit code the code policy refused: imports, or code over the size
   * limit.
   *
   * @private
   */
  private _auditCodePolicy(
    run: Run,
    refused: Extract<ReturnType<typeof prepareCode>, { ok: false }>,
  ): void {
    if (refused.error.reason === "import_not_allowed") {
      run.logs.audit(
        "execution.import_denied",
        "denied",
        { violations: refused.violations?.length ?? 1 },
        "warn",
      );
    }
    if (refused.error.type === "resource_limit") {
      run.logs.audit(
        "execution.resource_limit",
        "denied",
        { limit: "maxCodeBytes", value: this.config.execution.maxCodeBytes },
        "warn",
      );
    }
  }

  /**
   * Run the code in the sandbox once a slot is free, with its SDK requests
   * going through the request broker for the caller.
   *
   * @private
   */
  private async _run(
    input: ExecuteInput,
    run: Run,
    moduleBase64: string,
  ): Promise<ExecutionOutcome | Refused> {
    const cfg = this.config.execution;
    const release = await this.semaphore.acquire();
    if (!release) {
      run.logs.audit(
        "execution.resource_limit",
        "denied",
        { limit: "maxConcurrent", value: cfg.maxConcurrent },
        "warn",
      );
      return {
        error: {
          type: "resource_limit",
          reason: "executor_busy",
          message: "Too many concurrent executions; retry shortly",
        },
      };
    }
    try {
      return await this.executor.execute({
        executionId: run.executionId,
        moduleBase64,
        bindings: this.info.operations,
        basePath: this.broker.sdkBasePath,
        limits: {
          timeoutMs: Math.min(
            Math.max(input.timeoutMs ?? cfg.timeoutMs, 100),
            cfg.maxTimeoutMs,
          ),
          memoryMb: cfg.memoryMb,
          maxSdkCalls: cfg.maxSdkCalls,
          maxResultBytes: cfg.maxResultBytes,
          maxLogBytes: cfg.maxLogBytes,
          maxLogEntries: 200,
          maxStdoutBytes: Math.max(cfg.maxResultBytes * 4, 8 * 1024 * 1024),
        },
        bridge: (req, signal) =>
          this.broker.handle(
            req,
            {
              principal: run.ctx.principal,
              executionId: run.executionId,
              requestId: run.ctx.requestId,
              logs: run.logs,
            },
            signal,
          ),
      });
    } finally {
      release();
    }
  }

  /**
   * Audit what the sandbox enforced: denied capabilities and result limits.
   *
   * @private
   */
  private _auditOutcome(run: Run, outcome: ExecutionOutcome): void {
    const error = outcome.error;
    if (
      error?.type === "permission_denied" &&
      error.reason === "sandbox_capability_denied"
    ) {
      run.logs.audit(
        "execution.capability_denied",
        "denied",
        { capability: error.capability ?? "unknown" },
        "warn",
      );
    }
    if (
      error?.type === "output_limit" ||
      error?.type === "unsupported_result"
    ) {
      run.logs.audit(
        "execution.resource_limit",
        "denied",
        { limit: error.type },
        "warn",
      );
    }
  }

  /**
   * The tool output for an execution that ran, with any known secret that an
   * API response might echo back scrubbed.
   *
   * @private
   */
  private _output(run: Run, outcome: ExecutionOutcome): ExecuteOutput {
    const durationMs = () => Date.now() - run.started;
    run.logs.op(
      "info",
      outcome.ok ? "execution.completed" : "execution.failed",
      {
        durationMs: durationMs(),
        sdkCalls: outcome.stats.sdkCalls,
        terminated: outcome.stats.terminated,
        errorType: outcome.error?.type,
        outcome: outcome.ok ? "success" : "failure",
      },
    );
    return {
      ok: outcome.ok,
      executionId: run.executionId,
      result: outcome.ok
        ? JSON.parse(secrets.scrubKnown(JSON.stringify(outcome.result ?? null)))
        : undefined,
      logs: outcome.logs.map((l) => ({
        level: l.level,
        message: secrets.scrubKnown(l.message),
      })),
      logsTruncated: outcome.logsTruncated,
      error: outcome.error ? this._scrubError(outcome.error) : undefined,
      hint: _outcomeHint(outcome),
      stats: { durationMs: durationMs(), sdkCalls: outcome.stats.sdkCalls },
    };
  }

  /**
   * The tool output for a call refused before or instead of running.
   *
   * @private
   */
  private _fail(run: Run, error: ExecutionError, hint?: string): ExecuteOutput {
    run.logs.op("info", "execution.failed", {
      errorType: error.type,
      reason: error.reason,
      durationMs: Date.now() - run.started,
      outcome: "failure",
    });
    return {
      ok: false,
      executionId: run.executionId,
      logs: [],
      logsTruncated: false,
      error: this._scrubError(error),
      hint,
      stats: { durationMs: Date.now() - run.started, sdkCalls: 0 },
    };
  }

  /**
   * Remove secrets from an execution error.
   *
   * @private
   */
  private _scrubError(e: ExecutionError): ExecutionError {
    return boundValue(e, { maxString: 4000, maxDepth: 4 }) as ExecutionError;
  }
}

"use strict";
/**
 * Static checks and transpilation of agent-submitted code.
 *
 * Agent code is the body of an async function receiving `sdk` and
 * `console`. Module syntax and dynamic `import()` are rejected before
 * execution; the Deno sandbox additionally disables string code generation
 * so imports cannot be smuggled through eval. These checks are defence in
 * depth, not the security boundary: the separate, permissionless Deno
 * process is.
 *
 * @module executor/code-policy
 */
import ts from "typescript";

import type { Diagnostic, ExecutionError } from "./types.js";

/** Number of wrapper lines that precede agent code. */
export const WRAPPER_HEADER_LINES = 1;

/** Result of preparing code. */
export type PreparedCode =
  | { ok: true; moduleBase64: string; js: string }
  | { ok: false; error: ExecutionError; violations?: string[] };

/**
 * Wrap agent code for transpilation and execution.
 *
 * @param {String} code - agent code
 * @return {String} module source
 */
export function wrapForExecution(code: string): string {
  return `export default async function __oagMcpMain(sdk, console) {\n${code}\n}\n`;
}

/**
 * Wrap agent code for type checking against the global `sdk` declaration.
 *
 * @param {String} code - agent code
 * @return {String} TypeScript source
 */
export function wrapForTypecheck(code: string): string {
  return `export {}; async function __oagMcpMain() {\n${code}\n}\n`;
}

/**
 * Convert a TypeScript diagnostic to agent coordinates.
 *
 * @param {Object} d - diagnostic
 * @return {Object|undefined} mapped diagnostic
 */
export function mapDiagnostic(d: ts.Diagnostic): Diagnostic | undefined {
  if (!d.file || d.start === undefined) {
    return {
      line: 0,
      column: 0,
      code: d.code,
      message: ts.flattenDiagnosticMessageText(d.messageText, "\n"),
    };
  }
  const pos = d.file.getLineAndCharacterOfPosition(d.start);
  const line = pos.line + 1 - WRAPPER_HEADER_LINES;
  return {
    line: Math.max(line, 1),
    column: pos.character + 1,
    code: d.code,
    message: ts.flattenDiagnosticMessageText(d.messageText, "\n"),
  };
}

/** Module-loading constructs agent code may not use, and how to name them. */
const MODULE_LOADERS: ReadonlyArray<[(n: ts.Node) => boolean, string]> = [
  [
    (n) =>
      ts.isCallExpression(n) &&
      n.expression.kind === ts.SyntaxKind.ImportKeyword,
    "dynamic import()",
  ],
  [
    (n) =>
      ts.isMetaProperty(n) && n.keywordToken === ts.SyntaxKind.ImportKeyword,
    "import.meta",
  ],
  [
    (n) =>
      ts.isCallExpression(n) &&
      ts.isIdentifier(n.expression) &&
      n.expression.text === "require",
    "require()",
  ],
  [
    (n) =>
      ts.isImportDeclaration(n) ||
      ts.isImportEqualsDeclaration(n) ||
      (ts.isExportDeclaration(n) && Boolean(n.moduleSpecifier)),
    "module import",
  ],
];

/**
 * Find module-loading constructs in agent code.
 *
 * @param {String} code - agent code
 * @param {String} language - "typescript" or "javascript"
 * @return {Array} violation descriptions with line numbers
 */
export function findViolations(
  code: string,
  language: "typescript" | "javascript",
): string[] {
  const sf = ts.createSourceFile(
    language === "typescript" ? "agent.ts" : "agent.js",
    wrapForExecution(code),
    ts.ScriptTarget.ES2022,
    true,
    language === "typescript" ? ts.ScriptKind.TS : ts.ScriptKind.JS,
  );
  const out: string[] = [];
  const visit = (n: ts.Node) => {
    const loader = MODULE_LOADERS.find(([matches]) => matches(n));
    if (loader) {
      const line =
        sf.getLineAndCharacterOfPosition(n.getStart(sf)).line +
        1 -
        WRAPPER_HEADER_LINES;
      out.push(`${loader[1]} at line ${line}`);
    }
    ts.forEachChild(n, visit);
  };
  visit(sf);
  return out;
}

/**
 * Validate and transpile agent code into a base64 ES module.
 *
 * @param {String} code - agent code
 * @param {String} language - "typescript" or "javascript"
 * @param {Number} maxBytes - maximum accepted code size
 * @return {Object} prepared code or error
 */
export function prepareCode(
  code: string,
  language: "typescript" | "javascript",
  maxBytes: number,
): PreparedCode {
  if (Buffer.byteLength(code) > maxBytes) {
    return {
      ok: false,
      error: {
        type: "resource_limit",
        reason: "code_too_large",
        message: `Code is ${Buffer.byteLength(code)} bytes; the limit is ${maxBytes}`,
      },
    };
  }
  const result = ts.transpileModule(wrapForExecution(code), {
    fileName: language === "typescript" ? "agent.ts" : "agent.js",
    reportDiagnostics: true,
    compilerOptions: {
      target: ts.ScriptTarget.ES2022,
      module: ts.ModuleKind.ESNext,
      allowJs: true,
      sourceMap: false,
      removeComments: false,
    },
  });
  const syntax = (result.diagnostics ?? [])
    .filter((d) => d.category === ts.DiagnosticCategory.Error)
    .map(mapDiagnostic)
    .filter((d): d is Diagnostic => Boolean(d));
  if (syntax.length > 0) {
    return {
      ok: false,
      error: {
        type: "syntax_error",
        message: `Code has ${syntax.length} syntax error(s): ${syntax[0].message} (line ${syntax[0].line})`,
        diagnostics: syntax.slice(0, 10),
      },
    };
  }
  const violations = findViolations(code, language);
  if (violations.length > 0) {
    return {
      ok: false,
      violations,
      error: {
        type: "permission_denied",
        reason: "import_not_allowed",
        message: `Imports are not allowed; use the provided \`sdk\` binding instead (${violations.slice(0, 3).join("; ")})`,
      },
    };
  }
  return {
    ok: true,
    js: result.outputText,
    moduleBase64: Buffer.from(result.outputText).toString("base64"),
  };
}

"use strict";
/**
 * Deno subprocess executor.
 *
 * Each execution runs in a fresh Deno process:
 *
 * - no `--allow-*` permissions: filesystem, network, environment,
 *   subprocess, FFI and system information access are all denied;
 * - `--no-remote --no-npm --cached-only --no-config --no-lock`: no package
 *   installation or remote imports;
 * - V8 `--disallow-code-generation-from-strings` (no eval/new Function) and
 *   a heap limit;
 * - an empty environment (only Deno bookkeeping variables pointing at a
 *   private temporary directory) and a private temporary working directory;
 * - a wall-clock timeout after which the process is killed (SIGKILL);
 * - bounded stdout, logs and result size.
 *
 * Process separation plus Deno's permission model is the boundary. It is
 * not a complete sandbox: see docs/security.md for the residual risks.
 *
 * @module executor/deno-executor
 */
import { type ChildProcess, spawn, spawnSync } from "node:child_process";
import fs from "node:fs";
import { createRequire } from "node:module";
import os from "node:os";
import path from "node:path";

import semver from "semver";
import which from "which";

import { OagMcpError } from "../errors.js";
import type { Logs } from "../logging/logger.js";
import type { OperationBinding } from "../types.js";
import { DENO_VERSION_RANGE } from "../util/version.js";
import type {
  BridgeFetchRequest,
  ExecutionError,
  ExecutionOutcome,
  ExecutionRequest,
  Executor,
  LogEntry,
} from "./types.js";

const require = createRequire(import.meta.url);

/** Sandbox stderr characters kept to classify an unexpected exit. */
const STDERR_KEPT = 16384;

/** Resolved Deno runtime. */
export interface DenoRuntime {
  path: string;
  version: string;
  source: "configured" | "env" | "npm-package" | "path";
}

/**
 * Name of the `deno` npm package's binary package for this platform, e.g.
 * `@deno/darwin-arm64` or `@deno/linux-x64-glibc` (the same naming the
 * `deno` package's own installer uses).
 *
 * @param {String} [platform] - Node.js platform, default: this process's
 * @param {String} [arch] - Node.js architecture, default: this process's
 * @return {String} package name
 */
export function denoPlatformPackage(
  platform: string = process.platform,
  arch: string = os.arch(),
): string {
  return platform === "linux"
    ? `@deno/linux-${arch}-glibc`
    : `@deno/${platform}-${arch}`;
}

/** A place a Deno binary may be found. */
interface DenoCandidate {
  path: string;
  source: DenoRuntime["source"];
}

/**
 * The Deno binary of an installed npm package, if the package is installed.
 *
 * @private
 */
function _packageBinary(pkg: string, exe: string): DenoCandidate[] {
  try {
    const dir = path.dirname(require.resolve(`${pkg}/package.json`));
    return [{ path: path.join(dir, exe), source: "npm-package" }];
  } catch {
    // The optional npm package is not installed.
    return [];
  }
}

/**
 * Where to look for Deno, in order of preference.
 *
 * @private
 */
function _denoCandidates(configured: string | undefined): DenoCandidate[] {
  const exe = process.platform === "win32" ? "deno.exe" : "deno";
  const fromEnv = process.env.OAG_MCP_DENO_PATH;
  return [
    ...(configured
      ? [{ path: configured, source: "configured" as const }]
      : []),
    ...(fromEnv ? [{ path: fromEnv, source: "env" as const }] : []),
    ..._packageBinary(denoPlatformPackage(), exe),
    ..._packageBinary("deno", exe),
    ..._onPath(),
  ];
}

/**
 * Deno on this process's PATH, as an absolute path: the probe and the
 * sandbox run with an environment that has no PATH of its own.
 *
 * @private
 */
function _onPath(): DenoCandidate[] {
  const found = which.sync("deno", { nothrow: true });
  return found ? [{ path: found, source: "path" }] : [];
}

/**
 * The version a candidate reports, if it exists and runs as Deno.
 *
 * @private
 */
function _denoVersion(c: DenoCandidate): string | undefined {
  if (!fs.existsSync(c.path)) {
    return undefined;
  }
  const res = spawnSync(c.path, ["--version"], {
    encoding: "utf8",
    env: { NO_COLOR: "1", DENO_NO_UPDATE_CHECK: "1" },
  });
  if (res.status !== 0 || res.error) {
    return undefined;
  }
  return /deno (\d+\.\d+\.\d+)/.exec(res.stdout)?.[1];
}

/**
 * Locate a Deno binary: configured path, OAG_MCP_DENO_PATH, the `deno` npm
 * package installed with oag-mcp, or `deno` on PATH.
 *
 * From the npm package, the binary in this platform's package
 * ({@link denoPlatformPackage}) is tried first, then the copy the `deno`
 * package's install step places in its own folder. That copy is made once,
 * for the platform that first installed it, so it can be a binary for
 * another operating system when `node_modules` is shared, e.g. between a
 * macOS host and a Linux container.
 *
 * @param {String} [configured] - configured path
 * @return {Object} runtime
 */
export function resolveDeno(configured?: string): DenoRuntime {
  for (const c of _denoCandidates(configured)) {
    const version = _denoVersion(c);
    if (!version) {
      continue;
    }
    if (!semver.satisfies(version, DENO_VERSION_RANGE)) {
      throw new OagMcpError(
        "DENO_VERSION_UNSUPPORTED",
        `Deno ${version} at ${c.path} is outside the supported range ${DENO_VERSION_RANGE}`,
        {
          hint: "Install a supported Deno 2.x release or set OAG_MCP_DENO_PATH.",
        },
      );
    }
    return { path: c.path, version, source: c.source };
  }
  throw new OagMcpError(
    "DENO_NOT_FOUND",
    "No Deno runtime was found for the execute tool",
    {
      hint: "Reinstall oag-mcp so its `deno` dependency is installed, install Deno 2.x (https://deno.com) on PATH, or set OAG_MCP_DENO_PATH.",
    },
  );
}

/**
 * The environment of a sandbox process: only Deno bookkeeping variables
 * pointing at its private temporary directory, plus what Windows needs to
 * start a process.
 *
 * @param {String} tmp - the execution's private temporary directory
 * @return {Object} environment variables
 */
export function sandboxEnv(tmp: string): Record<string, string> {
  const env: Record<string, string> = {
    DENO_DIR: path.join(tmp, "deno-dir"),
    DENO_NO_UPDATE_CHECK: "1",
    DENO_NO_PROMPT: "1",
    NO_COLOR: "1",
    TMPDIR: tmp,
    HOME: tmp,
    // Deterministic date handling: typescript-fetch maps `format: date` to
    // local midnight, so pin the sandbox clock zone to UTC.
    TZ: "UTC",
  };
  if (process.platform === "win32" && process.env.SystemRoot) {
    env.SystemRoot = process.env.SystemRoot;
  }
  return env;
}

/** Options for {@link DenoExecutor}. */
export interface DenoExecutorOptions {
  /** Preparation workspace containing executor/runner.js and sdk/. */
  workspaceDir: string;
  deno: DenoRuntime;
  logs: Logs;
}

/**
 * Executor running agent code in a restricted Deno subprocess.
 */
export class DenoExecutor implements Executor {
  readonly name = "deno-subprocess";
  private readonly runner: string;

  /**
   * @param {Object} opts - executor options
   */
  constructor(private readonly opts: DenoExecutorOptions) {
    this.runner = path.join(opts.workspaceDir, "executor", "runner.js");
  }

  /**
   * Deno command-line arguments for an execution.
   *
   * @param {Number} memoryMb - heap limit
   * @return {Array} arguments
   */
  args(memoryMb: number): string[] {
    return [
      "run",
      "--no-prompt",
      "--no-config",
      "--no-lock",
      "--no-remote",
      "--no-npm",
      "--cached-only",
      `--v8-flags=--max-old-space-size=${memoryMb},--disallow-code-generation-from-strings`,
      this.runner,
    ];
  }

  /**
   * Run the bundle in verification mode: load it and check every binding.
   *
   * @param {Array} bindings - operation bindings
   * @param {String} basePath - SDK base path
   */
  async verify(bindings: OperationBinding[], basePath: string): Promise<void> {
    const outcome = await this._run(
      {
        executionId: "verify",
        moduleBase64: "",
        bindings,
        basePath,
        limits: {
          timeoutMs: 20000,
          memoryMb: 128,
          maxSdkCalls: 0,
          maxResultBytes: 4096,
          maxLogBytes: 1024,
          maxLogEntries: 10,
          maxStdoutBytes: 1024 * 1024,
        },
        // maxSdkCalls 0: the executor refuses every SDK call itself.
        bridge: () => Promise.reject(new Error("no SDK calls in verification")),
      },
      true,
    );
    if (!outcome.ok) {
      throw new OagMcpError(
        "EXECUTOR_VERIFY_FAILED",
        `The SDK bundle failed to load in Deno: ${outcome.error?.message}`,
        {
          hint: "The SDK must run without Node.js built-ins or filesystem/network access at import time.",
        },
      );
    }
  }

  /**
   * Execute prepared code.
   *
   * @param {Object} req - execution request
   * @return {Promise} outcome
   */
  execute(req: ExecutionRequest): Promise<ExecutionOutcome> {
    return this._run(req, false);
  }

  /**
   * Spawn Deno and run the protocol.
   *
   * @private
   */
  private async _run(
    req: ExecutionRequest,
    verifyOnly: boolean,
  ): Promise<ExecutionOutcome> {
    const started = Date.now();
    const logs = this.opts.logs.child({ executionId: req.executionId });
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), "oag-mcp-exec-"));
    const env = sandboxEnv(tmp);
    let child: ChildProcess;
    try {
      child = spawn(this.opts.deno.path, this.args(req.limits.memoryMb), {
        cwd: tmp,
        env,
        stdio: ["pipe", "pipe", "pipe"],
        windowsHide: true,
      });
    } catch (err) {
      fs.rmSync(tmp, { recursive: true, force: true });
      throw err;
    }
    // Audit records about the sandbox identify its process.
    const audit: Logs["audit"] = (event, outcome, fields = {}, level) =>
      logs.audit(event, outcome, { ...fields, pid: child.pid }, level);
    const abort = new AbortController();
    let sdkCalls = 0;
    let stdoutBytes = 0;
    let stderr = "";
    let buffer = "";
    let settled = false;
    let terminated = false;
    let done: Record<string, unknown> | undefined;
    let limitError: ExecutionError | undefined;

    const kill = (reason: string, forced = true) => {
      if (child.exitCode === null && child.signalCode === null) {
        child.kill("SIGKILL");
        if (forced && !terminated) {
          terminated = true;
          audit(
            "executor.terminated",
            "terminated",
            { reason, executor: this.name },
            "warn",
          );
        }
      }
    };

    child.stdin?.on("error", () => {
      // The sandbox may exit (or be killed) while a broker reply is pending.
    });
    const write = (msg: unknown) => {
      // A failed write is reported on stdin's "error" event, handled above.
      if (!settled && child.stdin?.writable) {
        child.stdin.write(`${JSON.stringify(msg)}\n`);
      }
    };

    const outcome = await new Promise<ExecutionOutcome>((resolve) => {
      const finish = (o: Omit<ExecutionOutcome, "stats">) => {
        if (settled) {
          return;
        }
        settled = true;
        clearTimeout(timer);
        abort.abort();
        // The runner exits by itself after reporting; reap it if it lingers.
        setTimeout(() => kill("cleanup", false), 500).unref();
        resolve({
          ...o,
          stats: { durationMs: Date.now() - started, sdkCalls, terminated },
        });
      };

      const timer = setTimeout(() => {
        audit(
          "execution.timeout",
          "denied",
          { timeoutMs: req.limits.timeoutMs, reason: "wall_clock_timeout" },
          "warn",
        );
        kill("timeout");
        finish({
          ok: false,
          logs: [],
          logsTruncated: false,
          error: {
            type: "timeout",
            message: `Execution exceeded the ${req.limits.timeoutMs} ms time limit and was terminated`,
          },
        });
      }, req.limits.timeoutMs);

      const handleFetch = async (msg: BridgeFetchRequest) => {
        sdkCalls++;
        if (sdkCalls > req.limits.maxSdkCalls) {
          audit(
            "execution.resource_limit",
            "denied",
            { limit: "maxSdkCalls", value: req.limits.maxSdkCalls },
            "warn",
          );
          write({
            type: "fetchResult",
            rid: msg.rid,
            ok: false,
            error: {
              type: "resource_limit",
              reason: "max_sdk_calls",
              message: `More than ${req.limits.maxSdkCalls} SDK calls in one execution`,
            },
          });
          return;
        }
        let result;
        try {
          result = await req.bridge(msg, abort.signal);
        } catch (err) {
          result = {
            ok: false as const,
            error: {
              type: "executor_error" as const,
              message: `Broker failure: ${(err as Error).message}`,
            },
          };
        }
        write({ type: "fetchResult", rid: msg.rid, ...result });
      };

      child.stdout!.on("data", (chunk: Buffer) => {
        stdoutBytes += chunk.length;
        if (stdoutBytes > req.limits.maxStdoutBytes) {
          limitError = {
            type: "output_limit",
            reason: "stdout_limit",
            message: `Sandbox output exceeded ${req.limits.maxStdoutBytes} bytes`,
          };
          audit(
            "execution.resource_limit",
            "denied",
            { limit: "maxStdoutBytes", value: req.limits.maxStdoutBytes },
            "warn",
          );
          kill("output_limit");
          return;
        }
        buffer += chunk.toString("utf8");
        let idx;
        while ((idx = buffer.indexOf("\n")) >= 0) {
          const line = buffer.slice(0, idx);
          buffer = buffer.slice(idx + 1);
          let msg: Record<string, unknown>;
          try {
            msg = JSON.parse(line);
          } catch {
            continue;
          }
          if (msg.type === "fetch") {
            void handleFetch(msg as unknown as BridgeFetchRequest);
          } else if (msg.type === "done" && !done) {
            done = msg;
            finish({
              ok: Boolean(msg.ok),
              result: msg.result,
              resultUndefined: Boolean(msg.resultUndefined),
              logs: Array.isArray(msg.logs) ? (msg.logs as LogEntry[]) : [],
              logsTruncated: Boolean(msg.logsTruncated),
              error: msg.error as ExecutionError | undefined,
            });
          }
        }
      });
      child.stderr!.on("data", (chunk: Buffer) => {
        // Keep the end: Deno's fatal errors (out of memory) come last, and
        // sandboxed code may write to stderr before them.
        stderr = (stderr + chunk.toString("utf8")).slice(-STDERR_KEPT);
      });
      child.on("error", (err) => {
        finish({
          ok: false,
          logs: [],
          logsTruncated: false,
          error: {
            type: "executor_error",
            message: `Failed to start Deno: ${err.message}`,
          },
        });
      });
      child.on("close", (code, signal) => {
        if (settled) {
          return;
        }
        if (limitError) {
          finish({
            ok: false,
            logs: [],
            logsTruncated: false,
            error: limitError,
          });
          return;
        }
        const oom = /out of memory|heap limit|Allocation failed/i.test(stderr);
        if (oom) {
          audit(
            "execution.resource_limit",
            "denied",
            { limit: "memoryMb", value: req.limits.memoryMb },
            "warn",
          );
        }
        finish({
          ok: false,
          logs: [],
          logsTruncated: false,
          error: oom
            ? {
                type: "resource_limit",
                reason: "memory_limit",
                message: `Execution exceeded the ${req.limits.memoryMb} MB memory limit`,
              }
            : {
                type: "executor_error",
                message: `Sandbox exited unexpectedly (code ${code ?? "null"}${signal ? `, signal ${signal}` : ""})`,
              },
        });
      });
      write({
        type: "init",
        code: req.moduleBase64,
        verifyOnly,
        bindings: req.bindings.map((b) => ({
          id: b.id,
          className: b.className,
          methodName: b.methodName,
        })),
        basePath: req.basePath,
        limits: {
          maxLogBytes: req.limits.maxLogBytes,
          maxLogEntries: req.limits.maxLogEntries,
          maxResultBytes: req.limits.maxResultBytes,
        },
      });
    });
    child.stdin?.end();
    fs.rmSync(tmp, { recursive: true, force: true });
    return outcome;
  }
}

"use strict";
/**
 * Type-check agent TypeScript against the exposed `sdk` binding.
 *
 * Type checking is a correctness aid that returns useful diagnostics before
 * code runs; it is not an authorisation boundary.
 *
 * @module executor/typecheck
 */
import fs from "node:fs";
import path from "node:path";

import ts from "typescript";

import { sdkCompilerOptions } from "../prepare/bundle.js";
import { mapDiagnostic, wrapForTypecheck } from "./code-policy.js";
import type { Diagnostic } from "./types.js";

/**
 * A persistent language service over the prepared SDK declarations.
 */
export class AgentTypeChecker {
  private readonly service: ts.LanguageService;
  private readonly agentFile: string;
  private readonly libDir: string;
  private version = 0;
  private current = "";
  private readonly options: ts.CompilerOptions;

  /**
   * @param {String} sdkDir - workspace sdk/ directory (contains types/ and sdk-binding.d.ts)
   * @param {String} libDir - directory with TypeScript lib files
   */
  constructor(sdkDir: string, libDir: string) {
    this.libDir = libDir;
    this.agentFile = path.join(sdkDir, "__agent__.ts");
    const bindingFile = path.join(sdkDir, "sdk-binding.d.ts");
    this.options = {
      ...sdkCompilerOptions(),
      noEmit: true,
      strict: true,
      noImplicitAny: false,
      noUnusedLocals: false,
      noUnusedParameters: false,
      noImplicitReturns: false,
      allowUnreachableCode: true,
    };
    const snapshots = new Map<string, ts.IScriptSnapshot>();
    const host: ts.LanguageServiceHost = {
      getCompilationSettings: () => this.options,
      getScriptFileNames: () => [bindingFile, this.agentFile],
      getScriptVersion: (f) =>
        f === this.agentFile ? String(this.version) : "0",
      getScriptSnapshot: (f) => {
        if (f === this.agentFile) {
          return ts.ScriptSnapshot.fromString(this.current);
        }
        let snap = snapshots.get(f);
        if (!snap) {
          if (!fs.existsSync(f)) {
            return undefined;
          }
          snap = ts.ScriptSnapshot.fromString(fs.readFileSync(f, "utf8"));
          snapshots.set(f, snap);
        }
        return snap;
      },
      getCurrentDirectory: () => sdkDir,
      getDefaultLibFileName: () => path.join(this.libDir, "lib.es2022.d.ts"),
      fileExists: (f) => f === this.agentFile || fs.existsSync(f),
      readFile: (f) => this._readFile(f),
      readDirectory: ts.sys.readDirectory,
      directoryExists: ts.sys.directoryExists,
      getDirectories: ts.sys.getDirectories,
    };
    this.service = ts.createLanguageService(host, ts.createDocumentRegistry());
  }

  /**
   * The agent code being checked, or a file from disk (undefined when
   * missing).
   *
   * @private
   */
  private _readFile(f: string): string | undefined {
    return f === this.agentFile ? this.current : ts.sys.readFile(f);
  }

  /**
   * Type-check agent code.
   *
   * @param {String} code - agent TypeScript (function body)
   * @return {Array} diagnostics (empty when the code type-checks)
   */
  check(code: string): Diagnostic[] {
    this.current = wrapForTypecheck(code);
    this.version++;
    const diags = [
      ...this.service.getSyntacticDiagnostics(this.agentFile),
      ...this.service.getSemanticDiagnostics(this.agentFile),
    ].filter((d) => d.category === ts.DiagnosticCategory.Error);
    return diags
      .map(mapDiagnostic)
      .filter((d): d is Diagnostic => Boolean(d))
      .slice(0, 10);
  }

  /** Warm the language service so the first agent call is fast. */
  warmUp(): void {
    this.check("return 1;");
  }
}

"use strict";
/**
 * Trusted host-side request broker.
 *
 * Every HTTP request made by the sandboxed SDK arrives here as a bridge
 * message tagged with the SDK binding that issued it. Before anything is
 * sent upstream the broker:
 *
 * 1. authorises the operation for the request principal (audited);
 * 2. checks the request matches that operation (method and path template)
 *    and targets the configured base URL (network policy);
 * 3. strips agent-supplied credential headers and query parameters;
 * 4. resolves the operation's security requirement into credentials;
 * 5. performs the request with manual redirect handling, following only
 *    permitted redirects and never forwarding credentials cross-origin;
 * 6. bounds the response size and removes Set-Cookie headers.
 *
 * @module upstream/broker
 */
import type { AuthorizationPolicy } from "../server/authorization.js";
import type {
  BridgeFetchRequest,
  BridgeFetchResult,
  ExecutionError,
} from "../executor/types.js";
import type { Logs } from "../logging/logger.js";
import { sanitizeError } from "../util/redact.js";
import type {
  OperationBinding,
  Principal,
  SecuritySchemeInfo,
} from "../types.js";
import { UpstreamAuthError } from "./credentials.js";
import type { CredentialProvider } from "./types.js";
import { resolveSecurity } from "./security.js";

/** Network and size policy for upstream calls. */
export interface NetworkPolicy {
  baseUrl: string;
  /** Extra origins redirects may target (credentials are not forwarded). */
  allowedOrigins: string[];
  followRedirects: boolean;
  maxRedirects: number;
  timeoutMs: number;
  maxResponseBytes: number;
  maxRequestBytes: number;
}

/** Per-execution context for the broker. */
export interface BrokerContext {
  principal: Principal;
  executionId: string;
  requestId?: string;
  logs: Logs;
}

const HOP_BY_HOP = new Set([
  "connection",
  "keep-alive",
  "transfer-encoding",
  "te",
  "trailer",
  "upgrade",
  "host",
  "content-length",
  "proxy-connection",
]);
const ALWAYS_STRIPPED = new Set([
  "authorization",
  "proxy-authorization",
  "cookie",
]);
const RESPONSE_STRIPPED = new Set(["set-cookie", "set-cookie2"]);
const REDIRECT_STATUSES = new Set([301, 302, 303, 307, 308]);

/** A refused request: the bridge result returned to the sandbox. */
type Refusal = Extract<BridgeFetchResult, { ok: false }>;

/** The authorisation policy's decision for an allowed operation. */
type Decision = ReturnType<AuthorizationPolicy["decide"]>;

/** Credentials resolved for an operation's security requirement. */
type AppliedSecurity = Awaited<ReturnType<typeof resolveSecurity>>;

/** A request body, decoded. */
type Body = Uint8Array | string | undefined;

/** One SDK operation call as it moves through the broker's steps. */
interface Call {
  op: OperationBinding;
  /** The operation's path template as a URL path matcher. */
  re: RegExp;
  ctx: BrokerContext;
  signal: AbortSignal;
  /** Fields identifying the operation in audit records. */
  audit: {
    operation: string;
    operationId?: string;
    httpMethod: string;
    pathTemplate: string;
  };
}

/** Where the request goes, once checked. */
interface Target {
  url: URL;
  method: string;
  /** Request headers, set once credentials are applied. */
  headers?: Record<string, string>;
}

/** Request headers without agent-supplied credentials. */
interface Stripped {
  headers: Record<string, string>;
  /** Names of the credential headers and query parameters removed. */
  names: string[];
}

/** A response received from the API. */
interface Sent {
  response: Response;
  /** When the request was first sent, in milliseconds. */
  started: number;
}

/**
 * Compile a path template into a regular expression over URL paths.
 *
 * @param {String} basePath - base URL path without trailing slash
 * @param {String} template - OpenAPI path template
 * @return {RegExp} matcher
 */
export function compilePathTemplate(
  basePath: string,
  template: string,
): RegExp {
  const escape = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const parts = template
    .split(/(\{[^}]+\})/)
    .map((part) => (/^\{[^}]+\}$/.test(part) ? "[^/]+" : escape(part)));
  return new RegExp(`^${escape(basePath)}${parts.join("")}/?$`);
}

/**
 * Host-side broker for sandboxed SDK requests.
 */
export class RequestBroker {
  private readonly ops = new Map<
    string,
    { op: OperationBinding; re: RegExp }
  >();
  private readonly base: URL;
  private readonly basePath: string;
  private readonly allowedOrigins: Set<string>;
  private readonly credentialNames: {
    headers: Set<string>;
    query: Set<string>;
  };

  /**
   * @param {Object} opts - broker options
   */
  constructor(
    private readonly opts: {
      operations: OperationBinding[];
      schemes: Record<string, SecuritySchemeInfo>;
      provider: CredentialProvider;
      policy: AuthorizationPolicy;
      network: NetworkPolicy;
      fetchImpl?: typeof fetch;
    },
  ) {
    this.base = new URL(opts.network.baseUrl);
    this.basePath = this.base.pathname.replace(/\/+$/, "");
    for (const op of opts.operations) {
      this.ops.set(op.id, {
        op,
        re: compilePathTemplate(this.basePath, op.path),
      });
    }
    this.allowedOrigins = new Set([
      this.base.origin,
      ...opts.network.allowedOrigins.map((o) => new URL(o).origin),
    ]);
    const headers = new Set<string>();
    const query = new Set<string>();
    for (const s of Object.values(opts.schemes)) {
      if (s.type === "apiKey" && s.paramName) {
        (s.in === "query" ? query : headers).add(s.paramName.toLowerCase());
      }
    }
    this.credentialNames = { headers, query };
  }

  /** Base path the sandboxed SDK must use. */
  get sdkBasePath(): string {
    return `${this.base.origin}${this.basePath}`;
  }

  /**
   * Build an error result.
   *
   * @private
   */
  private _err(error: ExecutionError): Refusal {
    return { ok: false, error };
  }

  /**
   * Handle one bridge fetch: each step either passes its result on or
   * refuses the request.
   *
   * @param {Object} req - bridge request
   * @param {Object} ctx - broker context
   * @param {AbortSignal} signal - aborted when the execution ends
   * @return {Promise} bridge result
   */
  async handle(
    req: BridgeFetchRequest,
    ctx: BrokerContext,
    signal: AbortSignal,
  ): Promise<BridgeFetchResult> {
    const call = this._call(req, ctx, signal);
    if (_refused(call)) {
      return call;
    }
    const decision = this._authorize(call);
    if (_refused(decision)) {
      return decision;
    }
    const target = this._destination(call, req);
    if (_refused(target)) {
      return target;
    }
    const stripped = this._stripCredentials(req, target);
    const applied = await this._applyCredentials(
      call,
      decision,
      target,
      stripped,
    );
    if (_refused(applied)) {
      return applied;
    }
    const body = this._body(call, req);
    if (_refused(body)) {
      return body;
    }
    const sent = await this._send(call, { ...target, body }, applied);
    if (_refused(sent)) {
      return sent;
    }
    this._invalidateRejected(call, sent.response, applied);
    return this._readResponse(call, sent);
  }

  /**
   * Find the operation of the SDK binding that sent the request. An unknown
   * binding can only come from agent code writing bridge messages itself.
   *
   * @private
   */
  private _call(
    req: BridgeFetchRequest,
    ctx: BrokerContext,
    signal: AbortSignal,
  ): Call | Refusal {
    const entry = this.ops.get(req.binding);
    if (!entry) {
      ctx.logs.audit(
        "execution.boundary_violation",
        "denied",
        {
          reason: "unknown_binding",
          binding: String(req.binding).slice(0, 120),
        },
        "warn",
      );
      return this._err({
        type: "permission_denied",
        reason: "unknown_binding",
        message: "Request did not come from a known SDK binding",
      });
    }
    const { op, re } = entry;
    return {
      op,
      re,
      ctx,
      signal,
      audit: {
        operation: op.id,
        operationId: op.operationId,
        httpMethod: op.httpMethod,
        pathTemplate: op.path,
      },
    };
  }

  /**
   * Step 1: authorise the operation, for every attempted SDK operation.
   *
   * Each attempt gets exactly one decision record: denied here, a denied
   * destination or a credential failure in a later step, or allowed once
   * credentials are applied.
   *
   * @private
   */
  private _authorize(call: Call): Decision | Refusal {
    const decision = this.opts.policy.decide(call.ctx.principal, call.op);
    if (decision.allowed) {
      return decision;
    }
    call.ctx.logs.audit(
      "authorization.denied",
      "denied",
      {
        ...call.audit,
        policyId: decision.policyId,
        reason: decision.reason,
      },
      "warn",
    );
    return this._err({
      type: "permission_denied",
      reason: "authorization_denied",
      operation: call.op.id,
      message: `You are not permitted to call ${call.op.id}`,
    });
  }

  /**
   * Step 2: the request must match the operation (method and path template)
   * and target the configured base URL.
   *
   * @private
   */
  private _destination(call: Call, req: BridgeFetchRequest): Target | Refusal {
    let url: URL;
    try {
      url = new URL(req.url);
    } catch {
      call.ctx.logs.audit(
        "network.destination_denied",
        "denied",
        { ...call.audit, reason: "invalid_url" },
        "warn",
      );
      return this._err({
        type: "permission_denied",
        reason: "invalid_url",
        message: "Invalid request URL",
      });
    }
    const method = String(req.method).toUpperCase();
    const reason = this._destinationMismatch(call, url, method);
    if (!reason) {
      return { url, method };
    }
    call.ctx.logs.audit(
      "network.destination_denied",
      "denied",
      {
        operation: call.op.id,
        httpMethod: method,
        pathTemplate: call.op.path,
        reason,
        destinationOrigin: url.origin,
      },
      "warn",
    );
    return this._err({
      type: "permission_denied",
      reason: "network_destination_denied",
      operation: call.op.id,
      message: `Request to ${url.origin} does not match ${call.op.httpMethod} ${call.op.path} on the configured API base URL`,
    });
  }

  /**
   * Why a request does not match its operation, or undefined when it does.
   * A URL with user info never matches.
   *
   * @private
   */
  private _destinationMismatch(
    call: Call,
    url: URL,
    method: string,
  ): string | undefined {
    if (url.origin !== this.base.origin) {
      return "origin_not_allowed";
    }
    if (method !== call.op.httpMethod) {
      return "method_mismatch";
    }
    if (!call.re.test(url.pathname) || url.username || url.password) {
      return "path_mismatch";
    }
    return undefined;
  }

  /**
   * Step 3: drop agent-supplied credentials (headers and query parameters)
   * and hop-by-hop headers. The URL's credential query parameters are
   * removed in place.
   *
   * @private
   */
  private _stripCredentials(req: BridgeFetchRequest, target: Target): Stripped {
    const headers: Record<string, string> = {};
    const names: string[] = [];
    for (const [k, v] of Object.entries(req.headers ?? {})) {
      const lk = k.toLowerCase();
      if (this._isCredentialHeader(lk)) {
        names.push(lk);
      } else if (!HOP_BY_HOP.has(lk)) {
        headers[k] = String(v);
      }
    }
    for (const name of [...target.url.searchParams.keys()]) {
      if (this.credentialNames.query.has(name.toLowerCase())) {
        target.url.searchParams.delete(name);
        names.push(`query:${name}`);
      }
    }
    return { headers, names };
  }

  /**
   * Whether a (lower-case) header name carries credentials.
   *
   * @private
   */
  private _isCredentialHeader(name: string): boolean {
    return ALWAYS_STRIPPED.has(name) || this.credentialNames.headers.has(name);
  }

  /**
   * Step 4: resolve the operation's security requirement into credentials,
   * record the allowed decision and apply the credentials to the request.
   *
   * @private
   */
  private async _applyCredentials(
    call: Call,
    decision: Decision,
    target: Target,
    stripped: Stripped,
  ): Promise<AppliedSecurity | Refusal> {
    const { ctx, op } = call;
    const strippedCredentials =
      stripped.names.length > 0
        ? { strippedCredentials: stripped.names.slice(0, 10) }
        : {};
    let applied: AppliedSecurity;
    try {
      applied = await resolveSecurity(
        op.security,
        this.opts.schemes,
        this.opts.provider,
        {
          principal: ctx.principal,
          operation: op,
          executionId: ctx.executionId,
          requestId: ctx.requestId,
          logs: ctx.logs,
          signal: call.signal,
        },
      );
    } catch (err) {
      const auth = err instanceof UpstreamAuthError ? err : undefined;
      const reason = auth?.reason ?? "credential_error";
      ctx.logs.audit(
        "credential.lookup_failed",
        "failure",
        {
          ...call.audit,
          ...strippedCredentials,
          provider: this.opts.provider.id,
          reason,
        },
        "warn",
      );
      return this._err({
        type: "upstream_auth_error",
        reason,
        operation: op.id,
        message: auth?.message ?? "Upstream credentials are unavailable",
      });
    }
    ctx.logs.audit(
      "authorization.allowed",
      "allowed",
      {
        ...call.audit,
        ...strippedCredentials,
        policyId: decision.policyId,
        reason: decision.reason,
        provider: this.opts.provider.id,
        schemes: applied.schemes,
        unauthenticated: applied.schemes.length === 0,
      },
      stripped.names.length > 0 ? "warn" : "info",
    );
    for (const [k, v] of Object.entries(applied.query)) {
      target.url.searchParams.set(k, v);
    }
    Object.assign(stripped.headers, applied.headers);
    target.headers = stripped.headers;
    return applied;
  }

  /**
   * Step 5: decode the request body and enforce its size limit.
   *
   * @private
   */
  private _body(call: Call, req: BridgeFetchRequest): Body | Refusal {
    if (req.body === null || req.body === undefined) {
      return undefined;
    }
    const body =
      req.bodyEncoding === "base64"
        ? Buffer.from(req.body, "base64")
        : req.body;
    const size =
      typeof body === "string" ? Buffer.byteLength(body) : body.byteLength;
    const limit = this.opts.network.maxRequestBytes;
    if (size <= limit) {
      return body;
    }
    call.ctx.logs.audit(
      "execution.resource_limit",
      "denied",
      { ...call.audit, limit: "maxRequestBytes", value: limit },
      "warn",
    );
    return this._err({
      type: "resource_limit",
      reason: "request_too_large",
      message: `Request body exceeds ${limit} bytes`,
    });
  }

  /**
   * Step 6: send the request, following only redirects the network policy
   * permits, within the upstream timeout.
   *
   * @private
   */
  private async _send(
    call: Call,
    request: Target & { body: Body },
    applied: AppliedSecurity,
  ): Promise<Sent | Refusal> {
    const started = Date.now();
    const timeout = AbortSignal.timeout(this.opts.network.timeoutMs);
    const signal = AbortSignal.any([call.signal, timeout]);
    const fetchImpl = this.opts.fetchImpl ?? fetch;
    const current = { ...request };
    try {
      for (let hop = 0; ; hop++) {
        const response = await fetchImpl(current.url, {
          method: current.method,
          headers: current.headers,
          body: current.body as RequestInit["body"],
          redirect: "manual",
          signal,
        });
        const next = _redirectLocation(response, current.url);
        if (!next) {
          return { response, started };
        }
        await response.body?.cancel();
        const refused = this._checkRedirect(call, next, hop, current.method);
        if (refused) {
          return refused;
        }
        this._followRedirect(call, current, response.status, next, applied);
      }
    } catch (err) {
      return this._unreachable(call, err, timeout, started);
    }
  }

  /**
   * Refuse a redirect the network policy does not permit.
   *
   * @private
   */
  private _checkRedirect(
    call: Call,
    next: URL,
    hop: number,
    method: string,
  ): Refusal | undefined {
    const network = this.opts.network;
    const reason = !network.followRedirects
      ? "redirects_disabled"
      : hop >= network.maxRedirects
        ? "too_many_redirects"
        : !/^https?:$/.test(next.protocol) ||
            !this.allowedOrigins.has(next.origin)
          ? "origin_not_allowed"
          : undefined;
    if (!reason) {
      return undefined;
    }
    call.ctx.logs.audit(
      "network.redirect_denied",
      "denied",
      {
        operation: call.op.id,
        httpMethod: method,
        pathTemplate: call.op.path,
        destinationOrigin: next.origin,
        reason,
      },
      "warn",
    );
    return this._err({
      type: "permission_denied",
      reason: "redirect_denied",
      operation: call.op.id,
      message: `The API redirected to ${next.origin}, which the network policy does not allow`,
    });
  }

  /**
   * Prepare the request for a permitted redirect: never forward credentials
   * to another origin, and turn the request into a GET where HTTP says so.
   *
   * @private
   */
  private _followRedirect(
    call: Call,
    current: Target & { body: Body },
    status: number,
    next: URL,
    applied: AppliedSecurity,
  ): void {
    call.ctx.logs.op("debug", "upstream.call.redirected", {
      operation: call.op.id,
      status,
      sameOrigin: next.origin === this.base.origin,
    });
    if (next.origin !== this.base.origin) {
      current.headers = Object.fromEntries(
        Object.entries(current.headers ?? {}).filter(
          ([k]) => !this._isCredentialHeader(k.toLowerCase()),
        ),
      );
      for (const name of Object.keys(applied.query)) {
        next.searchParams.delete(name);
      }
    }
    if (
      status === 303 ||
      ((status === 301 || status === 302) && current.method === "POST")
    ) {
      current.method = "GET";
      current.body = undefined;
    }
    current.url = next;
  }

  /**
   * Report a request that failed before any response: timeout, end of the
   * execution, or a network error.
   *
   * @private
   */
  private _unreachable(
    call: Call,
    err: unknown,
    timeout: AbortSignal,
    started: number,
  ): Refusal {
    const timedOut = timeout.aborted && !call.signal.aborted;
    call.ctx.logs.op("warn", "upstream.call.failed", {
      operation: call.op.id,
      httpMethod: call.op.httpMethod,
      pathTemplate: call.op.path,
      durationMs: Date.now() - started,
      reason: timedOut
        ? "timeout"
        : call.signal.aborted
          ? "execution_ended"
          : "network_error",
      error: sanitizeError(err).name,
    });
    return this._err({
      type: "upstream_unreachable",
      reason: timedOut ? "upstream_timeout" : "network_error",
      operation: call.op.id,
      message: timedOut
        ? `The API did not respond within ${this.opts.network.timeoutMs} ms`
        : "The API could not be reached",
    });
  }

  /**
   * Discard cached OAuth tokens the API rejected, so the next call obtains
   * a new one.
   *
   * @private
   */
  private _invalidateRejected(
    call: Call,
    response: Response,
    applied: AppliedSecurity,
  ): void {
    if (response.status !== 401) {
      return;
    }
    for (const s of applied.schemes) {
      if (this.opts.schemes[s]?.type === "oauth2") {
        this.opts.provider.invalidate(s, {
          principal: call.ctx.principal,
          operation: call.op,
          logs: call.ctx.logs,
        });
      }
    }
  }

  /**
   * Step 7: read the response within its size limit, without Set-Cookie
   * headers.
   *
   * @private
   */
  private async _readResponse(
    call: Call,
    sent: Sent,
  ): Promise<BridgeFetchResult> {
    const { response, started } = sent;
    const body = await this._readBody(call, response);
    if (_refused(body)) {
      return body;
    }
    const headers: Array<[string, string]> = [];
    response.headers.forEach((v, k) => {
      if (!RESPONSE_STRIPPED.has(k.toLowerCase())) {
        headers.push([k, v]);
      }
    });
    call.ctx.logs.op("info", "upstream.call.completed", {
      operation: call.op.id,
      httpMethod: call.op.httpMethod,
      pathTemplate: call.op.path,
      status: response.status,
      durationMs: Date.now() - started,
      responseBytes: body.byteLength,
      outcome: response.ok ? "success" : "failure",
    });
    return {
      ok: true,
      status: response.status,
      statusText: response.statusText,
      headers,
      body: body.toString("base64"),
    };
  }

  /**
   * Read a response body, refusing it once it exceeds the size limit.
   *
   * @private
   */
  private async _readBody(
    call: Call,
    response: Response,
  ): Promise<Buffer | Refusal> {
    const limit = this.opts.network.maxResponseBytes;
    const chunks: Uint8Array[] = [];
    let total = 0;
    const reader = response.body?.getReader();
    for (let r = await reader?.read(); r && !r.done; r = await reader!.read()) {
      total += r.value.byteLength;
      if (total > limit) {
        await reader!.cancel();
        call.ctx.logs.audit(
          "execution.resource_limit",
          "denied",
          { ...call.audit, limit: "maxResponseBytes", value: limit },
          "warn",
        );
        return this._err({
          type: "resource_limit",
          reason: "response_too_large",
          operation: call.op.id,
          message: `The API response exceeded ${limit} bytes`,
        });
      }
      chunks.push(r.value);
    }
    return Buffer.concat(chunks);
  }
}

/**
 * The next URL of a redirect response, or undefined when the response is
 * not a redirect.
 *
 * @private
 */
function _redirectLocation(response: Response, current: URL): URL | undefined {
  if (!REDIRECT_STATUSES.has(response.status)) {
    return undefined;
  }
  const location = response.headers.get("location");
  return location ? new URL(location, current) : undefined;
}

/**
 * Whether a step refused the request.
 *
 * @private
 */
function _refused(value: unknown): value is Refusal {
  return (
    typeof value === "object" &&
    value !== null &&
    (value as { ok?: unknown }).ok === false
  );
}

"use strict";
/**
 * Upstream API credential providers.
 *
 * A {@link CredentialProvider} (see upstream/types) turns an OpenAPI security scheme into
 * request headers or query parameters on the trusted host side. Agent code
 * never sees provider objects, configuration or credential values.
 *
 * Version one ships {@link ServiceIdentityCredentialProvider}: one
 * explicitly configured upstream identity shared by every MCP caller. The
 * interface receives the request principal so that a future per-caller
 * provider can map MCP principals to their own upstream credentials. MCP
 * access tokens are never forwarded upstream.
 *
 * @module upstream/credentials
 */
import type { UpstreamSchemeConfig } from "../config.js";
import type { SecretResolver } from "../util/secrets.js";
import { OagMcpError } from "../errors.js";
import type { Logs } from "../logging/logger.js";
import { type SecretRegistry, sanitizeError } from "../util/redact.js";
import type { SecuritySchemeInfo } from "../types.js";
import type {
  AppliedCredential,
  CredentialContext,
  CredentialProvider,
} from "./types.js";

/** Error raised when upstream credentials cannot be produced. */
export class UpstreamAuthError extends Error {
  constructor(
    readonly reason: string,
    message: string,
  ) {
    super(message);
    this.name = "UpstreamAuthError";
  }
}

interface CachedToken {
  token: string;
  expiresAt: number;
}

interface ResolvedScheme {
  info: SecuritySchemeInfo;
  config: UpstreamSchemeConfig;
  apiKey?: string;
  username?: string;
  password?: string;
  token?: string;
  clientId?: string;
  clientSecret?: string;
  tokenUrl?: string;
}

/** The supported ways of presenting a credential. */
type SchemeKind = "apiKey" | "basic" | "bearer" | "oauth2";

/** Configuration fields that hold secret references. */
type SecretField =
  "apiKey" | "username" | "password" | "token" | "clientId" | "clientSecret";

/** Audit events of a token request. */
type TokenEvent = "upstream.token.issue" | "upstream.token.refresh";

/** A client credentials token request. */
interface TokenForm {
  headers: Record<string, string>;
  body: URLSearchParams;
}

/** Options for {@link ServiceIdentityCredentialProvider}. */
export interface ServiceIdentityOptions {
  schemes: Record<string, UpstreamSchemeConfig>;
  schemeInfo: Record<string, SecuritySchemeInfo>;
  resolver: SecretResolver;
  registry: SecretRegistry;
  logs: Logs;
  allowInsecureTokenUrl: boolean;
  baseUrl: string;
  fetchImpl?: typeof fetch;
  /** Refresh tokens this many seconds before expiry. */
  refreshSkewSec?: number;
}

/**
 * Whether a URL is safe for sending client secrets.
 *
 * @private
 */
function _secureUrl(u: URL): boolean {
  return (
    u.protocol === "https:" ||
    ["127.0.0.1", "localhost", "[::1]", "::1"].includes(u.hostname)
  );
}

/**
 * How a security scheme presents its credential, when it is supported.
 *
 * @private
 */
function _schemeKind(info: SecuritySchemeInfo): SchemeKind | undefined {
  if (info.type === "apiKey" || info.type === "oauth2") {
    return info.type;
  }
  if (
    info.type === "http" &&
    (info.scheme === "basic" || info.scheme === "bearer")
  ) {
    return info.scheme;
  }
  return undefined;
}

/**
 * The form and headers of a client credentials token request.
 *
 * @private
 */
function _tokenForm(r: ResolvedScheme, scopes: string[]): TokenForm {
  const body = new URLSearchParams({ grant_type: "client_credentials" });
  if (scopes.length > 0) {
    body.set("scope", scopes.join(" "));
  }
  if (r.config.audience) {
    body.set("audience", r.config.audience);
  }
  const headers: Record<string, string> = {
    "content-type": "application/x-www-form-urlencoded",
    accept: "application/json",
  };
  if (
    (r.config.clientAuthMethod ?? "client_secret_basic") ===
    "client_secret_basic"
  ) {
    headers.authorization = `Basic ${Buffer.from(
      `${encodeURIComponent(r.clientId!)}:${encodeURIComponent(r.clientSecret!)}`,
    ).toString("base64")}`;
  } else {
    body.set("client_id", r.clientId!);
    body.set("client_secret", r.clientSecret!);
  }
  return { headers, body };
}

/**
 * A token response's JSON object; empty when the body is not one.
 *
 * @private
 */
async function _readTokenJson(res: Response): Promise<Record<string, unknown>> {
  try {
    const json: unknown = await res.json();
    return json && typeof json === "object" && !Array.isArray(json)
      ? (json as Record<string, unknown>)
      : {};
  } catch {
    return {};
  }
}

/**
 * Why a token response is unusable, if it is.
 *
 * @private
 */
function _tokenRejection(
  res: Response,
  token: string,
  json: Record<string, unknown>,
): string | undefined {
  if (!res.ok) {
    return "token_endpoint_error";
  }
  if (!token) {
    return "no_access_token";
  }
  return String(json.token_type ?? "bearer").toLowerCase() === "bearer"
    ? undefined
    : "unsupported_token_type";
}

/**
 * The token lifetime in seconds, defaulting to five minutes.
 *
 * @private
 */
function _expiresIn(json: Record<string, unknown>): number {
  return typeof json.expires_in === "number" && json.expires_in > 0
    ? json.expires_in
    : 300;
}

/**
 * Single upstream service identity loaded from the configuration.
 */
export class ServiceIdentityCredentialProvider implements CredentialProvider {
  readonly id = "service-identity";
  private readonly resolved = new Map<string, ResolvedScheme>();
  private readonly cache = new Map<string, CachedToken>();
  private readonly inflight = new Map<string, Promise<CachedToken>>();
  private readonly fetchImpl: typeof fetch;
  private readonly skewSec: number;

  /**
   * Validate configuration and resolve all secret references eagerly so
   * misconfiguration fails at startup.
   *
   * @param {Object} opts - options
   */
  constructor(private readonly opts: ServiceIdentityOptions) {
    this.fetchImpl = opts.fetchImpl ?? fetch;
    this.skewSec = opts.refreshSkewSec ?? 30;
    const problems: string[] = [];
    for (const [name, config] of Object.entries(opts.schemes)) {
      const info = opts.schemeInfo[name];
      if (!info) {
        problems.push(`${name}: not a security scheme in the OpenAPI document`);
        continue;
      }
      if (!info.supported) {
        problems.push(`${name}: ${info.unsupportedReason}`);
        continue;
      }
      try {
        this.resolved.set(name, this._resolve(name, info, config));
      } catch (err) {
        problems.push(`${name}: ${(err as Error).message}`);
      }
    }
    if (problems.length > 0) {
      opts.logs.audit(
        "credential.config_invalid",
        "failure",
        { provider: this.id, problems: problems.map((p) => p.split(":")[0]) },
        "error",
      );
      throw new OagMcpError(
        "UPSTREAM_AUTH_CONFIG_INVALID",
        `Invalid upstreamAuth configuration: ${problems.join("; ")}`,
        { hint: "See docs/authentication.md#upstream-api-authentication." },
      );
    }
    opts.logs.audit("credential.provider.configured", "success", {
      provider: this.id,
      schemes: [...this.resolved.keys()],
      sharedIdentity: true,
    });
  }

  /**
   * Resolve configured secrets for one scheme.
   *
   * @private
   */
  private _resolve(
    name: string,
    info: SecuritySchemeInfo,
    config: UpstreamSchemeConfig,
  ): ResolvedScheme {
    const need = (field: SecretField) =>
      this._secret(name, info, config, field);
    const out: ResolvedScheme = { info, config };
    switch (_schemeKind(info)) {
      case "apiKey":
        out.apiKey = need("apiKey");
        break;
      case "basic":
        out.username = need("username");
        out.password = need("password");
        this.opts.registry.add(`${out.username}:${out.password}`);
        break;
      case "bearer":
        out.token = need("token");
        break;
      case "oauth2":
        out.clientId = need("clientId");
        out.clientSecret = need("clientSecret");
        this.opts.registry.add(`${out.clientId}:${out.clientSecret}`);
        out.tokenUrl = this._tokenUrl(info, config);
        break;
    }
    return out;
  }

  /**
   * Resolve one configured secret and register it for scrubbing.
   *
   * @private
   */
  private _secret(
    name: string,
    info: SecuritySchemeInfo,
    config: UpstreamSchemeConfig,
    field: SecretField,
  ): string {
    const ref = config[field];
    if (!ref || typeof ref !== "object" || Array.isArray(ref)) {
      throw new Error(`missing "${field}" for ${info.type} scheme`);
    }
    const v = this.opts.resolver.resolve(ref, `${name}.${field}`);
    this.opts.registry.add(v);
    return v;
  }

  /**
   * The token endpoint, which must be HTTPS or loopback unless allowed.
   *
   * @private
   */
  private _tokenUrl(
    info: SecuritySchemeInfo,
    config: UpstreamSchemeConfig,
  ): string {
    const tokenUrl = new URL(
      config.tokenUrl ?? info.tokenUrl ?? "",
      this.opts.baseUrl,
    );
    if (!_secureUrl(tokenUrl) && !this.opts.allowInsecureTokenUrl) {
      throw new Error(
        `token URL ${tokenUrl.origin} is not HTTPS (set upstreamAuth.allowInsecureTokenUrl only for local testing)`,
      );
    }
    return tokenUrl.toString();
  }

  /** @inheritdoc */
  has(schemeName: string): boolean {
    return this.resolved.has(schemeName);
  }

  /** @inheritdoc */
  async apply(
    scheme: SecuritySchemeInfo,
    scopes: string[],
    ctx: CredentialContext,
  ): Promise<AppliedCredential> {
    const r = this.resolved.get(scheme.name);
    if (!r) {
      throw new UpstreamAuthError(
        "credential_not_configured",
        `No upstream credentials are configured for security scheme "${scheme.name}"`,
      );
    }
    const out: AppliedCredential = { headers: {}, query: {} };
    switch (_schemeKind(scheme)) {
      case "apiKey":
        (scheme.in === "header" ? out.headers : out.query)[scheme.paramName!] =
          r.apiKey!;
        break;
      case "basic":
        out.headers.Authorization = `Basic ${Buffer.from(`${r.username}:${r.password}`).toString("base64")}`;
        break;
      case "bearer":
        out.headers.Authorization = `Bearer ${r.token}`;
        break;
      case "oauth2":
        out.headers.Authorization = `Bearer ${await this._clientCredentialsToken(r, scopes, ctx)}`;
        break;
    }
    return out;
  }

  /**
   * Cache key for a token request.
   *
   * @private
   */
  private _key(scheme: string, scopes: string[]): string {
    return `${scheme} ${[...scopes].sort().join(" ")}`;
  }

  /**
   * Obtain an OAuth2 client credentials token, reusing a cached token until
   * shortly before expiry and de-duplicating concurrent refreshes.
   *
   * @private
   */
  private async _clientCredentialsToken(
    r: ResolvedScheme,
    requiredScopes: string[],
    ctx: CredentialContext,
  ): Promise<string> {
    const scopes = r.config.scopes ?? requiredScopes;
    const key = this._key(r.info.name, scopes);
    const now = Date.now() / 1000;
    const cached = this.cache.get(key);
    if (cached && cached.expiresAt - this.skewSec > now) {
      ctx.logs.op("debug", "upstream.token.cache_hit", {
        scheme: r.info.name,
      });
      return cached.token;
    }
    let pending = this.inflight.get(key);
    if (!pending) {
      pending = this._requestToken(r, scopes, ctx, Boolean(cached)).finally(
        () => this.inflight.delete(key),
      );
      this.inflight.set(key, pending);
    }
    const fresh = await pending;
    return fresh.token;
  }

  /**
   * Request a token from the token endpoint.
   *
   * @private
   */
  private async _requestToken(
    r: ResolvedScheme,
    scopes: string[],
    ctx: CredentialContext,
    isRefresh: boolean,
  ): Promise<CachedToken> {
    const started = Date.now();
    const event: TokenEvent = isRefresh
      ? "upstream.token.refresh"
      : "upstream.token.issue";
    const res = await this._postToken(r, scopes, ctx, event);
    const json = await _readTokenJson(res);
    const token =
      typeof json.access_token === "string" ? json.access_token : "";
    const reason = _tokenRejection(res, token, json);
    if (reason) {
      this._auditTokenFailure(r, ctx, event, {
        status: res.status,
        reason,
        oauthError:
          typeof json.error === "string" ? json.error.slice(0, 64) : undefined,
      });
      throw new UpstreamAuthError(
        "token_request_failed",
        `The OAuth2 token endpoint rejected the client credentials request for "${r.info.name}" (HTTP ${res.status})`,
      );
    }
    const expiresIn = _expiresIn(json);
    const entry = this._storeToken(r, scopes, token, expiresIn);
    ctx.logs.audit(event, "success", {
      scheme: r.info.name,
      provider: this.id,
      expiresInSec: expiresIn,
      scopeCount: scopes.length,
      durationMs: Date.now() - started,
    });
    return entry;
  }

  /**
   * POST the token request, failing clearly when the endpoint is unreachable.
   *
   * @private
   */
  private async _postToken(
    r: ResolvedScheme,
    scopes: string[],
    ctx: CredentialContext,
    event: TokenEvent,
  ): Promise<Response> {
    try {
      return await this.fetchImpl(r.tokenUrl!, {
        method: "POST",
        ..._tokenForm(r, scopes),
        redirect: "error",
        signal: ctx.signal,
      });
    } catch (err) {
      this._auditTokenFailure(r, ctx, event, {
        reason: "token_endpoint_unreachable",
        error: sanitizeError(err).name,
      });
      throw new UpstreamAuthError(
        "token_endpoint_unreachable",
        `Could not reach the OAuth2 token endpoint for "${r.info.name}"`,
      );
    }
  }

  /**
   * Audit a failed token request.
   *
   * @private
   */
  private _auditTokenFailure(
    r: ResolvedScheme,
    ctx: CredentialContext,
    event: TokenEvent,
    fields: Record<string, unknown>,
  ): void {
    ctx.logs.audit(
      `${event}_failed`,
      "failure",
      { scheme: r.info.name, provider: this.id, ...fields },
      "warn",
    );
  }

  /**
   * Cache a fresh token, registering it for scrubbing.
   *
   * @private
   */
  private _storeToken(
    r: ResolvedScheme,
    scopes: string[],
    token: string,
    expiresIn: number,
  ): CachedToken {
    this.opts.registry.add(token);
    const entry = { token, expiresAt: Date.now() / 1000 + expiresIn };
    const key = this._key(r.info.name, scopes);
    const previous = this.cache.get(key);
    this.cache.set(key, entry);
    if (previous) {
      // Keep scrubbing the previous token briefly; in-flight errors may echo it.
      setTimeout(
        () => this.opts.registry.remove(previous.token),
        60000,
      ).unref();
    }
    return entry;
  }

  /** @inheritdoc */
  invalidate(schemeName: string, ctx: CredentialContext): void {
    let removed = 0;
    for (const key of [...this.cache.keys()]) {
      if (key.startsWith(`${schemeName} `)) {
        this.cache.delete(key);
        removed++;
      }
    }
    if (removed > 0) {
      ctx.logs.audit("upstream.token.invalidated", "success", {
        scheme: schemeName,
        provider: this.id,
        reason: "upstream_rejected_credentials",
      });
    }
  }
}

"use strict";
/**
 * Resolve the effective OpenAPI security requirement of an operation into
 * concrete credentials, honouring operation overrides and alternatives, and
 * never silently downgrading to unauthenticated access.
 *
 * @module upstream/security
 */
import type { SecurityRequirement, SecuritySchemeInfo } from "../types.js";
import { UpstreamAuthError } from "./credentials.js";
import type {
  AppliedCredential,
  CredentialContext,
  CredentialProvider,
} from "./types.js";

/** Result of credential resolution. */
export interface ResolvedSecurity extends AppliedCredential {
  /** Scheme names applied; empty when the call is unauthenticated. */
  schemes: string[];
  /** Index of the alternative used, -1 when none was required. */
  alternative: number;
}

/**
 * Choose and apply the first satisfiable security alternative.
 *
 * Alternatives are tried in document order, skipping the empty alternative
 * (`{}`, meaning "no authentication"), which is used only when no
 * authenticated alternative is configured. If the operation requires
 * authentication and no alternative is satisfiable, an error is raised.
 *
 * @param {Array} security - effective requirement alternatives
 * @param {Object} schemes - security scheme info
 * @param {Object} provider - credential provider
 * @param {Object} ctx - credential context
 * @return {Promise} resolved security
 */
export async function resolveSecurity(
  security: SecurityRequirement[],
  schemes: Record<string, SecuritySchemeInfo>,
  provider: CredentialProvider,
  ctx: CredentialContext,
): Promise<ResolvedSecurity> {
  if (security.length === 0) {
    return { headers: {}, query: {}, schemes: [], alternative: -1 };
  }
  const unsupported = new Set<string>();
  const unconfigured = new Set<string>();
  for (let i = 0; i < security.length; i++) {
    const names = Object.keys(security[i]);
    if (names.length === 0) {
      continue;
    }
    const usable = names.every((n) => {
      const s = schemes[n];
      if (!s || !s.supported) {
        unsupported.add(n);
        return false;
      }
      if (!provider.has(n)) {
        unconfigured.add(n);
        return false;
      }
      return true;
    });
    if (!usable) {
      continue;
    }
    const out: ResolvedSecurity = {
      headers: {},
      query: {},
      schemes: names,
      alternative: i,
    };
    for (const n of names) {
      const applied = await provider.apply(schemes[n], security[i][n], ctx);
      Object.assign(out.headers, applied.headers);
      Object.assign(out.query, applied.query);
    }
    return out;
  }
  if (security.some((r) => Object.keys(r).length === 0)) {
    return { headers: {}, query: {}, schemes: [], alternative: -1 };
  }
  if (unconfigured.size === 0 && unsupported.size > 0) {
    throw new UpstreamAuthError(
      "unsupported_scheme",
      `This operation requires security schemes oag-mcp cannot satisfy: ${[...unsupported].join(", ")}`,
    );
  }
  throw new UpstreamAuthError(
    "credential_not_configured",
    `No upstream credentials are configured for this operation; configure one of: ${security
      .map((r) => Object.keys(r).join(" + "))
      .filter(Boolean)
      .join(" | ")} under upstreamAuth.schemes`,
  );
}

"use strict";
/**
 * A counting semaphore with a bounded FIFO wait queue. A released slot is
 * handed directly to the longest-waiting acquirer, so the number of holders
 * never exceeds the limit and new callers cannot overtake queued ones.
 *
 * @module util/semaphore
 */

/**
 * Bounded concurrency gate.
 */
export class Semaphore {
  private active = 0;
  private readonly waiters: Array<() => void> = [];

  /**
   * @param {Number} max - concurrent holders
   * @param {Number} maxQueue - maximum waiting acquirers
   */
  constructor(
    private readonly max: number,
    private readonly maxQueue: number,
  ) {}

  /** Number of slots currently held. */
  get inUse(): number {
    return this.active;
  }

  /**
   * Acquire a slot.
   *
   * @return {Promise} release function, or undefined when the queue is full
   */
  async acquire(): Promise<(() => void) | undefined> {
    if (this.active < this.max) {
      this.active++;
      return this._release();
    }
    if (this.waiters.length >= this.maxQueue) {
      return undefined;
    }
    // The releasing holder hands its slot over directly (see _release), so
    // `active` already counts this waiter when it resumes. Incrementing
    // here instead would let a caller arriving between the release and the
    // resumption take the same slot.
    await new Promise<void>((resolve) => this.waiters.push(resolve));
    return this._release();
  }

  /**
   * Build a one-shot release function.
   *
   * @private
   */
  private _release(): () => void {
    let released = false;
    return () => {
      if (released) {
        return;
      }
      released = true;
      const next = this.waiters.shift();
      if (next) {
        // Transfer the slot: `active` is unchanged, FIFO order is kept.
        next();
      } else {
        this.active--;
      }
    };
  }
}

"use strict";
/**
 * Read oag-mcp log records in either standard format, flattened to the few
 * fields tests check.
 *
 * - Operational records are OpenTelemetry log records (`EventName`,
 *   `Attributes`).
 * - Security audit records are OCSF events (`class_uid`,
 *   `metadata.event_code`).
 */
import fs from "node:fs";

import { otelAttributeName } from "../../lib/logging/otel.js";

type Json = Record<string, unknown>;

/** A log record of either category, flattened. */
export interface LogRecordView {
  category: "operational" | "security_audit";
  /** Stable event name. */
  event: string;
  /**
   * Operational: `oag_mcp.outcome`. Audit: the security control action
   * (`allowed`, `denied`, `modified`) when there is one, otherwise the status
   * (`success`, `failure`).
   */
  outcome?: string;
  requestId?: string;
  executionId?: string;
  principalId?: string;
  /** The record as written. */
  raw: Json;
  /**
   * A logged field by its call-site (camelCase) name, read from where the
   * standard format placed it.
   */
  get(field: string): unknown;
}

/** Where OCSF events place call-site fields other than under `unmapped`. */
const OCSF_FIELDS: Record<string, (raw: Json) => unknown> = {
  operation: (raw) => _obj(raw.api).operation ?? _obj(raw.unmapped).operation,
  policyId: (raw) => _obj(raw.policy).uid,
  reason: (raw) => raw.status_detail,
  errorCode: (raw) => raw.status_code,
  httpMethod: (raw) => _obj(raw.http_request).http_method,
};

function _obj(v: unknown): Json {
  return v && typeof v === "object" ? (v as Json) : {};
}

function _str(v: unknown): string | undefined {
  return typeof v === "string" ? v : undefined;
}

/**
 * Flatten one record.
 *
 * @param {Object} raw - parsed JSON line
 * @return {Object} view
 */
export function viewRecord(raw: Json): LogRecordView {
  if (raw.class_uid !== undefined) {
    const metadata = _obj(raw.metadata);
    const unmapped = _obj(raw.unmapped);
    const action = _str(raw.action);
    return {
      category: "security_audit",
      event: String(metadata.event_code),
      outcome: (action ?? _str(raw.status))?.toLowerCase(),
      requestId: _str(metadata.correlation_uid),
      executionId:
        _str(_obj(_obj(raw.api).request).uid) ??
        _str(_obj(raw.process).uid) ??
        _str(unmapped.executionId),
      principalId:
        _str(_obj(_obj(raw.actor).user).uid) ??
        (raw.class_uid === 3002 ? _str(_obj(raw.user).uid) : undefined),
      raw,
      get: (field) => OCSF_FIELDS[field]?.(raw) ?? _obj(raw.unmapped)[field],
    };
  }
  const attributes = _obj(raw.Attributes);
  return {
    category: "operational",
    event: String(raw.EventName),
    outcome: _str(attributes["oag_mcp.outcome"]),
    requestId: _str(attributes["oag_mcp.request.id"]),
    executionId: _str(attributes["oag_mcp.execution.id"]),
    principalId: _str(attributes["enduser.id"]),
    raw,
    get: (field) => attributes[otelAttributeName(field)],
  };
}

/**
 * Read and flatten every record of a log file.
 *
 * @param {String} file - JSON lines file (missing means no records)
 * @return {Array} views
 */
export function readLogRecords(file: string): LogRecordView[] {
  if (!fs.existsSync(file)) {
    return [];
  }
  return parseLogRecords(fs.readFileSync(file, "utf8"));
}

/**
 * Parse and flatten JSON lines.
 *
 * @param {String} text - JSON lines
 * @return {Array} views
 */
export function parseLogRecords(text: string): LogRecordView[] {
  return text
    .split("\n")
    .filter(Boolean)
    .map((l) => viewRecord(JSON.parse(l) as Json));
}

"use strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { fileURLToPath } from "node:url";

/** Repository root. */
export const ROOT = path.resolve(
  path.dirname(fileURLToPath(import.meta.url)),
  "..",
  "..",
);

/** Fixture directory. */
export const FIXTURES = path.join(ROOT, "test", "fixtures", "petclinic");

export const SPEC = path.join(FIXTURES, "openapi.yaml");
export const SDK_726 = path.join(FIXTURES, "sdk-7.26.0");
export const SDK_VARIANT = path.join(FIXTURES, "sdk-variant-7.26.0");
export const SDK_TGZ = path.join(FIXTURES, "petclinic-sdk-1.2.0.tgz");

/**
 * Create a temporary directory.
 *
 * @param {String} prefix - name prefix
 * @return {String} path
 */
export function tmpDir(prefix = "oag-mcp-test-"): string {
  return fs.mkdtempSync(path.join(os.tmpdir(), prefix));
}

/**
 * Copy a fixture SDK into a temporary directory for mutation.
 *
 * @param {String} src - fixture directory
 * @return {String} copy path
 */
export function copyFixture(src: string): string {
  const dest = path.join(tmpDir(), path.basename(src));
  fs.cpSync(src, dest, { recursive: true });
  return dest;
}

export interface Cache {
  has: (value: any) => boolean;
  set: (key: any, value: any) => void;
  get: (key: any) => any;
}

/**
 * Error thrown when the copier traverses deeper than the configured `maxDepth`.
 *
 * @note
 * Extends `RangeError` for backwards compatibility, since exceeding the maximum depth
 * previously surfaced as a native `RangeError` from stack exhaustion.
 */
export class MaxDepthExceededError extends RangeError {
  readonly maxDepth: number;

  constructor(maxDepth: number) {
    super(`Maximum copy depth of ${String(maxDepth)} exceeded; the value copied is nested too deeply.`);

    this.maxDepth = maxDepth;
    this.name = 'MaxDepthExceededError';
  }
}

// eslint-disable-next-line @typescript-eslint/unbound-method
const toStringFunction = Function.prototype.toString;
// eslint-disable-next-line @typescript-eslint/unbound-method
const toStringObject = Object.prototype.toString;

/**
 * Get an empty version of the object with the same prototype it has.
 */
export function getCleanClone(prototype: any): any {
  if (!prototype) {
    return Object.create(null);
  }

  const Constructor = prototype.constructor;

  if (Constructor === Object) {
    return prototype === Object.prototype ? {} : Object.create(prototype as object | null);
  }

  // 2026-10-10: Prototype constructor properties may contain ordinary data.
  if (typeof Constructor === 'function' && ~toStringFunction.call(Constructor).indexOf('[native code]')) {
    try {
      return new Constructor();
    } catch {
      // Ignore
    }
  }

  return Object.create(prototype as object | null);
}

/**
 * Get the tag of the value passed, so that the correct copier can be used.
 */
export function getTag(value: any): string {
  const stringTag = value[Symbol.toStringTag];

  if (stringTag) {
    return stringTag;
  }

  const type = toStringObject.call(value);

  return type.substring(8, type.length - 1);
}
import { getCleanClone } from './utils.js';
import type { Cache } from './utils.ts';

export type InternalCopier<Value> = (value: Value, state: State) => Value;

export interface State {
  /**
   * The constructor of the value currently being copied, derived from its `prototype`.
   * Used to construct the clone for values that are not plain objects, such as subclasses
   * of `Array` or custom classes.
   *
   * @note
   * This is `undefined` for primitives and for values already present in the `cache`. It is
   * also reassigned for every value copied, so it must be read before any recursive
   * `copier` call is made, not after.
   */
  Constructor: any;
  /**
   * The cache of values already copied, mapping each original to its clone. Copiers should
   * populate it with the clone _before_ copying that value's contents, so that circular
   * references resolve to the clone rather than recursing infinitely.
   */
  cache: Cache;
  /**
   * The copier used for nested values. Call it as `state.copier(value, state)` to deeply
   * copy the contents of the value being copied.
   */
  copier: InternalCopier<any>;
  /**
   * The number of nested objects currently being copied, used to bound traversal of
   * deeply-nested values before the call stack is exhausted.
   *
   * @note
   * This is maintained by the copier itself; custom methods should not modify it.
   */
  depth: number;
  /**
   * The prototype of the value currently being copied, used to create a clone that
   * maintains the original's prototype chain.
   *
   * @note
   * This is `undefined` for primitives and for values already present in the `cache`. It is
   * also reassigned for every value copied, so it must be read before any recursive
   * `copier` call is made, not after.
   */
  prototype: any;
}

// eslint-disable-next-line @typescript-eslint/unbound-method
const { propertyIsEnumerable } = Object.prototype;

/**
 * The shared `%TypedArray%.prototype.slice`, which every typed array inherits.
 *
 * @note
 * This is used instead of the `slice` found on the value itself because subclasses can
 * override it with one that does not copy. `Buffer` is the notable case: its `slice`
 * returns a view over the same memory, so copying through it would alias the original.
 */
const sliceTypedArray = Object.getPrototypeOf(Int8Array.prototype).slice as (
  this: ArrayBufferView,
  start: number,
) => ArrayBufferView;

function copyOwnDescriptor<Value extends object>(
  original: Value,
  clone: Value,
  property: string | symbol,
  state: State,
): void {
  const ownDescriptor = Object.getOwnPropertyDescriptor(original, property) || {
    configurable: true,
    enumerable: true,
    value: original[property as keyof Value],
    writable: true,
  };
  const descriptor =
    ownDescriptor.get || ownDescriptor.set
      ? ownDescriptor
      : {
          configurable: ownDescriptor.configurable,
          enumerable: ownDescriptor.enumerable,
          value: state.copier(ownDescriptor.value, state),
          writable: ownDescriptor.writable,
        };

  try {
    Object.defineProperty(clone, property, descriptor);
  } catch {
    // The above can fail on node in extreme edge cases, so fall back to the loose assignment.
    clone[property as keyof Value] = descriptor.get ? descriptor.get() : descriptor.value;
  }
}

/**
 * Strictly copy all properties contained on the object.
 */
function copyOwnPropertiesStrict<Value extends object>(value: Value, clone: Value, state: State): Value {
  for (const name of Object.getOwnPropertyNames(value)) {
    copyOwnDescriptor(value, clone, name, state);
  }

  for (const symbol of Object.getOwnPropertySymbols(value)) {
    copyOwnDescriptor(value, clone, symbol, state);
  }

  return clone;
}

/**
 * Deeply copy the indexed values in the array.
 */
export function copyArrayLoose(array: any[], state: State) {
  const clone = new state.Constructor();

  // set in the cache immediately to be able to reuse the object recursively
  state.cache.set(array, clone);

  for (let index = 0; index < array.length; ++index) {
    clone[index] = state.copier(array[index], state);
  }

  return clone;
}

/**
 * Deeply copy the indexed values in the array, as well as any custom properties.
 */
export function copyArrayStrict<Value extends any[]>(array: Value, state: State) {
  const clone = new state.Constructor() as Value;

  // set in the cache immediately to be able to reuse the object recursively
  state.cache.set(array, clone);

  return copyOwnPropertiesStrict(array, clone, state);
}

/**
 * Copy the contents of the ArrayBuffer, or of the typed array viewing one.
 */
export function copyArrayBuffer<Value extends ArrayBufferLike | ArrayBufferView>(
  arrayBuffer: Value,
  _state: State,
): Value {
  return ArrayBuffer.isView(arrayBuffer)
    ? (sliceTypedArray.call(arrayBuffer, 0) as Value)
    : (arrayBuffer.slice(0) as Value);
}

/**
 * Create a new Blob with the contents of the original.
 */
export function copyBlob<Value extends Blob>(blob: Value, _state: State): Value {
  return blob.slice(0, blob.size, blob.type) as Value;
}

/**
 * Create a new DataView with the contents of the original.
 */
export function copyDataView<Value extends DataView>(dataView: Value, state: State): Value {
  return new state.Constructor(copyArrayBuffer(dataView.buffer, state), dataView.byteOffset, dataView.byteLength);
}

/**
 * Create a new Date based on the time of the original.
 */
export function copyDate<Value extends Date>(date: Value, state: State): Value {
  return new state.Constructor(date.getTime());
}

/**
 * Copy the time of the original Date, as well as any custom properties.
 */
export function copyDateStrict<Value extends Date>(date: Value, state: State): Value {
  const clone = copyDate(date, state);

  // set in the cache immediately to be able to reuse the object recursively
  state.cache.set(date, clone);

  return copyOwnPropertiesStrict(date, clone, state);
}

/**
 * Deeply copy the keys and values of the original.
 */
export function copyMapLoose<Value extends Map<any, any>>(map: Value, state: State): Value {
  const clone = new state.Constructor() as Value;

  // set in the cache immediately to be able to reuse the object recursively
  state.cache.set(map, clone);

  for (const [key, value] of map) {
    clone.set(key, state.copier(value, state));
  }

  return clone;
}

/**
 * Deeply copy the keys and values of the original, as well as any custom properties.
 */
export function copyMapStrict<Value extends Map<any, any>>(map: Value, state: State) {
  return copyOwnPropertiesStrict(map, copyMapLoose(map, state), state);
}

/**
 * Deeply copy the properties (keys and symbols) and values of the original.
 */
export function copyObjectLoose<Value extends Record<string, any>>(object: Value, state: State): Value {
  const clone = getCleanClone(state.prototype);

  // set in the cache immediately to be able to reuse the object recursively
  state.cache.set(object, clone);

  for (const key of Object.keys(object)) {
    if (key === '__proto__') {
      Object.defineProperty(clone, key, {
        configurable: true,
        enumerable: true,
        value: state.copier(object[key], state),
        writable: true,
      });
    } else {
      clone[key] = state.copier(object[key], state);
    }
  }

  for (const symbol of Object.getOwnPropertySymbols(object)) {
    if (propertyIsEnumerable.call(object, symbol)) {
      clone[symbol] = state.copier((object as any)[symbol], state);
    }
  }

  return clone;
}

/**
 * Deeply copy the properties (keys and symbols) and values of the original, as well
 * as any hidden or non-enumerable properties.
 */
export function copyObjectStrict<Value extends Record<string, any>>(object: Value, state: State): Value {
  const clone = getCleanClone(state.prototype);

  // set in the cache immediately to be able to reuse the object recursively
  state.cache.set(object, clone);

  return copyOwnPropertiesStrict(object, clone, state);
}

/**
 * Create a new primitive wrapper from the value of the original.
 */
export function copyPrimitiveWrapper<
  // Specifically use the object constructor types
  // eslint-disable-next-line @typescript-eslint/no-wrapper-object-types
  Value extends Boolean | Number | String,
>(primitiveObject: Value, state: State): Value {
  return new state.Constructor(primitiveObject.valueOf());
}

/**
 * Create a new RegExp based on the value and flags of the original.
 */
export function copyRegExp<Value extends RegExp>(regExp: Value, state: State): Value {
  const clone = new state.Constructor(regExp.source, regExp.flags) as Value;

  clone.lastIndex = regExp.lastIndex;

  return clone;
}

/**
 * Return the original value (an identity function).
