  // [123]-[125] exclude trailing and leading s-white around a folded break;
  // single-quoted style has no escape that could preserve it.
  if (/[ \t]\n|\n[ \t]/.test(str)) return false

  // A decoded LF is rendered through flow folding. At zero continuation
  // indentation, c-forbidden would terminate the quoted scalar.
  if (!layout.isKey && layout.shiftOfContent === 0) {
    const firstLineBreak = str.indexOf('\n')

    if (firstLineBreak !== -1 &&
        C_FORBIDDEN_CONTENT.test(str.slice(firstLineBreak + 1))) return false
  }

  return true
}

function canUseBlock (layout: ScalarLayout): boolean {
  if (layout.flowOnly || !BLOCK_SCALAR_CONTENT.test(layout.node.value)) return false

  const contentIndent = layout.shiftOfContent - layout.shiftOfParent

  if (contentIndent < 1) return false

  // A leading space requires [163] c-indentation-indicator. Its value is 1-9.
  if (contentIndent > 9 && /^\n* /.test(layout.node.value)) return false

  // Block content starts on its own line, so every zero-indented content line
  // is subject to [206] c-forbidden.
  if (layout.shiftOfContent === 0 && C_FORBIDDEN_CONTENT.test(layout.node.value)) return false

  return true
}

function detectAllowedStyles (layout: ScalarLayout): void {
  // [107] Double-quoted style can express arbitrary strings through escape sequences.
  let mask = setBit(0, SCALAR_STYLE.DOUBLE_QUOTED)

  if (canUsePlain(layout)) mask = setBit(mask, SCALAR_STYLE.PLAIN)
  if (canUseSingleQuoted(layout)) mask = setBit(mask, SCALAR_STYLE.SINGLE_QUOTED)

  if (canUseBlock(layout)) {
    mask = setBit(setBit(mask, SCALAR_STYLE.LITERAL_BLOCK), SCALAR_STYLE.FOLDED_BLOCK)
  }

  layout.allowedStylesMask = mask
}

function renderScalar (layout: ScalarLayout): string {
  switch (layout.style) {
    case SCALAR_STYLE.PLAIN:
      return renderPlain(layout)
    case SCALAR_STYLE.SINGLE_QUOTED:
      return renderSingleQuoted(layout)
    case SCALAR_STYLE.LITERAL_BLOCK:
      return renderLiteralBlock(layout)
    case SCALAR_STYLE.FOLDED_BLOCK:
      return renderFoldedBlock(layout)
    case SCALAR_STYLE.DOUBLE_QUOTED:
      return renderDoubleQuoted(layout)
  }
}

function renderPlain (layout: ScalarLayout): string {
  return encodeFlowBreaks(layout.node.value, layout.shiftOfContent)
}

function renderSingleQuoted (layout: ScalarLayout): string {
  const value = encodeFlowBreaks(layout.node.value, layout.shiftOfContent)
  return `'${value.replace(/'/g, "''")}'`
}

function renderLiteralBlock (layout: ScalarLayout): string {
  const value = layout.node.value

  return '|' + blockHeader(value, layout.shiftOfParent, layout.shiftOfContent) +
    dropEndingNewline(indentString(value, layout.shiftOfContent))
}

function renderFoldedBlock (layout: ScalarLayout): string {
  const value = layout.node.value
  const w = layout.presenterOptions.lineWidth
  let availableWidth = Infinity

  if (w !== -1) {
    availableWidth = Math.max(
      Math.min(w, MIN_SCALAR_CONTENT_WIDTH),
      w - layout.shiftOfContent
    )
  }

  return '>' + blockHeader(value, layout.shiftOfParent, layout.shiftOfContent) +
    dropEndingNewline(indentString(
      foldBlockScalar(value, availableWidth),
      layout.shiftOfContent
    ))
}

function renderDoubleQuoted (layout: ScalarLayout): string {
  return `"${escapeString(layout.node.value)}"`
}

// Flow scalars fold line breaks: a run of k source line breaks reparses to k-1
// literal LF characters. Encode each run of p literal LF characters as p+1
// breaks and indent the following content line.
function encodeFlowBreaks (string: string, shiftOfContent: number): string {
  let nextLF = string.indexOf('\n')
  if (nextLF === -1) return string

  const pad = ' '.repeat(shiftOfContent)
  let result = string.slice(0, nextLF)

  const lineRe = /(\n+)([^\n]*)/g
  lineRe.lastIndex = nextLF
  let match

  while ((match = lineRe.exec(string))) {
    const breaks = match[1].length
    const line = match[2]
    result += '\n'.repeat(breaks + 1) + pad + line
  }

  return result
}

// Indents every line in a string. Empty lines (\n only) are not indented.
function indentString (string: string, spaces: number): string {
  const indent = ' '.repeat(spaces)
  let position = 0
  let result = ''
  const length = string.length

  while (position < length) {
    let line
    const next = string.indexOf('\n', position)

    if (next === -1) {
      line = string.slice(position)
      position = length
    } else {
      line = string.slice(position, next + 1)
      position = next + 1
    }

    if (line.length && line !== '\n') result += indent

    result += line
  }

  return result
}

function needIndentIndicator (string: string): boolean {
  return /^\n* /.test(string)
}

function blockHeader (string: string, shiftOfParent: number, shiftOfContent: number): string {
  const indentIndicator = needIndentIndicator(string)
    ? String(shiftOfContent - shiftOfParent)
    : ''

  // The string '\n' counts as a trailing empty line.
  const clip = string[string.length - 1] === '\n'
  const keep = clip && (string[string.length - 2] === '\n' || string === '\n')
  const chomp = keep ? '+' : (clip ? '' : '-')

  return `${indentIndicator}${chomp}\n`
}

// The presenter adds its own trailing newline.
function dropEndingNewline (string: string): string {
  return string[string.length - 1] === '\n' ? string.slice(0, -1) : string
}

function isMoreIndented (char: string): boolean {
  return char === ' ' || char === '\t'
}

function foldLine (line: string, width: number): string {
  if (line === '' || isMoreIndented(line[0])) return line

  const breakRe = / [^ \t]/g
  let match
  let start = 0
  let end
  let curr = 0
  let next = 0
  let result = ''

  while ((match = breakRe.exec(line))) {
    next = match.index

    if (next - start > width) {
      end = (curr > start) ? curr : next
      result += `\n${line.slice(start, end)}`
      start = end + 1
    }

    curr = next
  }

  result += '\n'

  if (line.length - start > width && curr > start) {
    result += `${line.slice(start, curr)}\n${line.slice(curr + 1)}`
  } else {
    result += line.slice(start)
  }

  return result.slice(1)
}

function foldBlockScalar (string: string, width: number): string {
  const lineRe = /(\n+)([^\n]*)/g

  let nextLF = string.indexOf('\n')
  if (nextLF === -1) nextLF = string.length
  lineRe.lastIndex = nextLF

  let result = foldLine(string.slice(0, nextLF), width)
  let prevMoreIndented = string[0] === '\n' || isMoreIndented(string[0])
  let moreIndented
  let match

  while ((match = lineRe.exec(string))) {
    const prefix = match[1]
    const line = match[2]

    moreIndented = line !== '' && isMoreIndented(line[0])
    result += prefix +
      ((!prevMoreIndented && !moreIndented && line !== '') ? '\n' : '') +
      foldLine(line, width)
    prevMoreIndented = moreIndented
  }

  return result
}

// Characters escaped in Double-Quoted Style:
//
// - the inverse of YAML 1.2.2 [1] c-printable;
// - TAB, LF and CR, which c-printable includes;
// - NEL, NBSP, LS, PS and BOM, which are escaped to make invisible content
//   visible;
// - double quote and backslash, which must be escaped because they have
//   syntactic meaning.
//
// In Unicode mode, the surrogate range matches unpaired surrogates but does not
// match either code unit of a valid surrogate pair.
// https://yaml.org/spec/1.2.2/#rule-c-printable
const CHARACTERS_TO_ESCAPE =
  /["\\\x00-\x1F\x7F-\xA0\u2028\u2029\uD800-\uDFFF\uFEFF\uFFFE\uFFFF]/gu

function escapeCharacter (character: string): string {
  switch (character) {
    case '\x00': return '\\0'
    case '\x07': return '\\a'
    case '\x08': return '\\b'
    case '\x09': return '\\t'
    case '\x0A': return '\\n'
    case '\x0B': return '\\v'
    case '\x0C': return '\\f'
    case '\x0D': return '\\r'
    case '\x1B': return '\\e'
    case '"': return '\\"'
    case '\\': return '\\\\'
    case '\x85': return '\\N'
    case '\xA0': return '\\_'
    case '\u2028': return '\\L'
    case '\u2029': return '\\P'
  }

  const code = character.charCodeAt(0)
  const hex = code.toString(16).toUpperCase()

  if (code <= 0xFF) return `\\x${'0'.repeat(2 - hex.length)}${hex}`

  return `\\u${'0'.repeat(4 - hex.length)}${hex}`
}

function escapeString (string: string): string {
  return string.replace(CHARACTERS_TO_ESCAPE, escapeCharacter)
}

export {
  detectAllowedStyles,
  renderScalar,
  type ScalarLayout,
  type ScalarStyleRule
}
// AST → text. Walks the node `kind`; the scalar machinery (style selection,
// quoting, folding) is driven by node text, not by sniffing a JS value.

import { YAMLException } from '../common/exception.ts'
import { tagNameShort } from '../common/tagname.ts'
import { COLLECTION_STYLE, SCALAR_STYLE } from '../parser/events.ts'
import { type Schema } from '../schema.ts'
import {
  type Node,
  type Document,
  type ScalarNode,
  type SequenceNode,
  type MappingNode
} from './nodes.ts'
import {
  detectAllowedStyles,
  renderScalar,
  type ScalarLayout,
  type ScalarStyleRule
} from './scalar_styler.ts'
import { DEFAULT_SCALAR_STYLE_RULES } from './styler_defaults.ts'

const CHAR_LINE_FEED = 0x0A /* LF */

/** @category AST */
interface PresenterOptions {
  /** Schema used when selecting a safe scalar style. */
  schema: Schema

  /**
   * Indentation width in spaces.
   *
   * @defaultValue `2`
   */
  indent?: number

  /**
   * Does not add an indentation level to array elements when enabled.
   *
   * @defaultValue `false`
   */
  seqNoIndent?: boolean

  /**
   * Allows a nested collection to start on the same line after `-`.
   *
   * @defaultValue `true`
   */
  seqInlineFirst?: boolean

  /**
   * Preferred line width for folding. Unbreakable and more-indented lines may
   * exceed it. Set to `-1` for unlimited width.
   *
   * @defaultValue `80`
   */
  lineWidth?: number

  /**
   * Adds spaces inside flow collection brackets: `{a: 1}` becomes `{ a: 1 }`.
   *
   * @defaultValue `false`
   */
  flowBracketPadding?: boolean

  /**
   * Omits the space after commas in flow collections: `[1, 2]` becomes
   * `[1,2]`.
   *
   * @defaultValue `false`
   */
  flowSkipCommaSpace?: boolean

  /**
   * Omits the space after `:` in flow mappings: `{"a": 1}` becomes `{"a":1}`.
   *
   * This forces `quoteFlowKeys`; otherwise `a:1` would be parsed as a single
   * plain scalar instead of a mapping entry.
   *
   * @defaultValue `false`
   */
  flowSkipColonSpace?: boolean

  /**
   * Quotes flow mapping keys: `{a: 1}` becomes `{"a": 1}`.
   *
   * @defaultValue `false`
   */
  quoteFlowKeys?: boolean

  /**
   * Quoting style to use when a string needs quotes.
   *
   * @defaultValue `'single'`
   */
  quoteStyle?: 'single' | 'double'

  /**
   * Quotes all non-key strings using {@link quoteStyle}.
   *
   * @defaultValue `false`
   */
  forceQuotes?: boolean

  /**
   * Customizes how strings are rendered as plain, quoted, literal, or folded
   * scalars. Rules are applied in array order; providing this option replaces
   * the {@link DEFAULT_SCALAR_STYLE_RULES default rules}.
   *
   * @defaultValue `Object.values(DEFAULT_SCALAR_STYLE_RULES)`
   */
  scalarStyleRules?: readonly ScalarStyleRule[]

  /**
   * Prints an explicit tag before an anchor: `&ref_0 !!set` becomes
   * `!!set &ref_0`.
   *
   * @defaultValue `false`
   */
  tagBeforeAnchor?: boolean
}

const DEFAULT_PRESENTER_OPTIONS: Required<Omit<PresenterOptions, 'schema'>> = {
  indent: 2,
  seqNoIndent: false,
  seqInlineFirst: true,
  lineWidth: 80,
  flowBracketPadding: false,
  flowSkipCommaSpace: false,
  flowSkipColonSpace: false,
  quoteFlowKeys: false,
  quoteStyle: 'single',
  forceQuotes: false,
  scalarStyleRules: Object.keys(DEFAULT_SCALAR_STYLE_RULES)
    .map(name => Reflect.get(DEFAULT_SCALAR_STYLE_RULES, name)),
  tagBeforeAnchor: false
}

interface PresenterState extends Required<PresenterOptions> {
  defaultScalarTagName: string
  openEnded: boolean
}

function nodeTagShort (node: ScalarNode | SequenceNode | MappingNode) {
  return node.tagged ? node.tag : tagNameShort(node.tag)
}

function createPresenterState (options: PresenterOptions): PresenterState {
  const opts = {
    ...DEFAULT_PRESENTER_OPTIONS,
    ...options
  }

  if (opts.flowSkipColonSpace) {
    opts.quoteFlowKeys = true
  }

  return {
    ...opts,
    defaultScalarTagName: opts.schema.defaultScalarTag.tagName,
    openEnded: false
  }
}

function generateNextLine (state: PresenterState, level: number) {
  return `\n${' '.repeat(state.indent * level)}`
}

function scalarLayout (state: PresenterState, node: ScalarNode, parent: Readonly<Node> | null, level: number,
  isKey: boolean, flowOnly: boolean): ScalarLayout {
  const shiftOfParent = level === 0 ? -1 : state.indent * (level - 1)
  const shiftOfContent = state.indent * Math.max(1, level)

  return {
    node,
    parent,
    level,
    isKey,
    flowOnly,
    shiftOfParent,
    shiftOfContent,
    shiftOfFirstLine: level === 0 ? 0 : state.indent * level,
    presenterOptions: state,
    allowedStylesMask: 0,
    style: node.style
  }
}

function writeFlowSequence (state: PresenterState, level: number, node: SequenceNode) {
  let result = ''

  for (let index = 0, length = node.items.length; index < length; index += 1) {
    const item = writeNode(state, level, node.items[index], node, {}).text
    if (index > 0) result += `,${!state.flowSkipCommaSpace ? ' ' : ''}`
    result += item
  }

  const pad = state.flowBracketPadding && node.items.length > 0 ? ' ' : ''
  return `[${pad}${result}${pad}]`
}

function writeBlockSequence (state: PresenterState, level: number, node: SequenceNode, compact: boolean) {
  let result = ''

  for (let index = 0, length = node.items.length; index < length; index += 1) {
    const item = writeNode(state, level + 1, node.items[index], node,
      { block: true, compact: state.seqInlineFirst, isblockseq: true }).text

    if (!compact || result !== '') {
      result += generateNextLine(state, level)
    }

    // No trailing space when the value renders empty (e.g. null → '').
    if (item === '' || CHAR_LINE_FEED === item.charCodeAt(0)) {
      result += '-'
    } else {
      result += '- '
    }

    result += item
  }

  return result
}

function writeFlowMapping (state: PresenterState, level: number, node: MappingNode) {
  let result = ''

  for (const { key, value } of node.items) {
    let pairBuffer = ''
    if (result !== '') pairBuffer += `,${!state.flowSkipCommaSpace ? ' ' : ''}`

    const keyRender = writeNode(state, level, key, node, { iskey: true })
    const keyText = keyRender.text

    const valueText = writeNode(state, level, value, node, {}).text
    // No separating space when the value renders empty (e.g. null → '').
    const sep = state.flowSkipColonSpace || valueText === '' ? '' : ' '

    // An alias or a property-only scalar must be separated from `:` because the
    // colon can otherwise be consumed as part of the alias/anchor/tag name.
    const keyIsBareProps = key.kind === 'scalar' && keyRender.noBody &&
      (key.tagged || key.anchor !== undefined)
    const keyColonSep = key.kind === 'alias' || keyIsBareProps ? ' ' : ''

    pairBuffer += `${keyText}${keyColonSep}:${sep}${valueText}`

    result += pairBuffer
  }

  const pad = state.flowBracketPadding && result !== '' ? ' ' : ''
  return `{${pad}${result}${pad}}`
}

function writeBlockMapping (state: PresenterState, level: number, node: MappingNode, compact: boolean) {
  let result = ''

  for (let index = 0, length = node.items.length; index < length; index += 1) {
    let pairBuffer = ''

    if (!compact || result !== '') {
      pairBuffer += generateNextLine(state, level)
    }

    const { key, value } = node.items[index]

    // A block key — a block collection (mapping/sequence) or a block scalar
    // (literal/folded) — can't sit on a `key:` line, so it's written with block
    // context and the pair takes the explicit `? key / : value` form. A simple
    // scalar key stays inline (flow-vs-block is invisible there).
    const keyIsBlock =
      ((key.kind === 'mapping' || key.kind === 'sequence') &&
        key.style === COLLECTION_STYLE.BLOCK && key.items.length !== 0) ||
      (key.kind === 'scalar' &&
        (key.style === SCALAR_STYLE.LITERAL_BLOCK || key.style === SCALAR_STYLE.FOLDED_BLOCK))

    // The `?`/`:` indicators shift content right like a `-`, so a block key or
    // value that stays on the indicator line keeps its indentation under
    // seqNoIndent (`isblockseq`). One that drops to its own line (tag/anchor)
    // collapses to the parent indent, so leave the flag off there.
    const keyRender = keyIsBlock
      ? writeNode(state, level + 1, key, node,
        { block: true, compact: true, isblockseq: !cannotBeCompact(state, key, level + 1) })
      : writeNode(state, level + 1, key, node, { block: true, compact: true, iskey: true })
    const keyText = keyRender.text

    // Block key, over-long key, or multiline scalar key forces explicit form.
    // Multiline isn't a spec requirement — just matches pyyaml's simple-key rule.
    const keyHasLineBreak = key.kind === 'scalar' && key.value.indexOf('\n') !== -1

    // YAML limits an implicit key to 1024 Unicode code points. `length` counts
    // UTF-16 code units, never fewer than code points, so it is a cheap safe
    // precheck. The `u` regexp then counts each [\s\S] match as one code point.
    const keyIsTooLong = keyText.length > 1024 && /^[\s\S]{1025}/u.test(keyText)
    const explicitPair = keyIsBlock || keyHasLineBreak || keyIsTooLong

    if (explicitPair) {
      if (keyText && CHAR_LINE_FEED === keyText.charCodeAt(0)) {
        pairBuffer += '?'
      } else {
        pairBuffer += '? '
      }
    }

    pairBuffer += keyText

    if (explicitPair) {
      pairBuffer += generateNextLine(state, level)
    }

    const valueText = writeNode(state, level + 1, value, node,
      { block: true, compact: explicitPair, isblockseq: explicitPair && !cannotBeCompact(state, value, level + 1) }).text

    // Keep a space before the colon when the key text ends in a leading
    // property rather than scalar content, so the colon can't be read as part
    // of it. Two cases: an inline alias key (`*b : v`), and an empty scalar key
    // whose whole text is its anchor/tag (`&a :`, `!!str :`) — without the
    // space `&a:` reparses as an anchored value, dropping the null key.
    const keyIsBareProps = key.kind === 'scalar' && keyRender.noBody &&
      (key.tagged || key.anchor !== undefined)
    const keyColonSep = !explicitPair && (key.kind === 'alias' || keyIsBareProps) ? ' ' : ''

    // No trailing space when the value renders empty (e.g. null → '').
    if (valueText === '' || CHAR_LINE_FEED === valueText.charCodeAt(0)) {
      pairBuffer += `${keyColonSep}:`
    } else {
      pairBuffer += `${keyColonSep}: `
    }

    pairBuffer += valueText

    result += pairBuffer
  }

  return result
}

// Where a node sits relative to its parent — drives layout/style decisions.
// All flags default to false (the flow-context, non-key, non-compact case).
interface NodeContext {
  block?: boolean      // block context (vs flow); propagates downward
  compact?: boolean    // may start on the current line (no leading newline)
  iskey?: boolean      // node is a mapping key
  isblockseq?: boolean // content follows an indicator (`-`, or `?`/`:` in an
                       // explicit pair) that already shifted it right; keeps
                       // its indentation under seqNoIndent
}

interface NodeRender {
  text: string
  noBody: boolean
}

// A node can't sit compact on its parent's indicator (`-`/`?`/`:`) line when it
// carries leading props (tag/anchor) that would collide with the indicator, or
// when the indent step is too narrow for the 2-char indicator. Such a node drops
// to its own line; a block collection that does so also collapses its seqNoIndent
// indentation back to the parent.
function cannotBeCompact (state: PresenterState, node: Node, level: number) {
  if (node.kind === 'alias') return true
  return node.tagged || node.anchor !== undefined || (state.indent < 2 && level > 0)
}

function writeNode (state: PresenterState, level: number, node: Node,
  parent: Readonly<Node> | null, ctx: NodeContext): NodeRender {
  if (node.kind === 'alias') {
    state.openEnded = false
    return { text: `*${node.anchor}`, noBody: false }
  }

  const { block = false, iskey = false, isblockseq = false } = ctx
  let compact = ctx.compact ?? false

  const hasAnchor = node.anchor !== undefined

  if (cannotBeCompact(state, node, level)) {
    compact = false
  }

  let body: string
  let shouldPrintTag = node.tagged
  const useBlockCollection = block &&
    (node.kind === 'mapping' || node.kind === 'sequence') &&
    node.style === COLLECTION_STYLE.BLOCK && node.items.length !== 0

  if (node.kind === 'mapping') {
    if (useBlockCollection) {
      body = writeBlockMapping(state, level, node, compact)
    } else {
      body = writeFlowMapping(state, level, node)
    }
  } else if (node.kind === 'sequence') {
    if (useBlockCollection) {
      if (state.seqNoIndent && !isblockseq && level > 0) {
        body = writeBlockSequence(state, level - 1, node, compact)
      } else {
        body = writeBlockSequence(state, level, node, compact)
      }
    } else {
      body = writeFlowSequence(state, level, node)
    }
  } else {
    const layout = scalarLayout(state, node, parent, level, iskey, !block)

    detectAllowedStyles(layout)
    for (const rule of state.scalarStyleRules) rule(layout)

    body = renderScalar(layout)
    state.openEnded =
      (layout.style === SCALAR_STYLE.LITERAL_BLOCK || layout.style === SCALAR_STYLE.FOLDED_BLOCK) &&
      (node.value === '\n' || node.value.endsWith('\n\n'))

    // A flow sequence entry cannot be completely empty. Print the semantic tag
    // as the node property that explicitly indicates the entry's existence.
    shouldPrintTag = node.tagged ||
      (body === '' && layout.flowOnly && parent?.kind === 'sequence' && !hasAnchor) ||
      (layout.style !== SCALAR_STYLE.PLAIN && node.tag !== state.defaultScalarTagName)
  }

  // A flow collection ends with its closing indicator, not with its last child.
  if ((node.kind === 'mapping' || node.kind === 'sequence') && !useBlockCollection) {
    state.openEnded = false
  }

  // An indicator plus its mandatory separator occupies 2 columns. For wider
  // indentation, pad a compact block collection so its first item starts at
  // the same column as the following items.
  if (useBlockCollection && compact && level > 0 && state.indent > 2) {
    body = `${' '.repeat(state.indent - 2)}${body}`
  }

  const noBody = body === ''
  let text = body

  if (shouldPrintTag || hasAnchor) {
    const props: string[] = []
    const tag = shouldPrintTag ? nodeTagShort(node) : null
    const anchor = hasAnchor ? `&${node.anchor}` : null

    if (state.tagBeforeAnchor) {
      if (tag !== null) props.push(tag)
      if (anchor !== null) props.push(anchor)
    } else {
      if (anchor !== null) props.push(anchor)
      if (tag !== null) props.push(tag)
    }

    // No separator when the body is empty (e.g. `&anchor` on a null node) or
    // already starts on its own line.
    const sep = body === '' || body.charCodeAt(0) === CHAR_LINE_FEED ? '' : ' '
    text = `${props.join(' ')}${sep}${body}`
  }

  return { text, noBody }
}

// A bare (untagged, unanchored) non-empty block collection: writeNode renders it
// in compact form with its first item on the opening line. That works mid-stream,
// but right after a `---` the first item must drop to the next line. A tag/anchor
// already forces the body onto its own line, so those stay on the `---` line.
function rootStartsOwnLine (node: Node) {
  return (node.kind === 'sequence' || node.kind === 'mapping') &&
    node.style === COLLECTION_STYLE.BLOCK &&
    node.items.length !== 0 &&
    !node.tagged &&
    node.anchor === undefined
}

function writeDocumentDirectives (doc: Document) {
  let result = ''

  for (const directive of doc.directives) {
    if (directive.kind === 'yaml') {
      result += `%YAML ${directive.version}\n`
      continue
    }

