    visit(documents, node => {
    if (node.kind !== 'mapping') return

    node.items.sort((a, b) => compareFn(
      a.key.kind === 'scalar' ? a.key.value : '',
      b.key.kind === 'scalar' ? b.key.value : ''
    ))
