/** Logs writing to a throwaway file so tests stay quiet. */
export function quietLogs(): {
  logs: Logs;
  file: string;
  records: () => LogRecordView[];
} {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "oag-mcp-quiet-"));
  const file = path.join(dir, "all.log");
  const logs = new Logs({ file, auditFile: file, level: "debug" });
  return {
    logs,
    file,
    records: () => readLogRecords(file),
  };
}

/** Security schemes matching the fixture spec. */
export const SCHEMES: Record<string, SecuritySchemeInfo> = {
  apiKeyHeader: {
    name: "apiKeyHeader",
    type: "apiKey",
    in: "header",
    paramName: "X-Api-Key",
    supported: true,
  },
  apiKeyQuery: {
    name: "apiKeyQuery",
    type: "apiKey",
    in: "query",
    paramName: "api_key",
    supported: true,
  },
  bearerAuth: {
    name: "bearerAuth",
    type: "http",
    scheme: "bearer",
    supported: true,
  },
  adminBasic: {
    name: "adminBasic",
    type: "http",
    scheme: "basic",
    supported: true,
  },
  clinicOAuth: {
    name: "clinicOAuth",
    type: "oauth2",
    flows: ["clientCredentials"],
    tokenUrl: "http://127.0.0.1:4011/token",
    scopes: ["pets:write"],
    supported: true,
  },
  oidc: {
    name: "oidc",
    type: "openIdConnect",
    supported: false,
    unsupportedReason: "nope",
  },
};

/** A scripted fetch that records calls. */
export function fakeFetch(
  handler: (url: URL, init: RequestInit) => Response | Promise<Response>,
): typeof fetch & { calls: Array<{ url: URL; init: RequestInit }> } {
  const calls: Array<{ url: URL; init: RequestInit }> = [];
  const fn = (async (input: string | URL | Request, init: RequestInit = {}) => {
    const url = new URL(String(input instanceof Request ? input.url : input));
    calls.push({ url, init });
    return handler(url, init);
  }) as typeof fetch & { calls: typeof calls };
  fn.calls = calls;
  return fn;
}

"use strict";
import fs from "node:fs";
import path from "node:path";

import referee from "@sinonjs/referee";

import { AgentTypeChecker } from "../../lib/executor/typecheck.js";
import { copyTsLibs } from "../../lib/prepare/bundle.js";
import { tmpDir } from "../helpers/paths.js";

const { assert } = referee;

const BINDING = `/// <reference path="./missing.d.ts" />
import type { Pet } from "petlib";
declare global {
  const sdk: {
    PetsApi: { listPets(req?: { limit?: number }): Promise<Pet[]> };
  };
}
`;

/** An sdk/ directory with a binding, a typed package and the TS libs. */
function sdkDir(): { dir: string; libDir: string } {
  const dir = tmpDir();
  fs.writeFileSync(path.join(dir, "sdk-binding.d.ts"), BINDING);
  const pkg = path.join(dir, "node_modules", "petlib");
  fs.mkdirSync(pkg, { recursive: true });
  fs.writeFileSync(
    path.join(pkg, "package.json"),
    JSON.stringify({ name: "petlib", types: "index.d.ts" }),
  );
  fs.writeFileSync(
    path.join(pkg, "index.d.ts"),
    "export interface Pet { name: string; vaccinated: boolean }\n",
  );
  const libDir = path.join(dir, "ts-lib");
  copyTsLibs(libDir);
  return { dir, libDir };
}

describe("typecheck - AgentTypeChecker", function () {
  this.timeout(30000);
  let checker: AgentTypeChecker;

  before(function () {
    const { dir, libDir } = sdkDir();
    checker = new AgentTypeChecker(dir, libDir);
    checker.warmUp();
  });

  it("should accept code that uses the sdk binding correctly", function () {
    assert.equals(
      checker.check(
        "const pets = await sdk.PetsApi.listPets({ limit: 5 });\nreturn pets.filter((p) => p.vaccinated).map((p) => p.name);",
      ),
      [],
    );
  });

  it("should report type errors in the agent's own coordinates", function () {
    const [d, ...rest] = checker.check(
      "const pets = await sdk.PetsApi.listPets();\nreturn pets[0].age;",
    );
    assert.equals(rest, []);
    assert.equals(d.line, 2);
    assert.equals(d.code, 2339);
    assert.match(d.message, /Property 'age' does not exist on type 'Pet'/);
  });

  it("should report syntax errors and check each version of the code afresh", function () {
    assert.greater(checker.check("return (;").length, 0);
    assert.equals(checker.check("return 1;"), []);
  });

  it("should report at most ten errors", function () {
    const code = Array.from({ length: 15 }, (_, i) => `sdk.Nope${i}();`).join(
      "\n",
    );
    assert.equals(checker.check(code).length, 10);
  });
});

"use strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import tty from "node:tty";

import referee from "@sinonjs/referee";
import sinon from "sinon";

import { Logs, MAX_WRITE_RETRIES } from "../../lib/logging/logger.js";
import { OCSF_VERSION } from "../../lib/logging/ocsf.js";
import { secrets } from "../../lib/util/redact.js";
import { oagMcpVersion } from "../../lib/util/version.js";
import { readLogRecords } from "../helpers/log-records.js";

const { assert, refute, match } = referee;

// eslint-disable-next-line @typescript-eslint/no-explicit-any -- parsed JSON
function readJsonLines(file: string): Array<Record<string, any>> {
  return fs
    .readFileSync(file, "utf8")
    .split("\n")
    .filter(Boolean)
    .map((l) => JSON.parse(l));
}

describe("logger - Logs", function () {
  beforeEach(function () {
    this.dir = fs.mkdtempSync(path.join(os.tmpdir(), "oag-mcp-logs-"));
  });

  afterEach(function () {
    sinon.restore();
    fs.rmSync(this.dir, { recursive: true, force: true });
  });

  it("should write OpenTelemetry operational records and OCSF audit records to separate destinations when configured", function () {
    const op = path.join(this.dir, "op.log");
    const audit = path.join(this.dir, "audit.log");
    const logs = new Logs({ file: op, auditFile: audit, instanceId: "inst-1" });
    logs.op("info", "server.ready", { transport: "stdio", methods: 3 });
    logs.audit(
      "authorization.denied",
      "denied",
      {
        operation: "PetsApi.listPets",
        httpMethod: "GET",
        policyId: "p1",
        reason: "default_deny",
      },
      "warn",
    );
    logs.flush();
    const [opRecord, ...moreOp] = readJsonLines(op);
    const [auditRecord, ...moreAudit] = readJsonLines(audit);
    assert.equals(moreOp.length + moreAudit.length, 0);

    // OpenTelemetry Logs Data Model.
    assert.equals(opRecord.SeverityText, "INFO");
    assert.equals(opRecord.SeverityNumber, 9);
    assert.match(opRecord.Timestamp, /^\d{19}$/);
    assert.equals(opRecord.Resource, {
      "service.name": "oag-mcp",
      "service.version": oagMcpVersion(),
      "service.instance.id": "inst-1",
    });
    assert.equals(opRecord.InstrumentationScope, {
      Name: "oag-mcp.operational",
      Version: oagMcpVersion(),
    });
    assert.equals(opRecord.EventName, "server.ready");
    assert.equals(opRecord.Body, "server.ready");
    assert.equals(opRecord.Attributes, {
      "network.transport": "pipe",
      "oag_mcp.methods": 3,
    });

    // OCSF API Activity: Read, denied.
    assert.equals(auditRecord.class_uid, 6003);
    assert.equals(auditRecord.category_uid, 6);
    assert.equals(auditRecord.activity_id, 2);
    assert.equals(auditRecord.type_uid, 600302);
    assert.equals(auditRecord.severity_id, 2);
    assert.equals(auditRecord.status_id, 2);
    assert.equals(auditRecord.status_detail, "default_deny");
    assert.equals(auditRecord.action_id, 2);
    assert.equals(auditRecord.policy, { uid: "p1" });
    assert.equals(auditRecord.api, match({ operation: "PetsApi.listPets" }));
    assert.isNumber(auditRecord.time);
    assert.equals(auditRecord.message, "authorization.denied");
    assert.equals(
      auditRecord.metadata,
      match({
        version: OCSF_VERSION,
        event_code: "authorization.denied",
        product: match({ name: "oag-mcp", version: oagMcpVersion() }),
        reporter: match({ uid: "inst-1" }),
      }),
    );
    assert.isUndefined(auditRecord.level);
  });

  it("should write both categories to one stream when only one destination is given", function () {
    const file = path.join(this.dir, "all.log");
    const logs = new Logs({ file, auditFile: file });
    logs.op("info", "a.event");
    logs.audit("execution.requested", "accepted");
    assert.equals(
      readLogRecords(file).map((r) => r.category),
      ["operational", "security_audit"],
    );
  });

  it("should keep audit records when the operational level suppresses everything", function () {
    const op = path.join(this.dir, "op.log");
    const audit = path.join(this.dir, "audit.log");
    const logs = new Logs({ level: "silent", file: op, auditFile: audit });
    logs.op("error", "should.not.appear");
    logs.audit("authentication.failed", "failure", { reason: "invalid_token" });
    assert.equals(fs.existsSync(op) ? fs.readFileSync(op, "utf8") : "", "");
    assert.equals(readLogRecords(audit)[0].event, "authentication.failed");
  });

  it("should carry child context fields into every record", function () {
    const file = path.join(this.dir, "all.log");
    const logs = new Logs({ file, auditFile: file }).child({
      requestId: "req_1",
      executionId: "exec_1",
      principalId: "local:test",
    });
    logs.op("info", "execution.started");
    logs.audit("authorization.allowed", "allowed", { operation: "X.y" });
    for (const r of readLogRecords(file)) {
      assert.equals(r.requestId, "req_1", r.category);
      assert.equals(r.executionId, "exec_1", r.category);
      assert.equals(r.principalId, "local:test", r.category);
    }
  });

  it("should keep fields that neither standard defines, namespaced or unmapped", function () {
    const file = path.join(this.dir, "all.log");
    const logs = new Logs({ file, auditFile: file });
    logs.op("info", "prepare.stage.completed", { stage: "sdk", durationMs: 5 });
    logs.audit("execution.capability_denied", "denied", { capability: "net" });
    const [op, audit] = readJsonLines(file);
    assert.equals(op.Attributes, {
      "oag_mcp.stage": "sdk",
      "oag_mcp.duration_ms": 5,
    });
    assert.equals(audit.unmapped, { capability: "net" });
  });

  it("should redact registered secrets and sensitive keys from records", function () {
    const file = path.join(this.dir, "all.log");
    secrets.add("logger-test-secret-value");
    const logs = new Logs({ file, auditFile: file });
    logs.op("info", "test.event", {
      note: "contains logger-test-secret-value",
      headers: { authorization: "Bearer logger-test-secret-value" },
      url: "https://x.test/?api_key=abc12345",
    });
    const text = fs.readFileSync(file, "utf8");
    refute.contains(text, "logger-test-secret-value");
    refute.contains(text, "abc12345");
  });

  it("should censor credential keys at any depth and in any case when values are not registered", function () {
    const file = path.join(this.dir, "keys.log");
    const logs = new Logs({ file, auditFile: file });
    const keys = [
      "authorization",
      "Authorization",
      "cookie",
      "password",
      "token",
      "accessToken",
      "access_token",
      "refresh_token",
      "clientSecret",
      "client_secret",
      "apiKey",
      "X-Api-Key",
    ];
    const values = Object.fromEntries(keys.map((k) => [k, `plain-${k}-value`]));
    logs.op("info", "test.keys", {
      ...values,
      headers: { ...values },
      deep: { a: { b: { ...values } } },
    });
    logs.audit("execution.requested", "accepted", {
      request: { headers: values },
    });
    const text = fs.readFileSync(file, "utf8");
    for (const k of keys) {
      refute.contains(text, `plain-${k}-value`, k);
    }
    assert.contains(text, "[REDACTED]");
  });

  it("should report audit destination failure and block execution when fail-closed", function () {
    const logs = new Logs({
      file: path.join(this.dir, "op.log"),
      auditFile: "fd:99",
      auditFailClosed: true,
    });
    const ok = logs.audit("execution.requested", "accepted");
    assert.isFalse(ok);
    assert.isFalse(logs.auditHealthy);
    assert.isTrue(logs.auditBlocksExecution());
  });

  it("should not block execution on audit failure when fail-closed is off", function () {
    const logs = new Logs({
      file: path.join(this.dir, "op.log"),
      auditFile: "fd:99",
    });
    logs.audit("execution.requested", "accepted");
    assert.isFalse(logs.auditHealthy);
    assert.isFalse(logs.auditBlocksExecution());
  });

  it("should retry a full non-blocking destination a bounded number of times, then fail fast, and write the backlog once it drains", function () {
    // sonic-boom waits 100 ms between retries, so the first record takes ~2 s.
    this.timeout(15000);
    const file = path.join(this.dir, "audit.log");
    const logs = new Logs({
      file: path.join(this.dir, "op.log"),
      auditFile: file,
      auditFailClosed: true,
    });
    // Simulate a full non-blocking pipe for audit writes: every attempt fails
    // with EAGAIN until the reader "drains" it.
    const writeSync = fs.writeSync;
    let busy = true;
    let attempts = 0;
    sinon.stub(fs, "writeSync").callsFake(((
      fd: number,
      data: string,
      ...rest: never[]
    ) => {
      if (busy && fd !== 2 && String(data).includes('"class_uid"')) {
        attempts++;
        throw Object.assign(new Error("busy"), { code: "EAGAIN" });
      }
      return writeSync(fd, data, ...rest);
    }) as typeof fs.writeSync);

    // First record: the first attempt plus MAX_WRITE_RETRIES retries.
    assert.isFalse(logs.audit("execution.requested", "accepted", { n: 1 }));
    assert.equals(attempts, MAX_WRITE_RETRIES + 1);
    assert.isTrue(logs.auditBlocksExecution());

    // While still busy, later records fail fast instead of waiting again.
    attempts = 0;
    const started = performance.now();
    assert.isFalse(logs.audit("execution.requested", "accepted", { n: 2 }));
    assert.equals(attempts, 1);
    assert.less(performance.now() - started, 90);

    // Once the reader drains the pipe, the backlog is written in order.
    busy = false;
    assert.isTrue(logs.audit("execution.requested", "accepted", { n: 3 }));
    assert.equals(
      readLogRecords(file).map((r) => r.get("n")),
      [1, 2, 3],
    );
    // Fail-closed stays in force once an audit record has failed.
    assert.isTrue(logs.auditBlocksExecution());
  });

  it("should not hang when flushing or logging fatal records to a destination that keeps failing", function () {
    // pino flushes the destination after every fatal record; with a
    // persistent error (here EBADF) that must give up, not retry forever.
    const logs = new Logs({ file: "fd:99", auditFile: "fd:98" });
    logs.op("fatal", "test.fatal");
    logs.audit("security.config_invalid", "failure", {}, "error");
    logs.flush();
    assert.isFalse(logs.auditHealthy);
  });

  it("should count write failures in pretty format for fail-closed auditing", function () {
    const logs = new Logs({ format: "pretty", auditFailClosed: true });
    const writeSync = fs.writeSync;
    sinon.stub(fs, "writeSync").callsFake(((
      fd: number,
      data: string,
      ...rest: never[]
    ) => {
      if (fd === 2) {
        throw Object.assign(new Error("stderr gone"), { code: "EIO" });
      }
      return writeSync(fd, data, ...rest);
    }) as typeof fs.writeSync);
    assert.isFalse(logs.audit("execution.requested", "accepted"));
    assert.isTrue(logs.auditBlocksExecution());
  });

  it("should treat an unopenable audit file as a failure", function () {
    const logs = new Logs({
      auditFile: path.join(this.dir, "missing-dir", "audit.log"),
      auditFailClosed: true,
    });
    assert.isTrue(logs.auditBlocksExecution());
  });

  it("should refuse stdout as a destination", function () {
    assert.exception(() => new Logs({ file: "stdout" }), {
      message: /stdout is reserved/,
    });
    assert.exception(() => new Logs({ auditFile: "fd:1" }), {
      message: /stdout/,
    });
  });
});

describe("logger - Logs on stderr", function () {
  let stderr: string[];

  beforeEach(function () {
    stderr = [];
    // Pretty output is colourised only on a TTY; pin it off so the
    // assertions hold whether or not the tests run in a terminal.
    sinon.stub(tty, "isatty").returns(false);
    const writeSync = fs.writeSync;
    sinon.stub(fs, "writeSync").callsFake(((
      fd: number,
      data: string | Buffer,
      ...rest: never[]
    ) => {
      if (fd === 2) {
        stderr.push(String(data));
        return Buffer.byteLength(String(data));
      }
      return writeSync(fd, data as string, ...rest);
    }) as typeof fs.writeSync);
  });

  afterEach(function () {
    sinon.restore();
  });

  async function settle() {
    for (let i = 0; i < 5; i++) {
      await new Promise((r) => setImmediate(r));
    }
  }

  it("should print one readable line per record in pretty format", async function () {
    const logs = new Logs({ format: "pretty", level: "debug" });
    logs.op("info", "tools.registered", { outcome: "success" });
    logs.op("info", "server.ready");
    logs.audit(
      "authentication.failed",
      "failure",
      { mode: "static-bearer", reason: "missing_token" },
      "warn",
    );
    logs.audit("authentication.succeeded", "success", { mode: "none" });
    logs.flush();
    await settle();
    const text = stderr.join("");
    assert.match(text, /\[operational\] tools\.registered success/);
    assert.match(
      text,
      /\[operational\] server\.ready\n|\[operational\] server\.ready\s/,
    );
    assert.match(
      text,
      /\[security_audit\] authentication\.failed Authentication: \S.*\(missing_token\)/,
    );
    assert.match(text, /\[security_audit\] authentication\.succeeded /);
  });

  it("should report an operational file it cannot open on stderr", function () {
    const dir = fs.mkdtempSync(path.join(os.tmpdir(), "oag-mcp-logs-"));
    try {
      new Logs({ file: path.join(dir, "missing-dir", "op.log") });
      assert.match(stderr.join(""), /logging\.destination_open_failed/);
      assert.match(stderr.join(""), /operational/);
    } finally {
      fs.rmSync(dir, { recursive: true, force: true });
    }
  });
});

describe("logger - Logs.ctx", function () {
  it("should expose a copy of a child's context", function () {
    const dir = fs.mkdtempSync(path.join(os.tmpdir(), "oag-mcp-logs-"));
    try {
      const logs = new Logs({ file: path.join(dir, "all.log") });
      const child = logs
        .child({ requestId: "req_1" })
        .child({ executionId: "e" });
      assert.equals(child.ctx, { requestId: "req_1", executionId: "e" });
      const ctx = child.ctx;
      ctx.requestId = "changed";
      assert.equals(child.ctx.requestId, "req_1");
      assert.equals(logs.ctx, {});
    } finally {
      fs.rmSync(dir, { recursive: true, force: true });
    }
  });
});

"use strict";
import referee from "@sinonjs/referee";

import {
  AUDIT_EVENTS,
  OCSF_VERSION,
  toOcsfEvent,
} from "../../lib/logging/ocsf.js";

const { assert, refute, match } = referee;

const PRODUCT = {
  name: "oag-mcp",
  version: "1.2.3",
  vendorName: "Vendor",
  instanceId: "inst_1",
};

// eslint-disable-next-line @typescript-eslint/no-explicit-any -- OCSF JSON
type Event = Record<string, any>;

const event = (
  name: Parameters<typeof toOcsfEvent>[0],
  outcome: Parameters<typeof toOcsfEvent>[1],
  fields: Record<string, unknown> = {},
  level: Parameters<typeof toOcsfEvent>[2] = "info",
): Event => toOcsfEvent(name, outcome, level, fields, PRODUCT, 1000);

describe("ocsf - toOcsfEvent", function () {
  it("should give every audit event a consistent class, category and activity", function () {
    const categories: Record<number, number> = {
      3002: 3,
      6003: 6,
      4002: 4,
      1007: 1,
      6002: 6,
      2004: 2,
    };
    for (const name of AUDIT_EVENTS) {
      const e = event(name, "success", { httpMethod: "GET" });
      assert.equals(e.category_uid, categories[e.class_uid], name);
      assert.equals(e.type_uid, e.class_uid * 100 + e.activity_id, name);
      assert.isString(e.activity_name, name);
      assert.equals(e.type_name, `${e.class_name}: ${e.activity_name}`, name);
      assert.equals(e.metadata.event_code, name);
      assert.equals(e.metadata.version, OCSF_VERSION);
    }
  });

  it("should record the time in milliseconds and as a date-time", function () {
    const e = event("execution.requested", "accepted");
    assert.equals(e.time, 1000);
    assert.equals(e.time_dt, "1970-01-01T00:00:01.000Z");
    assert.contains(e.metadata.profiles, "datetime");
  });

  it("should identify the product and the reporting instance", function () {
    const e = event("execution.requested", "accepted", { requestId: "req_1" });
    assert.equals(e.metadata.product, {
      name: "oag-mcp",
      version: "1.2.3",
      vendor_name: "Vendor",
    });
    assert.equals(e.metadata.reporter, match({ uid: "inst_1" }));
    assert.equals(e.metadata.correlation_uid, "req_1");
  });

  it("should map an SDK operation's HTTP method to the API Activity activity", function () {
    const id = (httpMethod: string) =>
      event("authorization.allowed", "allowed", { httpMethod }).activity_id;
    assert.equals(
      ["POST", "GET", "PUT", "PATCH", "DELETE"].map(id),
      [1, 2, 3, 3, 4],
    );
    assert.equals(
      event("authorization.allowed", "allowed", { httpMethod: "QUERY" })
        .activity_id,
      99,
    );
  });

  it("should record allow and deny decisions with the security control profile", function () {
    const allowed = event("authorization.allowed", "allowed", {
      policyId: "readers",
    });
    assert.equals(allowed.status_id, 1);
    assert.equals(allowed.action_id, 1);
    assert.equals(allowed.disposition_id, 1);
    assert.equals(allowed.policy, { uid: "readers" });
    assert.contains(allowed.metadata.profiles, "security_control");

    const denied = event("authorization.denied", "denied", {}, "warn");
    assert.equals(denied.status_id, 2);
    assert.equals(denied.action_id, 2);
    assert.equals(denied.disposition_id, 2);
    assert.equals(denied.severity_id, 2);

    const plain = event("execution.requested", "accepted");
    assert.isUndefined(plain.action_id);
    refute.contains(plain.metadata.profiles, "security_control");
  });

  it("should mark an allowed request as modified when agent-supplied credentials were removed", function () {
    const e = event("authorization.allowed", "allowed", {
      strippedCredentials: ["authorization"],
    });
    assert.equals(e.action_id, 4);
    assert.equals(e.disposition_id, 11);
    assert.equals(e.unmapped.strippedCredentials, ["authorization"]);
  });

  it("should place known fields in their OCSF attributes and keep the rest unmapped", function () {
    const e = event("authorization.allowed", "allowed", {
      requestId: "req_1",
      executionId: "exec_1",
      principalId: "static:reader",
      clientAddress: "127.0.0.1",
      clientPort: 5000,
      operation: "PetsApi.listPets",
      operationId: "listPets",
      httpMethod: "GET",
      pathTemplate: "/pets",
      reason: "rule_match",
      schemes: ["apiKey"],
    });
    assert.equals(e.actor, { user: { uid: "static:reader" } });
    assert.equals(e.api, {
      operation: "PetsApi.listPets",
      request: { uid: "exec_1" },
      service: { name: "oag-mcp", version: "1.2.3" },
    });
    assert.equals(e.src_endpoint, { ip: "127.0.0.1", port: 5000 });
    assert.equals(e.http_request, {
      http_method: "GET",
      url: { path: "/pets" },
    });
    assert.equals(e.resources, [
      { uid: "listPets", type: "OpenAPI operation" },
    ]);
    assert.equals(e.status_detail, "rule_match");
    assert.equals(e.unmapped, { schemes: ["apiKey"] });
  });

  it("should describe an MCP tool call with the AI operation profile", function () {
    const e = event("execution.requested", "accepted", {
      toolName: "execute",
      mcpSessionId: "sess-1",
    });
    assert.equals(e.message_context, {
      uid: "sess-1",
      name: "tools/call execute",
      ai_role_id: 3,
      ai_role: "Tool",
      service: { name: "oag-mcp", version: "1.2.3" },
    });
    assert.contains(e.metadata.profiles, "ai_operation");
  });

  it("should name the caller as the authenticated user, or as unknown when authentication failed", function () {
    const ok = event("authentication.succeeded", "success", {
      principalId: "static:reader",
      mode: "static-bearer",
      transport: "stdio",
    });
    assert.equals(ok.user, { uid: "static:reader" });
    assert.equals(ok.auth_protocol_id, 99);
    assert.equals(ok.src_endpoint, { name: "stdio" });
    const failed = event("authentication.failed", "failure", { mode: "oauth" });
    assert.equals(failed.user, match({ type_id: 0 }));
    assert.equals(failed.auth_protocol_id, 6);
  });

  it("should record upstream tokens as authentication of oag-mcp's service identity", function () {
    const e = event("upstream.token.issue_failed", "failure", {
      scheme: "oauth2cc",
      provider: "service-identity",
      status: 401,
    });
    assert.equals(e.class_uid, 3002);
    assert.equals(e.activity_name, "Token Issue");
    assert.equals(e.user, {
      uid: "service-identity",
      type_id: 4,
      type: "Service",
    });
    assert.equals(e.service, { name: "oauth2cc" });
    assert.equals(e.status_code, "401");
  });

  it("should describe a denied destination by its endpoint, never its query", function () {
    const e = event("network.destination_denied", "denied", {
      httpMethod: "POST",
      destinationOrigin: "https://evil.example.com",
    });
    assert.equals(e.class_uid, 4002);
    assert.equals(e.activity_id, 6);
    assert.equals(e.dst_endpoint, { hostname: "evil.example.com", port: 443 });
    assert.equals(e.http_request.url, {
      scheme: "https",
      hostname: "evil.example.com",
    });
  });

  it("should identify the sandbox process", function () {
    const e = event("execution.timeout", "denied", {
      pid: 42,
      executionId: "exec_1",
    });
    assert.equals(e.class_uid, 1007);
    assert.equals(e.activity_id, 2);
    assert.equals(e.status_id, 1);
    assert.equals(e.process, { name: "deno", pid: 42, uid: "exec_1" });
    assert.equals(e.device, match({ type_id: 1 }));
  });

  it("should report forged bridge messages as new detection findings", function () {
    const e = event("execution.boundary_violation", "denied", {
      reason: "unknown_binding",
    });
    assert.equals(e.class_uid, 2004);
    assert.equals(e.status, "New");
    assert.equals(e.severity_id, 3);
    assert.isString(e.finding_info.uid);
  });

  it("should record security configuration as application lifecycle events", function () {
    const configured = event("authorization.policy_loaded", "success", {
      rules: 2,
    });
    assert.equals(configured.class_uid, 6002);
    assert.equals(configured.activity_id, 99);
    assert.equals(configured.activity_name, "Configure");
    assert.equals(configured.unmapped, { rules: 2 });
    const refused = event("security.config_invalid", "failure", {
      errorCode: "MCP_AUTH_CONFIG_INVALID",
    });
    assert.equals(refused.activity_id, 3);
    assert.equals(refused.status_id, 2);
    assert.equals(refused.status_code, "MCP_AUTH_CONFIG_INVALID");
  });
});

describe("ocsf - toOcsfEvent destinations", function () {
