      'const result = await sdk.ThingsApi.getThing({ color: "blue", size: "m", when: new Date("2026-02-02"), tags: ["x"], flag: false, nested: { inner: { deep: undefined } }, shape: { kind: "example" }, record: { a: undefined }, nothing: undefined, opts: {}, count: 3, label: "example" });\nreturn result;',
    );
    assert.equals(get.requiredArguments.length, 12);
    assert.equals(get.parameters[1], {
      name: "initOverrides",
      type: "unknown",
      optional: true,
    });
  });

  it("should render referenced interfaces, enums and aliases without the input type", function () {
    const get = this.byName("getThing") as AnalyzedMethod;
    const decl = new Map(
      get.referencedTypes.map((t) => [t.name, t.declaration]),
    );
    assert.equals(
      [...decl.keys()],
      ["Big", "Color", "Size", "Nested", "Shape", "Nothing", "Inner"],
    );
    const big = decl.get("Big")!.split("\n");
    assert.equals(big[0], "interface Big extends Base {");
    assert.equals(big[1], "  [key: string]: unknown;");
    assert.equals(big[2], "  m0: string; // Member 0.");
    assert.equals(big.at(-2), "  // … 2 more members");
    assert.equals(big.length, 43);
    assert.match(decl.get("Color")!, /^export declare enum Color \{/);
    assert.equals(decl.get("Size"), 'type Size = "s" | "m";');
    assert.equals(decl.get("Shape"), "type Shape = { kind: string } | null;");
  });

  it("should give properties without declarations an undefined example", function () {
    const rec = this.byName("getRecord") as AnalyzedMethod;
    assert.isUndefined(rec.inputType, "Record is not an SDK declaration");
    assert.equals(rec.requiredArguments, ["a"]);
    assert.equals(
      rec.example,
      "await sdk.ThingsApi.getRecord({ a: undefined });\nreturn { done: true };",
    );
  });

  it("should give the body hint to object-typed positional parameters", function () {
    const list = this.byName("listThings") as AnalyzedMethod;
    assert.equals(list.requestStyle, "positional");
    assert.equals(list.requiredArguments, ["a", "body", "mode"]);
    assert.match(
      list.example,
      /listThings\(5, \{ inner: \{ deep: \{ x: 2 \} \} \}, "x"\)/,
    );
    assert.equals(
      list.referencedTypes.map((t) => t.name),
      ["Nested", "Inner", "Deep"],
    );
  });

  it("should leave out the input type of an inline request type", function () {
    const inline = this.byName("inline") as AnalyzedMethod;
    assert.equals(inline.requestStyle, "object");
    assert.isUndefined(inline.inputType);
    assert.match(inline.example, /inline\(\{ id: 1 \}\)/);
  });

  it("should describe methods without arguments or a declared return type", function () {
    const none = this.byName("noArgs") as AnalyzedMethod;
    assert.equals(none.requestStyle, "none");
    assert.equals(none.requiredArguments, []);
    assert.equals(
      none.example,
      "const result = await sdk.ThingsApi.noArgs();\nreturn result;",
    );
    const untyped = this.byName("untyped") as AnalyzedMethod;
    assert.equals(untyped.signature, "untyped()");
    assert.equals(untyped.returnType, "Promise<unknown>");
    assert.equals(untyped.referencedTypes, []);
  });

  it("should report methods without bindings and bindings without classes", function () {
    try {
      syntheticAnalyzer().analyze(
        new Map([
          ["OtherApi", new Map()],
          ["GhostApi", new Map([["get", binding("/g")]])],
        ]),
        () => ({}),
      );
      assert(false, "expected failure");
    } catch (e) {
      const err = e as OagMcpError;
      assert.equals(err.code, "SDK_BINDING_AMBIGUOUS");
      assert.equals(err.details!.problems, [
        "OtherApi.orphan: no HTTP method/path found in its RequestOpts/Raw implementation",
        "GhostApi: implementation found but no matching class in declarations",
      ]);
    }
  });
});

describe("method-records - buildRecords", function () {
  it("should fail when the SDK has methods the spec does not define", async function () {
    const spec = await loadSpec(SPEC);
    const { methods } = await analyse(SDK_726, spec);
    const trimmed = {
      ...spec,
      operations: spec.operations.filter((o) => o.operationId !== "listOwners"),
    };
    try {
      buildRecords(trimmed, methods);
      assert(false, "expected failure");
    } catch (e) {
      assert.equals((e as OagMcpError).code, "SDK_SPEC_MISMATCH");
    }
  });

  it("should report operations without SDK methods as unmapped", async function () {
    const spec = await loadSpec(SPEC);
    const { methods } = await analyse(SDK_726, spec);
    const { unmapped, records } = buildRecords(
      spec,
      methods.filter((m) => m.methodName !== "healthGet"),
    );
    assert.equals(unmapped, [{ key: "GET /health", operationId: undefined }]);
    assert.equals(records.length, 10);
  });

  it("should detect a binding that matches several operations", async function () {
    const spec = await loadSpec(SPEC);
    const { methods } = await analyse(SDK_726, spec);
    const extra = {
      ...spec.operations.find((o) => o.key === "GET /pets/{petId}")!,
    };
    const dup = {
      ...spec,
      operations: [
        ...spec.operations.filter((o) => o.key !== "GET /pets/{petId}"),
        { ...extra, key: "GET /pets/{id}", path: "/pets/{id}" },
        { ...extra, key: "GET /pets/{x}", path: "/pets/{x}" },
      ],
    };
    try {
      buildRecords(dup, methods);
      assert(false, "expected failure");
    } catch (e) {
      assert.match((e as OagMcpError).message, /matches several operations/);
    }
  });

  it("should summarise auth alternatives and optional auth", function () {
    const schemes = {
      a: {
        name: "a",
        type: "apiKey" as const,
        in: "header" as const,
        supported: true,
      },
      c: { name: "c", type: "openIdConnect" as const, supported: false },
    };
    const s = summariseAuth([{ a: [] }, {}], schemes);
    assert.isTrue(s.optional);
    assert.equals(s.alternatives[0].schemes[0].type, "apiKey-header");
    assert.equals(summariseAuth([{ c: [] }], schemes).unsupportedSchemes, [
      "c",
    ]);
    assert.equals(normalisePathTemplate("/a/{b}/c/"), "/a/{}/c");
    assert.equals(normaliseName("Pet_ID"), "petid");
  });

  it("should give every record an id, sdk path and auth summary", async function () {
    const spec = await loadSpec(SPEC);
    const { methods } = await analyse(SDK_726, spec);
    const { records, bindings } = buildRecords(spec, methods);
    for (const r of records as MethodRecord[]) {
      assert.equals(r.sdkPath, `sdk.${r.className}.${r.methodName}`);
      assert.equals(r.id, `${r.className}.${r.methodName}`);
    }
    assert.equals(bindings.length, records.length);
  });
});

"use strict";
import fs from "node:fs";
import path from "node:path";

import referee from "@sinonjs/referee";

import { OagMcpError } from "../../lib/errors.js";
import {
  AGENT_TS_LIBS,
  REQUIRED_RUNTIME_EXPORTS,
  bundleSdk,
  copyDeclarations,
  copyTsLibs,
  emitDeclarations,
  sdkCompilerOptions,
} from "../../lib/prepare/bundle.js";
import { SDK_726, tmpDir } from "../helpers/paths.js";

const { assert, refute } = referee;

/** Write files under a new directory. */
function files(entries: Record<string, string>): string {
  const dir = tmpDir();
  for (const [rel, text] of Object.entries(entries)) {
    fs.mkdirSync(path.dirname(path.join(dir, rel)), { recursive: true });
    fs.writeFileSync(path.join(dir, rel), text);
  }
  return dir;
}

async function bundle(root: string, entry: string, classNames = ["PetsApi"]) {
  const out = tmpDir();
  const outFile = path.join(out, "sdk", "sdk.bundle.js");
  const result = await bundleSdk({
    entry: path.join(root, entry),
    root,
    outFile,
    shimDir: path.join(out, "shim"),
    classNames,
  });
  return { ...result, out, outFile };
}

async function rejection(p: Promise<unknown>): Promise<OagMcpError> {
  try {
    await p;
  } catch (e) {
    return e as OagMcpError;
  }
  throw new Error("expected a rejection");
}

describe("bundle - sdkCompilerOptions", function () {
  it("should target ES2022 modules with the agent libs and no ambient types", function () {
    const o = sdkCompilerOptions();
    assert.equals(o.lib, AGENT_TS_LIBS);
    assert.equals(o.types, []);
    refute(o.allowJs);
  });
});

describe("bundle - bundleSdk", function () {
  this.timeout(30000);

  it("should bundle a source SDK into one ES module exporting the runtime and API classes", async function () {
    const { exports, bytes, outFile } = await bundle(
      SDK_726,
      path.join("src", "index.ts"),
      ["PetsApi", "StoreApi"],
    );
    for (const name of [...REQUIRED_RUNTIME_EXPORTS, "PetsApi", "StoreApi"]) {
      assert.contains(exports, name);
    }
    assert.equals(bytes, fs.statSync(outFile).size);
    assert.match(
      fs.readFileSync(outFile, "utf8"),
      /^\/\/ oag-mcp SDK execution bundle\./,
    );
  });

  it("should bundle a compiled ES module entry as it is", async function () {
    const root = files({
      "dist/index.js":
        "export class Configuration {}\nexport class BaseAPI {}\nexport class PetsApi extends BaseAPI {}\n",
    });
    const { exports, out } = await bundle(root, path.join("dist", "index.js"));
    assert.equals(exports.sort(), ["BaseAPI", "Configuration", "PetsApi"]);
    refute(fs.existsSync(path.join(out, "shim")), "no CommonJS shim");
  });

  it("should re-export a CommonJS entry's names through an ES module shim", async function () {
    const root = files({
      "dist/index.js": [
        '"use strict";',
        "class BaseAPI {}",
        "exports.BaseAPI = BaseAPI;",
        "exports.Configuration = class Configuration {};",
        "exports.ResponseError = class ResponseError extends Error {};",
        'exports.PetsApi = require("./apis").PetsApi;',
      ].join("\n"),
      "dist/apis.js": "exports.PetsApi = class PetsApi {};\n",
    });
    const { exports, out } = await bundle(root, path.join("dist", "index.js"));
    for (const name of [
      "BaseAPI",
      "Configuration",
      "ResponseError",
      "PetsApi",
    ]) {
      assert.contains(exports, name);
    }
    const shim = fs.readFileSync(
      path.join(out, "shim", "__oag_mcp_entry.mjs"),
      "utf8",
    );
    assert.match(shim, /^import __sdk from ".*\/dist\/index\.js";/);
    assert.match(shim, /export const PetsApi = __sdk\.PetsApi;/);
  });

  it("should explain a bundle that cannot be built", async function () {
    const root = files({
      "src/index.ts":
        'import { thing } from "not-installed-pkg";\nexport { thing };\n',
    });
    const err = await rejection(bundle(root, path.join("src", "index.ts")));
    assert.equals(err.code, "SDK_BUNDLE_FAILED");
    assert.match(err.message, /not-installed-pkg/);
    assert.match(err.hint!, /oag-mcp never installs packages/);
  });

  it("should refuse a bundle missing the runtime or API classes", async function () {
    const root = files({ "src/index.ts": "export class Configuration {}\n" });
    const err = await rejection(bundle(root, path.join("src", "index.ts")));
    assert.equals(err.code, "SDK_BUNDLE_EXPORTS");
    assert.match(err.message, /does not export: BaseAPI, PetsApi/);
  });
});

describe("bundle - emitDeclarations", function () {
  this.timeout(30000);

  it("should emit declarations and return non-fatal type errors", function () {
    const root = files({
      "src/index.ts":
        'export const n: number = "not a number";\nexport class PetsApi {}\n',
    });
    const out = tmpDir();
    const messages = emitDeclarations(path.join(root, "src", "index.ts"), out);
    assert(fs.existsSync(path.join(out, "index.d.ts")));
    assert.equals(messages.length, 1);
    assert.match(messages[0], /not assignable to type 'number'/);
  });

  it("should fail when no index declaration is produced", function () {
    const root = files({ "src/main.ts": "export const x = 1;\n" });
    try {
      emitDeclarations(path.join(root, "src", "main.ts"), tmpDir());
      assert(false, "expected failure");
    } catch (e) {
      assert.equals((e as OagMcpError).code, "SDK_DECLARATIONS_FAILED");
    }
  });
});

describe("bundle - copyDeclarations", function () {
  it("should copy only declarations, leaving out the ESM build", function () {
    const typesDir = files({
      "index.d.ts": "export {};",
      "index.js": "",
      "apis/PetsApi.d.ts": "export {};",
      "esm/index.d.ts": "export {};",
    });
    const out = tmpDir();
    copyDeclarations(typesDir, out);
    assert(fs.existsSync(path.join(out, "index.d.ts")));
    assert(fs.existsSync(path.join(out, "apis", "PetsApi.d.ts")));
    refute(fs.existsSync(path.join(out, "index.js")));
    refute(fs.existsSync(path.join(out, "esm")));
  });
});

describe("bundle - copyTsLibs", function () {
  it("should copy the agent libs and every lib they reference", function () {
    const out = tmpDir();
    const copied = copyTsLibs(out);
    for (const name of [...AGENT_TS_LIBS, "lib.es5.d.ts", "lib.es2021.d.ts"]) {
      assert.contains(copied, name);
      assert(fs.existsSync(path.join(out, name)), name);
    }
    assert.equals(copied, [...copied].sort());
