describe("method-records - buildRecords", function () {
  it("should bind methods by exact path, or by path with other parameter names", function () {
    const { records, bindings, unmapped } = buildRecords(
      spec([
        operation("GET", "/pets", {
          operationId: "listPets",
          description: "From the spec",
        }),
        operation("GET", "/pets/{petId}", { deprecated: true }),
        operation("DELETE", "/pets/{petId}"),
      ]),
      [
        method("listPets", "GET", "/pets", { documentation: "From the SDK" }),
        method("getPet", "GET", "/pets/{id}", {
          documentation: "SDK docs",
        }),
      ],
    );
    assert.equals(
      records.map((r) => [r.id, r.path, r.description, r.deprecated]),
      [
        ["PetsApi.listPets", "/pets", "From the spec", false],
        ["PetsApi.getPet", "/pets/{petId}", "SDK docs", true],
      ],
    );
    assert.equals(records[0].sdkPath, "sdk.PetsApi.listPets");
    assert.equals(bindings[0], {
      id: "PetsApi.listPets",
      className: "PetsApi",
      methodName: "listPets",
      httpMethod: "GET",
      path: "/pets",
      operationId: "listPets",
      tags: ["t"],
      security: [],
    });
    assert.equals(unmapped, [
      { key: "DELETE /pets/{petId}", operationId: undefined },
    ]);
  });

  it("should leave out a method's empty documentation", function () {
    const { records } = buildRecords(spec([operation("GET", "/pets")]), [
      method("listPets", "GET", "/pets", { deprecated: true }),
    ]);
    assert.isUndefined(records[0].description);
    assert.isTrue(records[0].deprecated);
  });

  it("should refuse methods that match several operations or none", function () {
    const err = expectCode(
      () =>
        buildRecords(
          spec([operation("GET", "/pets/{a}"), operation("GET", "/pets/{b}")]),
          [
            method("getPet", "GET", "/pets/{id}"),
            method("ghost", "GET", "/ghosts"),
          ],
        ),
      "SDK_SPEC_MISMATCH",
    );
    assert.match(err.message, /PetsApi\.getPet .* matches several operations/);
    assert.match(err.message, /PetsApi\.ghost .* has no matching operation/);
    assert.equals((err.details!.problems as string[]).length, 2);
  });

  it("should refuse an SDK without methods", function () {
    expectCode(
      () => buildRecords(spec([operation("GET", "/pets")]), []),
      "SDK_NO_METHODS",
    );
  });
});

"use strict";
import fs from "node:fs";
import path from "node:path";

import referee from "@sinonjs/referee";

import { OagMcpError } from "../../lib/errors.js";
import {
  type PrepareOptions,
  prepareSdk,
  runStage,
} from "../../lib/prepare/prepare.js";
import { WORKSPACE_PATHS } from "../../lib/prepare/workspace.js";
import { quietLogs } from "../helpers/fakes.js";
import {
  SDK_726,
  SDK_TGZ,
  SPEC,
  copyFixture,
  tmpDir,
} from "../helpers/paths.js";

const { assert, refute, match } = referee;

function options(extra: Partial<PrepareOptions> = {}) {
  const { logs, records } = quietLogs();
  const workspaceRoot = tmpDir();
  return {
    opts: { spec: SPEC, sdk: SDK_726, workspaceRoot, logs, ...extra },
    records,
    workspaceRoot,
  };
}

async function rejection(p: Promise<unknown>): Promise<OagMcpError> {
  try {
    await p;
  } catch (e) {
    return e as OagMcpError;
  }
  throw new Error("expected a rejection");
}

describe("prepare - runStage", function () {
  it("should log a stage's start and completion and return its result", async function () {
    const { opts, records } = options();
    assert.equals(await runStage(opts.logs, "index", () => 7), 7);
    const done = records().find((r) => r.event === "prepare.stage.completed")!;
    assert.equals(done.get("stage"), "index");
    assert.equals(done.outcome, "success");
  });

  it("should not start a stage once cancelled", async function () {
    const { opts, records } = options();
    const abort = new AbortController();
    abort.abort();
    let ran = false;
    await assert.rejects(
      runStage(opts.logs, "sdk", () => (ran = true), abort.signal),
      match({ code: "STARTUP_ABORTED" }),
    );
    refute(ran);
    assert.contains(
      records().map((r) => r.event),
      "prepare.aborted",
    );
  });

  it("should log a failed stage's error code, and compatibility failures separately", async function () {
    const { opts, records } = options();
    await assert.rejects(
      runStage(opts.logs, "compatibility", () => {
        throw new OagMcpError("SDK_X", "no");
      }),
    );
    await assert.rejects(
      runStage(opts.logs, "index", () => {
        throw new TypeError("bug");
      }),
    );
    const failed = records().filter((r) => r.event === "prepare.stage.failed");
    assert.equals(
      failed.map((r) => [r.get("stage"), r.get("errorCode")]),
      [
        ["compatibility", "SDK_X"],
        ["index", "UNEXPECTED"],
      ],
    );
    assert.equals(
      records().filter((r) => r.event === "prepare.compat.failed").length,
      1,
    );
  });
});

describe("prepare - prepareSdk", function () {
  this.timeout(60000);

  it("should prepare a source SDK into a private workspace", async function () {
    const { opts, records } = options();
    const prepared = await prepareSdk(opts);
    try {
      const ws = prepared.workspaceDir;
      for (const p of [
        WORKSPACE_PATHS.bundle,
        WORKSPACE_PATHS.runner,
        WORKSPACE_PATHS.binding,
        path.join(WORKSPACE_PATHS.types, "index.d.ts"),
        path.join(WORKSPACE_PATHS.tsLib, "lib.es2022.d.ts"),
      ]) {
        assert(fs.existsSync(path.join(ws, p)), p);
      }
      const { info } = prepared;
      assert.equals(info.target.sdkLayout, "source");
      assert.equals(info.target.oagVersion, "7.26.0");
      assert.equals(info.target.sdkPackage!.name, "petclinic-sdk");
      assert.equals(info.inputs.spec.fileName, "openapi.yaml");
      assert.match(info.inputs.spec.sha256, /^[0-9a-f]{64}$/);
      assert.equals(info.inputs.sdk.kind, "directory");
      assert.isString(info.api.title);
      assert.equals(prepared.records.length, prepared.bindings.length);
      assert.equals(info.operations, prepared.bindings);
      assert.greater(prepared.records.length, 0);
      for (const u of info.unmappedOperations) {
        assert.contains(prepared.warnings.join("\n"), `Operation ${u.key}`);
      }
      const events = records().map((r) => r.event);
      for (const e of [
        "prepare.started",
        "prepare.spec.loaded",
        "prepare.sdk.resolved",
        "prepare.compat.checked",
        "prepare.sdk.bundled",
        "prepare.index.created",
        "prepare.sdk.prepared",
      ]) {
        assert.contains(events, e);
      }
    } finally {
      assert.isTrue(prepared.cleanup());
    }
    refute(fs.existsSync(prepared.workspaceDir));
  });

  it("should prepare a packed SDK from its compiled declarations", async function () {
    const { opts } = options({ sdk: SDK_TGZ, sdkLayout: "compiled" });
    const prepared = await prepareSdk(opts);
    try {
      assert.equals(prepared.info.inputs.sdk.kind, "archive");
      assert.equals(prepared.info.target.sdkLayout, "compiled");
      assert(
        fs.existsSync(
          path.join(prepared.workspaceDir, WORKSPACE_PATHS.types, "index.d.ts"),
        ),
      );
    } finally {
      prepared.cleanup();
    }
  });

  it("should warn about type errors in the SDK and operations it lacks", async function () {
    const sdk = copyFixture(SDK_726);
    fs.appendFileSync(
      path.join(sdk, "src", "index.ts"),
      '\nexport const broken: number = "not a number";\n',
    );
    fs.rmSync(path.join(sdk, "package.json"));
    const spec = path.join(tmpDir(), "openapi.yaml");
    fs.writeFileSync(
      spec,
      fs
        .readFileSync(SPEC, "utf8")
        .replace(
          /^paths:\n/m,
          "paths:\n  /extra:\n    get:\n      operationId: getExtra\n      responses:\n        '200':\n          description: ok\n",
        ),
    );
    const { opts, records } = options({ sdk, spec });
    const prepared = await prepareSdk(opts);
    prepared.cleanup();
    assert.isUndefined(prepared.info.target.sdkPackage);
    const warnings = prepared.warnings.join("\n");
    assert.match(warnings, /SDK has no package\.json/);
    assert.match(
      warnings,
      /SDK declarations emitted with 1 TypeScript diagnostic\(s\): Type 'string' is not assignable/,
    );
    assert.match(
      warnings,
      /Operation GET \/extra \(getExtra\) has no SDK method/,
    );
    assert.greater(
      records().filter((r) => r.event === "prepare.warning").length,
      1,
    );
  });

  it("should require a spec and an SDK, and an existing spec file", async function () {
    for (const [extra, code] of [
      [{ spec: "" }, "CLI_ARGS_INVALID"],
      [{ sdk: "" }, "CLI_ARGS_INVALID"],
      [{ spec: path.join(tmpDir(), "none.yaml") }, "SPEC_NOT_FOUND"],
      [{ spec: tmpDir() }, "SPEC_NOT_FOUND"],
    ] as const) {
      const { opts, workspaceRoot, records } = options(extra);
      const err = await rejection(prepareSdk(opts));
      assert.equals(err.code, code);
      assert.equals(fs.readdirSync(workspaceRoot), [], "workspace removed");
      assert.equals(
        records()
          .find((r) => r.event === "prepare.failed")!
          .get("errorCode"),
        code,
      );
    }
  });

  it("should explain how to install missing SDK dependencies", async function () {
    const sdk = copyFixture(SDK_726);
    const pkgFile = path.join(sdk, "package.json");
    const pkg = JSON.parse(fs.readFileSync(pkgFile, "utf8"));
    pkg.dependencies = { "not-installed-pkg": "1.0.0" };
    fs.writeFileSync(pkgFile, JSON.stringify(pkg));
    const err = await rejection(prepareSdk(options({ sdk }).opts));
    assert.equals(err.code, "SDK_DEPENDENCIES_MISSING");
    assert.match(err.message, /not-installed-pkg/);
    assert.match(
      err.hint!,
      /Run `npm install --omit=dev --ignore-scripts` in /,
    );
    assert.equals(err.details!.missing, ["not-installed-pkg"]);
  });

  it("should tell archive users to extract and install before serving", async function () {
    const work = tmpDir();
    const { execFileSync } = await import("node:child_process");
    execFileSync("tar", ["-xzf", SDK_TGZ, "-C", work]);
    const pkgFile = path.join(work, "package", "package.json");
    const pkg = JSON.parse(fs.readFileSync(pkgFile, "utf8"));
    pkg.dependencies = { "not-installed-pkg": "1.0.0" };
    fs.writeFileSync(pkgFile, JSON.stringify(pkg));
    const archive = path.join(work, "sdk.tgz");
    execFileSync("tar", ["-czf", archive, "-C", work, "package"]);
    const err = await rejection(prepareSdk(options({ sdk: archive }).opts));
    assert.equals(err.code, "SDK_DEPENDENCIES_MISSING");
    assert.match(err.hint!, /Extract the archive/);
  });
});

"use strict";
import fs from "node:fs";
import path from "node:path";

import referee from "@sinonjs/referee";
import sinon from "sinon";
import * as tar from "tar";

import {
  ARCHIVE_LIMITS,
  extractArchive,
  missingDependencies,
  stageSdkInput,
  unsafeArchivePath,
} from "../../lib/prepare/sdk-input.js";
import { OagMcpError } from "../../lib/errors.js";
import { SDK_726, SDK_TGZ, tmpDir } from "../helpers/paths.js";
import { sha256Tree } from "../../lib/util/hash.js";

const { assert } = referee;

async function expectRejection(
  p: Promise<unknown>,
  code: string,
): Promise<void> {
  try {
    await p;
  } catch (e) {
    assert.equals((e as OagMcpError).code, code);
    return;
  }
  throw new Error(`expected ${code}`);
}

describe("sdk-input - unsafeArchivePath", function () {
  it("should flag absolute paths and traversal but accept normal entries", function () {
    assert.isString(unsafeArchivePath("/etc/passwd"));
    assert.isString(unsafeArchivePath("C:\\x"));
    assert.isString(unsafeArchivePath("package/../../x"));
    assert.isUndefined(unsafeArchivePath("package/src/index.ts"));
    assert.equals(unsafeArchivePath(""), "empty or NUL-containing path");
    assert.equals(
      unsafeArchivePath("package/a\0b"),
      "empty or NUL-containing path",
    );
  });
});

describe("sdk-input - extractArchive", function () {
  it("should extract an npm pack archive and return its package root", async function () {
    const root = await extractArchive(SDK_TGZ, path.join(tmpDir(), "out"));
    assert.equals(path.basename(root), "package");
    assert(fs.existsSync(path.join(root, "dist", "index.d.ts")));
  });

  it("should reject archives containing parent traversal", async function () {
    const work = tmpDir();
    fs.mkdirSync(path.join(work, "a", "b"), { recursive: true });
    fs.writeFileSync(path.join(work, "a", "evil.txt"), "x");
    const file = path.join(work, "evil.tgz");
    await tar.c(
      { gzip: true, file, cwd: path.join(work, "a", "b"), preservePaths: true },
      ["../evil.txt"],
    );
    await expectRejection(
      extractArchive(file, path.join(work, "out")),
      "SDK_ARCHIVE_UNSAFE",
    );
    assert.isFalse(fs.existsSync(path.join(work, "evil.txt")));
  });

  it("should reject archives containing symbolic links", async function () {
    const work = tmpDir();
    fs.mkdirSync(path.join(work, "package"));
    fs.symlinkSync("/etc/passwd", path.join(work, "package", "link"));
    const file = path.join(work, "link.tgz");
    await tar.c({ gzip: true, file, cwd: work }, ["package"]);
    await expectRejection(
      extractArchive(file, path.join(work, "out")),
      "SDK_ARCHIVE_UNSAFE",
    );
  });

  it("should reject archives with several top-level directories", async function () {
    const work = tmpDir();
    fs.mkdirSync(path.join(work, "one"));
    fs.mkdirSync(path.join(work, "two"));
    fs.writeFileSync(path.join(work, "one", "a"), "1");
    fs.writeFileSync(path.join(work, "two", "b"), "2");
    const file = path.join(work, "multi.tgz");
    await tar.c({ gzip: true, file, cwd: work }, ["one", "two"]);
    await expectRejection(
      extractArchive(file, path.join(work, "out")),
      "SDK_ARCHIVE_LAYOUT",
    );
  });

  it("should reject files that are not archives", async function () {
    const work = tmpDir();
    const file = path.join(work, "fake.tgz");
    fs.writeFileSync(file, "not gzip");
    await expectRejection(
      extractArchive(file, path.join(work, "out")),
      "SDK_ARCHIVE_INVALID",
    );
  });
});

describe("sdk-input - stageSdkInput", function () {
  it("should use a directory in place without copying or modifying it", async function () {
    const before = sha256Tree(SDK_726);
    const work = tmpDir();
    const staged = await stageSdkInput(SDK_726, work);
    assert.equals(staged.kind, "directory");
    assert.equals(staged.root, fs.realpathSync(SDK_726));
    assert.equals(fs.readdirSync(work), []);
    assert.equals(sha256Tree(SDK_726), before);
    assert.equals(staged.sha256, before);
  });

  it("should extract an archive into the workspace", async function () {
    const work = tmpDir();
    const staged = await stageSdkInput(SDK_TGZ, path.join(work, "input"));
    assert.equals(staged.kind, "archive");
    assert(staged.root.startsWith(fs.realpathSync(work)));
    assert.match(staged.sha256, /^[0-9a-f]{64}$/);
  });

  it("should reject inputs that are neither directories nor archives", async function () {
    const work = tmpDir();
    const file = path.join(work, "sdk.zip");
    fs.writeFileSync(file, "x");
    await expectRejection(stageSdkInput(file, work), "SDK_INPUT_UNSUPPORTED");
    await expectRejection(
      stageSdkInput(path.join(work, "missing"), work),
      "SDK_NOT_FOUND",
    );
  });
});

describe("sdk-input - missingDependencies", function () {
  it("should resolve dependencies from the SDK or any parent node_modules", function () {
    const work = tmpDir();
    const sdk = path.join(work, "apps", "sdk");
    fs.mkdirSync(path.join(sdk, "node_modules", "local-dep"), {
      recursive: true,
    });
    fs.writeFileSync(
      path.join(sdk, "node_modules", "local-dep", "package.json"),
      "{}",
    );
    fs.mkdirSync(path.join(work, "node_modules", "@scope", "hoisted"), {
      recursive: true,
    });
    fs.writeFileSync(
      path.join(work, "node_modules", "@scope", "hoisted", "package.json"),
      "{}",
    );
    assert.equals(
      missingDependencies(sdk, {
        "local-dep": "1",
        "@scope/hoisted": "1",
        "not-installed-anywhere-xyz": "1",
      }),
      ["not-installed-anywhere-xyz"],
    );
    assert.equals(missingDependencies(sdk, undefined), []);
  });
});

describe("sdk-input - extractArchive limits and extracted tree", function () {
  const saved = { ...ARCHIVE_LIMITS };

  async function packed(): Promise<{ work: string; file: string }> {
    const work = tmpDir();
    fs.mkdirSync(path.join(work, "package", "src"), { recursive: true });
    fs.writeFileSync(path.join(work, "package", "a.txt"), "aaaa");
    fs.writeFileSync(path.join(work, "package", "src", "b.txt"), "bbbb");
    const file = path.join(work, "p.tgz");
    await tar.c({ gzip: true, file, cwd: work }, ["package"]);
    return { work, file };
  }

  afterEach(function () {
    Object.assign(ARCHIVE_LIMITS, saved);
    sinon.restore();
  });

  it("should reject archives over the entry and size limits", async function () {
    const { work, file } = await packed();
    ARCHIVE_LIMITS.maxEntries = 2;
    ARCHIVE_LIMITS.maxTotalBytes = 4;
    try {
      await extractArchive(file, path.join(work, "out"));
      assert(false, "expected failure");
    } catch (e) {
      const err = e as OagMcpError;
      assert.equals(err.code, "SDK_ARCHIVE_UNSAFE");
      assert.match(err.message, /too many entries \(4 > 2\)/);
      assert.match(err.message, /uncompressed size too large \(8 > 4 bytes\)/);
    }
  });

  it("should reject an extracted tree that contains a link", async function () {
    const { work, file } = await packed();
    const readdirSync = fs.readdirSync;
    sinon.stub(fs, "readdirSync").callsFake(((dir: string, opts: never) => {
      const entries = readdirSync(dir, opts) as unknown as fs.Dirent[];
      if (path.basename(dir) !== "package") {
        return entries;
      }
      const link = Object.assign(Object.create(entries[0]), {
        name: "sneaky",
        isSymbolicLink: () => true,
      });
      return [...entries, link];
    }) as typeof fs.readdirSync);
    await expectRejection(
      extractArchive(file, path.join(work, "out")),
      "SDK_ARCHIVE_UNSAFE",
    );
  });

  it("should reject an extracted path that resolves outside the destination", async function () {
    const { work, file } = await packed();
    const realpathSync = fs.realpathSync;
    sinon
      .stub(fs, "realpathSync")
      .callsFake(((p: string) =>
        p.endsWith("b.txt") ? "/elsewhere/b.txt" : realpathSync(p)) as never);
    try {
      await extractArchive(file, path.join(work, "out"));
      assert(false, "expected failure");
    } catch (e) {
      assert.equals((e as OagMcpError).code, "SDK_ARCHIVE_UNSAFE");
      assert.match((e as OagMcpError).message, /escapes destination: .*b\.txt/);
    }
  });
});

"use strict";
import fs from "node:fs";
