"use strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";

import referee from "@sinonjs/referee";
import sinon from "sinon";

import {
  WORKSPACE_PREFIX,
  bindingDeclaration,
  createWorkspace,
  sweepStaleWorkspaces,
} from "../../lib/prepare/workspace.js";
import type { MethodRecord } from "../../lib/types.js";
import { quietLogs } from "../helpers/fakes.js";
import { tmpDir } from "../helpers/paths.js";

const { assert, refute } = referee;

/** Write a workspace-like directory with an owner marker. */
function fakeWorkspace(
  root: string,
  name: string,
  owner?: Record<string, unknown>,
): string {
  const dir = path.join(root, `${WORKSPACE_PREFIX}${name}`);
  fs.mkdirSync(dir);
  if (owner) {
    fs.writeFileSync(
      path.join(dir, ".oag-mcp-owner.json"),
      JSON.stringify(owner),
    );
  }
  return dir;
}

describe("workspace - createWorkspace", function () {
  afterEach(function () {
    sinon.restore();
  });

  it("should create a private directory and remove it on cleanup", function () {
    const root = tmpDir();
    const { logs } = quietLogs();
    const ws = createWorkspace({ root, logs });
    assert(path.basename(ws.dir).startsWith(WORKSPACE_PREFIX));
    assert.equals(fs.statSync(ws.dir).mode & 0o777, 0o700);
    assert.isTrue(ws.cleanup());
    refute(fs.existsSync(ws.dir));
    assert.isTrue(ws.cleanup(), "idempotent");
  });

  it("should log and report a cleanup failure instead of throwing", function () {
    const root = tmpDir();
    const { logs, records } = quietLogs();
    const ws = createWorkspace({ root, logs });
    sinon
      .stub(fs, "rmSync")
      .throws(Object.assign(new Error("busy"), { code: "EBUSY" }));
    assert.isFalse(ws.cleanup());
    sinon.restore();
    const failed = records().find(
      (r) => r.event === "prepare.workspace.cleanup_failed",
    );
    assert.equals(failed?.get("error"), "EBUSY");
    assert.isTrue(ws.cleanup());
  });
});

describe("workspace - sweepStaleWorkspaces", function () {
  it("should remove only workspaces of dead processes on this host", function () {
    const root = tmpDir();
    const { logs } = quietLogs();
    const dead = fakeWorkspace(root, "dead", {
      pid: 2 ** 22 + 4242,
      hostname: os.hostname(),
    });
    const alive = fakeWorkspace(root, "alive", {
      pid: process.pid,
      hostname: os.hostname(),
    });
    const otherHost = fakeWorkspace(root, "other", {
      pid: 2 ** 22 + 4242,
      hostname: `${os.hostname()}-elsewhere`,
    });
    const unmarked = fakeWorkspace(root, "unmarked");
    const unrelated = path.join(root, "something-else");
    fs.mkdirSync(unrelated);
    assert.equals(sweepStaleWorkspaces(root, logs), 1);
    refute(fs.existsSync(dead));
    for (const kept of [alive, otherHost, unmarked, unrelated]) {
      assert(fs.existsSync(kept), kept);
    }
  });

  it("should tolerate a missing root", function () {
    const { logs } = quietLogs();
    assert.equals(
      sweepStaleWorkspaces(path.join(tmpDir(), "missing"), logs),
      0,
    );
  });
});

describe("workspace - bindingDeclaration", function () {
  it("should declare only indexed methods per API class", function () {
    const decl = bindingDeclaration([
      { className: "PetsApi", methodName: "listPets" },
      { className: "PetsApi", methodName: "getPetById" },
      { className: "AdminApi", methodName: "deletePet" },
    ] as MethodRecord[]);
    assert.contains(
      decl,
      'readonly AdminApi: Pick<__sdk.AdminApi, "deletePet">;',
    );
    assert.contains(
      decl,
      'readonly PetsApi: Pick<__sdk.PetsApi, "getPetById" | "listPets">;',
    );
    assert(decl.indexOf("AdminApi") < decl.indexOf("PetsApi"));
  });
});

describe("workspace - exit safety net", function () {
  afterEach(function () {
    sinon.restore();
  });

  it("should remove live workspaces at exit, tolerating a removal failure", function () {
    const { logs } = quietLogs();
    const kept = createWorkspace({ root: tmpDir(), logs });
    const stuck = createWorkspace({ root: tmpDir(), logs });
    const onExit = process
      .listeners("exit")
      .find((l) => l.name === "_onExit") as () => void;
    assert.isFunction(onExit);
    const rmSync = fs.rmSync;
    sinon.stub(fs, "rmSync").callsFake((dir, opts) => {
      if (dir === stuck.dir) {
        throw Object.assign(new Error("busy"), { code: "EBUSY" });
      }
      rmSync(dir, opts);
    });
    onExit();
    sinon.restore();
    refute(fs.existsSync(kept.dir));
    assert(fs.existsSync(stuck.dir), "left for the next start-up's sweep");
    assert.isTrue(stuck.cleanup());
  });
});

"use strict";
import fs from "node:fs";
import path from "node:path";

import referee from "@sinonjs/referee";

import { SdkAnalyzer, scanImplementation } from "../../lib/prepare/analyze.js";
import { emitDeclarations } from "../../lib/prepare/bundle.js";
import { inspectSdk } from "../../lib/prepare/compat.js";
import {
  buildRecords,
  hintsForOperation,
} from "../../lib/prepare/method-records.js";
import { loadSpec } from "../../lib/prepare/spec.js";
import {
  MethodSearchIndex,
  authLine,
  processTerm,
  splitWords,
} from "../../lib/search/search-index.js";
import type { MethodRecord } from "../../lib/types.js";
import { SDK_726, SPEC, tmpDir } from "../helpers/paths.js";
import { BINDINGS, record } from "../helpers/prepared.js";

const { assert } = referee;

let records: MethodRecord[];

before(async function () {
  this.timeout(30000);
  const spec = await loadSpec(SPEC);
  const insp = inspectSdk(SDK_726);
  const types = path.join(tmpDir(), "types");
  emitDeclarations(insp.entry, types);
  const byKey = new Map(spec.operations.map((o) => [o.key, o]));
  const methods = new SdkAnalyzer(path.join(types, "index.d.ts")).analyze(
    scanImplementation(insp.apiFiles),
    (m, p) => hintsForOperation(byKey.get(`${m} ${p}`)),
  );
  records = buildRecords(spec, methods).records;
  assert(fs.existsSync(types));
});

describe("search-index - helpers", function () {
  it("should split identifiers into words", function () {
    assert.equals(splitWords("listPetVisits"), "list pet visits");
  });

  it("should stem terms so word forms meet", function () {
    assert.equals(processTerm("Cats"), "cat");
    assert.equals(processTerm("cat's"), "cat");
    assert.equals(processTerm("inventories"), processTerm("inventory"));
    assert.equals(processTerm("vaccinated"), processTerm("vaccination"));
    assert.equals(processTerm("visits"), processTerm("visit"));
    assert.equals(processTerm("listing"), "list");
  });

  it("should drop English stop words but keep API terms", function () {
    for (const w of ["the", "a", "of", "how", "me", "all", "with"]) {
      assert.equals(processTerm(w), null, w);
    }
    for (const w of ["get", "since", "before", "after", "between", "from"]) {
      assert.isString(processTerm(w), w);
    }
  });
});

describe("search-index - MethodSearchIndex.search", function () {
  it("should rank the relevant method first for natural queries", function () {
    const idx = new MethodSearchIndex(records);
    const all = () => true;
    assert.equals(
      idx.search("vet visits of a pet", { visible: all, limit: 3 }).hits[0].id,
      "PetsApi.listPetVisits",
    );
    assert.equals(
      idx.search("store inventory", { visible: all, limit: 3 }).hits[0].id,
      "StoreApi.getStoreInventory",
    );
    assert.equals(
      idx.search("register a new pet", { visible: all, limit: 3 }).hits[0].id,
      "PetsApi.createPet",
    );
    assert.equals(
      idx.search("get-store-inventory", { visible: all, limit: 1 }).hits[0].id,
      "StoreApi.getStoreInventory",
    );
    // Enum values of a filter parameter lead to the method that filters.
    for (const q of ["cats", "rabbits"]) {
      assert.equals(
        idx.search(q, { visible: all, limit: 3 }).hits[0].id,
        "PetsApi.listPets",
        q,
      );
    }
    // "since" is a stop word in prose but a parameter name here.
    assert.equals(
      idx.search("visits since a date", { visible: all, limit: 3 }).hits[0].id,
      "PetsApi.listPetVisits",
    );
    // Stemming joins word forms.
    assert.equals(
      idx.search("inventories", { visible: all, limit: 3 }).hits[0].id,
      "StoreApi.getStoreInventory",
    );
  });

  it("should return only methods available through the sdk binding", function () {
    const idx = new MethodSearchIndex(records);
    for (const h of idx.search("pet", { visible: () => true, limit: 20 })
      .hits) {
      const r = idx.get(h.id)!;
      assert.equals(h.sdkPath, `sdk.${r.className}.${r.methodName}`);
      assert.equals(h.signature, r.signature);
    }
  });

  it("should bound results and filter by visibility", function () {
    const idx = new MethodSearchIndex(records);
    const res = idx.search("pet", {
      visible: (r) => r.className !== "AdminApi",
      limit: 2,
    });
    assert.equals(res.hits.length, 2);
    assert.greater(res.total, 2);
    for (const h of idx.search("delete pet", {
      visible: (r) => r.className !== "AdminApi",
      limit: 20,
    }).hits) {
      assert.equals(h.id.startsWith("AdminApi"), false);
    }
  });

  it("should round-trip through its serialised form", function () {
    const idx = new MethodSearchIndex(records);
