"use strict";
/**
 * A prepared SDK and an executor that need neither a workspace nor Deno.
 */
import os from "node:os";
import path from "node:path";

import sinon from "sinon";

import type {
  ExecutionOutcome,
  ExecutionRequest,
  Executor,
} from "../../lib/executor/types.js";
import type { PreparedSdk } from "../../lib/prepare/prepare.js";
import { MethodSearchIndex } from "../../lib/search/search-index.js";
import type {
  MethodRecord,
  OperationBinding,
  PreparedSdkInfo,
} from "../../lib/types.js";
import { SCHEMES } from "./fakes.js";

export const BASE = "https://api.example.test/v1";

export const BINDINGS: OperationBinding[] = [
  {
    id: "PetsApi.listPets",
    className: "PetsApi",
    methodName: "listPets",
    httpMethod: "GET",
    path: "/pets",
    tags: ["pets"],
    security: [],
  },
  {
    id: "AdminApi.deletePet",
    className: "AdminApi",
    methodName: "deletePet",
    httpMethod: "DELETE",
    path: "/pets/{petId}",
    tags: ["admin"],
    security: [],
  },
];

/**
 * A method record; `overrides` replace any field.
 */
export function record(
  binding: OperationBinding,
  overrides: Partial<MethodRecord> = {},
): MethodRecord {
  return {
    id: binding.id,
    className: binding.className,
    methodName: binding.methodName,
    sdkPath: `sdk.${binding.id}`,
    operationId: binding.methodName,
    httpMethod: binding.httpMethod,
    path: binding.path,
    tags: binding.tags,
    summary: `Summary of ${binding.methodName}`,
    description: `Description of ${binding.methodName}`,
    deprecated: false,
    signature: `${binding.methodName}(): Promise<void>`,
    parameters: [],
    returnType: "Promise<void>",
    referencedTypes: [],
    requiredArguments: [],
    apiParameters: [
      {
        name: "limit",
        in: "query",
        required: false,
        description: "How many",
        schemaType: "integer",
      },
    ],
    responses: { "200": "ok" },
    auth: { alternatives: [], optional: true, unsupportedSchemes: [] },
    security: [],
    example: `return await ${`sdk.${binding.id}`}();`,
    ...overrides,
  };
}

/**
 * A prepared SDK without a workspace: the records are indexed in memory.
 */
export function prepared(
  opts: { records?: MethodRecord[]; servers?: string[] } = {},
): PreparedSdk {
  const records = opts.records ?? BINDINGS.map((b) => record(b));
  const info = {
    prepareId: "prep_1",
    api: {
      title: "Pet Clinic",
      version: "1.0.0",
      servers: opts.servers ?? [BASE],
      tags: [],
    },
    securitySchemes: { apiKeyHeader: SCHEMES.apiKeyHeader },
    operations: BINDINGS,
    unmappedOperations: [],
  } as unknown as PreparedSdkInfo;
  return {
    info,
    workspaceDir: path.join(os.tmpdir(), "oag-mcp-unit-workspace"),
    records,
    bindings: BINDINGS,
    index: new MethodSearchIndex(records),
    warnings: [],
    cleanup: () => true,
  };
}

/**
 * An executor whose outcome is scripted per test.
 */
export function executor(
  run: (
    req: ExecutionRequest,
  ) => Promise<Partial<ExecutionOutcome>> = async () => ({
    ok: true,
    result: 1,
  }),
): Executor & { execute: sinon.SinonSpy } {
  return {
    name: "fake",
    verify: async () => {},
    execute: sinon.spy(async (req: ExecutionRequest) => ({
      ok: false,
      logs: [],
      logsTruncated: false,
      stats: { durationMs: 1, sdkCalls: 0, terminated: false },
      ...(await run(req)),
    })),
  };
}

"use strict";
import referee from "@sinonjs/referee";
import * as jose from "jose";
import sinon from "sinon";

import { type Config, parseConfig } from "../../lib/config.js";
import {
  type HttpAuthenticator,
  createHttpAuthenticator,
  isLoopbackHost,
  scopesFromClaims,
} from "../../lib/server/authentication.js";
import { opaquePrincipalId } from "../../lib/server/authorization.js";
import { SecretRegistry } from "../../lib/util/redact.js";
import { SecretResolver } from "../../lib/util/secrets.js";
import { quietLogs } from "../helpers/fakes.js";

const { assert, match } = referee;

const ISSUER = "https://auth.example.test";
const RESOURCE = "https://mcp.example.test/mcp";
const JWKS_URI = `${ISSUER}/jwks`;
const INTROSPECT = `${ISSUER}/introspect`;
const env = {
  ALICE: "alice-token-0123456789",
  BOB: "bob-token-0123456789",
  WEAK: "short",
  ICID: "mcp server",
  ISEC: "introspect-secret-123",
};

type Route = (init: RequestInit) => Response | Promise<Response>;

/** Answer fetches by URL; anything else is a network failure. */
function serve(routes: Record<string, Route>) {
  return sinon
    .stub(globalThis, "fetch")
    .callsFake(async (input: string | URL | Request, init?: RequestInit) => {
      const url = String(input instanceof Request ? input.url : input);
      const route = routes[url];
      if (!route) {
        throw new TypeError(`fetch failed: ${url}`);
      }
      return route(init ?? {});
    });
}

function json(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { "content-type": "application/json" },
  });
}

async function setup(mcpAuth: unknown) {
  const { logs, records } = quietLogs();
  const registry = new SecretRegistry();
  const config: Config = parseConfig({ mcpAuth });
  const auth = await createHttpAuthenticator({
    config,
    resolver: new SecretResolver({ baseDir: process.cwd(), env }),
    registry,
    logs,
    resourceUrl: new URL(RESOURCE),
    resourceName: "Pet Clinic",
  });
  return { auth, logs, records, registry };
}

function request(authorization?: string, url = RESOURCE, method = "POST") {
  return new Request(url, {
    method,
    headers: authorization ? { authorization } : {},
  });
}

/** The reason of the last authentication failure audited. */
function lastReason(records: ReturnType<typeof quietLogs>["records"]) {
  return records()
    .filter((r) => r.event === "authentication.failed")
    .at(-1)
    ?.get("reason");
}

describe("authentication - scopesFromClaims", function () {
