describe("authentication - static-bearer", function () {
  const tokens = [
    { principal: "alice", token: { env: "ALICE" }, scopes: ["pets:read"] },
    { principal: "bob", token: { env: "BOB" } },
  ];

  it("should map a configured token to its principal", async function () {
    const { auth, logs, registry } = await setup({
      mode: "static-bearer",
      staticBearer: { tokens },
    });
    assert.isUndefined(auth.metadata(request()));
    const result = await auth.authenticate(
      request(`bearer ${env.BOB}  `),
      logs,
    );
    assert.isTrue(result.ok);
    if (result.ok) {
      assert.equals(result.principal, {
        id: "static:bob",
        kind: "static",
        name: "bob",
        scopes: [],
      });
      assert.equals(result.authInfo.token, "[static-bearer]");
      assert.equals(result.authInfo.clientId, "bob");
    }
    assert.equals(registry.scrubKnown(env.ALICE), "[REDACTED]");
  });

  it("should challenge a request without a bearer token", async function () {
    const { auth, logs, records } = await setup({
      mode: "static-bearer",
      staticBearer: { tokens },
    });
    for (const header of [undefined, `Basic ${env.ALICE}`, "Bearer a b"]) {
      const result = await auth.authenticate(request(header), logs);
      assert.isFalse(result.ok);
      if (!result.ok) {
        assert.equals(result.response.status, 401);
        assert.equals(
          result.response.headers.get("www-authenticate"),
          'Bearer realm="oag-mcp"',
        );
        assert.equals(await result.response.json(), {
          error: "unauthorized",
          error_description: "Bearer token required",
        });
      }
      assert.equals(lastReason(records), "missing_token");
    }
  });

  it("should challenge an unknown token as invalid", async function () {
    const { auth, logs, records } = await setup({
      mode: "static-bearer",
      staticBearer: { tokens },
    });
    const result = await auth.authenticate(
      request("Bearer not-a-configured-token"),
      logs,
    );
    assert.isFalse(result.ok);
    if (!result.ok) {
      assert.equals(
        result.response.headers.get("www-authenticate"),
        'Bearer realm="oag-mcp", error="invalid_token", error_description="The bearer token is invalid"',
      );
    }
    assert.equals(lastReason(records), "invalid_token");
  });

  it("should refuse a missing token list and weak tokens", async function () {
    await assert.rejects(
      setup({ mode: "static-bearer" }),
      match({ code: "MCP_AUTH_CONFIG_INVALID" }),
    );
    await assert.rejects(
      setup({
        mode: "static-bearer",
        staticBearer: { tokens: [{ principal: "w", token: { env: "WEAK" } }] },
      }),
      match({ code: "MCP_AUTH_TOKEN_WEAK" }),
    );
  });
});

describe("authentication - oauth configuration", function () {
  afterEach(function () {
    sinon.restore();
  });

  it("should refuse a missing oauth section and an insecure issuer", async function () {
    await assert.rejects(
      setup({ mode: "oauth" }),
      match({ code: "MCP_AUTH_CONFIG_INVALID" }),
    );
    await assert.rejects(
      setup({
        mode: "oauth",
        oauth: { issuer: "http://auth.example.test", jwksUri: JWKS_URI },
      }),
      match({ code: "MCP_AUTH_ISSUER_INSECURE" }),
    );
    for (const oauth of [
      { issuer: "http://127.0.0.1:9000", jwksUri: JWKS_URI },
      {
        issuer: "http://auth.example.test",
        jwksUri: JWKS_URI,
        allowInsecureIssuer: true,
      },
    ]) {
      assert.equals((await setup({ mode: "oauth", oauth })).auth.mode, "oauth");
    }
  });

  it("should serve protected resource metadata on GET and HEAD only", async function () {
    const { auth } = await setup({
      mode: "oauth",
      oauth: { issuer: ISSUER, jwksUri: JWKS_URI, requiredScopes: ["mcp"] },
    });
    const base =
      "https://mcp.example.test/.well-known/oauth-protected-resource";
    for (const url of [base, `${base}/mcp`]) {
      const res = auth.metadata(request(undefined, url, "GET"))!;
      assert.equals(res.status, 200);
      assert.equals(res.headers.get("cache-control"), "max-age=300");
      assert.equals(await res.json(), {
        resource: RESOURCE,
        authorization_servers: [ISSUER],
        scopes_supported: ["mcp"],
        bearer_methods_supported: ["header"],
        resource_name: "Pet Clinic",
      });
    }
    assert.equals(auth.metadata(request(undefined, base, "HEAD"))!.status, 200);
    const post = auth.metadata(request(undefined, base, "POST"))!;
    assert.equals(post.status, 405);
    assert.equals(post.headers.get("allow"), "GET, HEAD");
    assert.isUndefined(auth.metadata(request(undefined, RESOURCE, "GET")));
  });

  it("should discover the JWKS from authorization server metadata", async function () {
    const fetch = serve({
      [`${ISSUER}/.well-known/oauth-authorization-server`]: () =>
        json({ issuer: ISSUER, jwks_uri: JWKS_URI }),
    });
    const { records } = await setup({
      mode: "oauth",
      oauth: { issuer: ISSUER },
    });
    assert.equals(fetch.firstCall.args[1], { redirect: "error" });
    assert.equals(
      records()
        .find((r) => r.event === "authentication.mode_configured")!
        .get("validation"),
      "jwt",
    );
  });

  it("should fall back to OpenID configuration under the issuer's path", async function () {
    const issuer = `${ISSUER}/tenant/`;
    serve({
      [`${ISSUER}/.well-known/oauth-authorization-server/tenant`]: () =>
        json({}, 404),
      [`${ISSUER}/tenant/.well-known/openid-configuration`]: () =>
        json({ issuer, jwks_uri: JWKS_URI }),
    });
    assert.equals(
      (await setup({ mode: "oauth", oauth: { issuer } })).auth.mode,
      "oauth",
    );
  });

  it("should refuse metadata that names another issuer", async function () {
    serve({
      [`${ISSUER}/.well-known/oauth-authorization-server`]: () =>
        json({ issuer: "https://evil.example.test", jwks_uri: JWKS_URI }),
    });
    await assert.rejects(
      setup({ mode: "oauth", oauth: { issuer: ISSUER } }),
      match({ code: "MCP_AUTH_ISSUER_MISMATCH" }),
    );
  });

  it("should refuse an issuer whose JWKS cannot be discovered", async function () {
    serve({
      [`${ISSUER}/.well-known/oauth-authorization-server`]: () =>
        json({ issuer: ISSUER }),
    });
    await assert.rejects(
      setup({ mode: "oauth", oauth: { issuer: ISSUER } }),
      match({ code: "MCP_AUTH_JWKS_UNKNOWN" }),
    );
  });
});

describe("authentication - oauth with JWTs", function () {
  let signing: jose.GenerateKeyPairResult;
  let other: jose.GenerateKeyPairResult;

  before(async function () {
    signing = await jose.generateKeyPair("ES256");
    other = await jose.generateKeyPair("ES256");
  });

  beforeEach(async function () {
    const jwk = { ...(await jose.exportJWK(signing.publicKey)), kid: "k1" };
    serve({ [JWKS_URI]: () => json({ keys: [jwk] }) });
  });

  afterEach(function () {
    sinon.restore();
  });

  function sign(
    claims: jose.JWTPayload,
    opts: { key?: jose.CryptoKey; kid?: string; exp?: number | string } = {},
  ) {
    const jwt = new jose.SignJWT({
      iss: ISSUER,
      aud: RESOURCE,
      sub: "user-1",
      scope: "mcp pets:read",
      ...claims,
    }).setProtectedHeader({ alg: "ES256", kid: opts.kid ?? "k1" });
    if (opts.exp !== undefined) {
      jwt.setExpirationTime(opts.exp);
    }
    return jwt.sign(opts.key ?? signing.privateKey);
  }

  async function jwtAuth(oauth: Record<string, unknown> = {}) {
    return setup({
      mode: "oauth",
      oauth: { issuer: ISSUER, jwksUri: JWKS_URI, ...oauth },
    });
  }

  async function refused(
    auth: HttpAuthenticator,
    logs: ReturnType<typeof quietLogs>["logs"],
    header: string | undefined,
  ) {
    const result = await auth.authenticate(request(header), logs);
    assert.isFalse(result.ok);
    return result.ok ? undefined : result.response;
  }

  it("should accept a valid token and identify the caller opaquely", async function () {
    const { auth, logs, records, registry } = await jwtAuth({
      requiredScopes: ["mcp"],
    });
    const token = await sign({ client_id: "cli" }, { exp: "5m" });
    const result = await auth.authenticate(request(`Bearer ${token}`), logs);
    assert.isTrue(result.ok);
    if (result.ok) {
      assert.equals(
        result.principal.id,
        opaquePrincipalId("oauth", [ISSUER, "user-1"]),
      );
      assert.equals(result.principal.kind, "oauth");
      assert.equals(result.principal.clientId, "cli");
      assert.equals(result.principal.scopes, ["mcp", "pets:read"]);
      assert.equals(result.authInfo.resource, new URL(RESOURCE));
    }
    assert.equals(registry.scrubKnown(token), "[REDACTED]");
    assert.equals(
      records()
        .find((r) => r.event === "authentication.succeeded")!
        .get("scopeCount"),
      2,
    );
  });

  it("should take the client from azp, then sub, when there is no client_id", async function () {
    const { auth, logs } = await jwtAuth();
    const azp = await auth.authenticate(
      request(`Bearer ${await sign({ azp: "web" }, { exp: "5m" })}`),
      logs,
    );
    assert.equals(azp.ok && azp.principal.clientId, "web");
    const sub = await auth.authenticate(
      request(`Bearer ${await sign({}, { exp: "5m" })}`),
      logs,
    );
    assert.equals(sub.ok && sub.principal.clientId, "user-1");
  });

  it("should name why a token's claims or signature are refused", async function () {
    const { auth, logs, records } = await jwtAuth({ audience: [RESOURCE] });
    const now = Math.floor(Date.now() / 1000);
    const cases: Array<[string, Promise<string>]> = [
      ["expired", sign({}, { exp: now - 600 })],
      ["audience_mismatch", sign({ aud: "https://other.test" }, { exp: "5m" })],
      ["issuer_mismatch", sign({ iss: "https://other.test" }, { exp: "5m" })],
      ["not_yet_valid", sign({ nbf: now + 600 }, { exp: "5m" })],
      ["claim_exp_invalid", sign({})],
      ["invalid_signature", sign({}, { exp: "5m", key: other.privateKey })],
      ["unknown_signing_key", sign({}, { exp: "5m", kid: "k2" })],
    ];
    for (const [reason, token] of cases) {
      const res = await refused(auth, logs, `Bearer ${await token}`);
      assert.equals(res!.status, 401, reason);
      assert.equals(lastReason(records), reason);
    }
  });

  it("should refuse tokens that are malformed or use another algorithm", async function () {
    const { auth, logs, records } = await jwtAuth({ algorithms: ["RS256"] });
    await refused(auth, logs, `Bearer ${await sign({}, { exp: "5m" })}`);
    assert.equals(lastReason(records), "algorithm_not_allowed");
    const strict = await jwtAuth();
    await refused(strict.auth, strict.logs, "Bearer not.a-jwt");
    assert.equals(lastReason(strict.records), "malformed_token");
    const notClaims = await new jose.CompactSign(
      new TextEncoder().encode("[1]"),
    )
      .setProtectedHeader({ alg: "ES256", kid: "k1" })
      .sign(signing.privateKey);
    await refused(strict.auth, strict.logs, `Bearer ${notClaims}`);
    assert.equals(lastReason(strict.records), "malformed_token");
  });

  it("should name refusals that happen outside token validation", async function () {
    const { auth, logs, records } = await jwtAuth({
      requiredScopes: ["admin"],
    });
    assert.equals((await refused(auth, logs, undefined))!.status, 401);
    assert.equals(lastReason(records), "missing_token");
    await refused(auth, logs, "Basic abc");
    assert.equals(lastReason(records), "invalid_token");
    const scoped = await refused(
      auth,
      logs,
      `Bearer ${await sign({}, { exp: "5m" })}`,
    );
    assert.equals(scoped!.status, 403);
    assert.equals(lastReason(records), "insufficient_scope");
    // Inside jose's clock tolerance but past expiry for the MCP SDK.
    const lenient = await jwtAuth();
    const now = Math.floor(Date.now() / 1000);
    await refused(
      lenient.auth,
      lenient.logs,
      `Bearer ${await sign({}, { exp: now - 5 })}`,
    );
    assert.equals(lastReason(lenient.records), "expired");
  });

  it("should treat an unreachable JWKS as an invalid token", async function () {
    sinon.restore();
    serve({ [JWKS_URI]: () => json({}, 500) });
    const { auth, logs, records } = await jwtAuth();
    await refused(auth, logs, `Bearer ${await sign({}, { exp: "5m" })}`);
    assert.equals(lastReason(records), "invalid_token");
  });
});

describe("authentication - oauth with introspection", function () {
  let answer: Route;

  beforeEach(function () {
    answer = () => json({});
    serve({ [INTROSPECT]: (init) => answer(init) });
  });

  afterEach(function () {
    sinon.restore();
  });

  async function introspected(oauth: Record<string, unknown> = {}) {
    return setup({
      mode: "oauth",
      oauth: {
        issuer: ISSUER,
        introspection: {
          endpoint: INTROSPECT,
          clientId: { env: "ICID" },
          clientSecret: { env: "ISEC" },
        },
        ...oauth,
      },
    });
  }

  function active(data: Record<string, unknown> = {}) {
    return json({
      active: true,
      aud: [RESOURCE],
      exp: Math.floor(Date.now() / 1000) + 300,
      ...data,
    });
  }

  it("should accept an active token for this resource", async function () {
    let seen: RequestInit | undefined;
    answer = (init) => {
      seen = init;
      return active({ client_id: "cli", sub: "user-2", scope: "mcp" });
    };
    const { auth, logs, records, registry } = await introspected();
    const result = await auth.authenticate(request("Bearer opaque-1"), logs);
    assert.isTrue(result.ok);
    if (result.ok) {
      assert.equals(
        result.principal.id,
        opaquePrincipalId("oauth", [ISSUER, "user-2"]),
      );
      assert.equals(result.principal.clientId, "cli");
      assert.equals(result.principal.scopes, ["mcp"]);
    }
    const headers = seen!.headers as Record<string, string>;
    assert.equals(
      headers.authorization,
      `Basic ${Buffer.from("mcp%20server:introspect-secret-123").toString("base64")}`,
    );
    assert.equals(
      String(seen!.body),
      "token=opaque-1&token_type_hint=access_token",
    );
    assert.equals(seen!.redirect, "error");
    assert.equals(registry.scrubKnown(env.ISEC), "[REDACTED]");
    assert.equals(
      records()
        .find((r) => r.event === "authentication.mode_configured")!
        .get("validation"),
      "introspection",
    );
  });

  it("should accept a single audience string and fall back to sub or unknown", async function () {
    const { auth, logs } = await introspected({ audience: ["api://mcp"] });
    answer = () => active({ aud: "api://mcp", sub: "user-3" });
    const sub = await auth.authenticate(request("Bearer opaque-2"), logs);
    assert.equals(sub.ok && sub.principal.clientId, "user-3");
    answer = () => active({ aud: "api://mcp", iss: ISSUER });
    const unknown = await auth.authenticate(request("Bearer opaque-3"), logs);
    assert.equals(unknown.ok && unknown.principal.clientId, "unknown");
  });

  it("should name why an introspected token is refused", async function () {
    const { auth, logs, records } = await introspected();
    const cases: Array<[string, Record<string, unknown>]> = [
      ["inactive", { active: false }],
      ["issuer_mismatch", { iss: "https://other.test" }],
      ["audience_mismatch", { aud: "https://other.test" }],
      ["audience_mismatch", { aud: undefined }],
      ["expired", { exp: undefined }],
      ["expired", { exp: Math.floor(Date.now() / 1000) - 10 }],
    ];
    for (const [reason, data] of cases) {
      answer = () => active(data);
      const result = await auth.authenticate(request("Bearer opaque"), logs);
      assert.isFalse(result.ok, reason);
      assert.equals(lastReason(records), reason);
    }
  });

  it("should answer with a server error when introspection is unavailable", async function () {
    const { auth, logs, records } = await introspected();
    for (const respond of [
      () => {
        throw new TypeError("fetch failed");
      },
      () => json({ error: "nope" }, 503),
      () => new Response("not json"),
    ]) {
      answer = respond;
      const result = await auth.authenticate(request("Bearer opaque"), logs);
      assert.isFalse(result.ok);
      if (!result.ok) {
        assert.equals(result.response.status, 500);
      }
      assert.equals(lastReason(records), "server_error");
    }
  });
});

"use strict";
import referee from "@sinonjs/referee";

import {
  AuthorizationPolicy,
  matchesOperation,
  opaquePrincipalId,
} from "../../lib/server/authorization.js";
import type { OperationBinding, Principal } from "../../lib/types.js";

const { assert, refute } = referee;

const op = (
  id: string,
  extra: Partial<OperationBinding> = {},
): OperationBinding => ({
  id,
  className: id.split(".")[0],
  methodName: id.split(".")[1],
  httpMethod: "GET",
  path: "/x",
  tags: [],
  security: [],
  ...extra,
});

const reader: Principal = {
  id: "static:reader",
  kind: "static",
  name: "reader",
  scopes: ["pets:read"],
};
const admin: Principal = {
  id: "static:admin",
  kind: "static",
  name: "admin",
  scopes: ["pets:read", "admin"],
};

describe("authorization - matchesOperation", function () {
  it("should match globs, tags, methods and operationIds", function () {
    assert.isTrue(matchesOperation("PetsApi.*", op("PetsApi.listPets")));
    assert.isTrue(matchesOperation("*.list*", op("PetsApi.listPets")));
    refute(matchesOperation("PetsApi.get*", op("PetsApi.listPets")));
    assert.isTrue(
      matchesOperation("tag:pets", op("PetsApi.listPets", { tags: ["pets"] })),
    );
    assert.isTrue(matchesOperation("method:get", op("PetsApi.listPets")));
    refute(matchesOperation("method:DELETE", op("PetsApi.listPets")));
    assert.isTrue(
      matchesOperation(
        "operationId:list-*",
        op("PetsApi.listPetVisits", { operationId: "list-pet-visits" }),
      ),
    );
    refute(matchesOperation("PetsApi.list.Pets", op("PetsApi.listPets")));
  });
});

describe("authorization - AuthorizationPolicy.decide", function () {
  it("should allow everything with an implicit policy when none is configured", function () {
    const p = new AuthorizationPolicy();
    const d = p.decide(reader, op("AdminApi.deletePet"));
    assert.isTrue(d.allowed);
    assert.equals(d.policyId, "implicit-allow-all");
  });

  it("should apply allow rules by scope and deny by default", function () {
    const p = new AuthorizationPolicy({
      default: "deny",
      rules: [
        {
          id: "readers",
          scopes: ["pets:read"],
          allow: ["method:GET"],
          deny: [],
        },
        { id: "admins", principals: ["admin"], allow: ["*"], deny: [] },
      ],
    });
    assert.isTrue(p.decide(reader, op("PetsApi.listPets")).allowed);
    const denied = p.decide(
      reader,
      op("AdminApi.deletePet", { httpMethod: "DELETE" }),
    );
    assert.isFalse(denied.allowed);
    assert.equals(denied.policyId, "default");
    assert.isTrue(
      p.decide(admin, op("AdminApi.deletePet", { httpMethod: "DELETE" }))
        .allowed,
    );
  });

  it("should let deny rules win over allow rules", function () {
    const p = new AuthorizationPolicy({
      default: "allow",
      rules: [
        {
          id: "no-admin",
          principals: ["*"],
          allow: ["*"],
          deny: ["AdminApi.*"],
        },
      ],
    });
    const d = p.decide(admin, op("AdminApi.deletePet"));
    assert.isFalse(d.allowed);
    assert.equals(d.policyId, "no-admin");
    assert.equals(d.reason, "rule_deny");
  });

  it("should match client ids for OAuth principals", function () {
    const p = new AuthorizationPolicy({
      default: "deny",
      rules: [
        { id: "app", clientIds: ["app-1"], allow: ["PetsApi.*"], deny: [] },
      ],
    });
    const oauth: Principal = {
      id: "oauth:abc",
      kind: "oauth",
      clientId: "app-1",
      scopes: [],
    };
    assert.isTrue(p.decide(oauth, op("PetsApi.listPets")).allowed);
    assert.isFalse(
      p.decide({ ...oauth, clientId: "app-2" }, op("PetsApi.listPets")).allowed,
    );
  });
});

describe("authorization - opaquePrincipalId", function () {
  it("should be stable and not reveal the subject", function () {
    const a = opaquePrincipalId("oauth", [
      "https://issuer",
      "alice@example.com",
    ]);
    assert.equals(
      a,
      opaquePrincipalId("oauth", ["https://issuer", "alice@example.com"]),
    );
    refute.contains(a, "alice");
    assert.match(a, /^oauth:[0-9a-f]{16}$/);
  });
});

describe("authorization - AuthorizationPolicy.decide scopes", function () {
  it("should not apply a rule to principals missing any of its scopes", function () {
    const policy = new AuthorizationPolicy({
      default: "deny",
      rules: [
        {
          id: "admins",
          scopes: ["pets:read", "admin"],
          allow: ["*"],
          deny: [],
        },
      ],
    });
    assert.isFalse(policy.decide(reader, op("AdminApi.deletePet")).allowed);
    assert.isTrue(policy.decide(admin, op("AdminApi.deletePet")).allowed);
  });
});

"use strict";
import http from "node:http";
import net from "node:net";
import path from "node:path";
import { PassThrough } from "node:stream";

import {
  Client,
  StreamableHTTPClientTransport,
} from "@modelcontextprotocol/client";
import referee from "@sinonjs/referee";
import sinon from "sinon";

import { type Config, parseConfig } from "../../lib/config.js";
import type { PreparedSdk } from "../../lib/prepare/prepare.js";
import {
  type RunningServer,
  type ServeOptions,
  mcpRequestHandler,
  serve,
  servePrepared,
} from "../../lib/server/serve.js";
import { OagMcpService } from "../../lib/server/service.js";
import { quietLogs } from "../helpers/fakes.js";
import { tmpDir } from "../helpers/paths.js";
import { executor, prepared } from "../helpers/prepared.js";

const { assert, refute, match } = referee;

const ALICE = "alice-token-0123456789";

interface Started {
  running: RunningServer;
  sdk: PreparedSdk & { cleanup: sinon.SinonSpy };
  records: ReturnType<typeof quietLogs>["records"];
}

function config(raw: Record<string, unknown> = {}): Config {
  return parseConfig({
    upstream: { baseUrl: "https://api.example.test/v1" },
    execution: { typecheck: false },
    ...raw,
    http: { port: 0, ...(raw.http as Record<string, unknown>) },
  });
}

function options(
  cfg: Config,
  logs: ServeOptions["logs"],
  extra: Partial<ServeOptions> = {},
): ServeOptions {
  return {
    transport: "streamable-http",
    spec: "unused",
    sdk: "unused",
    config: cfg,
    configBaseDir: process.cwd(),
    logs,
    executor: executor(),
    ...extra,
  };
}

function fakeSdk(): Started["sdk"] {
  const sdk = prepared();
  return { ...sdk, cleanup: sinon.spy(() => true) };
}

async function start(
  raw: Record<string, unknown> = {},
  extra: Partial<ServeOptions> = {},
): Promise<Started> {
  const { logs, records } = quietLogs();
  const sdk = fakeSdk();
  const running = await servePrepared(sdk, options(config(raw), logs, extra));
  return { running, sdk, records };
}

/** A raw HTTP request, so the Host header and request target are ours. */
function rawRequest(
  url: string,
  opts: {
    method?: string;
    path?: string;
    headers?: Record<string, string>;
    body?: string;
  } = {},
): Promise<{
  status: number;
  headers: http.IncomingHttpHeaders;
  body: string;
}> {
  const u = new URL(url);
  return new Promise((resolve, reject) => {
    const req = http.request(
      {
        host: u.hostname.replace(/^\[|\]$/g, ""),
        port: u.port,
        method: opts.method ?? "GET",
        path: opts.path ?? u.pathname + u.search,
        headers: opts.headers,
      },
      (res) => {
        let body = "";
        res.setEncoding("utf8");
        res.on("data", (c: string) => (body += c));
        res.on("end", () =>
          resolve({ status: res.statusCode!, headers: res.headers, body }),
        );
      },
    );
    req.on("error", reject);
    req.end(opts.body);
  });
}

async function connect(url: string, token?: string): Promise<Client> {
  const client = new Client({ name: "unit", version: "1" });
  await client.connect(
    new StreamableHTTPClientTransport(new URL(url), {
      requestInit: token
        ? { headers: { authorization: `Bearer ${token}` } }
        : undefined,
    }),
  );
  return client;
}

function events(records: Started["records"]): string[] {
  return records().map((r) => r.event);
}

describe("serve - servePrepared over Streamable HTTP", function () {
  this.timeout(20000);
  let started: Started | undefined;

  afterEach(async function () {
    sinon.restore();
    await started?.running.close();
    started = undefined;
  });

  it("should serve the tools to an MCP client and answer health checks", async function () {
    started = await start();
    const { running, sdk, records } = started;
    assert.equals(running.transport, "streamable-http");
    assert.match(running.url!, /^http:\/\/127\.0\.0\.1:\d+\/mcp$/);
    const client = await connect(running.url!);
    const tools = await client.listTools();
    assert.equals(tools.tools.map((t) => t.name).sort(), ["execute", "search"]);
    await client.close();
    const health = await fetch(new URL("/healthz", running.url));
    assert.equals(await health.json(), { status: "ok" });
    const ready = records().find((r) => r.event === "server.ready")!;
    assert.equals(ready.get("methods"), 2);
    assert.equals(
      records()
        .find((r) => r.event === "transport.initialized")!
        .get("mcpAuthMode"),
      "none",
    );
    const closing = running.close();
    assert.same(running.close(), closing);
    await closing;
    started = undefined;
    assert.equals(sdk.cleanup.callCount, 1);
    assert.contains(events(records), "prepare.workspace.cleaned");
    assert.contains(events(records), "server.stopped");
  });

  it("should refuse tokens in the URL and answer unknown paths with 404", async function () {
    started = await start();
    const { running, records } = started;
    const inUrl = await fetch(`${running.url}?access_token=abc`);
    assert.equals(inUrl.status, 400);
    assert.equals(
      ((await inUrl.json()) as { error: string }).error,
      "invalid_request",
    );
    assert.equals(
      (await fetch(new URL("/mcp?token=abc", running.url))).status,
      400,
    );
    assert.contains(events(records), "authentication.token_in_url_rejected");
    const missing = await fetch(new URL("/elsewhere", running.url));
    assert.equals(missing.status, 404);
    assert.equals(await missing.json(), { error: "not_found" });
  });

  it("should refuse requests for other hosts and from other origins on loopback", async function () {
    started = await start();
    const { running, records } = started;
    const host = await rawRequest(running.url!, {
      headers: { host: "evil.example.test" },
    });
    assert.equals(host.status, 403);
    const origin = await rawRequest(running.url!, {
      headers: { origin: "https://evil.example.test" },
    });
    assert.equals(origin.status, 403);
    const denied = records().filter((r) =>
      ["transport.host_rejected", "transport.origin_rejected"].includes(
        r.event,
      ),
    );
    assert.equals(
      denied.map((r) => [r.event, r.get("httpMethod"), r.get("reason")]),
      [
        ["transport.host_rejected", "GET", "host_not_allowed"],
        ["transport.origin_rejected", "GET", "origin_not_allowed"],
      ],
    );
  });

  it("should admit exactly the configured origins, and requests without one", async function () {
    started = await start({
      http: {
        allowedOrigins: ["https://app.example.test", "http://localhost:5173/"],
      },
    });
    const health = new URL("/healthz", started.running.url).toString();
    const status = async (origin?: string) =>
      (await rawRequest(health, origin ? { headers: { origin } } : {})).status;
    assert.equals(await status(), 200, "no Origin: a non-browser client");
    for (const ok of [
      "https://app.example.test",
      "https://app.example.test:443",
      "http://localhost:5173",
    ]) {
      assert.equals(await status(ok), 200, ok);
    }
    for (const refused of [
      "http://app.example.test",
      "https://app.example.test:8443",
      "https://evil.test",
      "http://localhost:3000",
      "http://127.0.0.1:5173",
      "null",
    ]) {
      assert.equals(await status(refused), 403, refused);
    }
    const res = await rawRequest(health, {
      headers: { origin: "https://evil.test" },
    });
    assert.equals(JSON.parse(res.body).error.message, "Origin not allowed");
  });

  it("should accept configured hosts as well as localhost names on loopback", async function () {
    started = await start({ http: { allowedHosts: ["mcp.example.test"] } });
    const health = new URL("/healthz", started.running.url).toString();
    const status = async (host: string) =>
      (await rawRequest(health, { headers: { host } })).status;
    assert.equals(await status("mcp.example.test"), 200);
    assert.equals(await status("mcp.example.test:8080"), 200);
    assert.equals(await status(new URL(health).host), 200);
    assert.equals(await status("localhost"), 200);
    assert.equals(await status("evil.example.test"), 403);
  });

  it("should relay authentication challenges and serve authenticated callers", async function () {
    process.env.OAG_MCP_UNIT_ALICE = ALICE;
    try {
      started = await start({
        mcpAuth: {
          mode: "static-bearer",
          staticBearer: {
            tokens: [
              { principal: "alice", token: { env: "OAG_MCP_UNIT_ALICE" } },
            ],
          },
        },
      });
    } finally {
      delete process.env.OAG_MCP_UNIT_ALICE;
    }
    const { running, records } = started;
    const challenged = await fetch(running.url!, { method: "POST" });
    assert.equals(challenged.status, 401);
    assert.match(
      challenged.headers.get("www-authenticate")!,
      /^Bearer realm="oag-mcp"/,
    );
    const client = await connect(running.url!, ALICE);
    assert.equals((await client.listTools()).tools.length, 2);
    await client.close();
    const ok = records().find((r) => r.event === "authentication.succeeded")!;
    assert.equals(ok.principalId, "static:alice");
    assert.match(String(ok.requestId), /^req_/);
  });

  it("should serve protected resource metadata for the public URL", async function () {
    started = await start({
      http: { publicUrl: "https://mcp.example.test/mcp" },
      mcpAuth: {
        mode: "oauth",
        oauth: {
          issuer: "https://auth.example.test",
          jwksUri: "https://auth.example.test/jwks",
        },
      },
    });
    const res = await fetch(
      new URL("/.well-known/oauth-protected-resource", started.running.url),
    );
    assert.equals(res.status, 200);
    assert.equals(
      ((await res.json()) as { resource: string }).resource,
      "https://mcp.example.test/mcp",
    );
  });

  it("should answer a server error when a request cannot be routed", async function () {
    started = await start();
    const { running, records } = started;
    const res = await rawRequest(running.url!, { path: "http://[bad" });
    assert.equals(res.status, 500);
    assert.equals(JSON.parse(res.body), { error: "server_error" });
    const failed = records().find(
      (r) => r.event === "transport.request_failed",
    )!;
    assert.equals(failed.get("error"), "TypeError");
  });

  it("should drop connections that do not speak HTTP", async function () {
    started = await start();
    const { running, records } = started;
    const u = new URL(running.url!);
    await new Promise<void>((resolve) => {
      const socket = net.connect(Number(u.port), u.hostname, () =>
        socket.write("NOT HTTP\r\n\r\n"),
      );
      socket.on("close", () => resolve());
      socket.on("error", () => resolve());
      socket.resume();
    });
    assert.contains(events(records), "transport.connection_failed");
  });

  it("should log requests the MCP handler rejects", async function () {
    started = await start();
    const { running, records } = started;
    const res = await rawRequest(running.url!, {
      method: "POST",
      headers: {
        "content-type": "application/json",
        accept: "application/json, text/event-stream",
        "mcp-protocol-version": "2099-01-01",
      },
      body: JSON.stringify({ jsonrpc: "2.0", id: 1, method: "tools/list" }),
    });
    assert.equals(res.status, 400);
    assert.contains(events(records), "transport.request_failed");
  });

  it("should refuse an oversized request body", async function () {
    started = await start();
    const res = await rawRequest(started.running.url!, {
      method: "POST",
      headers: {
        "content-type": "application/json",
        accept: "application/json, text/event-stream",
      },
      body: "x".repeat(2 * 1024 * 1024),
    });
    assert.equals(res.status, 413);
  });
});

describe("serve - servePrepared on non-loopback addresses", function () {
  this.timeout(20000);
  // 127.0.0.1 in decimal: reachable only locally, but not one of the names
  // oag-mcp treats as loopback.
  const HOST = "2130706433";
  let started: Started | undefined;

  afterEach(async function () {
    sinon.restore();
    await started?.running.close();
    started = undefined;
  });

  function bearer(http: Record<string, unknown> = {}) {
    process.env.OAG_MCP_UNIT_ALICE = ALICE;
    return start({
      http: { host: HOST, ...http },
      mcpAuth: {
        mode: "static-bearer",
        staticBearer: {
          tokens: [
            { principal: "alice", token: { env: "OAG_MCP_UNIT_ALICE" } },
          ],
        },
      },
    }).finally(() => delete process.env.OAG_MCP_UNIT_ALICE);
  }

  it("should refuse to serve unauthenticated callers, and clean up", async function () {
    const { logs, records } = quietLogs();
    const sdk = fakeSdk();
    await assert.rejects(
      servePrepared(sdk, options(config({ http: { host: HOST } }), logs)),
      match({ code: "MCP_AUTH_REQUIRED" }),
    );
    assert.equals(sdk.cleanup.callCount, 1);
    assert.contains(
      events(records),
      "security.unauthenticated_nonloopback_refused",
    );
  });

  it("should warn about remote exposure and refuse every cross-origin request", async function () {
    started = await bearer();
    const { running, records } = started;
    assert.match(running.url!, /^http:\/\/127\.0\.0\.1:\d+\/mcp$/);
    assert.contains(events(records), "transport.remote_exposure");
    const health = new URL("/healthz", running.url).toString();
    const anyHost = await rawRequest(health, {
      headers: { host: "anything.example.test" },
    });
    assert.equals(anyHost.status, 200);
    const origin = await rawRequest(health, {
      headers: { origin: "https://app.example.test" },
    });
    assert.equals(origin.status, 403);
  });

  it("should log a request the MCP transport cannot convert", async function () {
    started = await bearer();
    const { running, records } = started;
    const res = await rawRequest(running.url!, {
      method: "POST",
      headers: {
        host: "bad host",
        authorization: `Bearer ${ALICE}`,
        "content-type": "application/json",
        accept: "application/json, text/event-stream",
      },
      body: "{}",
    });
    assert.equals(res.status, 500);
    assert.contains(events(records), "transport.error");
  });

  it("should check the Host header against configured hosts", async function () {
    started = await bearer({ allowedHosts: ["mcp.example.test"] });
    const health = new URL("/healthz", started.running.url).toString();
    assert.equals(
      (await rawRequest(health, { headers: { host: "mcp.example.test" } }))
        .status,
      200,
    );
    assert.equals(
      (await rawRequest(health, { headers: { host: "evil.example.test" } }))
        .status,
      403,
    );
  });
});

describe("serve - servePrepared start-up failures", function () {
  this.timeout(20000);

  afterEach(function () {
    sinon.restore();
  });

  it("should audit an invalid authentication configuration and clean up", async function () {
    const { logs, records } = quietLogs();
    const sdk = fakeSdk();
    await assert.rejects(
      servePrepared(
        sdk,
        options(config({ mcpAuth: { mode: "static-bearer" } }), logs),
      ),
      match({ code: "MCP_AUTH_CONFIG_INVALID" }),
    );
    assert.equals(sdk.cleanup.callCount, 1);
    assert.equals(
      records()
        .find((r) => r.event === "security.config_invalid")!
        .get("errorCode"),
      "MCP_AUTH_CONFIG_INVALID",
    );
  });

  it("should fail when the port is taken, and clean up", async function () {
    const blocker = net.createServer();
    await new Promise<void>((r) => blocker.listen(0, "127.0.0.1", r));
    try {
      const { port } = blocker.address() as net.AddressInfo;
      const { logs } = quietLogs();
      const sdk = fakeSdk();
      await assert.rejects(
        servePrepared(sdk, options(config({ http: { port } }), logs)),
        match({ code: "EADDRINUSE" }),
      );
      assert.equals(sdk.cleanup.callCount, 1);
    } finally {
      blocker.close();
    }
  });

  it("should not start a transport once start-up is cancelled", async function () {
    const { logs, records } = quietLogs();
    const sdk = fakeSdk();
    const abort = new AbortController();
    // The shutdown signal arrives as the executor stage completes.
    const op = logs.op.bind(logs);
    sinon.stub(logs, "op").callsFake((level, event, fields) => {
      op(level, event, fields);
      if (event === "prepare.stage.completed") {
        abort.abort();
      }
    });
    await assert.rejects(
      servePrepared(sdk, options(config(), logs, { signal: abort.signal })),
      match({ code: "STARTUP_ABORTED" }),
    );
    assert.equals(sdk.cleanup.callCount, 1);
    refute.contains(events(records), "transport.initialized");
  });
});

describe("serve - servePrepared over stdio", function () {
  this.timeout(20000);

  it("should speak MCP on the given streams as the configured local principal", async function () {
    const stdin = new PassThrough();
    const stdout = new PassThrough();
    const replies: Array<Record<string, unknown>> = [];
    let buffer = "";
    stdout.on("data", (c: Buffer) => {
      buffer += c.toString("utf8");
      let i;
      while ((i = buffer.indexOf("\n")) >= 0) {
        replies.push(JSON.parse(buffer.slice(0, i)));
        buffer = buffer.slice(i + 1);
      }
    });
    const next = async (count: number) => {
      while (replies.length < count) {
        await new Promise((r) => setTimeout(r, 10));
      }
      return replies[count - 1];
    };
    const { logs, records } = quietLogs();
    const sdk = fakeSdk();
    const running = await servePrepared(
      sdk,
      options(config({ mcpAuth: { stdio: { principal: "dev" } } }), logs, {
        transport: "stdio",
        stdio: { stdin, stdout },
      }),
    );
    try {
      assert.equals(running.transport, "stdio");
      assert.isUndefined(running.url);
      const send = (m: unknown) => stdin.write(`${JSON.stringify(m)}\n`);
      send({
        jsonrpc: "2.0",
        id: 1,
        method: "initialize",
        params: {
          protocolVersion: "2025-06-18",
          capabilities: {},
          clientInfo: { name: "unit", version: "1" },
        },
      });
      assert.equals((await next(1)).id, 1);
      send({ jsonrpc: "2.0", method: "notifications/initialized" });
      send({ jsonrpc: "2.0", id: 2, method: "tools/list" });
      const list = (await next(2)) as { result: { tools: unknown[] } };
      assert.equals(list.result.tools.length, 2);
      stdin.emit("error", new Error("stdin failed"));
    } finally {
      await running.close();
    }
    const ok = records().find((r) => r.event === "authentication.succeeded")!;
    assert.equals(ok.principalId, "local:dev");
    assert.contains(events(records), "transport.error");
    assert.equals(sdk.cleanup.callCount, 1);
  });
});

describe("serve - serve", function () {
  it("should not serve when preparation fails", async function () {
    const { logs } = quietLogs();
    await assert.rejects(
      serve({
        ...options(config(), logs),
        spec: path.join(tmpDir(), "missing.yaml"),
        sdk: tmpDir(),
      }),
    );
  });
});

describe("serve - mcpRequestHandler", function () {
  it("should refuse a request that arrives without an authenticated principal", async function () {
    const { logs, records } = quietLogs();
    const svc = await OagMcpService.create({
      prepared: prepared(),
      config: config(),
      configBaseDir: process.cwd(),
      logs,
      executor: executor(),
    });
    const handler = mcpRequestHandler(svc, logs);
    try {
      const res = await handler.fetch(
        new Request("http://127.0.0.1/mcp", {
          method: "POST",
          headers: {
            "content-type": "application/json",
            accept: "application/json, text/event-stream",
          },
          body: JSON.stringify({
            jsonrpc: "2.0",
            id: 1,
            method: "initialize",
            params: {
              protocolVersion: "2025-06-18",
              capabilities: {},
              clientInfo: { name: "unit", version: "1" },
            },
          }),
        }),
      );
      assert.equals(res.status, 500);
    } finally {
      await handler.close();
    }
    const failed = records().find(
      (r) => r.event === "transport.request_failed",
    )!;
    assert.equals(failed.get("error"), "Error");
  });
});

