/** The full set of frozen 2026-07-28 wire schemas, as one built object (the memo target). */
export type Rev2026WireSchemas = ReturnType<typeof build>;

let memo: Rev2026WireSchemas | undefined;

/**
 * Builds the era wire-schema set on first call and returns the same object
 * thereafter. Module evaluation stays construction-free so importing the
 * era codec/registry costs nothing until the first validation actually
 * needs a schema; the registry, the codec, and the eager `schemas.ts`
 * shim all pull through this memo, so reference identity holds across
 * every consumer.
 */
export function buildSchemas2026(): Rev2026WireSchemas {
    return (memo ??= build());
}
/**
 * Cache-hint plumbing for cacheable results (protocol revision 2026-07-28).
 *
 * The 2026-07-28 revision requires `ttlMs`/`cacheScope` on the cacheable
 * result types (SEP-2549 `CacheableResult`). The values are resolved at the
 * era-aware encode seam (the 2026 wire codec's `encodeResult`), most specific
 * author first:
 *
 *   1. fields the handler returned on the result itself (when valid),
 *   2. a configured cache hint attached by the server layer
 *      (per-registration hint, then the server-level per-operation hint,
 *      combined per field — see {@linkcode attachCacheHintFallback}),
 *   3. the conservative defaults `{ ttlMs: 0, cacheScope: 'private' }`.
 *
 * The configured hint travels from the (era-blind) server configuration to the
 * (era-aware) encode seam on a symbol-keyed property of the result object —
 * {@linkcode RESULT_CACHE_HINT_FALLBACK}. Symbol-keyed properties are never
 * serialized to JSON, so attaching a hint can never change what a 2025-era
 * response looks like on the wire: only the 2026-era codec reads (and removes)
 * it while filling the required fields. The 2025-era codec has no cache code
 * path at all.
 */

/** The cache scopes defined for cacheable results (SEP-2549). */
export type CacheScope = 'public' | 'private';

/**
 * A cache hint for a cacheable result (protocol revision 2026-07-28): the
 * values to emit for `ttlMs` / `cacheScope` when the handler does not provide
 * them itself. Absent fields fall back to the conservative defaults
 * (`ttlMs: 0`, `cacheScope: 'private'`).
 */
export interface CacheHint {
    /** Cache lifetime in milliseconds. Must be a non-negative safe integer. */
    ttlMs?: number;
    /** Whether the result may be cached by shared caches (`public`) or only by the requesting client (`private`). */
    cacheScope?: CacheScope;
}

/**
 * The operations whose results are cacheable on the 2026-07-28 revision (the
 * `CacheableResult` extenders). This list is closed: no other operation's
 * result ever receives cache fields from the SDK.
 */
export const CACHEABLE_RESULT_METHODS = [
    'tools/list',
    'prompts/list',
    'resources/list',
    'resources/templates/list',
    'resources/read',
    'server/discover'
] as const;

/** A method whose result is cacheable on the 2026-07-28 revision. */
export type CacheableResultMethod = (typeof CACHEABLE_RESULT_METHODS)[number];

/** Whether the given method's result is cacheable on the 2026-07-28 revision. */
export function isCacheableResultMethod(method: string): method is CacheableResultMethod {
    return (CACHEABLE_RESULT_METHODS as readonly string[]).includes(method);
}

/**
 * The symbol-keyed carrier for a configured cache hint on a result object.
 * Symbol properties are invisible to JSON serialization, so the carrier can be
 * attached era-blind: only the 2026-era encode seam consumes it.
 */
export const RESULT_CACHE_HINT_FALLBACK: unique symbol = Symbol('modelcontextprotocol.resultCacheHintFallback');

/** A result object that may carry a configured cache-hint fallback. */
interface CacheHintCarrier {
    [RESULT_CACHE_HINT_FALLBACK]?: CacheHint;
}

/**
 * Attaches a configured cache hint to a result as the encode-time fallback.
 * Returns the result unchanged when there is nothing to attach. When a more
 * specific hint is already attached, the two hints are combined per field
 * (most-specific-author-wins for each of `ttlMs` and `cacheScope`): the
 * per-registration hint attached by the feature layer keeps every field it
 * sets, and the server-level per-operation hint only fills the fields the
 * more specific hint leaves unset.
 */
export function attachCacheHintFallback<T extends object>(result: T, hint: CacheHint | undefined): T {
    if (hint === undefined) {
        return result;
    }
    const attached = (result as CacheHintCarrier)[RESULT_CACHE_HINT_FALLBACK];
    if (attached === undefined) {
        return { ...result, [RESULT_CACHE_HINT_FALLBACK]: hint };
    }
    const merged: CacheHint = {};
    const ttlMs = attached.ttlMs ?? hint.ttlMs;
    if (ttlMs !== undefined) {
        merged.ttlMs = ttlMs;
    }
    const cacheScope = attached.cacheScope ?? hint.cacheScope;
    if (cacheScope !== undefined) {
        merged.cacheScope = cacheScope;
    }
    return { ...result, [RESULT_CACHE_HINT_FALLBACK]: merged };
}

/** Reads the configured cache-hint fallback attached to a result, if any. */
export function cacheHintFallbackOf(result: object): CacheHint | undefined {
    return (result as CacheHintCarrier)[RESULT_CACHE_HINT_FALLBACK];
}

/**
 * Whether a value is a valid `ttlMs`: a non-negative safe integer. Safe
 * integers are required because the wire schemas validate `ttlMs` as an
 * integer within `Number.MIN_SAFE_INTEGER`/`Number.MAX_SAFE_INTEGER`; a value
 * outside that range is treated as invalid here so it falls through to the
 * next author instead of being emitted and rejected downstream.
 */
export function isValidCacheTtlMs(value: unknown): value is number {
    return typeof value === 'number' && Number.isSafeInteger(value) && value >= 0;
}

/** Whether a value is a valid `cacheScope`. */
export function isValidCacheScope(value: unknown): value is CacheScope {
    return value === 'public' || value === 'private';
}

/**
 * Validates a configured cache hint at configuration time. Throws a
 * `RangeError` naming the offending field, so misconfiguration fails at
 * startup/registration rather than silently degrading at encode time.
 */
export function assertValidCacheHint(hint: CacheHint, context: string): void {
    if (hint.ttlMs !== undefined && !isValidCacheTtlMs(hint.ttlMs)) {
        throw new RangeError(`Invalid cache hint for ${context}: ttlMs must be a non-negative safe integer (got ${String(hint.ttlMs)})`);
    }
    if (hint.cacheScope !== undefined && !isValidCacheScope(hint.cacheScope)) {
        throw new RangeError(
            `Invalid cache hint for ${context}: cacheScope must be 'public' or 'private' (got ${String(hint.cacheScope)})`
        );
    }
}
/**
 * Error codes for protocol errors that cross the wire as JSON-RPC error responses.
 * These follow the JSON-RPC specification and MCP-specific extensions.
 */
export enum ProtocolErrorCode {
    // Standard JSON-RPC error codes
    ParseError = -32_700,
    InvalidRequest = -32_600,
    MethodNotFound = -32_601,
    InvalidParams = -32_602,
    InternalError = -32_603,

    // MCP-specific error codes
    /**
     * Resource not found.
     *
     * Receive-tolerated only: the SDK never EMITS `-32002` — `resources/read`
     * misses answer `-32602` (Invalid Params) on every protocol revision per
     * the 2026-07-28 spec MUST, and a handler-thrown `-32002` is mapped to
     * `-32602` at the era encode seam. The member stays importable so clients
     * can recognise `-32002` from peers built on earlier SDK releases (the
     * spec's "clients SHOULD also accept `-32002`" backwards-compatibility
     * clause). Throw `ResourceNotFoundError` instead.
     */
    ResourceNotFound = -32_002,
    /**
     * Processing the request requires a capability the client did not declare
     * in the request's `clientCapabilities` (protocol revision 2026-07-28).
     */
    MissingRequiredClientCapability = -32_021,
    /**
     * The request's protocol version is unknown to the server or unsupported
     * by it (protocol revision 2026-07-28).
     */
    UnsupportedProtocolVersion = -32_022,
    UrlElicitationRequired = -32_042
}
import { brandedHasInstance, stampErrorBrands } from '../errors/crossBundleBrand';
import { ProtocolErrorCode } from './enums';
import type {
    ClientCapabilities,
    ElicitRequestURLParams,
    MissingRequiredClientCapabilityErrorData,
    UnsupportedProtocolVersionErrorData
} from './types';

/**
 * Protocol errors are JSON-RPC errors that cross the wire as error responses.
 * They use numeric error codes from the {@linkcode ProtocolErrorCode} enum.
 *
 * `instanceof` on this class (and its subclasses) is brand-matched, so it works
 * across separately bundled copies of the SDK — e.g. an error constructed by
 * `@modelcontextprotocol/client` matches the class re-exported by
 * `@modelcontextprotocol/server` in the same process.
 */
export class ProtocolError extends Error {
    static {
        Object.defineProperty(this, 'mcpBrand', { value: 'mcp.ProtocolError' });
    }

    static override [Symbol.hasInstance](value: unknown): boolean {
        return brandedHasInstance(this, value);
    }

    /**
     * Brand-based type guard: equivalent to `value instanceof this`, as an
     * explicit static predicate (the axios/AWS-SDK `isInstance` style). Reads
     * the caller's own brand via `this`, so every branded subclass gets a
     * correctly-scoped guard by inheritance. Must be invoked on the class —
     * in callback position write `v => SdkError.isInstance(v)`, not
     * `.filter(SdkError.isInstance)` (detached calls throw rather than
     * silently matching nothing).
     */
    static isInstance<T extends abstract new (...args: never[]) => unknown>(this: T, value: unknown): value is InstanceType<T> {
        if (typeof this !== 'function') {
            throw new TypeError(
                'isInstance must be called on the class (e.g. `SdkError.isInstance(value)`); for callbacks use `v => SdkError.isInstance(v)`'
            );
        }
        return brandedHasInstance(this, value);
    }

    constructor(
        public readonly code: number,
        message: string,
        public readonly data?: unknown
    ) {
        super(message);
        this.name = 'ProtocolError';
        stampErrorBrands(this, new.target);
    }

    /**
     * Factory method to create the appropriate error type based on the error code and data
     */
    static fromError(code: number, message: string, data?: unknown): ProtocolError {
        // Check for specific error types
        if (code === ProtocolErrorCode.UrlElicitationRequired && data) {
            const errorData = data as { elicitations?: unknown[] };
            if (errorData.elicitations) {
                return new UrlElicitationRequiredError(errorData.elicitations as ElicitRequestURLParams[], message);
            }
        }

        if (code === ProtocolErrorCode.UnsupportedProtocolVersion && data) {
            const errorData = data as Partial<UnsupportedProtocolVersionErrorData>;
            if (Array.isArray(errorData.supported) && typeof errorData.requested === 'string') {
                return new UnsupportedProtocolVersionError({ supported: errorData.supported, requested: errorData.requested }, message);
            }
        }

        // Resource not found is recognised on BOTH the spec-mandated −32602 and
        // the legacy −32002 (the spec's "clients SHOULD also accept −32002"
        // backwards-compatibility clause). On −32602 the data-shape parse is
        // narrowed to "exactly `{ uri: string }` and nothing else": a server's
        // own Invalid Params that happens to carry `data.uri` alongside other
        // keys (e.g. `{ uri, reason: 'uri must be https' }`) stays a generic
        // ProtocolError. On −32002 the code itself is the discriminator, so any
        // `data.uri` string suffices.
        if (code === ProtocolErrorCode.InvalidParams || code === ProtocolErrorCode.ResourceNotFound) {
            const errorData = data as Record<string, unknown> | undefined;
            if (
                typeof errorData?.uri === 'string' &&
                (code === ProtocolErrorCode.ResourceNotFound || Object.keys(errorData).length === 1)
            ) {
                return new ResourceNotFoundError(errorData.uri, message);
            }
        }

        if (code === ProtocolErrorCode.MissingRequiredClientCapability && data) {
            const errorData = data as Partial<MissingRequiredClientCapabilityErrorData>;
            if (
                errorData.requiredCapabilities !== null &&
                typeof errorData.requiredCapabilities === 'object' &&
                !Array.isArray(errorData.requiredCapabilities)
            ) {
                return new MissingRequiredClientCapabilityError({ requiredCapabilities: errorData.requiredCapabilities }, message);
            }
        }

        // Default to generic ProtocolError
        return new ProtocolError(code, message, data);
    }
}

/**
 * Error type for a `resources/read` miss: the requested resource does not
 * exist. The wire code is `-32602` (Invalid Params) on every protocol
 * revision — the spec MUST for revision 2026-07-28, and the value the v1.x
 * SDK has always emitted on earlier revisions. The error data echoes the
 * requested URI.
 *
 * Recognise this error by checking `error.data` is exactly `{ uri: string }`
 * (a `-32602` whose data carries `uri` and nothing else is resource-not-found;
 * any other `-32602` is an ordinary Invalid Params). For backwards compatibility, clients should also
 * accept `-32002` as resource not found — earlier SDK builds emitted that
 * code, and {@linkcode ProtocolError.fromError} reconstructs this class for
 * either code **when `error.data` carries `uri`** (a bare `-32002` without
 * `data.uri` stays a generic {@linkcode ProtocolError}). `instanceof` checks
 * are brand-matched and work across separately bundled copies of the SDK.
 */
export class ResourceNotFoundError extends ProtocolError {
    static {
        Object.defineProperty(this, 'mcpBrand', { value: 'mcp.ResourceNotFoundError' });
    }

    constructor(uri: string, message: string = `Resource not found: ${uri}`) {
        super(ProtocolErrorCode.InvalidParams, message, { uri });
    }

    /** The URI that was requested and not found. */
    get uri(): string {
        return (this.data as { uri: string }).uri;
    }
}

/**
 * Specialized error type when a tool requires a URL mode elicitation.
 * This makes it nicer for the client to handle since there is specific data to work with instead of just a code to check against.
 */
export class UrlElicitationRequiredError extends ProtocolError {
    static {
        Object.defineProperty(this, 'mcpBrand', { value: 'mcp.UrlElicitationRequiredError' });
    }

    constructor(elicitations: ElicitRequestURLParams[], message: string = `URL elicitation${elicitations.length > 1 ? 's' : ''} required`) {
        super(ProtocolErrorCode.UrlElicitationRequired, message, {
            elicitations: elicitations
        });
    }

    get elicitations(): ElicitRequestURLParams[] {
        return (this.data as { elicitations: ElicitRequestURLParams[] })?.elicitations ?? [];
    }
}

/**
