/**
 * Validates and parses an unknown value as a JSON-RPC message.
 *
 * Use this to validate incoming messages in custom transport implementations.
 * Throws if the value does not conform to the JSON-RPC message schema.
 *
 * @param value - The value to validate (typically a parsed JSON object).
 * @returns The validated {@linkcode JSONRPCMessage}.
 * @throws If validation fails.
 */
export function parseJSONRPCMessage(value: unknown): JSONRPCMessage {
    return JSONRPCMessageSchema.parse(value);
}

export const isJSONRPCRequest = (value: unknown): value is JSONRPCRequest => JSONRPCRequestSchema.safeParse(value).success;

export const isJSONRPCNotification = (value: unknown): value is JSONRPCNotification => JSONRPCNotificationSchema.safeParse(value).success;

/**
 * Checks if a value is a valid {@linkcode JSONRPCResultResponse}.
 * @param value - The value to check.
 *
 * @returns True if the value is a valid {@linkcode JSONRPCResultResponse}, false otherwise.
 */
export const isJSONRPCResultResponse = (value: unknown): value is JSONRPCResultResponse =>
    JSONRPCResultResponseSchema.safeParse(value).success;

/**
 * Checks if a value is a valid {@linkcode JSONRPCErrorResponse}.
 * @param value - The value to check.
 *
 * @returns True if the value is a valid {@linkcode JSONRPCErrorResponse}, false otherwise.
 */
export const isJSONRPCErrorResponse = (value: unknown): value is JSONRPCErrorResponse =>
    JSONRPCErrorResponseSchema.safeParse(value).success;

/**
 * Checks if a value is a valid {@linkcode JSONRPCResponse} (either a result or error response).
 * @param value - The value to check.
 *
 * @returns True if the value is a valid {@linkcode JSONRPCResponse}, false otherwise.
 */
export const isJSONRPCResponse = (value: unknown): value is JSONRPCResponse => JSONRPCResponseSchema.safeParse(value).success;

/**
 * Checks if a value is a valid {@linkcode CallToolResult}.
 *
 * This is a consumer-side VALUE check against the neutral model, not a wire
 * validator: a raw wire object that additionally carries wire-only members
 * (e.g. `resultType`) still passes through the loose index signature. Use a
 * transport-level parse to validate raw wire traffic.
 *
 * @param value - The value to check.
 *
 * @returns True if the value is a valid {@linkcode CallToolResult}, false otherwise.
 */
export const isCallToolResult = (value: unknown): value is CallToolResult => {
    // content === undefined covers an explicit undefined key too: the schema's
    // .default([]) would parse it, but the narrowed type requires the array.
    if (typeof value !== 'object' || value === null || (value as { content?: unknown }).content === undefined) return false;
    return CallToolResultSchema.safeParse(value).success;
};

/**
 * Checks whether a value is an input-required result (protocol revision
 * 2026-07-28): the multi-round-trip return shape discriminated by
 * `resultType: 'input_required'`.
 *
 * This is a discriminator check, not a full validator — the at-least-one rule
 * (`inputRequests` or `requestState`) is enforced by the `inputRequired()`
 * builder and re-checked by the server seam for hand-built values.
 *
 * @param value - The value to check.
 * @returns True if the value carries the `input_required` discriminator.
 */
export const isInputRequiredResult = (value: unknown): value is InputRequiredResult =>
    typeof value === 'object' &&
    value !== null &&
    !Array.isArray(value) &&
    (value as { resultType?: unknown }).resultType === 'input_required';

/**
 * Checks if a value is a valid {@linkcode TaskAugmentedRequestParams}.
 * @param value - The value to check.
 *
 * @returns True if the value is a valid {@linkcode TaskAugmentedRequestParams}, false otherwise.
 *
 * @deprecated Recognizes 2025-11-25 task wire vocabulary, which has no SDK
 * runtime; kept importable for interoperability only.
 */
export const isTaskAugmentedRequestParams = (value: unknown): value is TaskAugmentedRequestParams =>
    TaskAugmentedRequestParamsSchema.safeParse(value).success;

export const isInitializeRequest = (value: unknown): value is InitializeRequest => InitializeRequestSchema.safeParse(value).success;

export const isInitializedNotification = (value: unknown): value is InitializedNotification =>
    InitializedNotificationSchema.safeParse(value).success;

export function assertCompleteRequestPrompt(request: CompleteRequest): asserts request is CompleteRequestPrompt {
    if (request.params.ref.type !== 'ref/prompt') {
        throw new TypeError(`Expected CompleteRequestPrompt, but got ${request.params.ref.type}`);
    }
    void (request as CompleteRequestPrompt);
}

export function assertCompleteRequestResourceTemplate(request: CompleteRequest): asserts request is CompleteRequestResourceTemplate {
    if (request.params.ref.type !== 'ref/resource') {
        throw new TypeError(`Expected CompleteRequestResourceTemplate, but got ${request.params.ref.type}`);
    }
    void (request as CompleteRequestResourceTemplate);
}
/**
 * SEP-2243 `Mcp-Param-*` header codec (protocol revision 2026-07-28).
 *
 * Pure functions for the custom-header half of SEP-2243: scanning a tool's
 * `inputSchema` for `x-mcp-header` declarations, encoding argument values into
 * `Mcp-Param-{Name}` HTTP headers (with the `=?base64?…?=` sentinel for values
 * that cannot be safely represented as plain ASCII field values), decoding
 * those headers, and validating that the headers a request carries match the
 * argument values in its body.
 *
 * The standard-header half (`MCP-Protocol-Version`, `Mcp-Method`, `Mcp-Name`)
 * lives with the inbound classifier — this module is the custom-header half
 * only, and it consumes the same `-32020` (`HeaderMismatch`) emission shape the
 * classifier established for header/body cross-check failures.
 *
 * Spec text at the implementation's spec pin:
 * - draft/basic/transports/streamable-http.mdx § "Custom Headers from Tool Parameters"
 *   (constraints, value encoding, the 5-step client algorithm, the
 *   server-behavior table, the `400` + `-32020` rejection)
 * - draft/server/tools.mdx § "x-mcp-header" (the schema-extension property and
 *   its constraints)
 */
import type { InboundLadderRejection } from './inboundClassification';
import { HEADER_MISMATCH_ERROR_CODE } from './inboundClassification';

/* ------------------------------------------------------------------------ *
 * Declaration scan
 * ------------------------------------------------------------------------ */

/** The fixed prefix every custom-parameter header carries. */
export const MCP_PARAM_HEADER_PREFIX = 'Mcp-Param-';

/** The schema-extension property name a tool's `inputSchema` carries. */
export const X_MCP_HEADER_KEY = 'x-mcp-header';

/**
 * One `x-mcp-header` declaration found inside a tool's `inputSchema`.
 *
 * `path` is the property path from the arguments root (the spec permits
 * declarations at any nesting depth under `properties`); `headerName` is the
 * `{Name}` portion as declared (case preserved for emission; comparison is
 * case-insensitive); `type` is the JSON Schema `type` of the declaring
 * property.
 */
export interface XMcpHeaderDeclaration {
    path: readonly string[];
    headerName: string;
    type: string;
}

/** The result of scanning a tool's `inputSchema` for `x-mcp-header` declarations. */
export type XMcpHeaderScanResult = { valid: true; declarations: readonly XMcpHeaderDeclaration[] } | { valid: false; reason: string };

/**
 * RFC 9110 §5.1 `token` syntax (`1*tchar`). Rejects empty, space, control
 * characters (including CR/LF), and the listed delimiters.
 */
const RFC9110_TOKEN = /^[!#$%&'*+\-.^_`|~0-9A-Za-z]+$/;

/**
 * JSON Schema `type` values the spec admits on an `x-mcp-header` property.
 *
 * The spec text names `integer`, `string`, `boolean` and explicitly excludes
 * `number`. The published conformance referee at the pinned release ships its
 * `http-custom-headers` scenario with two `type: "number"` `x-mcp-header`
 * parameters and expects the client to mirror them, so `number` is accepted
 * here so that the conformance gate passes; the discrepancy is tracked
 * upstream. Everything else (`object`, `array`, `null`, absent) is rejected.
 */
const PERMITTED_X_MCP_HEADER_TYPES: ReadonlySet<string> = new Set(['string', 'integer', 'boolean', 'number']);

/**
 * Scan a tool's JSON-serialized `inputSchema` for `x-mcp-header` declarations
 * and validate every constraint the spec places on them. Returns either the
 * collected declarations (possibly empty) or the first violated constraint.
 *
 * The walk descends through `properties` at any depth (the spec's "any nesting
 * depth" clause). The static-reachability MUST is enforced as a structural
 * sweep: every position the chain MUST NOT pass through (`items`/
 * `additionalProperties`, `oneOf`/`anyOf`/`allOf`/`not`, `if`/`then`/`else`,
 * `$defs`, `$ref` targets within `$defs`) is visited too, and an
 * `x-mcp-header` found anywhere on that path invalidates the schema — "an
 * annotation anywhere else makes the tool definition invalid".
 */
export function scanXMcpHeaderDeclarations(inputSchema: unknown): XMcpHeaderScanResult {
    const declarations: XMcpHeaderDeclaration[] = [];
    const seenLower = new Map<string, string>();

    const visit = (node: unknown, path: readonly string[], reachable: boolean): string | undefined => {
        if (node === null || typeof node !== 'object') return undefined;
        const schema = node as Record<string, unknown>;

        if (X_MCP_HEADER_KEY in schema) {
            if (!reachable || path.length === 0) {
                return `${pathName(path)}: x-mcp-header is only permitted on properties statically reachable via a chain of 'properties' keys (not under items, additionalProperties, oneOf/anyOf/allOf/not, if/then/else, or $ref)`;
            }
            const raw = schema[X_MCP_HEADER_KEY];
            if (typeof raw !== 'string' || raw.length === 0) {
                return `${pathName(path)}: x-mcp-header MUST be a non-empty string`;
            }
            if (!RFC9110_TOKEN.test(raw)) {
                return `${pathName(path)}: x-mcp-header '${raw}' is not a valid RFC 9110 token (no spaces, control characters or HTTP delimiters)`;
            }
            const type = typeof schema.type === 'string' ? schema.type : undefined;
            if (type === undefined || !PERMITTED_X_MCP_HEADER_TYPES.has(type)) {
                return `${pathName(path)}: x-mcp-header is only permitted on primitive-typed properties (string, integer, boolean); got ${type ?? '<none>'}`;
            }
            const lower = raw.toLowerCase();
            const prior = seenLower.get(lower);
            if (prior !== undefined) {
                return `x-mcp-header '${raw}' is not case-insensitively unique (also declared as '${prior}')`;
            }
            seenLower.set(lower, raw);
            declarations.push({ path, headerName: raw, type });
        }

        const properties = schema.properties;
        if (properties !== null && typeof properties === 'object') {
            for (const [key, child] of Object.entries(properties as Record<string, unknown>)) {
                const fault = visit(child, [...path, key], reachable);
                if (fault !== undefined) return fault;
            }
        }
        // Static-reachability sweep: descend the keywords the chain MUST NOT
        // pass through with `reachable: false` so an annotation under any of
        // them is reported (rather than silently ignored). `$defs` covers
        // `$ref`-within-`$defs` — chasing arbitrary `$ref` URIs is out of scope.
        for (const k of NON_REACHABLE_SUBSCHEMA_KEYWORDS) {
            const sub = schema[k];
            if (sub === undefined) continue;
            const branches: unknown[] = Array.isArray(sub)
                ? sub
                : sub !== null && typeof sub === 'object' && OBJECT_VALUED_SUBSCHEMA_KEYWORDS.has(k)
                  ? Object.values(sub as Record<string, unknown>)
                  : [sub];
            for (const branch of branches) {
                const fault = visit(branch, [...path, `<${k}>`], false);
                if (fault !== undefined) return fault;
            }
        }
        return undefined;
    };

    const fault = visit(inputSchema, [], true);
    return fault === undefined ? { valid: true, declarations } : { valid: false, reason: fault };
}

/**
 * JSON Schema keywords whose subschemas the SEP-2243 static-reachability
 * constraint excludes from the `properties`-only chain. An `x-mcp-header`
 * found under any of these invalidates the tool definition.
 */
const NON_REACHABLE_SUBSCHEMA_KEYWORDS = [
    'items',
    'prefixItems',
    'contains',
    'additionalProperties',
    'unevaluatedProperties',
    'unevaluatedItems',
    'propertyNames',
    'patternProperties',
    'dependentSchemas',
    'oneOf',
    'anyOf',
    'allOf',
    'not',
    'if',
    'then',
    'else',
    '$defs',
    'definitions'
] as const;

/**
 * Subschema-carrying keywords whose value is a `name → subschema` object
 * (not a single subschema or array of subschemas). The visit branches over
 * `Object.values()` for these.
 */
const OBJECT_VALUED_SUBSCHEMA_KEYWORDS: ReadonlySet<string> = new Set(['patternProperties', 'dependentSchemas', '$defs', 'definitions']);

function pathName(path: readonly string[]): string {
    return path.length === 0 ? '<root>' : path.join('.');
}

/* ------------------------------------------------------------------------ *
 * Value encoding
 * ------------------------------------------------------------------------ */

const BASE64_SENTINEL_PREFIX = '=?base64?';
const BASE64_SENTINEL_SUFFIX = '?=';
// RFC 4648 §4, padding required (the spec's encoding-examples table and the
// conformance referee's invalid-padding cell both require canonical padding).
const BASE64_CANONICAL = /^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/;
// Strict decimal — gates the numeric comparison in `validateMcpParamHeaders`
// so `Number()` never sees the looser forms it would otherwise accept
// (`'0x1a'`, `' 42 '`, `'1e3'`).
const CANONICAL_DECIMAL = /^-?\d+(\.\d+)?$/;

/**
 * Convert a primitive argument value to its string representation per the
 * spec's type-conversion rules: strings pass through, integers and numbers
 * become their decimal string, booleans become lowercase `'true'` / `'false'`.
 * Non-finite numbers and integers outside the safe range are refused (the
 * caller treats `undefined` as "do not emit a header for this value").
 */
export function mcpParamPrimitiveToString(value: unknown): string | undefined {
    if (typeof value === 'string') return value;
    if (typeof value === 'boolean') return value ? 'true' : 'false';
    if (typeof value === 'number') {
        if (!Number.isFinite(value)) return undefined;
        if (Number.isInteger(value) && !Number.isSafeInteger(value)) return undefined;
        return String(value);
    }
    return undefined;
}

/**
 * `true` when `s` cannot be safely represented as a plain ASCII HTTP field
 * value per RFC 9110 §5.5: it contains a byte outside `0x20–0x7E` / `0x09`, it
 * has leading or trailing whitespace (which field parsing strips), or it
 * already matches the Base64 sentinel pattern (the spec's "to avoid ambiguity"
 * rule).
 */
function needsBase64(s: string): boolean {
    if (s.length === 0) return true;
    if (s.startsWith(BASE64_SENTINEL_PREFIX) && s.endsWith(BASE64_SENTINEL_SUFFIX)) return true;
    if (s !== s.trim()) return true;
    for (let i = 0; i < s.length; i++) {
        const c = s.codePointAt(i)!;
        // Visible ASCII 0x21–0x7E, plus space 0x20 and horizontal tab 0x09; a
        // tab is only safe when it is interior whitespace (the trim() check
        // above already covered leading/trailing).
        if (c === 0x09 || (c >= 0x20 && c <= 0x7e)) continue;
        return true;
    }
    return false;
}

function utf8ToBase64(s: string): string {
    const bytes = new TextEncoder().encode(s);
    let bin = '';
    for (const b of bytes) bin += String.fromCodePoint(b);
    return btoa(bin);
}

function base64ToUtf8(b64: string): string {
    const bin = atob(b64);
    const bytes = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) bytes[i] = bin.codePointAt(i)!;
    return new TextDecoder('utf-8', { fatal: true }).decode(bytes);
}

/**
 * Encode a string value as an HTTP field value per the spec's value-encoding
 * rules: a value that is already a safe plain-ASCII field value is passed
 * through unchanged; anything else is wrapped as `=?base64?{b64-of-utf8}?=`.
 */
export function encodeMcpParamValue(value: string): string {
    return needsBase64(value) ? `${BASE64_SENTINEL_PREFIX}${utf8ToBase64(value)}${BASE64_SENTINEL_SUFFIX}` : value;
}

/**
 * Decode an `Mcp-Param-*` header value: when it carries the Base64 sentinel,
 * the payload is decoded as UTF-8; otherwise the value is returned as-is.
 * Returns `undefined` when the sentinel is present but the payload is not
 * canonical Base64 (or not valid UTF-8) — the spec requires servers to reject
 * such values.
 */
export function decodeMcpParamValue(value: string): string | undefined {
    if (!(value.startsWith(BASE64_SENTINEL_PREFIX) && value.endsWith(BASE64_SENTINEL_SUFFIX))) {
        return value;
    }
    const b64 = value.slice(BASE64_SENTINEL_PREFIX.length, value.length - BASE64_SENTINEL_SUFFIX.length);
    if (!BASE64_CANONICAL.test(b64)) return undefined;
    try {
        return base64ToUtf8(b64);
    } catch {
        return undefined;
    }
}

/* ------------------------------------------------------------------------ *
 * Client-side header construction (the 5-step MUST algorithm, steps 3–5)
 * ------------------------------------------------------------------------ */

function valueAtPath(root: unknown, path: readonly string[]): unknown {
    let node: unknown = root;
    for (const key of path) {
        if (node === null || typeof node !== 'object') return undefined;
        node = (node as Record<string, unknown>)[key];
    }
    return node;
}

/**
 * Build the `Mcp-Param-{Name}` headers for one `tools/call` from a scan of the
 * tool's `inputSchema` and the call's `arguments`. A declaration whose value is
 * `null` or absent in `arguments` is omitted (the spec's "client MUST omit the
 * header" rows); a value that is not a primitive of the declared kind is
 * omitted rather than emitted malformed.
 */
export function buildMcpParamHeaders(
    declarations: readonly XMcpHeaderDeclaration[],
    args: Record<string, unknown> | undefined
): Record<string, string> {
    const out: Record<string, string> = {};
    for (const decl of declarations) {
        const raw = valueAtPath(args, decl.path);
        if (raw === undefined || raw === null) continue;
        const stringValue = mcpParamPrimitiveToString(raw);
        if (stringValue === undefined) continue;
        out[`${MCP_PARAM_HEADER_PREFIX}${decl.headerName}`] = encodeMcpParamValue(stringValue);
    }
    return out;
}

/* ------------------------------------------------------------------------ *
 * Server-side validation
 * ------------------------------------------------------------------------ */

/**
 * The header/body comparison the server performs at tool-resolution time.
 *
 * For each `x-mcp-header` declaration on the named tool: when the body
 * `arguments` carries a value, the matching `Mcp-Param-{Name}` header MUST be
 * present and decode to an equal value; when the body value is `null` or
 * absent the server MUST NOT expect the header (a present header is ignored).
 * A sentinel-carrying header whose payload is not canonical Base64 / valid
 * UTF-8 is rejected as invalid characters.
 *
 * Integer-typed declarations are compared numerically (the spec's SHOULD —
 * `42.0` and `42` are equal); everything else is compared as decoded strings.
 *
 * Returns `undefined` when every check passes, or an
 * {@linkcode InboundLadderRejection} carrying the same `-32020`
 * (`HeaderMismatch`) shape the inbound classifier emits for the
 * standard-header cross-checks — `400 Bad Request` with the disagreeing pair
 * in `data.mismatch`.
 */
export function validateMcpParamHeaders(
    declarations: readonly XMcpHeaderDeclaration[],
    args: Record<string, unknown> | undefined,
    headers: Headers
): InboundLadderRejection | undefined {
    for (const decl of declarations) {
        const headerKey = `${MCP_PARAM_HEADER_PREFIX}${decl.headerName}`;
        const headerValue = headers.get(headerKey);
        const bodyRaw = valueAtPath(args, decl.path);

        if (bodyRaw === undefined || bodyRaw === null) {
            // Server MUST NOT expect the header for a null/absent value.
            continue;
        }
        const bodyString = mcpParamPrimitiveToString(bodyRaw);
        if (bodyString === undefined) {
            // Body carries a non-primitive where the schema declares one;
            // params validation owns that fault. Skip the header check.
            continue;
        }
        if (headerValue === null) {
            return paramHeaderMismatchRejection(
                'param-header-missing',
                headerKey,
                `the body carries ${pathName(decl.path)}=${JSON.stringify(bodyRaw)} but the ${headerKey} header is absent`
            );
        }
        const decoded = decodeMcpParamValue(headerValue);
        if (decoded === undefined) {
            return paramHeaderMismatchRejection(
                'param-header-invalid-encoding',
                headerKey,
                `the ${headerKey} header carries an invalid Base64 sentinel value`
            );
        }
        // Integer/number-typed declarations compare numerically (the spec's
        // SHOULD — `42.0` and `42` are equal). The strict-decimal gate is
        // applied to the *header* side only (so `'0x1a'`, `' 42 '`, `'1e3'`
        // etc. never coerce); the body side is gated on being an actual JS
        // number — `String(0.0000001) === '1e-7'` would fail the regex even
        // though the value is perfectly canonical. A non-numeric body
        // primitive (e.g. `'abc'` where the schema declares `integer`) is a
        // body-vs-schema fault that params validation owns; fall back to
        // string comparison and let dispatch emit `-32602` instead so an
        // identical non-numeric pair never reports a mismatch.
        const numericComparable =
            (decl.type === 'integer' || decl.type === 'number') && CANONICAL_DECIMAL.test(decoded) && typeof bodyRaw === 'number';
        const equal = numericComparable ? Number(decoded) === bodyRaw : decoded === bodyString;
        if (!equal) {
            return paramHeaderMismatchRejection(
                'param-header-mismatch',
                headerKey,
                `the ${headerKey} header decodes to ${JSON.stringify(decoded)} but the body carries ${pathName(decl.path)}=${JSON.stringify(bodyRaw)}`
            );
        }
    }
    return undefined;
}

/**
 * Build the `-32020` (`HeaderMismatch`) rejection for an `Mcp-Param-*`
 * disagreement. Same shape as the inbound classifier's standard-header
 * cross-check mismatch (HTTP `400`, `data.mismatch` naming the disagreeing
 * pair, `settled: true`); only the rung differs because this check runs at the
 * pre-dispatch step against a known tool's schema rather than at the edge.
 */
export function paramHeaderMismatchRejection(cell: string, header: string, body: string): InboundLadderRejection {
    return {
        kind: 'reject',
        rung: 'param-header-validation',
        cell,
        httpStatus: 400,
        code: HEADER_MISMATCH_ERROR_CODE,
        message: `Bad Request: the request headers and body disagree: ${body}`,
        data: { mismatch: { header, body } },
        settled: true
    };
}
/**
 * Inbound HTTP request classification and the inbound validation ladder
 * (protocol revision 2026-07-28).
 *
 * `classifyInboundRequest` is the body-primary era predicate for an HTTP
 * entry that serves both protocol eras on one endpoint. It is evaluated
 * exactly once, at the entry boundary, on the already-parsed request body:
 *
 * - `initialize` is a legacy-era request by definition (the modern era has no
 *   `initialize` handshake) — unless it carries a valid envelope claim naming
 *   a modern revision, in which case the claim wins and the request is
 *   classified like any other enveloped request (the modern era then answers
 *   it with method-not-found, exactly like every other method it does not
 *   define).
 * - A request whose `params._meta` carries the reserved protocol-version key
 *   claims the per-request envelope mechanism and classifies into the era the
 *   named revision belongs to (a malformed envelope behind a present claim is
 *   a validation error, never a silent fall back to legacy handling).
 * - A request without a claim is legacy-era traffic.
 * - The `MCP-Protocol-Version` header is a cross-check only *for
 *   classification*: it never upgrades or downgrades a body-derived
 *   classification, and a disagreement between header and body is an explicit
 *   ladder outcome. Its absence likewise never changes the era — but the spec
 *   requires the header on every modern *request* POST, so a
 *   modern-classified request that omits it is refused one rung later, by
 *   {@linkcode validateStandardRequestHeaders}, not here. Notification POSTs
 *   are exempt (see the next bullet), and that rung enforces presence on
 *   requests only.
 * - Notifications carry no envelope claim of their own under the current
 *   spec, so for notification POSTs without a body claim the modern header is
 *   determinative; the `Mcp-Method` header is validated against the body when
 *   the message classifies modern and is never enforced on legacy traffic.
 *   A notification that does carry a claim is treated body-primary like a
 *   request, and a malformed claim is rejected the same way a request's
 *   malformed claim is — never silently resolved against the header.
 *   The notification-POST header cross-checks here are an SDK-defensive
 *   posture, not a spec requirement: the spec leaves header rules for posted
 *   notifications undefined (core client notifications do not occur over
 *   Streamable HTTP); applying the request rules symmetrically is what an
 *   ecosystem custom-notification POST expects, and the −32020 cells stay
 *   passing for them.
 * - `GET`/`DELETE` (and any other non-`POST` method) are body-less 2025-era
 *   session operations: the modern era is `POST`-only, so they are routed to
 *   legacy serving when it is configured and rejected otherwise.
 * - Array (batch) bodies are classified element-wise: an array containing a
 *   modern-claiming or invalid element is rejected, an all-legacy array is
 *   legacy traffic unchanged, and a single-element array is still an array.
 *
 * The classifier returns plain values (it never throws and never touches a
 * transport): a routing outcome (`legacy`/`modern`) or a ladder rejection
 * carrying the JSON-RPC error to emit and the HTTP status to emit it with.
 * Legacy routing outcomes deliberately carry NO `MessageClassification` —
 * legacy and hand-wired traffic is never classified, which keeps its
 * dispatch behavior byte-identical to today's.
 *
 * Error codes for the modern-path rejection cells follow the published
 * conformance suite (and the spec text it asserts):
 *
 * - A header/body cross-check mismatch (the `MCP-Protocol-Version` header
 *   disagreeing with the body, or the `Mcp-Method` header disagreeing with the
 *   body method) is rejected with `-32020` (`HeaderMismatch`) on HTTP 400.
 * - A request whose protocol-version header names a modern revision but whose
 *   body carries no `_meta` envelope claim — including an envelope present but
 *   missing the required protocol-version key — is rejected with `-32602`
 *   (invalid params) naming the missing key(s), on HTTP 400.
 *
 * Should a future spec revision or conformance release change these
 * assignments, the affected cells are re-derived against that release; the
 * `settled` flag on {@linkcode InboundLadderRejection} stays available to mark
 * a cell provisional again while such a change is in flight.
 */
import { PROTOCOL_VERSION_META_KEY } from '../types/constants';
import { ProtocolErrorCode } from '../types/enums';
import { ProtocolError, UnsupportedProtocolVersionError } from '../types/errors';
import { isJSONRPCErrorResponse, isJSONRPCNotification, isJSONRPCRequest, isJSONRPCResultResponse } from '../types/guards';
import type { JSONRPCNotification, JSONRPCRequest, MessageClassification } from '../types/types';
import { envelopeClaimVersion, hasEnvelopeClaim, requestMetaOf, validateEnvelopeMeta } from './envelope';
// Value encoding is shared between the standard `Mcp-Name` header and the
// custom `Mcp-Param-*` headers; the codec module already imports the
// `HeaderMismatch` constant and rejection type from here, so this is a benign
// two-module cycle (both sides only consume the other's exports inside
// function bodies, never at module-evaluation time).
import { decodeMcpParamValue } from './mcpParamHeaders';
import { isModernProtocolVersion } from './protocolEras';

/* ------------------------------------------------------------------------ *
 * Classifier input
 * ------------------------------------------------------------------------ */

/**
 * The transport-neutral description of an inbound HTTP request the classifier
 * evaluates. The caller (the HTTP entry) reads the body exactly once and
 * extracts the two protocol headers; the classifier never touches a request
 * object itself.
 */
export interface InboundHttpRequest {
    /** The HTTP request method, e.g. `POST`, `GET`, `DELETE`. */
    httpMethod: string;
    /** The value of the `MCP-Protocol-Version` header, when present. */
    protocolVersionHeader?: string;
    /** The value of the `Mcp-Method` header, when present. */
    mcpMethodHeader?: string;
    /** The value of the `Mcp-Name` header, when present. */
    mcpNameHeader?: string;
    /** The parsed JSON request body (`undefined` for body-less methods). */
    body?: unknown;
}

/* ------------------------------------------------------------------------ *
 * Classifier outcomes
 * ------------------------------------------------------------------------ */

/** Why an inbound request was routed to legacy-era serving. */
export type InboundLegacyRouteReason =
    /** Non-`POST` HTTP method: a body-less 2025-era session operation. */
    | 'http-method'
    /** An `initialize` request without a valid modern envelope claim — the legacy handshake by definition. */
    | 'initialize'
    /** A request without a per-request envelope claim. */
    | 'no-claim'
    /** A notification without a body claim or a modern protocol-version header. */
    | 'notification'
    /** An all-legacy JSON-RPC batch array. */
    | 'batch'
    /** A JSON-RPC response posted to the endpoint (2025-era session traffic). */
    | 'response';

/**
 * The request is legacy-era traffic. It carries no classification on purpose:
 * legacy serving receives it exactly as a hand-wired 2025 transport would.
 */
export interface InboundLegacyRoute {
    kind: 'legacy';
    reason: InboundLegacyRouteReason;
    /**
     * The protocol version the request named, when it named one (an
     * `initialize` body's `protocolVersion`, or the `MCP-Protocol-Version`
     * header). Used to echo `requested` when legacy serving is not configured.
     */
    requestedVersion?: string;
}

/**
 * The request claims the per-request envelope mechanism and is served on the
 * modern path. Discriminated by `messageKind` so the typed `message` narrows
 * with it — the classifier has already proved the JSON-RPC shape via the
 * `isJSONRPCRequest` / `isJSONRPCNotification` guards, so consumers never
 * cast the body again.
 */
export type InboundModernRoute =
    | {
          kind: 'modern';
          messageKind: 'request';
          /** The classified body — guard-proved {@linkcode JSONRPCRequest} shape. */
          message: JSONRPCRequest;
          /**
           * The classification handed to the per-request transport and validated by
           * the protocol layer against the serving instance's negotiated era.
           */
          classification: MessageClassification;
      }
    | {
          kind: 'modern';
          messageKind: 'notification';
          /** The classified body — guard-proved {@linkcode JSONRPCNotification} shape. */
          message: JSONRPCNotification;
          classification: MessageClassification;
      };

/** The named steps of the inbound validation ladder, in evaluation order. */
export type InboundValidationRung =
    | 'http-method'
    | 'jsonrpc-shape'
    | 'era-classification'
    | 'envelope'
    | 'method-registry'
    | 'request-params'
    | 'standard-header-validation'
    | 'client-capabilities'
    | 'param-header-validation';

/** A ladder rejection: the JSON-RPC error to emit and the HTTP status to emit it with. */
export interface InboundLadderRejection {
    kind: 'reject';
    /** The ladder rung that produced the rejection. */
    rung: InboundValidationRung;
    /** The cell this rejection corresponds to on the ladder cell sheet (stable identifier for tests). */
    cell: string;
    /** The HTTP status the rejection is emitted with. */
    httpStatus: number;
    /** The JSON-RPC error code. */
    code: number;
    /** The JSON-RPC error message. */
    message: string;
    /** Structured error data (recognizers parse this; they never rely on class identity). */
    data?: unknown;
    /**
     * `false` when the exact error code for this cell is not settled upstream
     * yet and the emitted code is provisional.
     */
    settled: boolean;
}

/** The outcome of classifying one inbound HTTP request. */
export type InboundClassificationOutcome = InboundLegacyRoute | InboundModernRoute | InboundLadderRejection;

/* ------------------------------------------------------------------------ *
 * Header cross-check mismatches
 * ------------------------------------------------------------------------ */

/**
 * The error code emitted for header/body cross-check mismatches: the
 * `MCP-Protocol-Version` header disagreeing with the body's envelope claim (or
 * with the body's classification), and the `Mcp-Method` header disagreeing
 * with the body method.
 *
 * `-32020` is the draft schema's `HEADER_MISMATCH` constant (the SEP-2243
 * `HeaderMismatch` code; the spec requires HTTP 400 for it), as also asserted
 * by the published conformance suite for header-validation failures. It has no
 * {@linkcode ProtocolErrorCode} member because it is not part of the 2025-era
 * wire vocabulary; the validation ladder is its only emitter.
 */
export const HEADER_MISMATCH_ERROR_CODE = -32_020;

/* ------------------------------------------------------------------------ *
 * The validation ladder as data
 * ------------------------------------------------------------------------ */

/** One rung of the inbound validation ladder. */
export interface InboundValidationRungDescriptor {
    rung: InboundValidationRung;
    /** Evaluation order: lower runs first; an earlier rung's outcome wins over a later rung's. */
    order: number;
    /**
     * Where the rung is evaluated: at the HTTP entry edge by
     * {@linkcode classifyInboundRequest} (`edge`), by the HTTP entry after
     * classification but before dispatch (`pre-dispatch`), or by the protocol
     * layer at dispatch (`dispatch`).
     */
    evaluatedAt: 'edge' | 'pre-dispatch' | 'dispatch';
    /** The JSON-RPC error codes this rung can produce (empty when the rung only routes). */
    codes: readonly number[];
    /** Conformance scenarios that exercise this rung (where one exists). */
    conformance: readonly string[];
    /** Why the rung sits where it does. */
    rationale: string;
}

/**
 * The inbound validation ladder, expressed as data rather than control flow.
 *
 * The edge rungs are evaluated by {@linkcode classifyInboundRequest}; the
 * dispatch rungs are evaluated by the protocol layer once the classified
 * message is injected into a per-request server instance (the era registry
 * gate, the envelope requiredness check, and per-method params validation).
 * The client-capability rung is evaluated by the HTTP entry itself,
 * pre-dispatch, on the validated envelope the classifier produced — see that
 * rung's rationale for the ordering caveat. The order is the precedence: a
 * request that fails several rungs is answered by the earliest one.
 */
export const INBOUND_VALIDATION_LADDER: readonly InboundValidationRungDescriptor[] = [
    {
        rung: 'http-method',
        order: 1,
        evaluatedAt: 'edge',
        codes: [-32_000],
        conformance: [],
        rationale:
            'The modern era is POST-only; GET/DELETE are body-less 2025-era session operations and are method-routed to legacy ' +
            'serving (405 when legacy serving is not configured), before any body is read.'
    },
    {
        rung: 'jsonrpc-shape',
        order: 2,
        evaluatedAt: 'edge',
        codes: [ProtocolErrorCode.InvalidRequest],
        conformance: ['server-stateless'],
        rationale:
            'The body must be a JSON-RPC request or notification: posted responses and batch arrays containing a modern or ' +
            'invalid element are rejected before classification (element-wise batch rule); all-legacy arrays stay legacy traffic.'
    },
    {
        rung: 'era-classification',
        order: 3,
        evaluatedAt: 'edge',
        codes: [HEADER_MISMATCH_ERROR_CODE, ProtocolErrorCode.UnsupportedProtocolVersion],
