   * Note: this is not part of the spec, but is included for better error handling.
   *
   * @public
   */
  public code?: number | undefined

  /**
   * Optional message attached to the error.
   * Note: this is not part of the spec, but is included for better error handling.
   *
   * @public
   */
  public message?: string | undefined

