    httpMethod: "GET",
    path: "/pets/{petId}",
    tags: ["pets"],
    security: [],
  },
  {
    id: "OwnersApi.listOwners",
    className: "OwnersApi",
    methodName: "listOwners",
    httpMethod: "GET",
    path: "/owners",
    tags: ["owners"],
    security: [{ apiKeyQuery: [] }],
  },
  {
    id: "PetsApi.createPet",
    className: "PetsApi",
