const principal: Principal = {
  id: "static:reader",
  kind: "static",
  name: "reader",
  scopes: [],
};
const BASE = "https://api.example.test/v1";

function broker(
  fetchImpl: typeof fetch,
  extra: Partial<{
    policy: AuthorizationPolicy;
    allowedOrigins: string[];
    maxResponseBytes: number;
    followRedirects: boolean;
    timeoutMs: number;
    provider: CredentialProvider;
    operations: OperationBinding[];
  }> = {},
) {
  const q = quietLogs();
  const provider =
    extra.provider ??
    new ServiceIdentityCredentialProvider({
      schemes: {
        apiKeyHeader: { apiKey: { env: "KEY" } },
        apiKeyQuery: { apiKey: { env: "KEY" } },
        adminBasic: { username: { env: "U" }, password: { env: "P" } },
      },
      schemeInfo: SCHEMES,
      resolver: new SecretResolver({
        baseDir: process.cwd(),
        env: { KEY: "broker-key-123456", U: "admin", P: "broker-pass-123456" },
      }),
      registry: new SecretRegistry(),
      logs: q.logs,
      allowInsecureTokenUrl: true,
      baseUrl: BASE,
    });
  const b = new RequestBroker({
    operations: extra.operations ?? OPS,
    schemes: SCHEMES,
    provider,
    policy: extra.policy ?? new AuthorizationPolicy(),
    network: {
      baseUrl: BASE,
      allowedOrigins: extra.allowedOrigins ?? [],
      followRedirects: extra.followRedirects ?? true,
      maxRedirects: 3,
      timeoutMs: extra.timeoutMs ?? 5000,
      maxResponseBytes: extra.maxResponseBytes ?? 1024 * 1024,
      maxRequestBytes: 1024,
    },
    fetchImpl,
  });
  return { b, ...q };
}

const req = (
  binding: string,
  url: string,
  method = "GET",
  headers: Record<string, string> = {},
) => ({
  rid: 1,
  binding,
  url,
  method,
  headers,
  body: null,
});
const ctx = (logs: ReturnType<typeof quietLogs>["logs"]) => ({
  principal,
  executionId: "exec_1",
  requestId: "req_1",
  logs,
});

describe("broker - compilePathTemplate", function () {
  it("should match concrete paths under the base path only", function () {
    const re = compilePathTemplate("/v1", "/pets/{petId}/visits");
    assert.isTrue(re.test("/v1/pets/12/visits"));
    assert.isTrue(re.test("/v1/pets/a%2Fb/visits"));
    assert.isFalse(re.test("/v1/pets/12/visits/x"));
    assert.isFalse(re.test("/pets/12/visits"));
    assert.isFalse(re.test("/v1/pets//visits"));
  });
});

describe("broker - RequestBroker.handle", function () {
  it("should inject credentials host-side and strip agent-supplied ones", async function () {
    const f = fakeFetch(
      () =>
        new Response("[]", {
          status: 200,
          headers: {
            "set-cookie": "sid=1",
            "content-type": "application/json",
          },
        }),
    );
    const { b, logs, records } = broker(f);
    const res = await b.handle(
      req("PetsApi.listPets", `${BASE}/pets?limit=2`, "GET", {
        "X-Api-Key": "agent-guess",
        Authorization: "Bearer agent",
        Accept: "application/json",
      }),
      ctx(logs),
      new AbortController().signal,
    );
    assert.isTrue(res.ok);
    const sent = f.calls[0];
    const headers = sent.init.headers as Record<string, string>;
    assert.equals(headers["X-Api-Key"], "broker-key-123456");
    assert.isUndefined(headers.Authorization);
    assert.equals(headers.Accept, "application/json");
    if (res.ok) {
      refute(res.headers.some(([k]) => k === "set-cookie"));
    }
    // One allowed decision, marked as modified: agent-supplied credentials
    // were removed.
    const decisions = records().filter((r) =>
      r.event.startsWith("authorization."),
    );
    assert.equals(decisions.length, 1);
    assert.equals(decisions[0].event, "authorization.allowed");
    assert.equals(decisions[0].outcome, "modified");
    assert.equals(
      (decisions[0].get("strippedCredentials") as string[]).sort(),
      ["authorization", "x-api-key"],
    );
  });

  it("should add query api keys and remove agent-supplied ones", async function () {
    const f = fakeFetch(() => new Response("[]", { status: 200 }));
    const { b, logs } = broker(f);
    await b.handle(
      req(
        "OwnersApi.listOwners",
        `${BASE}/owners?api_key=guess&city=Melbourne`,
      ),
      ctx(logs),
      new AbortController().signal,
    );
    assert.equals(f.calls[0].url.searchParams.getAll("api_key"), [
      "broker-key-123456",
    ]);
    assert.equals(f.calls[0].url.searchParams.get("city"), "Melbourne");
  });

  it("should deny and audit operations the policy forbids before contacting the API", async function () {
    const f = fakeFetch(() => new Response("{}", { status: 200 }));
    const policy = new AuthorizationPolicy({
      default: "deny",
      rules: [{ id: "read", allow: ["method:GET"], deny: [] }],
    });
    const { b, logs, records } = broker(f, { policy });
    const res = await b.handle(
      req("AdminApi.deletePet", `${BASE}/pets/1`, "DELETE"),
      ctx(logs),
      new AbortController().signal,
    );
    assert.isFalse(res.ok);
    if (!res.ok) assert.equals(res.error.reason, "authorization_denied");
    assert.equals(f.calls.length, 0);
    const audit = records().find((r) => r.event === "authorization.denied")!;
    assert.equals(audit.get("operation"), "AdminApi.deletePet");
    assert.equals(audit.get("policyId"), "default");
    assert.equals(audit.outcome, "denied");
  });

  it("should reject requests that do not match the operation or base URL", async function () {
    const f = fakeFetch(() => new Response("{}", { status: 200 }));
    const { b, logs, records } = broker(f);
    const signal = new AbortController().signal;
    for (const r of [
      req("PetsApi.getPetById", "https://evil.example.test/v1/pets/1"),
      req("PetsApi.getPetById", `${BASE}/owners`),
      req("PetsApi.getPetById", `${BASE}/pets/1`, "DELETE"),
      req("PetsApi.getPetById", `${BASE}/pets/1/../../admin`),
      req("Nope.method", `${BASE}/pets`),
    ]) {
      const res = await b.handle(r, ctx(logs), signal);
      assert.isFalse(res.ok, r.url);
    }
    assert.equals(f.calls.length, 0);
    const events = records().map((r) => r.event);
    assert.contains(events, "network.destination_denied");
    assert.contains(events, "execution.boundary_violation");
  });

  it("should follow same-origin redirects and deny other origins", async function () {
    const f = fakeFetch((url) => {
      if (url.pathname === "/v1/pets/1")
        return new Response(null, {
          status: 302,
          headers: { location: "/v1/pets/2" },
        });
      if (url.pathname === "/v1/pets/2")
        return new Response(null, {
          status: 302,
          headers: { location: "https://evil.example.test/x" },
        });
      return new Response("{}", { status: 200 });
    });
    const { b, logs, records } = broker(f);
    const res = await b.handle(
      req("PetsApi.getPetById", `${BASE}/pets/1`),
      ctx(logs),
      new AbortController().signal,
    );
    assert.isFalse(res.ok);
    if (!res.ok) assert.equals(res.error.reason, "redirect_denied");
    assert.equals(f.calls.length, 2);
    assert.contains(
      records().map((r) => r.event),
      "network.redirect_denied",
    );
  });

  it("should not forward credentials on redirects to another allowed origin", async function () {
    const f = fakeFetch((url) =>
      url.hostname === "api.example.test"
        ? new Response(null, {
            status: 307,
            headers: { location: "https://cdn.example.test/pets?api_key=x" },
          })
        : new Response("[]", { status: 200 }),
    );
    const { b, logs } = broker(f, {
      allowedOrigins: ["https://cdn.example.test"],
    });
    const res = await b.handle(
      req("PetsApi.listPets", `${BASE}/pets`),
      ctx(logs),
      new AbortController().signal,
    );
    assert.isTrue(res.ok);
    const second = f.calls[1];
    assert.equals(second.url.hostname, "cdn.example.test");
    assert.isUndefined(
      (second.init.headers as Record<string, string>)["X-Api-Key"],
    );
  });

  it("should bound response size", async function () {
    const f = fakeFetch(() => new Response("x".repeat(5000), { status: 200 }));
    const { b, logs } = broker(f, { maxResponseBytes: 2048 });
    const res = await b.handle(
      req("PetsApi.getPetById", `${BASE}/pets/1`),
      ctx(logs),
      new AbortController().signal,
    );
    assert.isFalse(res.ok);
    if (!res.ok) assert.equals(res.error.reason, "response_too_large");
  });

  it("should report missing upstream credentials without calling the API", async function () {
    const f = fakeFetch(() => new Response("{}", { status: 200 }));
    const q = quietLogs();
    const provider = new ServiceIdentityCredentialProvider({
      schemes: {},
      schemeInfo: SCHEMES,
      resolver: new SecretResolver({ baseDir: process.cwd(), env: {} }),
      registry: new SecretRegistry(),
      logs: q.logs,
      allowInsecureTokenUrl: true,
      baseUrl: BASE,
    });
    const b = new RequestBroker({
      operations: OPS,
      schemes: SCHEMES,
      provider,
      policy: new AuthorizationPolicy(),
      network: {
        baseUrl: BASE,
        allowedOrigins: [],
        followRedirects: true,
        maxRedirects: 3,
        timeoutMs: 1000,
        maxResponseBytes: 1024,
        maxRequestBytes: 1024,
      },
      fetchImpl: f,
    });
    const res = await b.handle(
      req("PetsApi.listPets", `${BASE}/pets`),
      ctx(q.logs),
      new AbortController().signal,
    );
    assert.isFalse(res.ok);
    if (!res.ok) assert.equals(res.error.type, "upstream_auth_error");
    assert.equals(f.calls.length, 0);
    assert.contains(
      q.records().map((r) => r.event),
      "credential.lookup_failed",
    );
  });
});

describe("broker - handle request limits and failures", function () {
  const signal = () => new AbortController().signal;

  it("should refuse and audit a request URL that cannot be parsed", async function () {
    const f = fakeFetch(() => new Response("{}"));
    const { b, logs, records } = broker(f);
    const res = await b.handle(
      req("PetsApi.listPets", "not a url"),
      ctx(logs),
      signal(),
    );
    assert.isFalse(res.ok);
    if (!res.ok) assert.equals(res.error.reason, "invalid_url");
    assert.equals(f.calls.length, 0);
    const denied = records().find(
      (r) => r.event === "network.destination_denied",
    )!;
    assert.equals(denied.get("reason"), "invalid_url");
  });

  it("should send a base64 request body decoded", async function () {
    const f = fakeFetch(() => new Response("{}", { status: 201 }));
    const { b, logs } = broker(f);
    const res = await b.handle(
      {
        ...req("PetsApi.createPet", `${BASE}/pets`, "POST"),
        body: Buffer.from('{"name":"Rex"}').toString("base64"),
        bodyEncoding: "base64",
      },
      ctx(logs),
      signal(),
    );
    assert.isTrue(res.ok);
    assert.equals(
      Buffer.from(f.calls[0].init.body as Uint8Array).toString(),
      '{"name":"Rex"}',
    );
  });

  it("should refuse and audit a request body over the size limit without calling the API", async function () {
    const f = fakeFetch(() => new Response("{}"));
    const { b, logs, records } = broker(f);
    const res = await b.handle(
      {
        ...req("PetsApi.createPet", `${BASE}/pets`, "POST"),
        body: "x".repeat(2048),
      },
      ctx(logs),
      signal(),
    );
    assert.isFalse(res.ok);
    if (!res.ok) assert.equals(res.error.reason, "request_too_large");
    assert.equals(f.calls.length, 0);
    const limit = records().find(
      (r) => r.event === "execution.resource_limit",
    )!;
    assert.equals(limit.get("limit"), "maxRequestBytes");
  });

  it("should report an API that cannot be reached", async function () {
    const f = fakeFetch(() => {
      throw new TypeError("fetch failed");
    });
    const { b, logs, records } = broker(f);
    const res = await b.handle(
      req("PetsApi.getPetById", `${BASE}/pets/1`),
      ctx(logs),
      signal(),
    );
    assert.isFalse(res.ok);
    if (!res.ok) {
      assert.equals(res.error.type, "upstream_unreachable");
      assert.equals(res.error.reason, "network_error");
    }
    const failed = records().find((r) => r.event === "upstream.call.failed")!;
    assert.equals(failed.get("reason"), "network_error");
    assert.equals(failed.get("error"), "TypeError");
  });

  it("should time out an API that does not respond, and tell it apart from the execution ending", async function () {
    // Like fetch, reject once the signal aborts (or at once if it has).
    const hang = fakeFetch(
      (_url, init) =>
        new Promise((_resolve, reject) => {
          const signal = init.signal!;
          if (signal.aborted) {
            reject(signal.reason);
          }
          signal.addEventListener("abort", () => reject(signal.reason));
        }),
    );
    const slow = broker(hang, { timeoutMs: 50 });
    const timedOut = await slow.b.handle(
      req("PetsApi.getPetById", `${BASE}/pets/1`),
      ctx(slow.logs),
      signal(),
    );
    assert.isFalse(timedOut.ok);
    if (!timedOut.ok) assert.equals(timedOut.error.reason, "upstream_timeout");

    const ended = broker(hang);
    const execution = new AbortController();
    const pending = ended.b.handle(
      req("PetsApi.getPetById", `${BASE}/pets/1`),
      ctx(ended.logs),
      execution.signal,
    );
    execution.abort();
    const res = await pending;
    assert.isFalse(res.ok);
    if (!res.ok) assert.equals(res.error.reason, "network_error");
    const failed = ended
      .records()
      .find((r) => r.event === "upstream.call.failed")!;
    assert.equals(failed.get("reason"), "execution_ended");
  });

  it("should refuse redirects when following them is disabled, or after too many", async function () {
    const loop = () =>
      fakeFetch(
        () =>
          new Response(null, {
            status: 302,
            headers: { location: "/v1/pets/2" },
          }),
      );
    const reason = async (b: ReturnType<typeof broker>) => {
      await b.b.handle(
        req("PetsApi.getPetById", `${BASE}/pets/1`),
        ctx(b.logs),
        signal(),
      );
      return b
        .records()
        .find((r) => r.event === "network.redirect_denied")
        ?.get("reason");
    };
    const disabled = loop();
    assert.equals(
      await reason(broker(disabled, { followRedirects: false })),
      "redirects_disabled",
    );
    assert.equals(disabled.calls.length, 1);
    const endless = loop();
    assert.equals(await reason(broker(endless)), "too_many_redirects");
    assert.equals(endless.calls.length, 4, "the first request and 3 redirects");
  });

  it("should not forward credentials when a permitted redirect goes to another origin", async function () {
    const f = fakeFetch((url) =>
      url.hostname === "api.example.test"
        ? new Response(null, {
            status: 302,
            headers: {
              location: "https://cdn.example.test/owners?api_key=echoed&city=x",
            },
          })
        : new Response("[]"),
    );
    const { b, logs } = broker(f, {
      allowedOrigins: ["https://cdn.example.test"],
    });
    const res = await b.handle(
      req("OwnersApi.listOwners", `${BASE}/owners`),
      ctx(logs),
      signal(),
    );
    assert.isTrue(res.ok);
    assert.equals(
      f.calls[0].url.searchParams.get("api_key"),
      "broker-key-123456",
    );
    assert.isNull(f.calls[1].url.searchParams.get("api_key"));
    assert.equals(f.calls[1].url.searchParams.get("city"), "x");

    const h = fakeFetch((url) =>
      url.hostname === "api.example.test"
        ? new Response(null, {
            status: 307,
            headers: { location: "https://cdn.example.test/pets" },
          })
        : new Response("[]"),
    );
    const other = broker(h, { allowedOrigins: ["https://cdn.example.test"] });
    await other.b.handle(
      req("PetsApi.listPets", `${BASE}/pets`),
      ctx(other.logs),
      signal(),
    );
    const sent = (i: number) =>
      h.calls[i].init.headers as Record<string, string>;
    assert.equals(sent(0)["X-Api-Key"], "broker-key-123456");
    assert.isUndefined(sent(1)["X-Api-Key"]);
  });

  it("should turn a POST into a GET without a body after a 303 redirect, but keep it after a 307", async function () {
    const redirecting = (status: number) =>
      fakeFetch((url) =>
        url.pathname === "/v1/pets"
          ? new Response(null, {
              status,
              headers: { location: "/v1/pets/1" },
            })
          : new Response("{}"),
      );
    const send = async (f: ReturnType<typeof fakeFetch>) => {
      const { b, logs } = broker(f);
      await b.handle(
        { ...req("PetsApi.createPet", `${BASE}/pets`, "POST"), body: "{}" },
        ctx(logs),
        signal(),
      );
      return f.calls[1].init;
    };
    const seeOther = await send(redirecting(303));
    assert.equals(seeOther.method, "GET");
    assert.isUndefined(seeOther.body);
    const temporary = await send(redirecting(307));
    assert.equals(temporary.method, "POST");
    assert.equals(temporary.body, "{}");
  });

  it("should discard a cached OAuth token that the API rejects", async function () {
    const provider: CredentialProvider = {
      id: "fake",
      has: () => true,
      apply: async () => ({
        headers: { Authorization: "Bearer t" },
        query: {},
      }),
      invalidate: sinon.spy(),
    };
    const operations: OperationBinding[] = [
      { ...OPS[0], security: [{ clinicOAuth: [] }] },
    ];
    const f = fakeFetch(() => new Response("{}", { status: 401 }));
    const { b, logs } = broker(f, { provider, operations });
    const res = await b.handle(
      req("PetsApi.listPets", `${BASE}/pets`),
      ctx(logs),
      signal(),
    );
    assert.isTrue(res.ok);
    if (res.ok) assert.equals(res.status, 401);
    const invalidate = provider.invalidate as sinon.SinonSpy;
    assert.equals(invalidate.callCount, 1);
    assert.equals(invalidate.firstCall.args[0], "clinicOAuth");
  });
});

"use strict";
import referee from "@sinonjs/referee";
import sinon from "sinon";

import type { Principal } from "../../lib/types.js";
import { SecretResolver } from "../../lib/util/secrets.js";
import { OagMcpError } from "../../lib/errors.js";
import { SecretRegistry } from "../../lib/util/redact.js";
import {
  ServiceIdentityCredentialProvider,
  UpstreamAuthError,
} from "../../lib/upstream/credentials.js";
import { resolveSecurity } from "../../lib/upstream/security.js";
import { SCHEMES, fakeFetch, quietLogs } from "../helpers/fakes.js";

const { assert, match } = referee;

const principal: Principal = { id: "local:test", kind: "local", scopes: [] };
const env = {
  KEY: "key-value-123456",
  TOKEN: "bearer-value-123456",
  USER: "admin",
  PASS: "pass-value-123456",
  CID: "client-id-1",
  CSEC: "client-secret-123456",
};

function provider(
  schemes: Record<string, unknown>,
  fetchImpl?: typeof fetch,
  opts: { allowInsecureTokenUrl?: boolean } = {},
) {
  const { logs, records } = quietLogs();
  const registry = new SecretRegistry();
  const p = new ServiceIdentityCredentialProvider({
    schemes: schemes as never,
    schemeInfo: SCHEMES,
    resolver: new SecretResolver({ baseDir: process.cwd(), env }),
    registry,
    logs,
    allowInsecureTokenUrl: opts.allowInsecureTokenUrl ?? true,
    baseUrl: "http://127.0.0.1:4010/v1",
    fetchImpl,
  });
  return { p, logs, records, registry };
}

function oauthProvider(
  config: Record<string, unknown>,
  fetchImpl: typeof fetch,
) {
  return provider(
    {
      clinicOAuth: {
        clientId: { env: "CID" },
        clientSecret: { env: "CSEC" },
        ...config,
      },
    },
    fetchImpl,
  );
}

function tokenFetch(json: Record<string, unknown>) {
  return fakeFetch(() => new Response(JSON.stringify(json), { status: 200 }));
}

const ctx = (logs: ReturnType<typeof quietLogs>["logs"]) => ({
  principal,
  operation: {
    id: "PetsApi.createPet",
    className: "PetsApi",
    methodName: "createPet",
    httpMethod: "POST",
    path: "/pets",
    tags: [],
    security: [],
  },
  logs,
});

describe("credentials - ServiceIdentityCredentialProvider", function () {
  it("should apply apiKey header/query, basic and bearer credentials", async function () {
    const { p, logs, registry } = provider({
      apiKeyHeader: { apiKey: { env: "KEY" } },
      apiKeyQuery: { apiKey: { env: "KEY" } },
      adminBasic: { username: { env: "USER" }, password: { env: "PASS" } },
      bearerAuth: { token: { env: "TOKEN" } },
    });
    assert.equals(
      (await p.apply(SCHEMES.apiKeyHeader, [], ctx(logs))).headers,
      { "X-Api-Key": env.KEY },
    );
    assert.equals((await p.apply(SCHEMES.apiKeyQuery, [], ctx(logs))).query, {
      api_key: env.KEY,
    });
    assert.equals(
      (await p.apply(SCHEMES.adminBasic, [], ctx(logs))).headers.Authorization,
      `Basic ${Buffer.from("admin:pass-value-123456").toString("base64")}`,
    );
    assert.equals(
      (await p.apply(SCHEMES.bearerAuth, [], ctx(logs))).headers.Authorization,
      `Bearer ${env.TOKEN}`,
    );
    assert.equals(
      registry.scrubKnown(`x ${env.PASS} ${env.TOKEN}`),
      "x [REDACTED] [REDACTED]",
    );
  });

  it("should reject configuration for unknown, unsupported or incomplete schemes at startup", function () {
    for (const cfg of [
      { nope: { apiKey: { env: "KEY" } } },
      { oidc: { token: { env: "TOKEN" } } },
      { adminBasic: { username: { env: "USER" } } },
      { bearerAuth: { token: { env: "MISSING_ENV" } } },
      { apiKeyHeader: { apiKey: "plain-text-key" } },
      { apiKeyHeader: { apiKey: [{ env: "KEY" }] } },
    ]) {
      try {
        provider(cfg);
        assert(false, JSON.stringify(cfg));
      } catch (e) {
        assert.equals((e as OagMcpError).code, "UPSTREAM_AUTH_CONFIG_INVALID");
      }
    }
  });

  it("should reject a non-HTTPS token URL unless explicitly allowed", function () {
    const schemeInfo = { ...SCHEMES };
    try {
      const { logs } = quietLogs();
      new ServiceIdentityCredentialProvider({
        schemes: {
          clinicOAuth: {
            clientId: { env: "CID" },
            clientSecret: { env: "CSEC" },
            tokenUrl: "http://auth.example.test/token",
          },
        },
        schemeInfo,
        resolver: new SecretResolver({ baseDir: process.cwd(), env }),
        registry: new SecretRegistry(),
        logs,
        allowInsecureTokenUrl: false,
        baseUrl: "https://api.example.test",
      });
      assert(false, "expected failure");
    } catch (e) {
      assert.match((e as Error).message, /not HTTPS/);
    }
  });

  it("should cache client credentials tokens, renew after expiry and de-duplicate refreshes", async function () {
    let issued = 0;
    const fetchImpl = fakeFetch(async (_url, init) => {
      issued++;
      const body = new URLSearchParams(String(init.body));
      assert.equals(body.get("grant_type"), "client_credentials");
      assert.equals(body.get("scope"), "pets:write");
      assert.equals(
        (init.headers as Record<string, string>).authorization,
        `Basic ${Buffer.from("client-id-1:client-secret-123456").toString("base64")}`,
      );
      return new Response(
        JSON.stringify({
          access_token: `tok-${issued}-abcdef`,
          token_type: "Bearer",
          expires_in: 31,
        }),
        { status: 200 },
      );
    });
    const { p, logs, records } = provider(
      {
        clinicOAuth: {
          clientId: { env: "CID" },
          clientSecret: { env: "CSEC" },
        },
      },
      fetchImpl,
    );
    const [a, b] = await Promise.all([
      p.apply(SCHEMES.clinicOAuth, ["pets:write"], ctx(logs)),
      p.apply(SCHEMES.clinicOAuth, ["pets:write"], ctx(logs)),
    ]);
    assert.equals(issued, 1);
    assert.equals(a.headers.Authorization, "Bearer tok-1-abcdef");
    assert.equals(b.headers.Authorization, "Bearer tok-1-abcdef");
    // expires_in 31 with a 30s skew: the next call refreshes after one second.
    await new Promise((r) => setTimeout(r, 1100));
    const c = await p.apply(SCHEMES.clinicOAuth, ["pets:write"], ctx(logs));
    assert.equals(c.headers.Authorization, "Bearer tok-2-abcdef");
    assert.equals(issued, 2);
    p.invalidate("clinicOAuth", ctx(logs));
    await p.apply(SCHEMES.clinicOAuth, ["pets:write"], ctx(logs));
    assert.equals(issued, 3);
    const events = records().map((r) => r.event);
    assert.contains(events, "upstream.token.issue");
    assert.contains(events, "upstream.token.refresh");
    assert.contains(events, "upstream.token.invalidated");
    // Token values never reach the logs.
    assert.equals(JSON.stringify(records()).includes("tok-1-abcdef"), false);
  });

  it("should raise a clear error when the token endpoint rejects the client", async function () {
    const fetchImpl = fakeFetch(
      () =>
        new Response(JSON.stringify({ error: "invalid_client" }), {
          status: 401,
        }),
    );
    const { p, logs, records } = provider(
      {
        clinicOAuth: {
          clientId: { env: "CID" },
          clientSecret: { env: "CSEC" },
        },
      },
      fetchImpl,
    );
    try {
      await p.apply(SCHEMES.clinicOAuth, ["pets:write"], ctx(logs));
      assert(false, "expected failure");
    } catch (e) {
      assert(e instanceof UpstreamAuthError);
      assert.equals((e as UpstreamAuthError).reason, "token_request_failed");
    }
    assert.contains(
      records().map((r) => r.event),
      "upstream.token.issue_failed",
    );
  });

  it("should refuse a scheme it has no credentials for", async function () {
    const { p, logs } = provider({ bearerAuth: { token: { env: "TOKEN" } } });
    assert.isFalse(p.has("apiKeyHeader"));
    await assert.rejects(
      p.apply(SCHEMES.apiKeyHeader, [], ctx(logs)),
      match({ reason: "credential_not_configured" }),
    );
  });

  it("should reuse a cached token until shortly before it expires", async function () {
    const fetchImpl = tokenFetch({
      access_token: "tok-long",
      expires_in: 3600,
    });
    const { p, logs, records } = oauthProvider({}, fetchImpl);
    await p.apply(SCHEMES.clinicOAuth, ["pets:write"], ctx(logs));
    const again = await p.apply(SCHEMES.clinicOAuth, ["pets:write"], ctx(logs));
    assert.equals(again.headers.Authorization, "Bearer tok-long");
    assert.equals(fetchImpl.calls.length, 1);
    assert.contains(
      records().map((r) => r.event),
      "upstream.token.cache_hit",
    );
  });

  it("should post client credentials, configured scopes and the audience in the form", async function () {
    const fetchImpl = tokenFetch({ access_token: "tok-post" });
    const { p, logs, records } = oauthProvider(
      {
        clientAuthMethod: "client_secret_post",
        audience: "https://api.example.test",
        scopes: ["b", "a"],
      },
      fetchImpl,
    );
    await p.apply(SCHEMES.clinicOAuth, ["pets:write"], ctx(logs));
    const { url, init } = fetchImpl.calls[0];
    assert.equals(url.toString(), "http://127.0.0.1:4011/token");
    assert.equals(init.redirect, "error");
    assert.isUndefined((init.headers as Record<string, string>).authorization);
    assert.equals(Object.fromEntries(new URLSearchParams(String(init.body))), {
      grant_type: "client_credentials",
      scope: "b a",
      audience: "https://api.example.test",
      client_id: env.CID,
      client_secret: env.CSEC,
    });
    const issued = records().find((r) => r.event === "upstream.token.issue")!;
    assert.equals(issued.get("expiresInSec"), 300);
    assert.equals(issued.get("scopeCount"), 2);
  });

  it("should leave out the scope when no scopes are needed", async function () {
    const fetchImpl = tokenFetch({ access_token: "tok-x", expires_in: -5 });
    const { p, logs, records } = oauthProvider({ scopes: [] }, fetchImpl);
    await p.apply(SCHEMES.clinicOAuth, ["pets:write"], ctx(logs));
    const body = new URLSearchParams(String(fetchImpl.calls[0].init.body));
    assert.isFalse(body.has("scope"));
    assert.equals(
      records()
        .find((r) => r.event === "upstream.token.issue")!
        .get("expiresInSec"),
      300,
    );
  });

  it("should fail clearly when the token endpoint is unreachable", async function () {
    const fetchImpl = fakeFetch(() => {
      throw new TypeError("fetch failed");
    });
    const { p, logs, records } = oauthProvider({}, fetchImpl);
    await assert.rejects(
      p.apply(SCHEMES.clinicOAuth, ["pets:write"], ctx(logs)),
      match({ reason: "token_endpoint_unreachable" }),
    );
    const failed = records().find(
      (r) => r.event === "upstream.token.issue_failed",
    )!;
    assert.equals(failed.get("reason"), "token_endpoint_unreachable");
    assert.equals(failed.get("error"), "TypeError");
  });

  it("should name why a token response is unusable", async function () {
    const cases: Array<[number, string, string, string | null]> = [
      [200, "not json", "no_access_token", null],
      [200, "null", "no_access_token", null],
      [200, "[1]", "no_access_token", null],
      [200, '{"access_token":7}', "no_access_token", null],
      [
        200,
        '{"access_token":"t","token_type":"mac"}',
        "unsupported_token_type",
        null,
      ],
      [500, '{"error":42}', "token_endpoint_error", null],
      [
        400,
        JSON.stringify({ error: "x".repeat(100) }),
        "token_endpoint_error",
        "x".repeat(64),
      ],
    ];
    for (const [status, body, reason, oauthError] of cases) {
      const fetchImpl = fakeFetch(() => new Response(body, { status }));
      const { p, logs, records } = oauthProvider({}, fetchImpl);
      await assert.rejects(
        p.apply(SCHEMES.clinicOAuth, ["pets:write"], ctx(logs)),
        match({ reason: "token_request_failed" }),
      );
      const failed = records().find(
        (r) => r.event === "upstream.token.issue_failed",
      )!;
      assert.equals(failed.get("reason"), reason, body);
      // The token endpoint's HTTP status is the OCSF status_code.
      assert.equals(failed.raw.status_code, String(status), body);
      assert.equals(failed.get("oauthError") ?? null, oauthError, body);
    }
  });

  it("should keep scrubbing a replaced token for a minute", async function () {
    const clock = sinon.useFakeTimers({ toFake: ["setTimeout"] });
    try {
      let issued = 0;
      const fetchImpl = fakeFetch(
        () =>
          new Response(
            JSON.stringify({
              access_token: `tok-${++issued}-abcdef`,
              expires_in: 1,
            }),
          ),
      );
      const { p, logs, registry } = oauthProvider({}, fetchImpl);
      await p.apply(SCHEMES.clinicOAuth, ["pets:write"], ctx(logs));
      // expires_in 1 is inside the refresh skew, so the next call refreshes.
      await p.apply(SCHEMES.clinicOAuth, ["pets:write"], ctx(logs));
      assert.equals(issued, 2);
      assert.equals(registry.scrubKnown("tok-1-abcdef"), "[REDACTED]");
      clock.tick(60000);
      assert.equals(registry.scrubKnown("tok-1-abcdef"), "tok-1-abcdef");
      assert.equals(registry.scrubKnown("tok-2-abcdef"), "[REDACTED]");
    } finally {
      clock.restore();
    }
  });

  it("should not report an invalidation when nothing was cached", function () {
    const { p, logs, records } = oauthProvider({}, tokenFetch({}));
    p.invalidate("clinicOAuth", ctx(logs));
    assert.equals(
      records().filter((r) => r.event === "upstream.token.invalidated"),
      [],
    );
  });
});

describe("security - resolveSecurity", function () {
  it("should use the first configured alternative in document order", async function () {
    const { p, logs } = provider({ bearerAuth: { token: { env: "TOKEN" } } });
    const r = await resolveSecurity(
      [{ apiKeyHeader: [] }, { bearerAuth: [] }],
      SCHEMES,
      p,
      ctx(logs),
    );
    assert.equals(r.schemes, ["bearerAuth"]);
    assert.equals(r.alternative, 1);
  });

  it("should require all schemes of an AND alternative", async function () {
    const { p, logs } = provider({
      apiKeyHeader: { apiKey: { env: "KEY" } },
      bearerAuth: { token: { env: "TOKEN" } },
    });
    const r = await resolveSecurity(
      [{ apiKeyHeader: [], bearerAuth: [] }],
      SCHEMES,
      p,
      ctx(logs),
    );
    assert.equals(r.schemes, ["apiKeyHeader", "bearerAuth"]);
    assert.equals(r.headers["X-Api-Key"], env.KEY);
    assert.equals(r.headers.Authorization, `Bearer ${env.TOKEN}`);
  });

  it("should not downgrade to unauthenticated access when credentials are missing", async function () {
    const { p, logs } = provider({});
    try {
      await resolveSecurity(
        [{ apiKeyHeader: [] }, { bearerAuth: [] }],
        SCHEMES,
        p,
        ctx(logs),
      );
      assert(false, "expected failure");
    } catch (e) {
      assert.equals(
        (e as UpstreamAuthError).reason,
        "credential_not_configured",
      );
    }
  });

  it("should allow unauthenticated calls only when the spec allows them", async function () {
    const { p, logs } = provider({});
    assert.equals(
      (await resolveSecurity([], SCHEMES, p, ctx(logs))).schemes,
      [],
    );
    assert.equals(
      (await resolveSecurity([{ bearerAuth: [] }, {}], SCHEMES, p, ctx(logs)))
        .schemes,
      [],
    );
  });

  it("should prefer an authenticated alternative over an optional empty one", async function () {
    const { p, logs } = provider({ bearerAuth: { token: { env: "TOKEN" } } });
    const r = await resolveSecurity(
      [{}, { bearerAuth: [] }],
      SCHEMES,
      p,
      ctx(logs),
    );
    assert.equals(r.schemes, ["bearerAuth"]);
  });

  it("should report unsupported schemes distinctly", async function () {
    const { p, logs } = provider({});
    try {
      await resolveSecurity([{ oidc: [] }], SCHEMES, p, ctx(logs));
      assert(false, "expected failure");
    } catch (e) {
      assert.equals((e as UpstreamAuthError).reason, "unsupported_scheme");
    }
  });
});

"use strict";
import fs from "node:fs";
import path from "node:path";

import referee from "@sinonjs/referee";

import { listFiles, sha256Tree } from "../../lib/util/hash.js";
import { tmpDir } from "../helpers/paths.js";

const { assert, refute } = referee;

function tree(): string {
  const dir = tmpDir();
  fs.mkdirSync(path.join(dir, "src", "apis"), { recursive: true });
  fs.mkdirSync(path.join(dir, "node_modules", "x"), { recursive: true });
  fs.writeFileSync(path.join(dir, "b.txt"), "b");
  fs.writeFileSync(path.join(dir, "src", "apis", "A.ts"), "a");
  fs.writeFileSync(path.join(dir, "node_modules", "x", "i.js"), "i");
  fs.symlinkSync(path.join(dir, "b.txt"), path.join(dir, "link.txt"));
  return dir;
}

describe("hash - listFiles", function () {
  it("should list files as sorted POSIX paths, skipping links and filtered paths", function () {
    const dir = tree();
    assert.equals(listFiles(dir), [
      "b.txt",
      "node_modules/x/i.js",
      "src/apis/A.ts",
    ]);
    assert.equals(
      listFiles(dir, (rel) => !rel.startsWith("node_modules")),
      ["b.txt", "src/apis/A.ts"],
    );
  });
});

describe("hash - sha256Tree", function () {
  it("should change when any file's content changes", function () {
    const dir = tree();
    const before = sha256Tree(dir);
    assert.equals(sha256Tree(dir), before);
    fs.writeFileSync(path.join(dir, "src", "apis", "A.ts"), "changed");
    refute.equals(sha256Tree(dir), before);
  });
});

"use strict";
import referee from "@sinonjs/referee";

import {
  REDACTED,
  SecretRegistry,
  boundValue,
  isSensitiveKey,
  sanitizeError,
} from "../../lib/util/redact.js";

const { assert, refute } = referee;

describe("redact - SecretRegistry.scrub", function () {
  it("should replace registered secrets and their base64 form when present in text", function () {
    const reg = new SecretRegistry();
    reg.add("super-secret-value");
    const b64 = Buffer.from("super-secret-value").toString("base64");
    const out = reg.scrub(`a super-secret-value b ${b64}`);
    refute.contains(out, "super-secret-value");
    refute.contains(out, b64);
    assert.contains(out, REDACTED);
  });

  it("should ignore very short values when registering", function () {
    const reg = new SecretRegistry();
    reg.add("abc");
    assert.equals(reg.size, 0);
    assert.equals(reg.scrub("abc"), "abc");
  });

  it("should scrub bearer tokens, JWTs and credential query parameters when not registered", function () {
    const reg = new SecretRegistry();
    const text =
      "Authorization: Bearer abcdef123456 jwt eyJhbGciOiJIUzI1NiJ9.eyJzdWIiOiIxIn0.sig and https://api.test/x?api_key=k1234&ok=1";
    const out = reg.scrub(text);
    refute.contains(out, "abcdef123456");
    refute.contains(out, "eyJzdWIiOiIxIn0");
    refute.contains(out, "k1234");
    assert.contains(out, "ok=1");
  });

  it("should only replace registered values when using scrubKnown", function () {
    const reg = new SecretRegistry();
    reg.add("token-1234567");
    assert.equals(
      reg.scrubKnown("Bearer xyz token-1234567"),
      `Bearer xyz ${REDACTED}`,
    );
  });

  it("should stop scrubbing a value after it is removed", function () {
    const reg = new SecretRegistry();
    reg.add("rotating-token-1");
    reg.remove("rotating-token-1");
    assert.equals(reg.scrubKnown("rotating-token-1"), "rotating-token-1");
  });
});

describe("redact - boundValue", function () {
  it("should censor sensitive keys at any depth", function () {
    const out = boundValue({
      a: { Authorization: "Bearer x", nested: { client_secret: "y", ok: 1 } },
    }) as Record<string, Record<string, Record<string, unknown>>>;
    assert.equals(out.a.Authorization, REDACTED);
    assert.equals(out.a.nested.client_secret, REDACTED);
    assert.equals(out.a.nested.ok, 1);
  });

  it("should truncate long strings and cap arrays and depth", function () {
    const out = boundValue(
      {
        s: "x".repeat(1000),
        arr: Array.from({ length: 60 }, (_, i) => i),
        deep: { a: { b: { c: { d: 1 } } } },
      },
      { maxString: 10, maxArray: 5, maxDepth: 3 },
    ) as { s: string; arr: unknown[]; deep: { a: { b: unknown } } };
    assert.match(out.s, /^x{10}…\[truncated 990\]$/);
    assert.equals(out.arr.length, 6);
    assert.equals(out.deep.a.b, "[max-depth]");
  });

  it("should mark circular references", function () {
    const a: Record<string, unknown> = { name: "a" };
    a.self = a;
    const out = boundValue(a) as Record<string, unknown>;
    assert.equals(out.self, "[circular]");
  });
});

describe("redact - isSensitiveKey", function () {
  it("should recognise credential key names case-insensitively", function () {
    for (const k of [
      "authorization",
      "Cookie",
      "password",
      "apiKey",
      "x-api-key",
      "client_secret",
      "refresh_token",
    ]) {
      assert.isTrue(isSensitiveKey(k), k);
    }
    refute(isSensitiveKey("operation"));
  });
});

describe("redact - sanitizeError", function () {
  it("should keep name and code but scrub the message", function () {
    const reg = new SecretRegistry();
    reg.add("leaky-secret-99");
    const err = Object.assign(new Error("failed with leaky-secret-99"), {
      code: "E_X",
    });
    const out = sanitizeError(err, reg);
    assert.equals(out.name, "Error");
    assert.equals(out.code, "E_X");
    refute.contains(out.message, "leaky-secret-99");
  });
});

describe("redact - boundValue value kinds", function () {
  it("should keep null, undefined, numbers and booleans, and stringify bigints", function () {
    assert.equals(
      boundValue({ a: null, b: undefined, c: 1.5, d: false, e: 12n }),
      { a: null, b: undefined, c: 1.5, d: false, e: "12" },
    );
    assert.isNull(boundValue(null));
  });

  it("should name functions and symbols instead of copying them", function () {
    assert.equals(boundValue({ f: () => 1, s: Symbol("x") }), {
      f: "[function]",
      s: "[symbol]",
    });
  });

  it("should sanitise errors and write dates as ISO 8601", function () {
    const reg = new SecretRegistry();
    reg.add("error-secret-value");
    const out = boundValue(
      {
        err: new TypeError("failed with error-secret-value"),
        at: new Date(Date.UTC(2026, 0, 31, 12)),
      },
      { registry: reg },
    ) as { err: { name: string; message: string }; at: string };
    assert.equals(out.err.name, "TypeError");
    refute.contains(out.err.message, "error-secret-value");
    assert.equals(out.at, "2026-01-31T12:00:00.000Z");
  });

  it("should keep only the first keys of a large object", function () {
    const big = Object.fromEntries(
      Array.from({ length: 5 }, (_, i) => [`k${i}`, i]),
    );
    assert.equals(boundValue(big, { maxKeys: 3 }), {
      k0: 0,
      k1: 1,
      k2: 2,
      "…": "[more keys truncated]",
    });
  });
});

"use strict";
import fs from "node:fs";
import path from "node:path";

import referee from "@sinonjs/referee";

import { OagMcpError } from "../../lib/errors.js";
import { SecretResolver } from "../../lib/util/secrets.js";
import { tmpDir } from "../helpers/paths.js";

const { assert } = referee;

describe("secrets - SecretResolver", function () {
  it("should resolve environment references without exposing values in errors", function () {
    const r = new SecretResolver({
      baseDir: process.cwd(),
      env: { A: "value-a" },
    });
    assert.equals(r.resolve({ env: "A" }, "x"), "value-a");
    try {
      r.resolve({ env: "B" }, "label");
      assert(false);
    } catch (e) {
      assert.equals((e as OagMcpError).code, "SECRET_NOT_FOUND");
    }
  });

  it("should read a protected secrets file and refuse a world-readable one", function () {
    if (process.platform === "win32") this.skip();
    const dir = tmpDir();
    const file = path.join(dir, "secrets.yaml");
    fs.writeFileSync(file, "admin_password: from-file-123\n", { mode: 0o600 });
    assert.equals(
      new SecretResolver({ secretsFile: "secrets.yaml", baseDir: dir }).resolve(
        { secret: "admin_password" },
        "x",
      ),
      "from-file-123",
    );
    fs.chmodSync(file, 0o644);
    try {
      new SecretResolver({ secretsFile: "secrets.yaml", baseDir: dir }).resolve(
        { secret: "admin_password" },
        "x",
      );
      assert(false);
    } catch (e) {
      assert.equals((e as OagMcpError).code, "SECRETS_FILE_PERMISSIONS");
    }
  });
});

describe("secrets - SecretResolver secrets file", function () {
  const write = (body: string) => {
    const dir = tmpDir();
    fs.writeFileSync(path.join(dir, "secrets.yaml"), body, { mode: 0o600 });
    return new SecretResolver({ secretsFile: "secrets.yaml", baseDir: dir });
  };
  const code = (fn: () => unknown) => {
    try {
      fn();
    } catch (e) {
      return (e as OagMcpError).code;
    }
    return undefined;
  };

  it("should read the file once and keep using its values", function () {
    const dir = tmpDir();
    const file = path.join(dir, "secrets.yaml");
    fs.writeFileSync(file, "a: one\nb: two\n", { mode: 0o600 });
    const r = new SecretResolver({ secretsFile: file, baseDir: "/elsewhere" });
    assert.equals(r.resolve({ secret: "a" }, "x"), "one");
    fs.rmSync(file);
    assert.equals(r.resolve({ secret: "b" }, "x"), "two");
  });

  it("should require a configured secrets file for secret references", function () {
    const r = new SecretResolver({ baseDir: process.cwd() });
    assert.equals(
      code(() => r.resolve({ secret: "a" }, "x")),
      "SECRETS_FILE_MISSING",
    );
  });

  it("should report a secrets file that cannot be read", function () {
    const r = new SecretResolver({
      secretsFile: "missing.yaml",
      baseDir: tmpDir(),
    });
    assert.equals(
      code(() => r.resolve({ secret: "a" }, "x")),
      "SECRETS_FILE_MISSING",
    );
  });

  it("should require a mapping of keys to string values", function () {
    assert.equals(
      code(() => write("- a\n- b\n").resolve({ secret: "a" }, "x")),
      "SECRETS_FILE_INVALID",
    );
    assert.equals(
      code(() => write("42\n").resolve({ secret: "a" }, "x")),
      "SECRETS_FILE_INVALID",
    );
    const r = write("number: 42\nempty: ''\nok: yes-string\n");
    assert.equals(r.resolve({ secret: "ok" }, "x"), "yes-string");
    assert.equals(
      code(() => r.resolve({ secret: "number" }, "x")),
      "SECRET_NOT_FOUND",
    );
    assert.equals(
      code(() => r.resolve({ secret: "empty" }, "x")),
      "SECRET_NOT_FOUND",
    );
    assert.equals(
      code(() => r.resolve({ secret: "absent" }, "x")),
      "SECRET_NOT_FOUND",
    );
    assert.equals(
      code(() => write("").resolve({ secret: "a" }, "x")),
      "SECRET_NOT_FOUND",
      "an empty file has no secrets",
    );
  });
});

"use strict";
import referee from "@sinonjs/referee";

import { Semaphore } from "../../lib/util/semaphore.js";

const { assert } = referee;

/** Let pending promise continuations run. */
const settle = () => new Promise<void>((resolve) => setImmediate(resolve));

describe("semaphore - acquire", function () {
  it("should bound concurrency and queue length", async function () {
    const s = new Semaphore(1, 1);
    const r1 = await s.acquire();
    const pending = s.acquire();
    assert.isUndefined(await s.acquire());
    r1!();
    const r2 = await pending;
    assert.isFunction(r2);
    r2!();
  });

  it("should hand a released slot to the next waiter so a new caller cannot take it too", async function () {
    const s = new Semaphore(1, 1);
    const r1 = await s.acquire();
    const queued = s.acquire();
    // Release, then a new caller arrives before the woken waiter resumes.
    r1!();
    let lateGotSlot = false;
    const late = s.acquire().then((r) => {
      lateGotSlot = true;
      return r;
    });
    const r2 = await queued;
    await settle();
    assert.isFunction(r2);
    assert.isFalse(lateGotSlot, "new caller must wait behind the woken waiter");
    assert.equals(s.inUse, 1);
    r2!();
    const r3 = await late;
    assert.isFunction(r3);
    assert.equals(s.inUse, 1);
    r3!();
    assert.equals(s.inUse, 0);
  });

  it("should never exceed the limit under bursts of acquire and release", async function () {
    const max = 3;
    const s = new Semaphore(max, 100);
    let holders = 0;
    let peak = 0;
    const work = async () => {
      const release = await s.acquire();
      assert.isFunction(release);
      holders++;
      peak = Math.max(peak, holders, s.inUse);
      await settle();
      holders--;
      release!();
    };
    await Promise.all(Array.from({ length: 50 }, work));
    assert.equals(peak, max);
    assert.equals(s.inUse, 0);
  });

  it("should ignore a second call to the same release function", async function () {
    const s = new Semaphore(1, 0);
    const r1 = await s.acquire();
    r1!();
    r1!();
    assert.equals(s.inUse, 0);
    const r2 = await s.acquire();
    assert.isFunction(r2);
    assert.isUndefined(await s.acquire());
  });
});

"use strict";
import fs from "node:fs";
import path from "node:path";

import referee from "@sinonjs/referee";
import semver from "semver";

import {
  DENO_VERSION_RANGE,
  SUPPORTED_OAG_VERSIONS,
  authorName,
  dependencyVersion,
  oagMcpName,
  oagMcpVersion,
  packageRoot,
} from "../../lib/util/version.js";
import { ROOT } from "../helpers/paths.js";

const { assert } = referee;

const pkg = JSON.parse(
  fs.readFileSync(path.join(ROOT, "package.json"), "utf8"),
);

describe("version - oagMcpName", function () {
  it("should return the package name from package.json", function () {
    assert.equals(oagMcpName(), pkg.name);
  });
});

describe("version - oagMcpVersion", function () {
  it("should return the package version from package.json", function () {
    assert.equals(oagMcpVersion(), pkg.version);
  });
});

describe("version - packageRoot", function () {
  it("should locate the repository root from the util module", function () {
    assert.equals(packageRoot(), ROOT);
  });
});

describe("version - dependencyVersion", function () {
  it("should report installed versions and unknown for missing packages", function () {
    assert.equals(dependencyVersion("semver"), pkg.dependencies.semver);
    assert.equals(dependencyVersion("oag-mcp-no-such-package"), "unknown");
  });
});

describe("version - DENO_VERSION_RANGE", function () {
  it("should accept Deno 2.x from 2.5.0 and reject older, 3.x and pre-releases", function () {
    for (const ok of ["2.5.0", "2.9.6", "2.99.0"]) {
      assert.isTrue(semver.satisfies(ok, DENO_VERSION_RANGE), ok);
    }
    for (const bad of ["2.4.9", "3.0.0", "1.46.3", "2.9.6-rc.1"]) {
      assert.isFalse(semver.satisfies(bad, DENO_VERSION_RANGE), bad);
    }
    assert.isTrue(
      semver.satisfies(dependencyVersion("deno"), DENO_VERSION_RANGE),
      "the bundled deno dependency must be in range",
    );
  });
});

describe("version - SUPPORTED_OAG_VERSIONS", function () {
  it("should list exact, valid versions", function () {
    assert.equals(SUPPORTED_OAG_VERSIONS.length > 0, true);
    for (const v of SUPPORTED_OAG_VERSIONS) {
      assert.equals(semver.valid(v), v);
    }
  });
});

describe("version - authorName", function () {
  it("should read npm's person string or object form", function () {
    assert.equals(
      authorName("Cliffano <c@example.test> (https://x.test)"),
      "Cliffano",
    );
    assert.equals(authorName("Solo"), "Solo");
    assert.equals(authorName({ name: "Obj", email: "o@example.test" }), "Obj");
    assert.isUndefined(authorName(undefined));
    assert.isUndefined(authorName({ email: "o@example.test" }));
    assert.isUndefined(authorName(" <c@example.test>"));
  });
});
